                                    trang_thai, xet_at)
select ma, mon, khoi, chu_de, thu_tu, loai, ten, ten_khac, noi_dung, cong_thuc, y, bang, bien, vd, nham, lq, hinh, nguon, 'da_duyet', now()
from jsonb_populate_recordset(null::public.sotay_cong_thuc, $j$[{"ma":"l6-khoa-hoc-tu-nhien","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":1,"loai":"kn","ten":"Khoa học tự nhiên","ten_khac":["khoa hoc tu nhien","khtn","khoa hoc","linh vuc khtn","vat ly hoa hoc sinh hoc","natural science"],"noi_dung":"Ngành khoa học nghiên cứu các sự vật, hiện tượng, quy luật tự nhiên và ảnh hưởng của chúng đến con người, môi trường.","cong_thuc":null,"y":["Các lĩnh vực chính: <b>Vật lí</b>, <b>Hóa học</b>, <b>Sinh học</b>, Khoa học Trái Đất, Thiên văn học.","Vai trò: mở rộng hiểu biết, ứng dụng vào công nghệ, sản xuất, chăm sóc sức khỏe, bảo vệ môi trường.","Cách tìm hiểu: quan sát, đặt câu hỏi, làm thí nghiệm, đo đạc, rút ra kết luận."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l6-an-toan-phong-thuc-hanh","l6-don-vi-do","l6-kinh-lup"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-an-toan-phong-thuc-hanh","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":2,"loai":"ud","ten":"An toàn phòng thực hành","ten_khac":["an toan phong thuc hanh","quy tac an toan","noi quy phong thi nghiem","phong thi nghiem","an toan thi nghiem"],"noi_dung":"Những quy định cần tuân theo khi làm thí nghiệm để tránh tai nạn cho người và hư hỏng dụng cụ.","cong_thuc":null,"y":["Chỉ vào phòng và làm thí nghiệm khi có <b>giáo viên hướng dẫn</b>.","Mặc đồ bảo hộ, đeo kính, găng tay khi cần; không ăn uống, đùa nghịch trong phòng.","Đọc kĩ <b>kí hiệu cảnh báo</b> trên dụng cụ, hóa chất; không tự ý nếm, ngửi hóa chất.","Gặp sự cố (vỡ dụng cụ, đổ hóa chất, cháy) phải báo ngay cho giáo viên.","Xong buổi: thu gom chất thải đúng nơi quy định, rửa tay sạch."],"bang":null,"bien":null,"vd":{"de":"Trong phòng thực hành, một bạn định nếm thử một dung dịch không rõ nhãn để đoán xem đó là chất gì. Việc làm này có an toàn không?","buoc":["Hóa chất không rõ nhãn có thể độc hoặc ăn mòn.","Quy tắc an toàn cấm nếm, ngửi trực tiếp hóa chất khi chưa được hướng dẫn."],"kq":"Không an toàn; cần hỏi giáo viên và làm theo đúng hướng dẫn."},"nham":["Tưởng chất không mùi, không màu là an toàn nên cầm tay hoặc nếm thử."],"lq":["l6-ki-hieu-canh-bao","l6-khoa-hoc-tu-nhien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-ki-hieu-canh-bao","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":3,"loai":"ud","ten":"Kí hiệu cảnh báo","ten_khac":["ki hieu canh bao","bien bao","bien canh bao","bien cam","ky hieu nguy hiem","chat doc","de chay"],"noi_dung":"Các biển, hình vẽ in trên dụng cụ, hóa chất hoặc trong phòng thực hành để báo nguy hiểm, điều cấm hoặc chỉ dẫn.","cong_thuc":null,"y":["Hình dạng và màu sắc giúp nhận ra nhanh loại biển báo.","Một số kí hiệu thường gặp: chất độc, chất ăn mòn, chất dễ cháy, điện cao thế, chất phóng xạ."],"bang":[["Loại kí hiệu","Hình dạng, màu (thường gặp)"],["Cảnh báo cấm","hình tròn, viền đỏ, nền trắng"],["Cảnh báo khu vực nguy hiểm","hình tam giác, viền đen hoặc đỏ, nền vàng"],["Cảnh báo nguy hiểm do hóa chất","nền cam hoặc hình thoi viền đỏ, có hình vẽ: đầu lâu (chất độc), ngọn lửa (dễ cháy), tay bị ăn mòn…"],["Chỉ dẫn thực hiện","hình chữ nhật, nền xanh hoặc đỏ"]],"bien":null,"vd":{"de":"Trên một lọ hóa chất có in hình đầu lâu xương chéo. Kí hiệu này cảnh báo điều gì?","buoc":["Hình đầu lâu xương chéo là kí hiệu cảnh báo chất độc.","Cần tránh tiếp xúc trực tiếp, đeo găng tay khi dùng."],"kq":"Chất độc hại; chỉ dùng khi có giáo viên hướng dẫn và trang bị bảo hộ."},"nham":null,"lq":["l6-an-toan-phong-thuc-hanh","l6-khoa-hoc-tu-nhien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-xu-li-su-co-thuc-hanh","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":4,"loai":"ud","ten":"Xử lí sự cố khi thực hành","ten_khac":["xu li su co","bong","do vo","hoa chat dinh vao da","so cuu phong thuc hanh"],"noi_dung":"Khi có sự cố trong phòng thực hành, cần bình tĩnh, báo ngay cho giáo viên và xử lí theo hướng dẫn.","cong_thuc":null,"y":["<b>Hóa chất dính vào da, mắt</b>: rửa ngay dưới vòi nước sạch nhiều lần, báo giáo viên.","<b>Bị bỏng nhiệt</b>: làm mát vết bỏng bằng nước sạch; không bôi kem đánh răng, nước mắm lên vết bỏng.","<b>Dụng cụ thủy tinh vỡ</b>: không nhặt bằng tay, báo giáo viên để thu dọn."],"bang":null,"bien":null,"vd":{"de":"Khi làm thí nghiệm, một bạn làm vỡ ống nghiệm thủy tinh xuống sàn. Bạn nên làm gì?","buoc":["Mảnh thủy tinh sắc có thể gây đứt tay.","Không tự nhặt bằng tay, báo ngay giáo viên để thu dọn đúng cách."],"kq":"Không nhặt bằng tay; báo giáo viên xử lí."},"nham":["Tự ý xử lí sự cố mà không báo giáo viên."],"lq":["l6-an-toan-phong-thuc-hanh","l6-ki-hieu-canh-bao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-kinh-lup","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":5,"loai":"tn","ten":"Kính lúp","ten_khac":["kinh lup","kinh phong to","kinh lup cam tay","magnifier","do phong dai","kinh lop"],"noi_dung":"Dụng cụ có tấm kính lồi (dày ở giữa, mỏng ở rìa), giúp quan sát rõ vật nhỏ bằng cách tạo ảnh phóng to.","cong_thuc":null,"y":["Cấu tạo: <b>tấm kính lồi</b> và khung, tay cầm.","Độ phóng đại thường từ khoảng <b>3 lần đến 20 lần</b>.","Cách dùng: cầm kính, để mặt kính gần vật, từ từ đưa kính ra xa đến khi nhìn rõ vật.","Bảo quản: lau bằng khăn mềm, tránh cọ xát làm xước mặt kính."],"bang":null,"bien":null,"vd":{"de":"Muốn quan sát rõ các đường vân trên một chiếc lá nhỏ, nên dùng kính lúp hay kính hiển vi?","buoc":["Kính lúp phù hợp quan sát vật nhỏ nhưng vẫn thấy được bằng mắt thường.","Kính hiển vi dùng cho vật cực nhỏ như tế bào, phóng to nhiều hơn hẳn."],"kq":"Dùng kính lúp là đủ để quan sát rõ vân lá."},"nham":null,"lq":["l6-kinh-hien-vi","l6-khoa-hoc-tu-nhien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-kinh-hien-vi","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":6,"loai":"tn","ten":"Kính hiển vi quang học","ten_khac":["kinh hien vi","kinh hien vi quang hoc","khv","microscope","thi kinh","vat kinh","oc to oc nho","ban kinh"],"noi_dung":"Dụng cụ quang học phóng to ảnh của vật rất nhỏ (tế bào, vi khuẩn…) từ khoảng 40 đến 3 000 lần.","cong_thuc":null,"y":["Dùng khi vật quá nhỏ, kính lúp không quan sát được.","Cách dùng: đặt tiêu bản lên bàn kính, chỉnh ánh sáng, vặn <b>ốc to</b> rồi <b>ốc nhỏ</b> đến khi thấy rõ.","Bắt đầu quan sát với vật kính có độ phóng đại nhỏ nhất.","Cầm kính bằng hai tay: một tay nắm thân kính, một tay đỡ chân đế."],"bang":[["Bộ phận","Chức năng"],["Thị kính","kính sát mắt khi quan sát"],["Vật kính","kính gần vật, có nhiều độ phóng đại"],["Bàn kính","đặt tiêu bản"],["Ốc to, ốc nhỏ","điều chỉnh để nhìn rõ vật"],["Đèn/gương","chiếu sáng vật"],["Thân kính, chân đế","giữ và đỡ kính"]],"bien":null,"vd":{"de":"Một bạn muốn quan sát hình dạng của tế bào biểu bì vảy hành. Dụng cụ quang học nào phù hợp?","buoc":["Tế bào có kích thước rất nhỏ, mắt thường và kính lúp không thấy rõ.","Kính hiển vi quang học phóng to được 40 đến 3 000 lần."],"kq":"Dùng kính hiển vi quang học."},"nham":["Vặn ốc to khi vật kính ở sát tiêu bản làm vỡ tiêu bản và hỏng vật kính."],"lq":["l6-kinh-lup","l6-an-toan-phong-thuc-hanh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-don-vi-do","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":7,"loai":"kn","ten":"Đơn vị đo lường","ten_khac":["don vi do","don vi do luong","he si","don vi chuan","si","don vi co ban","dai luong"],"noi_dung":"Đại lượng chuẩn dùng để so sánh khi đo; nước ta dùng đơn vị đo lường chính thức theo hệ SI.","cong_thuc":null,"y":["Đo một đại lượng là so sánh nó với một đại lượng cùng loại được chọn làm <b>đơn vị</b>.","Kết quả đo luôn gồm <b>số đo</b> và <b>đơn vị</b>, ví dụ 1,5 m."],"bang":[["Đại lượng","Đơn vị SI","Kí hiệu"],["Chiều dài","mét","m"],["Khối lượng","kilôgam","kg"],["Thời gian","giây","s"],["Nhiệt độ","kelvin","K"]],"bien":null,"vd":null,"nham":["Ghi kết quả đo mà quên đơn vị."],"lq":["l6-chieu-dai","l6-khoi-luong","l6-thoi-gian","l6-nhiet-do"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-chieu-dai","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":8,"loai":"dl","ten":"Chiều dài","ten_khac":["chieu dai","do dai","met","m","km","cm","mm","don vi chieu dai","length"],"noi_dung":"Đại lượng cho biết độ dài của vật hay khoảng cách giữa hai điểm; đơn vị chuẩn là mét (m).","cong_thuc":null,"y":["Đơn vị đo chiều dài trong hệ SI là <b>mét (m)</b>.","Đơn vị thường dùng khác: km, dm, cm, mm.","Dụng cụ đo: các loại <b>thước</b>."],"bang":[["Đơn vị","Đổi ra mét"],["1 km","1 000 m"],["1 dm","0,1 m"],["1 cm","0,01 m"],["1 mm","0,001 m"]],"bien":null,"vd":{"de":"Một quyển sách dày 2,5 cm. Đổi độ dày đó sang đơn vị mét và milimét.","buoc":["2,5 cm = 2,5 : 100 m","2,5 cm = 2,5 · 10 mm"],"kq":"0,025 m = 25 mm"},"nham":["Đổi 1 m = 100 mm (đúng là 1 m = 1 000 mm)."],"lq":["l6-thuoc-do","l6-do-chieu-dai","l6-don-vi-do"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-thuoc-do","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":9,"loai":"tn","ten":"Thước đo chiều dài","ten_khac":["thuoc","thuoc do","thuoc ke","thuoc day","thuoc cuon","thuoc met","thuoc kep"],"noi_dung":"Dụng cụ dùng để đo chiều dài; mỗi thước có giới hạn đo và độ chia nhỏ nhất riêng.","cong_thuc":null,"y":["Các loại: thước thẳng (thước kẻ), thước dây, thước cuộn, thước kẹp…","Chọn thước có <b>GHĐ</b> lớn hơn chiều dài cần đo và <b>ĐCNN</b> phù hợp để đo chính xác.","Ví dụ: đo chiều dài sân trường dùng thước cuộn; đo chiều dài bút chì dùng thước kẻ."],"bang":null,"bien":null,"vd":{"de":"Cần đo chiều dài quyển vở khoảng 24 cm. Nên chọn thước nào trong hai thước: GHĐ 20 cm hay GHĐ 30 cm (cùng ĐCNN 1 mm)?","buoc":["Thước phải có GHĐ lớn hơn chiều dài cần đo.","Thước GHĐ 20 cm nhỏ hơn vật cần đo nên không dùng được."],"kq":"Chọn thước có GHĐ 30 cm, ĐCNN 1 mm."},"nham":null,"lq":["l6-gioi-han-do","l6-do-chia-nho-nhat","l6-do-chieu-dai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-gioi-han-do","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":10,"loai":"kn","ten":"Giới hạn đo (GHĐ)","ten_khac":["gioi han do","ghd","so lon nhat tren thuoc","gioi han","do lon nhat"],"noi_dung":"Giá trị lớn nhất ghi trên dụng cụ đo (thước, cân, nhiệt kế…).","cong_thuc":null,"y":["Thước kẻ có số lớn nhất là 30 cm thì GHĐ là <b>30 cm</b>.","Nên chọn dụng cụ có GHĐ lớn hơn đại lượng cần đo để chỉ đo một lần."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm GHĐ với độ dài thực của thước (thước có thể dài hơn vạch lớn nhất)."],"lq":["l6-do-chia-nho-nhat","l6-thuoc-do","l6-can"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-do-chia-nho-nhat","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":11,"loai":"kn","ten":"Độ chia nhỏ nhất (ĐCNN)","ten_khac":["do chia nho nhat","dcnn","vach chia","khoang cach hai vach","do chia"],"noi_dung":"Hiệu giá trị giữa hai vạch chia liên tiếp trên dụng cụ đo.","cong_thuc":null,"y":["Cách tìm: lấy hiệu hai số ghi liền nhau chia cho số khoảng chia giữa chúng.","ĐCNN càng nhỏ thì phép đo càng <b>chính xác</b>."],"bang":null,"bien":null,"vd":{"de":"Giữa vạch 0 và vạch 1 cm của thước có 10 khoảng chia. Tìm ĐCNN.","buoc":["ĐCNN = (1 cm − 0) : 10"],"kq":"ĐCNN = 0,1 cm = 1 mm"},"nham":["Đếm số vạch thay vì đếm số khoảng chia."],"lq":["l6-gioi-han-do","l6-thuoc-do","l6-nhiet-ke"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-do-chieu-dai","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":12,"loai":"tn","ten":"Cách đo chiều dài","ten_khac":["cach do chieu dai","do chieu dai","dat thuoc","doc ket qua do","uoc luong chieu dai"],"noi_dung":"Các bước dùng thước đo chiều dài một vật cho đúng và chính xác.","cong_thuc":null,"y":["1. <b>Ước lượng</b> chiều dài cần đo. 2. Chọn thước có GHĐ và ĐCNN phù hợp.","3. Đặt thước dọc theo vật, một đầu vật ngang <b>vạch số 0</b>.","4. Đặt mắt nhìn <b>vuông góc</b> với thước ở đầu kia của vật.","5. Đọc và ghi kết quả theo vạch chia gần nhất với đầu kia của vật."],"bang":null,"bien":null,"vd":{"de":"Khi đo chiều dài một chiếc bút chì, một bạn đặt mắt nhìn lệch sang một bên thước thay vì nhìn vuông góc. Kết quả đo bị ảnh hưởng thế nào?","buoc":["Đặt mắt lệch làm đường ngắm không vuông góc với thước.","Đây là một lỗi gây sai số khi đọc vạch chia."],"kq":"Kết quả đo bị sai lệch; cần đặt mắt nhìn vuông góc với thước."},"nham":["Nhìn xiên khi đọc số làm kết quả sai.","Để đầu vật không trùng vạch 0 mà không trừ đi phần lệch."],"lq":["l6-thuoc-do","l6-chieu-dai","l6-do-chia-nho-nhat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-khoi-luong","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":13,"loai":"dl","ten":"Khối lượng","ten_khac":["khoi luong","kg","kilogam","gam","tan","ta yen","luong chat","mass","m"],"noi_dung":"Số đo lượng chất của một vật; đơn vị chuẩn là kilôgam (kg).","cong_thuc":null,"y":["Đơn vị SI: <b>kilôgam (kg)</b>. Đơn vị khác: tấn, tạ, yến, gam (g), miligam (mg).","Số ghi trên bao bì (ví dụ \"khối lượng tịnh 500 g\") là khối lượng chất chứa trong đó.","Dụng cụ đo: <b>cân</b>."],"bang":[["Đơn vị","Đổi"],["1 tấn","1 000 kg"],["1 tạ","100 kg"],["1 yến","10 kg"],["1 kg","1 000 g"],["1 g","1 000 mg"]],"bien":null,"vd":{"de":"Một hộp sữa có khối lượng 1 800 g. Đổi khối lượng đó sang kilôgam.","buoc":["Đổi đơn vị: 1 kg = 1 000 g.","1 800 g = 1 800 : 1 000 kg"],"kq":"1,8 kg"},"nham":["Nhầm khối lượng (kg) với trọng lượng (N)."],"lq":["l6-can","l6-trong-luong","l6-don-vi-do"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-can","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":14,"loai":"tn","ten":"Cân","ten_khac":["can","can dong ho","can dien tu","can don","can robecvan","can y te","do khoi luong","cach can"],"noi_dung":"Dụng cụ dùng để đo khối lượng của vật.","cong_thuc":null,"y":["Các loại: cân đồng hồ, cân điện tử, cân đòn, cân Roberval, cân y tế…","Cách đo: ước lượng khối lượng, chọn cân có GHĐ và ĐCNN phù hợp, <b>hiệu chỉnh về số 0</b>.","Đặt vật lên cân, mắt nhìn vuông góc với vạch chia (hoặc đọc số trên màn hình), ghi kết quả."],"bang":null,"bien":null,"vd":{"de":"Trước khi cân một vật bằng cân đồng hồ, kim của cân chưa chỉ đúng vạch số 0. Cần làm gì trước khi cân?","buoc":["Kim lệch số 0 sẽ làm kết quả cân bị sai.","Quy tắc dùng cân yêu cầu hiệu chỉnh về số 0 trước khi đo."],"kq":"Phải chỉnh kim về đúng vạch số 0 rồi mới đặt vật lên cân."},"nham":["Không chỉnh kim/số về 0 trước khi cân."],"lq":["l6-khoi-luong","l6-gioi-han-do","l6-do-chia-nho-nhat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-thoi-gian","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":15,"loai":"dl","ten":"Thời gian","ten_khac":["thoi gian","giay","s","phut","gio","don vi thoi gian","time"],"noi_dung":"Đại lượng cho biết một việc, một hiện tượng diễn ra lâu hay nhanh; đơn vị chuẩn là giây (s).","cong_thuc":null,"y":["Đơn vị SI: <b>giây (s)</b>. Đơn vị khác: phút, giờ (h), ngày, tuần, tháng, năm.","Dụng cụ đo: <b>đồng hồ</b>."],"bang":[["Đơn vị","Đổi"],["1 phút","60 s"],["1 giờ","60 phút = 3 600 s"],["1 ngày","24 giờ"]],"bien":null,"vd":{"de":"Một vận động viên chạy hết 2 phút 15 giây. Đổi thời gian đó sang giây.","buoc":["2 phút = 2 · 60 = 120 s","Tổng thời gian = 120 + 15"],"kq":"135 s"},"nham":["Viết 1,5 giờ = 1 giờ 50 phút (đúng là 1 giờ 30 phút)."],"lq":["l6-dong-ho","l6-don-vi-do"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-dong-ho","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":16,"loai":"tn","ten":"Đồng hồ","ten_khac":["dong ho","dong ho bam giay","dong ho dien tu","dong ho kim","do thoi gian","cach do thoi gian"],"noi_dung":"Dụng cụ dùng để đo thời gian.","cong_thuc":null,"y":["Các loại: đồng hồ kim, đồng hồ điện tử, <b>đồng hồ bấm giây</b> (đo khoảng thời gian ngắn, cần chính xác).","Cách đo: ước lượng thời gian, chọn đồng hồ phù hợp, <b>chỉnh về số 0</b>, bấm bắt đầu và kết thúc đúng lúc.","Đọc và ghi kết quả kèm đơn vị."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l6-thoi-gian","l6-don-vi-do"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-nhiet-do","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":17,"loai":"dl","ten":"Nhiệt độ","ten_khac":["nhiet do","do nong lanh","do c","do f","kelvin","temperature","t"],"noi_dung":"Số đo độ \"nóng\", \"lạnh\" của một vật; đo bằng nhiệt kế.","cong_thuc":null,"y":["Vật càng nóng thì nhiệt độ càng <b>cao</b>.","Cảm giác bằng tay không xác định đúng nhiệt độ, phải dùng <b>nhiệt kế</b>.","Đơn vị thường dùng ở nước ta: <b>độ C (°C)</b>. Đơn vị trong hệ SI là kelvin (K)."],"bang":null,"bien":null,"vd":{"de":"Nhiệt kế y tế chỉ 38,5 °C trong khi nhiệt độ cơ thể bình thường là 37 °C. Nhiệt độ đó cao hơn bình thường bao nhiêu?","buoc":["Nhiệt độ đo được là 38,5 °C, nhiệt độ bình thường là 37 °C.","So sánh: 38,5 − 37"],"kq":"Cao hơn 1,5 °C, có thể bạn đó đang sốt nhẹ"},"nham":["Dùng tay để so sánh nhiệt độ — tay dễ cho cảm giác sai."],"lq":["l6-nhiet-ke","l6-thang-celsius","l6-thang-fahrenheit"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-nhiet-ke","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":18,"loai":"tn","ten":"Nhiệt kế","ten_khac":["nhiet ke","nhiet ke y te","nhiet ke dien tu","nhiet ke hong ngoai","nhiet ke thuy ngan","nhiet ke ruou","do nhiet do"],"noi_dung":"Dụng cụ dùng để đo nhiệt độ.","cong_thuc":null,"y":["Nhiệt kế chất lỏng hoạt động dựa trên <b>sự nở vì nhiệt</b> của chất lỏng (thủy ngân, rượu).","Các loại: nhiệt kế y tế, nhiệt kế rượu, nhiệt kế điện tử, nhiệt kế hồng ngoại.","Cách đo: ước lượng, chọn nhiệt kế có GHĐ, ĐCNN phù hợp, đặt đúng cách, chờ ổn định rồi đọc."],"bang":[["Loại","Thường dùng"],["Nhiệt kế y tế","đo nhiệt độ cơ thể"],["Nhiệt kế rượu","đo nhiệt độ không khí"],["Nhiệt kế hồng ngoại","đo nhanh, không cần chạm"]],"bien":null,"vd":{"de":"Trước khi đo nhiệt độ cơ thể bằng nhiệt kế y tế thủy ngân, vì sao phải vẩy nhẹ cho mực thủy ngân tụt xuống dưới vạch 35 °C?","buoc":["Nhiệt kế y tế có chỗ thắt nhỏ, thủy ngân không tự tụt xuống khi nhiệt kế nguội.","Nếu không vẩy, mực thủy ngân còn giữ số chỉ của lần đo trước nên đọc sai."],"kq":"Vẩy nhẹ (cầm chắc, tránh va đập làm vỡ) để thủy ngân về dưới 35 °C thì lần đo mới chính xác."},"nham":["Cầm vào bầu nhiệt kế khi đo làm sai kết quả."],"lq":["l6-nhiet-do","l6-thang-celsius","l6-do-chia-nho-nhat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-thang-celsius","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":19,"loai":"kn","ten":"Thang nhiệt độ Celsius","ten_khac":["celsius","thang celsius","do c","xen xi ut","thang nhiet do","nuoc da tan 0 do"],"noi_dung":"Thang nhiệt độ lấy nước đá đang tan là 0 °C và nước đang sôi là 100 °C.","cong_thuc":null,"y":["Khoảng giữa 0 °C và 100 °C chia làm 100 phần, mỗi phần là <b>1 °C</b>.","Nhiệt độ thấp hơn 0 °C viết dấu trừ, ví dụ −10 °C.","Là thang nhiệt độ dùng phổ biến ở Việt Nam."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l6-thang-fahrenheit","l6-nhiet-do","l6-nhiet-ke"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-thang-fahrenheit","mon":"KHTN","khoi":"6","chu_de":"l6-do-luong","thu_tu":20,"loai":"kn","ten":"Thang nhiệt độ Fahrenheit","ten_khac":["fahrenheit","thang fahrenheit","do f","fa ren hai","doi do c sang do f"],"noi_dung":"Thang nhiệt độ lấy nước đá đang tan là 32 °F và nước đang sôi là 212 °F.","cong_thuc":"t(°F) = t(°C) × 1,8 + 32","y":["Dùng nhiều ở Mỹ và một số nước. Công thức đổi là kiến thức <b>mở rộng</b>.","Khoảng 0 °C → 100 °C ứng với 32 °F → 212 °F (180 phần), nên 1 °C ứng với <b>1,8 °F</b>."],"bang":null,"bien":[["t(°F)","nhiệt độ theo thang Fahrenheit","°F"],["t(°C)","nhiệt độ theo thang Celsius","°C"]],"vd":{"de":"Đổi 25 °C sang °F.","buoc":["t(°F) = 25 × 1,8 + 32 = 45 + 32"],"kq":"77 °F"},"nham":["Quên cộng 32 khi đổi từ °C sang °F."],"lq":["l6-thang-celsius","l6-nhiet-do"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-luc","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":1,"loai":"kn","ten":"Lực","ten_khac":["luc","luc day","luc keo","force","f","tac dung luc","luc la gi"],"noi_dung":"Tác dụng đẩy hoặc kéo của vật này lên vật khác.","cong_thuc":null,"y":["Lực có <b>điểm đặt</b>, <b>phương</b>, <b>chiều</b> và <b>độ lớn</b>.","Đơn vị lực: <b>niutơn (N)</b>; đo bằng lực kế.","Lực có thể làm vật thay đổi tốc độ, đổi hướng chuyển động hoặc biến dạng."],"bang":null,"bien":null,"vd":{"de":"Khi một bạn dùng tay kéo cánh cửa đóng lại, tay bạn đó có tác dụng lực lên cửa không?","buoc":["Tay tác dụng lực kéo lên cửa làm cửa chuyển động.","Đây là tác dụng đẩy hoặc kéo của vật này lên vật khác, đúng định nghĩa lực."],"kq":"Có; đó là lực kéo của tay tác dụng lên cánh cửa."},"nham":["Nghĩ phải chạm vào nhau mới có lực (lực hấp dẫn, lực từ không cần chạm)."],"lq":["l6-tac-dung-cua-luc","l6-bieu-dien-luc","l6-luc-ke","l6-luc-tiep-xuc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-tac-dung-cua-luc","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":2,"loai":"ht","ten":"Tác dụng của lực","ten_khac":["tac dung cua luc","ket qua tac dung luc","thay doi chuyen dong","bien dang","doi huong","thay doi toc do"],"noi_dung":"Lực có thể làm thay đổi tốc độ, hướng chuyển động của vật hoặc làm vật bị biến dạng.","cong_thuc":null,"y":["<b>Thay đổi tốc độ</b>: đá quả bóng đang đứng yên làm nó chuyển động.","<b>Đổi hướng</b>: thủ môn đẩy quả bóng bay chệch hướng.","<b>Biến dạng</b> (thay đổi hình dạng): bóp quả bóng cao su, kéo dãn lò xo.","Một lực có thể gây ra đồng thời nhiều kết quả trên."],"bang":null,"bien":null,"vd":{"de":"Một quả bóng đang bay thẳng thì bị một cầu thủ dùng đầu đánh lệch hướng. Lực tác dụng của đầu lên bóng đã gây ra tác dụng gì?","buoc":["Lực có thể làm thay đổi hướng chuyển động của vật.","Ở đây bóng đổi hướng bay sau khi chạm đầu cầu thủ."],"kq":"Lực đã làm thay đổi hướng chuyển động của quả bóng."},"nham":null,"lq":["l6-luc","l6-bien-dang-lo-xo","l6-bieu-dien-luc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-luc-ke","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":3,"loai":"tn","ten":"Lực kế","ten_khac":["luc ke","do luc","luc ke lo xo","niuton","newton","n","dung cu do luc"],"noi_dung":"Dụng cụ đo độ lớn của lực; lực kế lò xo có bộ phận chính là một lò xo gắn kim chỉ thị.","cong_thuc":null,"y":["Đơn vị đo: <b>niutơn (N)</b>.","Cách đo: ước lượng lực, chọn lực kế có GHĐ, ĐCNN phù hợp, <b>chỉnh kim về vạch 0</b>.","Cho lực cần đo tác dụng dọc theo trục lò xo, đọc số chỉ khi kim đứng yên."],"bang":null,"bien":null,"vd":{"de":"Treo một vật vào lực kế lò xo, kim chỉ dừng ở vạch 2,5 N. Con số này cho biết điều gì?","buoc":["Lực kế đo độ lớn của lực bằng độ dãn của lò xo bên trong.","Số chỉ trên lực kế chính là độ lớn lực (ở đây là trọng lượng vật treo)."],"kq":"Vật có trọng lượng 2,5 N."},"nham":["Cầm lực kế nghiêng so với phương của lực cần đo."],"lq":["l6-luc","l6-bien-dang-lo-xo","l6-trong-luong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-bieu-dien-luc","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":4,"loai":"kn","ten":"Biểu diễn lực","ten_khac":["bieu dien luc","mui ten luc","ve luc","diem dat","phuong chieu","ti xich","ty xich","vecto luc"],"noi_dung":"Biểu diễn lực bằng một mũi tên có gốc, hướng và độ dài theo tỉ xích chọn trước.","cong_thuc":null,"y":["<b>Gốc</b> mũi tên là điểm đặt của lực.","<b>Hướng</b> mũi tên (phương và chiều) là hướng của lực.","<b>Độ dài</b> mũi tên biểu thị độ lớn của lực theo tỉ xích."],"bang":null,"bien":null,"vd":{"de":"Biểu diễn lực kéo 30 N theo phương nằm ngang, chiều từ trái sang phải, tỉ xích 1 cm ứng với 10 N.","buoc":["Độ dài mũi tên = 30 : 10 = 3 cm","Vẽ mũi tên nằm ngang, gốc tại điểm đặt, đầu mũi tên hướng sang phải."],"kq":"Mũi tên dài 3 cm, nằm ngang, hướng sang phải."},"nham":["Vẽ gốc mũi tên không nằm ở điểm đặt của lực trên vật."],"lq":["l6-luc","l6-trong-luong","l6-luc-ke"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-luc-tiep-xuc","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":5,"loai":"kn","ten":"Lực tiếp xúc","ten_khac":["luc tiep xuc","tiep xuc","cham vao","luc day tay","contact force"],"noi_dung":"Lực xuất hiện khi vật gây ra lực có sự tiếp xúc (chạm) với vật chịu tác dụng của lực.","cong_thuc":null,"y":["Ví dụ: tay đẩy cửa, chân đá bóng, người kéo xe, lực ma sát.","Khi thôi tiếp xúc thì lực tiếp xúc không còn."],"bang":null,"bien":null,"vd":{"de":"Khi một bạn dùng chân đá quả bóng, đây có phải lực tiếp xúc không?","buoc":["Lực tiếp xúc xuất hiện khi vật gây lực chạm vào vật chịu lực.","Chân bạn đó chạm trực tiếp vào quả bóng khi đá."],"kq":"Có; đây là lực tiếp xúc vì chân và bóng có sự tiếp xúc."},"nham":null,"lq":["l6-luc-khong-tiep-xuc","l6-luc","l6-luc-ma-sat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-luc-khong-tiep-xuc","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":6,"loai":"kn","ten":"Lực không tiếp xúc","ten_khac":["luc khong tiep xuc","khong tiep xuc","luc tu","luc hut nam cham","tac dung tu xa"],"noi_dung":"Lực xuất hiện khi vật gây ra lực không có sự tiếp xúc với vật chịu tác dụng của lực.","cong_thuc":null,"y":["Ví dụ: lực hút của Trái Đất lên quả táo đang rơi, lực hút của nam châm lên đinh sắt ở gần.","Lực hấp dẫn, lực từ là những lực không tiếp xúc."],"bang":null,"bien":null,"vd":{"de":"Một chiếc kẹp giấy bị hút về phía nam châm dù chưa chạm vào nam châm. Đây là lực tiếp xúc hay không tiếp xúc?","buoc":["Lực không tiếp xúc xuất hiện khi hai vật không chạm nhau.","Nam châm và kẹp giấy chưa chạm nhau nhưng vẫn có lực hút."],"kq":"Là lực không tiếp xúc (lực hút của nam châm)."},"nham":null,"lq":["l6-luc-tiep-xuc","l6-luc-hap-dan","l6-luc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-bien-dang-lo-xo","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":7,"loai":"ht","ten":"Biến dạng của lò xo","ten_khac":["bien dang lo xo","lo xo","bien dang dan hoi","dan hoi","lo xo dan","lo xo nen","gioi han dan hoi"],"noi_dung":"Lò xo bị kéo thì dãn ra, bị nén thì co lại; thôi tác dụng lực, lò xo trở lại hình dạng ban đầu.","cong_thuc":null,"y":["Biến dạng như vậy gọi là <b>biến dạng đàn hồi</b>; lò xo là vật có tính đàn hồi.","Nếu kéo quá mạnh (vượt <b>giới hạn đàn hồi</b>), lò xo không trở lại hình dạng ban đầu.","Ứng dụng: lực kế, đệm lò xo, bút bi, giảm xóc xe máy."],"bang":null,"bien":null,"vd":{"de":"Treo các quả nặng vào một lò xo, lò xo dãn ra càng nhiều khi quả nặng càng nặng. Nếu bỏ hết quả nặng ra, lò xo sẽ như thế nào?","buoc":["Lò xo là vật đàn hồi: dãn khi bị kéo, co lại khi thôi tác dụng lực.","Khi bỏ quả nặng, lực kéo không còn tác dụng lên lò xo."],"kq":"Lò xo trở lại hình dạng (chiều dài) ban đầu."},"nham":null,"lq":["l6-do-dan-lo-xo","l6-luc-ke","l6-the-nang-dan-hoi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-do-dan-lo-xo","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":8,"loai":"dl","ten":"Độ dãn của lò xo","ten_khac":["do dan lo xo","do dan","l - l0","chieu dai tu nhien","delta l","do bien dang"],"noi_dung":"Hiệu giữa chiều dài khi bị biến dạng và chiều dài tự nhiên của lò xo.","cong_thuc":"Δl = l − l0","y":["Với lò xo treo thẳng đứng, độ dãn <b>tỉ lệ</b> với khối lượng vật treo (trong giới hạn đàn hồi).","Khối lượng vật treo tăng gấp đôi thì độ dãn tăng gấp đôi."],"bang":null,"bien":[["Δl","độ dãn của lò xo","cm"],["l","chiều dài lò xo khi bị kéo dãn","cm"],["l0","chiều dài tự nhiên của lò xo","cm"]],"vd":{"de":"Lò xo dài tự nhiên 10 cm. Treo vật 50 g thì lò xo dài 11 cm. Treo vật 150 g thì lò xo dài bao nhiêu?","buoc":["Treo 50 g: Δl = 11 − 10 = 1 cm","150 g gấp 3 lần 50 g nên Δl = 3 × 1 = 3 cm","l = l0 + Δl = 10 + 3"],"kq":"l = 13 cm"},"nham":["Cho chiều dài lò xo tỉ lệ với khối lượng vật treo (đúng là độ dãn tỉ lệ)."],"lq":["l6-bien-dang-lo-xo","l6-luc-ke","l6-khoi-luong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-vat-dan-hoi","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":9,"loai":"kn","ten":"Vật có tính chất đàn hồi","ten_khac":["bien dang dan hoi","tinh chat dan hoi","vat dan hoi","day chun","gioi han dan hoi"],"noi_dung":"Vật bị biến dạng khi có lực tác dụng và trở lại hình dạng ban đầu khi thôi tác dụng lực là vật có tính chất đàn hồi.","cong_thuc":null,"y":["Ví dụ: lò xo, dây cao su, quả bóng cao su.","Nếu kéo quá mạnh (quá giới hạn đàn hồi), vật không trở lại hình dạng ban đầu được nữa.","Đất nặn, kẹo cao su bị biến dạng nhưng không tự trở lại hình dạng cũ."],"bang":null,"bien":null,"vd":{"de":"Kéo dãn một sợi dây chun rồi thả ra; bóp méo một cục đất nặn rồi thả tay. Vật nào có tính chất đàn hồi?","buoc":["Dây chun trở lại chiều dài ban đầu khi thả tay.","Cục đất nặn giữ nguyên hình dạng đã bị bóp méo."],"kq":"Dây chun có tính chất đàn hồi; cục đất nặn thì không."},"nham":["Nghĩ lò xo kéo mạnh bao nhiêu cũng trở lại như cũ; quá giới hạn đàn hồi thì lò xo bị hỏng."],"lq":["l6-bien-dang-lo-xo","l6-do-dan-lo-xo","l6-the-nang-dan-hoi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-luc-hap-dan","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":10,"loai":"kn","ten":"Lực hấp dẫn","ten_khac":["luc hap dan","hap dan","luc hut trai dat","trong luc","gravity","luc hut"],"noi_dung":"Lực hút giữa các vật có khối lượng.","cong_thuc":null,"y":["Mọi vật có khối lượng đều hút nhau; là lực <b>không tiếp xúc</b>.","Lực hút của Trái Đất lên vật (trọng lực) có phương <b>thẳng đứng</b>, chiều hướng về phía Trái Đất.","Nhờ lực hấp dẫn, vật được thả thì rơi xuống, Mặt Trăng chuyển động quanh Trái Đất."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l6-trong-luong","l6-luc-khong-tiep-xuc","l6-mat-trang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-trong-luong","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":11,"loai":"dl","ten":"Trọng lượng","ten_khac":["trong luong","p","trong luc","suc nang","weight","niuton","luc hut trai dat"],"noi_dung":"Độ lớn lực hút của Trái Đất tác dụng lên vật; đơn vị là niutơn (N).","cong_thuc":null,"y":["Đo trọng lượng bằng <b>lực kế</b>, không đo bằng cân.","Vật có khối lượng khoảng <b>100 g</b> thì có trọng lượng khoảng <b>1 N</b>.","Khối lượng (kg) là lượng chất của vật; trọng lượng (N) là độ lớn lực hút của Trái Đất — hai đại lượng khác nhau."],"bang":[["","Khối lượng","Trọng lượng"],["Là gì","số đo lượng chất","độ lớn lực hút của Trái Đất"],["Đơn vị","kg","N"],["Dụng cụ đo","cân","lực kế"]],"bien":null,"vd":{"de":"Một bạn học sinh có khối lượng 40 kg. Tính trọng lượng của bạn đó.","buoc":["Công thức: P = 10m (m tính bằng kg, P tính bằng N).","P = 10 · 40"],"kq":"P = 400 N"},"nham":["Nghĩ \"nặng 40 kg\" là trọng lượng 40 kg — đó là khối lượng; trọng lượng tính bằng N (khoảng 400 N)."],"lq":["l6-khoi-luong","l6-luc-hap-dan","l6-luc-ke"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-phuong-chieu-luc-hut","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":12,"loai":"kn","ten":"Phương, chiều lực hút Trái Đất","ten_khac":["phuong thang dung","day doi","chieu luc hut","luc hut trai dat","trong luong tren mat trang"],"noi_dung":"Lực hút của Trái Đất tác dụng lên vật có phương thẳng đứng và chiều hướng về phía Trái Đất.","cong_thuc":null,"y":["Dây dọi (quả nặng treo vào sợi dây) chỉ phương thẳng đứng.","Vật được thả ra đều rơi theo phương thẳng đứng, chiều từ trên xuống.","Khối lượng của vật không đổi theo nơi, nhưng trọng lượng thay đổi: trên Mặt Trăng, trọng lượng của vật chỉ khoảng 1/6 so với trên Trái Đất."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ lên Mặt Trăng khối lượng của vật giảm; thực ra chỉ trọng lượng giảm."],"lq":["l6-trong-luong","l6-luc-hap-dan","l6-khoi-luong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-luc-ma-sat","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":13,"loai":"kn","ten":"Lực ma sát","ten_khac":["luc ma sat","ma sat","friction","fms","ma sat co loi","ma sat co hai"],"noi_dung":"Lực xuất hiện ở mặt tiếp xúc giữa hai vật, cản trở chuyển động hoặc xu hướng chuyển động của vật.","cong_thuc":null,"y":["Là lực <b>tiếp xúc</b>; có ma sát trượt và ma sát nghỉ.","<b>Có lợi</b>: giúp đi lại không trượt ngã, cầm nắm được đồ vật, phanh xe.","<b>Có hại</b>: làm mòn lốp xe, xích xe, cản trở chuyển động.","Giảm ma sát: tra dầu mỡ, làm nhẵn mặt tiếp xúc; tăng ma sát: làm khía rãnh, rắc cát."],"bang":null,"bien":null,"vd":{"de":"Khi xe đạp đang chạy, nếu bóp phanh thì xe chuyển động chậm dần rồi dừng lại. Lực nào đã cản trở chuyển động của xe?","buoc":["Lực ma sát xuất hiện ở mặt tiếp xúc giữa hai vật, cản trở chuyển động.","Má phanh ép vào bánh xe tạo ra lực cản chuyển động."],"kq":"Lực ma sát (giữa má phanh và bánh xe) làm xe chậm dần."},"nham":null,"lq":["l6-ma-sat-truot","l6-ma-sat-nghi","l6-luc-can-cua-nuoc","l6-luc-tiep-xuc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-ma-sat-truot","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":14,"loai":"kn","ten":"Lực ma sát trượt","ten_khac":["ma sat truot","luc ma sat truot","truot","mst","sliding friction"],"noi_dung":"Lực ma sát sinh ra khi một vật trượt trên bề mặt một vật khác, cản trở chuyển động trượt.","cong_thuc":null,"y":["Ví dụ: má phanh ép vào vành xe, kéo thùng hàng trượt trên sàn.","Luôn ngược chiều với chiều chuyển động trượt của vật."],"bang":null,"bien":null,"vd":{"de":"Khi đẩy một chiếc hộp trượt trên sàn nhà, hộp chuyển động chậm dần rồi dừng lại dù không còn ai đẩy. Loại lực ma sát nào đã tác dụng lên hộp?","buoc":["Ma sát trượt sinh ra khi vật trượt trên bề mặt vật khác.","Hộp trượt trên sàn nên chịu lực ma sát trượt cản trở chuyển động."],"kq":"Lực ma sát trượt giữa đáy hộp và sàn nhà."},"nham":null,"lq":["l6-luc-ma-sat","l6-ma-sat-nghi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-ma-sat-nghi","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":15,"loai":"kn","ten":"Lực ma sát nghỉ","ten_khac":["ma sat nghi","luc ma sat nghi","giu vat dung yen","msn","static friction"],"noi_dung":"Lực ma sát giữ cho vật đứng yên trên bề mặt vật khác khi vật bị tác dụng lực nhưng chưa chuyển động.","cong_thuc":null,"y":["Ví dụ: đẩy nhẹ tủ nặng mà tủ vẫn đứng yên; quyển sách nằm yên trên mặt bàn nghiêng.","Nhờ ma sát nghỉ, ta đi bộ không bị trượt chân, cầm được cốc nước."],"bang":null,"bien":null,"vd":{"de":"Một thùng hàng nặng đặt trên sàn dốc nhẹ vẫn đứng yên, không bị trượt xuống. Lực nào đã giữ cho thùng hàng đứng yên?","buoc":["Ma sát nghỉ giữ vật đứng yên khi có xu hướng trượt do lực khác.","Thùng hàng chưa chuyển động nên lực ma sát này là ma sát nghỉ."],"kq":"Lực ma sát nghỉ giữa đáy thùng và mặt dốc."},"nham":null,"lq":["l6-luc-ma-sat","l6-ma-sat-truot"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-luc-can-cua-nuoc","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":16,"loai":"kn","ten":"Lực cản của nước","ten_khac":["luc can cua nuoc","luc can","can nuoc","luc can khong khi","suc can","hinh khi dong hoc"],"noi_dung":"Lực nước tác dụng lên vật chuyển động trong nước, cản trở chuyển động của vật.","cong_thuc":null,"y":["Vật chuyển động trong <b>không khí</b> cũng chịu lực cản của không khí.","Diện tích mặt cản càng lớn thì lực cản càng lớn.","Tàu thuyền, cá có hình dạng thuôn nhọn để giảm lực cản; dù dùng lực cản không khí để rơi chậm."],"bang":null,"bien":null,"vd":{"de":"Khi bơi, một người cảm thấy khó di chuyển hơn nhiều so với khi đi bộ trên cạn. Nguyên nhân là do đâu?","buoc":["Nước tác dụng lực cản lên vật chuyển động trong nó.","Lực cản của nước lớn hơn lực cản của không khí nên khó di chuyển hơn."],"kq":"Do lực cản của nước tác dụng lên người bơi."},"nham":null,"lq":["l6-luc-ma-sat","l6-luc-tiep-xuc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-luc-can-khong-khi","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":17,"loai":"ht","ten":"Lực cản của không khí","ten_khac":["luc can khong khi","luc can cua khong khi","du","nhay du","air resistance"],"noi_dung":"Vật chuyển động trong không khí chịu lực cản của không khí, ngược chiều chuyển động; lực cản này thường nhỏ hơn lực cản của nước.","cong_thuc":null,"y":["Lực cản của không khí làm vật chuyển động chậm lại.","Diện tích mặt cản càng lớn thì lực cản càng lớn: dù bung ra giúp người nhảy dù rơi chậm.","Người đi xe đạp cúi thấp người để giảm lực cản của không khí."],"bang":null,"bien":null,"vd":{"de":"Vì sao người nhảy dù có thể tiếp đất an toàn khi dù đã bung?","buoc":["Dù bung ra có mặt cản rất rộng.","Lực cản của không khí lên dù lớn, làm người rơi chậm lại."],"kq":"Nhờ lực cản lớn của không khí lên mặt dù rộng, người rơi chậm và tiếp đất an toàn."},"nham":["Cho rằng không khí không cản trở chuyển động."],"lq":["l6-luc-can-cua-nuoc","l6-giam-luc-can","l6-luc-ma-sat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-giam-luc-can","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":18,"loai":"ud","ten":"Giảm hoặc tận dụng lực cản","ten_khac":["giam luc can","hinh dang thuon","tau thuyen","ca boi nhanh","mai cheo","mat can"],"noi_dung":"Vật hình thuôn, nhọn phía trước chịu lực cản nhỏ hơn khi chuyển động trong nước, không khí; muốn tận dụng lực cản thì tăng mặt cản.","cong_thuc":null,"y":["Thân cá, mũi tàu thủy, máy bay có dạng thuôn để giảm lực cản.","Vận động viên bơi đội mũ bơi, mặc đồ bơi bó sát để giảm lực cản của nước.","Tận dụng lực cản: mái chèo bản rộng, chân vịt có màng, dù có mặt rộng."],"bang":null,"bien":null,"vd":{"de":"Vì sao mũi thuyền đua thường được làm nhọn và thon?","buoc":["Mũi nhọn, thân thon làm diện tích mặt cản phía trước nhỏ.","Lực cản của nước nhỏ hơn nên thuyền đi nhanh hơn với cùng sức chèo."],"kq":"Để giảm lực cản của nước, giúp thuyền đi nhanh."},"nham":null,"lq":["l6-luc-can-cua-nuoc","l6-luc-can-khong-khi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-nang-luong","mon":"KHTN","khoi":"6","chu_de":"l6-nang-luong","thu_tu":1,"loai":"kn","ten":"Năng lượng","ten_khac":["nang luong","energy","truyen nang luong","dang nang luong","j","jun","joule"],"noi_dung":"Đại lượng đặc trưng cho khả năng tác dụng lực của vật (làm vật khác chuyển động, biến dạng…).","cong_thuc":null,"y":["Vật có năng lượng thì có khả năng tác dụng lực lên vật khác.","Năng lượng có thể <b>truyền</b> từ vật này sang vật khác, hoặc chuyển từ dạng này sang dạng khác.","Đơn vị năng lượng là <b>jun (J)</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l6-dang-nang-luong","l6-chuyen-hoa-nang-luong","h6-nhien-lieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-dang-nang-luong","mon":"KHTN","khoi":"6","chu_de":"l6-nang-luong","thu_tu":2,"loai":"kn","ten":"Các dạng năng lượng","ten_khac":["cac dang nang luong","dang nang luong","phan loai nang luong","dong nang the nang","nang luong nhiet dien"],"noi_dung":"Năng lượng tồn tại ở nhiều dạng như động năng, thế năng, nhiệt, ánh sáng, âm, điện, hóa học.","cong_thuc":null,"y":["Nhận biết dạng năng lượng qua biểu hiện: chuyển động, được nâng cao, nóng, phát sáng, phát ra âm…","Một vật có thể có nhiều dạng năng lượng cùng lúc."],"bang":[["Dạng","Ví dụ"],["Động năng","ô tô đang chạy"],["Thế năng hấp dẫn","quả dừa trên cây"],["Thế năng đàn hồi","lò xo bị nén"],["Năng lượng nhiệt","nồi nước nóng"],["Năng lượng ánh sáng","ánh sáng Mặt Trời"],["Năng lượng âm","tiếng trống"],["Năng lượng điện","dòng điện chạy qua quạt"],["Năng lượng hóa học","thức ăn, pin, xăng"]],"bien":null,"vd":null,"nham":null,"lq":["l6-dong-nang","l6-the-nang-hap-dan","l6-nang-luong-nhiet","l6-nang-luong-hoa-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-dong-nang","mon":"KHTN","khoi":"6","chu_de":"l6-nang-luong","thu_tu":3,"loai":"kn","ten":"Động năng","ten_khac":["dong nang","nang luong chuyen dong","kinetic energy","wd","vat chuyen dong"],"noi_dung":"Năng lượng mà vật có do chuyển động.","cong_thuc":null,"y":["Vật chuyển động càng <b>nhanh</b> thì động năng càng lớn.","Ví dụ: gió làm quay cánh quạt, dòng nước chảy làm quay tua bin, quả bóng đang bay."],"bang":null,"bien":null,"vd":{"de":"Hai chiếc xe giống hệt nhau, một xe chạy chậm, một xe chạy nhanh hơn. Xe nào có động năng lớn hơn?","buoc":["Động năng là năng lượng vật có được do chuyển động.","Cùng khối lượng, xe chạy nhanh hơn thì chuyển động mạnh hơn."],"kq":"Xe chạy nhanh hơn có động năng lớn hơn."},"nham":null,"lq":["l6-the-nang-hap-dan","l6-dang-nang-luong","l6-chuyen-hoa-nang-luong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-the-nang-hap-dan","mon":"KHTN","khoi":"6","chu_de":"l6-nang-luong","thu_tu":4,"loai":"kn","ten":"Thế năng hấp dẫn","ten_khac":["the nang hap dan","the nang","the nang trong truong","do cao","potential energy","wt"],"noi_dung":"Năng lượng mà vật có do được đặt ở một độ cao so với mặt đất.","cong_thuc":null,"y":["Vật ở càng <b>cao</b> thì thế năng hấp dẫn càng lớn.","Ví dụ: nước trên hồ thủy điện, quả táo trên cành.","Khi vật rơi, thế năng hấp dẫn chuyển hóa dần thành động năng."],"bang":null,"bien":null,"vd":{"de":"Một quả dừa treo trên cây cao và một quả dừa khác nằm dưới đất. Quả nào có thế năng hấp dẫn lớn hơn?","buoc":["Thế năng hấp dẫn là năng lượng vật có do ở độ cao so với mặt đất.","Quả dừa trên cây ở độ cao lớn hơn quả nằm dưới đất."],"kq":"Quả dừa treo trên cây có thế năng hấp dẫn lớn hơn."},"nham":null,"lq":["l6-dong-nang","l6-the-nang-dan-hoi","l6-chuyen-hoa-nang-luong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-the-nang-dan-hoi","mon":"KHTN","khoi":"6","chu_de":"l6-nang-luong","thu_tu":5,"loai":"kn","ten":"Thế năng đàn hồi","ten_khac":["the nang dan hoi","dan hoi","lo xo bi nen","day cung","elastic energy"],"noi_dung":"Năng lượng mà vật có khi bị biến dạng đàn hồi (lò xo bị nén, dây cung bị kéo căng).","cong_thuc":null,"y":["Biến dạng càng lớn thì thế năng đàn hồi càng lớn.","Ví dụ: dây cung kéo căng bắn mũi tên đi, lò xo bị nén bật lên."],"bang":null,"bien":null,"vd":{"de":"Một dây cao su được kéo căng ra rồi giữ nguyên. Lúc này dây cao su có mang năng lượng không, thuộc dạng nào?","buoc":["Vật bị biến dạng đàn hồi (kéo căng, nén) sẽ dự trữ năng lượng.","Dây cao su bị kéo dãn là một biến dạng đàn hồi."],"kq":"Có; đó là thế năng đàn hồi."},"nham":null,"lq":["l6-bien-dang-lo-xo","l6-the-nang-hap-dan","l6-dang-nang-luong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-nang-luong-nhiet","mon":"KHTN","khoi":"6","chu_de":"l6-nang-luong","thu_tu":6,"loai":"kn","ten":"Năng lượng nhiệt","ten_khac":["nang luong nhiet","nhiet nang","nhiet","nong len","thermal energy"],"noi_dung":"Năng lượng có ở mọi vật; vật càng nóng thì năng lượng nhiệt càng lớn.","cong_thuc":null,"y":["Biểu hiện: vật nóng lên, làm nóng vật khác.","Ví dụ: bếp lửa, nước nóng, bàn là đang dùng.","Hầu hết quá trình chuyển hóa năng lượng đều sinh ra một phần năng lượng nhiệt."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l6-dang-nang-luong","l6-nang-luong-hao-phi","h6-nhien-lieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-nang-luong-am","mon":"KHTN","khoi":"6","chu_de":"l6-nang-luong","thu_tu":7,"loai":"kn","ten":"Năng lượng âm","ten_khac":["nang luong am","am nang","am thanh","sound energy","tieng dong"],"noi_dung":"Năng lượng do các vật phát ra âm mang theo.","cong_thuc":null,"y":["Ví dụ: tiếng trống, tiếng loa, tiếng sấm.","Âm to có thể làm rung cửa kính, chứng tỏ âm mang năng lượng."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l6-dang-nang-luong","l6-nang-luong-hao-phi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-nang-luong-dien","mon":"KHTN","khoi":"6","chu_de":"l6-nang-luong","thu_tu":8,"loai":"kn","ten":"Năng lượng điện","ten_khac":["nang luong dien","dien nang","dien","dong dien","electric energy"],"noi_dung":"Năng lượng của dòng điện, làm cho các thiết bị điện hoạt động.","cong_thuc":null,"y":["Dễ chuyển hóa thành các dạng khác: quạt (động năng), đèn (ánh sáng), bàn là (nhiệt), loa (âm).","Được sản xuất ở nhà máy điện (thủy điện, nhiệt điện, điện gió, điện mặt trời…)."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l6-dang-nang-luong","l6-chuyen-hoa-nang-luong","l6-tiet-kiem-nang-luong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-nang-luong-hoa-hoc","mon":"KHTN","khoi":"6","chu_de":"l6-nang-luong","thu_tu":9,"loai":"kn","ten":"Năng lượng hóa học","ten_khac":["nang luong hoa hoc","hoa nang","nang luong du tru","thuc an","pin","chemical energy"],"noi_dung":"Năng lượng dự trữ trong thức ăn, nhiên liệu, pin, được giải phóng khi xảy ra biến đổi hóa học.","cong_thuc":null,"y":["Thức ăn cung cấp năng lượng hóa học cho cơ thể hoạt động.","Đốt nhiên liệu giải phóng năng lượng hóa học thành năng lượng nhiệt, ánh sáng."],"bang":null,"bien":null,"vd":{"de":"Khi ăn cơm, cơ thể lấy năng lượng từ thức ăn để hoạt động. Năng lượng dự trữ trong thức ăn thuộc dạng nào?","buoc":["Năng lượng hóa học là năng lượng dự trữ trong thức ăn, nhiên liệu, pin.","Thức ăn được cơ thể biến đổi để giải phóng năng lượng này."],"kq":"Năng lượng hóa học."},"nham":null,"lq":["h6-nhien-lieu","l6-dang-nang-luong","l6-chuyen-hoa-nang-luong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-nang-luong-tai-tao","mon":"KHTN","khoi":"6","chu_de":"l6-nang-luong","thu_tu":10,"loai":"kn","ten":"Năng lượng tái tạo","ten_khac":["nang luong tai tao","tai tao","nang luong sach","dien gio","dien mat troi","nang luong xanh"],"noi_dung":"Năng lượng từ những nguồn có sẵn trong tự nhiên, được bổ sung liên tục, gần như không cạn kiệt.","cong_thuc":null,"y":["Nguồn: <b>Mặt Trời</b>, gió, nước (thủy triều, sông), địa nhiệt, sinh khối.","Ưu điểm: ít gây ô nhiễm môi trường.","Nhược điểm: phụ thuộc thời tiết, chi phí xây dựng ban đầu cao."],"bang":null,"bien":null,"vd":{"de":"Một ngôi nhà lắp tấm pin mặt trời để phát điện thay vì dùng máy phát chạy dầu diesel. Nguồn năng lượng của tấm pin thuộc loại nào?","buoc":["Năng lượng tái tạo là nguồn có sẵn trong tự nhiên, được bổ sung liên tục.","Ánh sáng Mặt Trời chiếu tới Trái Đất hằng ngày, gần như không cạn kiệt."],"kq":"Năng lượng tái tạo (năng lượng Mặt Trời)."},"nham":null,"lq":["l6-nang-luong-khong-tai-tao","l7-nang-luong-anh-sang","l6-tiet-kiem-nang-luong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-nang-luong-khong-tai-tao","mon":"KHTN","khoi":"6","chu_de":"l6-nang-luong","thu_tu":11,"loai":"kn","ten":"Năng lượng không tái tạo","ten_khac":["nang luong khong tai tao","khong tai tao","nhien lieu hoa thach","than da dau mo","can kiet"],"noi_dung":"Năng lượng từ những nguồn có hạn, cần hàng triệu năm để hình thành, sẽ cạn kiệt nếu khai thác mãi.","cong_thuc":null,"y":["Nguồn chính: than đá, dầu mỏ, khí tự nhiên (<b>nhiên liệu hóa thạch</b>).","Khi đốt tạo ra khí thải gây ô nhiễm không khí, làm Trái Đất nóng lên."],"bang":null,"bien":null,"vd":{"de":"Nhà máy nhiệt điện đốt than để phát điện. Nguồn năng lượng từ than đá thuộc loại tái tạo hay không tái tạo?","buoc":["Than đá cần hàng triệu năm hình thành từ xác sinh vật.","Nguồn năng lượng như vậy sẽ cạn kiệt nếu khai thác liên tục."],"kq":"Năng lượng không tái tạo."},"nham":null,"lq":["l6-nang-luong-tai-tao","h6-nhien-lieu","l6-tiet-kiem-nang-luong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-chuyen-hoa-nang-luong","mon":"KHTN","khoi":"6","chu_de":"l6-nang-luong","thu_tu":12,"loai":"ht","ten":"Chuyển hóa năng lượng","ten_khac":["chuyen hoa nang luong","su chuyen hoa","bien doi nang luong","dang nay sang dang khac","chuyen hoa"],"noi_dung":"Sự biến đổi năng lượng từ dạng này sang dạng khác.","cong_thuc":null,"y":["Quạt điện: điện năng → <b>động năng</b> (có ích) + nhiệt, âm (hao phí).","Bóng đèn: điện năng → ánh sáng + nhiệt.","Thủy điện: thế năng của nước → động năng → điện năng.","Trong mọi quá trình chuyển hóa, năng lượng được bảo toàn."],"bang":null,"bien":null,"vd":{"de":"Khi cắm quạt điện vào ổ điện và bật lên, quạt quay tạo ra gió. Năng lượng đã chuyển hóa như thế nào?","buoc":["Dòng điện mang năng lượng điện cung cấp cho quạt.","Động cơ quạt biến đổi năng lượng điện thành năng lượng làm cánh quạt quay."],"kq":"Năng lượng điện chuyển hóa thành động năng (và một phần thành nhiệt, âm)."},"nham":null,"lq":["l6-bao-toan-nang-luong","l6-nang-luong-hao-phi","l6-dang-nang-luong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-bao-toan-nang-luong","mon":"KHTN","khoi":"6","chu_de":"l6-nang-luong","thu_tu":13,"loai":"ct","ten":"Định luật bảo toàn năng lượng","ten_khac":["bao toan nang luong","dinh luat bao toan nang luong","khong tu sinh ra","khong tu mat di","bao toan"],"noi_dung":"Năng lượng không tự sinh ra hoặc tự mất đi, chỉ chuyển từ dạng này sang dạng khác hoặc truyền từ vật này sang vật khác.","cong_thuc":null,"y":["Tổng năng lượng trước và sau khi chuyển hóa là <b>bằng nhau</b>.","Năng lượng cung cấp = năng lượng có ích + năng lượng hao phí."],"bang":null,"bien":null,"vd":{"de":"Một bóng đèn nhận 100 J điện năng, phát ra 10 J năng lượng ánh sáng. Tính năng lượng nhiệt đèn tỏa ra.","buoc":["Theo bảo toàn năng lượng: 100 J = 10 J + năng lượng nhiệt","Năng lượng nhiệt = 100 − 10"],"kq":"90 J"},"nham":["Nghĩ năng lượng hao phí là \"biến mất\" (thật ra chuyển thành nhiệt, âm… tỏa ra môi trường)."],"lq":["l6-chuyen-hoa-nang-luong","l6-nang-luong-hao-phi","l6-nang-luong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-nang-luong-hao-phi","mon":"KHTN","khoi":"6","chu_de":"l6-nang-luong","thu_tu":14,"loai":"kn","ten":"Năng lượng hao phí","ten_khac":["nang luong hao phi","hao phi","nang luong co ich","co ich","lang phi nang luong","hieu qua"],"noi_dung":"Phần năng lượng không được sử dụng đúng mục đích, thường tỏa ra môi trường dưới dạng nhiệt hoặc âm.","cong_thuc":null,"y":["<b>Năng lượng có ích</b>: phần năng lượng dùng đúng mục đích (ánh sáng của đèn, động năng của quạt).","Năng lượng hao phí luôn xuất hiện trong mọi quá trình chuyển hóa.","Thiết bị càng ít hao phí thì càng <b>tiết kiệm</b> năng lượng; ví dụ đèn LED ít hao phí hơn đèn sợi đốt."],"bang":null,"bien":null,"vd":{"de":"Khi bật một bóng đèn sợi đốt, ngoài ánh sáng ta còn cảm nhận được bóng đèn rất nóng. Phần năng lượng tỏa nhiệt đó có phải năng lượng hao phí không?","buoc":["Mục đích dùng bóng đèn là để chiếu sáng.","Phần năng lượng tỏa ra dưới dạng nhiệt không phục vụ mục đích chiếu sáng."],"kq":"Có; phần nhiệt tỏa ra là năng lượng hao phí."},"nham":null,"lq":["l6-bao-toan-nang-luong","l6-chuyen-hoa-nang-luong","l6-tiet-kiem-nang-luong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-tiet-kiem-nang-luong","mon":"KHTN","khoi":"6","chu_de":"l6-nang-luong","thu_tu":15,"loai":"ud","ten":"Tiết kiệm năng lượng","ten_khac":["tiet kiem nang luong","tiet kiem dien","su dung hieu qua","bao ve moi truong","gio trai dat"],"noi_dung":"Sử dụng năng lượng hợp lí, đúng lúc, đúng mức cần để giảm lãng phí và bảo vệ môi trường.","cong_thuc":null,"y":["Tắt thiết bị điện khi không dùng; tận dụng ánh sáng tự nhiên.","Dùng thiết bị hiệu suất cao: đèn LED, thiết bị dán nhãn tiết kiệm năng lượng.","Đi bộ, đi xe đạp, dùng phương tiện công cộng để giảm tiêu thụ xăng dầu.","Ưu tiên nguồn <b>năng lượng tái tạo</b>."],"bang":null,"bien":null,"vd":{"de":"Ra khỏi phòng học nhưng vẫn để quạt và đèn bật. Việc làm này có tiết kiệm năng lượng không?","buoc":["Sử dụng năng lượng khi không cần thiết là lãng phí.","Tiết kiệm năng lượng là dùng đúng lúc, đúng mức cần thiết."],"kq":"Không tiết kiệm; nên tắt quạt và đèn khi ra khỏi phòng."},"nham":null,"lq":["l6-nang-luong-hao-phi","l6-nang-luong-tai-tao","l6-nang-luong-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-chuyen-dong-mat-troi","mon":"KHTN","khoi":"6","chu_de":"l6-bau-troi","thu_tu":1,"loai":"ht","ten":"Chuyển động nhìn thấy của Mặt Trời","ten_khac":["chuyen dong nhin thay cua mat troi","mat troi moc","mat troi lan","moc dong lan tay","trai dat tu quay","ngay dem"],"noi_dung":"Hằng ngày ta thấy Mặt Trời mọc ở phía Đông, lặn ở phía Tây, do Trái Đất tự quay quanh trục.","cong_thuc":null,"y":["Trái Đất tự quay quanh trục từ <b>Tây sang Đông</b> nên ta thấy Mặt Trời chuyển động từ Đông sang Tây.","Đây là chuyển động <b>nhìn thấy</b> (biểu kiến), không phải Mặt Trời quay quanh Trái Đất.","Trái Đất tự quay còn gây ra hiện tượng ngày và đêm luân phiên."],"bang":null,"bien":null,"vd":null,"nham":["Cho rằng Mặt Trời quay quanh Trái Đất."],"lq":["l6-mat-troi","l6-thien-the","l6-he-mat-troi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-thien-the","mon":"KHTN","khoi":"6","chu_de":"l6-bau-troi","thu_tu":2,"loai":"kn","ten":"Thiên thể","ten_khac":["thien the","vat the tren bau troi","thien van","vu tru","celestial body"],"noi_dung":"Tên gọi chung các vật thể tự nhiên trong vũ trụ như sao, hành tinh, vệ tinh, sao chổi.","cong_thuc":null,"y":["Mặt Trời, Mặt Trăng, Trái Đất đều là thiên thể.","Thiên thể có loại tự phát sáng (sao) và loại không tự phát sáng (hành tinh, vệ tinh)."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l6-sao","l6-hanh-tinh","l6-ve-tinh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-sao","mon":"KHTN","khoi":"6","chu_de":"l6-bau-troi","thu_tu":3,"loai":"kn","ten":"Sao","ten_khac":["sao","ngoi sao","ngoi sao tu phat sang","star","vi sao"],"noi_dung":"Thiên thể tự phát ra ánh sáng; Mặt Trời là ngôi sao gần Trái Đất nhất.","cong_thuc":null,"y":["Ban đêm nhìn thấy các sao như những chấm sáng lấp lánh vì chúng ở rất xa.","Các sao hợp thành những <b>thiên hà</b>; hệ Mặt Trời nằm trong Ngân Hà."],"bang":null,"bien":null,"vd":null,"nham":["Gọi hành tinh (sao Kim, sao Hỏa) là \"sao\" nên tưởng chúng tự phát sáng."],"lq":["l6-mat-troi","l6-ngan-ha","l6-chom-sao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-mat-troi","mon":"KHTN","khoi":"6","chu_de":"l6-bau-troi","thu_tu":4,"loai":"kn","ten":"Mặt Trời","ten_khac":["mat troi","sun","ong mat troi","ngoi sao gan nhat","thai duong"],"noi_dung":"Ngôi sao ở trung tâm hệ Mặt Trời, tự phát sáng và cung cấp ánh sáng, nhiệt cho Trái Đất.","cong_thuc":null,"y":["Là <b>ngôi sao</b> duy nhất trong hệ Mặt Trời.","Là nguồn năng lượng chính cho sự sống trên Trái Đất.","Khoảng cách từ Trái Đất đến Mặt Trời khoảng <b>150 triệu km</b> (1 AU)."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l6-he-mat-troi","l6-chuyen-dong-mat-troi","l6-sao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-mat-trang","mon":"KHTN","khoi":"6","chu_de":"l6-bau-troi","thu_tu":5,"loai":"kn","ten":"Mặt Trăng","ten_khac":["mat trang","moon","ve tinh trai dat","ong trang","trang"],"noi_dung":"Vệ tinh tự nhiên của Trái Đất, không tự phát sáng mà hắt lại ánh sáng Mặt Trời.","cong_thuc":null,"y":["Mặt Trăng chuyển động quanh Trái Đất.","Ta nhìn thấy Mặt Trăng vì nó <b>phản chiếu ánh sáng Mặt Trời</b> tới mắt.","Phần được chiếu sáng mà ta nhìn thấy thay đổi theo ngày, tạo nên các <b>pha Mặt Trăng</b>."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ Mặt Trăng tự phát sáng."],"lq":["l6-pha-mat-trang","l6-ve-tinh","l6-luc-hap-dan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-pha-mat-trang","mon":"KHTN","khoi":"6","chu_de":"l6-bau-troi","thu_tu":6,"loai":"ht","ten":"Pha của Mặt Trăng","ten_khac":["pha mat trang","tuan trang","trang tron","trang khuyet","trang luoi liem","trang ban nguyet","trang moi","hinh dang mat trang"],"noi_dung":"Các hình dạng nhìn thấy khác nhau của Mặt Trăng, lặp lại theo chu kì khoảng 29,5 ngày.","cong_thuc":null,"y":["Nguyên nhân: Mặt Trăng quay quanh Trái Đất nên phần được Mặt Trời chiếu sáng mà ta thấy thay đổi.","Trăng tròn vào khoảng giữa tháng âm lịch (ngày 14, 15, 16).","Đầu tháng âm lịch không nhìn thấy trăng (<b>trăng mới</b>)."],"bang":[["Thứ tự","Pha"],["1","Trăng mới (không trăng)"],["2","Trăng lưỡi liềm đầu tháng"],["3","Trăng bán nguyệt đầu tháng"],["4","Trăng khuyết đầu tháng"],["5","Trăng tròn"],["6","Trăng khuyết cuối tháng"],["7","Trăng bán nguyệt cuối tháng"],["8","Trăng lưỡi liềm cuối tháng"]],"bien":null,"vd":{"de":"Một đêm, người quan sát thấy Mặt Trăng có hình dạng tròn sáng hoàn toàn. Đây là pha nào của Mặt Trăng?","buoc":["Các pha lặp lại theo chu kì khoảng 29,5 ngày: không trăng, trăng lưỡi liềm, bán nguyệt, tròn.","Hình tròn sáng hoàn toàn ứng với pha nhìn thấy toàn bộ mặt được chiếu sáng."],"kq":"Đó là pha Trăng tròn (Rằm)."},"nham":["Cho rằng trăng khuyết vì bóng Trái Đất che (đó là nguyệt thực, không phải pha trăng)."],"lq":["l6-mat-trang","l6-mat-troi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-hanh-tinh","mon":"KHTN","khoi":"6","chu_de":"l6-bau-troi","thu_tu":7,"loai":"kn","ten":"Hành tinh","ten_khac":["hanh tinh","planet","sao thuy sao kim","sao hoa","sao moc","8 hanh tinh","tam hanh tinh"],"noi_dung":"Thiên thể chuyển động quanh một ngôi sao, không tự phát sáng; Trái Đất là một hành tinh.","cong_thuc":null,"y":["Hệ Mặt Trời có <b>8 hành tinh</b> quay quanh Mặt Trời.","Hành tinh nhìn thấy được vì phản chiếu ánh sáng Mặt Trời.","Sao Kim (sao Mai, sao Hôm) là hành tinh sáng nhất trên bầu trời."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l6-he-mat-troi","l6-ve-tinh","l6-sao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-ve-tinh","mon":"KHTN","khoi":"6","chu_de":"l6-bau-troi","thu_tu":8,"loai":"kn","ten":"Vệ tinh","ten_khac":["ve tinh","ve tinh tu nhien","ve tinh nhan tao","satellite","quay quanh hanh tinh"],"noi_dung":"Thiên thể chuyển động quanh một hành tinh; Mặt Trăng là vệ tinh tự nhiên của Trái Đất.","cong_thuc":null,"y":["Vệ tinh không tự phát sáng.","Con người còn phóng các <b>vệ tinh nhân tạo</b> quay quanh Trái Đất để phục vụ thông tin, dự báo thời tiết."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l6-mat-trang","l6-hanh-tinh","l6-thien-the"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-he-mat-troi","mon":"KHTN","khoi":"6","chu_de":"l6-bau-troi","thu_tu":9,"loai":"cq","ten":"Hệ Mặt Trời","ten_khac":["he mat troi","thai duong he","solar system","8 hanh tinh","thu tu hanh tinh","hmt"],"noi_dung":"Hệ gồm Mặt Trời ở trung tâm và các thiên thể chuyển động quanh nó: 8 hành tinh, vệ tinh, tiểu hành tinh, sao chổi…","cong_thuc":null,"y":["Thứ tự từ gần đến xa Mặt Trời: <b>Thủy, Kim, Trái Đất, Hỏa, Mộc, Thổ, Thiên Vương, Hải Vương</b>.","Hành tinh càng xa Mặt Trời thì quay một vòng quanh Mặt Trời càng lâu.","Sao Mộc là hành tinh lớn nhất; Trái Đất là hành tinh thứ 3."],"bang":[["Hành tinh","Khoảng cách đến Mặt Trời (AU)"],["Thủy","0,39"],["Kim","0,72"],["Trái Đất","1"],["Hỏa","1,52"],["Mộc","5,2"],["Thổ","9,54"],["Thiên Vương","19,2"],["Hải Vương","30,1"]],"bien":null,"vd":{"de":"Trong hệ Mặt Trời, Sao Kim gần Mặt Trời hơn Trái Đất, còn Sao Hỏa xa Mặt Trời hơn Trái Đất. Sắp xếp ba hành tinh này theo thứ tự xa dần Mặt Trời.","buoc":["Hệ Mặt Trời gồm Mặt Trời ở trung tâm và các hành tinh chuyển động quanh nó.","So sánh khoảng cách: Sao Kim gần nhất, rồi đến Trái Đất, rồi đến Sao Hỏa."],"kq":"Thứ tự xa dần Mặt Trời: Sao Kim, Trái Đất, Sao Hỏa."},"nham":["Kể Mặt Trăng là một hành tinh của hệ Mặt Trời."],"lq":["l6-hanh-tinh","l6-mat-troi","l6-don-vi-thien-van","l6-ngan-ha"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-don-vi-thien-van","mon":"KHTN","khoi":"6","chu_de":"l6-bau-troi","thu_tu":10,"loai":"dl","ten":"Đơn vị thiên văn (AU)","ten_khac":["don vi thien van","au","khoang cach thien van","150 trieu km","astronomical unit","dvtv"],"noi_dung":"Đơn vị đo khoảng cách trong hệ Mặt Trời, bằng khoảng cách trung bình từ Trái Đất đến Mặt Trời.","cong_thuc":null,"y":["<b>1 AU ≈ 150 triệu km</b>.","Ví dụ: sao Mộc cách Mặt Trời khoảng 5,2 AU, tức khoảng 780 triệu km."],"bang":null,"bien":null,"vd":{"de":"Khoảng cách từ Sao Hỏa đến Mặt Trời khoảng 1,5 AU. Đổi ra kilômét, biết 1 AU ≈ 150 000 000 km.","buoc":["1 AU ≈ 150 000 000 km.","1,5 AU = 1,5 · 150 000 000 km"],"kq":"≈ 225 000 000 km (225 triệu km)"},"nham":null,"lq":["l6-he-mat-troi","l6-mat-troi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-thien-ha","mon":"KHTN","khoi":"6","chu_de":"l6-bau-troi","thu_tu":11,"loai":"kn","ten":"Thiên hà","ten_khac":["thien ha","galaxy","tap hop sao","thien ha tien nu","vu tru"],"noi_dung":"Tập hợp rất nhiều sao cùng bụi, khí và các thiên thể khác, liên kết với nhau bởi lực hấp dẫn.","cong_thuc":null,"y":["Vũ trụ có vô số thiên hà.","Hệ Mặt Trời nằm trong một thiên hà tên là <b>Ngân Hà</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l6-ngan-ha","l6-sao","l6-luc-hap-dan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-ngan-ha","mon":"KHTN","khoi":"6","chu_de":"l6-bau-troi","thu_tu":12,"loai":"kn","ten":"Ngân Hà","ten_khac":["ngan ha","dai ngan ha","milky way","song ngan","thien ha cua chung ta"],"noi_dung":"Thiên hà chứa hệ Mặt Trời, gồm hàng trăm tỉ ngôi sao.","cong_thuc":null,"y":["Đêm trời quang, không trăng, ta thấy Ngân Hà như một <b>dải sáng mờ</b> vắt ngang bầu trời.","Hệ Mặt Trời nằm ở phía rìa, không nằm ở trung tâm Ngân Hà.","Dân gian gọi là \"sông Ngân\"."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm Ngân Hà với hệ Mặt Trời."],"lq":["l6-thien-ha","l6-he-mat-troi","l6-sao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-chom-sao","mon":"KHTN","khoi":"6","chu_de":"l6-bau-troi","thu_tu":13,"loai":"kn","ten":"Chòm sao","ten_khac":["chom sao","dai hung","gau lon","bac dau","sao bac cuc","constellation"],"noi_dung":"Nhóm các ngôi sao nhìn thấy gần nhau trên bầu trời, tạo thành hình dạng nhất định (mở rộng).","cong_thuc":null,"y":["Ví dụ: chòm Gấu Lớn (Đại Hùng), chòm Gấu Nhỏ (Tiểu Hùng), chòm Thiên Hậu, chòm Lạp Hộ.","<b>Sao Bắc Cực</b> thuộc chòm Gấu Nhỏ, dùng để xác định hướng Bắc.","Các sao trong một chòm chỉ trông gần nhau, thực tế có thể ở rất xa nhau."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l6-sao","l6-ngan-ha"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-toc-do","mon":"KHTN","khoi":"7","chu_de":"l7-toc-do","thu_tu":1,"loai":"dl","ten":"Tốc độ","ten_khac":["toc do","van toc","v","s/t","v = s/t","speed","nhanh cham","toc do chuyen dong"],"noi_dung":"Đại lượng cho biết mức độ nhanh hay chậm của chuyển động, bằng quãng đường vật đi được trong một đơn vị thời gian.","cong_thuc":"v = s/t; s = v·t; t = s/v","y":["Cùng thời gian, vật đi được quãng đường <b>dài hơn</b> thì nhanh hơn.","Cùng quãng đường, vật đi hết <b>ít thời gian hơn</b> thì nhanh hơn.","Biết 2 trong 3 đại lượng v, s, t thì tính được đại lượng còn lại.","Trước khi tính, đưa s và t về cùng hệ đơn vị."],"bang":null,"bien":[["v","tốc độ","m/s hoặc km/h"],["s","quãng đường đi được","m hoặc km"],["t","thời gian đi hết quãng đường","s hoặc h"]],"vd":{"de":"Một bạn đạp xe được 3 600 m trong 20 phút. Tính tốc độ của bạn ra m/s.","buoc":["Đổi t = 20 phút = 1 200 s.","v = s/t = 3 600 : 1 200"],"kq":"v = 3 m/s (= 10,8 km/h)"},"nham":["Nhân s với t thay vì chia khi tính tốc độ.","Để s tính bằng km mà t tính bằng giây rồi chia luôn."],"lq":["l7-don-vi-toc-do","l7-do-toc-do","l7-toc-do-ca-quang-duong","l7-do-thi-s-t"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-don-vi-toc-do","mon":"KHTN","khoi":"7","chu_de":"l7-toc-do","thu_tu":2,"loai":"dl","ten":"Đơn vị tốc độ","ten_khac":["don vi toc do","m/s","km/h","met tren giay","kilomet tren gio","doi don vi","3,6","doi km/h sang m/s"],"noi_dung":"Đơn vị tốc độ phụ thuộc đơn vị quãng đường và thời gian; thường dùng m/s và km/h, với 1 m/s = 3,6 km/h.","cong_thuc":"1 m/s = 3,6 km/h","y":["Quãng đường đo bằng m, thời gian bằng s → tốc độ tính bằng <b>m/s</b>.","Quãng đường đo bằng km, thời gian bằng h → tốc độ tính bằng <b>km/h</b>.","Đổi m/s sang km/h: <b>nhân 3,6</b>. Đổi km/h sang m/s: <b>chia 3,6</b>."],"bang":[["Quãng đường","Thời gian","Đơn vị tốc độ"],["m","s","m/s"],["km","h","km/h"]],"bien":[["m/s","mét trên giây","đơn vị SI"],["km/h","kilômét trên giờ","hay dùng cho xe cộ"]],"vd":{"de":"Đổi 54 km/h ra m/s.","buoc":["54 : 3,6"],"kq":"15 m/s"},"nham":["Đổi sai chiều: 36 km/h = 10 m/s (chia 3,6), không phải 129,6 m/s.","15 phút = 0,15 h → SAI: 15 phút = 0,25 h."],"lq":["l7-toc-do","l7-toc-do-ca-quang-duong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-toc-do-ca-quang-duong","mon":"KHTN","khoi":"7","chu_de":"l7-toc-do","thu_tu":3,"loai":"ct","ten":"Tốc độ trên cả quãng đường","ten_khac":["toc do ca quang duong","nhieu doan duong","toc do trung binh","tong quang duong chia tong thoi gian","hai doan","vtb"],"noi_dung":"Khi quãng đường gồm nhiều đoạn, tốc độ trên cả quãng đường bằng tổng quãng đường chia cho tổng thời gian.","cong_thuc":"v = (s₁ + s₂)/(t₁ + t₂)","y":["Cộng tất cả quãng đường, cộng tất cả thời gian (kể cả thời gian dừng nghỉ nếu đề tính vào), rồi chia.","<b>Không</b> lấy trung bình cộng các tốc độ."],"bang":null,"bien":[["s₁, s₂","quãng đường từng đoạn","km hoặc m"],["t₁, t₂","thời gian đi từng đoạn","h hoặc s"],["v","tốc độ trên cả quãng đường","km/h hoặc m/s"]],"vd":{"de":"Xe đi 10 km đầu hết 0,5 h, 20 km sau hết 2 h. Tính tốc độ trên cả quãng đường.","buoc":["Tổng quãng đường: 10 + 20 = 30 km.","Tổng thời gian: 0,5 + 2 = 2,5 h.","v = 30 : 2,5"],"kq":"v = 12 km/h (không phải (20 + 10) : 2 = 15 km/h)"},"nham":["Lấy trung bình cộng hai tốc độ → SAI."],"lq":["l7-toc-do","l7-don-vi-toc-do","l7-doc-do-thi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-do-toc-do","mon":"KHTN","khoi":"7","chu_de":"l7-toc-do","thu_tu":4,"loai":"tn","ten":"Đo tốc độ","ten_khac":["do toc do","cach do toc do","dung cu do toc do","thiet bi ban toc do","sung ban toc do","camera toc do","toc ke"],"noi_dung":"Đo quãng đường s bằng thước, đo thời gian t bằng đồng hồ rồi tính v = s/t; cũng có thiết bị đo trực tiếp tốc độ.","cong_thuc":null,"y":["Dụng cụ đo thời gian: <b>đồng hồ bấm giây</b> hoặc <b>đồng hồ đo thời gian hiện số</b> nối với cổng quang điện.","Nên đo nhiều lần rồi lấy giá trị trung bình.","Cảnh sát giao thông dùng <b>thiết bị bắn tốc độ</b>, camera để đo tốc độ xe.","Tốc kế trên xe máy, ô tô cho biết tốc độ xe tại mỗi lúc."],"bang":[["Cách đo","Đặc điểm"],["Thước + đồng hồ bấm giây","Đơn giản, sai số do người bấm"],["Thước + đồng hồ hiện số, cổng quang điện","Tự bật, tắt, chính xác hơn"],["Thiết bị bắn tốc độ","Đo trực tiếp tốc độ xe"]],"bien":null,"vd":{"de":"Một bạn đo được quãng đường 15 m trong thời gian 3 s bằng thước và đồng hồ bấm giây. Tính tốc độ chuyển động.","buoc":["Đo s bằng thước, đo t bằng đồng hồ bấm giây.","v = s/t = 15 : 3"],"kq":"v = 5 m/s"},"nham":null,"lq":["l7-dong-ho-bam-giay","l7-cong-quang-dien","l7-toc-do"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-dong-ho-bam-giay","mon":"KHTN","khoi":"7","chu_de":"l7-toc-do","thu_tu":5,"loai":"tn","ten":"Đồng hồ bấm giây","ten_khac":["dong ho bam giay","bam giay","dong ho bam gio","stopwatch","do thoi gian"],"noi_dung":"Dụng cụ đo thời gian bằng cách bấm tay lúc vật bắt đầu và lúc vật kết thúc chuyển động.","cong_thuc":null,"y":["Bấm nút <b>bắt đầu</b> khi vật xuất phát, bấm <b>dừng</b> khi vật tới đích, đọc thời gian.","Trước mỗi lần đo phải đưa đồng hồ về số 0.","Sai số lớn vì phụ thuộc <b>phản xạ</b> (thời gian phản ứng) của người bấm."],"bang":null,"bien":null,"vd":{"de":"Một bạn bấm đồng hồ trễ khoảng 0,5 giây so với lúc vật bắt đầu chuyển động. Kết quả đo thời gian bị ảnh hưởng thế nào?","buoc":["Bấm trễ làm thời gian đo được ngắn hơn thời gian thực tế.","Đây là một nguồn sai số khi đo thời gian bằng đồng hồ bấm giây."],"kq":"Thời gian đo được nhỏ hơn thời gian thực, kết quả tốc độ tính ra sẽ bị sai."},"nham":["Quên đưa đồng hồ về 0 trước khi đo lần mới."],"lq":["l7-do-toc-do","l7-cong-quang-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-cong-quang-dien","mon":"KHTN","khoi":"7","chu_de":"l7-toc-do","thu_tu":6,"loai":"tn","ten":"Cổng quang điện","ten_khac":["cong quang dien","dong ho hien so","dong ho do thoi gian hien so","photogate","cong quang","may do thoi gian"],"noi_dung":"Bộ phận nối với đồng hồ đo thời gian hiện số, tự bật hoặc tắt đồng hồ khi vật chắn tia sáng đi qua cổng.","cong_thuc":null,"y":["Mỗi cổng có một bộ phát và một bộ thu tia sáng; vật đi qua làm tia sáng bị chắn.","Vật qua cổng thứ nhất: đồng hồ bắt đầu đếm; qua cổng thứ hai: đồng hồ dừng.","Thời gian đo được là thời gian vật đi từ cổng 1 đến cổng 2; quãng đường là khoảng cách hai cổng.","Chính xác hơn đồng hồ bấm tay."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l7-dong-ho-bam-giay","l7-do-toc-do"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-do-thi-s-t","mon":"KHTN","khoi":"7","chu_de":"l7-toc-do","thu_tu":7,"loai":"kn","ten":"Đồ thị quãng đường – thời gian","ten_khac":["do thi quang duong thoi gian","do thi s-t","do thi s t","do thi st","ve do thi","do thi chuyen dong"],"noi_dung":"Đồ thị biểu diễn quãng đường vật đi được theo thời gian: trục ngang là thời gian t, trục đứng là quãng đường s.","cong_thuc":null,"y":["Vẽ: lập bảng (t, s) → vẽ hai trục có đơn vị, chọn tỉ lệ → chấm các điểm → nối lại.","Vật có tốc độ không đổi: đồ thị là <b>đoạn thẳng nghiêng</b>.","Đồ thị không phải hình dạng con đường vật đi."],"bang":[["t (h)","0","1","2","3"],["s (km)","0","20","40","60"]],"bien":null,"vd":{"de":"Đồ thị quãng đường – thời gian của một xe là đường thẳng qua gốc tọa độ, đi qua điểm t = 4 s, s = 40 m. Tính tốc độ của xe từ đồ thị.","buoc":["Chọn hai điểm trên đồ thị: (0 s, 0 m) và (4 s, 40 m).","v = Δs/Δt = 40 : 4"],"kq":"v = 10 m/s"},"nham":["Đảo trục: đặt t ở trục đứng, s ở trục ngang."],"lq":["l7-doc-do-thi","l7-toc-do"],"hinh":"H-l7-do-thi-s-t","nguon":["KHTN Pocket"]},{"ma":"l7-doc-do-thi","mon":"KHTN","khoi":"7","chu_de":"l7-toc-do","thu_tu":8,"loai":"tn","ten":"Đọc đồ thị s–t","ten_khac":["doc do thi","doan nam ngang","dung yen","do doc","so sanh toc do tren do thi","tinh toc do tu do thi"],"noi_dung":"Từ đồ thị s–t, tìm được quãng đường, thời gian, tốc độ và biết lúc nào vật đứng yên hay nhanh hơn.","cong_thuc":null,"y":["Đoạn <b>nghiêng</b>: vật chuyển động. Đoạn <b>nằm ngang</b>: s không đổi → vật <b>đứng yên</b>.","Tốc độ một đoạn = quãng đường đi thêm : thời gian của đoạn đó.","Hai đường trên cùng đồ thị: đường nào <b>dốc hơn</b> thì vật đó nhanh hơn."],"bang":null,"bien":null,"vd":{"de":"Dựa vào đồ thị, tính tốc độ của xe từ 2 h đến 3 h.","buoc":["Quãng đường đi thêm: 100 − 40 = 60 km.","Thời gian: 3 − 2 = 1 h.","v = 60 : 1"],"kq":"v = 60 km/h (từ 1 h đến 2 h xe đứng yên)"},"nham":["Đoạn nằm ngang là xe chạy đều → SAI: xe đứng yên.","Lấy s đọc tại điểm cuối chia cho t tại điểm cuối để tính tốc độ đoạn sau → SAI."],"lq":["l7-do-thi-s-t","l7-toc-do","l7-toc-do-ca-quang-duong"],"hinh":"H-l7-doc-do-thi","nguon":["KHTN Pocket"]},{"ma":"l7-toc-do-an-toan","mon":"KHTN","khoi":"7","chu_de":"l7-toc-do","thu_tu":9,"loai":"ud","ten":"Tốc độ và an toàn giao thông","ten_khac":["toc do an toan giao thong","toc do toi da","bien bao toc do","bien bao","vuot qua toc do","tai nan giao thong","chay qua toc do"],"noi_dung":"Tốc độ càng lớn thì xe càng khó dừng và va chạm càng nguy hiểm, nên luật quy định tốc độ tối đa.","cong_thuc":null,"y":["Luật giao thông quy định <b>tốc độ tối đa</b> cho từng loại xe, từng loại đường.","Biển báo tốc độ tối đa: hình tròn, <b>viền đỏ</b>, nền trắng, số màu đen (km/h).","Giảm tốc độ khi trời mưa, đường trơn, qua trường học, khu đông dân cư."],"bang":null,"bien":null,"vd":{"de":"Trong khu vực đông dân cư, biển báo quy định tốc độ tối đa 40 km/h thay vì 80 km/h như trên đường cao tốc. Vì sao?","buoc":["Tốc độ càng lớn thì xe càng khó dừng kịp khi có tình huống bất ngờ.","Khu đông dân cư có nhiều người đi bộ, xe cộ qua lại nên cần tốc độ thấp để an toàn."],"kq":"Giảm tốc độ tối đa giúp xe dừng kịp, giảm nguy cơ tai nạn."},"nham":["Biển ghi 50 là phải chạy đúng 50 km/h → SAI: không được vượt quá 50 km/h."],"lq":["l7-khoang-cach-an-toan","l7-thoi-gian-phan-ung","l7-do-toc-do"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-khoang-cach-an-toan","mon":"KHTN","khoi":"7","chu_de":"l7-toc-do","thu_tu":10,"loai":"ud","ten":"Khoảng cách an toàn","ten_khac":["khoang cach an toan","khoang cach toi thieu","giu khoang cach","cach xe truoc","khoang cach giua hai xe"],"noi_dung":"Khoảng cách tối thiểu người lái phải giữ với xe phía trước; tốc độ càng lớn thì khoảng cách này càng lớn.","cong_thuc":null,"y":["Giữ khoảng cách để kịp phanh khi xe trước dừng đột ngột.","Bảng dưới là khoảng cách tối thiểu theo quy định của Bộ Giao thông vận tải, khi mặt đường khô ráo.","Trời mưa, sương mù, đường trơn, đèo dốc: phải giữ khoảng cách <b>lớn hơn</b>."],"bang":[["Tốc độ (km/h)","Khoảng cách tối thiểu (m)"],["60","35"],["Trên 60 đến 80","55"],["Trên 80 đến 100","70"],["Trên 100 đến 120","100"]],"bien":null,"vd":{"de":"Khi lái xe với tốc độ cao trên đường cao tốc, người lái cần giữ khoảng cách với xe phía trước lớn hơn hay nhỏ hơn so với khi đi chậm trong phố?","buoc":["Tốc độ càng lớn thì quãng đường xe đi được trong thời gian phản ứng và hãm phanh càng dài.","Khoảng cách an toàn phải đủ để xe kịp dừng khi xe trước phanh gấp."],"kq":"Cần giữ khoảng cách lớn hơn khi đi tốc độ cao."},"nham":["Mọi tốc độ đều cách xe trước như nhau → SAI."],"lq":["l7-toc-do-an-toan","l7-thoi-gian-phan-ung"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-thoi-gian-phan-ung","mon":"KHTN","khoi":"7","chu_de":"l7-toc-do","thu_tu":11,"loai":"kn","ten":"Thời gian phản ứng","ten_khac":["thoi gian phan ung","phan xa nguoi lai","quang duong phan ung","dap phanh","phanh xe"],"noi_dung":"Khoảng thời gian từ lúc người lái thấy nguy hiểm đến lúc bắt đầu đạp phanh; trong lúc đó xe vẫn chạy với tốc độ cũ.","cong_thuc":null,"y":["Quãng đường xe đi trong thời gian phản ứng: <b>s = v·t</b>.","Sau khi phanh, xe còn trượt thêm một đoạn mới dừng hẳn.","Mệt mỏi, uống rượu bia, dùng điện thoại làm thời gian phản ứng <b>dài hơn</b>."],"bang":null,"bien":null,"vd":{"de":"Ô tô chạy 72 km/h, thời gian phản ứng của người lái là 0,8 s. Trong thời gian đó xe đi được bao xa?","buoc":["Đổi v = 72 : 3,6 = 20 m/s.","s = v·t = 20 · 0,8"],"kq":"s = 16 m"},"nham":["Nhân km/h với giây → phải đổi tốc độ sang m/s trước."],"lq":["l7-khoang-cach-an-toan","l7-toc-do-an-toan","l7-toc-do"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-dao-dong","mon":"KHTN","khoi":"7","chu_de":"l7-am-thanh","thu_tu":1,"loai":"kn","ten":"Dao động","ten_khac":["dao dong","rung","chuyen dong qua lai","vi tri can bang","vat dao dong"],"noi_dung":"Chuyển động qua lại quanh một vị trí cân bằng, như dây đàn rung, mặt trống rung, con lắc đưa qua đưa lại.","cong_thuc":null,"y":["Mọi nguồn âm khi phát ra âm đều <b>dao động</b>.","Số dao động trong 1 giây là <b>tần số</b>; độ lệch lớn nhất khỏi vị trí cân bằng là <b>biên độ</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l7-nguon-am","l7-tan-so","l7-bien-do"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-nguon-am","mon":"KHTN","khoi":"7","chu_de":"l7-am-thanh","thu_tu":2,"loai":"kn","ten":"Nguồn âm","ten_khac":["nguon am","vat phat ra am","phat am","day thanh quan","nhac cu","am thoa"],"noi_dung":"Vật phát ra âm gọi là nguồn âm; mọi nguồn âm khi phát ra âm đều dao động.","cong_thuc":null,"y":["Ví dụ: dây đàn, mặt trống, âm thoa, cột không khí trong ống sáo, <b>dây thanh quản</b> của người.","Vật ngừng dao động thì ngừng phát ra âm."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ tai là nguồn âm → SAI: tai là nơi nhận âm."],"lq":["l7-dao-dong","l7-song-am"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-song-am","mon":"KHTN","khoi":"7","chu_de":"l7-am-thanh","thu_tu":3,"loai":"kn","ten":"Sóng âm","ten_khac":["song am","song","am truyen","nen dan","lop khong khi","truyen am","am thanh"],"noi_dung":"Dao động của nguồn âm lan truyền trong môi trường (rắn, lỏng, khí) tạo thành sóng âm.","cong_thuc":null,"y":["Trong không khí, sóng âm là các lớp không khí bị <b>nén, dãn</b> liên tiếp.","Sóng âm truyền dao động đi, <b>không</b> mang các phần tử môi trường đi theo.","Sóng âm truyền tới tai làm màng nhĩ dao động → ta nghe thấy âm."],"bang":null,"bien":null,"vd":null,"nham":["Sóng âm mang không khí từ nguồn âm tới tai → SAI: các lớp không khí chỉ dao động tại chỗ."],"lq":["l7-nguon-am","l7-moi-truong-truyen-am","l7-toc-do-truyen-am"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-moi-truong-truyen-am","mon":"KHTN","khoi":"7","chu_de":"l7-am-thanh","thu_tu":4,"loai":"kn","ten":"Môi trường truyền âm","ten_khac":["moi truong truyen am","chan khong","am truyen trong chat ran","am truyen trong nuoc","am truyen trong khong khi","ran long khi"],"noi_dung":"Âm truyền được trong chất rắn, lỏng, khí; âm không truyền được trong chân không.","cong_thuc":null,"y":["Áp tai xuống bàn nghe rõ tiếng gõ: âm truyền qua <b>chất rắn</b>.","Cá nghe được tiếng động trên bờ: âm truyền qua <b>chất lỏng</b>.","Trên Mặt Trăng (chân không), nhà du hành phải nói chuyện qua bộ đàm."],"bang":null,"bien":null,"vd":{"de":"Trong phim khoa học viễn tưởng, hai phi thuyền ngoài không gian bắn nhau và khán giả nghe thấy tiếng nổ lớn. Điều này có đúng với thực tế không?","buoc":["Âm cần môi trường vật chất (rắn, lỏng, khí) để truyền đi.","Ngoài không gian là chân không, không có môi trường truyền âm."],"kq":"Không đúng thực tế; trong chân không sẽ không nghe được tiếng nổ."},"nham":["Âm truyền được trong chân không → SAI."],"lq":["l7-song-am","l7-toc-do-truyen-am"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-toc-do-truyen-am","mon":"KHTN","khoi":"7","chu_de":"l7-am-thanh","thu_tu":5,"loai":"dl","ten":"Tốc độ truyền âm","ten_khac":["toc do truyen am","toc do am","340 m/s","am truyen nhanh","tieng sam","tia chop"],"noi_dung":"Quãng đường âm truyền được trong 1 giây; lớn nhất trong chất rắn, rồi đến chất lỏng, nhỏ nhất trong chất khí.","cong_thuc":"s = v·t","y":["Số liệu trong bảng là gần đúng; khi làm bài, đề sẽ cho tốc độ âm.","Thấy chớp rồi mới nghe sấm vì ánh sáng truyền nhanh hơn âm rất nhiều."],"bang":[["Môi trường","Tốc độ âm (gần đúng)"],["Không khí","khoảng 340 m/s"],["Nước","khoảng 1 500 m/s"],["Thép","khoảng 6 000 m/s"]],"bien":[["s","quãng đường âm truyền","m"],["v","tốc độ truyền âm","m/s"],["t","thời gian âm truyền","s"]],"vd":{"de":"Thấy tia chớp, 3 s sau mới nghe tiếng sấm. Tốc độ âm trong không khí là 340 m/s. Chỗ sét đánh cách người đó bao xa?","buoc":["s = v·t = 340 · 3"],"kq":"s = 1 020 m"},"nham":["Âm truyền nhanh nhất trong không khí → SAI: nhanh nhất trong chất rắn."],"lq":["l7-moi-truong-truyen-am","l7-song-am","l7-toc-do"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-tan-so","mon":"KHTN","khoi":"7","chu_de":"l7-am-thanh","thu_tu":6,"loai":"dl","ten":"Tần số","ten_khac":["tan so","f","f = n/t","so dao dong trong 1 giay","frequency","hz"],"noi_dung":"Số dao động vật thực hiện được trong 1 giây; đơn vị là hertz (Hz).","cong_thuc":"f = N/t","y":["Tần số càng lớn thì âm càng <b>cao</b> (bổng); càng nhỏ thì âm càng <b>thấp</b> (trầm).","Tai người nghe được âm có tần số từ 20 Hz đến 20 000 Hz."],"bang":null,"bien":[["f","tần số","Hz"],["N","số dao động","—"],["t","thời gian thực hiện N dao động","s"]],"vd":{"de":"Trong 0,5 phút, cánh một con côn trùng thực hiện 9 000 dao động. Tính tần số.","buoc":["Đổi t = 0,5 phút = 30 s.","f = N/t = 9 000 : 30"],"kq":"f = 300 Hz"},"nham":["Quên đổi phút ra giây trước khi tính f."],"lq":["l7-hertz","l7-do-cao-cua-am","l7-dao-dong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-hertz","mon":"KHTN","khoi":"7","chu_de":"l7-am-thanh","thu_tu":7,"loai":"dl","ten":"Hertz (Hz)","ten_khac":["hertz","hz","hec","don vi tan so","khz"],"noi_dung":"Đơn vị đo tần số: 1 Hz là 1 dao động trong 1 giây.","cong_thuc":null,"y":["Vật dao động 100 lần trong 1 giây có tần số <b>100 Hz</b>.","1 kHz = 1 000 Hz."],"bang":null,"bien":null,"vd":{"de":"Một con lắc dao động với tần số 5 Hz. Trong 10 giây, con lắc thực hiện bao nhiêu dao động?","buoc":["1 Hz là 1 dao động trong 1 giây.","Số dao động = f · t = 5 · 10"],"kq":"50 dao động"},"nham":["Viết hz, HZ → đúng là <b>Hz</b>."],"lq":["l7-tan-so","l7-am-nghe-duoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-do-cao-cua-am","mon":"KHTN","khoi":"7","chu_de":"l7-am-thanh","thu_tu":8,"loai":"kn","ten":"Độ cao của âm","ten_khac":["do cao cua am","am cao","am thap","am bong","am tram","cao do","bong tram"],"noi_dung":"Độ cao (bổng, trầm) của âm phụ thuộc tần số: tần số càng lớn, âm càng cao; tần số càng nhỏ, âm càng thấp.","cong_thuc":null,"y":["Trên đồ thị dao động âm, trong cùng khoảng thời gian, đường sóng <b>càng dày</b> (nhiều dao động) thì âm càng cao.","Hình trái: ít dao động → âm thấp; hình phải: nhiều dao động → âm cao.","Dây đàn căng hơn, ngắn hơn thì phát âm cao hơn."],"bang":null,"bien":null,"vd":{"de":"Dây đàn violin dao động với tần số 880 Hz, dây đàn guitar bass dao động với tần số 80 Hz. Dây nào phát ra âm cao hơn?","buoc":["Độ cao của âm phụ thuộc tần số: tần số càng lớn, âm càng cao.","So sánh: 880 Hz > 80 Hz."],"kq":"Dây đàn violin phát ra âm cao hơn."},"nham":["Nhầm âm cao với âm to: cao – thấp do tần số, to – nhỏ do biên độ."],"lq":["l7-tan-so","l7-do-to-cua-am"],"hinh":"H-l7-do-cao-cua-am","nguon":["KHTN Pocket"]},{"ma":"l7-bien-do","mon":"KHTN","khoi":"7","chu_de":"l7-am-thanh","thu_tu":9,"loai":"dl","ten":"Biên độ dao động","ten_khac":["bien do","bien do dao dong","do lech lon nhat","vi tri can bang","amplitude"],"noi_dung":"Độ lệch lớn nhất của vật dao động so với vị trí cân bằng.","cong_thuc":null,"y":["Biên độ càng lớn thì âm phát ra càng <b>to</b>.","Gảy dây đàn mạnh → dây lệch nhiều → biên độ lớn → âm to.","Trên đồ thị dao động âm, đường sóng càng <b>cao</b> thì biên độ càng lớn."],"bang":null,"bien":null,"vd":{"de":"Một vật dao động, độ lệch lớn nhất so với vị trí cân bằng đo được là 3 cm. Biên độ dao động của vật là bao nhiêu?","buoc":["Biên độ là độ lệch lớn nhất so với vị trí cân bằng.","Đề bài cho độ lệch lớn nhất là 3 cm."],"kq":"Biên độ dao động là 3 cm."},"nham":null,"lq":["l7-do-to-cua-am","l7-dao-dong"],"hinh":"H-l7-bien-do","nguon":["KHTN Pocket"]},{"ma":"l7-do-to-cua-am","mon":"KHTN","khoi":"7","chu_de":"l7-am-thanh","thu_tu":10,"loai":"kn","ten":"Độ to của âm","ten_khac":["do to cua am","am to","am nho","to nho","am luong","tieng to"],"noi_dung":"Độ to của âm phụ thuộc biên độ dao động: biên độ càng lớn, âm càng to; biên độ càng nhỏ, âm càng nhỏ.","cong_thuc":null,"y":["Hình trái: đường sóng thấp → âm nhỏ; hình phải: đường sóng cao → âm to.","Âm quá to, kéo dài có thể gây hại cho tai."],"bang":null,"bien":null,"vd":{"de":"Gảy nhẹ và gảy mạnh cùng một dây đàn. Trường hợp nào biên độ dao động lớn hơn và âm phát ra to hơn?","buoc":["Độ to của âm phụ thuộc biên độ dao động: biên độ càng lớn, âm càng to.","Gảy mạnh làm dây lệch nhiều hơn khỏi vị trí cân bằng."],"kq":"Gảy mạnh cho biên độ lớn hơn và âm to hơn."},"nham":["Đường sóng cao là âm cao → SAI: đường sóng cao là biên độ lớn, âm to."],"lq":["l7-bien-do","l7-do-cao-cua-am","l7-o-nhiem-tieng-on"],"hinh":"H-l7-do-to-cua-am","nguon":["KHTN Pocket"]},{"ma":"l7-am-nghe-duoc","mon":"KHTN","khoi":"7","chu_de":"l7-am-thanh","thu_tu":11,"loai":"kn","ten":"Âm nghe được","ten_khac":["am nghe duoc","nguong nghe","tai nguoi nghe duoc","20 hz","20 000 hz","gioi han nghe"],"noi_dung":"Âm có tần số từ 20 Hz đến 20 000 Hz, là những âm tai người nghe được.","cong_thuc":null,"y":["Dưới 20 Hz là <b>hạ âm</b>; trên 20 000 Hz là <b>siêu âm</b>; tai người không nghe được hai loại này.","Một số động vật nghe được hạ âm hoặc siêu âm."],"bang":[["Loại âm","Tần số"],["Hạ âm","Dưới 20 Hz"],["Âm nghe được","20 Hz – 20 000 Hz"],["Siêu âm","Trên 20 000 Hz"]],"bien":null,"vd":{"de":"Một loại còi phát ra âm có tần số 2 000 Hz. Âm này có thuộc vùng âm nghe được của tai người không?","buoc":["Âm nghe được có tần số từ 20 Hz đến 20 000 Hz.","2 000 Hz nằm trong khoảng này."],"kq":"Có; tai người nghe được âm này."},"nham":null,"lq":["l7-ha-am","l7-sieu-am","l7-tan-so"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-ha-am","mon":"KHTN","khoi":"7","chu_de":"l7-am-thanh","thu_tu":12,"loai":"kn","ten":"Hạ âm","ten_khac":["ha am","infrasound","duoi 20 hz","am tan so thap","voi","ca voi"],"noi_dung":"Âm có tần số dưới 20 Hz, tai người không nghe được.","cong_thuc":null,"y":["Hạ âm có thể sinh ra khi có động đất, núi lửa, bão.","Một số động vật như voi, cá voi phát ra và cảm nhận được hạ âm."],"bang":null,"bien":null,"vd":{"de":"Voi có thể phát ra âm tần số khoảng 15 Hz để liên lạc với đồng loại ở xa. Tai người có nghe được âm này không?","buoc":["Âm nghe được của tai người có tần số từ 20 Hz trở lên.","15 Hz nhỏ hơn 20 Hz."],"kq":"Không; đây là hạ âm, tai người không nghe được."},"nham":["Hạ âm là âm nhỏ → SAI: hạ âm là âm có tần số thấp."],"lq":["l7-am-nghe-duoc","l7-sieu-am"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-sieu-am","mon":"KHTN","khoi":"7","chu_de":"l7-am-thanh","thu_tu":13,"loai":"kn","ten":"Siêu âm","ten_khac":["sieu am","ultrasound","tren 20 000 hz","doi","ca heo","may sieu am","do do sau"],"noi_dung":"Âm có tần số trên 20 000 Hz, tai người không nghe được.","cong_thuc":null,"y":["Dơi, cá heo phát ra siêu âm để định hướng, tìm mồi; chó nghe được một số siêu âm.","Ứng dụng: máy siêu âm trong y tế; tàu thuỷ dùng siêu âm đo độ sâu đáy biển, dò đàn cá."],"bang":null,"bien":null,"vd":{"de":"Dơi phát ra âm có tần số khoảng 50 000 Hz để định vị trong bóng tối. Tai người có nghe được âm này không?","buoc":["Âm nghe được của tai người có tần số tối đa 20 000 Hz.","50 000 Hz lớn hơn 20 000 Hz."],"kq":"Không; đây là siêu âm, tai người không nghe được."},"nham":["Siêu âm là âm rất to → SAI: siêu âm là âm có tần số rất cao."],"lq":["l7-am-nghe-duoc","l7-ha-am","l7-do-khoang-cach-bang-am"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-phan-xa-am","mon":"KHTN","khoi":"7","chu_de":"l7-am-thanh","thu_tu":14,"loai":"ht","ten":"Phản xạ âm","ten_khac":["phan xa am","am phan xa","doi lai","hap thu am","vat phan xa am tot","vat phan xa am kem"],"noi_dung":"Âm gặp vật cản bị dội ngược trở lại gọi là âm phản xạ.","cong_thuc":null,"y":["Vật <b>cứng, nhẵn</b> phản xạ âm tốt.","Vật <b>mềm, xốp, gồ ghề</b> phản xạ âm kém, tức là hấp thụ âm tốt."],"bang":[["Phản xạ âm tốt","Phản xạ âm kém"],["Mặt gương, tấm kim loại","Rèm vải, thảm"],["Tường gạch, mặt đá, gỗ nhẵn","Miếng xốp, bông, cao su xốp"]],"bien":null,"vd":{"de":"Đứng trước một vách núi và hét to, sau một lúc nghe thấy chính tiếng hét của mình vọng lại. Hiện tượng gì đã xảy ra?","buoc":["Âm truyền tới vách núi (vật cản) rồi dội ngược trở lại.","Âm dội lại đến tai gọi là âm phản xạ."],"kq":"Đó là hiện tượng phản xạ âm."},"nham":["Vật mềm, xốp phản xạ âm tốt → SAI: chúng hấp thụ âm tốt."],"lq":["l7-tieng-vang","l7-do-khoang-cach-bang-am","l7-chong-o-nhiem-tieng-on"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-tieng-vang","mon":"KHTN","khoi":"7","chu_de":"l7-am-thanh","thu_tu":15,"loai":"ht","ten":"Tiếng vang","ten_khac":["tieng vang","vang","echo","tieng doi","1/15 giay","nghe vang"],"noi_dung":"Âm phản xạ nghe được cách biệt với âm phát ra.","cong_thuc":null,"y":["Trong phòng nhỏ, âm phản xạ đến gần như cùng lúc với âm trực tiếp → không nghe vang, chỉ thấy âm to hơn.","(Mở rộng) Có tiếng vang khi âm phản xạ đến tai chậm hơn âm trực tiếp ít nhất khoảng <b>1/15 giây</b>, tức vật cản cách ta từ khoảng <b>11 m</b> trở lên.","Ví dụ: nói to trong hang động, giữa vách núi."],"bang":null,"bien":null,"vd":{"de":"Trong một căn phòng nhỏ, hét to nhưng không nghe thấy tiếng vọng riêng biệt, chỉ thấy âm to hơn bình thường. Vì sao phòng nhỏ không tạo được tiếng vang?","buoc":["Tiếng vang chỉ nghe được khi âm phản xạ tách biệt rõ với âm phát ra.","Trong phòng nhỏ, tường ở rất gần nên âm phản xạ dội lại gần như ngay lập tức, hòa lẫn vào âm phát ra."],"kq":"Vì khoảng cách quá ngắn, tai không phân biệt được hai âm nên không nghe thấy tiếng vang."},"nham":["Phòng nào cũng nghe tiếng vang → SAI."],"lq":["l7-phan-xa-am","l7-toc-do-truyen-am"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-do-khoang-cach-bang-am","mon":"KHTN","khoi":"7","chu_de":"l7-am-thanh","thu_tu":16,"loai":"ud","ten":"Đo khoảng cách bằng âm phản xạ","ten_khac":["do khoang cach bang am","do do sau day bien","sonar","am di va ve","chia 2","d = v.t/2"],"noi_dung":"Phát âm tới vật cản, đo thời gian đến khi nhận âm phản xạ; khoảng cách bằng tốc độ âm nhân thời gian chia 2.","cong_thuc":"d = v·t/2","y":["Âm đi tới vật cản rồi dội về, nên quãng đường âm đi <b>gấp đôi</b> khoảng cách.","Ứng dụng: tàu thuỷ đo độ sâu đáy biển, dò đàn cá bằng siêu âm."],"bang":null,"bien":[["d","khoảng cách tới vật cản","m"],["v","tốc độ truyền âm","m/s"],["t","thời gian từ lúc phát đến lúc nhận âm phản xạ","s"]],"vd":{"de":"Tàu phát siêu âm xuống đáy biển, sau 1,2 s nhận được âm phản xạ. Tốc độ âm trong nước biển là 1 500 m/s. Tính độ sâu đáy biển.","buoc":["Quãng đường âm đi và về: 1 500 · 1,2 = 1 800 m.","d = 1 800 : 2"],"kq":"d = 900 m"},"nham":["Quên chia 2 (âm đi rồi về)."],"lq":["l7-phan-xa-am","l7-sieu-am","l7-toc-do-truyen-am"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-o-nhiem-tieng-on","mon":"KHTN","khoi":"7","chu_de":"l7-am-thanh","thu_tu":17,"loai":"ht","ten":"Ô nhiễm tiếng ồn","ten_khac":["o nhiem tieng on","tieng on","on ao","tac hai tieng on","o nhiem am thanh"],"noi_dung":"Tiếng ồn to và kéo dài, gây ảnh hưởng xấu đến sức khoẻ và hoạt động bình thường của con người.","cong_thuc":null,"y":["Tác hại: đau đầu, mất ngủ, căng thẳng, giảm tập trung; lâu dài có thể giảm thính lực.","Nguồn ồn thường gặp: xe cộ, công trường, nhà máy, loa đài mở quá to."],"bang":null,"bien":null,"vd":{"de":"Sống gần một công trường xây dựng, tiếng máy khoan kêu to suốt cả ngày khiến khó ngủ, khó tập trung học bài. Đây có phải ô nhiễm tiếng ồn không?","buoc":["Ô nhiễm tiếng ồn là tiếng ồn to, kéo dài, ảnh hưởng xấu đến sức khỏe và sinh hoạt.","Tiếng máy khoan to, liên tục cả ngày gây ảnh hưởng như trên."],"kq":"Có; đây là ô nhiễm tiếng ồn."},"nham":["Mọi âm to đều là ô nhiễm → chỉ khi to, kéo dài và gây ảnh hưởng xấu."],"lq":["l7-chong-o-nhiem-tieng-on","l7-do-to-cua-am"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-chong-o-nhiem-tieng-on","mon":"KHTN","khoi":"7","chu_de":"l7-am-thanh","thu_tu":18,"loai":"ud","ten":"Chống ô nhiễm tiếng ồn","ten_khac":["chong o nhiem tieng on","giam tieng on","cach am","vat lieu cach am","trong cay xanh","tuong chan"],"noi_dung":"Giảm độ to của nguồn âm, phân tán âm trên đường truyền hoặc ngăn đường truyền âm tới tai.","cong_thuc":null,"y":["Dùng vật liệu <b>mềm, xốp</b> (hấp thụ âm tốt) để cách âm.","Không gây tiếng ồn lớn vào giờ nghỉ ngơi."],"bang":[["Cách làm","Ví dụ"],["Giảm độ to của nguồn âm","Hạn chế bóp còi, lắp bộ giảm thanh"],["Phân tán âm trên đường truyền","Trồng nhiều cây xanh quanh nhà, trường học"],["Ngăn cản đường truyền âm","Xây tường chắn, đóng cửa, dùng rèm dày, xốp, thảm"]],"bien":null,"vd":{"de":"Nhà ở gần đường lớn nhiều xe cộ qua lại. Nêu một biện pháp để giảm tiếng ồn lọt vào phòng ngủ.","buoc":["Có ba nhóm biện pháp: giảm to nguồn âm, phân tán âm trên đường truyền, ngăn đường truyền âm tới tai.","Với nhà gần đường, khó giảm tiếng xe nên nên ngăn đường truyền âm."],"kq":"Lắp cửa kính dày, trồng cây hoặc treo rèm dày để ngăn bớt âm truyền vào phòng."},"nham":null,"lq":["l7-o-nhiem-tieng-on","l7-phan-xa-am"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-nang-luong-anh-sang","mon":"KHTN","khoi":"7","chu_de":"l7-anh-sang","thu_tu":1,"loai":"kn","ten":"Năng lượng ánh sáng","ten_khac":["nang luong anh sang","quang nang","pin mat troi","anh sang la nang luong","nang luong mat troi","light energy"],"noi_dung":"Ánh sáng là một dạng năng lượng, có thể chuyển hoá thành điện năng, nhiệt năng, hoá năng.","cong_thuc":null,"y":["Do các nguồn sáng phát ra: Mặt Trời, bóng đèn, ngọn lửa…","Pin mặt trời biến năng lượng ánh sáng thành <b>điện năng</b>.","Phơi thóc, bình nước nóng mặt trời: thành <b>nhiệt năng</b>.","Cây xanh quang hợp: thành <b>hoá năng</b>."],"bang":[["Thiết bị, hiện tượng","Ánh sáng chuyển thành"],["Pin mặt trời","Điện năng"],["Bình nước nóng năng lượng mặt trời","Nhiệt năng"],["Quang hợp","Hoá năng"]],"bien":null,"vd":{"de":"Đặt một tấm pin mặt trời ngoài nắng, pin tạo ra dòng điện chạy trong mạch. Ánh sáng đã chuyển hóa thành dạng năng lượng nào?","buoc":["Ánh sáng là một dạng năng lượng, có thể chuyển hóa thành dạng khác.","Ở đây pin mặt trời biến đổi năng lượng ánh sáng thành dòng điện."],"kq":"Năng lượng ánh sáng chuyển hóa thành năng lượng điện."},"nham":null,"lq":["l7-nguon-sang","l7-tia-sang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-nguon-sang","mon":"KHTN","khoi":"7","chu_de":"l7-anh-sang","thu_tu":2,"loai":"kn","ten":"Nguồn sáng","ten_khac":["nguon sang","vat tu phat sang","mat troi","bong den","ngon nen"],"noi_dung":"Vật tự phát ra ánh sáng, như Mặt Trời, ngọn nến đang cháy, bóng đèn đang sáng.","cong_thuc":null,"y":["Mặt Trăng <b>không</b> phải nguồn sáng: nó chỉ hắt lại ánh sáng Mặt Trời.","Nguồn sáng nhỏ chỉ tạo vùng tối; nguồn sáng rộng tạo thêm vùng nửa tối."],"bang":null,"bien":null,"vd":{"de":"Mặt Trăng có phải là nguồn sáng không? Vì sao ban đêm ta vẫn nhìn thấy Mặt Trăng sáng?","buoc":["Nguồn sáng là vật tự phát ra ánh sáng.","Mặt Trăng không tự phát sáng mà chỉ hắt lại ánh sáng nhận từ Mặt Trời."],"kq":"Không; Mặt Trăng không phải nguồn sáng, ta thấy nó sáng vì nó hắt lại ánh sáng Mặt Trời."},"nham":["Mặt Trăng, cái gương là nguồn sáng → SAI."],"lq":["l7-nang-luong-anh-sang","l7-vung-toi","l7-vung-nua-toi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-tia-sang","mon":"KHTN","khoi":"7","chu_de":"l7-anh-sang","thu_tu":3,"loai":"kn","ten":"Tia sáng","ten_khac":["tia sang","duong truyen anh sang","truyen thang","anh sang truyen theo duong thang","bieu dien tia sang"],"noi_dung":"Tia sáng được biểu diễn bằng một đường thẳng có mũi tên chỉ hướng truyền của ánh sáng.","cong_thuc":null,"y":["Trong môi trường trong suốt, đồng tính (như không khí), ánh sáng truyền theo <b>đường thẳng</b>.","Nhiều tia sáng hợp thành <b>chùm sáng</b>."],"bang":null,"bien":null,"vd":null,"nham":["Vẽ tia sáng không có mũi tên."],"lq":["l7-chum-sang","l7-vung-toi","l7-nguon-sang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-chum-sang","mon":"KHTN","khoi":"7","chu_de":"l7-anh-sang","thu_tu":4,"loai":"kn","ten":"Chùm sáng","ten_khac":["chum sang","chum song song","chum hoi tu","chum phan ki","chum sang phan ky"],"noi_dung":"Chùm sáng gồm nhiều tia sáng; có ba loại: chùm song song, chùm hội tụ, chùm phân kì.","cong_thuc":null,"y":["Chùm sáng hẹp có thể coi gần đúng như một tia sáng.","Chùm phân kì: càng xa nguồn, chùm càng loe rộng."],"bang":[["Chùm sáng","Đặc điểm","Ví dụ"],["Song song","Các tia không giao nhau","Ánh sáng Mặt Trời chiếu tới Trái Đất"],["Hội tụ","Các tia gặp nhau tại một điểm","Ánh sáng qua kính lúp"],["Phân kì","Các tia loe rộng ra","Ánh sáng từ đèn pin, bóng đèn"]],"bien":null,"vd":{"de":"Chùm sáng phát ra từ một đèn pin chiếu thẳng tạo ra vệt sáng tròn gần như không đổi kích thước khi xa dần. Đây là loại chùm sáng gì?","buoc":["Có ba loại chùm sáng: song song, hội tụ, phân kì.","Vệt sáng không đổi kích thước khi đi xa là đặc điểm của chùm không loe rộng hay thu hẹp."],"kq":"Đó là chùm sáng song song."},"nham":["Đèn pin cho chùm hội tụ → SAI: thường là chùm phân kì."],"lq":["l7-tia-sang","l7-nguon-sang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-vung-toi","mon":"KHTN","khoi":"7","chu_de":"l7-anh-sang","thu_tu":5,"loai":"kn","ten":"Vùng tối","ten_khac":["vung toi","bong toi","bong","vat can sang","bong den"],"noi_dung":"Vùng phía sau vật cản sáng, không nhận được ánh sáng từ nguồn sáng.","cong_thuc":null,"y":["Vùng tối xuất hiện vì ánh sáng <b>truyền theo đường thẳng</b>.","Nguồn sáng nhỏ: trên màn chỉ có vùng tối và vùng sáng, ranh giới rõ nét.","Đưa vật cản lại gần nguồn sáng thì bóng trên màn to ra."],"bang":null,"bien":null,"vd":{"de":"Đặt một vật cản trước một nguồn sáng nhỏ (bóng đèn dây tóc). Đứng ở vùng phía sau vật, hoàn toàn không nhận được ánh sáng nào từ đèn. Đó là vùng gì?","buoc":["Vùng tối là vùng phía sau vật cản, không nhận được ánh sáng từ nguồn.","Nguồn sáng nhỏ (coi như một điểm) chỉ tạo ra vùng tối, không có vùng nửa tối."],"kq":"Đó là vùng tối."},"nham":null,"lq":["l7-vung-nua-toi","l7-tia-sang","l7-nhat-thuc"],"hinh":"H-l7-vung-toi","nguon":["KHTN Pocket"]},{"ma":"l7-vung-nua-toi","mon":"KHTN","khoi":"7","chu_de":"l7-anh-sang","thu_tu":6,"loai":"kn","ten":"Vùng nửa tối","ten_khac":["vung nua toi","bong nua toi","nua toi","nguon sang rong","bong nhoe"],"noi_dung":"Vùng phía sau vật cản chỉ nhận được một phần ánh sáng từ nguồn sáng rộng.","cong_thuc":null,"y":["Chỉ có khi <b>nguồn sáng rộng</b> (lớn so với vật cản).","Nằm giữa vùng tối và vùng sáng, làm ranh giới bóng bị nhoè."],"bang":null,"bien":null,"vd":{"de":"Đặt một vật cản trước một nguồn sáng rộng (bóng đèn ống dài). Đứng ở vùng chỉ nhận được ánh sáng từ một phần của đèn. Đó là vùng gì?","buoc":["Vùng nửa tối là vùng chỉ nhận được một phần ánh sáng từ nguồn sáng rộng.","Nguồn sáng rộng tạo ra cả vùng tối và vùng nửa tối phía sau vật cản."],"kq":"Đó là vùng nửa tối."},"nham":["Nguồn sáng nhỏ cũng tạo vùng nửa tối → SAI.","Vùng nửa tối không nhận được ánh sáng nào → SAI: nhận một phần."],"lq":["l7-vung-toi","l7-nhat-thuc","l7-nguon-sang"],"hinh":"H-l7-vung-nua-toi","nguon":["KHTN Pocket"]},{"ma":"l7-nhat-thuc","mon":"KHTN","khoi":"7","chu_de":"l7-anh-sang","thu_tu":7,"loai":"ht","ten":"Nhật thực","ten_khac":["nhat thuc","che mat troi","nhat thuc toan phan","nhat thuc mot phan","mat trang che mat troi"],"noi_dung":"Hiện tượng Mặt Trăng nằm giữa, thẳng hàng với Mặt Trời và Trái Đất, che khuất Mặt Trời đối với người quan sát trên Trái Đất.","cong_thuc":null,"y":["Người đứng trong <b>vùng tối</b> của Mặt Trăng thấy nhật thực toàn phần.","Người đứng trong <b>vùng nửa tối</b> thấy nhật thực một phần.","Không nhìn trực tiếp Mặt Trời khi xem nhật thực vì hại mắt."],"bang":null,"bien":null,"vd":{"de":"Ban ngày, Mặt Trăng đi vào giữa, thẳng hàng với Mặt Trời và Trái Đất, che khuất Mặt Trời đối với người đứng ở một vùng trên Trái Đất. Đây là hiện tượng gì?","buoc":["Hiện tượng liên quan đến vị trí thẳng hàng của Mặt Trời, Mặt Trăng, Trái Đất.","Mặt Trăng ở giữa che khuất ánh sáng Mặt Trời chiếu tới Trái Đất."],"kq":"Đó là hiện tượng nhật thực."},"nham":null,"lq":["l7-nguyet-thuc","l7-vung-toi","l7-vung-nua-toi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-nguyet-thuc","mon":"KHTN","khoi":"7","chu_de":"l7-anh-sang","thu_tu":8,"loai":"ht","ten":"Nguyệt thực","ten_khac":["nguyet thuc","mat trang bi che","trang mau","trai dat che mat trang"],"noi_dung":"Hiện tượng Trái Đất nằm giữa, thẳng hàng với Mặt Trời và Mặt Trăng, Mặt Trăng đi vào vùng tối của Trái Đất.","cong_thuc":null,"y":["Mặt Trăng không được Mặt Trời chiếu sáng nên ta không thấy nó sáng như bình thường.","Nguyệt thực xảy ra vào đêm <b>trăng tròn</b>."],"bang":null,"bien":null,"vd":{"de":"Ban đêm, Trái Đất nằm giữa, thẳng hàng với Mặt Trời và Mặt Trăng; Mặt Trăng đi vào vùng bóng tối của Trái Đất và tối dần. Đây là hiện tượng gì?","buoc":["Hiện tượng liên quan đến vị trí thẳng hàng của Mặt Trời, Trái Đất, Mặt Trăng.","Trái Đất ở giữa che khuất ánh sáng Mặt Trời chiếu tới Mặt Trăng."],"kq":"Đó là hiện tượng nguyệt thực."},"nham":["Nhầm thứ tự: nhật thực là Mặt Trăng ở giữa; nguyệt thực là Trái Đất ở giữa."],"lq":["l7-nhat-thuc","l7-vung-toi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-phan-xa-anh-sang","mon":"KHTN","khoi":"7","chu_de":"l7-anh-sang","thu_tu":9,"loai":"ht","ten":"Phản xạ ánh sáng","ten_khac":["phan xa anh sang","su phan xa anh sang","tia toi","tia phan xa","diem toi","hat lai anh sang"],"noi_dung":"Hiện tượng ánh sáng chiếu tới bề mặt một vật bị hắt trở lại môi trường cũ.","cong_thuc":null,"y":["<b>SI</b>: tia tới · <b>I</b>: điểm tới · <b>IR</b>: tia phản xạ · <b>IN</b>: pháp tuyến.","Bề mặt nhẵn bóng cho phản xạ gương (thấy ảnh); bề mặt gồ ghề cho phản xạ khuếch tán.","Nhờ ánh sáng phản xạ từ vật đi vào mắt, ta nhìn thấy vật."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l7-dinh-luat-phan-xa","l7-goc-toi","l7-phap-tuyen","l7-phan-xa-khuech-tan"],"hinh":"H-l7-phan-xa-anh-sang","nguon":["KHTN Pocket"]},{"ma":"l7-dinh-luat-phan-xa","mon":"KHTN","khoi":"7","chu_de":"l7-anh-sang","thu_tu":10,"loai":"ct","ten":"Định luật phản xạ ánh sáng","ten_khac":["dinh luat phan xa anh sang","dinh luat phan xa","goc phan xa bang goc toi","i' = i","i = i′"],"noi_dung":"Tia phản xạ nằm trong mặt phẳng chứa tia tới và pháp tuyến tại điểm tới; góc phản xạ bằng góc tới.","cong_thuc":"i′ = i","y":["Tia phản xạ nằm ở <b>phía bên kia</b> pháp tuyến so với tia tới.","Tia tới vuông góc với gương (i = 0°) thì tia phản xạ bật ngược lại theo đường cũ.","Góc giữa tia tới và tia phản xạ bằng <b>2i</b>."],"bang":null,"bien":[["i","góc tới (giữa tia tới và pháp tuyến)","°"],["i′","góc phản xạ (giữa tia phản xạ và pháp tuyến)","°"]],"vd":{"de":"Tia tới hợp với mặt gương một góc 30°. Tính góc phản xạ và góc giữa tia tới với tia phản xạ.","buoc":["Góc tới: i = 90° − 30° = 60°.","Góc phản xạ: i′ = i = 60°.","Góc giữa tia tới và tia phản xạ: 60° + 60° = 120°."],"kq":"i′ = 60°; góc giữa hai tia 120°"},"nham":["Đo góc tới với mặt gương → SAI: đo với pháp tuyến.","Góc phản xạ gấp đôi góc tới → SAI: i′ = i."],"lq":["l7-phan-xa-anh-sang","l7-goc-toi","l7-phap-tuyen","l7-guong-phang"],"hinh":"H-l7-dinh-luat-phan-xa","nguon":["KHTN Pocket"]},{"ma":"l7-goc-toi","mon":"KHTN","khoi":"7","chu_de":"l7-anh-sang","thu_tu":11,"loai":"kn","ten":"Góc tới và góc phản xạ","ten_khac":["goc toi","goc phan xa","goc sin","goc nir","i va i′","do goc toi"],"noi_dung":"Góc tới i là góc giữa tia tới và pháp tuyến; góc phản xạ i′ là góc giữa tia phản xạ và pháp tuyến.","cong_thuc":null,"y":["Góc tới i = góc SIN; góc phản xạ i′ = góc NIR.","Cả hai góc đều đo với <b>pháp tuyến</b>, không đo với mặt gương.","Nếu đề cho góc giữa tia tới và mặt gương là α thì i = 90° − α."],"bang":null,"bien":null,"vd":{"de":"Một tia sáng tới hợp với mặt gương phẳng một góc 40°. Tính góc tới i (so với pháp tuyến).","buoc":["Pháp tuyến vuông góc với mặt gương tại điểm tới, tạo góc 90° với mặt gương.","Góc tới i = 90° − 40°"],"kq":"i = 50°"},"nham":["Lấy luôn góc giữa tia tới và mặt gương làm góc tới."],"lq":["l7-phap-tuyen","l7-dinh-luat-phan-xa","l7-phan-xa-anh-sang"],"hinh":"H-l7-goc-toi","nguon":["KHTN Pocket"]},{"ma":"l7-phap-tuyen","mon":"KHTN","khoi":"7","chu_de":"l7-anh-sang","thu_tu":12,"loai":"kn","ten":"Pháp tuyến","ten_khac":["phap tuyen","in","duong vuong goc voi guong","duong phap tuyen","normal"],"noi_dung":"Đường thẳng vuông góc với mặt gương tại điểm tới, thường kí hiệu IN và vẽ bằng nét đứt.","cong_thuc":null,"y":["Muốn vẽ tia phản xạ, phải dựng pháp tuyến trước.","Pháp tuyến là tia phân giác của góc tạo bởi tia tới và tia phản xạ."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l7-goc-toi","l7-dinh-luat-phan-xa"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-phan-xa-khuech-tan","mon":"KHTN","khoi":"7","chu_de":"l7-anh-sang","thu_tu":13,"loai":"ht","ten":"Phản xạ khuếch tán","ten_khac":["phan xa khuech tan","khuech tan","phan xa guong","be mat go ghe","phan xa moi huong"],"noi_dung":"Phản xạ trên bề mặt gồ ghề: chùm tia tới song song cho các tia phản xạ đi theo mọi hướng.","cong_thuc":null,"y":["Nhờ phản xạ khuếch tán, ta nhìn thấy trang sách, bức tường từ nhiều chỗ ngồi khác nhau.","Mỗi tia sáng vẫn tuân theo định luật phản xạ."],"bang":[["","Phản xạ gương","Phản xạ khuếch tán"],["Bề mặt","Nhẵn bóng (gương, mặt nước lặng)","Gồ ghề (tờ giấy, bức tường)"],["Chùm tới song song","Chùm phản xạ song song","Tia phản xạ theo mọi hướng"],["Kết quả","Thấy ảnh rõ nét","Không thấy ảnh, nhìn được vật từ nhiều phía"]],"bien":null,"vd":{"de":"Ánh sáng chiếu vào mặt một tờ giấy nhám (xù xì) rồi hắt ra theo nhiều hướng khác nhau, không tạo được ảnh rõ. Đây là loại phản xạ gì?","buoc":["Phản xạ khuếch tán xảy ra trên bề mặt gồ ghề.","Chùm tia tới song song cho các tia phản xạ đi theo mọi hướng khác nhau."],"kq":"Đó là phản xạ khuếch tán."},"nham":null,"lq":["l7-phan-xa-anh-sang","l7-guong-phang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-guong-phang","mon":"KHTN","khoi":"7","chu_de":"l7-anh-sang","thu_tu":14,"loai":"kn","ten":"Gương phẳng","ten_khac":["guong phang","guong","soi guong","kinh tiem vong","mat phan xa"],"noi_dung":"Vật có bề mặt phẳng, nhẵn, phản xạ tốt ánh sáng, cho ảnh ảo lớn bằng vật.","cong_thuc":null,"y":["Mặt nước lặng, tấm kính, tấm kim loại nhẵn bóng cũng có thể coi là gương phẳng.","Ứng dụng: soi gương, gương tiệm cắt tóc, gương làm phòng trông rộng hơn.","<b>Kính tiềm vọng</b>: hai gương phẳng song song, nghiêng 45°, giúp quan sát vật bị che khuất."],"bang":null,"bien":null,"vd":{"de":"Soi mặt vào mặt lõm của một chiếc thìa inox, thấy ảnh bị méo, không giống ảnh trong gương phẳng thông thường. Vì sao?","buoc":["Gương phẳng có bề mặt phẳng, nhẵn, cho ảnh không bị méo.","Mặt thìa bị cong (không phẳng) nên ánh sáng phản xạ không đều, ảnh bị méo."],"kq":"Vì mặt thìa không phải bề mặt phẳng nên không cho ảnh giống gương phẳng."},"nham":null,"lq":["l7-anh-qua-guong-phang","l7-dinh-luat-phan-xa","l7-anh-ao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-anh-ao","mon":"KHTN","khoi":"7","chu_de":"l7-anh-sang","thu_tu":15,"loai":"kn","ten":"Ảnh ảo","ten_khac":["anh ao","khong hung duoc tren man","anh sau guong","net dut"],"noi_dung":"Ảnh không hứng được trên màn chắn, như ảnh của vật tạo bởi gương phẳng.","cong_thuc":null,"y":["Ta nhìn thấy ảnh ảo vì tia phản xạ đi vào mắt có <b>đường kéo dài</b> đi qua ảnh.","Khi vẽ, ảnh ảo được vẽ bằng <b>nét đứt</b>."],"bang":null,"bien":null,"vd":{"de":"Đặt một tờ giấy làm màn ở phía sau một gương phẳng, không hứng được ảnh của vật đặt trước gương trên tờ giấy đó. Ảnh này gọi là ảnh gì?","buoc":["Ảnh ảo là ảnh không hứng được trên màn chắn.","Ảnh của vật qua gương phẳng không thể hứng được trên màn phía sau gương."],"kq":"Đó là ảnh ảo."},"nham":["Ảnh qua gương phẳng hứng được trên màn → SAI."],"lq":["l7-anh-qua-guong-phang","l7-guong-phang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-anh-qua-guong-phang","mon":"KHTN","khoi":"7","chu_de":"l7-anh-sang","thu_tu":16,"loai":"kn","ten":"Ảnh qua gương phẳng","ten_khac":["anh qua guong phang","tinh chat anh","anh doi xung","anh lon bang vat","anh cua vat","anh tao boi guong phang"],"noi_dung":"Ảnh ảo, lớn bằng vật, đối xứng với vật qua gương: khoảng cách từ ảnh tới gương bằng khoảng cách từ vật tới gương.","cong_thuc":null,"y":["Khoảng cách từ vật tới ảnh <b>gấp đôi</b> khoảng cách từ vật tới gương.","Thí nghiệm kiểm chứng: dùng tấm kính trong thay gương và hai cây nến giống nhau.","Đi xa gương, ảnh vẫn lớn bằng vật; chỉ trông nhỏ đi vì ở xa mắt."],"bang":null,"bien":null,"vd":{"de":"An đứng cách gương phẳng 1,5 m. Ảnh cách An bao xa? Nếu An tiến lại gần gương 0,5 m thì ảnh cách An bao xa?","buoc":["Ảnh cách gương 1,5 m → ảnh cách An 1,5 + 1,5 = 3 m.","An tiến lại 0,5 m → An cách gương 1 m → ảnh cách An 1 + 1 = 2 m."],"kq":"3 m; sau đó 2 m"},"nham":["Khoảng cách vật – ảnh bằng khoảng cách vật – gương → SAI: gấp đôi."],"lq":["l7-anh-ao","l7-ve-anh-qua-guong","l7-guong-phang"],"hinh":"H-l7-anh-qua-guong-phang","nguon":["KHTN Pocket"]},{"ma":"l7-ve-anh-qua-guong","mon":"KHTN","khoi":"7","chu_de":"l7-anh-sang","thu_tu":17,"loai":"tn","ten":"Vẽ ảnh qua gương phẳng","ten_khac":["ve anh qua guong","ve anh","dung anh","ve tia sang toi mat","doi xung qua guong"],"noi_dung":"Dựa vào tính chất đối xứng: lấy điểm đối xứng của từng điểm trên vật qua gương rồi nối lại bằng nét đứt.","cong_thuc":null,"y":["Bước 1: Từ A kẻ đường vuông góc với gương, lấy A′ sau gương sao cho A′ cách gương bằng A.","Bước 2: Làm tương tự với B được B′; nối A′B′ bằng <b>nét đứt</b>.","Vẽ tia tới mắt M: nối A′ với M cắt gương tại I; AI là tia tới, IM là tia phản xạ."],"bang":null,"bien":null,"vd":null,"nham":["Vẽ ảnh lộn ngược, hoặc vẽ ảnh bằng nét liền."],"lq":["l7-anh-qua-guong-phang","l7-dinh-luat-phan-xa"],"hinh":"H-l7-ve-anh-qua-guong","nguon":["KHTN Pocket"]},{"ma":"l7-nam-cham","mon":"KHTN","khoi":"7","chu_de":"l7-tu","thu_tu":1,"loai":"kn","ten":"Nam châm","ten_khac":["nam cham","nam cham vinh cuu","nam cham thang","nam cham chu u","kim nam cham","magnet","tu tinh"],"noi_dung":"Vật có từ tính: hút được sắt, thép, nickel, cobalt và luôn có hai cực là cực Bắc và cực Nam.","cong_thuc":null,"y":["Các loại thường gặp: nam châm thẳng, nam châm chữ U, kim nam châm, nam châm viên.","Nam châm không hút nhôm, đồng, nhựa, gỗ, giấy.","Treo tự do, nam châm luôn chỉ hướng <b>Bắc – Nam</b> địa lí."],"bang":null,"bien":null,"vd":{"de":"Đưa một chiếc đũa nhôm và một chiếc đinh sắt lại gần một thanh nam châm. Vật nào bị hút?","buoc":["Nam châm chỉ hút được sắt, thép, nickel, cobalt.","Nhôm không thuộc nhóm vật liệu bị nam châm hút."],"kq":"Chỉ đinh sắt bị hút, đũa nhôm không bị hút."},"nham":["Nam châm hút mọi kim loại → SAI: không hút nhôm, đồng."],"lq":["l7-cuc-tu","l7-vat-lieu-tu","l7-tuong-tac-nam-cham","l7-tu-truong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-cuc-tu","mon":"KHTN","khoi":"7","chu_de":"l7-tu","thu_tu":2,"loai":"kn","ten":"Cực từ","ten_khac":["cuc tu","cuc bac","cuc nam","n","s","hai cuc nam cham","cuc nam cham"],"noi_dung":"Hai đầu của nam châm, nơi hút sắt mạnh nhất: cực Bắc (N) và cực Nam (S).","cong_thuc":null,"y":["Treo nam châm tự do: đầu chỉ hướng Bắc địa lí là <b>cực Bắc (N)</b>, đầu kia là <b>cực Nam (S)</b>.","Cực Bắc thường sơn màu đỏ.","Bẻ đôi nam châm, mỗi nửa vẫn có đủ hai cực."],"bang":null,"bien":null,"vd":{"de":"Hai thanh nam châm để gần nhau, hai cực Bắc của chúng đối diện nhau. Chúng hút hay đẩy nhau?","buoc":["Cùng cực thì đẩy nhau, khác cực thì hút nhau.","Ở đây hai cực Bắc (cùng cực) đối diện nhau."],"kq":"Hai thanh nam châm đẩy nhau."},"nham":["Bẻ đôi nam châm được một nửa chỉ có cực Bắc → SAI."],"lq":["l7-nam-cham","l7-tuong-tac-nam-cham"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-tuong-tac-nam-cham","mon":"KHTN","khoi":"7","chu_de":"l7-tu","thu_tu":3,"loai":"ht","ten":"Tương tác giữa hai nam châm","ten_khac":["tuong tac giua hai nam cham","cung ten day nhau","khac ten hut nhau","hut nhau","day nhau","tuong tac tu"],"noi_dung":"Đặt hai nam châm gần nhau: các cực cùng tên thì đẩy nhau, các cực khác tên thì hút nhau.","cong_thuc":null,"y":["Dùng quy tắc này để tìm tên cực của nam châm chưa ghi cực.","Nam châm hút được mọi vật liệu từ, nhưng chỉ <b>đẩy</b> được một nam châm khác (khi đặt cực cùng tên gần nhau)."],"bang":[["Hai cực đặt gần nhau","Tương tác"],["N – N","Đẩy nhau"],["S – S","Đẩy nhau"],["N – S","Hút nhau"]],"bien":null,"vd":{"de":"Đưa cực Bắc của kim la bàn lại gần đầu A của một thanh nam châm, thấy kim bị hút về A. Đầu A là cực gì?","buoc":["Cực Bắc của kim bị hút về A.","Khác tên thì hút nhau."],"kq":"A là cực Nam (S)"},"nham":null,"lq":["l7-cuc-tu","l7-nam-cham","l7-la-ban"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-vat-lieu-tu","mon":"KHTN","khoi":"7","chu_de":"l7-tu","thu_tu":4,"loai":"ch","ten":"Vật liệu từ","ten_khac":["vat lieu tu","vat lieu co tinh chat tu","sat","thep","nickel","cobalt","bi nam cham hut"],"noi_dung":"Vật liệu bị nam châm hút, như sắt, thép, nickel, cobalt.","cong_thuc":null,"y":["<b>Không</b> phải vật liệu từ: nhôm, đồng, nhựa, gỗ, giấy, thuỷ tinh.","Ứng dụng: dùng nam châm tách sắt ra khỏi hỗn hợp, phân loại rác kim loại."],"bang":null,"bien":null,"vd":{"de":"Trong các vật: thìa nhôm, đinh sắt, dây đồng, kẹp giấy bằng thép. Những vật nào bị nam châm hút?","buoc":["Vật liệu từ (bị nam châm hút) gồm sắt, thép, nickel, cobalt.","Nhôm và đồng không phải vật liệu từ."],"kq":"Đinh sắt và kẹp giấy thép bị hút; thìa nhôm và dây đồng không bị hút."},"nham":["Đồng, nhôm là kim loại nên bị nam châm hút → SAI."],"lq":["l7-nam-cham","l7-nam-cham-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-tu-truong","mon":"KHTN","khoi":"7","chu_de":"l7-tu","thu_tu":5,"loai":"kn","ten":"Từ trường","ten_khac":["tu truong","magnetic field","vung xung quanh nam cham","luc tu","nhan biet tu truong"],"noi_dung":"Vùng không gian xung quanh nam châm (hoặc dòng điện) có khả năng tác dụng lực từ lên kim nam châm đặt trong nó.","cong_thuc":null,"y":["Nhận biết: đặt kim nam châm vào, nếu kim bị lệch khỏi hướng Bắc – Nam thì ở đó có từ trường.","Từ trường được biểu diễn bằng <b>đường sức từ</b>.","Gần hai cực, từ trường mạnh hơn."],"bang":null,"bien":null,"vd":{"de":"Đưa một kim nam châm nhỏ lại gần một thanh nam châm, kim bị lệch khỏi hướng ban đầu dù chưa chạm vào nam châm. Điều này chứng tỏ điều gì?","buoc":["Từ trường là vùng không gian có khả năng tác dụng lực từ lên kim nam châm.","Kim bị lệch dù không chạm chứng tỏ xung quanh nam châm có từ trường."],"kq":"Chứng tỏ xung quanh thanh nam châm có từ trường."},"nham":null,"lq":["l7-tu-pho","l7-duong-suc-tu","l7-tu-truong-trai-dat","l7-tu-truong-dong-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-tu-pho","mon":"KHTN","khoi":"7","chu_de":"l7-tu","thu_tu":6,"loai":"kn","ten":"Từ phổ","ten_khac":["tu pho","mat sat","hinh anh tu truong","rac mat sat"],"noi_dung":"Hình ảnh các đường mạt sắt sắp xếp xung quanh nam châm, cho biết hình ảnh trực quan của từ trường.","cong_thuc":null,"y":["Tạo từ phổ: đặt tấm nhựa lên nam châm, rắc đều mạt sắt, gõ nhẹ tấm nhựa.","Mạt sắt xếp thành những đường cong nối hai cực; gần hai cực mạt sắt <b>dày hơn</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l7-duong-suc-tu","l7-tu-truong"],"hinh":"H-l7-tu-pho","nguon":["KHTN Pocket"]},{"ma":"l7-duong-suc-tu","mon":"KHTN","khoi":"7","chu_de":"l7-tu","thu_tu":7,"loai":"kn","ten":"Đường sức từ","ten_khac":["duong suc tu","duong suc","chieu duong suc tu","ra bac vao nam","magnetic field lines"],"noi_dung":"Những đường vẽ theo hình ảnh từ phổ để biểu diễn từ trường; bên ngoài nam châm, chúng đi ra ở cực Bắc, đi vào ở cực Nam.","cong_thuc":null,"y":["Chiều đường sức từ: chiều từ cực Nam sang cực Bắc của kim nam châm đặt dọc theo đường sức.","Chỗ đường sức <b>dày</b> thì từ trường mạnh, chỗ thưa thì từ trường yếu."],"bang":null,"bien":null,"vd":{"de":"Tại một điểm ở ngoài, gần cực Bắc của một thanh nam châm, đường sức từ có chiều đi ra hay đi vào nam châm?","buoc":["Bên ngoài nam châm, đường sức từ đi ra ở cực Bắc, đi vào ở cực Nam.","Điểm đang xét ở gần cực Bắc."],"kq":"Đường sức từ có chiều đi ra khỏi nam châm tại đó."},"nham":["Bên ngoài nam châm, đường sức đi từ cực Nam sang cực Bắc → SAI."],"lq":["l7-tu-pho","l7-tu-truong","l7-la-ban"],"hinh":"H-l7-duong-suc-tu","nguon":["KHTN Pocket"]},{"ma":"l7-la-ban","mon":"KHTN","khoi":"7","chu_de":"l7-tu","thu_tu":8,"loai":"tn","ten":"La bàn","ten_khac":["la ban","compass","kim la ban","xac dinh phuong huong","tim huong bac","dung la ban"],"noi_dung":"Dụng cụ xác định hướng, gồm kim nam châm quay tự do trên trục và mặt có chia độ, ghi các hướng.","cong_thuc":null,"y":["Cách dùng: đặt la bàn nằm ngang, xa sắt thép và nam châm; xoay vỏ cho vạch N trùng đầu Bắc của kim rồi đọc hướng.","Dùng khi đi biển, đi rừng, hàng không.","Tự làm: cọ kim khâu vào nam châm theo một chiều, cắm lên miếng xốp thả nổi trên nước."],"bang":null,"bien":null,"vd":{"de":"Kim la bàn đang chỉ hướng Bắc thì đưa một thanh nam châm mạnh lại gần, kim la bàn lệch sang hướng khác. Vì sao?","buoc":["Kim la bàn định hướng theo từ trường mạnh nhất tác dụng lên nó.","Từ trường của thanh nam châm ở gần mạnh hơn từ trường Trái Đất tại đó."],"kq":"Kim la bàn lệch theo hướng từ trường của thanh nam châm vì nó mạnh hơn từ trường Trái Đất."},"nham":["Đặt la bàn gần vật bằng sắt → kim bị lệch, đọc sai hướng."],"lq":["l7-tu-truong-trai-dat","l7-nam-cham","l7-cuc-tu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-tu-truong-trai-dat","mon":"KHTN","khoi":"7","chu_de":"l7-tu","thu_tu":9,"loai":"kn","ten":"Từ trường Trái Đất","ten_khac":["tu truong trai dat","cuc tu trai dat","trai dat la nam cham","bac dia li","cuc dia li"],"noi_dung":"Trái Đất có từ trường, giống như một nam châm khổng lồ, nên kim la bàn luôn chỉ hướng Bắc – Nam.","cong_thuc":null,"y":["Cực từ của Trái Đất ở gần nhưng <b>không trùng</b> với cực địa lí.","Cực Bắc của kim la bàn chỉ về phía Bắc địa lí."],"bang":null,"bien":null,"vd":{"de":"Không có nam châm nào ở gần nhưng kim la bàn vẫn luôn chỉ về hướng Bắc – Nam. Vì sao?","buoc":["Trái Đất có từ trường, giống như một nam châm khổng lồ.","Kim la bàn (là kim nam châm nhỏ) chịu tác dụng của từ trường này."],"kq":"Do từ trường Trái Đất tác dụng lên kim la bàn."},"nham":["Cực từ trùng với cực địa lí → SAI."],"lq":["l7-la-ban","l7-tu-truong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-tu-truong-dong-dien","mon":"KHTN","khoi":"7","chu_de":"l7-tu","thu_tu":10,"loai":"ht","ten":"Từ trường của dòng điện","ten_khac":["tu truong cua dong dien","dong dien sinh ra tu truong","tu truong ong day","ong day co dong dien","kim lech khi co dien"],"noi_dung":"Xung quanh dây dẫn có dòng điện chạy qua có từ trường, làm kim nam châm đặt gần bị lệch.","cong_thuc":null,"y":["Đóng mạch: kim nam châm gần dây dẫn bị lệch; ngắt mạch: kim trở về hướng cũ.","<b>Ống dây</b> có dòng điện có từ trường giống từ trường của nam châm thẳng."],"bang":null,"bien":null,"vd":{"de":"Đặt một kim nam châm nhỏ gần một dây dẫn thẳng đang không có dòng điện, kim đứng yên. Cho dòng điện chạy qua dây, kim bị lệch. Hiện tượng này chứng tỏ điều gì?","buoc":["Kim chỉ lệch khi có tác dụng lực từ.","Kim chỉ lệch sau khi có dòng điện chạy qua dây dẫn."],"kq":"Chứng tỏ xung quanh dây dẫn có dòng điện xuất hiện từ trường."},"nham":null,"lq":["l7-nam-cham-dien","l7-tu-truong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-nam-cham-dien","mon":"KHTN","khoi":"7","chu_de":"l7-tu","thu_tu":11,"loai":"cq","ten":"Nam châm điện","ten_khac":["nam cham dien","ong day loi sat","loi sat non","che tao nam cham dien","electromagnet","can cau dien","chuong dien"],"noi_dung":"Gồm ống dây dẫn quấn quanh lõi sắt non; có từ tính khi có dòng điện chạy qua, mất từ tính khi ngắt điện.","cong_thuc":null,"y":["Mạnh hơn khi <b>tăng số vòng dây</b> hoặc <b>tăng dòng điện</b> (thêm pin).","Đổi chiều dòng điện thì hai cực đổi chỗ.","Ưu điểm: bật, tắt được từ tính. Dùng trong cần cẩu điện, chuông điện, rơ le, khoá điện từ.","Thí nghiệm: mỗi lần chỉ thay đổi <b>một yếu tố</b>, đếm số kẹp giấy bị hút."],"bang":null,"bien":null,"vd":{"de":"Ở cần cẩu phế liệu tại bãi sắt vụn, người ta cần hút rồi nhả kim loại ngay khi cần. Nên dùng nam châm vĩnh cửu hay nam châm điện?","buoc":["Nam châm điện có từ tính khi có dòng điện chạy qua, mất từ tính khi ngắt điện.","Nam châm vĩnh cửu luôn có từ tính, không thể chủ động nhả vật ngay lập tức."],"kq":"Dùng nam châm điện, để ngắt điện là nhả được kim loại."},"nham":["Nam châm điện lúc nào cũng có từ tính → SAI.","Dùng dây đồng trần không vỏ cách điện → các vòng chạm nhau, không hoạt động đúng."],"lq":["l7-tu-truong-dong-dien","l7-vat-lieu-tu","l7-nam-cham"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-khoi-luong-rieng","mon":"KHTN","khoi":"8","chu_de":"l8-ap-suat","thu_tu":1,"loai":"dl","ten":"Khối lượng riêng","ten_khac":["khoi luong rieng","klr","d","m/v","density","khoi luong tren the tich","kg/m3","g/cm3"],"noi_dung":"Khối lượng của một đơn vị thể tích chất, cho biết chất đó \"nặng\" hay \"nhẹ\".","cong_thuc":"D = m/V","y":["Mỗi chất có một khối lượng riêng xác định (ở cùng điều kiện).","Đơn vị thường dùng: <b>kg/m³</b> và g/cm³; 1 g/cm³ = 1 000 kg/m³.","Biết D và V tính được khối lượng: <b>m = D·V</b>."],"bang":[["Chất","D (kg/m³)"],["Nước","1 000"],["Dầu ăn","≈ 800"],["Nhôm","2 700"],["Sắt","7 800"],["Chì","11 300"]],"bien":[["D","khối lượng riêng","kg/m³"],["m","khối lượng","kg"],["V","thể tích","m³"]],"vd":{"de":"Một khối nhôm có thể tích 0,002 m³, khối lượng 5,4 kg. Tính khối lượng riêng của nhôm.","buoc":["D = m/V = 5,4 : 0,002"],"kq":"D = 2 700 kg/m³"},"nham":["Quên đổi cm³ sang m³ (1 m³ = 1 000 000 cm³).","Nhầm \"vật to thì khối lượng riêng lớn\": D chỉ phụ thuộc chất làm vật."],"lq":["l8-do-khoi-luong-rieng","l8-trong-luong-rieng","l8-luc-day-archimedes","l8-su-noi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-trong-luong-rieng","mon":"KHTN","khoi":"8","chu_de":"l8-ap-suat","thu_tu":2,"loai":"dl","ten":"Trọng lượng riêng","ten_khac":["trong luong rieng","tlr","d = 10d","p/v","n/m3","specific weight"],"noi_dung":"Trọng lượng của một đơn vị thể tích chất, đo bằng N/m³.","cong_thuc":"d = P/V; d = 10·D","y":["Vì P = 10·m nên <b>d = 10·D</b>.","Trọng lượng riêng của nước khoảng <b>10 000 N/m³</b>.","Dùng trong công thức áp suất chất lỏng và lực đẩy Archimedes."],"bang":null,"bien":[["d","trọng lượng riêng","N/m³"],["P","trọng lượng","N"],["V","thể tích","m³"],["D","khối lượng riêng","kg/m³"]],"vd":{"de":"Khối lượng riêng của sắt là 7 800 kg/m³. Tính trọng lượng riêng của sắt.","buoc":["d = 10·D = 10 · 7 800"],"kq":"d = 78 000 N/m³"},"nham":["Nhầm kí hiệu d (trọng lượng riêng, chữ thường) với D (khối lượng riêng, chữ hoa)."],"lq":["l8-khoi-luong-rieng","l8-ap-suat-chat-long","l8-luc-day-archimedes"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-do-khoi-luong-rieng","mon":"KHTN","khoi":"8","chu_de":"l8-ap-suat","thu_tu":3,"loai":"tn","ten":"Đo khối lượng riêng","ten_khac":["do khoi luong rieng","xac dinh khoi luong rieng","thuc hanh khoi luong rieng","binh chia do","can","binh tran"],"noi_dung":"Đo khối lượng m bằng cân, đo thể tích V bằng bình chia độ rồi tính D = m/V.","cong_thuc":null,"y":["<b>Chất lỏng:</b> cân bình rỗng, rót chất lỏng vào bình chia độ đọc V, cân lại để tìm m.","<b>Vật rắn hình hộp:</b> đo các cạnh bằng thước để tính V, cân để có m.","<b>Vật rắn bất kì, không thấm nước:</b> thả chìm vào bình chia độ; thể tích nước dâng lên bằng V của vật.","Đo nhiều lần, lấy giá trị trung bình để giảm sai số."],"bang":null,"bien":null,"vd":{"de":"Muốn đo khối lượng riêng của một hòn đá nhỏ, cần đo hai đại lượng nào và bằng dụng cụ gì?","buoc":["D = m/V nên cần biết khối lượng m và thể tích V của hòn đá.","Đo m bằng cân; đo V bằng bình chia độ (thả đá vào nước, đo thể tích nước dâng lên)."],"kq":"Đo khối lượng bằng cân, đo thể tích bằng bình chia độ, rồi tính D = m/V."},"nham":["Đọc mực nước không ngang tầm mắt.","Dùng cách bình chia độ với vật thấm nước hoặc vật nổi."],"lq":["l8-khoi-luong-rieng","l8-trong-luong-rieng"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-ap-luc","mon":"KHTN","khoi":"8","chu_de":"l8-ap-suat","thu_tu":4,"loai":"kn","ten":"Áp lực","ten_khac":["ap luc","luc ep","luc vuong goc","pressure force","f"],"noi_dung":"Lực ép có phương vuông góc với mặt bị ép.","cong_thuc":null,"y":["Ví dụ: trọng lượng của người đứng trên sàn, lực của ngón tay ấn đinh ghim.","Tác dụng của áp lực càng lớn khi <b>áp lực càng lớn</b> và <b>diện tích bị ép càng nhỏ</b>.","Đo bằng đơn vị lực: niutơn (N)."],"bang":null,"bien":null,"vd":{"de":"Một quyển sách đặt trên mặt bàn nằm ngang. Trọng lượng của sách có phải là áp lực lên mặt bàn không?","buoc":["Áp lực là lực ép có phương vuông góc với mặt bị ép.","Trọng lượng sách có phương thẳng đứng, vuông góc với mặt bàn nằm ngang."],"kq":"Có; trọng lượng của sách chính là áp lực lên mặt bàn."},"nham":["Coi mọi lực là áp lực: lực kéo song song mặt sàn không phải áp lực."],"lq":["l8-ap-suat","l8-tang-giam-ap-suat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-ap-suat","mon":"KHTN","khoi":"8","chu_de":"l8-ap-suat","thu_tu":5,"loai":"dl","ten":"Áp suất","ten_khac":["ap suat","p = f/s","p=f/s","f/s","pressure","ap suat chat ran","pa"],"noi_dung":"Độ lớn của áp lực trên một đơn vị diện tích bị ép.","cong_thuc":"p = F/S","y":["Áp suất tăng khi <b>tăng áp lực</b> hoặc <b>giảm diện tích bị ép</b>.","Đơn vị: <b>pascal (Pa)</b>, 1 Pa = 1 N/m².","Suy ra: F = p·S; S = F/p."],"bang":null,"bien":[["p","áp suất","Pa (N/m²)"],["F","áp lực","N"],["S","diện tích bị ép","m²"]],"vd":{"de":"Một người nặng 600 N đứng trên sàn, diện tích tiếp xúc của hai bàn chân là 0,03 m². Tính áp suất lên sàn.","buoc":["p = F/S = 600 : 0,03"],"kq":"p = 20 000 Pa"},"nham":["Quên đổi cm² sang m² (1 m² = 10 000 cm²).","Đứng một chân thì diện tích bị ép giảm một nửa, áp suất tăng gấp đôi."],"lq":["l8-ap-luc","l8-pascal","l8-tang-giam-ap-suat","l8-ap-suat-chat-long"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-pascal","mon":"KHTN","khoi":"8","chu_de":"l8-ap-suat","thu_tu":6,"loai":"dl","ten":"Pascal (Pa)","ten_khac":["pascal","pa","n/m2","don vi ap suat","atm","mmhg","bar"],"noi_dung":"Đơn vị đo áp suất trong hệ SI: 1 Pa là áp suất của lực 1 N ép vuông góc lên 1 m².","cong_thuc":null,"y":["<b>1 Pa = 1 N/m²</b>.","Đơn vị khác hay gặp: <b>atm</b> (1 atm ≈ 101 300 Pa), <b>mmHg</b> (1 mmHg ≈ 133 Pa), bar (1 bar = 100 000 Pa).","Pa là đơn vị nhỏ nên thường dùng kPa (1 kPa = 1 000 Pa)."],"bang":[["Đơn vị","Đổi ra Pa"],["1 kPa","1 000"],["1 bar","100 000"],["1 atm","≈ 101 300"],["1 mmHg","≈ 133"]],"bien":null,"vd":{"de":"Một lực 5 N ép vuông góc lên diện tích 2 m². Tính áp suất theo đơn vị Pascal.","buoc":["Công thức: p = F/S.","p = 5 : 2"],"kq":"p = 2,5 Pa"},"nham":null,"lq":["l8-ap-suat","l8-ap-suat-khi-quyen"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-tang-giam-ap-suat","mon":"KHTN","khoi":"8","chu_de":"l8-ap-suat","thu_tu":7,"loai":"ud","ten":"Tăng, giảm áp suất","ten_khac":["tang ap suat","giam ap suat","ung dung ap suat","mui dao sac","xe tang banh xich","dinh nhon"],"noi_dung":"Thay đổi áp lực hoặc diện tích bị ép để làm tăng hay giảm áp suất theo nhu cầu.","cong_thuc":null,"y":["<b>Tăng áp suất:</b> giảm diện tích bị ép (mài sắc dao, mũi đinh nhọn, mũi khoan) hoặc tăng áp lực.","<b>Giảm áp suất:</b> tăng diện tích bị ép (xe tăng có bánh xích, móng nhà rộng, ván lót khi đi trên bùn) hoặc giảm áp lực."],"bang":null,"bien":null,"vd":{"de":"Muốn cắm một chiếc đinh vào tường dễ dàng hơn, nên dùng đầu đinh nhọn hay đầu đinh tù?","buoc":["Áp suất p = F/S: cùng lực F, diện tích S càng nhỏ thì áp suất càng lớn.","Đầu đinh nhọn có diện tích tiếp xúc nhỏ hơn đầu đinh tù."],"kq":"Dùng đầu đinh nhọn để tăng áp suất, cắm dễ hơn."},"nham":["Nghĩ bánh xích làm xe nhẹ đi: trọng lượng không đổi, chỉ diện tích tiếp xúc tăng."],"lq":["l8-ap-suat","l8-ap-luc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-ap-suat-chat-long","mon":"KHTN","khoi":"8","chu_de":"l8-ap-suat","thu_tu":8,"loai":"ct","ten":"Áp suất chất lỏng","ten_khac":["ap suat chat long","p = d.h","p=dh","d.h","ap suat trong long chat long","do sau","lan sau"],"noi_dung":"Chất lỏng gây áp suất theo mọi phương lên đáy bình, thành bình và các vật trong lòng nó.","cong_thuc":"p = d·h (mở rộng)","y":["Càng xuống sâu, áp suất chất lỏng <b>càng lớn</b>.","Tại cùng một độ sâu trong cùng chất lỏng đứng yên, áp suất <b>như nhau</b> theo mọi phương.","Ứng dụng: đê, đập làm chân rộng hơn mặt; thợ lặn sâu phải mặc áo lặn chịu áp suất."],"bang":null,"bien":[["p","áp suất chất lỏng","Pa"],["d","trọng lượng riêng chất lỏng","N/m³"],["h","độ sâu tính từ mặt thoáng","m"]],"vd":{"de":"Tính áp suất của nước tại điểm sâu 2 m dưới mặt nước. Biết d nước = 10 000 N/m³.","buoc":["p = d·h = 10 000 · 2"],"kq":"p = 20 000 Pa"},"nham":["Lấy h là khoảng cách từ đáy bình lên, trong khi h phải tính từ mặt thoáng xuống."],"lq":["l8-binh-thong-nhau","l8-may-nen-thuy-luc","l8-trong-luong-rieng","l8-ap-suat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-binh-thong-nhau","mon":"KHTN","khoi":"8","chu_de":"l8-ap-suat","thu_tu":9,"loai":"cq","ten":"Bình thông nhau","ten_khac":["binh thong nhau","nhanh binh","mat thoang","am nuoc","ong do muc nuoc"],"noi_dung":"Bình có hai hay nhiều nhánh thông đáy với nhau; chất lỏng đứng yên thì mặt thoáng các nhánh ngang nhau.","cong_thuc":null,"y":["Chỉ đúng khi các nhánh chứa <b>cùng một chất lỏng</b> đứng yên.","Ứng dụng: vòi ấm nước và thân ấm, ống đo mực chất lỏng ngoài bình, tháp nước cấp nước cho nhà."],"bang":null,"bien":null,"vd":{"de":"Đổ nước vào một nhánh của bình thông nhau có hai nhánh. Sau khi nước đứng yên, mực nước ở hai nhánh so với nhau thế nào?","buoc":["Trong bình thông nhau, chất lỏng đứng yên thì mặt thoáng các nhánh ngang nhau.","Đây là tính chất chung, không phụ thuộc hình dạng hay tiết diện mỗi nhánh."],"kq":"Mực nước ở hai nhánh ngang bằng nhau."},"nham":["Nghĩ nhánh to chứa nhiều nước thì mực nước cao hơn."],"lq":["l8-ap-suat-chat-long","l8-may-nen-thuy-luc"],"hinh":"H-l8-binh-thong-nhau","nguon":["KHTN Pocket"]},{"ma":"l8-may-nen-thuy-luc","mon":"KHTN","khoi":"8","chu_de":"l8-ap-suat","thu_tu":10,"loai":"cq","ten":"Máy nén thủy lực","ten_khac":["may nen thuy luc","may ep thuy luc","kich thuy luc","con doi thuy luc","phanh dau","f/f = s/s"],"noi_dung":"Máy dùng chất lỏng truyền áp suất để lực nhỏ ở pít-tông nhỏ tạo ra lực lớn ở pít-tông lớn.","cong_thuc":"F/f = S/s (mở rộng)","y":["Chất lỏng truyền nguyên vẹn độ tăng áp suất đi mọi hướng.","Pít-tông lớn có diện tích gấp bao nhiêu lần thì lực nâng lớn gấp bấy nhiêu lần.","Ứng dụng: kích nâng ô tô, máy ép, phanh dầu."],"bang":null,"bien":[["F","lực ở pít-tông lớn","N"],["f","lực ở pít-tông nhỏ","N"],["S","diện tích pít-tông lớn","m²"],["s","diện tích pít-tông nhỏ","m²"]],"vd":{"de":"Pít-tông nhỏ có diện tích 2 cm², pít-tông lớn 200 cm². Tác dụng lực 100 N lên pít-tông nhỏ thì lực nâng ở pít-tông lớn là bao nhiêu?","buoc":["F = f·S/s = 100 · 200 : 2"],"kq":"F = 10 000 N"},"nham":["Nghĩ máy thủy lực \"tạo ra\" năng lượng: pít-tông nhỏ phải đi quãng đường dài hơn."],"lq":["l8-ap-suat-chat-long","l8-binh-thong-nhau","l8-ap-suat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-ap-suat-khi-quyen","mon":"KHTN","khoi":"8","chu_de":"l8-ap-suat","thu_tu":11,"loai":"kn","ten":"Áp suất khí quyển","ten_khac":["ap suat khi quyen","ap suat khong khi","khi quyen","atm","torricelli","760 mmhg","u tai"],"noi_dung":"Áp suất do lớp không khí bao quanh Trái Đất gây ra, tác dụng theo mọi phương lên mọi vật.","cong_thuc":null,"y":["Ở mặt biển, áp suất khí quyển khoảng <b>760 mmHg ≈ 101 300 Pa</b> (1 atm).","Càng lên cao, áp suất khí quyển <b>càng giảm</b>.","Khi áp suất bên ngoài thay đổi đột ngột (đi máy bay, lặn sâu), màng nhĩ bị ép lệch nên tai bị ù, có tiếng động trong tai."],"bang":null,"bien":null,"vd":{"de":"Hút hết không khí ra khỏi một hộp sữa giấy rỗng đã đậy kín, hộp bị móp méo lại. Vì sao?","buoc":["Áp suất khí quyển tác dụng theo mọi phương lên mọi vật.","Bên trong hộp gần như không còn không khí, áp suất bên ngoài lớn hơn hẳn bên trong nên ép hộp móp lại."],"kq":"Do áp suất khí quyển bên ngoài lớn hơn áp suất bên trong hộp."},"nham":["Nghĩ không khí không có trọng lượng nên không gây áp suất."],"lq":["l8-ung-dung-ap-suat-khi-quyen","l8-pascal","l8-ap-suat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-ung-dung-ap-suat-khi-quyen","mon":"KHTN","khoi":"8","chu_de":"l8-ap-suat","thu_tu":12,"loai":"ud","ten":"Ứng dụng áp suất khí quyển","ten_khac":["ung dung ap suat khi quyen","giac mut","ong hut","bom tiem","ong nho giot","hop sua"],"noi_dung":"Nhiều dụng cụ hoạt động nhờ chênh lệch giữa áp suất khí quyển bên ngoài và áp suất bên trong.","cong_thuc":null,"y":["<b>Ống hút:</b> hút làm giảm áp suất trong ống, áp suất khí quyển đẩy nước lên.","<b>Giác mút:</b> ép hết không khí ra, áp suất khí quyển giữ giác mút dính vào tường.","Bơm tiêm, ống nhỏ giọt lấy chất lỏng lên cũng nhờ áp suất khí quyển.","Nắp ấm trà có lỗ nhỏ để nước rót ra dễ dàng."],"bang":null,"bien":null,"vd":{"de":"Khi dùng ống hút để uống nước, ta hút bớt không khí trong ống. Nước dâng lên trong ống là nhờ đâu?","buoc":["Hút bớt không khí làm áp suất trong ống giảm xuống.","Áp suất khí quyển bên ngoài (lớn hơn) ép lên mặt nước, đẩy nước dâng lên trong ống."],"kq":"Nhờ áp suất khí quyển ép nước dâng lên trong ống hút."},"nham":null,"lq":["l8-ap-suat-khi-quyen","l8-ap-suat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-luc-day-archimedes","mon":"KHTN","khoi":"8","chu_de":"l8-ap-suat","thu_tu":13,"loai":"ct","ten":"Lực đẩy Archimedes","ten_khac":["luc day archimedes","luc day acsimet","acsimet","archimedes","fa","f = d.v","luc day chat long","dinh luat archimedes"],"noi_dung":"Lực chất lỏng đẩy vật nhúng trong nó, hướng thẳng đứng từ dưới lên, bằng trọng lượng phần chất lỏng bị vật chiếm chỗ.","cong_thuc":"F_A = d·V","y":["Phương <b>thẳng đứng</b>, chiều <b>từ dưới lên</b>.","Độ lớn phụ thuộc <b>d của chất lỏng</b> và <b>thể tích phần chìm</b>, không phụ thuộc chất làm vật.","Chất khí cũng tác dụng lực đẩy Archimedes (khinh khí cầu).","Đo bằng lực kế: F_A = P ngoài không khí − P khi nhúng trong chất lỏng."],"bang":null,"bien":[["F_A","lực đẩy Archimedes","N"],["d","trọng lượng riêng chất lỏng","N/m³"],["V","thể tích phần chất lỏng bị vật chiếm chỗ","m³"]],"vd":{"de":"Một vật có thể tích 0,002 m³ chìm hoàn toàn trong nước (d = 10 000 N/m³). Tính lực đẩy Archimedes.","buoc":["F_A = d·V = 10 000 · 0,002"],"kq":"F_A = 20 N"},"nham":["Lấy d là trọng lượng riêng của vật thay vì của chất lỏng.","Vật nổi một phần: V chỉ là thể tích phần chìm."],"lq":["l8-su-noi","l8-trong-luong-rieng","l8-ung-dung-su-noi","l8-khoi-luong-rieng"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-su-noi","mon":"KHTN","khoi":"8","chu_de":"l8-ap-suat","thu_tu":14,"loai":"ht","ten":"Sự nổi","ten_khac":["su noi","vat noi vat chim","dieu kien noi","lo lung","chim","noi len"],"noi_dung":"Vật nhúng trong chất lỏng nổi lên, lơ lửng hay chìm xuống tùy so sánh trọng lượng P với lực đẩy Archimedes F_A.","cong_thuc":null,"y":["<b>P > F_A</b>: vật chìm xuống.","<b>P = F_A</b>: vật lơ lửng.","<b>P < F_A</b>: vật nổi lên; khi nổi yên trên mặt thì F_A = P.","So sánh nhanh: D vật > D chất lỏng thì chìm; D vật < D chất lỏng thì nổi."],"bang":[["So sánh","Kết quả"],["P > F_A","chìm"],["P = F_A","lơ lửng"],["P < F_A","nổi lên"]],"bien":null,"vd":{"de":"Một khúc gỗ có trọng lượng P = 8 N; khi nhúng chìm hoàn toàn trong nước, lực đẩy Archimedes lớn nhất có thể đạt F_A = 12 N. Khúc gỗ sẽ nổi, lơ lửng hay chìm?","buoc":["So sánh P với F_A khi vật chìm hoàn toàn: P = 8 N, F_A = 12 N.","Vì P nhỏ hơn F_A lúc chìm hết nên gỗ chỉ cần chìm một phần là đã cân bằng được trọng lượng."],"kq":"Khúc gỗ nổi lên (nổi một phần trên mặt nước)."},"nham":["Nghĩ vật nặng thì luôn chìm: tàu thép nặng vẫn nổi vì rỗng, chiếm chỗ nhiều nước."],"lq":["l8-luc-day-archimedes","l8-ung-dung-su-noi","l8-khoi-luong-rieng"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-ung-dung-su-noi","mon":"KHTN","khoi":"8","chu_de":"l8-ap-suat","thu_tu":15,"loai":"ud","ten":"Ứng dụng sự nổi","ten_khac":["ung dung su noi","tau thuy","tau ngam","phao boi","khinh khi cau","ao phao"],"noi_dung":"Điều chỉnh trọng lượng hoặc thể tích chiếm chỗ để vật nổi, lơ lửng hay chìm theo ý muốn.","cong_thuc":null,"y":["<b>Tàu thủy</b> bằng thép nổi được vì thân rỗng, chiếm chỗ một thể tích nước lớn.","<b>Tàu ngầm</b> bơm nước vào khoang để lặn, bơm nước ra để nổi.","<b>Phao, áo phao</b> có khối lượng riêng nhỏ giúp người nổi.","<b>Khinh khí cầu</b> bay lên nhờ lực đẩy Archimedes của không khí."],"bang":null,"bien":null,"vd":{"de":"Tàu ngầm bơm nước vào các khoang chứa để chìm xuống, và bơm nước ra để nổi lên. Vì sao làm vậy lại thay đổi được trạng thái nổi, chìm của tàu?","buoc":["Nổi hay chìm phụ thuộc so sánh trọng lượng tàu P với lực đẩy Archimedes F_A.","Bơm nước vào hay ra làm thay đổi khối lượng (trọng lượng) của tàu mà không đổi nhiều thể tích tàu."],"kq":"Vì thay đổi trọng lượng tàu làm thay đổi tương quan giữa P và F_A."},"nham":null,"lq":["l8-su-noi","l8-luc-day-archimedes"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-tac-dung-lam-quay","mon":"KHTN","khoi":"8","chu_de":"l8-moment","thu_tu":1,"loai":"kn","ten":"Tác dụng làm quay của lực","ten_khac":["tac dung lam quay","lam quay","truc quay","quay quanh truc","mo cua","co le"],"noi_dung":"Lực tác dụng lên vật có trục quay có thể làm vật quay quanh trục đó.","cong_thuc":null,"y":["Lực có giá <b>song song</b> hoặc <b>đi qua</b> trục quay thì không làm vật quay.","Lực càng lớn và giá của lực càng <b>xa trục quay</b> thì tác dụng làm quay càng mạnh.","Ví dụ: mở cửa, vặn ốc bằng cờ lê, bập bênh."],"bang":null,"bien":null,"vd":{"de":"Đẩy vào cánh cửa ở vị trí gần bản lề so với đẩy ở mép cửa xa bản lề, với cùng độ lớn lực, trường hợp nào cửa quay dễ hơn?","buoc":["Tác dụng làm quay của lực phụ thuộc vào khoảng cách từ trục quay đến giá của lực (cánh tay đòn).","Đẩy ở mép cửa xa bản lề có cánh tay đòn dài hơn."],"kq":"Đẩy ở mép cửa xa bản lề làm cửa quay dễ hơn."},"nham":["Đẩy cửa ở gần bản lề thấy khó mở hơn đẩy ở mép cửa, vì giá lực gần trục quay."],"lq":["l8-moment-luc","l8-don-bay"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-moment-luc","mon":"KHTN","khoi":"8","chu_de":"l8-moment","thu_tu":2,"loai":"dl","ten":"Moment lực","ten_khac":["moment luc","momen luc","moment","m = f.d","canh tay don","n.m","torque"],"noi_dung":"Đại lượng đặc trưng cho tác dụng làm quay của lực quanh một điểm hoặc một trục.","cong_thuc":"M = F·d (mở rộng)","y":["Moment lực càng lớn khi lực càng lớn và <b>cánh tay đòn</b> càng dài.","Cánh tay đòn là khoảng cách <b>vuông góc</b> từ trục quay đến giá của lực.","Lực có giá đi qua trục quay có d = 0 nên M = 0: không làm vật quay."],"bang":null,"bien":[["M","moment lực","N·m"],["F","độ lớn lực","N"],["d","cánh tay đòn: khoảng cách từ trục quay đến giá của lực","m"]],"vd":{"de":"Dùng cờ lê dài 0,3 m, tác dụng lực 20 N vuông góc với cán ở đầu cờ lê. Tính moment lực.","buoc":["M = F·d = 20 · 0,3"],"kq":"M = 6 N·m"},"nham":["Lấy d là khoảng cách từ trục đến điểm đặt lực khi lực không vuông góc với thanh."],"lq":["l8-tac-dung-lam-quay","l8-don-bay"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-don-bay","mon":"KHTN","khoi":"8","chu_de":"l8-moment","thu_tu":3,"loai":"cq","ten":"Đòn bẩy","ten_khac":["don bay","diem tua","lever","o o1 o2","can bang don bay","f1.d1 = f2.d2"],"noi_dung":"Vật rắn quay được quanh một điểm tựa cố định, dùng để nâng vật hoặc đổi hướng lực.","cong_thuc":"F1·d1 = F2·d2 (mở rộng)","y":["Ba yếu tố: <b>điểm tựa O</b>, điểm tác dụng lực O1, điểm đặt vật O2.","Đòn bẩy cân bằng khi moment hai lực bằng nhau: F1·d1 = F2·d2.","Khoảng cách từ O đến lực tác dụng <b>lớn hơn</b> khoảng cách đến vật thì được lợi về lực."],"bang":null,"bien":[["F1","lực tác dụng (lực của người)","N"],["d1","khoảng cách từ điểm tựa O đến giá lực F1","m"],["F2","trọng lượng vật cần nâng","N"],["d2","khoảng cách từ điểm tựa O đến giá lực F2","m"]],"vd":{"de":"Trên bập bênh, bạn A nặng 300 N ngồi cách điểm tựa 1,5 m. Bạn B nặng 450 N phải ngồi cách điểm tựa bao xa để bập bênh cân bằng?","buoc":["300 · 1,5 = 450 · d2","d2 = 450 : 450"],"kq":"d2 = 1 m"},"nham":["Được lợi về lực thì thiệt về đường đi, không lợi về công."],"lq":["l8-cac-loai-don-bay","l8-ung-dung-don-bay","l8-moment-luc"],"hinh":"H-l8-don-bay","nguon":["KHTN Pocket"]},{"ma":"l8-cac-loai-don-bay","mon":"KHTN","khoi":"8","chu_de":"l8-moment","thu_tu":4,"loai":"kn","ten":"Các loại đòn bẩy","ten_khac":["cac loai don bay","don bay loai 1","don bay loai 2","phan loai don bay","loai don bay"],"noi_dung":"Đòn bẩy được chia theo vị trí điểm tựa O so với điểm tác dụng lực O1 và điểm đặt vật O2.","cong_thuc":null,"y":["<b>Loại 1:</b> điểm tựa O nằm giữa O1 và O2 (bập bênh, kéo cắt giấy, xà beng nạy đinh).","<b>Loại 2:</b> điểm tựa O nằm ở một đầu, O1 và O2 cùng một phía.","Loại 2, vật ở giữa (xe cút kít, cái kẹp hạt): luôn lợi về lực.","Loại 2, lực ở giữa (cần câu, cẳng tay người, gắp than): thiệt về lực nhưng lợi về đường đi."],"bang":[["Loại","Vị trí","Ví dụ"],["1","O ở giữa","bập bênh, kéo"],["2 (vật giữa)","O2 ở giữa","xe cút kít"],["2 (lực giữa)","O1 ở giữa","cẳng tay, cần câu"]],"bien":null,"vd":{"de":"Cái kéo có điểm tựa (trục quay) nằm giữa tay cầm (nơi tác dụng lực) và lưỡi kéo (nơi tác dụng lên vật). Đây là loại đòn bẩy có đặc điểm gì?","buoc":["Đòn bẩy được chia theo vị trí điểm tựa O so với điểm tác dụng lực và điểm đặt vật.","Ở cái kéo, điểm tựa nằm ở giữa hai điểm còn lại."],"kq":"Đây là đòn bẩy có điểm tựa nằm giữa điểm đặt lực và điểm đặt vật."},"nham":["Nhiều tài liệu chia 3 loại đòn bẩy; hai kiểu của loại 2 ở đây tương ứng loại 2 và loại 3 của cách chia đó."],"lq":["l8-don-bay","l8-ung-dung-don-bay"],"hinh":"H-l8-cac-loai-don-bay","nguon":["KHTN Pocket"]},{"ma":"l8-ung-dung-don-bay","mon":"KHTN","khoi":"8","chu_de":"l8-moment","thu_tu":5,"loai":"ud","ten":"Ứng dụng đòn bẩy","ten_khac":["ung dung don bay","xa beng","xe cut kit","bap benh","cai keo","tay nguoi","cai kim"],"noi_dung":"Đòn bẩy giúp nâng vật nặng bằng lực nhỏ hoặc thay đổi hướng và tăng quãng đường của lực.","cong_thuc":null,"y":["Dụng cụ: kéo, kìm, xà beng, xe cút kít, búa nhổ đinh, cần kéo nước (cần vọt).","Cơ thể người: cẳng tay khi co tay nâng vật, bàn chân khi kiễng gót.","Muốn đỡ tốn sức, đặt vật <b>gần điểm tựa</b> và tác dụng lực <b>xa điểm tựa</b>."],"bang":null,"bien":null,"vd":{"de":"Dùng một xà beng dài để bẩy một hòn đá nặng, tay đặt càng xa điểm tựa thì cần lực bẩy càng nhỏ hay càng lớn?","buoc":["Đòn bẩy giúp nâng vật nặng bằng lực nhỏ hơn khi cánh tay đòn của lực dài hơn.","Đặt tay càng xa điểm tựa thì cánh tay đòn của lực càng dài."],"kq":"Cần lực bẩy càng nhỏ."},"nham":null,"lq":["l8-don-bay","l8-cac-loai-don-bay","l8-moment-luc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-su-nhiem-dien","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":1,"loai":"ht","ten":"Sự nhiễm điện do cọ xát","ten_khac":["nhiem dien","su nhiem dien","co xat","nhiem dien do co xat","tinh dien","thuoc nhua hut giay","dien tich"],"noi_dung":"Nhiều vật sau khi cọ xát có khả năng hút các vật nhẹ; ta nói vật đó bị nhiễm điện.","cong_thuc":null,"y":["Ví dụ: thước nhựa cọ vào mảnh len hút được vụn giấy; lược chải tóc khô hút tóc.","<b>Giải thích:</b> khi cọ xát, một số <b>electron</b> dịch chuyển từ vật này sang vật kia.","Vật <b>nhận thêm electron</b> nhiễm điện âm; vật <b>mất bớt electron</b> nhiễm điện dương.","Sét là hiện tượng phóng điện giữa các đám mây nhiễm điện hoặc giữa mây và mặt đất."],"bang":null,"bien":null,"vd":{"de":"Sau khi dùng thước nhựa cọ xát vào tóc khô, đưa thước lại gần các mẩu giấy vụn, thấy mẩu giấy bị hút lên. Vì sao?","buoc":["Cọ xát có thể làm nhiều vật nhiễm điện.","Thước nhựa sau khi cọ xát nhiễm điện nên hút được các mẩu giấy nhẹ."],"kq":"Vì thước nhựa đã bị nhiễm điện do cọ xát."},"nham":["Nghĩ điện tích dương (hạt nhân) di chuyển khi cọ xát: chỉ electron di chuyển."],"lq":["l8-dien-tich","l8-dong-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-dien-tich","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":2,"loai":"kn","ten":"Điện tích","ten_khac":["dien tich","dien tich duong","dien tich am","electron","hut day","cung dau","trai dau","charge"],"noi_dung":"Có hai loại điện tích: dương (+) và âm (−); vật mang điện tích gọi là vật nhiễm điện.","cong_thuc":null,"y":["Điện tích <b>cùng loại đẩy nhau</b>, <b>khác loại hút nhau</b>.","Nguyên tử gồm hạt nhân mang điện dương và các <b>electron</b> mang điện âm; bình thường nguyên tử trung hòa về điện.","Quy ước: thanh thủy tinh cọ xát với lụa mang điện dương."],"bang":null,"bien":null,"vd":{"de":"Sau khi cọ xát, thanh thủy tinh nhiễm điện dương còn mảnh lụa nhiễm điện âm. Đưa lại gần nhau, chúng hút hay đẩy nhau?","buoc":["Có hai loại điện tích: dương và âm.","Hai vật mang điện tích khác loại (trái dấu) thì hút nhau."],"kq":"Thanh thủy tinh và mảnh lụa hút nhau."},"nham":["Nghĩ vật hút vụn giấy thì vụn giấy phải nhiễm điện trái dấu: vật nhiễm điện hút cả vật nhẹ không nhiễm điện."],"lq":["l8-su-nhiem-dien","l8-dong-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-dong-dien","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":3,"loai":"kn","ten":"Dòng điện","ten_khac":["dong dien","dong electron","hat mang dien","dich chuyen co huong","electric current","dong dien trong kim loai"],"noi_dung":"Dòng các hạt mang điện dịch chuyển có hướng.","cong_thuc":null,"y":["Trong kim loại, dòng điện là dòng các <b>electron tự do</b> dịch chuyển có hướng.","Dòng điện chạy trong mạch kín có nguồn điện.","Dấu hiệu có dòng điện: đèn sáng, quạt quay, dây dẫn nóng lên."],"bang":null,"bien":null,"vd":{"de":"Một bóng đèn pin sáng lên khi mạch kín có pin. Trong dây dẫn lúc đó có gì đang dịch chuyển có hướng?","buoc":["Dòng điện là dòng các hạt mang điện dịch chuyển có hướng.","Trong dây dẫn kim loại, các hạt mang điện đó là electron."],"kq":"Các hạt mang điện (electron) đang dịch chuyển có hướng trong dây dẫn."},"nham":["Nghĩ dòng điện là \"điện chảy như nước\" từ ổ cắm ra dù mạch hở."],"lq":["l8-chieu-dong-dien","l8-nguon-dien","l8-mach-dien","l8-cuong-do-dong-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-chieu-dong-dien","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":4,"loai":"kn","ten":"Chiều dòng điện","ten_khac":["chieu dong dien","chieu quy uoc","cuc duong sang cuc am","chieu electron"],"noi_dung":"Quy ước: chiều dòng điện là chiều từ cực dương qua dây dẫn và các dụng cụ điện tới cực âm của nguồn.","cong_thuc":null,"y":["Trên sơ đồ, chiều dòng điện được vẽ bằng mũi tên.","Electron trong dây kim loại dịch chuyển <b>ngược</b> chiều quy ước (từ cực âm về cực dương qua mạch ngoài)."],"bang":null,"bien":null,"vd":{"de":"Trong một mạch điện có pin, chiều dòng điện quy ước bên ngoài nguồn đi theo hướng nào: từ cực dương hay từ cực âm?","buoc":["Quy ước chiều dòng điện là chiều từ cực dương qua dây dẫn và dụng cụ điện tới cực âm.","Đây là chiều bên ngoài nguồn điện."],"kq":"Chiều dòng điện đi từ cực dương của pin qua mạch ngoài tới cực âm."},"nham":["Nhầm chiều dịch chuyển của electron với chiều quy ước của dòng điện."],"lq":["l8-dong-dien","l8-nguon-dien","l8-so-do-mach-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-nguon-dien","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":5,"loai":"cq","ten":"Nguồn điện","ten_khac":["nguon dien","pin","acquy","ac quy","cuc duong","cuc am","battery","pin mat troi"],"noi_dung":"Thiết bị cung cấp dòng điện lâu dài cho các dụng cụ điện hoạt động.","cong_thuc":null,"y":["Mỗi nguồn điện có <b>hai cực</b>: cực dương (+) và cực âm (−).","Ví dụ: pin, acquy, pin mặt trời, máy phát điện.","Số vôn ghi trên nguồn là hiệu điện thế giữa hai cực khi chưa mắc vào mạch."],"bang":null,"bien":null,"vd":{"de":"Ắc quy trong xe máy cung cấp dòng điện để khởi động xe và thắp đèn liên tục trong thời gian dài. Ắc quy đóng vai trò gì trong mạch điện?","buoc":["Nguồn điện là thiết bị cung cấp dòng điện lâu dài cho dụng cụ điện hoạt động.","Ắc quy cung cấp dòng điện liên tục cho các thiết bị trên xe."],"kq":"Ắc quy đóng vai trò là nguồn điện."},"nham":null,"lq":["l8-dong-dien","l8-mach-dien","l8-hieu-dien-the"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-vat-dan-dien","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":6,"loai":"ch","ten":"Vật dẫn điện","ten_khac":["vat dan dien","chat dan dien","dan dien","kim loai dan dien","day dong","conductor"],"noi_dung":"Vật cho dòng điện chạy qua.","cong_thuc":null,"y":["Ví dụ: kim loại (đồng, nhôm, sắt), than chì, dung dịch muối, nước sinh hoạt.","Lõi dây điện thường làm bằng <b>đồng</b> hoặc <b>nhôm</b>.","Cơ thể người cũng dẫn điện nên có thể bị điện giật."],"bang":null,"bien":null,"vd":{"de":"Trong các vật: thanh sắt, ống nhựa, dây đồng, cục tẩy cao su, những vật nào là vật dẫn điện?","buoc":["Vật dẫn điện là vật cho dòng điện chạy qua, thường là kim loại.","Trong danh sách, thanh sắt và dây đồng là kim loại."],"kq":"Thanh sắt và dây đồng là vật dẫn điện."},"nham":["Nghĩ nước lúc nào cũng cách điện: nước sinh hoạt, nước mưa có lẫn chất tan nên dẫn điện."],"lq":["l8-vat-cach-dien","l8-dong-dien","l8-an-toan-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-vat-cach-dien","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":7,"loai":"ch","ten":"Vật cách điện","ten_khac":["vat cach dien","chat cach dien","cach dien","nhua","cao su","su","insulator"],"noi_dung":"Vật không cho dòng điện chạy qua.","cong_thuc":null,"y":["Ví dụ: nhựa, cao su, sứ, thủy tinh, gỗ khô, không khí khô.","Dùng làm vỏ bọc dây điện, tay cầm dụng cụ điện, giá đỡ đường dây điện."],"bang":null,"bien":null,"vd":{"de":"Vì sao lõi dây điện làm bằng đồng nhưng vỏ bọc bên ngoài lại làm bằng nhựa hoặc cao su?","buoc":["Đồng là vật dẫn điện, dùng để dòng điện chạy qua.","Nhựa, cao su là vật cách điện, không cho dòng điện chạy qua, dùng để bảo vệ người dùng khỏi điện giật."],"kq":"Để lõi đồng dẫn điện, còn vỏ nhựa/cao su cách điện bảo vệ an toàn cho người sử dụng."},"nham":["Gỗ ướt, không khí ẩm có thể dẫn điện, không còn là vật cách điện tốt."],"lq":["l8-vat-dan-dien","l8-an-toan-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-mach-dien","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":8,"loai":"cq","ten":"Mạch điện","ten_khac":["mach dien","mach dien don gian","mach kin","mach ho","cong tac","day noi","bong den"],"noi_dung":"Gồm nguồn điện và các thiết bị điện (công tắc, bóng đèn…) nối với nhau bằng dây dẫn.","cong_thuc":null,"y":["Mạch đơn giản: <b>nguồn điện, công tắc, dây nối, bóng đèn</b>.","<b>Mạch kín</b> (công tắc đóng) thì có dòng điện; <b>mạch hở</b> thì không.","<b>Cầu chì</b> tự ngắt mạch khi dòng điện quá lớn, bảo vệ thiết bị."],"bang":null,"bien":null,"vd":{"de":"Một mạch điện gồm pin, công tắc, bóng đèn nối bằng dây dẫn thành vòng kín, đèn đang sáng. Nếu ngắt công tắc, đèn còn sáng không?","buoc":["Mạch điện gồm nguồn điện và các thiết bị nối với nhau bằng dây dẫn thành vòng kín.","Ngắt công tắc làm mạch bị hở, dòng điện không thể chạy qua."],"kq":"Đèn tắt vì mạch điện bị hở."},"nham":["Nối thẳng hai cực nguồn bằng dây không qua dụng cụ: gây đoản mạch, dây nóng, hỏng nguồn."],"lq":["l8-so-do-mach-dien","l8-nguon-dien","l8-dong-dien"],"hinh":"H-l8-mach-dien","nguon":["KHTN Pocket"]},{"ma":"l8-so-do-mach-dien","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":9,"loai":"kn","ten":"Sơ đồ mạch điện","ten_khac":["so do mach dien","ki hieu","ky hieu mach dien","ve so do","ki hieu bong den","ki hieu pin"],"noi_dung":"Hình vẽ mạch điện bằng các kí hiệu quy ước của từng bộ phận.","cong_thuc":null,"y":["Nguồn điện: vạch <b>dài</b> là cực dương, vạch <b>ngắn</b> là cực âm.","Dây nối vẽ bằng đoạn thẳng; chỗ hai dây nối nhau đánh dấu chấm đậm.","Từ sơ đồ có thể mắc mạch thật và ngược lại."],"bang":[["Bộ phận","Kí hiệu (mô tả)"],["Pin","một vạch dài, một vạch ngắn song song"],["Bộ pin/acquy","nhiều cặp vạch dài – ngắn nối tiếp"],["Công tắc","đoạn dây hở (mở) hoặc liền (đóng)"],["Bóng đèn","vòng tròn có dấu ×"],["Cầu chì","hình chữ nhật nhỏ có dây xuyên qua"],["Điốt phát quang (LED)","tam giác có vạch, kèm mũi tên ra ngoài"],["Ampe kế / Vôn kế","vòng tròn chữ A / chữ V"]],"bien":null,"vd":null,"nham":["Vẽ ngược cực nguồn: vạch dài mới là cực dương."],"lq":["l8-mach-dien","l8-chieu-dong-dien","l8-ampe-ke","l8-von-ke"],"hinh":"H-l8-so-do-mach-dien","nguon":["KHTN Pocket"]},{"ma":"l8-tac-dung-cua-dong-dien","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":10,"loai":"kn","ten":"Tác dụng của dòng điện","ten_khac":["tac dung cua dong dien","tac dung dong dien","5 tac dung","nam tac dung","tac dung dien"],"noi_dung":"Dòng điện có các tác dụng: nhiệt, phát sáng, từ, hóa học và sinh lí.","cong_thuc":null,"y":["Nhận biết có dòng điện qua các tác dụng của nó.","Một dụng cụ có thể có nhiều tác dụng cùng lúc: bóng đèn sợi đốt vừa nóng vừa sáng."],"bang":[["Tác dụng","Ví dụ"],["Nhiệt","bàn là, ấm điện"],["Phát sáng","đèn LED, bút thử điện"],["Từ","nam châm điện, chuông điện"],["Hóa học","mạ điện"],["Sinh lí","điện giật, máy kích thích tim"]],"bien":null,"vd":null,"nham":null,"lq":["l8-tac-dung-nhiet","l8-tac-dung-phat-sang","l8-tac-dung-tu","l8-tac-dung-hoa-hoc","l8-tac-dung-sinh-li"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-tac-dung-nhiet","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":11,"loai":"ht","ten":"Tác dụng nhiệt của dòng điện","ten_khac":["tac dung nhiet","dong dien lam nong","am dien","ban la","bep dien","may say toc"],"noi_dung":"Dòng điện chạy qua vật dẫn làm vật dẫn nóng lên.","cong_thuc":null,"y":["Có lợi: bàn là, bếp điện, ấm điện, nồi cơm điện, máy sấy tóc.","Có hại: dây dẫn, động cơ nóng lên gây hao phí năng lượng, có thể gây cháy.","Cầu chì hoạt động nhờ tác dụng nhiệt: dây chì nóng chảy khi dòng điện quá lớn."],"bang":null,"bien":null,"vd":{"de":"Bàn là quần áo khi cắm điện thì dây mayso bên trong nóng lên. Đây là tác dụng gì của dòng điện?","buoc":["Dòng điện chạy qua vật dẫn làm vật dẫn nóng lên.","Dây mayso nóng lên khi có dòng điện chạy qua."],"kq":"Đó là tác dụng nhiệt của dòng điện."},"nham":null,"lq":["l8-tac-dung-cua-dong-dien","l8-tac-dung-phat-sang","l8-an-toan-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-tac-dung-phat-sang","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":12,"loai":"ht","ten":"Tác dụng phát sáng","ten_khac":["tac dung phat sang","den led","but thu dien","den huynh quang","diot phat quang","phat sang"],"noi_dung":"Dòng điện có thể làm một số vật phát sáng, như đèn LED, đèn huỳnh quang, bút thử điện.","cong_thuc":null,"y":["<b>Đèn LED</b> (điốt phát quang) chỉ sáng khi dòng điện đi theo một chiều nhất định.","Bóng đèn bút thử điện sáng khi chạm vào dây có điện (dây nóng).","Đèn LED sáng nhưng ít nóng nên tiết kiệm điện hơn bóng sợi đốt."],"bang":null,"bien":null,"vd":{"de":"Đèn LED sáng khi có dòng điện chạy qua nhưng không nóng nhiều như đèn sợi đốt. Đây là tác dụng gì của dòng điện?","buoc":["Dòng điện có thể làm một số vật phát sáng, như đèn LED.","Ở đây tác dụng chủ yếu quan sát được là đèn phát sáng."],"kq":"Đó là tác dụng phát sáng của dòng điện."},"nham":null,"lq":["l8-tac-dung-cua-dong-dien","l8-tac-dung-nhiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-tac-dung-tu","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":13,"loai":"ht","ten":"Tác dụng từ của dòng điện","ten_khac":["tac dung tu","nam cham dien","chuong dien","dong dien va nam cham","kim nam cham lech"],"noi_dung":"Dòng điện làm lệch kim nam châm đặt gần dây dẫn và làm cuộn dây quấn quanh lõi sắt hút được sắt, thép (nam châm điện).","cong_thuc":null,"y":["Dòng điện làm <b>kim nam châm</b> đặt gần dây dẫn bị lệch.","Ngắt dòng điện thì nam châm điện mất từ tính.","Ứng dụng: chuông điện, cần cẩu điện, loa, động cơ điện."],"bang":null,"bien":null,"vd":{"de":"Đưa một kim nam châm nhỏ lại gần một cuộn dây có lõi sắt đang có dòng điện chạy qua, kim bị hút lệch. Đây là tác dụng gì của dòng điện?","buoc":["Dòng điện làm cuộn dây quấn quanh lõi sắt có từ tính, hút được kim nam châm.","Đây chính là nguyên lí của nam châm điện."],"kq":"Đó là tác dụng từ của dòng điện."},"nham":null,"lq":["l8-tac-dung-cua-dong-dien","l8-dong-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-tac-dung-hoa-hoc","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":14,"loai":"ht","ten":"Tác dụng hóa học","ten_khac":["tac dung hoa hoc","ma dien","ma dong","dien phan","copper sulfate","dung dich muoi dong"],"noi_dung":"Dòng điện chạy qua dung dịch muối kim loại có thể tách kim loại bám lên điện cực.","cong_thuc":null,"y":["Dòng điện qua dung dịch copper(II) sulfate làm thỏi than nối với <b>cực âm</b> được phủ một lớp đồng.","Ứng dụng: <b>mạ điện</b> (mạ đồng, mạ kẽm, mạ vàng), tinh chế kim loại, nạp acquy."],"bang":null,"bien":null,"vd":{"de":"Trong công nghiệp mạ điện, người ta cho dòng điện chạy qua dung dịch muối kim loại để phủ một lớp kim loại mỏng lên vật khác. Đây là tác dụng gì của dòng điện?","buoc":["Dòng điện chạy qua dung dịch muối kim loại có thể tách kim loại bám lên điện cực.","Mạ điện chính là ứng dụng của hiện tượng này."],"kq":"Đó là tác dụng hóa học của dòng điện."},"nham":["Nhầm kim loại bám vào cực dương: kim loại bám vào điện cực nối với cực âm."],"lq":["l8-tac-dung-cua-dong-dien","l8-vat-dan-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-tac-dung-sinh-li","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":15,"loai":"ht","ten":"Tác dụng sinh lí","ten_khac":["tac dung sinh li","tac dung sinh ly","dien giat","co co","y hoc","kich thich tim"],"noi_dung":"Dòng điện chạy qua cơ thể người và động vật làm co cơ, có thể gây nguy hiểm đến tính mạng.","cong_thuc":null,"y":["Dòng điện mạnh qua người gây <b>điện giật</b>: co giật, ngừng thở, tim ngừng đập, bỏng.","Dòng điện phù hợp được dùng trong y học: máy kích thích cơ, sốc điện tim."],"bang":null,"bien":null,"vd":{"de":"Khi vô tình chạm tay vào dây điện trần đang có dòng điện, cơ tay bị co giật mạnh, rất nguy hiểm. Đây là tác dụng gì của dòng điện đối với cơ thể?","buoc":["Dòng điện chạy qua cơ thể người và động vật làm co cơ.","Tác dụng này có thể gây nguy hiểm đến tính mạng nếu dòng điện đủ lớn."],"kq":"Đó là tác dụng sinh lí của dòng điện."},"nham":null,"lq":["l8-tac-dung-cua-dong-dien","l8-an-toan-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-cuong-do-dong-dien","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":16,"loai":"dl","ten":"Cường độ dòng điện","ten_khac":["cuong do dong dien","i","ampe","a","ma","miliampe","current"],"noi_dung":"Đại lượng cho biết độ mạnh, yếu của dòng điện; kí hiệu I, đo bằng ampe (A).","cong_thuc":null,"y":["Đơn vị: <b>ampe (A)</b>; miliampe: 1 mA = 0,001 A; 1 A = 1 000 mA.","Đo bằng <b>ampe kế</b> mắc nối tiếp trong mạch.","Dòng điện càng mạnh thì đèn càng sáng, dây càng nóng."],"bang":null,"bien":null,"vd":{"de":"Đổi 0,35 A và 1 250 mA sang đơn vị còn lại.","buoc":["0,35 A = 0,35 · 1 000 mA","1 250 mA = 1 250 : 1 000 A"],"kq":"0,35 A = 350 mA; 1 250 mA = 1,25 A"},"nham":["Nhầm cường độ dòng điện (A, ampe kế) với hiệu điện thế (V, vôn kế)."],"lq":["l8-ampe-ke","l8-hieu-dien-the","l8-dong-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-ampe-ke","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":17,"loai":"tn","ten":"Ampe kế","ten_khac":["ampe ke","ampere ke","do cuong do dong dien","mac noi tiep","ammeter","dong ho do dong"],"noi_dung":"Dụng cụ đo cường độ dòng điện, mắc nối tiếp với dụng cụ cần đo.","cong_thuc":null,"y":["Mắc <b>nối tiếp</b> với đoạn mạch cần đo.","Chốt (+) của ampe kế nối về phía <b>cực dương</b> của nguồn.","Chọn ampe kế có <b>giới hạn đo</b> lớn hơn cường độ cần đo; đọc số khi kim (số) ổn định.","Kí hiệu trên sơ đồ: vòng tròn có chữ A."],"bang":null,"bien":null,"vd":{"de":"Muốn đo cường độ dòng điện qua một bóng đèn, ampe kế phải được mắc như thế nào với bóng đèn?","buoc":["Ampe kế đo cường độ dòng điện, phải mắc nối tiếp với dụng cụ cần đo.","Mắc nối tiếp thì dòng điện qua ampe kế cũng chính là dòng điện qua đèn."],"kq":"Mắc ampe kế nối tiếp với bóng đèn."},"nham":["Mắc ampe kế song song hoặc thẳng vào hai cực nguồn: dễ làm hỏng ampe kế."],"lq":["l8-cuong-do-dong-dien","l8-von-ke","l8-so-do-mach-dien"],"hinh":"H-l8-ampe-ke","nguon":["KHTN Pocket"]},{"ma":"l8-hieu-dien-the","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":18,"loai":"dl","ten":"Hiệu điện thế","ten_khac":["hieu dien the","u","von","v","mv","kv","dien ap","voltage"],"noi_dung":"Giữa hai cực của nguồn điện có một hiệu điện thế; kí hiệu U, đo bằng vôn (V).","cong_thuc":null,"y":["Đơn vị: <b>vôn (V)</b>; 1 mV = 0,001 V; 1 kV = 1 000 V.","Đo bằng <b>vôn kế</b> mắc song song với hai đầu đoạn mạch.","Dụng cụ điện hoạt động bình thường khi dùng đúng <b>hiệu điện thế định mức</b> ghi trên nó (ví dụ 220 V)."],"bang":null,"bien":null,"vd":{"de":"Đổi 1,5 kV và 500 mV sang vôn.","buoc":["1,5 kV = 1,5 · 1 000 V","500 mV = 500 : 1 000 V"],"kq":"1,5 kV = 1 500 V; 500 mV = 0,5 V"},"nham":["Dùng thiết bị ghi 110 V ở mạng 220 V: thiết bị bị hỏng."],"lq":["l8-von-ke","l8-nguon-dien","l8-cuong-do-dong-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-von-ke","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":19,"loai":"tn","ten":"Vôn kế","ten_khac":["von ke","volt ke","do hieu dien the","mac song song","voltmeter"],"noi_dung":"Dụng cụ đo hiệu điện thế, mắc song song với hai đầu đoạn mạch cần đo.","cong_thuc":null,"y":["Mắc <b>song song</b> với hai đầu dụng cụ (hoặc hai cực nguồn) cần đo.","Chốt (+) nối về phía <b>cực dương</b> của nguồn.","Chọn giới hạn đo lớn hơn hiệu điện thế cần đo.","Kí hiệu trên sơ đồ: vòng tròn có chữ V."],"bang":null,"bien":null,"vd":{"de":"Muốn đo hiệu điện thế giữa hai đầu bóng đèn, vôn kế phải mắc như thế nào với đèn?","buoc":["Vôn kế đo hiệu điện thế, phải mắc song song với đoạn mạch cần đo.","Mắc song song thì vôn kế đo đúng hiệu điện thế hai đầu đèn mà không cản trở dòng điện qua đèn."],"kq":"Mắc vôn kế song song với bóng đèn."},"nham":["Mắc vôn kế nối tiếp trong mạch: đèn gần như không sáng, số đo sai."],"lq":["l8-hieu-dien-the","l8-ampe-ke","l8-so-do-mach-dien"],"hinh":"H-l8-von-ke","nguon":["KHTN Pocket"]},{"ma":"l8-mach-noi-tiep-i-u","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":20,"loai":"dl","ten":"I và U trong mạch nối tiếp","ten_khac":["mach noi tiep","noi tiep","i = i1 = i2","u = u1 + u2","hai den noi tiep","series circuit"],"noi_dung":"Trong mạch nối tiếp, cường độ dòng điện như nhau tại mọi điểm; hiệu điện thế hai đầu mạch bằng tổng hiệu điện thế trên từng dụng cụ.","cong_thuc":"I = I₁ = I₂ ; U = U₁ + U₂","y":["Cường độ dòng điện như nhau qua mọi dụng cụ: <b>I = I₁ = I₂</b>.","Hiệu điện thế chia cho các dụng cụ: <b>U = U₁ + U₂</b>.","Một đèn hỏng (đứt dây tóc) thì mạch hở, các đèn còn lại đều tắt."],"bang":null,"bien":[["I","cường độ dòng điện","A"],["U","hiệu điện thế","V"]],"vd":{"de":"Hai đèn mắc nối tiếp, U₁ = 2,5 V, U₂ = 3,5 V, ampe kế chỉ 0,3 A. Tính U và I₂.","buoc":["Nối tiếp: I₂ = I = 0,3 A","U = U₁ + U₂ = 2,5 + 3,5"],"kq":"I₂ = 0,3 A; U = 6 V"},"nham":["Cộng cường độ dòng điện trong mạch nối tiếp (nhầm với mạch song song)."],"lq":["l8-mach-song-song-i-u","l8-cuong-do-dong-dien","l8-hieu-dien-the"],"hinh":"H-l8-mach-noi-tiep-i-u","nguon":["KHTN Pocket"]},{"ma":"l8-mach-song-song-i-u","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":21,"loai":"dl","ten":"I và U trong mạch song song","ten_khac":["mach song song","song song","i = i1 + i2","u = u1 = u2","parallel circuit","mach re"],"noi_dung":"Trong mạch song song, hiệu điện thế hai đầu mỗi nhánh bằng nhau; cường độ dòng điện mạch chính bằng tổng cường độ các nhánh.","cong_thuc":"U = U₁ = U₂ ; I = I₁ + I₂","y":["Hiệu điện thế như nhau ở mọi nhánh: <b>U = U₁ = U₂</b>.","Dòng điện mạch chính chia cho các nhánh: <b>I = I₁ + I₂</b>.","Một đèn hỏng thì đèn ở nhánh kia vẫn sáng; mạch điện trong nhà mắc song song."],"bang":null,"bien":[["I","cường độ dòng điện","A"],["U","hiệu điện thế","V"]],"vd":{"de":"Hai đèn mắc song song vào nguồn 6 V; I₁ = 0,4 A, I₂ = 0,3 A. Tính U₁ và I mạch chính.","buoc":["Song song: U₁ = U = 6 V","I = I₁ + I₂ = 0,4 + 0,3"],"kq":"U₁ = 6 V; I = 0,7 A"},"nham":["Cộng hiệu điện thế các nhánh song song (nhầm với mạch nối tiếp)."],"lq":["l8-mach-noi-tiep-i-u","l8-cuong-do-dong-dien","l8-hieu-dien-the"],"hinh":"H-l8-mach-song-song-i-u","nguon":["KHTN Pocket"]},{"ma":"l8-an-toan-dien","mon":"KHTN","khoi":"8","chu_de":"l8-dien","thu_tu":22,"loai":"ud","ten":"An toàn điện","ten_khac":["an toan dien","dien giat","phong dien giat","su dung dien an toan","cau chi","aptomat"],"noi_dung":"Các quy tắc sử dụng điện để tránh điện giật, chập cháy và bảo vệ thiết bị.","cong_thuc":null,"y":["Không chạm tay trần vào dây trần, ổ điện; không dùng tay ướt cắm, rút phích điện.","Không thả diều, trèo cột gần đường dây điện; tránh xa dây điện bị đứt.","Dùng cầu chì, aptomat để ngắt mạch khi có sự cố.","Cứu người bị điện giật: <b>ngắt nguồn điện</b> trước, hoặc dùng vật cách điện khô tách người ra."],"bang":null,"bien":null,"vd":{"de":"Thấy dây điện trong nhà bị hở, lộ lõi đồng. Em cần làm gì để đảm bảo an toàn?","buoc":["Dây điện hở có thể gây điện giật hoặc chập cháy.","Quy tắc an toàn điện yêu cầu không tự ý chạm vào dây điện hở."],"kq":"Ngắt nguồn điện (cầu dao) và báo ngay cho người lớn để sửa chữa."},"nham":["Kéo tay trực tiếp người đang bị điện giật: người cứu cũng bị giật."],"lq":["l8-tac-dung-sinh-li","l8-vat-cach-dien","l8-mach-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-chuyen-dong-phan-tu","mon":"KHTN","khoi":"8","chu_de":"l8-nhiet","thu_tu":1,"loai":"kn","ten":"Chuyển động nhiệt của phân tử","ten_khac":["chuyen dong phan tu","chuyen dong nhiet","nguyen tu phan tu","khuech tan","chuyen dong hon loan","brown"],"noi_dung":"Các nguyên tử, phân tử cấu tạo nên chất chuyển động hỗn loạn không ngừng; nhiệt độ càng cao chúng chuyển động càng nhanh.","cong_thuc":null,"y":["Giữa các phân tử có <b>khoảng cách</b>; chất khí có khoảng cách lớn nhất.","Hiện tượng <b>khuếch tán</b> (mùi nước hoa lan tỏa, mực loang trong nước) chứng tỏ phân tử chuyển động.","Khuếch tán xảy ra <b>nhanh hơn</b> khi nhiệt độ cao hơn."],"bang":null,"bien":null,"vd":{"de":"Nhỏ một giọt mực vào cốc nước nóng và một giọt mực vào cốc nước lạnh có cùng thể tích. Cốc nào mực loang nhanh hơn?","buoc":["Nhiệt độ càng cao thì các phân tử chuyển động hỗn loạn càng nhanh.","Nước nóng có nhiệt độ cao hơn nước lạnh."],"kq":"Mực loang nhanh hơn trong cốc nước nóng."},"nham":null,"lq":["l8-nhiet-do","l8-nang-luong-nhiet","l8-noi-nang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-nhiet-do","mon":"KHTN","khoi":"8","chu_de":"l8-nhiet","thu_tu":2,"loai":"dl","ten":"Nhiệt độ","ten_khac":["nhiet do","t","do c","nhiet ke","nong lanh","temperature","kelvin"],"noi_dung":"Đại lượng cho biết mức độ nóng, lạnh của vật; liên quan đến tốc độ chuyển động của các phân tử.","cong_thuc":null,"y":["Nhiệt độ càng cao thì các phân tử chuyển động <b>càng nhanh</b>.","Đơn vị thường dùng: <b>°C</b>; trong SI dùng kelvin (K).","Đo bằng nhiệt kế."],"bang":null,"bien":null,"vd":{"de":"Cốc nước A ở 60 °C, cốc nước B ở 25 °C. Cốc nào có các phân tử nước chuyển động nhanh hơn?","buoc":["Nhiệt độ càng cao thì các phân tử chuyển động càng nhanh.","So sánh: cốc A có nhiệt độ cao hơn cốc B (60 °C > 25 °C)."],"kq":"Phân tử nước ở cốc A chuyển động nhanh hơn."},"nham":["Nhầm nhiệt độ với năng lượng nhiệt: ca nước sôi nóng hơn nhưng nồi nước ấm lớn có thể có năng lượng nhiệt lớn hơn."],"lq":["l8-chuyen-dong-phan-tu","l8-nang-luong-nhiet","l8-su-truyen-nhiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-nang-luong-nhiet","mon":"KHTN","khoi":"8","chu_de":"l8-nhiet","thu_tu":3,"loai":"kn","ten":"Năng lượng nhiệt","ten_khac":["nang luong nhiet","nhiet nang","nhiet luong","jun","j","thermal energy"],"noi_dung":"Năng lượng gắn với chuyển động nhiệt của các phân tử cấu tạo nên vật; nhiệt độ càng cao thì năng lượng nhiệt càng lớn.","cong_thuc":null,"y":["Đơn vị: <b>jun (J)</b>.","Phần năng lượng nhiệt vật nhận thêm hay mất bớt trong quá trình truyền nhiệt gọi là <b>nhiệt lượng</b>.","Đo năng lượng nhiệt vật nhận được khi đun bằng điện: dùng <b>joulemeter</b>."],"bang":null,"bien":null,"vd":{"de":"So sánh một cốc nước sôi 100 °C và một cốc nước 30 °C có cùng khối lượng. Cốc nào có năng lượng nhiệt lớn hơn?","buoc":["Năng lượng nhiệt gắn với chuyển động nhiệt của các phân tử; nhiệt độ càng cao thì năng lượng nhiệt càng lớn.","Cốc nước sôi có nhiệt độ cao hơn hẳn cốc nước 30 °C."],"kq":"Cốc nước sôi 100 °C có năng lượng nhiệt lớn hơn."},"nham":["Nghĩ vật lạnh không có năng lượng nhiệt: mọi vật đều có vì phân tử luôn chuyển động."],"lq":["l8-noi-nang","l8-nhiet-do","l8-joulemeter","l8-su-truyen-nhiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-noi-nang","mon":"KHTN","khoi":"8","chu_de":"l8-nhiet","thu_tu":4,"loai":"kn","ten":"Nội năng","ten_khac":["noi nang","dong nang phan tu","the nang phan tu","internal energy","thay doi noi nang"],"noi_dung":"Tổng động năng và thế năng của các phân tử cấu tạo nên vật.","cong_thuc":null,"y":["Nhiệt độ vật tăng thì các phân tử chuyển động nhanh hơn, <b>nội năng tăng</b>.","Nội năng có thể thay đổi bằng <b>truyền nhiệt</b> (đun nóng, làm lạnh) hoặc <b>thực hiện công</b> (cọ xát, nén khí).","Đơn vị: jun (J)."],"bang":null,"bien":null,"vd":{"de":"Khi cọ xát hai miếng kim loại vào nhau, chúng nóng lên. Nội năng của các miếng kim loại đã tăng hay giảm?","buoc":["Nội năng là tổng động năng và thế năng của các phân tử cấu tạo nên vật.","Cọ xát làm các phân tử chuyển động nhanh hơn (nóng lên), động năng phân tử tăng."],"kq":"Nội năng của các miếng kim loại tăng lên."},"nham":["Nhầm nội năng với cơ năng của cả vật: vật đứng yên vẫn có nội năng."],"lq":["l8-nang-luong-nhiet","l8-chuyen-dong-phan-tu","l8-su-truyen-nhiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-su-truyen-nhiet","mon":"KHTN","khoi":"8","chu_de":"l8-nhiet","thu_tu":5,"loai":"ht","ten":"Sự truyền nhiệt","ten_khac":["su truyen nhiet","truyen nhiet","nong sang lanh","can bang nhiet","heat transfer","cac hinh thuc truyen nhiet"],"noi_dung":"Năng lượng nhiệt truyền từ vật có nhiệt độ cao sang vật có nhiệt độ thấp hơn.","cong_thuc":null,"y":["Truyền nhiệt dừng lại khi hai vật có <b>nhiệt độ bằng nhau</b>.","Ba hình thức: <b>dẫn nhiệt</b>, <b>đối lưu</b>, <b>bức xạ nhiệt</b>."],"bang":[["Hình thức","Chủ yếu ở"],["Dẫn nhiệt","chất rắn"],["Đối lưu","chất lỏng, chất khí"],["Bức xạ nhiệt","chân không (cả chất khí)"]],"bien":null,"vd":{"de":"Thả một thìa kim loại lạnh vào cốc nước nóng. Nhiệt sẽ truyền theo chiều nào?","buoc":["Năng lượng nhiệt truyền từ vật có nhiệt độ cao sang vật có nhiệt độ thấp hơn.","Nước nóng hơn thìa kim loại lúc mới thả vào."],"kq":"Nhiệt truyền từ nước sang thìa kim loại."},"nham":["Nghĩ \"cái lạnh\" truyền từ đá sang tay: thực ra nhiệt truyền từ tay sang đá."],"lq":["l8-dan-nhiet","l8-doi-luu","l8-buc-xa-nhiet","l8-nang-luong-nhiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-joulemeter","mon":"KHTN","khoi":"8","chu_de":"l8-nhiet","thu_tu":6,"loai":"tn","ten":"Joulemeter","ten_khac":["joulemeter","jun ke","do nang luong nhiet","oat ke","thuc hanh do nang luong nhiet","dun nuoc"],"noi_dung":"Dụng cụ đo năng lượng điện cung cấp cho dụng cụ, dùng để đo năng lượng nhiệt vật nhận được khi đun bằng điện.","cong_thuc":null,"y":["Mắc joulemeter giữa nguồn và dây đun (điện trở nhúng trong nước).","Số chỉ (J) cho biết năng lượng cung cấp; kết hợp nhiệt kế để thấy nhiệt độ nước tăng theo năng lượng nhận được.","Joulemeter còn hiển thị công suất (W), hiệu điện thế (V), cường độ dòng điện (A)."],"bang":null,"bien":null,"vd":null,"nham":["Quên khuấy nước trong khi đun nên số đo nhiệt độ không đều."],"lq":["l8-nang-luong-nhiet","l8-nhiet-do"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-dan-nhiet","mon":"KHTN","khoi":"8","chu_de":"l8-nhiet","thu_tu":7,"loai":"ht","ten":"Dẫn nhiệt","ten_khac":["dan nhiet","su dan nhiet","dan nhiet tot","dan nhiet kem","cach nhiet","conduction","vat dan nhiet"],"noi_dung":"Năng lượng nhiệt truyền từ phần này sang phần khác của vật, hoặc giữa các vật tiếp xúc nhau, nhờ va chạm của các phân tử.","cong_thuc":null,"y":["Hình thức truyền nhiệt chủ yếu của <b>chất rắn</b>.","<b>Kim loại</b> dẫn nhiệt tốt; chất lỏng, chất khí dẫn nhiệt kém; chân không không dẫn nhiệt.","Vật dẫn nhiệt kém (bông, len, xốp, gỗ, không khí) dùng để <b>cách nhiệt</b>."],"bang":[["Dẫn nhiệt tốt","Dẫn nhiệt kém"],["bạc, đồng, nhôm, sắt","gỗ, nhựa, len, xốp"],["","nước, không khí"]],"bien":null,"vd":{"de":"Một đầu thanh kim loại được hơ trên ngọn lửa, một lúc sau đầu còn lại cũng nóng lên dù không tiếp xúc trực tiếp với lửa. Đây là hình thức truyền nhiệt nào?","buoc":["Dẫn nhiệt là sự truyền nhiệt từ phần này sang phần khác của cùng một vật nhờ va chạm phân tử.","Nhiệt lan từ đầu bị hơ nóng sang đầu kia qua chính thanh kim loại."],"kq":"Đó là dẫn nhiệt."},"nham":["Sờ tay vào sắt thấy lạnh hơn gỗ dù cùng nhiệt độ, vì sắt dẫn nhiệt từ tay đi nhanh hơn."],"lq":["l8-su-truyen-nhiet","l8-doi-luu","l8-ung-dung-truyen-nhiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-doi-luu","mon":"KHTN","khoi":"8","chu_de":"l8-nhiet","thu_tu":8,"loai":"ht","ten":"Đối lưu","ten_khac":["doi luu","su doi luu","dong doi luu","convection","dun nuoc","gio"],"noi_dung":"Sự truyền nhiệt nhờ các dòng chất lỏng hoặc chất khí chuyển động.","cong_thuc":null,"y":["Hình thức truyền nhiệt chủ yếu của <b>chất lỏng và chất khí</b>.","Phần nóng nở ra, nhẹ hơn thì <b>đi lên</b>; phần lạnh nặng hơn thì <b>đi xuống</b>, tạo thành dòng đối lưu.","Ví dụ: đun nước từ đáy nồi, gió biển – gió đất liền; điều hòa đặt cao, lò sưởi đặt thấp."],"bang":null,"bien":null,"vd":{"de":"Khi đun nước trong ấm, nước ở đáy ấm nóng lên rồi di chuyển lên trên, còn nước lạnh ở trên chìm xuống, tạo thành dòng chuyển động. Đây là hình thức truyền nhiệt nào?","buoc":["Đối lưu là sự truyền nhiệt nhờ các dòng chất lỏng hoặc chất khí chuyển động.","Ở đây có dòng nước nóng đi lên và nước lạnh đi xuống trong ấm."],"kq":"Đó là đối lưu."},"nham":["Đun nước từ phía trên mặt nước: nước ở dưới lâu nóng vì đối lưu khó xảy ra."],"lq":["l8-su-truyen-nhiet","l8-dan-nhiet","l8-buc-xa-nhiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-buc-xa-nhiet","mon":"KHTN","khoi":"8","chu_de":"l8-nhiet","thu_tu":9,"loai":"ht","ten":"Bức xạ nhiệt","ten_khac":["buc xa nhiet","buc xa","tia nhiet","radiation","nhiet mat troi","chan khong"],"noi_dung":"Sự truyền nhiệt bằng các tia nhiệt đi thẳng, xảy ra được cả trong chân không.","cong_thuc":null,"y":["Nhiệt từ <b>Mặt Trời</b> truyền tới Trái Đất bằng bức xạ nhiệt.","Vật có bề mặt <b>sẫm màu, xù xì</b> hấp thụ tia nhiệt tốt; bề mặt <b>sáng màu, nhẵn bóng</b> phản xạ tia nhiệt tốt.","Ví dụ: ngồi cạnh bếp lửa thấy ấm mặt."],"bang":null,"bien":null,"vd":{"de":"Đứng cạnh đống lửa, dù không khí xung quanh khá lạnh, em vẫn cảm thấy hơi nóng phả vào mặt gần như ngay lập tức. Nhiệt đã truyền tới em chủ yếu bằng hình thức nào?","buoc":["Bức xạ nhiệt truyền bằng các tia nhiệt đi thẳng, xảy ra được cả trong không khí và chân không.","Tia nhiệt từ đống lửa truyền thẳng tới người mà không cần không khí nóng lên trước."],"kq":"Đó là bức xạ nhiệt."},"nham":["Nghĩ nhiệt chỉ truyền được qua vật chất: bức xạ nhiệt truyền được qua chân không."],"lq":["l8-su-truyen-nhiet","l8-doi-luu","l8-ung-dung-truyen-nhiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-ung-dung-truyen-nhiet","mon":"KHTN","khoi":"8","chu_de":"l8-nhiet","thu_tu":10,"loai":"ud","ten":"Ứng dụng sự truyền nhiệt","ten_khac":["ung dung truyen nhiet","phich nuoc","binh giu nhiet","ao mau sang","noi nhom","cach nhiet nha"],"noi_dung":"Vận dụng dẫn nhiệt, đối lưu, bức xạ nhiệt để làm nóng nhanh hoặc giữ nhiệt trong đời sống.","cong_thuc":null,"y":["Nồi, xoong bằng kim loại (dẫn nhiệt tốt), tay cầm bằng nhựa, gỗ (dẫn nhiệt kém).","<b>Phích nước:</b> hai lớp thủy tinh có chân không ở giữa (hạn chế dẫn nhiệt, đối lưu), mặt tráng bạc (phản xạ bức xạ).","Mùa hè mặc áo sáng màu; mái nhà sơn sáng, tường có lớp cách nhiệt.","Ống khói nhà máy làm cao để tạo đối lưu tốt."],"bang":null,"bien":null,"vd":{"de":"Đáy nồi nấu ăn thường làm bằng kim loại, còn tay cầm làm bằng nhựa hoặc gỗ. Vì sao?","buoc":["Kim loại dẫn nhiệt tốt, giúp truyền nhiệt vào thức ăn nhanh.","Nhựa, gỗ dẫn nhiệt kém, giúp tay cầm không bị nóng khi nấu."],"kq":"Đáy kim loại truyền nhiệt nhanh, tay cầm nhựa/gỗ cách nhiệt để cầm an toàn."},"nham":null,"lq":["l8-dan-nhiet","l8-doi-luu","l8-buc-xa-nhiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-su-no-vi-nhiet","mon":"KHTN","khoi":"8","chu_de":"l8-nhiet","thu_tu":11,"loai":"ht","ten":"Sự nở vì nhiệt","ten_khac":["su no vi nhiet","no vi nhiet","dan no","co lai","thermal expansion","no ra khi nong"],"noi_dung":"Các chất nở ra khi nóng lên và co lại khi lạnh đi.","cong_thuc":null,"y":["Khi nóng lên, phân tử chuyển động mạnh hơn và <b>xa nhau hơn</b> nên thể tích tăng.","Chất khí nở vì nhiệt <b>nhiều nhất</b>, chất rắn nở <b>ít nhất</b>.","Sự nở vì nhiệt nếu bị ngăn cản có thể gây ra <b>lực rất lớn</b>."],"bang":[["Chất","Mức nở vì nhiệt"],["Khí","nhiều nhất"],["Lỏng","trung bình"],["Rắn","ít nhất"]],"bien":null,"vd":{"de":"Một chiếc ly thủy tinh dày bị rót nước sôi vào đột ngột và bị nứt vỡ. Hiện tượng gì đã gây ra điều đó?","buoc":["Các chất nở ra khi nóng lên.","Mặt trong ly nóng lên và nở ra nhanh trong khi mặt ngoài còn lạnh, chưa kịp nở nên ly bị kéo, nén không đều và nứt."],"kq":"Do sự nở vì nhiệt không đều giữa mặt trong và mặt ngoài ly."},"nham":["Nghĩ khi nở ra thì khối lượng tăng: chỉ thể tích tăng, khối lượng không đổi nên khối lượng riêng giảm."],"lq":["l8-no-vi-nhiet-chat-ran","l8-no-vi-nhiet-chat-long","l8-no-vi-nhiet-chat-khi","l8-ung-dung-no-vi-nhiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-no-vi-nhiet-chat-ran","mon":"KHTN","khoi":"8","chu_de":"l8-nhiet","thu_tu":12,"loai":"ht","ten":"Sự nở vì nhiệt của chất rắn","ten_khac":["no vi nhiet chat ran","chat ran no","qua cau kim loai","duong ray","thanh kim loai no"],"noi_dung":"Chất rắn nở ra khi nóng lên, co lại khi lạnh đi; các chất rắn khác nhau nở vì nhiệt khác nhau.","cong_thuc":null,"y":["Thí nghiệm: quả cầu kim loại vừa lọt vòng, khi hơ nóng thì <b>không lọt</b> nữa.","Nhôm nở vì nhiệt nhiều hơn đồng, đồng nhiều hơn sắt.","Vì vậy đường ray, cầu phải có khe hở; dây điện mùa hè võng hơn mùa đông."],"bang":null,"bien":null,"vd":{"de":"Giữa hai thanh ray xe lửa thường để một khe hở nhỏ. Vì sao?","buoc":["Chất rắn nở ra khi nóng lên.","Để khi trời nắng nóng, ray nở dài ra mà không bị cong vênh do không có chỗ giãn nở."],"kq":"Khe hở để ray nở dài ra khi nhiệt độ tăng mà không bị cong vênh."},"nham":null,"lq":["l8-su-no-vi-nhiet","l8-bang-kep","l8-ung-dung-no-vi-nhiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-no-vi-nhiet-chat-long","mon":"KHTN","khoi":"8","chu_de":"l8-nhiet","thu_tu":13,"loai":"ht","ten":"Sự nở vì nhiệt của chất lỏng","ten_khac":["no vi nhiet chat long","chat long no","nhiet ke chat long","nuoc no","nuoc 4 do c"],"noi_dung":"Chất lỏng nở ra khi nóng lên, co lại khi lạnh đi; các chất lỏng khác nhau nở vì nhiệt khác nhau.","cong_thuc":null,"y":["Chất lỏng nở vì nhiệt <b>nhiều hơn</b> chất rắn.","Ứng dụng: <b>nhiệt kế chất lỏng</b> (thủy ngân, rượu); đun nước không đổ đầy ấm.","Nước là trường hợp đặc biệt: từ 0 °C đến 4 °C, nước <b>co lại</b> khi nóng lên."],"bang":null,"bien":null,"vd":{"de":"Không nên đổ đầy nước vào một chai thủy tinh rồi đậy kín và để ngoài nắng. Vì sao?","buoc":["Chất lỏng nở ra khi nóng lên.","Nước nở ra khi nhiệt độ tăng nhưng không còn chỗ trống trong chai để giãn nở."],"kq":"Nước nở ra có thể làm bật nắp hoặc vỡ chai."},"nham":["Đổ đầy chai nước ngọt rồi để ngoài nắng: nước nở ra có thể làm bật nắp, vỡ chai."],"lq":["l8-su-no-vi-nhiet","l8-ung-dung-no-vi-nhiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-no-vi-nhiet-chat-khi","mon":"KHTN","khoi":"8","chu_de":"l8-nhiet","thu_tu":14,"loai":"ht","ten":"Sự nở vì nhiệt của chất khí","ten_khac":["no vi nhiet chat khi","chat khi no","khong khi no","bong bay no","giot mau trong ong"],"noi_dung":"Chất khí nở ra khi nóng lên, co lại khi lạnh đi; chất khí nở vì nhiệt nhiều hơn chất lỏng và chất rắn.","cong_thuc":null,"y":["Thí nghiệm: áp tay vào bình cầu có ống thủy tinh, giọt nước màu trong ống bị <b>đẩy ra</b> ngoài.","Quả bóng bàn bị bẹp nhúng vào nước nóng sẽ phồng lại.","Không khí nóng nở ra, nhẹ hơn nên bay lên: nguyên lí của đèn trời, khinh khí cầu."],"bang":null,"bien":null,"vd":{"de":"Một quả bóng bay bơm căng để trong ô tô đóng kín đỗ ngoài trời nắng có thể bị nổ. Vì sao?","buoc":["Chất khí nở vì nhiệt nhiều hơn chất lỏng và chất rắn.","Nhiệt độ trong xe tăng cao làm không khí trong bóng nở ra mạnh, áp suất tăng lên."],"kq":"Không khí trong bóng nở ra quá mức làm bóng căng và nổ."},"nham":["Bơm lốp xe quá căng rồi để ngoài nắng: khí nở ra có thể làm nổ lốp."],"lq":["l8-su-no-vi-nhiet","l8-doi-luu","l8-ung-dung-no-vi-nhiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-bang-kep","mon":"KHTN","khoi":"8","chu_de":"l8-nhiet","thu_tu":15,"loai":"cq","ten":"Băng kép","ten_khac":["bang kep","thanh luong kim","role nhiet","dong ngat tu dong","bimetal"],"noi_dung":"Hai thanh kim loại khác nhau (như đồng và thép) tán chặt vào nhau, bị cong khi nhiệt độ thay đổi.","cong_thuc":null,"y":["Khi nóng lên, băng kép cong về phía thanh kim loại <b>nở ít hơn</b>.","Dùng để tự động <b>đóng, ngắt mạch điện</b> khi nhiệt độ thay đổi.","Ứng dụng: bàn là, nồi cơm điện, rơle nhiệt, báo cháy."],"bang":null,"bien":null,"vd":{"de":"Một băng kép gồm đồng và thép bị nung nóng, biết đồng nở vì nhiệt nhiều hơn thép. Băng kép sẽ cong về phía thanh nào?","buoc":["Khi nóng lên, thanh đồng dài ra nhiều hơn thanh thép.","Hai thanh bị tán chặt vào nhau nên băng kép cong về phía thanh giãn nở ít hơn."],"kq":"Băng kép cong về phía thanh thép."},"nham":["Nói băng kép cong về phía kim loại nở nhiều: kim loại nở nhiều nằm ở mặt ngoài chỗ cong."],"lq":["l8-no-vi-nhiet-chat-ran","l8-ung-dung-no-vi-nhiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-ung-dung-no-vi-nhiet","mon":"KHTN","khoi":"8","chu_de":"l8-nhiet","thu_tu":16,"loai":"ud","ten":"Ứng dụng sự nở vì nhiệt","ten_khac":["ung dung no vi nhiet","khe ho duong ray","nhiet ke","con lan cau","mo nap chai","khinh khi cau"],"noi_dung":"Tận dụng hoặc phòng tránh tác dụng của sự nở vì nhiệt trong kĩ thuật và đời sống.","cong_thuc":null,"y":["<b>Phòng tránh:</b> khe hở giữa hai thanh ray, gối đỡ con lăn ở đầu cầu, không đổ đầy nước trong ấm, chai.","<b>Tận dụng:</b> nhiệt kế, băng kép trong bàn là, khinh khí cầu.","Mẹo: nắp lọ kim loại bị chặt thì hơ nóng nắp để nắp nở ra, dễ mở hơn."],"bang":null,"bien":null,"vd":{"de":"Trước khi rót nước sôi vào cốc thủy tinh, người ta thường tráng trước một lớp nước ấm rồi mới đổ nước sôi vào. Cách làm này vận dụng kiến thức nào để tránh vỡ cốc?","buoc":["Chênh lệch nhiệt độ đột ngột giữa các phần của cốc gây nở vì nhiệt không đều, dễ làm nứt vỡ.","Tráng nước ấm trước giúp cốc nóng dần lên, giảm chênh lệch nhiệt độ đột ngột."],"kq":"Vận dụng sự nở vì nhiệt: làm nóng từ từ để tránh nứt vỡ do giãn nở không đều."},"nham":null,"lq":["l8-su-no-vi-nhiet","l8-bang-kep","l8-no-vi-nhiet-chat-ran"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-dong-nang","mon":"KHTN","khoi":"9","chu_de":"l9-co-hoc","thu_tu":1,"loai":"dl","ten":"Động năng","ten_khac":["dong nang","wd","nang luong chuyen dong","1/2mv2","mv2","kinetic energy"],"noi_dung":"Năng lượng mà vật có được do chuyển động.","cong_thuc":"Wđ = ½mv²","y":["Vật đứng yên thì động năng bằng 0.","Động năng tỉ lệ với <b>khối lượng</b> và với <b>bình phương tốc độ</b>.","Tốc độ tăng 2 lần thì động năng tăng 4 lần."],"bang":null,"bien":[["Wđ","động năng","J"],["m","khối lượng","kg"],["v","tốc độ","m/s"]],"vd":{"de":"Một bạn khối lượng 50 kg chạy với tốc độ 4 m/s. Tính động năng.","buoc":["Wđ = ½mv² = ½ · 50 · 4²","= 25 · 16"],"kq":"Wđ = 400 J"},"nham":["Quên bình phương v.","Quên đổi km/h sang m/s (chia cho 3,6)."],"lq":["l9-the-nang","l9-co-nang","l9-chuyen-hoa-dong-the-nang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-the-nang","mon":"KHTN","khoi":"9","chu_de":"l9-co-hoc","thu_tu":2,"loai":"dl","ten":"Thế năng trọng trường","ten_khac":["the nang","the nang trong truong","wt","ph","mgh","10mh","potential energy","do cao"],"noi_dung":"Năng lượng vật có được khi ở một độ cao so với vị trí chọn làm mốc (thường là mặt đất).","cong_thuc":"Wt = Ph = 10mh","y":["Vật ở <b>mốc thế năng</b> thì thế năng bằng 0.","Vật càng nặng, càng ở cao thì thế năng càng lớn.","Trọng lượng P = 10m (m tính bằng kg).","Vật bị biến dạng đàn hồi (lò xo nén) cũng có thế năng, gọi là thế năng đàn hồi."],"bang":null,"bien":[["Wt","thế năng trọng trường","J"],["P","trọng lượng của vật (P = 10m)","N"],["h","độ cao so với mốc","m"]],"vd":{"de":"Một quả tạ 2 kg ở độ cao 5 m so với mặt đất. Tính thế năng trọng trường (mốc ở mặt đất).","buoc":["P = 10m = 10 · 2 = 20 N","Wt = Ph = 20 · 5"],"kq":"Wt = 100 J"},"nham":["Lấy khối lượng m nhân h mà quên đổi ra trọng lượng P = 10m.","Quên rằng thế năng phụ thuộc cách chọn mốc."],"lq":["l9-dong-nang","l9-co-nang","l9-cong-co-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-so-sanh-dong-nang","mon":"KHTN","khoi":"9","chu_de":"l9-co-hoc","thu_tu":3,"loai":"kn","ten":"So sánh động năng","ten_khac":["so sanh dong nang","dong nang tang k lan","binh phuong toc do","toc do gap doi","khoi luong gap doi"],"noi_dung":"Động năng tỉ lệ với khối lượng và với bình phương tốc độ, nên so sánh được hai vật mà không cần tính giá trị cụ thể.","cong_thuc":"Wđ₂ : Wđ₁ = (m₂ : m₁) · (v₂ : v₁)²","y":["Khối lượng tăng k lần (tốc độ giữ nguyên) → động năng tăng <b>k lần</b>.","Tốc độ tăng k lần (khối lượng giữ nguyên) → động năng tăng <b>k² lần</b>.","Cả khối lượng và tốc độ cùng đổi: nhân hai hệ số với nhau."],"bang":null,"bien":[["Wđ₁, Wđ₂","động năng của hai vật","J"],["m₁, m₂","khối lượng","kg"],["v₁, v₂","tốc độ","m/s"]],"vd":{"de":"Vật A: 2 kg, 3 m/s. Vật B: 1 kg, 6 m/s. Vật nào có động năng lớn hơn, lớn hơn bao nhiêu lần?","buoc":["Wđ_B : Wđ_A = (1 : 2) · (6 : 3)²","= ½ · 4 = 2"],"kq":"Vật B có động năng gấp 2 lần vật A (18 J so với 9 J)"},"nham":["Cho rằng tốc độ gấp đôi thì động năng cũng chỉ gấp đôi."],"lq":["l9-dong-nang","l9-dong-nang-giao-thong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-dong-nang-giao-thong","mon":"KHTN","khoi":"9","chu_de":"l9-co-hoc","thu_tu":4,"loai":"ud","ten":"Động năng và an toàn giao thông","ten_khac":["an toan giao thong","gioi han toc do","tui khi","mu bao hiem","dai an toan","va cham","hap thu dong nang"],"noi_dung":"Xe chạy càng nhanh thì động năng càng lớn (tăng theo bình phương tốc độ), nên khi va chạm càng gây hư hại và càng khó dừng lại.","cong_thuc":null,"y":["Tốc độ tăng gấp đôi thì động năng tăng <b>gấp bốn</b>: quãng đường phanh dài hơn nhiều, va chạm nguy hiểm hơn nhiều.","Vì vậy có <b>biển giới hạn tốc độ</b>; xe có khối lượng lớn như xe tải thường bị giới hạn tốc độ thấp hơn.","Các thiết bị <b>hấp thụ động năng</b> khi va chạm: mũ bảo hiểm, túi khí, đai an toàn, vùng co giãn của thân ô tô, đệm khi nhảy cao."],"bang":null,"bien":null,"vd":{"de":"Một ô tô 1 000 kg tăng tốc từ 10 m/s lên 20 m/s. Động năng của ô tô tăng mấy lần?","buoc":["Wđ₁ = ½ · 1 000 · 10² = 50 000 J","Wđ₂ = ½ · 1 000 · 20² = 200 000 J"],"kq":"Động năng tăng 4 lần"},"nham":["Nghĩ xe chạy nhanh gấp đôi chỉ nguy hiểm gấp đôi."],"lq":["l9-dong-nang","l9-so-sanh-dong-nang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-co-nang","mon":"KHTN","khoi":"9","chu_de":"l9-co-hoc","thu_tu":5,"loai":"dl","ten":"Cơ năng","ten_khac":["co nang","w","nang luong co hoc","wd + wt","tong dong nang the nang","mechanical energy"],"noi_dung":"Tổng động năng và thế năng của vật.","cong_thuc":"W = Wđ + Wt","y":["Cơ năng còn gọi là <b>năng lượng cơ học</b>.","Đơn vị cơ năng là jun (J), giống mọi dạng năng lượng.","Khi bỏ qua ma sát, lực cản thì cơ năng được bảo toàn."],"bang":null,"bien":[["W","cơ năng","J"],["Wđ","động năng","J"],["Wt","thế năng","J"]],"vd":{"de":"Vật 1 kg ở độ cao 2 m đang chuyển động với tốc độ 2 m/s. Tính cơ năng (mốc thế năng ở mặt đất).","buoc":["Wt = Ph = 10 · 1 · 2 = 20 J","Wđ = ½ · 1 · 2² = 2 J","W = Wđ + Wt = 2 + 20"],"kq":"W = 22 J"},"nham":null,"lq":["l9-dong-nang","l9-the-nang","l9-bao-toan-co-nang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-moc-the-nang","mon":"KHTN","khoi":"9","chu_de":"l9-co-hoc","thu_tu":6,"loai":"kn","ten":"Mốc thế năng","ten_khac":["moc the nang","chon moc","do cao so voi moc","doi moc"],"noi_dung":"Vị trí được chọn để tính độ cao h trong công thức thế năng trọng trường; tại mốc, thế năng bằng 0.","cong_thuc":null,"y":["Thường chọn <b>mặt đất</b> làm mốc, nhưng có thể chọn mặt bàn, sàn nhà, đáy hố…","Cùng một vật ở cùng một chỗ, đổi mốc thì h đổi nên <b>giá trị thế năng đổi</b>.","Khi so sánh thế năng của nhiều vật phải dùng <b>cùng một mốc</b>."],"bang":null,"bien":null,"vd":{"de":"Chậu cây 2 kg đặt trên bậu cửa sổ, cao 4 m so với sân và 1 m so với sàn phòng. Tính thế năng của chậu khi chọn mốc ở sân và khi chọn mốc ở sàn phòng.","buoc":["Mốc ở sân: Wt = 10 · 2 · 4 = 80 J","Mốc ở sàn phòng: Wt = 10 · 2 · 1 = 20 J"],"kq":"80 J (mốc ở sân); 20 J (mốc ở sàn phòng)"},"nham":["Luôn lấy độ cao so với mặt đất dù đề đã chọn mốc ở chỗ khác."],"lq":["l9-the-nang","l9-co-nang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-the-nang-dan-hoi","mon":"KHTN","khoi":"9","chu_de":"l9-co-hoc","thu_tu":7,"loai":"kn","ten":"Thế năng đàn hồi","ten_khac":["the nang dan hoi","lo xo","bien dang dan hoi","day cung","day chun","sung cao su"],"noi_dung":"Năng lượng của vật bị biến dạng đàn hồi, như lò xo bị nén hoặc kéo dãn, dây cung bị kéo căng.","cong_thuc":null,"y":["Biến dạng càng nhiều (trong giới hạn đàn hồi) thì thế năng đàn hồi càng lớn.","Khi vật trở lại hình dạng ban đầu, thế năng đàn hồi chuyển thành dạng năng lượng khác, thường là động năng.","Ví dụ: cung tên, súng cao su, lò xo đồ chơi, bạt nhún."],"bang":null,"bien":null,"vd":{"de":"Một dây cung được kéo căng rồi thả ra, mũi tên bay đi với tốc độ lớn. Thế năng đàn hồi của dây cung đã chuyển hóa thành dạng năng lượng nào của mũi tên?","buoc":["Vật biến dạng đàn hồi dự trữ thế năng đàn hồi.","Khi thả ra, dây cung trở về hình dạng ban đầu và truyền năng lượng cho mũi tên chuyển động."],"kq":"Thế năng đàn hồi chuyển hóa thành động năng của mũi tên."},"nham":["Cho rằng chỉ vật ở trên cao mới có thế năng."],"lq":["l9-the-nang","l9-chuyen-hoa-dong-the-nang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-the-nang-ung-dung","mon":"KHTN","khoi":"9","chu_de":"l9-co-hoc","thu_tu":8,"loai":"ud","ten":"Ứng dụng thế năng trong thực tế","ten_khac":["thuy dien","ho chua","bua may","dong coc","an toan tren cao","vat roi"],"noi_dung":"Thế năng của vật trên cao chuyển thành động năng để làm việc có ích; vật rơi từ trên cao lại gây nguy hiểm.","cong_thuc":null,"y":["<b>Thuỷ điện</b>: nước tích ở hồ trên cao có thế năng lớn, chảy xuống làm quay tua bin.","<b>Búa máy đóng cọc</b>: nâng búa lên cao rồi thả, thế năng chuyển thành động năng đóng cọc xuống đất.","<b>An toàn</b>: vật rơi từ trên cao có thể gây thương tích; làm việc trên cao phải đeo dây an toàn, không để đồ vật sát mép."],"bang":null,"bien":null,"vd":{"de":"Búa máy 500 kg được nâng lên cao 4 m so với đầu cọc. Tính thế năng của búa (mốc ở đầu cọc).","buoc":["P = 10m = 10 · 500 = 5 000 N","Wt = Ph = 5 000 · 4"],"kq":"Wt = 20 000 J"},"nham":null,"lq":["l9-the-nang","l9-chuyen-hoa-dong-the-nang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-bao-toan-co-nang","mon":"KHTN","khoi":"9","chu_de":"l9-co-hoc","thu_tu":9,"loai":"ct","ten":"Bảo toàn cơ năng","ten_khac":["bao toan co nang","dinh luat bao toan co nang","co nang khong doi","wd + wt = const","con lac"],"noi_dung":"Khi chỉ có trọng lực tác dụng (bỏ qua ma sát, lực cản), cơ năng của vật không đổi.","cong_thuc":"Wđ + Wt = hằng số","y":["Động năng tăng bao nhiêu thì thế năng giảm bấy nhiêu và ngược lại.","Có ma sát, lực cản: một phần cơ năng chuyển thành <b>nhiệt năng</b>, cơ năng giảm.","Ví dụ: con lắc dao động, vật rơi tự do, vật ném lên cao."],"bang":null,"bien":[["Wđ","động năng","J"],["Wt","thế năng","J"]],"vd":{"de":"Thả rơi vật 0,2 kg từ độ cao 5 m, bỏ qua lực cản. Tính tốc độ khi chạm đất.","buoc":["Lúc thả: W = Wt = 10 · 0,2 · 5 = 10 J","Chạm đất: Wđ = W = 10 J","½ · 0,2 · v² = 10 → v² = 100"],"kq":"v = 10 m/s"},"nham":["Áp dụng bảo toàn cơ năng khi có ma sát lớn."],"lq":["l9-co-nang","l9-chuyen-hoa-dong-the-nang","l9-dong-nang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-chuyen-hoa-dong-the-nang","mon":"KHTN","khoi":"9","chu_de":"l9-co-hoc","thu_tu":10,"loai":"ht","ten":"Chuyển hóa động năng – thế năng","ten_khac":["chuyen hoa dong nang the nang","chuyen hoa co nang","con lac dao dong","vat roi","nem len"],"noi_dung":"Trong chuyển động, động năng có thể chuyển thành thế năng và ngược lại.","cong_thuc":null,"y":["Vật đi lên: tốc độ giảm, độ cao tăng → <b>động năng chuyển thành thế năng</b>.","Vật đi xuống: độ cao giảm, tốc độ tăng → <b>thế năng chuyển thành động năng</b>.","Con lắc: ở vị trí cao nhất thế năng lớn nhất; ở vị trí thấp nhất động năng lớn nhất."],"bang":null,"bien":null,"vd":{"de":"Một con lắc dao động, khi đi từ vị trí cao nhất xuống vị trí thấp nhất, thế năng giảm còn động năng tăng. Điều này thể hiện điều gì?","buoc":["Trong chuyển động, động năng có thể chuyển thành thế năng và ngược lại.","Ở đây thế năng giảm đúng bằng phần động năng tăng thêm (bỏ qua ma sát)."],"kq":"Thể hiện sự chuyển hóa qua lại giữa động năng và thế năng."},"nham":null,"lq":["l9-bao-toan-co-nang","l9-dong-nang","l9-the-nang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-cong-co-hoc","mon":"KHTN","khoi":"9","chu_de":"l9-co-hoc","thu_tu":11,"loai":"dl","ten":"Công cơ học","ten_khac":["cong co hoc","cong","a = fs","a = f.s","jun","j","work"],"noi_dung":"Công được thực hiện khi có lực tác dụng làm vật dịch chuyển theo phương của lực.","cong_thuc":"A = F·s","y":["1 J = 1 N · 1 m; ngoài ra 1 kJ = 1 000 J.","Có lực mà vật không dịch chuyển thì <b>không có công</b>.","Công là số đo phần năng lượng được truyền hoặc chuyển hóa."],"bang":null,"bien":[["A","công cơ học","J"],["F","lực tác dụng","N"],["s","quãng đường dịch chuyển theo phương của lực","m"]],"vd":{"de":"Kéo thùng hàng bằng lực 50 N theo phương ngang, thùng dịch chuyển 10 m theo phương của lực. Tính công.","buoc":["A = F · s = 50 · 10"],"kq":"A = 500 J"},"nham":["Người đứng yên cầm vật nặng vẫn nghĩ là có thực hiện công cơ học."],"lq":["l9-cong-suat","l9-the-nang","l9-co-nang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-cong-suat","mon":"KHTN","khoi":"9","chu_de":"l9-co-hoc","thu_tu":12,"loai":"dl","ten":"Công suất","ten_khac":["cong suat","p = a/t","oat","watt","w","kw","toc do thuc hien cong","power"],"noi_dung":"Đại lượng cho biết công thực hiện được trong một đơn vị thời gian (tốc độ thực hiện công).","cong_thuc":"P = A/t","y":["1 W = 1 J/s; 1 kW = 1 000 W; 1 MW = 1 000 000 W.","Cùng một công, máy nào làm trong thời gian ngắn hơn thì công suất lớn hơn."],"bang":null,"bien":[["P","công suất","W"],["A","công thực hiện","J"],["t","thời gian thực hiện công","s"]],"vd":{"de":"Cần cẩu nâng kiện hàng 500 kg lên cao 6 m trong 10 s. Tính công suất.","buoc":["F = P = 10 · 500 = 5 000 N","A = F · s = 5 000 · 6 = 30 000 J","P = A/t = 30 000 : 10"],"kq":"P = 3 000 W = 3 kW"},"nham":["Nhầm kí hiệu P công suất với P trọng lượng.","Quên đổi phút ra giây."],"lq":["l9-cong-co-hoc","l9-cong-suat-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-khuc-xa-anh-sang","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":1,"loai":"ht","ten":"Khúc xạ ánh sáng","ten_khac":["khuc xa anh sang","khuc xa","tia khuc xa","gay khuc","refraction","coc nuoc but chi"],"noi_dung":"Hiện tượng tia sáng bị gãy khúc tại mặt phân cách khi truyền xiên góc từ môi trường trong suốt này sang môi trường khác.","cong_thuc":null,"y":["Nguyên nhân: tốc độ ánh sáng trong hai môi trường khác nhau.","Tia tới vuông góc mặt phân cách thì truyền thẳng, không bị gãy.","Ví dụ: chiếc bút cắm vào cốc nước trông như bị gãy; đáy bể nước trông nông hơn thực tế."],"bang":null,"bien":null,"vd":{"de":"Một chiếc đũa cắm nghiêng vào cốc nước, nhìn từ trên xuống ta thấy đũa như bị gãy khúc tại mặt nước. Hiện tượng gì gây ra điều này?","buoc":["Ánh sáng truyền xiên góc từ môi trường trong suốt này sang môi trường khác sẽ bị gãy khúc tại mặt phân cách.","Ánh sáng từ phần đũa trong nước truyền ra không khí tới mắt bị đổi hướng tại mặt nước."],"kq":"Đó là hiện tượng khúc xạ ánh sáng."},"nham":["Nhầm khúc xạ (tia sáng đi sang môi trường khác) với phản xạ (tia sáng hắt trở lại)."],"lq":["l9-goc-toi-goc-khuc-xa","l9-dinh-luat-khuc-xa","l9-chiet-suat","l9-phan-xa-toan-phan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-goc-toi-goc-khuc-xa","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":2,"loai":"kn","ten":"Góc tới và góc khúc xạ","ten_khac":["goc toi","goc khuc xa","i","r","phap tuyen","diem toi","mat phan cach"],"noi_dung":"Góc tới i là góc giữa tia tới và pháp tuyến; góc khúc xạ r là góc giữa tia khúc xạ và pháp tuyến.","cong_thuc":null,"y":["<b>Pháp tuyến</b>: đường thẳng vuông góc với mặt phân cách tại điểm tới.","Ánh sáng đi từ không khí vào nước, thủy tinh: r < i.","Ánh sáng đi từ nước, thủy tinh ra không khí: r > i."],"bang":null,"bien":null,"vd":{"de":"Tia sáng truyền từ không khí vào nước với góc tới i = 60°, cho góc khúc xạ r = 40°. So sánh hai góc này.","buoc":["So sánh trực tiếp: i = 60°, r = 40°.","Ánh sáng truyền từ không khí (kém chiết quang) sang nước (chiết quang hơn)."],"kq":"i > r: góc khúc xạ nhỏ hơn góc tới."},"nham":["Đo góc từ tia sáng đến mặt phân cách thay vì đến pháp tuyến."],"lq":["l9-khuc-xa-anh-sang","l9-dinh-luat-khuc-xa"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-chiet-suat","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":3,"loai":"dl","ten":"Chiết suất","ten_khac":["chiet suat","n","n = c/v","chiet suat moi truong","toc do anh sang","refractive index"],"noi_dung":"Đại lượng cho biết tốc độ ánh sáng trong chân không lớn gấp bao nhiêu lần tốc độ ánh sáng trong môi trường đó.","cong_thuc":"n = c/v","y":["Chiết suất luôn lớn hơn hoặc bằng 1; không khí có n ≈ 1.","Môi trường có chiết suất lớn hơn gọi là <b>chiết quang hơn</b>, ánh sáng truyền chậm hơn trong đó."],"bang":[["Môi trường","Chiết suất (gần đúng)"],["Không khí","1"],["Nước","1,33"],["Thủy tinh","1,5"],["Kim cương","2,42"]],"bien":[["n","chiết suất của môi trường","(không đơn vị)"],["c","tốc độ ánh sáng trong chân không, c ≈ 3·10⁸","m/s"],["v","tốc độ ánh sáng trong môi trường","m/s"]],"vd":{"de":"Nước có chiết suất 1,33. Tính tốc độ ánh sáng trong nước.","buoc":["v = c/n = 3·10⁸ : 1,33"],"kq":"v ≈ 2,26·10⁸ m/s"},"nham":null,"lq":["l9-dinh-luat-khuc-xa","l9-khuc-xa-anh-sang","l9-goc-toi-han"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-dinh-luat-khuc-xa","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":4,"loai":"ct","ten":"Định luật khúc xạ ánh sáng","ten_khac":["dinh luat khuc xa","sin i / sin r","sini/sinr","n1 sin i = n2 sin r","snell"],"noi_dung":"Tia khúc xạ nằm trong mặt phẳng tới, ở bên kia pháp tuyến; tỉ số sin i/sin r luôn không đổi với hai môi trường xác định.","cong_thuc":"sin i / sin r = n₂/n₁","y":["(Mở rộng) Viết gọn: n₁·sin i = n₂·sin r.","Đi vào môi trường chiết quang hơn (n₂ > n₁) thì r < i; ngược lại r > i.","i = 0° thì r = 0°: tia sáng truyền thẳng."],"bang":null,"bien":[["i","góc tới","°"],["r","góc khúc xạ","°"],["n₁","chiết suất môi trường chứa tia tới",""],["n₂","chiết suất môi trường chứa tia khúc xạ",""]],"vd":{"de":"Tia sáng đi từ không khí (n = 1) vào thủy tinh (n = 1,5) với góc tới 30°. Tính góc khúc xạ.","buoc":["sin r = n₁·sin i / n₂ = 1 · 0,5 : 1,5 ≈ 0,333"],"kq":"r ≈ 19,5°"},"nham":["Đặt ngược n₁, n₂.","Bấm máy tính ở chế độ radian thay vì độ."],"lq":["l9-chiet-suat","l9-goc-toi-goc-khuc-xa","l9-khuc-xa-anh-sang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-phan-xa-toan-phan","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":5,"loai":"ht","ten":"Phản xạ toàn phần","ten_khac":["phan xa toan phan","pxtp","total reflection","khong co tia khuc xa","phan xa hoan toan"],"noi_dung":"Hiện tượng toàn bộ ánh sáng tới bị phản xạ trở lại tại mặt phân cách, không có tia khúc xạ.","cong_thuc":null,"y":["Điều kiện 1: ánh sáng đi từ môi trường <b>chiết suất lớn sang chiết suất nhỏ</b> (ví dụ thủy tinh → không khí).","Điều kiện 2: góc tới <b>lớn hơn hoặc bằng góc tới hạn</b>.","Ứng dụng: sợi quang, lăng kính phản xạ toàn phần; giải thích độ lấp lánh của kim cương."],"bang":null,"bien":null,"vd":{"de":"Ánh sáng truyền từ nước ra không khí với góc tới lớn hơn góc tới hạn. Hiện tượng gì xảy ra tại mặt nước?","buoc":["Khi góc tới vượt quá góc tới hạn, không còn tia khúc xạ ra ngoài.","Toàn bộ ánh sáng bị phản xạ trở lại môi trường nước."],"kq":"Xảy ra hiện tượng phản xạ toàn phần."},"nham":["Cho rằng ánh sáng đi từ không khí vào nước cũng có thể phản xạ toàn phần."],"lq":["l9-goc-toi-han","l9-soi-quang","l9-khuc-xa-anh-sang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-goc-toi-han","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":6,"loai":"dl","ten":"Góc tới hạn","ten_khac":["goc toi han","ith","i th","goc gioi han","sin ith = n2/n1"],"noi_dung":"Góc tới nhỏ nhất bắt đầu xảy ra phản xạ toàn phần, ứng với góc khúc xạ bằng 90°.","cong_thuc":"sin iₜₕ = n₂/n₁","y":["i < iₜₕ: vừa có tia khúc xạ vừa có tia phản xạ.","i ≥ iₜₕ: chỉ còn tia phản xạ (phản xạ toàn phần)."],"bang":null,"bien":[["iₜₕ","góc tới hạn","°"],["n₁","chiết suất môi trường tới (lớn hơn)",""],["n₂","chiết suất môi trường khúc xạ (nhỏ hơn)",""]],"vd":{"de":"Tính góc tới hạn khi ánh sáng đi từ thủy tinh (n = 1,5) ra không khí (n = 1).","buoc":["sin iₜₕ = n₂/n₁ = 1 : 1,5 ≈ 0,667"],"kq":"iₜₕ ≈ 41,8°"},"nham":null,"lq":["l9-phan-xa-toan-phan","l9-chiet-suat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-soi-quang","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":7,"loai":"ud","ten":"Sợi quang","ten_khac":["soi quang","cap quang","soi quang hoc","internet cap quang","noi soi","fiber"],"noi_dung":"Sợi thủy tinh hoặc nhựa rất mảnh dẫn ánh sáng đi xa nhờ phản xạ toàn phần liên tiếp ở thành sợi.","cong_thuc":null,"y":["Gồm <b>lõi</b> chiết suất lớn, bọc bởi <b>vỏ</b> chiết suất nhỏ hơn.","Ánh sáng phản xạ toàn phần nhiều lần nên gần như không thoát ra ngoài.","Dùng trong cáp quang truyền internet, điện thoại và ống nội soi trong y học."],"bang":null,"bien":null,"vd":{"de":"Trong cáp quang, ánh sáng truyền đi xa hàng ki-lô-mét bên trong sợi thủy tinh mảnh dù sợi bị uốn cong nhẹ mà không thoát ra ngoài. Hiện tượng nào giúp điều này xảy ra?","buoc":["Ánh sáng trong sợi quang gặp thành sợi với góc tới lớn hơn góc tới hạn.","Điều này gây ra phản xạ toàn phần liên tiếp, giữ ánh sáng bên trong sợi."],"kq":"Nhờ hiện tượng phản xạ toàn phần liên tiếp ở thành sợi quang."},"nham":null,"lq":["l9-phan-xa-toan-phan","l9-goc-toi-han"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-lang-kinh","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":8,"loai":"cq","ten":"Lăng kính","ten_khac":["lang kinh","prism","lang kinh tam giac","goc chiet quang","mat ben"],"noi_dung":"Khối chất trong suốt (thường là thủy tinh) hình lăng trụ tam giác, dùng để làm lệch và tán sắc ánh sáng.","cong_thuc":null,"y":["Gồm hai <b>mặt bên</b> mà ánh sáng đi qua và <b>đáy</b>; góc giữa hai mặt bên gọi là góc chiết quang.","Tia sáng qua lăng kính bị khúc xạ hai lần và <b>lệch về phía đáy</b>.","Ánh sáng trắng qua lăng kính bị phân tách thành dải nhiều màu."],"bang":null,"bien":null,"vd":{"de":"Chiếu một tia sáng đơn sắc (một màu) qua một lăng kính. Tia ló ra có bị đổi màu không, chỉ bị thay đổi điều gì?","buoc":["Ánh sáng đơn sắc không bị tán sắc khi qua lăng kính.","Lăng kính chỉ làm lệch phương truyền của tia sáng."],"kq":"Tia ló không đổi màu, chỉ bị lệch phương truyền so với tia tới."},"nham":null,"lq":["l9-tan-sac-anh-sang","l9-anh-sang-trang","l9-khuc-xa-anh-sang"],"hinh":"H-l9-lang-kinh","nguon":["KHTN Pocket"]},{"ma":"l9-anh-sang-trang","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":9,"loai":"kn","ten":"Ánh sáng trắng","ten_khac":["anh sang trang","anh sang mat troi","anh sang mau","bay mau","quang pho","anh sang don sac"],"noi_dung":"Ánh sáng trắng là hỗn hợp của rất nhiều ánh sáng màu biến thiên liên tục từ đỏ đến tím, ví dụ ánh sáng Mặt Trời.","cong_thuc":null,"y":["Nguồn ánh sáng trắng: Mặt Trời, đèn sợi đốt, đèn LED trắng.","Dải màu tách ra gồm: <b>đỏ, cam, vàng, lục, lam, chàm, tím</b>.","Mỗi ánh sáng màu đơn sắc qua lăng kính chỉ bị lệch, không bị tách màu nữa."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l9-tan-sac-anh-sang","l9-lang-kinh","l9-mau-sac-vat"],"hinh":"H-l9-anh-sang-trang","nguon":["KHTN Pocket"]},{"ma":"l9-tan-sac-anh-sang","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":10,"loai":"ht","ten":"Sự tán sắc ánh sáng","ten_khac":["tan sac","tan sac anh sang","phan tich anh sang trang","cau vong","dispersion","dai mau"],"noi_dung":"Hiện tượng chùm ánh sáng trắng bị phân tách thành dải màu từ đỏ đến tím khi đi qua lăng kính.","cong_thuc":null,"y":["Nguyên nhân: chiết suất của lăng kính với mỗi ánh sáng màu khác nhau, nên mỗi màu lệch một góc khác nhau.","Ánh sáng <b>đỏ lệch ít nhất</b>, ánh sáng <b>tím lệch nhiều nhất</b>.","Cầu vồng là do ánh sáng Mặt Trời tán sắc qua các giọt nước mưa."],"bang":null,"bien":null,"vd":{"de":"Sau cơn mưa, khi có ánh nắng chiếu vào các hạt nước nhỏ trong không khí, ta thường thấy cầu vồng bảy sắc. Đây là hiện tượng gì của ánh sáng?","buoc":["Ánh sáng Mặt Trời là ánh sáng trắng, gồm nhiều ánh sáng màu.","Các hạt nước nhỏ đóng vai trò như lăng kính, tách ánh sáng trắng thành dải màu."],"kq":"Đó là hiện tượng tán sắc ánh sáng."},"nham":["Nghĩ lăng kính \"nhuộm màu\" ánh sáng; thật ra các màu có sẵn trong ánh sáng trắng."],"lq":["l9-lang-kinh","l9-anh-sang-trang","l9-mau-sac-vat"],"hinh":"H-l9-tan-sac-anh-sang","nguon":["KHTN Pocket"]},{"ma":"l9-mau-sac-vat","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":11,"loai":"kn","ten":"Màu sắc của vật","ten_khac":["mau sac vat","mau cua vat","vat mau den","vat mau trang","hap thu anh sang","tan xa anh sang"],"noi_dung":"Ta thấy vật có màu nào là do vật hắt lại (tán xạ) ánh sáng màu đó vào mắt.","cong_thuc":null,"y":["Vật màu nào thì <b>tán xạ mạnh ánh sáng màu đó</b>, hấp thụ các màu khác.","Vật màu trắng tán xạ tốt mọi ánh sáng màu; vật màu đen hầu như không tán xạ ánh sáng nào.","Chiếu ánh sáng đỏ vào vật màu xanh lục, ta thấy vật gần như màu đen."],"bang":null,"bien":null,"vd":{"de":"Một chiếc áo màu đỏ dưới ánh sáng trắng thì ta thấy nó màu đỏ. Nếu chiếu ánh sáng xanh lá cây (không có ánh sáng đỏ) vào chiếc áo đó trong phòng tối, ta sẽ thấy áo có màu gì?","buoc":["Ta thấy vật có màu nào là do vật hắt lại ánh sáng màu đó vào mắt.","Áo đỏ hắt lại ánh sáng đỏ nhưng không có ánh sáng đỏ chiếu tới để hắt lại."],"kq":"Áo sẽ có màu tối (gần như đen), không còn thấy màu đỏ."},"nham":["Nghĩ màu của vật không đổi dưới mọi ánh sáng chiếu tới."],"lq":["l9-anh-sang-trang","l9-tan-sac-anh-sang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-thau-kinh-hoi-tu","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":12,"loai":"cq","ten":"Thấu kính hội tụ","ten_khac":["thau kinh hoi tu","tkht","kinh rin mong","thau kinh loi","kinh lao","converging lens"],"noi_dung":"Thấu kính có phần rìa mỏng hơn phần giữa; chùm tia tới song song cho chùm tia ló hội tụ tại một điểm.","cong_thuc":null,"y":["Thấu kính: khối trong suốt giới hạn bởi hai mặt cầu, hoặc một mặt cầu và một mặt phẳng.","Kí hiệu trên hình vẽ: đoạn thẳng có hai mũi tên hướng ra ngoài.","Dùng làm kính lúp, kính lão, ống kính máy ảnh; có thể hội tụ ánh sáng Mặt Trời để đốt nóng."],"bang":null,"bien":null,"vd":{"de":"Sờ tay thấy một thấu kính có phần giữa dày hơn phần rìa. Đây là thấu kính gì?","buoc":["Thấu kính hội tụ có phần rìa mỏng hơn phần giữa.","Đặc điểm sờ được ở đây khớp với thấu kính hội tụ."],"kq":"Đó là thấu kính hội tụ."},"nham":["Nhận dạng thấu kính theo độ dày tổng thể thay vì so sánh rìa với phần giữa."],"lq":["l9-thau-kinh-phan-ki","l9-cau-tao-thau-kinh","l9-anh-qua-thau-kinh-hoi-tu","l9-kinh-lup"],"hinh":"H-l9-thau-kinh-hoi-tu","nguon":["KHTN Pocket"]},{"ma":"l9-thau-kinh-phan-ki","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":13,"loai":"cq","ten":"Thấu kính phân kì","ten_khac":["thau kinh phan ki","thau kinh phan ky","tkpk","kinh ria day","thau kinh lom","kinh can","diverging lens"],"noi_dung":"Thấu kính có phần rìa dày hơn phần giữa; chùm tia tới song song cho chùm tia ló loe rộng ra.","cong_thuc":null,"y":["Kí hiệu trên hình vẽ: đoạn thẳng có hai mũi tên hướng vào trong.","Đường kéo dài của các tia ló đi qua tiêu điểm ảo.","Dùng làm kính cận, kính nhìn trộm ở cửa."],"bang":null,"bien":null,"vd":{"de":"Sờ tay thấy một thấu kính khác có phần rìa dày hơn phần giữa. Đây là thấu kính gì?","buoc":["Thấu kính phân kì có phần rìa dày hơn phần giữa.","Đặc điểm sờ được ở đây khớp với thấu kính phân kì."],"kq":"Đó là thấu kính phân kì."},"nham":null,"lq":["l9-thau-kinh-hoi-tu","l9-anh-qua-thau-kinh-phan-ki","l9-cau-tao-thau-kinh"],"hinh":"H-l9-thau-kinh-phan-ki","nguon":["KHTN Pocket"]},{"ma":"l9-cau-tao-thau-kinh","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":14,"loai":"cq","ten":"Trục chính và quang tâm","ten_khac":["truc chinh","quang tam","o","truc phu","cac yeu to thau kinh","duong di tia sang qua thau kinh"],"noi_dung":"Quang tâm O là điểm giữa thấu kính; trục chính là đường thẳng qua O, vuông góc với mặt thấu kính.","cong_thuc":null,"y":["Tia sáng qua <b>quang tâm O</b> truyền thẳng, không đổi hướng.","Tia tới trùng trục chính thì truyền thẳng.","Mỗi thấu kính có hai tiêu điểm F, F′ nằm trên trục chính, đối xứng qua O."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l9-tieu-diem","l9-tieu-cu","l9-tia-sang-dac-biet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-tieu-diem","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":15,"loai":"kn","ten":"Tiêu điểm","ten_khac":["tieu diem","f","f phay","tieu diem chinh","diem hoi tu","focus"],"noi_dung":"Điểm trên trục chính mà chùm tia tới song song trục chính hội tụ tại đó (hoặc có đường kéo dài đi qua đó).","cong_thuc":null,"y":["Thấu kính hội tụ: tia ló hội tụ thật tại F′ (<b>tiêu điểm thật</b>).","Thấu kính phân kì: đường kéo dài của tia ló qua F′ (<b>tiêu điểm ảo</b>).","Mỗi thấu kính có 2 tiêu điểm F và F′ nằm hai bên, cách đều quang tâm."],"bang":null,"bien":null,"vd":{"de":"Chiếu một chùm tia sáng song song với trục chính vào một thấu kính hội tụ, các tia ló hội tụ tại một điểm trên trục chính. Điểm đó gọi là gì?","buoc":["Đây là điểm mà chùm tia tới song song trục chính hội tụ lại sau khi qua thấu kính.","Theo định nghĩa, điểm hội tụ như vậy có tên riêng."],"kq":"Đó là tiêu điểm của thấu kính."},"nham":null,"lq":["l9-tieu-cu","l9-cau-tao-thau-kinh","l9-tia-sang-dac-biet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-tieu-cu","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":16,"loai":"dl","ten":"Tiêu cự","ten_khac":["tieu cu","f","of","khoang cach tieu","focal length"],"noi_dung":"Khoảng cách từ quang tâm đến mỗi tiêu điểm của thấu kính, kí hiệu f.","cong_thuc":null,"y":["f = OF = OF′, đơn vị thường dùng cm hoặc m.","Thấu kính càng phồng (mặt cầu càng cong) thì tiêu cự càng ngắn.","Có thể đo tiêu cự thấu kính hội tụ bằng thí nghiệm tạo ảnh bằng vật."],"bang":null,"bien":null,"vd":{"de":"Một thấu kính hội tụ có hai tiêu điểm đối xứng qua quang tâm, mỗi tiêu điểm cách quang tâm 12 cm. Tiêu cự của thấu kính là bao nhiêu?","buoc":["Tiêu cự f là khoảng cách từ quang tâm O đến mỗi tiêu điểm.","Đề bài cho khoảng cách này là 12 cm."],"kq":"f = 12 cm"},"nham":["Nhầm tiêu cự (khoảng cách) với tiêu điểm (một điểm)."],"lq":["l9-tieu-diem","l9-do-tieu-cu","l9-so-boi-giac"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-tia-sang-dac-biet","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":17,"loai":"kn","ten":"Tia sáng đặc biệt qua thấu kính","ten_khac":["tia sang dac biet","ba tia dac biet","ve anh thau kinh","tia qua quang tam","tia song song truc chinh"],"noi_dung":"Ba đường truyền của tia sáng qua thấu kính biết trước, dùng để vẽ ảnh của vật.","cong_thuc":null,"y":["Tia qua <b>quang tâm O</b>: truyền thẳng.","Tia <b>song song trục chính</b>: tia ló qua tiêu điểm (thấu kính hội tụ) hoặc có đường kéo dài qua tiêu điểm cùng phía tia tới (thấu kính phân kì).","Tia tới qua tiêu điểm (thấu kính hội tụ) hoặc hướng tới tiêu điểm phía bên kia (thấu kính phân kì): tia ló song song trục chính.","Vẽ ảnh một điểm chỉ cần 2 trong 3 tia."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l9-anh-qua-thau-kinh-hoi-tu","l9-anh-qua-thau-kinh-phan-ki","l9-tieu-diem"],"hinh":"H-l9-tia-sang-dac-biet","nguon":["KHTN Pocket"]},{"ma":"l9-anh-that-anh-ao","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":18,"loai":"kn","ten":"Ảnh thật và ảnh ảo","ten_khac":["anh that","anh ao","anh hung duoc tren man","anh qua thau kinh","real image","virtual image"],"noi_dung":"Ảnh thật hứng được trên màn; ảnh ảo không hứng được trên màn, chỉ nhìn thấy qua thấu kính.","cong_thuc":null,"y":["Ảnh thật tạo bởi các tia ló <b>thực sự giao nhau</b>.","Ảnh ảo tạo bởi <b>đường kéo dài</b> của các tia ló.","Qua thấu kính hội tụ: ảnh thật thì ngược chiều vật, ảnh ảo thì cùng chiều vật."],"bang":null,"bien":null,"vd":{"de":"Đặt một màn ảnh sau thấu kính hội tụ đúng tại vị trí hội tụ của các tia sáng ló ra từ vật, thấy hiện rõ hình ảnh trên màn. Đây là ảnh thật hay ảnh ảo?","buoc":["Ảnh thật là ảnh hứng được trên màn chắn.","Ở đây ảnh hiện rõ được trên màn đặt sau thấu kính."],"kq":"Đó là ảnh thật."},"nham":null,"lq":["l9-anh-qua-thau-kinh-hoi-tu","l9-anh-qua-thau-kinh-phan-ki"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-anh-qua-thau-kinh-hoi-tu","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":19,"loai":"kn","ten":"Ảnh qua thấu kính hội tụ","ten_khac":["anh qua thau kinh hoi tu","anh tkht","dac diem anh","d > 2f","d < f","dung anh thau kinh"],"noi_dung":"Tùy vị trí vật, thấu kính hội tụ cho ảnh thật ngược chiều hoặc ảnh ảo cùng chiều lớn hơn vật.","cong_thuc":null,"y":["Tính độ lớn, vị trí ảnh bằng <b>tam giác đồng dạng</b> trên hình vẽ.","Vật ở rất xa: ảnh thật tại tiêu điểm F′."],"bang":[["Vị trí vật (d)","Đặc điểm ảnh"],["d > 2f","thật, ngược chiều, nhỏ hơn vật"],["d = 2f","thật, ngược chiều, bằng vật"],["f < d < 2f","thật, ngược chiều, lớn hơn vật"],["d < f","ảo, cùng chiều, lớn hơn vật"]],"bien":null,"vd":{"de":"Vật AB cao 2 cm đặt vuông góc trục chính, cách thấu kính hội tụ 30 cm; tiêu cự 10 cm. Tìm vị trí và chiều cao ảnh.","buoc":["Tam giác đồng dạng: A′B′/AB = OA′/OA và A′B′/AB = (OA′ − f)/f","→ OA′/30 = (OA′ − 10)/10 → OA′ = 15 cm","A′B′ = AB · OA′/OA = 2 · 15 : 30"],"kq":"Ảnh thật cách thấu kính 15 cm, cao 1 cm, ngược chiều vật"},"nham":["Vẽ tia qua F′ ở phía trước thấu kính.","Quên rằng vật đặt tại F thì không cho ảnh (ảnh ở rất xa)."],"lq":["l9-tia-sang-dac-biet","l9-anh-that-anh-ao","l9-thau-kinh-hoi-tu","l9-kinh-lup"],"hinh":"H-l9-anh-qua-thau-kinh-hoi-tu","nguon":["KHTN Pocket"]},{"ma":"l9-anh-qua-thau-kinh-phan-ki","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":20,"loai":"kn","ten":"Ảnh qua thấu kính phân kì","ten_khac":["anh qua thau kinh phan ki","anh tkpk","anh ao nho hon vat","anh thau kinh phan ky"],"noi_dung":"Vật đặt ở mọi vị trí trước thấu kính phân kì đều cho ảnh ảo, cùng chiều, nhỏ hơn vật.","cong_thuc":null,"y":["Ảnh luôn nằm <b>trong khoảng tiêu cự</b>, cùng phía với vật.","Vật ở rất xa: ảnh ảo nằm tại tiêu điểm.","Vì ảnh nhỏ hơn vật nên nhìn qua kính cận thấy vật nhỏ lại."],"bang":null,"bien":null,"vd":{"de":"Đặt một vật ở một vị trí bất kì trước thấu kính phân kì. Ảnh tạo ra có hứng được trên màn không, cùng chiều hay ngược chiều, lớn hơn hay nhỏ hơn vật?","buoc":["Vật đặt ở mọi vị trí trước thấu kính phân kì đều cho ảnh ảo.","Ảnh đó luôn cùng chiều và nhỏ hơn vật, dù vật ở gần hay xa thấu kính."],"kq":"Ảnh ảo, cùng chiều, nhỏ hơn vật (đúng với mọi vị trí đặt vật)."},"nham":null,"lq":["l9-thau-kinh-phan-ki","l9-tia-sang-dac-biet","l9-anh-that-anh-ao"],"hinh":"H-l9-anh-qua-thau-kinh-phan-ki","nguon":["KHTN Pocket"]},{"ma":"l9-do-tieu-cu","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":21,"loai":"tn","ten":"Đo tiêu cự thấu kính hội tụ","ten_khac":["do tieu cu","thuc hanh do tieu cu","f = l/4","anh bang vat","d = 2f"],"noi_dung":"Dịch thấu kính và màn đến khi ảnh rõ nét, cao bằng vật; khi đó vật và ảnh đều cách thấu kính 2f.","cong_thuc":"f = (d + d′)/4","y":["Dụng cụ: thấu kính hội tụ, vật sáng, màn chắn, giá quang học có thước.","Khi ảnh cao bằng vật: d = d′ = 2f, nên khoảng cách vật – màn bằng 4f.","Đo nhiều lần rồi lấy giá trị trung bình."],"bang":null,"bien":[["f","tiêu cự","cm"],["d","khoảng cách vật – thấu kính","cm"],["d′","khoảng cách ảnh (màn) – thấu kính","cm"]],"vd":{"de":"Ảnh rõ nét, cao bằng vật khi vật cách màn 60 cm. Tính tiêu cự.","buoc":["d + d′ = 4f = 60 cm"],"kq":"f = 15 cm"},"nham":null,"lq":["l9-tieu-cu","l9-anh-qua-thau-kinh-hoi-tu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-kinh-lup","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":22,"loai":"cq","ten":"Kính lúp","ten_khac":["kinh lup","kinh phong dai","magnifier","lup","quan sat vat nho"],"noi_dung":"Thấu kính hội tụ có tiêu cự ngắn, dùng để quan sát vật nhỏ.","cong_thuc":null,"y":["Đặt vật <b>trong khoảng tiêu cự</b> để có ảnh ảo, cùng chiều, lớn hơn vật.","Khả năng phóng đại cho bởi số bội giác, ghi trên vành kính (2x, 3x, 5x…).","Cách dùng: đặt kính gần vật, dịch từ từ ra xa đến khi nhìn rõ ảnh."],"bang":null,"bien":null,"vd":{"de":"Muốn quan sát rõ các chi tiết nhỏ trên một con tem, người chơi tem thường dùng dụng cụ quang học nào?","buoc":["Kính lúp là thấu kính hội tụ có tiêu cự ngắn, dùng để quan sát vật nhỏ.","Quan sát chi tiết trên tem là một vật nhỏ, cần phóng to vừa phải."],"kq":"Dùng kính lúp."},"nham":["Đặt vật ngoài khoảng tiêu cự nên thấy ảnh mờ hoặc lộn ngược."],"lq":["l9-so-boi-giac","l9-anh-qua-thau-kinh-hoi-tu","l9-thau-kinh-hoi-tu"],"hinh":"H-l9-kinh-lup","nguon":["KHTN Pocket"]},{"ma":"l9-so-boi-giac","mon":"KHTN","khoi":"9","chu_de":"l9-thau-kinh","thu_tu":23,"loai":"dl","ten":"Số bội giác","ten_khac":["so boi giac","g","g = 25/f","do phong dai kinh lup","2x","5x"],"noi_dung":"Số cho biết kính lúp giúp ta thấy ảnh lớn gấp bao nhiêu lần so với nhìn trực tiếp vật.","cong_thuc":"G = 25/f (mở rộng)","y":["Tiêu cự càng ngắn thì số bội giác càng lớn.","Trong công thức, f phải tính bằng <b>cm</b>."],"bang":null,"bien":[["G","số bội giác","(không đơn vị, ghi kèm x)"],["f","tiêu cự của kính lúp","cm"]],"vd":{"de":"Kính lúp có tiêu cự 5 cm. Tính số bội giác.","buoc":["G = 25/f = 25 : 5"],"kq":"G = 5 (ghi 5x)"},"nham":["