I."},"nham":["Mắc ampe kế song song với vật dẫn (gây đoản mạch, hỏng ampe kế)."],"lq":["l9-dien-tro","l9-dinh-luat-ohm"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-mach-noi-tiep","mon":"KHTN","khoi":"9","chu_de":"l9-dien","thu_tu":7,"loai":"ct","ten":"Đoạn mạch nối tiếp","ten_khac":["mach noi tiep","doan mach noi tiep","mac noi tiep","rtd = r1 + r2","u = u1 + u2","series"],"noi_dung":"Các điện trở mắc liên tiếp trên một đường, dòng điện có cùng cường độ qua mọi điện trở.","cong_thuc":"I = I₁ = I₂; U = U₁ + U₂; Rtđ = R₁ + R₂","y":["Hiệu điện thế chia theo tỉ lệ điện trở: U₁/U₂ = R₁/R₂.","Điện trở tương đương lớn hơn mỗi điện trở thành phần.","Một điện trở bị đứt thì cả mạch mất dòng điện."],"bang":null,"bien":[["I","cường độ dòng điện","A"],["U","hiệu điện thế","V"],["Rtđ","điện trở tương đương","Ω"]],"vd":{"de":"R₁ = 10 Ω nối tiếp R₂ = 20 Ω, mắc vào hiệu điện thế 12 V. Tính I, U₁, U₂.","buoc":["Rtđ = 10 + 20 = 30 Ω","I = U/Rtđ = 12 : 30 = 0,4 A","U₁ = I·R₁ = 4 V; U₂ = I·R₂ = 8 V"],"kq":"I = 0,4 A; U₁ = 4 V; U₂ = 8 V"},"nham":["Nghĩ dòng điện \"yếu dần\" khi qua từng điện trở."],"lq":["l9-mach-song-song","l9-dien-tro-tuong-duong","l9-dinh-luat-ohm"],"hinh":"H-l9-mach-noi-tiep","nguon":["KHTN Pocket"]},{"ma":"l9-mach-song-song","mon":"KHTN","khoi":"9","chu_de":"l9-dien","thu_tu":8,"loai":"ct","ten":"Đoạn mạch song song","ten_khac":["mach song song","doan mach song song","mac song song","1/rtd","i = i1 + i2","parallel"],"noi_dung":"Các điện trở mắc giữa cùng hai điểm, hiệu điện thế giữa hai đầu mỗi điện trở bằng nhau.","cong_thuc":"U = U₁ = U₂; I = I₁ + I₂; 1/Rtđ = 1/R₁ + 1/R₂","y":["Dòng điện chia theo tỉ lệ nghịch điện trở: I₁/I₂ = R₂/R₁.","Điện trở tương đương <b>nhỏ hơn</b> mỗi điện trở thành phần.","Hai điện trở: Rtđ = R₁R₂/(R₁ + R₂). Đồ dùng trong nhà được mắc song song."],"bang":null,"bien":[["I","cường độ dòng điện mạch chính","A"],["U","hiệu điện thế","V"],["Rtđ","điện trở tương đương","Ω"]],"vd":{"de":"R₁ = 6 Ω song song R₂ = 3 Ω, mắc vào hiệu điện thế 6 