","cường độ dòng điện","A"],["P","công suất điện","W"],["t","thời gian","s"]],"vd":{"de":"Bóng đèn 220 V – 100 W sáng bình thường trong 5 giờ. Tính năng lượng điện tiêu thụ.","buoc":["W = P · t = 100 W · 5 h = 500 Wh","= 0,5 kWh = 0,5 · 3 600 000 J"],"kq":"W = 0,5 kWh = 1 800 000 J"},"nham":["Nhân W với giờ nhưng lại ghi đơn vị J."],"lq":["l9-cong-suat-dien","l9-kilowatt-gio","l9-cong-to-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-cong-suat-dien","mon":"KHTN","khoi":"9","chu_de":"l9-dien","thu_tu":11,"loai":"dl","ten":"Công suất điện","ten_khac":["cong suat dien","p = ui","p = u.i","oat","watt","i2r","u2/r"],"noi_dung":"Đại lượng cho biết năng lượng điện mà dụng cụ tiêu thụ trong một đơn vị thời gian.","cong_thuc":"P = UI","y":["(Mở rộng) Dụng cụ chỉ có điện trở, kết hợp định luật Ohm: P = I²R = U²/R.","Công suất càng lớn thì dụng cụ tiêu thụ điện càng nhanh."],"bang":null,"bien":[["P","công suất điện","W"],["U","hiệu điện thế","V"],["I","cường độ dòng điện","A"]],"vd":{"de":"Một quạt điện dùng ở hiệu điện thế 220 V, dòng điện qua quạt 0,5 A. Tính công suất.","buoc":["P = U · I = 220 · 0,5"],"kq":"P = 110 W"},"nham":["Nhầm đơn vị W (oát, công suất) với W (kí hiệu năng lượng)."],"lq":["l9-cong-suat-dinh-muc","l9-nang-luong-dien","l9-cong-suat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-cong-suat-dinh-muc","mon":"KHTN","khoi":"9","chu_de":"l9-dien","thu_tu":12,"loai":"kn","ten":"Công suất định mức","ten_khac":["cong suat dinh muc","so oat","so von","220v 100w","hieu dien the dinh muc","hoat dong binh thuong"],"noi_dung":"Công suất ghi trên dụng cụ điện, là công suất khi dụng cụ dùng đúng hiệu điện thế định mức.","cong_thuc":null,"y":["Ví dụ \"220 V – 60 W\": dùng ở 220 V thì đèn sáng bình thường, công suất 60 W.","Dùng hiệu điện thế nhỏ hơn: dụng cụ hoạt động yếu; lớn hơn: dễ hỏng.","Từ số ghi tính được cường độ dòng điện định mức I = P/U."],"bang":null,"bien":null,"vd":{"de":"Đèn ghi 220 V – 60 W sáng bình thường. Tính cường độ dòng điện qua đèn.","buoc":["I = P/U = 60 : 220"],"kq":"I ≈ 0,27 A"},"nham":null,"lq":["l9-cong-suat-dien","l9-nang-luong-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-kilowatt-gio","mon":"KHTN","khoi":"9","chu_de":"l9-dien","thu_tu":13,"loai":"dl","ten":"Kilowatt giờ","ten_khac":["kilowatt gio","kwh","kw.h","so dien","mot so dien","kilooat gio"],"noi_dung":"Đơn vị năng lượng điện thường dùng, bằng năng lượng dụng cụ công suất 1 kW tiêu thụ trong 1 giờ.","cong_thuc":"1 kWh = 3 600 000 J","y":["Mỗi \"số điện\" trên công tơ là 1 kWh.","Tính nhanh: W (kWh) = P (kW) × t (h)."],"bang":null,"bien":[["kWh","kilowatt giờ (\"số điện\")",""],["J","jun",""]],"vd":{"de":"Bếp điện 1 000 W dùng 2 giờ mỗi ngày. Tính điện năng tiêu thụ trong 30 ngày.","buoc":["Mỗi ngày: 1 kW · 2 h = 2 kWh","30 ngày: 2 · 30"],"kq":"60 kWh (60 số điện)"},"nham":["Nhầm kW (công suất) với kWh (năng lượng)."],"lq":["l9-nang-luong-dien","l9-cong-to-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-cong-to-dien","mon":"KHTN","khoi":"9","chu_de":"l9-dien","thu_tu":14,"loai":"tn","ten":"Công tơ điện","ten_khac":["cong to dien","dong ho dien","dong ho do dien","so dien","dien ke"],"noi_dung":"Dụng cụ đo năng lượng điện mà gia đình, cơ sở đã tiêu thụ, tính bằng kWh.","cong_thuc":null,"y":["Số chỉ tăng thêm sau một thời gian = điện năng tiêu thụ trong thời gian đó.","Tiền điện = số kWh tiêu thụ × giá điện (tính theo bậc)."],"bang":null,"bien":null,"vd":{"de":"Công tơ điện nhà bạn A chỉ 1 250 kWh vào đầu tháng và 1 320 kWh vào cuối tháng. Gia đình đã tiêu thụ bao nhiêu điện năng trong tháng đó?","buoc":["Điện năng tiêu thụ = số cuối tháng − số đầu tháng.","1 320 − 1 250"],"kq":"70 kWh"},"nham":null,"lq":["l9-kilowatt-gio","l9-nang-luong-dien","l9-tiet-kiem-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-tiet-kiem-dien","mon":"KHTN","khoi":"9","chu_de":"l9-dien","thu_tu":15,"loai":"ud","ten":"Tiết kiệm điện năng","ten_khac":["tiet kiem dien","tiet kiem dien nang","dung dien hop li","den led","nhan nang luong"],"noi_dung":"Dùng điện hợp lí để giảm chi phí, giảm khai thác nhiên liệu và giảm ô nhiễm môi trường.","cong_thuc":null,"y":["Tắt thiết bị khi không dùng, rút phích sạc khi đầy.","Dùng đèn LED, thiết bị có <b>nhãn năng lượng</b> tiết kiệm.","Tận dụng ánh sáng, gió tự nhiên; không để điều hòa quá lạnh."],"bang":null,"bien":null,"vd":{"de":"Bóng đèn sợi đốt 60 W và bóng đèn LED 9 W cho độ sáng tương đương nhau. Dùng bóng đèn nào tiết kiệm điện hơn?","buoc":["Công suất càng nhỏ thì điện năng tiêu thụ trong cùng thời gian càng ít.","So sánh: 9 W nhỏ hơn nhiều so với 60 W, cùng độ sáng."],"kq":"Đèn LED 9 W tiết kiệm điện hơn."},"nham":null,"lq":["l9-nang-luong-dien","l9-su-dung-nang-luong-hop-li"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-cam-ung-dien-tu","mon":"KHTN","khoi":"9","chu_de":"l9-dien-tu","thu_tu":1,"loai":"ht","ten":"Hiện tượng cảm ứng điện từ","ten_khac":["cam ung dien tu","hien tuong cam ung","faraday","nam cham cuon day","electromagnetic induction"],"noi_dung":"Hiện tượng xuất hiện dòng điện trong cuộn dây dẫn kín khi số đường sức từ xuyên qua tiết diện cuộn dây biến thiên.","cong_thuc":null,"y":["Tạo được bằng cách đưa nam châm lại gần hoặc ra xa cuộn dây, hoặc quay nam châm trước cuộn dây.","Dòng điện chỉ xuất hiện khi đang có <b>sự biến thiên</b>; nam châm đứng yên thì không có.","Là cơ sở của máy phát điện."],"bang":null,"bien":null,"vd":{"de":"Đưa nhanh một thanh nam châm vào trong một cuộn dây dẫn kín, kim điện kế nối với cuộn dây bị lệch trong chốc lát. Hiện tượng gì đã xảy ra?","buoc":["Số đường sức từ xuyên qua tiết diện cuộn dây thay đổi khi nam châm di chuyển vào.","Sự biến thiên đó làm xuất hiện dòng điện trong cuộn dây, kim điện kế bị lệch."],"kq":"Đó là hiện tượng cảm ứng điện từ."},"nham":null,"lq":["l9-dong-dien-cam-ung","l9-duong-suc-tu-bien-thien","l9-may-phat-dien-xoay-chieu"],"hinh":"H-l9-cam-ung-dien-tu","nguon":["KHTN Pocket"]},{"ma":"l9-dong-dien-cam-ung","mon":"KHTN","khoi":"9","chu_de":"l9-dien-tu","thu_tu":2,"loai":"kn","ten":"Dòng điện cảm ứng","ten_khac":["dong dien cam ung","dieu kien xuat hien dong dien cam ung","dong cam ung","induced current"],"noi_dung":"Dòng điện xuất hiện trong cuộn dây dẫn kín do hiện tượng cảm ứng điện từ.","cong_thuc":null,"y":["Điều kiện: cuộn dây <b>kín</b> và số đường sức từ xuyên qua tiết diện cuộn dây <b>biến thiên</b>.","Số đường sức từ tăng và giảm thì dòng cảm ứng có chiều ngược nhau.","Nhận biết bằng đèn LED hoặc điện kế mắc vào cuộn dây."],"bang":null,"bien":null,"vd":{"de":"Khi rút nhanh một thanh nam châm ra khỏi cuộn dây dẫn kín, trong cuộn dây có xuất hiện dòng điện không? Dòng điện đó (nếu có) gọi là gì?","buoc":["Rút nam châm ra cũng làm số đường sức từ qua cuộn dây biến thiên.","Sự biến thiên này gây ra dòng điện trong cuộn dây kín."],"kq":"Có xuất hiện; đó là dòng điện cảm ứng."},"nham":["Cho rằng chỉ cần có nam châm gần cuộn dây là có dòng điện."],"lq":["l9-cam-ung-dien-tu","l9-duong-suc-tu-bien-thien","l9-dong-dien-xoay-chieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-duong-suc-tu-bien-thien","mon":"KHTN","khoi":"9","chu_de":"l9-dien-tu","thu_tu":3,"loai":"kn","ten":"Số đường sức từ biến thiên","ten_khac":["so duong suc tu","duong suc tu bien thien","tu thong","bien thien tu truong","tiet dien cuon day"],"noi_dung":"Sự tăng hoặc giảm số đường sức từ xuyên qua tiết diện cuộn dây, là nguyên nhân gây ra dòng điện cảm ứng.","cong_thuc":null,"y":["Làm biến thiên: di chuyển nam châm hoặc cuộn dây, quay nam châm hoặc cuộn dây.","Hoặc đóng, ngắt, thay đổi dòng điện trong nam châm điện đặt gần cuộn dây.","Biến thiên càng nhanh thì dòng cảm ứng càng mạnh."],"bang":null,"bien":null,"vd":{"de":"Giữ nam châm và cuộn dây đứng yên, không có gì chuyển động. Cuộn dây có xuất hiện dòng điện cảm ứng không?","buoc":["Dòng điện cảm ứng chỉ xuất hiện khi số đường sức từ qua cuộn dây biến thiên (tăng hoặc giảm).","Ở đây không có chuyển động nên số đường sức từ qua cuộn dây không đổi."],"kq":"Không; vì số đường sức từ qua cuộn dây không biến thiên."},"nham":null,"lq":["l9-cam-ung-dien-tu","l9-dong-dien-cam-ung"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-dong-dien-xoay-chieu","mon":"KHTN","khoi":"9","chu_de":"l9-dien-tu","thu_tu":4,"loai":"kn","ten":"Dòng điện xoay chiều","ten_khac":["dong dien xoay chieu","xoay chieu","ac","dien luoi","dong dien doi chieu","alternating current"],"noi_dung":"Dòng điện luân phiên đổi chiều liên tục theo thời gian.","cong_thuc":null,"y":["Điện lưới gia đình ở Việt Nam là dòng xoay chiều 220 V, đổi chiều 100 lần mỗi giây (tần số 50 Hz).","Kí hiệu AC hoặc dấu ~ trên thiết bị.","Khác <b>dòng điện một chiều</b> (pin, acquy) có chiều không đổi."],"bang":null,"bien":null,"vd":{"de":"Dòng điện lấy từ ổ cắm điện trong nhà (220 V) có chiều liên tục đổi qua đổi lại rất nhanh. Đây là loại dòng điện gì?","buoc":["Dòng điện xoay chiều là dòng điện luân phiên đổi chiều liên tục theo thời gian.","Dòng điện từ ổ cắm có đặc điểm này."],"kq":"Đó là dòng điện xoay chiều."},"nham":["Nghĩ dòng xoay chiều là dòng electron chạy vòng tròn."],"lq":["l9-tao-dong-dien-xoay-chieu","l9-tac-dung-dong-xoay-chieu","l9-dong-dien-mot-chieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-dong-dien-mot-chieu","mon":"KHTN","khoi":"9","chu_de":"l9-dien-tu","thu_tu":5,"loai":"kn","ten":"Dòng điện một chiều","ten_khac":["dong dien mot chieu","mot chieu","dc","pin","acquy","direct current"],"noi_dung":"Dòng điện có chiều không đổi theo thời gian, ví dụ dòng điện do pin, acquy tạo ra.","cong_thuc":null,"y":["Kí hiệu DC hoặc dấu – trên thiết bị.","Nguồn một chiều có cực dương (+) và cực âm (–) cố định.","Bộ sạc điện thoại biến dòng xoay chiều thành dòng một chiều."],"bang":null,"bien":null,"vd":{"de":"Dòng điện lấy từ một viên pin tiểu luôn chạy theo một chiều từ cực dương qua mạch ngoài tới cực âm, không đổi chiều. Đây là dòng điện gì?","buoc":["Dòng điện một chiều có chiều không đổi theo thời gian.","Dòng điện từ pin có đặc điểm này."],"kq":"Đó là dòng điện một chiều."},"nham":null,"lq":["l9-dong-dien-xoay-chieu","l9-tac-dung-dong-xoay-chieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-tao-dong-dien-xoay-chieu","mon":"KHTN","khoi":"9","chu_de":"l9-dien-tu","thu_tu":6,"loai":"ht","ten":"Nguyên tắc tạo dòng điện xoay chiều","ten_khac":["nguyen tac tao dong dien xoay chieu","tao dong xoay chieu","quay nam cham","quay cuon day"],"noi_dung":"Cho số đường sức từ qua cuộn dây kín luân phiên tăng, giảm thì trong cuộn dây xuất hiện dòng điện xoay chiều.","cong_thuc":null,"y":["Cách 1: <b>quay nam châm</b> trước cuộn dây dẫn kín.","Cách 2: <b>quay cuộn dây</b> trong từ trường của nam châm.","Số đường sức từ tăng thì dòng cảm ứng chạy một chiều, giảm thì chạy chiều ngược lại."],"bang":null,"bien":null,"vd":{"de":"Cho một cuộn dây dẫn kín quay đều trong từ trường của một nam châm, số đường sức từ qua cuộn dây liên tục tăng giảm luân phiên. Hiện tượng gì xảy ra trong cuộn dây?","buoc":["Số đường sức từ biến thiên luân phiên tăng, giảm sẽ gây ra dòng điện cảm ứng đổi chiều liên tục.","Đây đúng là nguyên tắc tạo ra dòng điện xoay chiều."],"kq":"Xuất hiện dòng điện xoay chiều trong cuộn dây."},"nham":null,"lq":["l9-dong-dien-xoay-chieu","l9-may-phat-dien-xoay-chieu","l9-cam-ung-dien-tu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-may-phat-dien-xoay-chieu","mon":"KHTN","khoi":"9","chu_de":"l9-dien-tu","thu_tu":7,"loai":"cq","ten":"Máy phát điện xoay chiều","ten_khac":["may phat dien xoay chieu","may phat dien","rotor","stator","roto","stato","generator"],"noi_dung":"Máy biến đổi cơ năng thành điện năng dựa trên hiện tượng cảm ứng điện từ.","cong_thuc":null,"y":["Hai bộ phận chính: <b>nam châm</b> và <b>cuộn dây</b>.","Bộ phận quay gọi là <b>rotor</b>, bộ phận đứng yên gọi là <b>stator</b>.","Nhà máy điện dùng tuabin (quay nhờ hơi nước, dòng nước, gió) để quay rotor."],"bang":null,"bien":null,"vd":{"de":"Ở nhà máy thủy điện, nước chảy làm quay tuabin nối với một bộ phận tạo ra dòng điện xoay chiều. Bộ phận đó gọi là gì?","buoc":["Bộ phận này biến đổi cơ năng thành điện năng dựa trên cảm ứng điện từ.","Đây đúng là chức năng của một thiết bị có tên riêng."],"kq":"Đó là máy phát điện xoay chiều."},"nham":null,"lq":["l9-tao-dong-dien-xoay-chieu","l9-dinamo-xe-dap","l9-cam-ung-dien-tu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-dinamo-xe-dap","mon":"KHTN","khoi":"9","chu_de":"l9-dien-tu","thu_tu":8,"loai":"ud","ten":"Đinamô xe đạp","ten_khac":["dinamo","dinamo xe dap","may phat dien xe dap","den xe dap","dynamo"],"noi_dung":"Máy phát điện xoay chiều nhỏ, nam châm quay nhờ bánh xe để thắp sáng đèn xe đạp.","cong_thuc":null,"y":["Núm đinamô tì vào bánh xe; bánh quay làm nam châm quay trước cuộn dây cố định.","Đạp càng nhanh, đèn càng sáng."],"bang":null,"bien":null,"vd":{"de":"Khi xe đạp chạy, núm đinamô tì vào lốp xe quay tròn làm đèn xe sáng lên; khi xe dừng, đèn tắt. Đinamô đã chuyển hóa dạng năng lượng nào thành điện năng?","buoc":["Đinamô xe đạp là một máy phát điện xoay chiều nhỏ.","Bánh xe quay làm nam châm trong đinamô quay theo, tạo ra dòng điện."],"kq":"Động năng (cơ năng) của bánh xe quay chuyển hóa thành điện năng."},"nham":null,"lq":["l9-may-phat-dien-xoay-chieu","l9-tao-dong-dien-xoay-chieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-tac-dung-dong-xoay-chieu","mon":"KHTN","khoi":"9","chu_de":"l9-dien-tu","thu_tu":9,"loai":"kn","ten":"Tác dụng của dòng điện xoay chiều","ten_khac":["tac dung dong dien xoay chieu","tac dung nhiet","tac dung phat sang","tac dung tu","tac dung sinh li"],"noi_dung":"Dòng điện xoay chiều có tác dụng nhiệt, phát sáng, từ, sinh lí,… giống dòng điện một chiều.","cong_thuc":null,"y":["<b>Nhiệt</b>: bàn là, nồi cơm điện; <b>phát sáng</b>: bóng đèn.","<b>Từ</b>: quạt điện, máy bơm; lực từ đổi chiều khi dòng điện đổi chiều.","<b>Sinh lí</b>: điện giật nguy hiểm, cần tuân thủ an toàn điện."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ dòng xoay chiều không làm nóng dây dẫn."],"lq":["l9-dong-dien-xoay-chieu","l9-do-dong-xoay-chieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-do-dong-xoay-chieu","mon":"KHTN","khoi":"9","chu_de":"l9-dien-tu","thu_tu":10,"loai":"tn","ten":"Đo dòng điện xoay chiều","ten_khac":["ampe ke xoay chieu","von ke xoay chieu","dong ho van nang","thang do ac","do dien ap xoay chieu"],"noi_dung":"Dùng ampe kế, vôn kế xoay chiều (thang đo AC hoặc ~) để đo cường độ và hiệu điện thế xoay chiều.","cong_thuc":null,"y":["Mắc dụng cụ đo <b>không cần phân biệt</b> chốt (+), (–).","Ampe kế mắc nối tiếp, vôn kế mắc song song như với dòng một chiều.","Số chỉ là giá trị hiệu dụng, ví dụ 220 V của điện lưới."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l9-dong-dien-xoay-chieu","l9-tac-dung-dong-xoay-chieu","l9-do-dien-tro"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-vong-nang-luong","mon":"KHTN","khoi":"9","chu_de":"l9-nang-luong","thu_tu":1,"loai":"kn","ten":"Vòng năng lượng trên Trái Đất","ten_khac":["vong nang luong","vong nang luong trai dat","nang luong mat troi","chuyen hoa nang luong","dong nang luong"],"noi_dung":"Năng lượng từ Mặt Trời được chuyển hóa qua nhiều dạng (gió, nước, sinh khối, nhiên liệu) và luân chuyển trên Trái Đất.","cong_thuc":null,"y":["Mặt Trời là <b>nguồn năng lượng chủ yếu</b> của Trái Đất.","Ví dụ: nắng làm nước bay hơi → mưa → sông chảy → thủy điện.","Thực vật quang hợp tích năng lượng; xác sinh vật qua hàng triệu năm thành than, dầu mỏ."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l9-nang-luong-hoa-thach","l9-nang-luong-tai-tao","l9-nang-luong-mat-troi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-nang-luong-hoa-thach","mon":"KHTN","khoi":"9","chu_de":"l9-nang-luong","thu_tu":2,"loai":"ch","ten":"Năng lượng hóa thạch","ten_khac":["nang luong hoa thach","nhien lieu hoa thach","than da","dau mo","khi dot","khong tai tao"],"noi_dung":"Năng lượng từ than đá, dầu mỏ, khí tự nhiên – hình thành từ xác sinh vật qua hàng triệu năm.","cong_thuc":null,"y":["Là năng lượng <b>không tái tạo</b>: dùng hết thì không bù lại kịp.","Ưu: dễ khai thác, dự trữ, cho nhiều năng lượng.","Nhược: đốt sinh ra CO₂ (tăng hiệu ứng nhà kính), khí độc, bụi gây ô nhiễm."],"bang":null,"bien":null,"vd":{"de":"Đốt than đá để chạy nhà máy nhiệt điện. Sau khi đốt hết, phải mất khoảng bao lâu để tự nhiên tạo ra lượng than đá tương đương?","buoc":["Năng lượng hóa thạch hình thành từ xác sinh vật qua một quá trình rất dài.","Quá trình này kéo dài hàng triệu năm."],"kq":"Phải mất hàng triệu năm, nên than đá là nguồn năng lượng không tái tạo."},"nham":["Nghĩ khí đốt, dầu mỏ là năng lượng tái tạo vì \"khai thác mãi vẫn còn\"."],"lq":["l9-nha-may-nhiet-dien","l9-hieu-ung-nha-kinh","l9-nang-luong-tai-tao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-nha-may-nhiet-dien","mon":"KHTN","khoi":"9","chu_de":"l9-nang-luong","thu_tu":3,"loai":"ud","ten":"Nhà máy nhiệt điện","ten_khac":["nha may nhiet dien","nhiet dien","nhiet dien than","dot than phat dien","lo hoi tuabin"],"noi_dung":"Nhà máy đốt nhiên liệu (thường là than, khí) đun sôi nước, hơi nước làm quay tuabin và máy phát điện.","cong_thuc":null,"y":["Chuyển hóa: hóa năng → nhiệt năng → cơ năng → điện năng.","Ưu: xây ở nhiều nơi, phát điện ổn định.","Nhược: tốn nhiên liệu hóa thạch, thải nhiều khí CO₂, bụi, gây ô nhiễm."],"bang":null,"bien":null,"vd":{"de":"Ở nhà máy nhiệt điện: đốt than tạo nhiệt làm nước sôi, hơi nước làm quay tuabin, tuabin quay làm quay máy phát điện. Đây là chuỗi chuyển hóa từ dạng năng lượng nào sang dạng nào?","buoc":["Than cháy giải phóng năng lượng hóa học thành nhiệt năng làm nước sôi.","Hơi nước làm quay tuabin (động năng), tuabin quay máy phát tạo ra điện năng."],"kq":"Hóa năng → nhiệt năng → động năng → điện năng."},"nham":null,"lq":["l9-nang-luong-hoa-thach","l9-may-phat-dien-xoay-chieu","l9-thuy-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-nang-luong-tai-tao","mon":"KHTN","khoi":"9","chu_de":"l9-nang-luong","thu_tu":4,"loai":"kn","ten":"Năng lượng tái tạo","ten_khac":["nang luong tai tao","nang luong sach","renewable","nang luong xanh","tai tao"],"noi_dung":"Năng lượng từ nguồn có sẵn trong tự nhiên, được bổ sung liên tục, gần như không cạn kiệt.","cong_thuc":null,"y":["Gồm: năng lượng <b>Mặt Trời, gió, nước (thủy điện), sinh khối, địa nhiệt</b>, sóng biển.","Ưu: ít phát thải khí nhà kính, ít gây ô nhiễm.","Nhược: phụ thuộc thời tiết, địa điểm; chi phí đầu tư ban đầu cao."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l9-nang-luong-mat-troi","l9-nang-luong-gio","l9-thuy-dien","l9-nang-luong-sinh-khoi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-nang-luong-mat-troi","mon":"KHTN","khoi":"9","chu_de":"l9-nang-luong","thu_tu":5,"loai":"ch","ten":"Năng lượng Mặt Trời","ten_khac":["nang luong mat troi","dien mat troi","pin mat troi","tam pin","may nuoc nong mat troi","solar"],"noi_dung":"Năng lượng ánh sáng và nhiệt từ Mặt Trời, được dùng để phát điện hoặc đun nóng.","cong_thuc":null,"y":["<b>Pin mặt trời</b>: biến đổi trực tiếp quang năng thành điện năng.","Máy nước nóng năng lượng mặt trời: quang năng → nhiệt năng.","Hạn chế: không phát điện ban đêm, giảm mạnh khi trời nhiều mây."],"bang":null,"bien":null,"vd":{"de":"Tấm pin quang điện lắp trên mái nhà chuyển hóa trực tiếp ánh sáng Mặt Trời thành dạng năng lượng nào?","buoc":["Năng lượng Mặt Trời là năng lượng ánh sáng và nhiệt từ Mặt Trời.","Pin quang điện biến đổi trực tiếp ánh sáng chiếu vào thành dòng điện."],"kq":"Chuyển hóa thành điện năng."},"nham":null,"lq":["l9-nang-luong-tai-tao","l9-vong-nang-luong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-nang-luong-gio","mon":"KHTN","khoi":"9","chu_de":"l9-nang-luong","thu_tu":6,"loai":"ch","ten":"Năng lượng gió","ten_khac":["nang luong gio","dien gio","tuabin gio","coi xay gio","wind"],"noi_dung":"Động năng của gió, được dùng làm quay tuabin gió để phát điện.","cong_thuc":null,"y":["Chuyển hóa: động năng gió → cơ năng tuabin → điện năng.","Phù hợp vùng ven biển, cao nguyên có gió mạnh và đều.","Hạn chế: phụ thuộc gió, gây tiếng ồn, chiếm diện tích."],"bang":null,"bien":null,"vd":{"de":"Cánh quạt của tuabin gió quay khi có gió thổi qua, làm quay máy phát điện. Năng lượng gió ở đây là dạng năng lượng nào của không khí chuyển động?","buoc":["Năng lượng gió là động năng của khối không khí đang chuyển động.","Gió thổi làm cánh quạt quay, rồi tuabin quay máy phát điện."],"kq":"Đó là động năng của gió, chuyển hóa thành điện năng."},"nham":null,"lq":["l9-nang-luong-tai-tao","l9-may-phat-dien-xoay-chieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-thuy-dien","mon":"KHTN","khoi":"9","chu_de":"l9-nang-luong","thu_tu":7,"loai":"ud","ten":"Thủy điện","ten_khac":["thuy dien","nha may thuy dien","nang luong nuoc","dap thuy dien","ho chua"],"noi_dung":"Dùng năng lượng của dòng nước từ hồ chứa trên cao chảy xuống làm quay tuabin phát điện.","cong_thuc":null,"y":["Chuyển hóa: thế năng của nước → động năng → điện năng.","Ưu: không đốt nhiên liệu, hồ chứa còn điều tiết lũ, cấp nước.","Nhược: làm ngập rừng, thay đổi dòng chảy, ảnh hưởng hệ sinh thái; phụ thuộc lượng mưa."],"bang":null,"bien":null,"vd":{"de":"Nước từ hồ chứa trên núi cao được dẫn xuống thấp qua ống, làm quay tuabin phát điện. Thế năng của nước ở trên cao đã chuyển hóa thành các dạng năng lượng nào?","buoc":["Nước ở trên cao có thế năng hấp dẫn lớn.","Khi chảy xuống, thế năng chuyển thành động năng (nước chảy), rồi tuabin và máy phát biến đổi thành điện năng."],"kq":"Thế năng → động năng → điện năng."},"nham":null,"lq":["l9-nang-luong-tai-tao","l9-the-nang","l9-nha-may-nhiet-dien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-nang-luong-sinh-khoi","mon":"KHTN","khoi":"9","chu_de":"l9-nang-luong","thu_tu":8,"loai":"ch","ten":"Năng lượng sinh khối","ten_khac":["nang luong sinh khoi","sinh khoi","biogas","khi sinh hoc","nhien lieu sinh hoc","ethanol","biomass"],"noi_dung":"Năng lượng từ vật liệu hữu cơ như gỗ, rơm rạ, bã mía, chất thải chăn nuôi.","cong_thuc":null,"y":["Dùng đốt trực tiếp hoặc tạo <b>khí sinh học (biogas)</b>, nhiên liệu sinh học (xăng E5, E10).","Tận dụng chất thải, giảm ô nhiễm môi trường nông thôn.","Vẫn thải CO₂ khi đốt nhưng cây trồng mới hấp thụ lại."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l9-nang-luong-tai-tao","l9-vong-nang-luong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-nang-luong-dia-nhiet","mon":"KHTN","khoi":"9","chu_de":"l9-nang-luong","thu_tu":9,"loai":"ch","ten":"Năng lượng địa nhiệt","ten_khac":["nang luong dia nhiet","dia nhiet","nhiet long dat","suoi nuoc nong","geothermal"],"noi_dung":"Nhiệt năng từ lòng Trái Đất, dùng để sưởi ấm hoặc phát điện.","cong_thuc":null,"y":["Khai thác hơi nước, nước nóng từ lòng đất để quay tuabin.","Chỉ khai thác hiệu quả ở một số vùng có nguồn nhiệt gần mặt đất."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l9-nang-luong-tai-tao","l9-vong-nang-luong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-hieu-ung-nha-kinh","mon":"KHTN","khoi":"9","chu_de":"l9-nang-luong","thu_tu":10,"loai":"ht","ten":"Hiệu ứng nhà kính","ten_khac":["hieu ung nha kinh","khi nha kinh","co2","nong len toan cau","bien doi khi hau","am len toan cau"],"noi_dung":"Hiện tượng khí nhà kính trong khí quyển giữ lại một phần nhiệt Trái Đất tỏa ra, làm Trái Đất ấm lên.","cong_thuc":null,"y":["Khí nhà kính chính: CO₂, CH₄ (methane), hơi nước.","Đốt nhiên liệu hóa thạch làm tăng CO₂ → <b>Trái Đất nóng lên</b>, biến đổi khí hậu.","Giảm bằng cách tiết kiệm năng lượng, dùng năng lượng tái tạo, trồng rừng."],"bang":null,"bien":null,"vd":{"de":"Vì sao khi lượng khí CO₂ trong khí quyển tăng lên, nhiệt độ trung bình của Trái Đất có xu hướng tăng?","buoc":["CO₂ là khí nhà kính: nó giữ lại một phần nhiệt mà mặt đất tỏa ra, không cho thoát hết ra không gian.","Lượng CO₂ càng nhiều thì nhiệt bị giữ lại càng nhiều."],"kq":"Hiệu ứng nhà kính tăng lên làm Trái Đất nóng dần."},"nham":null,"lq":["l9-nang-luong-hoa-thach","l9-su-dung-nang-luong-hop-li"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-su-dung-nang-luong-hop-li","mon":"KHTN","khoi":"9","chu_de":"l9-nang-luong","thu_tu":11,"loai":"ud","ten":"Sử dụng năng lượng hợp lí","ten_khac":["su dung nang luong hop li","tiet kiem nang luong","hieu qua nang luong","bao ve moi truong","nang luong ben vung"],"noi_dung":"Dùng năng lượng tiết kiệm, hiệu quả và ưu tiên nguồn tái tạo để bảo vệ tài nguyên và môi trường.","cong_thuc":null,"y":["Tiết kiệm điện, nước, xăng dầu trong sinh hoạt hằng ngày.","Đi bộ, xe đạp, phương tiện công cộng thay xe cá nhân khi có thể.","Chọn thiết bị hiệu suất cao; tăng dùng năng lượng tái tạo."],"bang":null,"bien":null,"vd":{"de":"Giữa việc dùng than đá và dùng điện mặt trời để đun nước nóng, cách nào phù hợp hơn với nguyên tắc sử dụng năng lượng hợp lí lâu dài?","buoc":["Sử dụng năng lượng hợp lí ưu tiên nguồn tái tạo để bảo vệ tài nguyên và môi trường.","Điện mặt trời là nguồn tái tạo, than đá là nguồn không tái tạo và gây ô nhiễm khi đốt."],"kq":"Dùng điện mặt trời phù hợp hơn."},"nham":null,"lq":["l9-tiet-kiem-dien","l9-nang-luong-tai-tao","l9-hieu-ung-nha-kinh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-phuong-phap-tim-hieu","mon":"KHTN","khoi":"7","chu_de":"l7-mo-dau","thu_tu":1,"loai":"kn","ten":"Phương pháp tìm hiểu tự nhiên","ten_khac":["phuong phap tim hieu tu nhien","cac buoc tim hieu tu nhien","phuong phap khoa hoc","quy trinh nghien cuu"],"noi_dung":"Cách tìm câu trả lời cho một câu hỏi về tự nhiên bằng bằng chứng, đi qua các bước nối tiếp nhau.","cong_thuc":null,"y":["Bước 1: <b>Quan sát, đặt câu hỏi</b> nghiên cứu.","Bước 2: <b>Hình thành giả thuyết</b> (đưa ra dự đoán).","Bước 3: <b>Lập kế hoạch</b> kiểm tra giả thuyết.","Bước 4: <b>Thực hiện kế hoạch</b>: làm thí nghiệm, quan sát, đo, ghi số liệu.","Bước 5: <b>Rút ra kết luận</b>, viết báo cáo và trình bày."],"bang":null,"bien":null,"vd":null,"nham":["Làm thí nghiệm trước rồi mới nghĩ ra câu hỏi","Kết luận theo mong muốn, không theo số liệu"],"lq":["l7-gia-thuyet","l7-cau-hoi-nghien-cuu","l7-bien-thi-nghiem"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-cau-hoi-nghien-cuu","mon":"KHTN","khoi":"7","chu_de":"l7-mo-dau","thu_tu":2,"loai":"kn","ten":"Câu hỏi nghiên cứu","ten_khac":["cau hoi nghien cuu","cau hoi kiem tra duoc","dat cau hoi khoa hoc"],"noi_dung":"Câu hỏi về tự nhiên có thể trả lời bằng quan sát, đo đạc hoặc thí nghiệm.","cong_thuc":null,"y":["Câu hỏi tốt gắn với một đại lượng đo được, ví dụ: \"Nước nóng có làm đường tan nhanh hơn không?\".","Câu hỏi về sở thích, cảm nhận (\"hoa nào đẹp nhất?\") không kiểm tra được bằng thí nghiệm.","Câu hỏi mơ hồ cần viết lại cho rõ: so sánh cái gì, đo đại lượng nào."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l7-phuong-phap-tim-hieu","l7-gia-thuyet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-gia-thuyet","mon":"KHTN","khoi":"7","chu_de":"l7-mo-dau","thu_tu":3,"loai":"kn","ten":"Giả thuyết (dự đoán)","ten_khac":["gia thuyet","du doan","hinh thanh gia thuyet","cau tra loi tam thoi"],"noi_dung":"Câu trả lời tạm thời cho câu hỏi nghiên cứu, cần được kiểm tra bằng thí nghiệm hoặc quan sát.","cong_thuc":null,"y":["Giả thuyết phải kiểm tra được và dựa trên quan sát ban đầu.","Kết quả phù hợp: giả thuyết được <b>ủng hộ</b>; không phù hợp: <b>điều chỉnh</b> giả thuyết.","Kết quả trái giả thuyết vẫn có giá trị, phải ghi lại trung thực."],"bang":null,"bien":null,"vd":null,"nham":["Sửa số liệu cho khớp với dự đoán","Cho rằng dự đoán luôn phải đúng"],"lq":["l7-phuong-phap-tim-hieu","l7-bien-thi-nghiem"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-bien-thi-nghiem","mon":"KHTN","khoi":"7","chu_de":"l7-mo-dau","thu_tu":4,"loai":"tn","ten":"Lập kế hoạch thí nghiệm công bằng","ten_khac":["yeu to thay doi","yeu to giu nguyen","thi nghiem cong bang","lap ke hoach kiem tra","bien thi nghiem"],"noi_dung":"Thí nghiệm so sánh chỉ thay đổi một yếu tố, giữ nguyên các yếu tố còn lại, rồi đo cùng một đại lượng.","cong_thuc":null,"y":["<b>Yếu tố thay đổi</b>: yếu tố cần tìm hiểu ảnh hưởng (ví dụ ánh sáng).","<b>Yếu tố giữ nguyên</b>: mọi điều kiện khác (loại cây, đất, lượng nước…).","<b>Số liệu cần đo</b>: đại lượng dùng để so sánh (ví dụ chiều cao cây).","Đổi nhiều yếu tố cùng lúc thì không biết yếu tố nào gây ra khác biệt.","Đo lặp lại nhiều lần, lấy trung bình để kết quả đáng tin hơn."],"bang":null,"bien":null,"vd":null,"nham":["Thay đổi cùng lúc nhiều yếu tố","Kết luận chung cho mọi trường hợp từ một lần đo"],"lq":["l7-phuong-phap-tim-hieu","l7-ki-nang-do-du-bao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-ki-nang-quan-sat-phan-loai","mon":"KHTN","khoi":"7","chu_de":"l7-mo-dau","thu_tu":5,"loai":"kn","ten":"Kĩ năng quan sát và phân loại","ten_khac":["ki nang quan sat","ki nang phan loai","quan sat","phan loai","tieu chi phan loai"],"noi_dung":"Quan sát là thu thập thông tin bằng giác quan hoặc dụng cụ; phân loại là xếp sự vật thành nhóm theo đặc điểm chung.","cong_thuc":null,"y":["Quan sát bằng giác quan (mắt, tai, da…) hoặc dụng cụ (kính lúp, kính hiển vi).","Quan sát chỉ ghi điều thấy, nghe, sờ được; không ghi điều đoán.","Phân loại: <b>chọn tiêu chí trước</b> (công dụng, vật liệu, nơi sống…) rồi mới chia nhóm.","Các vật cùng nhóm giống nhau ở tiêu chí đã chọn."],"bang":null,"bien":null,"vd":null,"nham":["Ghi điều suy đoán vào kết quả quan sát","Chia nhóm khi chưa chọn tiêu chí"],"lq":["l7-ki-nang-lien-ket","l7-ki-nang-do-du-bao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-ki-nang-lien-ket","mon":"KHTN","khoi":"7","chu_de":"l7-mo-dau","thu_tu":6,"loai":"kn","ten":"Kĩ năng liên kết","ten_khac":["ki nang lien ket","lien ket kien thuc","giai thich hien tuong"],"noi_dung":"Nối hiện tượng mới với kiến thức đã học để giải thích.","cong_thuc":null,"y":["Tìm điểm giống giữa hiện tượng mới và điều đã biết.","Ví dụ: giọt nước đọng ngoài cốc nước đá được giải thích bằng sự ngưng tụ.","Khác với phân loại (xếp nhóm) và đo (xác định độ lớn)."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l7-ki-nang-quan-sat-phan-loai","l7-ki-nang-do-du-bao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-ki-nang-do-du-bao","mon":"KHTN","khoi":"7","chu_de":"l7-mo-dau","thu_tu":7,"loai":"kn","ten":"Kĩ năng đo và dự báo","ten_khac":["ki nang do","ki nang du bao","du bao tu so lieu","quy luat so lieu","gia tri trung binh"],"noi_dung":"Đo là xác định độ lớn đại lượng bằng dụng cụ; dự báo là nói trước điều chưa xảy ra dựa vào quy luật của số liệu.","cong_thuc":null,"y":["Chọn dụng cụ đo phù hợp; ghi số đo <b>kèm đơn vị</b>.","Đo nhiều lần, lấy <b>giá trị trung bình</b>.","Dự báo dựa vào quy luật thay đổi của số liệu đã đo; dự báo vẫn có thể lệch.","Chỉ dự báo trong phạm vi số liệu hợp lí, không suy rộng quá xa."],"bang":null,"bien":null,"vd":null,"nham":["Dự báo từ một lần đo duy nhất","Ghi số đo không có đơn vị"],"lq":["l7-bien-thi-nghiem","l7-bao-cao-thi-nghiem"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-bao-cao-thi-nghiem","mon":"KHTN","khoi":"7","chu_de":"l7-mo-dau","thu_tu":8,"loai":"tn","ten":"Báo cáo thí nghiệm","ten_khac":["bao cao thi nghiem","viet bao cao","cau truc bao cao","trinh bay ket qua"],"noi_dung":"Văn bản trình bày ngắn gọn thí nghiệm đã làm để người khác hiểu và làm lại được.","cong_thuc":null,"y":["<b>Mục đích</b>: điều cần tìm hiểu.","<b>Chuẩn bị</b>: dụng cụ, vật liệu.","<b>Cách làm</b>: các bước thực hiện.","<b>Kết quả</b>: số liệu, hiện tượng (nên lập bảng, có đơn vị).","<b>Kết luận</b>: trả lời câu hỏi dựa trên số liệu."],"bang":null,"bien":null,"vd":null,"nham":["Viết kết luận vào phần kết quả","Bỏ số liệu không hợp dự đoán"],"lq":["l7-phuong-phap-tim-hieu","l7-ki-nang-do-du-bao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-dong-ho-hien-so","mon":"KHTN","khoi":"7","chu_de":"l7-mo-dau","thu_tu":9,"loai":"cq","ten":"Đồng hồ đo thời gian hiện số","ten_khac":["dong ho do thoi gian hien so","dong ho hien so","nut mode","nut reset","o cam a b"],"noi_dung":"Dụng cụ đo khoảng thời gian rất ngắn, hiện kết quả bằng chữ số (giây), dùng cùng cổng quang điện.","cong_thuc":null,"y":["<b>Màn hình</b> hiện số: hiển thị kết quả đo.","Nút <b>MODE</b>: chọn chế độ đo; nút <b>RESET</b>: đưa số về 0.","<b>Ổ cắm A, B</b>: nối dây của các cổng quang điện.","Chế độ <b>A↔B</b>: đo thời gian từ lúc vật chắn cổng A đến lúc chắn cổng B.","Chế độ chắn một cổng: đo thời gian vật che tia sáng của cổng đó."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l7-cong-quang-dien","l7-dung-dong-ho-hien-so"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-dung-dong-ho-hien-so","mon":"KHTN","khoi":"7","chu_de":"l7-mo-dau","thu_tu":10,"loai":"tn","ten":"Đo thời gian bằng đồng hồ hiện số","ten_khac":["cach dung dong ho hien so","do thoi gian chuyen dong","cac buoc do thoi gian"],"noi_dung":"Các bước đo thời gian vật chuyển động bằng đồng hồ hiện số và cổng quang điện.","cong_thuc":null,"y":["1. Nối cổng quang điện vào ổ A, B của đồng hồ.","2. Chọn chế độ đo bằng nút MODE, nhấn RESET đưa số về 0.","3. Cho vật chuyển động qua các cổng.","4. Đọc thời gian trên màn hình; đo lặp lại và lấy trung bình."],"bang":null,"bien":null,"vd":null,"nham":["Quên nhấn RESET nên lẫn số của lần đo trước","Chọn nhầm chế độ chắn một cổng khi cần đo giữa hai cổng"],"lq":["l7-dong-ho-hien-so","l7-sai-so-bam-tay"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-sai-so-bam-tay","mon":"KHTN","khoi":"7","chu_de":"l7-mo-dau","thu_tu":11,"loai":"ss","ten":"Đồng hồ bấm giây và đồng hồ hiện số","ten_khac":["dong ho bam giay","sai so bam tay","thoi gian phan ung","chon dung cu do thoi gian"],"noi_dung":"Bấm tay có độ trễ vài phần mười giây do phản ứng của người đo; đo thời gian rất ngắn nên dùng đồng hồ hiện số.","cong_thuc":null,"y":["Thời gian cần đo càng ngắn thì sai số bấm tay càng đáng kể.","Đo bấm tay nhiều lần và lấy trung bình giúp giảm ảnh hưởng của sai số."],"bang":[["","Đồng hồ bấm giây","Đồng hồ hiện số + cổng quang điện"],["Bắt đầu, dừng đếm","Người bấm tay","Vật chắn tia sáng"],["Sai số chính","Độ trễ phản ứng (vài phần mười giây)","Rất nhỏ"],["Phù hợp khi đo","Khoảng thời gian dài (chạy 100 m, 200 m…)","Khoảng thời gian rất ngắn (dưới 1 s)"]],"bien":null,"vd":null,"nham":null,"lq":["l7-dong-ho-hien-so","l6-dong-ho"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-nhan-hoa-chat","mon":"KHTN","khoi":"8","chu_de":"l8-mo-dau","thu_tu":1,"loai":"kn","ten":"Nhãn hóa chất và kí hiệu cảnh báo","ten_khac":["nhan hoa chat","ki hieu canh bao","ngon lua","dau lau xuong cheo","an mon","de no","nguy hiem moi truong"],"noi_dung":"Nhãn cho biết tên, công thức, lượng chất, hạn dùng và mức nguy hiểm của hóa chất; phải đọc nhãn trước khi dùng.","cong_thuc":null,"y":["Nhãn ghi tên, công thức, lượng chất (khối lượng hoặc nồng độ) và hạn sử dụng.","Lọ mất nhãn hoặc nhãn mờ: không dùng, báo giáo viên."],"bang":[["Kí hiệu","Cảnh báo","Cần làm"],["Ngọn lửa","Dễ cháy","Để xa lửa, nguồn nhiệt"],["Đầu lâu, xương chéo","Chất độc","Không nếm, không ngửi trực tiếp"],["Bàn tay, kim loại bị chất lỏng nhỏ vào","Ăn mòn","Đeo găng, kính bảo hộ"],["Quả bom đang nổ","Dễ nổ","Tránh va đập, không đun nóng"],["Cây và cá","Nguy hại môi trường","Thu gom, không đổ ra cống"]],"bien":null,"vd":null,"nham":null,"lq":["l8-lay-hoa-chat","l8-su-co-hoa-chat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-lay-hoa-chat","mon":"KHTN","khoi":"8","chu_de":"l8-mo-dau","thu_tu":2,"loai":"tn","ten":"Quy tắc lấy và sử dụng hóa chất","ten_khac":["lay hoa chat","quy tac su dung hoa chat","rot dung dich","hoa chat thua","ngui hoa chat"],"noi_dung":"Lấy đúng lượng cần dùng bằng dụng cụ phù hợp, không để hóa chất dính vào người và không làm bẩn lọ gốc.","cong_thuc":null,"y":["Chất rắn dạng bột: dùng <b>thìa</b> sạch, khô; mẩu kim loại: dùng <b>kẹp</b>.","Chất lỏng: rót với <b>nhãn quay vào lòng bàn tay</b>, hoặc dùng ống hút nhỏ giọt; đo chính xác dùng ống đong.","Mở nắp thì <b>đặt ngửa nắp</b> trên bàn; lấy xong đậy đúng nắp, đặt lọ về chỗ cũ.","<b>Không nếm</b>, không ngửi trực tiếp (chỉ phẩy nhẹ hơi về phía mũi khi được phép).","Hóa chất thừa <b>không đổ lại lọ</b>; cho vào bình thu gom theo hướng dẫn."],"bang":null,"bien":null,"vd":null,"nham":["Đổ hóa chất thừa trở lại lọ vì thấy còn sạch","Dùng chung ống hút cho nhiều lọ"],"lq":["l8-nhan-hoa-chat","l8-su-co-hoa-chat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-su-co-hoa-chat","mon":"KHTN","khoi":"8","chu_de":"l8-mo-dau","thu_tu":3,"loai":"ud","ten":"Xử lí sự cố và bảo quản hóa chất","ten_khac":["hoa chat dinh vao da","hoa chat ban vao mat","bao quan hoa chat","tu hoa chat"],"noi_dung":"Khi hóa chất dính vào người thì rửa ngay bằng nhiều nước sạch rồi báo giáo viên; hóa chất được cất nơi riêng, có khóa.","cong_thuc":null,"y":["Dính da: rửa dưới vòi nước sạch nhiều lần; áo thấm hóa chất thì cởi phần áo đó rồi rửa da.","Bắn vào mắt: rửa bằng dòng nước sạch nhẹ, <b>không dụi</b>.","Không tự dùng hóa chất khác để \"trung hòa\" chỗ bị dính.","Bảo quản: tủ riêng, khô mát, có khóa; chất dễ cháy xa nguồn nhiệt; chất nhạy sáng trong lọ sẫm màu.","Không đựng hóa chất trong chai nước uống."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l8-lay-hoa-chat","l6-an-toan-phong-thuc-hanh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-dung-cu-thi-nghiem","mon":"KHTN","khoi":"8","chu_de":"l8-mo-dau","thu_tu":4,"loai":"cq","ten":"Dụng cụ thí nghiệm thường dùng","ten_khac":["dung cu thi nghiem","ong nghiem","coc thuy tinh","binh tam giac","ong dong","pheu","bat su","kieng ba chan","luoi thep","kep ong nghiem"],"noi_dung":"Mỗi dụng cụ có hình dạng và công dụng riêng; chọn dụng cụ theo việc cần làm.","cong_thuc":null,"y":["Chọn dụng cụ theo việc cần làm: chứa, đo, đun, lọc hay giữ.","Ống đong chỉ dùng để đo thể tích, không dùng để đun hay pha chế.","Đun cốc hoặc bát sứ phải đặt trên kiềng ba chân có lưới thép."],"bang":[["Dụng cụ","Công dụng"],["Ống nghiệm","Chứa, làm phản ứng với lượng nhỏ hóa chất"],["Cốc thủy tinh","Chứa, pha chế lượng chất lỏng vừa và lớn"],["Bình tam giác","Chứa chất lỏng, lắc trộn ít bị bắn ra"],["Ống đong","Đo thể tích chất lỏng (không dùng để đun)"],["Phễu + giấy lọc","Rót vào bình miệng hẹp; lọc chất rắn không tan"],["Bát sứ","Cô cạn dung dịch"],["Kẹp, giá đỡ ống nghiệm","Giữ ống khi đun; đặt ống thẳng đứng"],["Kiềng ba chân + lưới thép","Đỡ cốc, bát khi đun; lưới giúp nóng đều"]],"bien":null,"vd":null,"nham":null,"lq":["l8-den-con","l8-dun-hoa-chat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-den-con","mon":"KHTN","khoi":"8","chu_de":"l8-mo-dau","thu_tu":5,"loai":"tn","ten":"Sử dụng đèn cồn","ten_khac":["den con","thap den con","tat den con","them con"],"noi_dung":"Đèn cồn gồm thân đèn chứa cồn, bấc và nắp; dùng để đun nóng trong phòng thí nghiệm.","cong_thuc":null,"y":["Kiểm tra đèn không nứt, bấc và cồn đủ dùng trước khi thắp.","Thắp bằng <b>que đóm</b>; không nghiêng đèn đang cháy để châm sang đèn khác.","Tắt bằng cách <b>đậy nắp</b>; <b>không thổi</b> (lửa có thể bén vào hơi cồn trong đèn).","Chỉ thêm cồn khi đèn đã tắt và nguội; không để đèn cháy khi không có người trông.","Cồn đổ và cháy trên bàn: phủ khăn ướt hoặc cát, báo giáo viên."],"bang":null,"bien":null,"vd":null,"nham":["Thổi để tắt đèn cồn","Dội nước lên cồn đang cháy"],"lq":["l8-dun-hoa-chat","l8-dung-cu-thi-nghiem"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-dun-hoa-chat","mon":"KHTN","khoi":"8","chu_de":"l8-mo-dau","thu_tu":6,"loai":"tn","ten":"Đun hóa chất an toàn","ten_khac":["dun ong nghiem","dun hoa chat","mot phan ba ong nghiem","kep ong nghiem khi dun"],"noi_dung":"Đun lượng nhỏ trong ống nghiệm giữ bằng kẹp; đun cốc, bát trên kiềng có lưới thép.","cong_thuc":null,"y":["Chất lỏng không quá <b>1/3 ống nghiệm</b>; kẹp cách miệng ống khoảng 1/3 chiều dài ống.","Hơ đều cả ống rồi đun ở chỗ có chất lỏng, lắc nhẹ; miệng ống <b>hướng ra xa người</b>.","Đeo kính bảo hộ; không cúi sát miệng ống đang đun.","Không cho dụng cụ đang nóng vào nước lạnh (dễ nứt vỡ); để nguội trên giá."],"bang":null,"bien":null,"vd":null,"nham":["Hướng miệng ống nghiệm về phía bạn","Đổ đầy chất lỏng rồi mới đun"],"lq":["l8-den-con","l8-dung-cu-thi-nghiem"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-bien-ap-nguon","mon":"KHTN","khoi":"8","chu_de":"l8-mo-dau","thu_tu":7,"loai":"cq","ten":"Nguồn điện trong phòng thí nghiệm","ten_khac":["bien ap nguon","nguon dien","pin","dien ap thap","cong tac","day noi"],"noi_dung":"Pin hoặc biến áp nguồn cung cấp điện ở hiệu điện thế thấp, an toàn cho học sinh làm thí nghiệm.","cong_thuc":null,"y":["<b>Biến áp nguồn</b>: đổi điện lưới 220 V thành hiệu điện thế nhỏ; có núm chỉnh giá trị.","Pin có cực dương (+) và cực âm (−); pin tiểu thường khoảng 1,5 V.","Công tắc đóng, ngắt mạch; dây nối có lớp cách điện nguyên vẹn.","Học sinh không lấy điện 220 V trực tiếp từ ổ cắm để mắc mạch."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l8-ampe-von-ke","l8-an-toan-dien-thi-nghiem"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-ampe-von-ke","mon":"KHTN","khoi":"8","chu_de":"l8-mo-dau","thu_tu":8,"loai":"tn","ten":"Ampe kế, vôn kế, joulemeter","ten_khac":["ampe ke","von ke","joulemeter","mac ampe ke","mac von ke","thang do"],"noi_dung":"Ampe kế đo cường độ dòng điện (A), vôn kế đo hiệu điện thế (V), joulemeter đo năng lượng điện (J).","cong_thuc":null,"y":["Ampe kế mắc <b>nối tiếp</b>; vôn kế mắc <b>song song</b> với đoạn mạch cần đo.","Chốt (+) nối về phía cực dương của nguồn; kim quay ngược là mắc ngược cực.","Chưa biết giá trị: chọn <b>thang lớn nhất</b> trước, rồi giảm dần.","Lắp, sửa mạch khi đã ngắt điện; đọc số khi mắt nhìn vuông góc mặt số.","Không mắc ampe kế thẳng vào hai cực nguồn (dòng điện rất lớn làm hỏng dụng cụ)."],"bang":null,"bien":null,"vd":null,"nham":["Mắc ampe kế song song với đèn","Mắc vôn kế nối tiếp nên đèn gần như không sáng"],"lq":["l8-bien-ap-nguon","l8-an-toan-dien-thi-nghiem"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l8-an-toan-dien-thi-nghiem","mon":"KHTN","khoi":"8","chu_de":"l8-mo-dau","thu_tu":9,"loai":"ud","ten":"An toàn điện khi thí nghiệm","ten_khac":["an toan dien khi thi nghiem","dien giat","chap mach","qua tai","rut phich cam"],"noi_dung":"Dùng nguồn điện thấp, ngắt điện trước khi thao tác và xử lí sự cố đúng cách để tránh điện giật, cháy.","cong_thuc":null,"y":["Ngắt công tắc, tắt nguồn trước khi lắp, sửa hay tháo mạch.","Tay khô khi cắm, rút phích; rút phích bằng cách cầm thân nhựa.","Dây nóng, có mùi khét, thiết bị bốc khói: <b>ngắt nguồn</b> rồi báo giáo viên.","Người bị điện giật: ngắt nguồn trước rồi mới đưa người ra.","Không dùng nước dập lửa khi thiết bị còn điện."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l8-bien-ap-nguon","l8-ampe-von-ke"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-dung-cu-quang-hoc","mon":"KHTN","khoi":"9","chu_de":"l9-mo-dau","thu_tu":1,"loai":"cq","ten":"Dụng cụ thí nghiệm quang học","ten_khac":["dung cu quang hoc","lang kinh","thau kinh hoi tu","thau kinh phan ki","den laser","khe hep","man anh","bang ghe quang hoc"],"noi_dung":"Các dụng cụ dùng để tạo, dẫn và quan sát chùm sáng trong thí nghiệm quang học.","cong_thuc":null,"y":["Thấu kính rìa mỏng là hội tụ, rìa dày là phân kì.","<b>Không chiếu tia laser vào mắt</b> người, kể cả tia phản xạ."],"bang":[["Dụng cụ","Công dụng"],["Lăng kính","Làm lệch và tách ánh sáng trắng thành dải màu"],["Thấu kính hội tụ (rìa mỏng)","Làm chùm tia song song hội tụ; tạo ảnh thật hứng được trên màn"],["Thấu kính phân kì (rìa dày)","Làm chùm tia song song loe rộng ra"],["Đèn laser, khe hẹp","Tạo tia sáng mảnh để vẽ đường truyền"],["Màn ảnh, giá quang học có thước","Hứng ảnh; đặt dụng cụ thẳng hàng và đo khoảng cách"]],"bien":null,"vd":null,"nham":null,"lq":["l9-dung-cu-do","l9-chon-dung-cu-do"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-dung-cu-do","mon":"KHTN","khoi":"9","chu_de":"l9-mo-dau","thu_tu":2,"loai":"cq","ten":"Dụng cụ đo điện và đo cơ học","ten_khac":["dung cu do","ampe ke","von ke","joulemeter","can dien tu","ong dong","dong ho hien so"],"noi_dung":"Mỗi đại lượng có dụng cụ đo và đơn vị riêng.","cong_thuc":null,"y":["Ampe kế mắc nối tiếp, vôn kế mắc song song với đoạn mạch cần đo.","Cân điện tử: đặt cốc lên cân, đưa số về 0 rồi mới cho chất vào."],"bang":[["Đại lượng","Dụng cụ","Đơn vị"],["Cường độ dòng điện","Ampe kế (mắc nối tiếp)","A"],["Hiệu điện thế","Vôn kế (mắc song song)","V"],["Năng lượng điện","Joulemeter","J"],["Khối lượng","Cân điện tử (đưa số về 0 trước khi cân)","g, kg"],["Thể tích chất lỏng","Ống đong (mắt ngang mặt chất lỏng)","mL"],["Thời gian ngắn","Đồng hồ hiện số + cổng quang điện","s"]],"bien":null,"vd":null,"nham":null,"lq":["l9-chon-dung-cu-do","l8-ampe-von-ke"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-chon-dung-cu-do","mon":"KHTN","khoi":"9","chu_de":"l9-mo-dau","thu_tu":3,"loai":"tn","ten":"Chọn dụng cụ đo phù hợp","ten_khac":["chon dung cu do","gioi han do","do chia nho nhat","ghd","dcnn","chon thang do"],"noi_dung":"Chọn dụng cụ có giới hạn đo (GHĐ) không nhỏ hơn giá trị cần đo và độ chia nhỏ nhất (ĐCNN) đủ nhỏ.","cong_thuc":null,"y":["GHĐ phải <b>lớn hơn hoặc bằng</b> giá trị cần đo; GHĐ càng sát giá trị cần đo thì đọc càng chính xác.","ĐCNN = giá trị của khoảng giữa hai vạch chia liền nhau; ĐCNN càng nhỏ, kết quả càng chi tiết.","Chưa biết giá trị: dùng thang lớn trước, rồi chuyển thang nhỏ hơn phù hợp.","Đo nhiều lần, lấy giá trị trung bình."],"bang":null,"bien":null,"vd":null,"nham":["Chọn dụng cụ có GHĐ nhỏ hơn giá trị cần đo","Nghĩ rằng GHĐ càng lớn càng chính xác"],"lq":["l9-dung-cu-do","l6-gioi-han-do"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-hoa-chat-thuong-dung","mon":"KHTN","khoi":"9","chu_de":"l9-mo-dau","thu_tu":4,"loai":"ch","ten":"Một số hóa chất thường dùng ở lớp 9","ten_khac":["hoa chat lop 9","sodium","natri","copper sulfate","phenolphthalein","quy tim","ethanol"],"noi_dung":"Nhận biết một số hóa chất quen thuộc qua tên, công thức, trạng thái và đặc điểm.","cong_thuc":null,"y":["Luôn đọc nhãn và kí hiệu cảnh báo trước khi dùng.","Quỳ tím và phenolphthalein dùng để nhận biết môi trường acid, base."],"bang":[["Hóa chất","Đặc điểm cần nhớ"],["Sodium (Na)","Kim loại mềm, phản ứng mạnh với nước; ngâm trong dầu hỏa"],["Dung dịch CuSO₄","Màu xanh lam"],["NaOH, dung dịch base","Ăn mòn; làm phenolphthalein hóa hồng"],["HCl, dung dịch acid","Ăn mòn; làm quỳ tím hóa đỏ"],["Ethanol (cồn)","Dễ cháy, dễ bay hơi; nhiên liệu của đèn cồn"]],"bien":null,"vd":null,"nham":null,"lq":["l9-bao-quan-hoa-chat","l8-nhan-hoa-chat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-bao-quan-hoa-chat","mon":"KHTN","khoi":"9","chu_de":"l9-mo-dau","thu_tu":5,"loai":"tn","ten":"Bảo quản và sử dụng hóa chất an toàn","ten_khac":["bao quan hoa chat","pha loang acid","rot acid vao nuoc","silver nitrate lo sam mau","ngam dau hoa"],"noi_dung":"Mỗi hóa chất được bảo quản theo tính chất riêng; dùng đúng lượng và đúng cách để tránh tai nạn.","cong_thuc":null,"y":["Sodium ngâm trong dầu hỏa (cách li nước và không khí).","Silver nitrate đựng lọ sẫm màu, để nơi tối mát; NaOH rắn đậy kín nắp (hút ẩm).","Chất dễ cháy để nơi thoáng mát, xa nguồn lửa; acid và base để riêng ngăn.","Pha loãng acid đặc: <b>rót từ từ acid vào nước</b>, không làm ngược lại.","Chất độc để tủ có khóa; hóa chất thừa cho vào bình thu gom."],"bang":null,"bien":null,"vd":null,"nham":["Rót nước vào acid đặc","Để chung acid và base trên cùng ngăn"],"lq":["l9-hoa-chat-thuong-dung","l9-so-cuu-thi-nghiem"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-so-cuu-thi-nghiem","mon":"KHTN","khoi":"9","chu_de":"l9-mo-dau","thu_tu":6,"loai":"ud","ten":"Sơ cứu khi xảy ra sự cố thí nghiệm","ten_khac":["so cuu","bong nhiet","hoa chat ban vao mat","chay nho","thuy tinh vo"],"noi_dung":"Xử lí ban đầu đúng cách rồi báo ngay cho giáo viên.","cong_thuc":null,"y":["Sau khi xử lí ban đầu, luôn báo ngay cho giáo viên.","Không tự dùng hóa chất khác để trung hòa chỗ bị dính."],"bang":[["Sự cố","Xử lí ban đầu"],["Bỏng do vật nóng","Xả vết bỏng dưới nước mát sạch; không bôi kem đánh răng, không chọc nốt phồng"],["Hóa chất dính da","Rửa nhiều nước sạch; cởi phần áo bị dính"],["Hóa chất bắn vào mắt","Rửa bằng dòng nước nhẹ, không dụi"],["Cháy nhỏ trên bàn","Phủ khăn ướt hoặc cát; tắt đèn cồn bằng nắp"],["Thủy tinh vỡ, vết cắt","Gom bằng dụng cụ; rửa sạch, băng vết thương"],["Thiết bị điện bốc khói","Ngắt nguồn điện, không dội nước"]],"bien":null,"vd":null,"nham":null,"lq":["l9-bao-quan-hoa-chat","l8-an-toan-dien-thi-nghiem"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-bao-cao-khoa-hoc","mon":"KHTN","khoi":"9","chu_de":"l9-mo-dau","thu_tu":7,"loai":"kn","ten":"Báo cáo khoa học","ten_khac":["bao cao khoa hoc","cau truc bao cao","tai lieu tham khao","thao luan"],"noi_dung":"Văn bản trình bày một nghiên cứu theo trình tự để người đọc hiểu và kiểm tra được.","cong_thuc":null,"y":["Tên đề tài (ngắn gọn, nêu rõ vấn đề) → <b>Mục đích</b> → <b>Cách làm</b> → <b>Kết quả</b> → <b>Thảo luận</b> → <b>Kết luận</b> → Tài liệu tham khảo.","Kết quả: số liệu, hiện tượng; trình bày bằng bảng hoặc biểu đồ, có đơn vị.","Thảo luận: giải thích, đánh giá kết quả; Kết luận: trả lời câu hỏi dựa trên kết quả.","Ghi rõ nguồn tài liệu đã dùng."],"bang":null,"bien":null,"vd":null,"nham":["Viết cảm nghĩ vào phần kết quả","Kết luận không dựa trên số liệu"],"lq":["l9-thuyet-trinh","l7-bao-cao-thi-nghiem"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-thuyet-trinh","mon":"KHTN","khoi":"9","chu_de":"l9-mo-dau","thu_tu":8,"loai":"tn","ten":"Thuyết trình một vấn đề khoa học","ten_khac":["thuyet trinh","trang trinh chieu","slide","chuan bi thuyet trinh","bieu do cot"],"noi_dung":"Trình bày ngắn gọn, có bằng chứng, đúng thời gian về một vấn đề khoa học.","cong_thuc":null,"y":["Các bước: chọn vấn đề → tìm tư liệu tin cậy → lập dàn ý → làm trang trình chiếu → luyện nói, bấm giờ.","Mỗi trang ít chữ, ý chính rõ, chữ đủ lớn; dùng bảng, biểu đồ để so sánh số liệu.","Số liệu ghi rõ đơn vị và nguồn; hình ảnh có chú thích.","Nói rõ ràng, tốc độ vừa phải, nhìn người nghe."],"bang":null,"bien":null,"vd":null,"nham":["Đọc nguyên văn chữ trên trang trình chiếu","Dùng số liệu không rõ nguồn"],"lq":["l9-bao-cao-khoa-hoc","l9-danh-gia-thuyet-trinh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l9-danh-gia-thuyet-trinh","mon":"KHTN","khoi":"9","chu_de":"l9-mo-dau","thu_tu":9,"loai":"ud","ten":"Đánh giá và phản biện bài thuyết trình","ten_khac":["danh gia thuyet trinh","tieu chi danh gia","phan bien","tra loi cau hoi"],"noi_dung":"Đánh giá bài thuyết trình theo tiêu chí; phản biện là đặt câu hỏi để kiểm tra lập luận và bằng chứng.","cong_thuc":null,"y":["Tiêu chí thường dùng: <b>nội dung đúng</b>, <b>có bằng chứng</b>, <b>trình bày rõ</b>, <b>trả lời câu hỏi</b> thuyết phục.","Nhận xét tốt: nêu ưu điểm và chỉ rõ điểm cần sửa.","Trả lời phản biện: nghe kĩ, dựa vào số liệu; chưa biết thì nói thật và hẹn tìm hiểu thêm.","Chỉ kết luận trong phạm vi số liệu đã có."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["l9-thuyet-trinh","l9-bao-cao-khoa-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-chat","mon":"KHTN","khoi":"6","chu_de":"h6-the-chat","thu_tu":1,"loai":"kn","ten":"Chất","ten_khac":["chat","chat la gi","substance","chat cau tao vat the","chat quanh ta"],"noi_dung":"Chất là thứ tạo nên vật thể; ở đâu có vật thể thì ở đó có chất.","cong_thuc":null,"y":["Mỗi vật thể được tạo nên từ một hay nhiều chất. Ví dụ: cốc thủy tinh làm từ thủy tinh.","Mỗi chất có những <b>tính chất</b> nhất định: tính chất vật lí và tính chất hóa học.","Chất có thể tồn tại ở <b>thể rắn, lỏng hoặc khí</b>."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm chất với vật thể: \"cái cốc\" là vật thể, \"thủy tinh\" là chất."],"lq":["h6-vat-the","h6-tinh-chat-vat-li","h6-tinh-chat-hoa-hoc","h6-the-ran"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-vat-the","mon":"KHTN","khoi":"6","chu_de":"h6-the-chat","thu_tu":2,"loai":"kn","ten":"Vật thể","ten_khac":["vat the","do vat","vat","object","vat the la gi"],"noi_dung":"Vật thể là mọi vật có hình dạng, kích thước, chiếm chỗ trong không gian, do một hay nhiều chất tạo nên.","cong_thuc":null,"y":["Theo nguồn gốc: <b>vật thể tự nhiên</b> và <b>vật thể nhân tạo</b>.","Theo sự sống: <b>vật sống</b> và <b>vật không sống</b>.","Ví dụ: cây cối, con người, cái bàn, ngôi nhà đều là vật thể."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h6-chat","h6-vat-the-tu-nhien","h6-vat-the-nhan-tao","h6-vat-song"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-vat-the-tu-nhien","mon":"KHTN","khoi":"6","chu_de":"h6-the-chat","thu_tu":3,"loai":"kn","ten":"Vật thể tự nhiên","ten_khac":["vat the tu nhien","vat tu nhien","co san trong tu nhien","natural object"],"noi_dung":"Vật thể có sẵn trong tự nhiên, không do con người làm ra.","cong_thuc":null,"y":["Ví dụ: núi, sông, cây cối, con vật, mặt trời, hòn đá.","Có thể là vật sống (cây, con người) hoặc vật không sống (núi đá, nước biển)."],"bang":null,"bien":null,"vd":null,"nham":["Cho rằng cây trồng trong vườn là vật thể nhân tạo: cây vẫn là vật thể tự nhiên."],"lq":["h6-vat-the","h6-vat-the-nhan-tao","h6-vat-song"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-vat-the-nhan-tao","mon":"KHTN","khoi":"6","chu_de":"h6-the-chat","thu_tu":4,"loai":"kn","ten":"Vật thể nhân tạo","ten_khac":["vat the nhan tao","vat nhan tao","do con nguoi tao ra","artificial object"],"noi_dung":"Vật thể do con người tạo ra để phục vụ cuộc sống.","cong_thuc":null,"y":["Ví dụ: bàn ghế, xe đạp, quần áo, ngôi nhà, bút chì.","Vật thể nhân tạo đều là <b>vật không sống</b>.","Được làm từ vật liệu như gỗ, kim loại, nhựa, thủy tinh…"],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h6-vat-the","h6-vat-the-tu-nhien","h6-vat-lieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-vat-song","mon":"KHTN","khoi":"6","chu_de":"h6-the-chat","thu_tu":5,"loai":"kn","ten":"Vật sống","ten_khac":["vat song","vat huu sinh","huu sinh","sinh vat","living thing"],"noi_dung":"Vật thể có các đặc trưng sống: trao đổi chất, sinh trưởng, phát triển, sinh sản, cảm ứng.","cong_thuc":null,"y":["Ví dụ: con người, con mèo, cây lúa, vi khuẩn.","Còn gọi là <b>vật hữu sinh</b>.","Vật sống đều là vật thể tự nhiên."],"bang":null,"bien":null,"vd":null,"nham":["Coi xác cây khô, gỗ làm bàn là vật sống: chúng không còn đặc trưng sống."],"lq":["h6-vat-khong-song","h6-vat-the","h6-vat-the-tu-nhien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-vat-khong-song","mon":"KHTN","khoi":"6","chu_de":"h6-the-chat","thu_tu":6,"loai":"kn","ten":"Vật không sống","ten_khac":["vat khong song","vat vo sinh","vo sinh","non living"],"noi_dung":"Vật thể không có các đặc trưng sống như trao đổi chất, sinh trưởng, sinh sản.","cong_thuc":null,"y":["Ví dụ: hòn đá, nước, cái bàn, xe đạp.","Còn gọi là <b>vật vô sinh</b>.","Có thể là vật thể tự nhiên (hòn đá) hoặc nhân tạo (cái ghế)."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h6-vat-song","h6-vat-the","h6-vat-the-nhan-tao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-tinh-chat-vat-li","mon":"KHTN","khoi":"6","chu_de":"h6-the-chat","thu_tu":7,"loai":"kn","ten":"Tính chất vật lí","ten_khac":["tinh chat vat li","tinh chat vat ly","tcvl","tinh chat vl","physical property"],"noi_dung":"Những tính chất của chất có thể quan sát, đo được mà chất không biến đổi thành chất khác.","cong_thuc":null,"y":["Gồm: <b>thể</b> (rắn, lỏng, khí), màu sắc, mùi, vị, hình dạng, kích thước, khối lượng riêng.","Tính tan trong nước, tính dẫn điện, dẫn nhiệt.","<b>Nhiệt độ nóng chảy</b>, <b>nhiệt độ sôi</b>."],"bang":null,"bien":null,"vd":{"de":"Vì sao nói cồn không màu, dễ bay hơi là tính chất vật lí, còn cồn dễ cháy là tính chất hóa học?","buoc":["Không màu, dễ bay hơi: quan sát được, cồn vẫn là cồn, không đổi thành chất khác","Cháy được: khi cháy cồn biến đổi thành chất khác (khí carbon dioxide, hơi nước)"],"kq":"Không màu, bay hơi là tính chất vật lí; cháy được là tính chất hóa học."},"nham":["Coi \"đường tan trong nước\" là tính chất hóa học: đường không biến thành chất khác nên là tính chất vật lí."],"lq":["h6-tinh-chat-hoa-hoc","h6-chat","h6-su-nong-chay","h6-su-soi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-tinh-chat-hoa-hoc","mon":"KHTN","khoi":"6","chu_de":"h6-the-chat","thu_tu":8,"loai":"kn","ten":"Tính chất hóa học","ten_khac":["tinh chat hoa hoc","tchh","tinh chat hh","bien doi thanh chat khac","chemical property"],"noi_dung":"Tính chất thể hiện khi chất bị biến đổi thành chất khác.","cong_thuc":null,"y":["Ví dụ: khả năng <b>bị cháy</b>, bị phân hủy, tác dụng với chất khác.","Dấu hiệu thường gặp khi có chất mới: đổi màu, sinh khí, tạo chất không tan, tỏa nhiệt hoặc phát sáng.","Ví dụ: sắt để lâu ngoài không khí bị gỉ; đường đun quá lửa bị cháy thành than."],"bang":null,"bien":null,"vd":{"de":"Miếng sắt để ngoài trời ẩm lâu ngày xuất hiện lớp gỉ màu nâu đỏ. Đây thể hiện tính chất gì của sắt?","buoc":["Lớp gỉ là chất mới, khác hẳn sắt ban đầu","Sắt đã biến đổi thành chất khác khi tác dụng với oxygen và hơi nước"],"kq":"Đó là tính chất hóa học: sắt bị oxygen trong không khí ăn mòn tạo gỉ."},"nham":["Nhầm nước đá tan thành nước lỏng là biến đổi hóa học: đây chỉ là chuyển thể."],"lq":["h6-tinh-chat-vat-li","h6-chat","h6-su-chay"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-the-ran","mon":"KHTN","khoi":"6","chu_de":"h6-the-chat","thu_tu":9,"loai":"kn","ten":"Thể rắn","ten_khac":["the ran","chat ran","ran","solid"],"noi_dung":"Thể của chất có hình dạng và thể tích xác định, rất khó bị nén.","cong_thuc":null,"y":["Các hạt xếp <b>rất sít nhau</b>, chỉ dao động tại chỗ.","Có hình dạng cố định, không chảy được.","Ví dụ: nước đá, sắt, muối ăn, gỗ."],"bang":[["Thể","Hình dạng","Thể tích","Nén được"],["Rắn","xác định","xác định","rất khó"],["Lỏng","theo vật chứa","xác định","khó"],["Khí","theo vật chứa","theo vật chứa","dễ"]],"bien":null,"vd":null,"nham":null,"lq":["h6-the-long","h6-the-khi","h6-su-chuyen-the"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-the-long","mon":"KHTN","khoi":"6","chu_de":"h6-the-chat","thu_tu":10,"loai":"kn","ten":"Thể lỏng","ten_khac":["the long","chat long","long","liquid"],"noi_dung":"Thể của chất có thể tích xác định nhưng không có hình dạng xác định, có hình dạng của vật chứa.","cong_thuc":null,"y":["Các hạt ở <b>gần nhau</b>, dao động và trượt lên nhau.","Chảy được, khó bị nén.","Ví dụ: nước, dầu ăn, xăng, sữa."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h6-the-ran","h6-the-khi","h6-su-chuyen-the"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-the-khi","mon":"KHTN","khoi":"6","chu_de":"h6-the-chat","thu_tu":11,"loai":"kn","ten":"Thể khí","ten_khac":["the khi","chat khi","the hoi","khi","gas"],"noi_dung":"Thể của chất không có hình dạng và thể tích xác định, chiếm đầy vật chứa và dễ bị nén.","cong_thuc":null,"y":["Các hạt ở <b>xa nhau</b>, chuyển động hỗn độn, tự do.","Dễ lan tỏa ra mọi phía, dễ bị nén.","Ví dụ: không khí, oxygen, hơi nước."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ chất khí không có khối lượng: khí vẫn có khối lượng."],"lq":["h6-the-ran","h6-the-long","h6-khong-khi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-su-chuyen-the","mon":"KHTN","khoi":"6","chu_de":"h6-the-chat","thu_tu":12,"loai":"ht","ten":"Sự chuyển thể của chất","ten_khac":["su chuyen the","chuyen the","doi the","chuyen the cua chat","phase change"],"noi_dung":"Quá trình chất chuyển từ thể này sang thể khác (rắn, lỏng, khí) mà không thành chất mới.","cong_thuc":null,"y":["Rắn → lỏng: <b>nóng chảy</b>; lỏng → rắn: <b>đông đặc</b>.","Lỏng → khí: <b>bay hơi</b> (và <b>sôi</b>); khí → lỏng: <b>ngưng tụ</b>.","Chuyển thể là biến đổi vật lí, chất vẫn giữ nguyên."],"bang":[["Quá trình","Từ","Sang"],["Nóng chảy","rắn","lỏng"],["Đông đặc","lỏng","rắn"],["Bay hơi","lỏng","khí"],["Ngưng tụ","khí","lỏng"]],"bien":null,"vd":null,"nham":null,"lq":["h6-su-nong-chay","h6-su-dong-dac","h6-su-bay-hoi","h6-su-ngung-tu","h6-su-soi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-su-nong-chay","mon":"KHTN","khoi":"6","chu_de":"h6-the-chat","thu_tu":13,"loai":"ht","ten":"Sự nóng chảy","ten_khac":["su nong chay","nong chay","tan chay","nhiet do nong chay","melting"],"noi_dung":"Quá trình chất chuyển từ thể rắn sang thể lỏng.","cong_thuc":null,"y":["Mỗi chất tinh khiết nóng chảy ở một nhiệt độ xác định gọi là <b>nhiệt độ nóng chảy</b>.","Nước đá nóng chảy ở <b>0 °C</b>.","Ví dụ: nước đá tan, nến chảy khi đốt, kim loại được nấu chảy để đúc."],"bang":null,"bien":null,"vd":{"de":"Một khối nước đá để ngoài nắng dần tan thành nước. Hiện tượng này gọi là gì, có tạo chất mới không?","buoc":["Nước đá (thể rắn) chuyển sang nước (thể lỏng) khi nhận nhiệt","Vẫn là chất nước, chỉ đổi thể, không sinh ra chất mới"],"kq":"Đó là sự nóng chảy, một biến đổi vật lí."},"nham":["Nhầm \"nóng chảy\" với \"hòa tan\": đường tan trong nước là sự hòa tan, không phải nóng chảy."],"lq":["h6-su-dong-dac","h6-su-chuyen-the","h6-the-ran","h6-su-hoa-tan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-su-dong-dac","mon":"KHTN","khoi":"6","chu_de":"h6-the-chat","thu_tu":14,"loai":"ht","ten":"Sự đông đặc","ten_khac":["su dong dac","dong dac","dong bang","nhiet do dong dac","freezing"],"noi_dung":"Quá trình chất chuyển từ thể lỏng sang thể rắn.","cong_thuc":null,"y":["Nước đông đặc ở <b>0 °C</b>.","Với cùng một chất, nhiệt độ đông đặc <b>bằng</b> nhiệt độ nóng chảy.","Ví dụ: làm đá trong tủ lạnh, sáp nến chảy rồi đông lại."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h6-su-nong-chay","h6-su-chuyen-the","h6-the-long"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-su-bay-hoi","mon":"KHTN","khoi":"6","chu_de":"h6-the-chat","thu_tu":15,"loai":"ht","ten":"Sự bay hơi","ten_khac":["su bay hoi","bay hoi","hoa hoi","boc hoi","evaporation"],"noi_dung":"Quá trình chất chuyển từ thể lỏng sang thể hơi, xảy ra trên bề mặt chất lỏng.","cong_thuc":null,"y":["Xảy ra <b>ở mọi nhiệt độ</b>.","Bay hơi nhanh hơn khi nhiệt độ cao, có gió, diện tích mặt thoáng lớn.","Ví dụ: quần áo phơi khô, nước biển bay hơi trong ruộng muối."],"bang":null,"bien":null,"vd":{"de":"Quần áo ướt phơi ngoài nắng, có gió khô nhanh hơn phơi trong nhà không gió. Vì sao?","buoc":["Nắng làm nhiệt độ tăng, gió giúp hơi nước thoát nhanh khỏi bề mặt vải","Cả hai yếu tố đều làm sự bay hơi xảy ra nhanh hơn"],"kq":"Nhiệt độ cao và có gió làm nước bay hơi nhanh, quần áo mau khô."},"nham":["Nghĩ nước chỉ bay hơi khi đun nóng: nước bay hơi cả ở nhiệt độ thường."],"lq":["h6-su-soi","h6-su-ngung-tu","h6-su-chuyen-the","h6-co-can"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-su-ngung-tu","mon":"KHTN","khoi":"6","chu_de":"h6-the-chat","thu_tu":16,"loai":"ht","ten":"Sự ngưng tụ","ten_khac":["su ngung tu","ngung tu","hoi thanh nuoc","suong","condensation"],"noi_dung":"Quá trình chất chuyển từ thể hơi (khí) sang thể lỏng.","cong_thuc":null,"y":["Là quá trình <b>ngược</b> với sự bay hơi.","Xảy ra khi hơi gặp lạnh.","Ví dụ: sương đọng trên lá, hơi nước đọng ở nắp nồi, mặt ngoài cốc nước đá."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h6-su-bay-hoi","h6-su-chuyen-the","h6-chung-cat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-su-soi","mon":"KHTN","khoi":"6","chu_de":"h6-the-chat","thu_tu":17,"loai":"ht","ten":"Sự sôi","ten_khac":["su soi","soi","nhiet do soi","dun soi","boiling"],"noi_dung":"Sự bay hơi xảy ra cả trên bề mặt và trong lòng chất lỏng, ở một nhiệt độ xác định.","cong_thuc":null,"y":["Nhiệt độ đó gọi là <b>nhiệt độ sôi</b>; mỗi chất có nhiệt độ sôi riêng.","Nước sôi ở <b>100 °C</b> (ở áp suất khí quyển bình thường).","Khi sôi có bọt khí nổi lên và vỡ trên mặt chất lỏng."],"bang":null,"bien":null,"vd":{"de":"Khi đun nước, nước bắt đầu sôi ở nhiệt độ nào, nhiệt độ đó có thay đổi khi đun tiếp không?","buoc":["Nước sôi ở 100 °C ở điều kiện thường","Suốt quá trình sôi, nhiệt độ giữ nguyên dù tiếp tục đun"],"kq":"Nước sôi ở 100 °C và nhiệt độ không đổi trong khi sôi."},"nham":["Nhầm sôi với bay hơi: bay hơi xảy ra ở mọi nhiệt độ và chỉ ở mặt thoáng."],"lq":["h6-su-bay-hoi","h6-su-chuyen-the","h6-chung-cat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-oxygen","mon":"KHTN","khoi":"6","chu_de":"h6-oxygen","thu_tu":1,"loai":"ch","ten":"Oxygen","ten_khac":["oxygen","oxi","oxy","khi oxi","duong khi","o2"],"noi_dung":"Chất khí không màu, không mùi, không vị, ít tan trong nước, cần cho sự sống và sự cháy.","cong_thuc":null,"y":["Ở điều kiện thường là <b>chất khí</b>; hóa lỏng ở −183 °C, oxygen lỏng màu xanh nhạt.","Ít tan trong nước, nặng hơn không khí.","<b>Duy trì sự sống</b> (hô hấp) và <b>duy trì sự cháy</b>.","Chiếm khoảng 21% thể tích không khí."],"bang":null,"bien":null,"vd":{"de":"Làm sao biết một lọ khí không màu đựng khí oxygen mà không phải khí khác?","buoc":["Đưa que đóm còn tàn đỏ vào miệng lọ khí","Nếu que đóm bùng cháy trở lại thì khí đó duy trì sự cháy mạnh"],"kq":"Que đóm bùng cháy chứng tỏ đó là khí oxygen."},"nham":["Viết tên cũ \"oxi\": theo CT 2018 dùng \"oxygen\"."],"lq":["h6-khong-khi","h6-thanh-phan-khong-khi","h6-su-chay"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-khong-khi","mon":"KHTN","khoi":"6","chu_de":"h6-oxygen","thu_tu":2,"loai":"ch","ten":"Không khí","ten_khac":["khong khi","khi quyen","bau khong khi","air"],"noi_dung":"Hỗn hợp nhiều chất khí bao quanh Trái Đất, chủ yếu là nitrogen và oxygen.","cong_thuc":null,"y":["Là một <b>hỗn hợp</b>, không phải một chất.","Cung cấp oxygen cho hô hấp và sự cháy; carbon dioxide cho cây quang hợp.","Nitrogen trong không khí góp phần cung cấp dưỡng chất cho cây.","Điều hòa khí hậu, bảo vệ Trái Đất."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ không khí là \"khí oxygen\": oxygen chỉ chiếm khoảng 1/5."],"lq":["h6-thanh-phan-khong-khi","h6-oxygen","h6-o-nhiem-khong-khi","h6-hon-hop"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-thanh-phan-khong-khi","mon":"KHTN","khoi":"6","chu_de":"h6-oxygen","thu_tu":3,"loai":"kn","ten":"Thành phần không khí","ten_khac":["thanh phan khong khi","78% nitrogen","21% oxygen","nito","nitrogen","khi hiem"],"noi_dung":"Theo thể tích, không khí gồm khoảng 78% nitrogen, 21% oxygen và 1% các khí khác.","cong_thuc":null,"y":["<b>Nitrogen</b> chiếm nhiều nhất (khoảng 78%).","<b>Oxygen</b> khoảng 21%.","Khoảng 1% còn lại: carbon dioxide, hơi nước, khí hiếm…","Thí nghiệm ước lượng: úp cốc lên ngọn nến đặt trong chậu nước, nến tắt, nước dâng lên khoảng 1/5 cốc."],"bang":[["Khí","Thể tích (%)"],["Nitrogen","78"],["Oxygen","21"],["Khí khác","1"]],"bien":null,"vd":{"de":"Úp một cốc thủy tinh lên ngọn nến đang cháy đặt trong chậu nước. Sau khi nến tắt, nước dâng lên khoảng bao nhiêu phần cốc, vì sao?","buoc":["Nến cháy tiêu hao oxygen trong cốc, đến khi thiếu oxygen thì nến tắt","Nước dâng lên chiếm chỗ phần khí oxygen đã bị tiêu hao"],"kq":"Nước dâng lên khoảng 1/5 cốc, cho thấy oxygen chiếm khoảng 1/5 thể tích không khí."},"nham":["Nhầm oxygen chiếm nhiều nhất: nhiều nhất là nitrogen."],"lq":["h6-khong-khi","h6-oxygen","h6-hon-hop-dong-nhat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-su-chay","mon":"KHTN","khoi":"6","chu_de":"h6-oxygen","thu_tu":4,"loai":"ht","ten":"Sự cháy","ten_khac":["su chay","chay","dot chay","phan ung chay","combustion","dap lua"],"noi_dung":"Quá trình chất tác dụng với oxygen, tỏa nhiệt và phát sáng.","cong_thuc":null,"y":["Điều kiện để cháy: có <b>chất cháy</b>, có <b>oxygen</b> và nhiệt độ đủ cao.","Càng nhiều oxygen, sự cháy càng mạnh; que đóm còn tàn đỏ bùng cháy trong oxygen.","Dập lửa: loại bỏ một trong ba điều kiện, như cách li chất cháy với oxygen, hạ nhiệt độ hoặc dọn chất cháy đi."],"bang":null,"bien":null,"vd":{"de":"Muốn dập một đám cháy dầu ăn trong chảo, vì sao không nên đổ nước vào mà nên đậy nắp vung?","buoc":["Đổ nước có thể làm dầu bắn tung tóe, lửa lan rộng hơn","Đậy nắp vung cách li dầu cháy với oxygen bên ngoài"],"kq":"Đậy vung ngăn oxygen tiếp xúc với dầu, lửa tắt do thiếu điều kiện cháy."},"nham":["Nghĩ cháy là chuyển thể: sự cháy tạo ra chất mới, là biến đổi hóa học."],"lq":["h6-oxygen","h6-nhien-lieu","h6-tinh-chat-hoa-hoc","h6-an-toan-nhien-lieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-o-nhiem-khong-khi","mon":"KHTN","khoi":"6","chu_de":"h6-oxygen","thu_tu":5,"loai":"ud","ten":"Ô nhiễm không khí","ten_khac":["o nhiem khong khi","o nhiem","khi thai","bui min","bao ve khong khi","air pollution"],"noi_dung":"Sự có mặt của chất lạ hoặc thay đổi thành phần không khí, gây hại cho sức khỏe và môi trường.","cong_thuc":null,"y":["Nguyên nhân: khí thải xe cộ, nhà máy, đốt rác, đốt rơm rạ; cháy rừng, núi lửa.","Tác hại: bệnh hô hấp, mưa acid, tăng hiệu ứng nhà kính, giảm tầm nhìn.","<b>Bảo vệ</b>: trồng cây, dùng phương tiện công cộng, năng lượng sạch, không đốt rác bừa bãi."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h6-khong-khi","h6-thanh-phan-khong-khi","h6-nhien-lieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-vat-lieu","mon":"KHTN","khoi":"6","chu_de":"h6-vat-lieu","thu_tu":1,"loai":"kn","ten":"Vật liệu","ten_khac":["vat lieu","vat lieu la gi","material","vat lieu xay dung"],"noi_dung":"Chất hoặc hỗn hợp chất được con người dùng làm nguyên liệu đầu vào để tạo ra sản phẩm.","cong_thuc":null,"y":["Vật liệu thông dụng: <b>kim loại, nhựa, cao su, gỗ, thủy tinh, gốm</b>.","Mỗi vật liệu có tính chất riêng nên dùng cho mục đích khác nhau.","Ví dụ: dây điện có lõi đồng (dẫn điện), vỏ nhựa (cách điện)."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h6-kim-loai","h6-nhua","h6-su-dung-vat-lieu","h6-nguyen-lieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-kim-loai","mon":"KHTN","khoi":"6","chu_de":"h6-vat-lieu","thu_tu":2,"loai":"ch","ten":"Kim loại","ten_khac":["kim loai","sat","nhom","dong","metal","vat lieu kim loai"],"noi_dung":"Vật liệu có ánh kim, dẫn điện, dẫn nhiệt tốt, dễ uốn, dễ kéo sợi.","cong_thuc":null,"y":["Ví dụ: sắt, nhôm, đồng và hợp kim như thép, inox.","Dùng làm dây điện, nồi xoong, khung nhà, máy móc.","Nhiều kim loại (như sắt) dễ bị <b>gỉ</b> khi để trong không khí ẩm."],"bang":null,"bien":null,"vd":{"de":"Vì sao dây dẫn điện thường có lõi bằng đồng nhưng vỏ bọc lại làm bằng nhựa?","buoc":["Đồng là kim loại, dẫn điện tốt nên làm lõi dẫn dòng điện","Nhựa không dẫn điện nên làm vỏ để cách điện, bảo đảm an toàn"],"kq":"Lõi đồng dẫn điện, vỏ nhựa cách điện, kết hợp để dẫn điện an toàn."},"nham":["Nghĩ mọi kim loại đều bị gỉ như sắt: nhôm, inox ít bị gỉ."],"lq":["h6-vat-lieu","h6-su-dung-vat-lieu","h6-nguyen-lieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-nhua","mon":"KHTN","khoi":"6","chu_de":"h6-vat-lieu","thu_tu":3,"loai":"ch","ten":"Nhựa","ten_khac":["nhua","chat deo","plastic","do nhua","rac thai nhua"],"noi_dung":"Vật liệu nhẹ, bền, không dẫn điện, dẫn nhiệt kém, dễ tạo hình.","cong_thuc":null,"y":["Dùng làm chai lọ, đồ gia dụng, vỏ dây điện, đồ chơi.","Không bị gỉ, ít bị ăn mòn.","Rất <b>khó phân hủy</b> nên rác thải nhựa gây ô nhiễm; cần giảm dùng, tái sử dụng, tái chế."],"bang":null,"bien":null,"vd":{"de":"Vì sao nên hạn chế dùng túi nilon và thay bằng túi vải, giấy khi có thể?","buoc":["Nhựa rất khó phân hủy, tồn tại rất lâu ngoài môi trường","Túi vải, giấy dễ phân hủy hơn, đỡ gây ô nhiễm"],"kq":"Giảm dùng túi nhựa giúp giảm rác thải khó phân hủy, bảo vệ môi trường."},"nham":null,"lq":["h6-vat-lieu","h6-cao-su","h6-su-dung-vat-lieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-cao-su","mon":"KHTN","khoi":"6","chu_de":"h6-vat-lieu","thu_tu":4,"loai":"ch","ten":"Cao su","ten_khac":["cao su","mu cao su","rubber","cao su tu nhien","cao su nhan tao"],"noi_dung":"Vật liệu có tính đàn hồi, không thấm nước, cách điện, cách nhiệt tốt.","cong_thuc":null,"y":["Có <b>cao su tự nhiên</b> (từ mủ cây cao su) và <b>cao su nhân tạo</b>.","Dùng làm lốp xe, găng tay, ủng, đệm.","Dễ bị lão hóa khi gặp nhiệt độ cao, ánh nắng."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h6-vat-lieu","h6-nhua","h6-nguyen-lieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-go","mon":"KHTN","khoi":"6","chu_de":"h6-vat-lieu","thu_tu":5,"loai":"ch","ten":"Gỗ","ten_khac":["go","vat lieu go","wood","go tu nhien","do go"],"noi_dung":"Vật liệu tự nhiên lấy từ thân cây, cứng, bền, dễ gia công.","cong_thuc":null,"y":["Dùng làm nhà cửa, bàn ghế, đồ mĩ nghệ, giấy.","Cách điện, cách nhiệt.","Dễ bị <b>mối mọt, ẩm mốc</b>, dễ cháy; khai thác quá mức làm mất rừng."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h6-vat-lieu","h6-su-dung-vat-lieu","h6-vat-the-tu-nhien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-thuy-tinh","mon":"KHTN","khoi":"6","chu_de":"h6-vat-lieu","thu_tu":6,"loai":"ch","ten":"Thủy tinh","ten_khac":["thuy tinh","kinh","glass","chai thuy tinh","cat"],"noi_dung":"Vật liệu trong suốt, cứng nhưng giòn, dễ vỡ, không bị gỉ.","cong_thuc":null,"y":["Nguyên liệu chính để sản xuất là <b>cát</b>.","Dùng làm cửa kính, chai lọ, dụng cụ thí nghiệm, kính mắt.","Ít bị ăn mòn, có thể tái chế."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h6-vat-lieu","h6-gom","h6-nguyen-lieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-gom","mon":"KHTN","khoi":"6","chu_de":"h6-vat-lieu","thu_tu":7,"loai":"ch","ten":"Gốm","ten_khac":["gom","do gom","gom su","dat set","ceramic","gach ngoi"],"noi_dung":"Vật liệu làm từ đất sét nung, cứng, cách điện, cách nhiệt, chịu nhiệt tốt nhưng giòn.","cong_thuc":null,"y":["Dùng làm gạch, ngói, bát đĩa, bình hoa, sứ cách điện.","Không bị gỉ, bền với nhiệt.","Giòn, <b>dễ vỡ</b> khi va đập."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h6-vat-lieu","h6-thuy-tinh","h6-nguyen-lieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-su-dung-vat-lieu","mon":"KHTN","khoi":"6","chu_de":"h6-vat-lieu","thu_tu":8,"loai":"ud","ten":"Sử dụng vật liệu bền vững","ten_khac":["su dung vat lieu","vat lieu an toan hieu qua","phat trien ben vung","ben vung","tai che","tiet kiem vat lieu"],"noi_dung":"Dùng vật liệu an toàn, hiệu quả, tiết kiệm để bảo vệ tài nguyên và môi trường.","cong_thuc":null,"y":["<b>Chọn đúng</b> vật liệu theo tính chất và mục đích sử dụng.","Sử dụng đúng cách, bảo quản để tăng độ bền.","Tiết kiệm, <b>tái sử dụng, tái chế</b>, giảm rác thải khó phân hủy."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h6-vat-lieu","h6-nhua","h6-kim-loai","h6-go"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-nguyen-lieu","mon":"KHTN","khoi":"6","chu_de":"h6-vat-lieu","thu_tu":9,"loai":"kn","ten":"Nguyên liệu","ten_khac":["nguyen lieu","nguyen lieu la gi","quang","khoang san","raw material"],"noi_dung":"Vật liệu tự nhiên (vật liệu thô) chưa qua xử lí, cần được chế biến để tạo ra sản phẩm.","cong_thuc":null,"y":["Ví dụ: <b>quặng</b> (quặng sắt, quặng bauxite để sản xuất nhôm), đá vôi, cát, dầu mỏ, mủ cao su.","Nguồn nguyên liệu tự nhiên có hạn.","Cần khai thác hợp lí, sử dụng tiết kiệm, an toàn và bảo vệ môi trường."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm nguyên liệu với nhiên liệu: nhiên liệu là chất cháy được để lấy nhiệt."],"lq":["h6-da-voi","h6-vat-lieu","h6-nhien-lieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-da-voi","mon":"KHTN","khoi":"6","chu_de":"h6-vat-lieu","thu_tu":10,"loai":"ch","ten":"Đá vôi","ten_khac":["da voi","calcium carbonate","canxi cacbonat","caco3","voi song","xi mang","limestone"],"noi_dung":"Nguyên liệu tự nhiên, thành phần chính là calcium carbonate, dùng trong xây dựng và sản xuất vôi, xi măng.","cong_thuc":null,"y":["Dạng rắn, cứng, không tan trong nước.","Nung đá vôi thu được <b>vôi sống</b>.","Dùng sản xuất <b>xi măng</b>, làm vật liệu xây dựng, rải đường."],"bang":null,"bien":null,"vd":{"de":"Vì sao đá vôi thường được khai thác để sản xuất xi măng và vôi sống?","buoc":["Đá vôi có thành phần chính là calcium carbonate","Nung đá vôi ở nhiệt độ cao thu được vôi sống, dùng làm nguyên liệu xây dựng"],"kq":"Vì đá vôi là nguyên liệu chính, sẵn có để sản xuất vôi sống và xi măng."},"nham":null,"lq":["h6-nguyen-lieu","h6-vat-lieu","h6-gom"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-quang","mon":"KHTN","khoi":"6","chu_de":"h6-vat-lieu","thu_tu":11,"loai":"ch","ten":"Quặng","ten_khac":["quang","quang sat","quang bauxite","quang nhom","khoang san"],"noi_dung":"Đất đá chứa khoáng chất với hàm lượng đủ lớn để khai thác, dùng làm nguyên liệu tách kim loại hoặc sản xuất.","cong_thuc":null,"y":["<b>Quặng sắt</b> là nguyên liệu để sản xuất gang, thép.","<b>Quặng bauxite</b> là nguyên liệu để sản xuất nhôm.","Quặng là tài nguyên có hạn, cần khai thác hợp lí và tái chế kim loại."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ quặng là kim loại nguyên chất; quặng là đất đá chứa hợp chất của kim loại."],"lq":["h6-nguyen-lieu","h6-da-voi","h6-kim-loai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-khai-thac-nguyen-lieu","mon":"KHTN","khoi":"6","chu_de":"h6-vat-lieu","thu_tu":12,"loai":"ud","ten":"Sử dụng nguyên liệu bền vững","ten_khac":["khai thac nguyen lieu","ben vung","tiet kiem nguyen lieu","khai thac cat","khai thac khoang san"],"noi_dung":"Nguyên liệu tự nhiên có hạn; khai thác bừa bãi gây cạn kiệt tài nguyên và ô nhiễm môi trường.","cong_thuc":null,"y":["Khai thác có kế hoạch, đúng quy định; không khai thác trái phép.","Sử dụng tiết kiệm, tái chế; dùng nguyên liệu thay thế khi có thể.","Khai thác đá, cát, quặng bừa bãi gây sạt lở, ô nhiễm không khí và nguồn nước."],"bang":null,"bien":null,"vd":{"de":"Khai thác cát trái phép ở lòng sông có thể gây hậu quả gì?","buoc":["Lòng sông bị khoét sâu, dòng chảy thay đổi.","Bờ sông dễ bị sạt lở, ảnh hưởng tới nhà cửa và đất canh tác."],"kq":"Gây sạt lở bờ sông và làm cạn kiệt tài nguyên cát."},"nham":null,"lq":["h6-nguyen-lieu","h6-quang","h6-su-dung-vat-lieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-nhien-lieu","mon":"KHTN","khoi":"6","chu_de":"h6-vat-lieu","thu_tu":13,"loai":"kn","ten":"Nhiên liệu","ten_khac":["nhien lieu","chat dot","than cui","xang dau","khi gas","fuel"],"noi_dung":"Chất cháy được, khi cháy tỏa nhiệt (và phát sáng), dùng để cung cấp năng lượng.","cong_thuc":null,"y":["<b>Rắn</b>: than, củi. <b>Lỏng</b>: xăng, dầu hỏa. <b>Khí</b>: khí gas, biogas.","Nhiên liệu hóa thạch (than, dầu mỏ, khí thiên nhiên) có hạn, khi cháy gây ô nhiễm.","Cần tiết kiệm, dùng thêm nguồn năng lượng khác để bảo đảm <b>an ninh năng lượng</b>."],"bang":[["Thể","Ví dụ"],["Rắn","than, củi"],["Lỏng","xăng, dầu hỏa"],["Khí","khí gas, biogas"]],"bien":null,"vd":{"de":"So với đốt một khối than to nguyên khối, đập nhỏ than trước khi đốt giúp than cháy như thế nào?","buoc":["Đập nhỏ làm tăng diện tích tiếp xúc giữa than với oxygen không khí","Diện tích tiếp xúc lớn giúp than cháy nhanh và hoàn toàn hơn"],"kq":"Than đập nhỏ cháy nhanh và mạnh hơn so với để nguyên khối to."},"nham":["Nhầm nhiên liệu với nguyên liệu."],"lq":["h6-su-chay","h6-an-toan-nhien-lieu","h6-nguyen-lieu","h6-o-nhiem-khong-khi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-an-toan-nhien-lieu","mon":"KHTN","khoi":"6","chu_de":"h6-vat-lieu","thu_tu":14,"loai":"ud","ten":"Sử dụng nhiên liệu an toàn","ten_khac":["an toan nhien lieu","su dung nhien lieu","ro ri gas","chay hieu qua","tiet kiem nhien lieu","carbon monoxide","cacbon monoxit","ngo doc khi than"],"noi_dung":"Cách đốt nhiên liệu hiệu quả, tiết kiệm và phòng tránh cháy nổ, ngộ độc.","cong_thuc":null,"y":["Cháy hiệu quả: cung cấp <b>đủ không khí</b> (oxygen), tăng diện tích tiếp xúc (chẻ nhỏ củi), điều chỉnh lượng nhiên liệu.","Đốt thiếu không khí sinh khí <b>carbon monoxide</b> rất độc; không đốt than trong phòng kín.","Rò rỉ gas: khóa van, mở cửa thông gió, không bật lửa hay công tắc điện."],"bang":null,"bien":null,"vd":{"de":"Vì sao không nên đốt than sưởi ấm trong phòng kín, đóng hết cửa?","buoc":["Phòng kín thiếu oxygen khiến than cháy không hoàn toàn","Sinh ra khí carbon monoxide rất độc, có thể gây ngộ độc, tử vong"],"kq":"Đốt than trong phòng kín có thể sinh khí CO độc, rất nguy hiểm."},"nham":null,"lq":["h6-nhien-lieu","h6-su-chay","h6-oxygen"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-nhien-lieu-thay-the","mon":"KHTN","khoi":"6","chu_de":"h6-vat-lieu","thu_tu":15,"loai":"kn","ten":"Nhiên liệu thay thế","ten_khac":["nhien lieu thay the","biogas","xang sinh hoc","xang e5","khi sinh hoc"],"noi_dung":"Nhiên liệu dùng thay cho nhiên liệu hóa thạch đang dần cạn kiệt, thường ít gây ô nhiễm hơn, như biogas, xăng sinh học.","cong_thuc":null,"y":["<b>Biogas</b> (khí sinh học) tạo ra từ chất thải chăn nuôi, rác hữu cơ.","<b>Xăng sinh học</b> (ví dụ xăng E5) là xăng pha thêm cồn làm từ ngô, sắn.","Dùng nhiên liệu thay thế giúp tiết kiệm nhiên liệu hóa thạch và giảm ô nhiễm."],"bang":null,"bien":null,"vd":{"de":"Vì sao nhiều trang trại chăn nuôi xây hầm biogas?","buoc":["Chất thải chăn nuôi trong hầm bị phân hủy, tạo ra khí biogas.","Khí biogas dùng làm nhiên liệu đun nấu, chất thải không bị xả thẳng ra môi trường."],"kq":"Vừa có nhiên liệu, vừa giảm ô nhiễm môi trường."},"nham":["Nghĩ nhiên liệu thay thế khi cháy không gây ô nhiễm chút nào."],"lq":["h6-nhien-lieu","h6-an-toan-nhien-lieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-luong-thuc","mon":"KHTN","khoi":"6","chu_de":"h6-vat-lieu","thu_tu":16,"loai":"ch","ten":"Lương thực","ten_khac":["luong thuc","gao","ngo","khoai","san","tinh bot"],"noi_dung":"Thức ăn chứa nhiều tinh bột, là nguồn chính cung cấp năng lượng cho cơ thể.","cong_thuc":null,"y":["Ví dụ: lúa gạo, ngô, lúa mì, khoai, sắn.","Thành phần chính là <b>tinh bột</b> (carbohydrate).","Lương thực là một phần của thực phẩm."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h6-thuc-pham","h6-chat-dinh-duong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-thuc-pham","mon":"KHTN","khoi":"6","chu_de":"h6-vat-lieu","thu_tu":17,"loai":"ch","ten":"Thực phẩm","ten_khac":["thuc pham","do an","thuc an","bao quan thuc pham","ve sinh an toan thuc pham"],"noi_dung":"Sản phẩm con người ăn, uống ở dạng tươi sống hoặc đã qua chế biến, bảo quản.","cong_thuc":null,"y":["Cung cấp <b>chất dinh dưỡng</b> cho cơ thể.","Bảo quản: làm lạnh, phơi khô, ướp muối, đóng hộp…","Chọn thực phẩm tươi, rõ nguồn gốc, còn hạn dùng; ăn uống đa dạng, cân đối."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h6-luong-thuc","h6-chat-dinh-duong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-chat-dinh-duong","mon":"KHTN","khoi":"6","chu_de":"h6-vat-lieu","thu_tu":18,"loai":"kn","ten":"Chất dinh dưỡng","ten_khac":["chat dinh duong","dinh duong","chat dam","chat beo","vitamin","chat khoang","protein"],"noi_dung":"Các chất trong thực phẩm cơ thể cần để sống, lớn lên và hoạt động.","cong_thuc":null,"y":["<b>Carbohydrate</b> (tinh bột, đường): cung cấp năng lượng chính.","<b>Protein</b> (chất đạm): xây dựng cơ thể. <b>Lipid</b> (chất béo): dự trữ năng lượng.","<b>Vitamin</b> và <b>chất khoáng</b>: cần lượng nhỏ nhưng thiếu sẽ gây bệnh."],"bang":[["Nhóm chất","Có nhiều trong"],["Carbohydrate","gạo, ngô, khoai"],["Protein","thịt, cá, trứng, đậu"],["Lipid","dầu ăn, mỡ, lạc"],["Vitamin, chất khoáng","rau, quả"]],"bien":null,"vd":null,"nham":null,"lq":["h6-thuc-pham","h6-luong-thuc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-chat-tinh-khiet","mon":"KHTN","khoi":"6","chu_de":"h6-hon-hop","thu_tu":1,"loai":"kn","ten":"Chất tinh khiết","ten_khac":["chat tinh khiet","chat nguyen chat","tinh khiet","nuoc cat","pure substance"],"noi_dung":"Chất tinh khiết (chất nguyên chất) được tạo ra từ một chất duy nhất, có tính chất xác định.","cong_thuc":null,"y":["Ví dụ: <b>nước cất</b>, đường ăn, muối ăn tinh khiết.","Nước cất sôi ở 100 °C, đông đặc ở 0 °C (áp suất khí quyển bình thường).","Muốn có chất tinh khiết phải tách chất ra khỏi hỗn hợp."],"bang":null,"bien":null,"vd":{"de":"Nước cất và nước máy (đã qua xử lí), loại nào là chất tinh khiết?","buoc":["Nước cất chỉ chứa một chất là nước, không lẫn chất khác","Nước máy còn hòa tan một số khoáng chất, khí nên không tinh khiết hoàn toàn"],"kq":"Nước cất là chất tinh khiết; nước máy là hỗn hợp (dung dịch loãng)."},"nham":["Coi nước khoáng, nước máy là chất tinh khiết: chúng có hòa tan chất khác nên là hỗn hợp."],"lq":["h6-hon-hop","h6-chung-cat","h6-chat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-hon-hop","mon":"KHTN","khoi":"6","chu_de":"h6-hon-hop","thu_tu":2,"loai":"kn","ten":"Hỗn hợp","ten_khac":["hon hop","hon hop la gi","tron lan","mixture"],"noi_dung":"Hỗn hợp gồm hai hay nhiều chất trộn lẫn với nhau.","cong_thuc":null,"y":["Mỗi chất trong hỗn hợp vẫn <b>giữ nguyên tính chất</b> của nó.","Tính chất hỗn hợp thay đổi theo thành phần.","Có hai loại: <b>hỗn hợp đồng nhất</b> và <b>hỗn hợp không đồng nhất</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h6-chat-tinh-khiet","h6-hon-hop-dong-nhat","h6-hon-hop-khong-dong-nhat","h6-khong-khi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-hon-hop-dong-nhat","mon":"KHTN","khoi":"6","chu_de":"h6-hon-hop","thu_tu":3,"loai":"kn","ten":"Hỗn hợp đồng nhất","ten_khac":["hon hop dong nhat","dong nhat","homogeneous","nuoc muoi"],"noi_dung":"Hỗn hợp có thành phần giống nhau ở mọi vị trí, không phân biệt được các chất bằng mắt.","cong_thuc":null,"y":["Ví dụ: nước muối, nước đường, không khí.","<b>Dung dịch</b> là hỗn hợp đồng nhất."],"bang":null,"bien":null,"vd":{"de":"Khuấy tan hoàn toàn một thìa đường vào cốc nước, có còn thấy hạt đường không? Đây là loại hỗn hợp nào?","buoc":["Đường tan hết, không còn nhìn thấy hạt riêng biệt","Mọi vị trí trong cốc đều ngọt như nhau"],"kq":"Đó là hỗn hợp đồng nhất (dung dịch đường)."},"nham":null,"lq":["h6-hon-hop","h6-hon-hop-khong-dong-nhat","h6-dung-dich"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-hon-hop-khong-dong-nhat","mon":"KHTN","khoi":"6","chu_de":"h6-hon-hop","thu_tu":4,"loai":"kn","ten":"Hỗn hợp không đồng nhất","ten_khac":["hon hop khong dong nhat","khong dong nhat","heterogeneous","nuoc cat","nuoc phu sa"],"noi_dung":"Hỗn hợp có thành phần không giống nhau ở mọi vị trí, thường nhìn thấy các chất riêng.","cong_thuc":null,"y":["Ví dụ: nước lẫn cát, dầu ăn với nước, nước phù sa.","<b>Huyền phù</b> và <b>nhũ tương</b> là hỗn hợp không đồng nhất."],"bang":null,"bien":null,"vd":{"de":"Khuấy một thìa bột phấn không tan vào cốc nước rồi để yên. Sau vài phút quan sát thấy hiện tượng gì?","buoc":["Bột phấn không tan trong nước","Sau khi để yên, bột phấn lắng dần xuống đáy cốc"],"kq":"Đó là hỗn hợp không đồng nhất (huyền phù), bột phấn lắng xuống đáy."},"nham":["Đọc nhầm \"nước cát\" (nước lẫn cát) với \"nước cất\" (chất tinh khiết)."],"lq":["h6-hon-hop","h6-hon-hop-dong-nhat","h6-huyen-phu","h6-nhu-tuong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-dung-dich","mon":"KHTN","khoi":"6","chu_de":"h6-hon-hop","thu_tu":5,"loai":"kn","ten":"Dung dịch","ten_khac":["dung dich","dd","solution","nuoc duong","nuoc muoi"],"noi_dung":"Hỗn hợp đồng nhất của dung môi và chất tan.","cong_thuc":null,"y":["Dung dịch = <b>dung môi</b> + <b>chất tan</b>.","Ví dụ: nước muối (dung môi nước, chất tan muối ăn).","Trong suốt, để lâu không lắng, không tách lớp."],"bang":null,"bien":null,"vd":{"de":"Pha một thìa muối ăn vào cốc nước rồi khuấy đều cho tan hết. Đâu là dung môi, đâu là chất tan?","buoc":["Muối ăn là chất bị hòa tan nên là chất tan","Nước là chất hòa tan muối nên là dung môi"],"kq":"Nước là dung môi, muối ăn là chất tan; hỗn hợp thu được là dung dịch nước muối."},"nham":["Coi nước phù sa là dung dịch: đó là huyền phù."],"lq":["h6-dung-moi","h6-chat-tan","h6-su-hoa-tan","h6-hon-hop-dong-nhat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-dung-moi","mon":"KHTN","khoi":"6","chu_de":"h6-hon-hop","thu_tu":6,"loai":"kn","ten":"Dung môi","ten_khac":["dung moi","chat dung de hoa tan","solvent","nuoc la dung moi"],"noi_dung":"Chất dùng để hòa tan chất khác, tạo thành dung dịch.","cong_thuc":null,"y":["Nước là <b>dung môi phổ biến</b> nhất.","Ngoài nước còn có xăng, dầu hỏa, cồn…","Ví dụ: trong nước đường, nước là dung môi."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h6-chat-tan","h6-dung-dich","h6-su-hoa-tan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-chat-tan","mon":"KHTN","khoi":"6","chu_de":"h6-hon-hop","thu_tu":7,"loai":"kn","ten":"Chất tan","ten_khac":["chat tan","chat bi hoa tan","solute","chat khong tan"],"noi_dung":"Chất bị hòa tan trong dung môi để tạo thành dung dịch.","cong_thuc":null,"y":["Có thể là chất rắn (muối, đường), lỏng (cồn) hoặc khí.","Chất <b>không tan</b> trong một dung môi thì tạo hỗn hợp không đồng nhất, ví dụ cát trong nước."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h6-dung-moi","h6-dung-dich","h6-su-hoa-tan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-su-hoa-tan","mon":"KHTN","khoi":"6","chu_de":"h6-hon-hop","thu_tu":8,"loai":"ht","ten":"Sự hòa tan","ten_khac":["su hoa tan","hoa tan","tan","hoa tan nhanh","dissolve"],"noi_dung":"Quá trình chất tan phân bố đều vào dung môi, tạo thành dung dịch.","cong_thuc":null,"y":["Chất rắn tan nhanh hơn khi <b>khuấy</b>, <b>đun nóng</b>, <b>nghiền nhỏ</b>.","Ở nhiệt độ cao, thường hòa tan được nhiều chất rắn hơn.","Một lượng dung môi xác định chỉ hòa tan được một lượng chất tan có giới hạn."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm hòa tan với nóng chảy."],"lq":["h6-chat-tan","h6-dung-moi","h6-dung-dich","h6-su-nong-chay"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-huyen-phu","mon":"KHTN","khoi":"6","chu_de":"h6-hon-hop","thu_tu":9,"loai":"kn","ten":"Huyền phù","ten_khac":["huyen phu","chat ran lo lung","suspension","nuoc phu sa","bot trong nuoc"],"noi_dung":"Hỗn hợp gồm các hạt chất rắn lơ lửng trong chất lỏng.","cong_thuc":null,"y":["Là hỗn hợp <b>không đồng nhất</b>, thường đục.","Để lâu, chất rắn <b>lắng xuống</b> đáy.","Ví dụ: nước phù sa, bột sắn khuấy trong nước, bột đá vôi khuấy trong nước."],"bang":null,"bien":null,"vd":{"de":"Khuấy đều bột sắn dây với nước rồi để yên vài phút, thấy bột lắng dần xuống đáy cốc. Đây là loại hỗn hợp gì?","buoc":["Bột sắn dây không tan hoàn toàn trong nước, tạo hạt lơ lửng","Để yên, các hạt rắn lắng xuống đáy do nặng hơn nước"],"kq":"Đó là huyền phù, hỗn hợp không đồng nhất giữa chất rắn và chất lỏng."},"nham":["Nhầm huyền phù (rắn trong lỏng) với nhũ tương (lỏng trong lỏng)."],"lq":["h6-nhu-tuong","h6-hon-hop-khong-dong-nhat","h6-loc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-nhu-tuong","mon":"KHTN","khoi":"6","chu_de":"h6-hon-hop","thu_tu":10,"loai":"kn","ten":"Nhũ tương","ten_khac":["nhu tuong","dau trong nuoc","emulsion","long trong long"],"noi_dung":"Hỗn hợp gồm các giọt chất lỏng phân tán trong một chất lỏng khác không tan vào nhau.","cong_thuc":null,"y":["Là hỗn hợp <b>không đồng nhất</b>.","Để yên một thời gian, hai chất lỏng thường <b>tách thành hai lớp</b>.","Ví dụ: dầu ăn lắc mạnh với nước, dầu hỏa lắc mạnh với nước."],"bang":null,"bien":null,"vd":{"de":"Lắc mạnh một ít dầu ăn với nước trong ống nghiệm rồi để yên, sau vài phút quan sát thấy gì?","buoc":["Lúc lắc, dầu tạo thành các giọt nhỏ phân tán trong nước","Để yên, dầu và nước tách thành hai lớp riêng do không tan vào nhau"],"kq":"Đó là nhũ tương tạm thời; để yên, dầu nổi lên tách thành lớp trên nước."},"nham":null,"lq":["h6-huyen-phu","h6-hon-hop-khong-dong-nhat","h6-chiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-loc","mon":"KHTN","khoi":"6","chu_de":"h6-hon-hop","thu_tu":11,"loai":"tn","ten":"Lọc","ten_khac":["loc","phuong phap loc","giay loc","pheu loc","filtration"],"noi_dung":"Cách tách chất rắn không tan ra khỏi chất lỏng bằng giấy lọc, phễu lọc.","cong_thuc":null,"y":["Dụng cụ: <b>phễu</b>, <b>giấy lọc</b>, cốc thủy tinh, đũa thủy tinh.","Chất rắn giữ lại trên giấy lọc; chất lỏng chảy qua gọi là nước lọc.","Ví dụ: tách cát khỏi nước, lọc nước giếng."],"bang":null,"bien":null,"vd":{"de":"Có một cốc nước bị lẫn cát. Nêu cách đơn giản để tách cát ra khỏi nước.","buoc":["Chuẩn bị phễu và giấy lọc đặt trên cốc hứng","Đổ từ từ hỗn hợp qua giấy lọc"],"kq":"Cát bị giữ lại trên giấy lọc, nước trong chảy xuống cốc, đó là phương pháp lọc."},"nham":["Lọc nước muối để lấy muối: muối tan đi qua giấy lọc, phải dùng cô cạn."],"lq":["h6-co-can","h6-chiet","h6-huyen-phu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-co-can","mon":"KHTN","khoi":"6","chu_de":"h6-hon-hop","thu_tu":12,"loai":"tn","ten":"Cô cạn","ten_khac":["co can","phuong phap co can","lam bay hoi","lay muoi","evaporate"],"noi_dung":"Cách đun nóng dung dịch cho dung môi bay hơi hết, thu lấy chất rắn đã tan trong đó.","cong_thuc":null,"y":["Dụng cụ: bát sứ, đèn cồn, kiềng đun.","Ví dụ: cô cạn nước muối thu được muối ăn.","Ruộng muối là cô cạn nước biển nhờ nắng và gió."],"bang":null,"bien":null,"vd":{"de":"Làm sao thu lại muối ăn tinh khiết từ dung dịch nước muối?","buoc":["Đun nóng dung dịch trong bát sứ để nước bay hơi dần","Đun đến khi nước bay hơi hết, chỉ còn lại chất rắn"],"kq":"Cô cạn dung dịch, thu được muối ăn ở dạng rắn."},"nham":null,"lq":["h6-su-bay-hoi","h6-loc","h6-dung-dich"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-chiet","mon":"KHTN","khoi":"6","chu_de":"h6-hon-hop","thu_tu":13,"loai":"tn","ten":"Chiết","ten_khac":["chiet","phuong phap chiet","pheu chiet","tach dau nuoc","extraction"],"noi_dung":"Cách tách các chất lỏng không tan vào nhau, dựa vào chúng tách thành các lớp riêng.","cong_thuc":null,"y":["Dụng cụ: <b>phễu chiết</b> có khóa.","Để hỗn hợp yên cho tách lớp, mở khóa cho chất lỏng lớp dưới chảy ra trước.","Ví dụ: tách dầu ăn ra khỏi nước."],"bang":null,"bien":null,"vd":{"de":"Có một hỗn hợp dầu hỏa lẫn nước, hai chất không tan vào nhau và tách thành hai lớp. Làm sao tách riêng chúng?","buoc":["Cho hỗn hợp vào phễu chiết có khóa, để yên cho tách lớp","Mở khóa từ từ để lớp nước (nặng hơn) chảy ra trước rồi khóa lại giữ dầu hỏa"],"kq":"Dùng phễu chiết, tách được nước và dầu hỏa thành hai phần riêng."},"nham":null,"lq":["h6-nhu-tuong","h6-loc","h6-chung-cat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h6-chung-cat","mon":"KHTN","khoi":"6","chu_de":"h6-hon-hop","thu_tu":14,"loai":"tn","ten":"Chưng cất (mở rộng)","ten_khac":["chung cat","nuoc cat","cat nuoc","distillation","cat ruou"],"noi_dung":"Cách đun sôi hỗn hợp lỏng rồi làm lạnh hơi để thu chất lỏng, dựa vào nhiệt độ sôi khác nhau.","cong_thuc":null,"y":["<b>Mở rộng</b>: SGK KNTT 6 học ba cách tách chất là lọc, cô cạn và chiết.","Gồm hai bước: <b>bay hơi (sôi)</b> rồi <b>ngưng tụ</b>.","Ví dụ: chưng cất nước thường để có <b>nước cất</b>; nấu rượu."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h6-su-soi","h6-su-ngung-tu","h6-chat-tinh-khiet","h6-chiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-phuong-phap-tim-hieu-tu-nhien","mon":"KHTN","khoi":"7","chu_de":"nguyen-tu","thu_tu":1,"loai":"tn","ten":"Phương pháp tìm hiểu tự nhiên","ten_khac":["phuong phap tim hieu tu nhien","phuong phap khoa hoc","du doan","du doan khoa hoc","gia thuyet","cac buoc nghien cuu","bao cao","de xuat van de"],"noi_dung":"Cách tìm hiểu tự nhiên theo 5 bước: đề xuất vấn đề, đưa ra dự đoán, lập kế hoạch, thực hiện kế hoạch, viết báo cáo.","cong_thuc":null,"y":["<b>Bước 1:</b> Đề xuất vấn đề cần tìm hiểu (quan sát, đặt câu hỏi).","<b>Bước 2:</b> Đưa ra <b>dự đoán khoa học</b> để giải quyết vấn đề.","<b>Bước 3–4:</b> Lập kế hoạch kiểm tra dự đoán rồi thực hiện kế hoạch; dự đoán sai thì quay lại bước 2.","<b>Bước 5:</b> Viết báo cáo, thảo luận và trình bày báo cáo."],"bang":null,"bien":null,"vd":null,"nham":["Dự đoán chưa phải là kết luận: phải kiểm tra bằng thí nghiệm mới biết đúng hay sai."],"lq":["h7-ki-nang-hoc-tap-khtn","h7-nguyen-tu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-ki-nang-hoc-tap-khtn","mon":"KHTN","khoi":"7","chu_de":"nguyen-tu","thu_tu":2,"loai":"tn","ten":"Kĩ năng học tập KHTN","ten_khac":["ki nang","ky nang","quan sat","phan loai","lien ket","ki nang do","du bao","ki nang hoc tap"],"noi_dung":"Những kĩ năng cơ bản khi học KHTN: quan sát – phân loại, liên kết, đo và dự báo.","cong_thuc":null,"y":["<b>Quan sát, phân loại:</b> dùng giác quan, dụng cụ để thu thông tin rồi xếp đối tượng thành nhóm.","<b>Liên kết:</b> tìm mối liên hệ giữa các sự vật, hiện tượng.","<b>Đo:</b> dùng dụng cụ đo để xác định số liệu.","<b>Dự báo:</b> nói trước điều có thể xảy ra dựa vào quan sát, hiểu biết."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h7-phuong-phap-tim-hieu-tu-nhien","h7-bang-tuan-hoan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-nguyen-tu","mon":"KHTN","khoi":"7","chu_de":"nguyen-tu","thu_tu":3,"loai":"kn","ten":"Nguyên tử","ten_khac":["nguyen tu","atom","hat vo cung nho","trung hoa ve dien","cau tao nguyen tu"],"noi_dung":"Hạt vô cùng nhỏ, trung hòa về điện, tạo nên các chất; gồm hạt nhân ở giữa và vỏ electron bao quanh.","cong_thuc":null,"y":["Gồm <b>hạt nhân</b> mang điện dương và <b>vỏ nguyên tử</b> gồm các electron mang điện âm.","Số proton = số electron nên nguyên tử <b>trung hòa về điện</b>.","Khối lượng nguyên tử tập trung gần hết ở hạt nhân."],"bang":[["Hạt","Kí hiệu","Điện tích","Khối lượng","Vị trí"],["Proton","p","+1","≈ 1 amu","hạt nhân"],["Neutron","n","0","≈ 1 amu","hạt nhân"],["Electron","e","−1","≈ 0,00055 amu","vỏ"]],"bien":null,"vd":{"de":"Một nguyên tử có 11 electron. Nguyên tử này có bao nhiêu proton, vì sao?","buoc":["Nguyên tử trung hòa về điện nên số p bằng số e","Số e là 11"],"kq":"11 proton, vì số p luôn bằng số e trong nguyên tử."},"nham":["Nguyên tử không mang điện, dù bên trong có hạt mang điện."],"lq":["h7-hat-nhan","h7-electron","h7-mo-hinh-rutherford-bohr"],"hinh":"H-h7-nguyen-tu","nguon":["KHTN Pocket"]},{"ma":"h7-mo-hinh-rutherford-bohr","mon":"KHTN","khoi":"7","chu_de":"nguyen-tu","thu_tu":4,"loai":"kn","ten":"Mô hình Rutherford – Bohr","ten_khac":["mo hinh nguyen tu","rutherford","bohr","mo hinh bohr","mo hinh hanh tinh","so do nguyen tu"],"noi_dung":"Mô hình nguyên tử: hạt nhân ở tâm, các electron chuyển động quanh hạt nhân theo từng lớp.","cong_thuc":null,"y":["Hạt nhân mang điện dương nằm ở tâm nguyên tử.","Electron xếp thành <b>từng lớp</b> quanh hạt nhân, lớp trong xếp đủ rồi mới sang lớp ngoài.","Vẽ sơ đồ: vòng tròn đồng tâm là các lớp, chấm nhỏ là electron."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h7-nguyen-tu","h7-lop-electron"],"hinh":"H-h7-mo-hinh-rutherford-bohr","nguon":["KHTN Pocket"]},{"ma":"h7-hat-nhan","mon":"KHTN","khoi":"7","chu_de":"nguyen-tu","thu_tu":5,"loai":"cq","ten":"Hạt nhân nguyên tử","ten_khac":["hat nhan","hat nhan nguyen tu","nucleus","dien tich hat nhan","loi nguyen tu"],"noi_dung":"Phần ở tâm nguyên tử, mang điện dương, gồm các proton và neutron.","cong_thuc":null,"y":["Gồm <b>proton</b> (mang điện dương) và <b>neutron</b> (không mang điện).","Số đơn vị điện tích hạt nhân bằng số proton.","Rất nhỏ so với nguyên tử nhưng chứa gần như toàn bộ khối lượng nguyên tử."],"bang":null,"bien":null,"vd":{"de":"Hạt nhân một nguyên tử có 8 proton và 8 neutron. Hạt nhân mang điện gì và khối lượng khoảng bao nhiêu?","buoc":["Hạt nhân chỉ có p (điện dương) và n (không mang điện) nên mang điện dương","Khối lượng hạt nhân xấp xỉ số p cộng số n = 8 + 8"],"kq":"Hạt nhân mang điện dương, khối lượng khoảng 16 amu."},"nham":["Electron không nằm trong hạt nhân mà chuyển động ở vỏ nguyên tử."],"lq":["h7-proton","h7-neutron","h7-nguyen-tu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-proton","mon":"KHTN","khoi":"7","chu_de":"nguyen-tu","thu_tu":6,"loai":"kn","ten":"Proton","ten_khac":["proton","p","hat p","so p","hat mang dien duong"],"noi_dung":"Hạt trong hạt nhân nguyên tử, mang điện tích +1, khối lượng khoảng 1 amu.","cong_thuc":null,"y":["Kí hiệu <b>p</b>, điện tích <b>+1</b>, khối lượng ≈ 1 amu.","Số proton = số electron = số hiệu nguyên tử <b>Z</b>.","Số proton quyết định nguyên tử thuộc nguyên tố nào."],"bang":null,"bien":null,"vd":{"de":"Hai nguyên tử cùng có 6 proton nhưng số neutron khác nhau (6 và 8). Chúng có phải cùng một nguyên tố không?","buoc":["Nguyên tố được xác định bởi số proton (số hiệu nguyên tử)","Cả hai đều có 6 proton"],"kq":"Có, cả hai đều là nguyên tố carbon dù số neutron khác nhau."},"nham":["Hạt mang điện gồm cả proton và electron, không chỉ có proton."],"lq":["h7-hat-nhan","h7-so-hieu-nguyen-tu","h7-nguyen-to-hoa-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-neutron","mon":"KHTN","khoi":"7","chu_de":"nguyen-tu","thu_tu":7,"loai":"kn","ten":"Neutron","ten_khac":["neutron","notron","n","hat n","so n","hat khong mang dien"],"noi_dung":"Hạt trong hạt nhân nguyên tử, không mang điện, khối lượng khoảng 1 amu.","cong_thuc":null,"y":["Kí hiệu <b>n</b>, không mang điện, khối lượng ≈ 1 amu.","Số n ≈ khối lượng nguyên tử − số p.","Các nguyên tử cùng nguyên tố có thể khác nhau số neutron."],"bang":null,"bien":null,"vd":{"de":"Nguyên tử potassium có 19 proton và khối lượng nguyên tử khoảng 39 amu. Tính số neutron.","buoc":["Số n xấp xỉ khối lượng nguyên tử trừ số p","= 39 - 19"],"kq":"20 neutron"},"nham":["Số neutron không nhất thiết bằng số proton (Na: 11 p, 12 n)."],"lq":["h7-hat-nhan","h7-khoi-luong-nguyen-tu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-electron","mon":"KHTN","khoi":"7","chu_de":"nguyen-tu","thu_tu":8,"loai":"kn","ten":"Electron","ten_khac":["electron","e","hat e","so e","vo nguyen tu","hat mang dien am"],"noi_dung":"Hạt mang điện tích −1, chuyển động quanh hạt nhân, tạo nên vỏ nguyên tử.","cong_thuc":null,"y":["Kí hiệu <b>e</b>, điện tích <b>−1</b>, khối lượng rất nhỏ (≈ 0,00055 amu).","Trong nguyên tử: số e = số p.","Electron xếp thành từng lớp; electron lớp ngoài cùng tham gia tạo liên kết hóa học."],"bang":null,"bien":null,"vd":{"de":"Nguyên tử aluminium có 13 proton, xếp electron theo lớp là 2, 8, 3. Lớp ngoài cùng có bao nhiêu electron?","buoc":["Tổng số electron bằng số proton, tức 13","Xếp theo lớp 2, 8, 3 thì lớp ngoài cùng có 3 electron"],"kq":"3 electron ở lớp ngoài cùng."},"nham":["Nghĩ electron nặng ngang proton: electron nhẹ hơn proton gần 2 000 lần nên thường bỏ qua khi tính khối lượng nguyên tử."],"lq":["h7-lop-electron","h7-nguyen-tu","h7-lien-ket-hoa-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-lop-electron","mon":"KHTN","khoi":"7","chu_de":"nguyen-tu","thu_tu":9,"loai":"cq","ten":"Lớp electron","ten_khac":["lop electron","lop e","lop vo","xep electron","electron lop ngoai cung","e ngoai cung","so lop e"],"noi_dung":"Các electron trong nguyên tử được xếp thành từng lớp quanh hạt nhân, mỗi lớp chứa tối đa một số electron.","cong_thuc":null,"y":["Lớp 1 chứa tối đa <b>2 e</b>, lớp 2 tối đa <b>8 e</b>.","Với Z ≤ 20: lớp 3 nhận 8 e rồi mới sang lớp 4 (K: 2, 8, 8, 1).","Số lớp e = số thứ tự chu kì; số e lớp ngoài cùng = số thứ tự nhóm A."],"bang":null,"bien":null,"vd":{"de":"Xếp electron của nguyên tử Na (Z = 11).","buoc":["Lớp 1: 2 e","Lớp 2: 8 e","Lớp 3: 11 − 10 = 1 e"],"kq":"2, 8, 1 (3 lớp, 1 e ngoài cùng)"},"nham":["Xếp K (Z = 19) thành 2, 8, 9 là sai; đúng là 2, 8, 8, 1."],"lq":["h7-electron","h7-chu-ki","h7-nhom-nguyen-to"],"hinh":"H-h7-lop-electron","nguon":["KHTN Pocket"]},{"ma":"h7-khoi-luong-nguyen-tu","mon":"KHTN","khoi":"7","chu_de":"nguyen-tu","thu_tu":10,"loai":"dl","ten":"Khối lượng nguyên tử","ten_khac":["khoi luong nguyen tu","klnt","nguyen tu khoi","ntk","khoi luong hat nhan","p + n"],"noi_dung":"Khối lượng của một nguyên tử, tính bằng amu, xấp xỉ bằng tổng số proton và neutron.","cong_thuc":"KLNT ≈ số p + số n","y":["Khối lượng electron rất nhỏ nên bỏ qua.","Tra khối lượng nguyên tử trong ô nguyên tố của bảng tuần hoàn."],"bang":[["Nguyên tố","KLNT (amu)"],["H","1"],["C","12"],["O","16"],["Na","23"],["Cl","35,5"],["Fe","56"]],"bien":[["KLNT","khối lượng nguyên tử","amu"],["số p","số proton",""],["số n","số neutron",""]],"vd":{"de":"Nguyên tử Al có 13 proton và 14 neutron. Tính khối lượng nguyên tử của Al.","buoc":["KLNT ≈ số p + số n = 13 + 14"],"kq":"27 amu"},"nham":["Làm tròn Cl thành 35 là sai; dùng 35,5."],"lq":["h7-amu","h7-neutron","h7-khoi-luong-phan-tu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-amu","mon":"KHTN","khoi":"7","chu_de":"nguyen-tu","thu_tu":11,"loai":"dl","ten":"Đơn vị amu","ten_khac":["amu","dvc","don vi cacbon","don vi khoi luong nguyen tu","atomic mass unit","u"],"noi_dung":"Đơn vị khối lượng nguyên tử (atomic mass unit), dùng để đo khối lượng nguyên tử và phân tử.","cong_thuc":null,"y":["1 amu = 1,6605 × 10⁻²⁴ g.","Khối lượng 1 proton ≈ 1 neutron ≈ <b>1 amu</b>.","Tên cũ trong sách cũ: đơn vị carbon (đvC)."],"bang":null,"bien":null,"vd":{"de":"Một nguyên tử có 12 proton và 12 neutron. Tính khối lượng nguyên tử theo amu.","buoc":["Khối lượng nguyên tử xấp xỉ số p cộng số n","= 12 + 12"],"kq":"24 amu"},"nham":["amu là đơn vị khối lượng, không phải đơn vị điện tích."],"lq":["h7-khoi-luong-nguyen-tu","h7-khoi-luong-phan-tu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-nguyen-to-hoa-hoc","mon":"KHTN","khoi":"7","chu_de":"nguyen-tu","thu_tu":12,"loai":"kn","ten":"Nguyên tố hóa học","ten_khac":["nguyen to","nguyen to hoa hoc","element","cung so proton","nthh"],"noi_dung":"Tập hợp những nguyên tử cùng loại, có cùng số proton trong hạt nhân.","cong_thuc":null,"y":["Số proton đặc trưng cho nguyên tố: 8 proton luôn là <b>oxygen</b>.","Nguyên tử cùng số p nhưng khác số n vẫn thuộc <b>cùng một nguyên tố</b>.","Hiện nay đã biết <b>118</b> nguyên tố hóa học."],"bang":null,"bien":null,"vd":{"de":"Nguyên tử có 6 proton, 8 neutron thuộc nguyên tố nào?","buoc":["Số p = 6 → Z = 6"],"kq":"Carbon (C)"},"nham":["Xác định nguyên tố theo số proton, không theo số neutron hay khối lượng."],"lq":["h7-ki-hieu-hoa-hoc","h7-so-hieu-nguyen-tu","h7-proton"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-ki-hieu-hoa-hoc","mon":"KHTN","khoi":"7","chu_de":"nguyen-tu","thu_tu":13,"loai":"kn","ten":"Kí hiệu hóa học","ten_khac":["ki hieu hoa hoc","ky hieu hoa hoc","kht","khhh","ki hieu nguyen to","viet ki hieu"],"noi_dung":"Cách viết ngắn gọn biểu diễn một nguyên tố hóa học, gồm một hoặc hai chữ cái.","cong_thuc":null,"y":["Chữ cái đầu viết <b>in hoa</b>, chữ thứ hai (nếu có) viết <b>thường</b>: Na, Cl, Ca.","Kí hiệu thường lấy từ tên Latin hoặc tên IUPAC của nguyên tố."],"bang":[["Tên","Kí hiệu"],["Hydrogen","H"],["Oxygen","O"],["Sodium","Na"],["Potassium","K"],["Iron","Fe"],["Copper","Cu"]],"bien":null,"vd":{"de":"Vì sao kí hiệu của nguyên tố calcium viết là Ca chứ không phải CA hay ca?","buoc":["Quy ước: chữ cái đầu viết in hoa, chữ thứ hai (nếu có) viết thường","Ca đúng quy ước; CA và ca đều sai"],"kq":"Kí hiệu đúng là Ca, chữ C in hoa và chữ a viết thường."},"nham":["Co là cobalt (nguyên tố), CO là hợp chất carbon monoxide.","Viết CL, NA là sai quy tắc."],"lq":["h7-nguyen-to-hoa-hoc","h7-cong-thuc-hoa-hoc","h7-o-nguyen-to"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-so-hieu-nguyen-tu","mon":"KHTN","khoi":"7","chu_de":"nguyen-tu","thu_tu":14,"loai":"kn","ten":"Số hiệu nguyên tử","ten_khac":["so hieu nguyen tu","z","so thu tu","so hieu","atomic number","dien tich hat nhan"],"noi_dung":"Số proton trong hạt nhân nguyên tử (kí hiệu Z), cũng là số thứ tự ô nguyên tố trong bảng tuần hoàn.","cong_thuc":null,"y":["<b>Z = số p = số e</b> = số thứ tự ô nguyên tố.","Mỗi nguyên tố có một số hiệu nguyên tử riêng."],"bang":null,"bien":null,"vd":{"de":"Nguyên tố ở ô số 12 có bao nhiêu proton và electron?","buoc":["Z = 12 → số p = số e = 12"],"kq":"12 proton, 12 electron (magnesium, Mg)"},"nham":null,"lq":["h7-proton","h7-o-nguyen-to","h7-nguyen-to-hoa-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-bang-tuan-hoan","mon":"KHTN","khoi":"7","chu_de":"h7-bang-tuan-hoan","thu_tu":1,"loai":"kn","ten":"Bảng tuần hoàn","ten_khac":["bang tuan hoan","bth","bang tuan hoan cac nguyen to hoa hoc","mendeleev","periodic table","bang hoa hoc"],"noi_dung":"Bảng xếp các nguyên tố hóa học theo quy luật, gồm các ô nguyên tố, chu kì và nhóm.","cong_thuc":null,"y":["Do <b>Mendeleev</b> đề xuất (1869), ngày nay có 118 nguyên tố.","Cấu tạo: <b>ô nguyên tố</b>, <b>chu kì</b> (hàng ngang), <b>nhóm</b> (cột dọc).","Chia thành 3 vùng: kim loại, phi kim, khí hiếm."],"bang":null,"bien":null,"vd":{"de":"Muốn biết nguyên tố có kí hiệu Cl thuộc chu kì mấy, nhóm mấy, cần tra ở đâu và dựa vào gì?","buoc":["Tra ô nguyên tố Cl trong bảng tuần hoàn","Xem hàng ngang (chu kì) và cột dọc (nhóm) chứa ô đó"],"kq":"Cl ở chu kì 3, nhóm VIIA."},"nham":null,"lq":["h7-nguyen-tac-sap-xep","h7-o-nguyen-to","h7-chu-ki","h7-nhom-nguyen-to"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-nguyen-tac-sap-xep","mon":"KHTN","khoi":"7","chu_de":"h7-bang-tuan-hoan","thu_tu":2,"loai":"kn","ten":"Nguyên tắc sắp xếp bảng tuần hoàn","ten_khac":["nguyen tac sap xep","sap xep bang tuan hoan","dien tich hat nhan tang dan","nguyen tac xay dung"],"noi_dung":"Các nguyên tố được xếp theo chiều tăng dần điện tích hạt nhân, theo số lớp electron và tính chất.","cong_thuc":null,"y":["Xếp theo chiều <b>tăng dần điện tích hạt nhân</b> (số p).","Nguyên tố có cùng <b>số lớp electron</b> xếp cùng một hàng.","Nguyên tố có <b>tính chất hóa học tương tự</b> xếp cùng một cột."],"bang":null,"bien":null,"vd":{"de":"Sodium (Z=11) và potassium (Z=19) đều có 1 electron lớp ngoài cùng. Chúng có được xếp cùng một cột trong bảng tuần hoàn không?","buoc":["Nguyên tố có cùng số electron lớp ngoài cùng thường có tính chất hóa học tương tự","Chúng được xếp cùng một nhóm (cột) trong bảng tuần hoàn"],"kq":"Có, Na và K cùng thuộc nhóm IA."},"nham":null,"lq":["h7-bang-tuan-hoan","h7-chu-ki","h7-nhom-nguyen-to"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-o-nguyen-to","mon":"KHTN","khoi":"7","chu_de":"h7-bang-tuan-hoan","thu_tu":3,"loai":"cq","ten":"Ô nguyên tố","ten_khac":["o nguyen to","o","o trong bang tuan hoan","doc o nguyen to","thong tin o"],"noi_dung":"Mỗi ô trong bảng tuần hoàn dành cho một nguyên tố, cho biết số hiệu, kí hiệu, tên và khối lượng nguyên tử.","cong_thuc":null,"y":["Ô ghi: <b>số hiệu nguyên tử</b>, kí hiệu hóa học, tên nguyên tố, khối lượng nguyên tử.","Số thứ tự ô = Z = số p = số e."],"bang":null,"bien":null,"vd":{"de":"Ô số 17 là chlorine (Cl), khối lượng nguyên tử 35,5. Nguyên tử Cl có bao nhiêu electron?","buoc":["Số thứ tự ô = Z = 17","Số e = Z"],"kq":"17 electron"},"nham":null,"lq":["h7-so-hieu-nguyen-tu","h7-bang-tuan-hoan","h7-khoi-luong-nguyen-tu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-chu-ki","mon":"KHTN","khoi":"7","chu_de":"h7-bang-tuan-hoan","thu_tu":4,"loai":"cq","ten":"Chu kì","ten_khac":["chu ki","chu ky","hang ngang","period","chu ki nho","chu ki lon"],"noi_dung":"Dãy các nguyên tố có cùng số lớp electron, xếp thành một hàng ngang trong bảng tuần hoàn.","cong_thuc":null,"y":["Bảng tuần hoàn có <b>7 chu kì</b>.","Số thứ tự chu kì = <b>số lớp electron</b>.","Chu kì 1, 2, 3 là chu kì nhỏ; chu kì 4 đến 7 là chu kì lớn."],"bang":null,"bien":null,"vd":{"de":"Mg (Z = 12) ở chu kì mấy?","buoc":["Xếp e: 2, 8, 2 → 3 lớp electron"],"kq":"Chu kì 3"},"nham":["Chu kì ứng với số lớp e, nhóm ứng với số e lớp ngoài cùng; đừng đảo."],"lq":["h7-lop-electron","h7-nhom-nguyen-to","h7-bang-tuan-hoan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-nhom-nguyen-to","mon":"KHTN","khoi":"7","chu_de":"h7-bang-tuan-hoan","thu_tu":5,"loai":"cq","ten":"Nhóm nguyên tố","ten_khac":["nhom","nhom nguyen to","cot doc","nhom a","nhom b","group","e lop ngoai cung"],"noi_dung":"Tập hợp các nguyên tố có tính chất hóa học tương tự, xếp thành cột dọc trong bảng tuần hoàn.","cong_thuc":null,"y":["Có nhóm A (IA đến VIIIA) và nhóm B.","Các nguyên tố nhóm A có cùng <b>số e lớp ngoài cùng</b>; số thứ tự nhóm A = số e lớp ngoài cùng.","Nhóm VIIIA là nhóm khí hiếm."],"bang":null,"bien":null,"vd":{"de":"Cl (Z = 17) thuộc nhóm nào?","buoc":["Xếp e: 2, 8, 7","7 e lớp ngoài cùng"],"kq":"Nhóm VIIA"},"nham":["He ở nhóm VIIIA dù chỉ có 2 e lớp ngoài cùng."],"lq":["h7-chu-ki","h7-lop-electron","h7-khi-hiem","h7-bang-tuan-hoan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-kim-loai","mon":"KHTN","khoi":"7","chu_de":"h7-bang-tuan-hoan","thu_tu":6,"loai":"ch","ten":"Nguyên tố kim loại","ten_khac":["kim loai","nguyen to kim loai","metal","anh kim","dan dien"],"noi_dung":"Nhóm nguyên tố chiếm phần lớn bảng tuần hoàn, đơn chất có ánh kim, dẫn điện và dẫn nhiệt tốt.","cong_thuc":null,"y":["Nằm ở phía <b>bên trái và giữa</b> bảng tuần hoàn.","Đơn chất có ánh kim, dẫn điện, dẫn nhiệt tốt, dễ dát mỏng, kéo sợi.","Ở điều kiện thường đều ở thể rắn, trừ <b>thủy ngân</b> (Hg) ở thể lỏng."],"bang":[["Ví dụ","Kí hiệu"],["Sodium","Na"],["Aluminium","Al"],["Iron","Fe"],["Copper","Cu"]],"bien":null,"vd":{"de":"Ở điều kiện thường, hầu hết kim loại tồn tại ở thể rắn. Kim loại nào là ngoại lệ, tồn tại ở thể lỏng?","buoc":["Xét tính chất vật lí chung của kim loại","Chỉ có một kim loại duy nhất ở thể lỏng ở điều kiện thường"],"kq":"Thủy ngân (Hg) là kim loại ở thể lỏng."},"nham":null,"lq":["h7-phi-kim","h7-khi-hiem","h7-lien-ket-ion"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-phi-kim","mon":"KHTN","khoi":"7","chu_de":"h7-bang-tuan-hoan","thu_tu":7,"loai":"ch","ten":"Phi kim","ten_khac":["phi kim","nguyen to phi kim","non metal","khong dan dien"],"noi_dung":"Nhóm nguyên tố nằm chủ yếu ở góc trên bên phải bảng tuần hoàn, đơn chất thường không dẫn điện.","cong_thuc":null,"y":["Đơn chất không có ánh kim, thường dẫn điện, dẫn nhiệt kém.","Ở điều kiện thường có thể ở thể rắn (S, C), lỏng (bromine) hoặc khí (O₂, N₂, Cl₂).","Ví dụ: H, C, N, O, P, S, Cl."],"bang":null,"bien":null,"vd":{"de":"Ở điều kiện thường, oxygen và chlorine tồn tại ở thể gì, chúng có dẫn điện không?","buoc":["Oxygen (O2) và chlorine (Cl2) là phi kim, tồn tại ở thể khí ở điều kiện thường","Phi kim thường không dẫn điện"],"kq":"Cả hai đều ở thể khí và không dẫn điện."},"nham":["H đứng ở nhóm IA nhưng là phi kim."],"lq":["h7-kim-loai","h7-khi-hiem","h7-lien-ket-cong-hoa-tri"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-khi-hiem","mon":"KHTN","khoi":"7","chu_de":"h7-bang-tuan-hoan","thu_tu":8,"loai":"ch","ten":"Khí hiếm","ten_khac":["khi hiem","khi tro","nhom viiia","nhom 8a","helium","neon","argon","noble gas"],"noi_dung":"Các nguyên tố nhóm VIIIA, ở thể khí, rất khó tham gia phản ứng hóa học.","cong_thuc":null,"y":["Gồm helium (He), neon (Ne), argon (Ar)…","Lớp electron ngoài cùng có <b>8 e</b> (riêng He có 2 e) nên rất bền.","Tồn tại dạng nguyên tử riêng lẻ; ứng dụng: He bơm khí cầu, Ne làm đèn quảng cáo."],"bang":null,"bien":null,"vd":{"de":"Vì sao khí hiếm như neon, argon rất khó tham gia phản ứng hóa học?","buoc":["Lớp electron ngoài cùng của khí hiếm đã có đủ 8 electron (He có 2)","Cấu trúc electron này rất bền, không cần nhường, nhận hay góp thêm electron"],"kq":"Vì lớp ngoài cùng đã bền vững nên khí hiếm rất trơ, khó phản ứng."},"nham":null,"lq":["h7-nhom-nguyen-to","h7-lop-ngoai-cung-ben-vung","h7-phi-kim"],"hinh":"H-h7-khi-hiem","nguon":["KHTN Pocket"]},{"ma":"h7-phan-tu","mon":"KHTN","khoi":"7","chu_de":"h7-phan-tu","thu_tu":1,"loai":"kn","ten":"Phân tử","ten_khac":["phan tu","molecule","hat dai dien cho chat","phan tu la gi"],"noi_dung":"Hạt đại diện cho chất, gồm một số nguyên tử liên kết với nhau và thể hiện đầy đủ tính chất hóa học của chất.","cong_thuc":null,"y":["Phân tử nước H₂O gồm 2 nguyên tử H và 1 nguyên tử O.","Phân tử có thể gồm các nguyên tử <b>cùng loại</b> (O₂, N₂) hoặc <b>khác loại</b> (H₂O, CO₂).","Với kim loại (Fe, Cu), hạt hợp thành là nguyên tử."],"bang":null,"bien":null,"vd":{"de":"Phân tử carbon dioxide CO₂ gồm những nguyên tử nào, mỗi loại bao nhiêu?","buoc":["Đọc chỉ số trong công thức CO₂","C không ghi chỉ số nghĩa là 1; O có chỉ số 2"],"kq":"1 nguyên tử C và 2 nguyên tử O."},"nham":null,"lq":["h7-khoi-luong-phan-tu","h7-don-chat","h7-hop-chat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-khoi-luong-phan-tu","mon":"KHTN","khoi":"7","chu_de":"h7-phan-tu","thu_tu":2,"loai":"dl","ten":"Khối lượng phân tử","ten_khac":["khoi luong phan tu","klpt","phan tu khoi","ptk","tinh khoi luong phan tu"],"noi_dung":"Tổng khối lượng của các nguyên tử trong một phân tử, tính bằng amu.","cong_thuc":"KLPT(AₓBᵧ) = x × KLNT(A) + y × KLNT(B)","y":["Nhân khối lượng mỗi nguyên tử với số nguyên tử của nó rồi cộng lại.","Chỉ số ngoài ngoặc nhân với <b>mọi</b> nguyên tử trong ngoặc."],"bang":null,"bien":[["KLPT","khối lượng phân tử","amu"],["KLNT","khối lượng nguyên tử","amu"],["x, y","số nguyên tử A, B trong phân tử",""]],"vd":{"de":"Tính khối lượng phân tử của H₂SO₄ (H = 1, S = 32, O = 16).","buoc":["2 × 1 + 32 + 4 × 16","= 2 + 32 + 64"],"kq":"98 amu"},"nham":["Quên nhân chỉ số, hoặc quên nhân cả nhóm trong ngoặc: Ca(OH)₂ = 40 + 2 × (16 + 1) = 74 amu."],"lq":["h7-phan-tu","h7-khoi-luong-nguyen-tu","h7-y-nghia-cthh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-don-chat","mon":"KHTN","khoi":"7","chu_de":"h7-phan-tu","thu_tu":3,"loai":"kn","ten":"Đơn chất","ten_khac":["don chat","chat don gian","mot nguyen to","don chat kim loai","don chat phi kim"],"noi_dung":"Chất được tạo nên từ một nguyên tố hóa học.","cong_thuc":null,"y":["Gồm đơn chất <b>kim loại</b> (Fe, Cu), <b>phi kim</b> (O₂, S, C) và <b>khí hiếm</b> (He, Ne).","Một nguyên tố có thể tạo nhiều đơn chất: oxygen O₂ và ozone O₃; than chì và kim cương đều từ carbon."],"bang":null,"bien":null,"vd":{"de":"Khí oxygen O₂ và khí ozone O₃ đều tạo từ một nguyên tố oxygen nhưng tính chất khác nhau. Chúng có phải đều là đơn chất không?","buoc":["Đơn chất là chất tạo nên từ một nguyên tố hóa học","Cả O₂ và O₃ đều chỉ chứa nguyên tố oxygen"],"kq":"Đúng, cả hai đều là đơn chất của nguyên tố oxygen."},"nham":["O₂ và O₃ đều là đơn chất vì chỉ có một nguyên tố oxygen."],"lq":["h7-hop-chat","h7-phan-tu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-hop-chat","mon":"KHTN","khoi":"7","chu_de":"h7-phan-tu","thu_tu":4,"loai":"kn","ten":"Hợp chất","ten_khac":["hop chat","chat phuc tap","hai nguyen to tro len","compound"],"noi_dung":"Chất được tạo nên từ hai hay nhiều nguyên tố hóa học.","cong_thuc":null,"y":["Ví dụ: nước H₂O (H, O), muối ăn NaCl (Na, Cl), carbon dioxide CO₂ (C, O).","Tính chất của hợp chất khác hẳn tính chất các đơn chất tạo nên nó."],"bang":null,"bien":null,"vd":{"de":"Muối ăn NaCl được tạo nên từ những nguyên tố nào? Đây là đơn chất hay hợp chất?","buoc":["NaCl gồm hai nguyên tố là sodium và chlorine","Chất tạo từ 2 nguyên tố trở lên là hợp chất"],"kq":"NaCl là hợp chất, tạo từ hai nguyên tố Na và Cl."},"nham":["Hợp chất khác hỗn hợp: hỗn hợp là nhiều chất trộn lẫn, còn hợp chất là một chất."],"lq":["h7-don-chat","h7-phan-tu","h7-cong-thuc-hoa-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-lop-ngoai-cung-ben-vung","mon":"KHTN","khoi":"7","chu_de":"h7-phan-tu","thu_tu":5,"loai":"kn","ten":"Lớp vỏ bền vững của khí hiếm","ten_khac":["lop vo ben vung","vo electron khi hiem","cau hinh ben","lop ngoai cung ben","8 electron","quy tac bat tu","octet","vi sao lien ket"],"noi_dung":"Lớp electron ngoài cùng có 8 electron (He: 2 electron) như khí hiếm là cấu trúc bền vững.","cong_thuc":null,"y":["Khí hiếm rất bền vì lớp ngoài cùng đã đủ <b>8 e</b> (He: 2 e).","Nguyên tử các nguyên tố khác có xu hướng liên kết với nhau để có lớp ngoài cùng giống khí hiếm."],"bang":null,"bien":null,"vd":{"de":"Nguyên tử neon có 10 electron, xếp lớp 2, 8. Vì sao lớp ngoài cùng này được coi là bền vững?","buoc":["Lớp ngoài cùng của neon có 8 electron","Cấu hình 8 electron lớp ngoài (giống khí hiếm) là cấu trúc bền, khó bị phá vỡ"],"kq":"Vì lớp ngoài cùng đủ 8 electron, giống cấu trúc bền của khí hiếm."},"nham":null,"lq":["h7-khi-hiem","h7-lien-ket-hoa-hoc","h7-lien-ket-ion","h7-lien-ket-cong-hoa-tri"],"hinh":"H-h7-lop-ngoai-cung-ben-vung","nguon":["KHTN Pocket"]},{"ma":"h7-lien-ket-hoa-hoc","mon":"KHTN","khoi":"7","chu_de":"h7-phan-tu","thu_tu":6,"loai":"kn","ten":"Liên kết hóa học","ten_khac":["lien ket hoa hoc","lien ket","chemical bond","kieu lien ket","nhan biet lien ket"],"noi_dung":"Sự kết hợp giữa các nguyên tử để tạo thành phân tử hay tinh thể, giúp chúng có lớp vỏ bền như khí hiếm.","cong_thuc":null,"y":["Lớp 7 học hai kiểu: <b>liên kết ion</b> và <b>liên kết cộng hóa trị</b>.","Kim loại + phi kim → thường là liên kết ion (NaCl, MgO).","Phi kim + phi kim → liên kết cộng hóa trị (H₂O, CO₂, Cl₂)."],"bang":null,"bien":null,"vd":{"de":"Sodium (kim loại) kết hợp với chlorine (phi kim) tạo NaCl. Đây thường là kiểu liên kết gì?","buoc":["Kim loại kết hợp với phi kim thường tạo liên kết ion","Na nhường electron, Cl nhận electron"],"kq":"Đó là liên kết ion."},"nham":null,"lq":["h7-lien-ket-ion","h7-lien-ket-cong-hoa-tri","h7-lop-ngoai-cung-ben-vung"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-ion","mon":"KHTN","khoi":"7","chu_de":"h7-phan-tu","thu_tu":7,"loai":"kn","ten":"Ion","ten_khac":["ion","ion duong","ion am","cation","anion","nhuong electron","nhan electron"],"noi_dung":"Hạt mang điện tích, tạo thành khi nguyên tử (hoặc nhóm nguyên tử) nhường hay nhận electron.","cong_thuc":null,"y":["Nguyên tử <b>nhường</b> e → <b>ion dương</b> (Na⁺, Mg²⁺).","Nguyên tử <b>nhận</b> e → <b>ion âm</b> (Cl⁻, O²⁻).","Kim loại thường tạo ion dương, phi kim thường tạo ion âm."],"bang":null,"bien":null,"vd":{"de":"Nguyên tử Mg (2, 8, 2) tạo ion như thế nào?","buoc":["Mg nhường 2 e lớp ngoài cùng","Còn 12 p, 10 e → dư 2 điện tích dương"],"kq":"Ion Mg²⁺"},"nham":["Nhường e thì thành ion dương, nhận e thì thành ion âm; đừng đảo.","Na nhường 1 e, không nhận 7 e."],"lq":["h7-lien-ket-ion","h7-chat-ion","h7-electron"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-lien-ket-ion","mon":"KHTN","khoi":"7","chu_de":"h7-phan-tu","thu_tu":8,"loai":"kn","ten":"Liên kết ion","ten_khac":["lien ket ion","lk ion","ionic bond","hut tinh dien","nacl","kim loai phi kim"],"noi_dung":"Liên kết tạo thành do lực hút giữa ion mang điện tích trái dấu (ion dương và ion âm).","cong_thuc":null,"y":["Thường hình thành giữa <b>kim loại</b> và <b>phi kim</b>.","Kim loại nhường e thành ion dương, phi kim nhận e thành ion âm, hai ion hút nhau."],"bang":null,"bien":null,"vd":{"de":"Mô tả sự tạo liên kết trong sodium chloride NaCl.","buoc":["Na (2, 8, 1) nhường 1 e → Na⁺","Cl (2, 8, 7) nhận 1 e → Cl⁻","Na⁺ và Cl⁻ hút nhau"],"kq":"Liên kết ion trong NaCl"},"nham":null,"lq":["h7-ion","h7-chat-ion","h7-lien-ket-cong-hoa-tri"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-lien-ket-cong-hoa-tri","mon":"KHTN","khoi":"7","chu_de":"h7-phan-tu","thu_tu":9,"loai":"kn","ten":"Liên kết cộng hóa trị","ten_khac":["lien ket cong hoa tri","lkcht","cong hoa tri","covalent","gop chung electron","cap electron chung","dung chung electron"],"noi_dung":"Liên kết tạo thành do hai nguyên tử góp chung một hay nhiều cặp electron.","cong_thuc":null,"y":["Thường hình thành giữa các <b>phi kim</b> với nhau.","Mỗi nguyên tử góp electron để tạo <b>cặp electron dùng chung</b>, nhờ đó có lớp ngoài cùng bền như khí hiếm."],"bang":null,"bien":null,"vd":{"de":"Mô tả sự tạo liên kết trong phân tử nước H₂O.","buoc":["O có 6 e ngoài cùng, cần thêm 2 e","Mỗi H góp chung với O 1 cặp e","O có 8 e ngoài cùng, mỗi H có 2 e"],"kq":"H₂O có 2 cặp electron dùng chung"},"nham":["H₂O, CO₂ là chất cộng hóa trị, không phải chất ion."],"lq":["h7-lien-ket-ion","h7-chat-cong-hoa-tri","h7-hoa-tri"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-chat-ion","mon":"KHTN","khoi":"7","chu_de":"h7-phan-tu","thu_tu":10,"loai":"ch","ten":"Chất ion","ten_khac":["chat ion","hop chat ion","tinh chat chat ion","muoi an","nacl"],"noi_dung":"Chất được tạo nên bởi các ion dương và ion âm liên kết với nhau bằng liên kết ion.","cong_thuc":null,"y":["Ở điều kiện thường là <b>chất rắn</b>, khó nóng chảy, khó bay hơi.","Khi tan trong nước tạo dung dịch <b>dẫn được điện</b>.","Ví dụ: NaCl, MgO, CaCl₂."],"bang":null,"bien":null,"vd":{"de":"Muối ăn NaCl là chất rắn, khó nóng chảy, khi tan trong nước thì dung dịch dẫn được điện. Đây là loại chất gì?","buoc":["Chất rắn, khó nóng chảy, dung dịch dẫn điện là đặc điểm của chất ion","NaCl được tạo từ ion Na dương và Cl âm"],"kq":"NaCl là chất ion."},"nham":null,"lq":["h7-lien-ket-ion","h7-chat-cong-hoa-tri","h7-ion"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-chat-cong-hoa-tri","mon":"KHTN","khoi":"7","chu_de":"h7-phan-tu","thu_tu":11,"loai":"ch","ten":"Chất cộng hóa trị","ten_khac":["chat cong hoa tri","hop chat cong hoa tri","tinh chat chat cong hoa tri","duong","nuoc"],"noi_dung":"Chất được tạo nên từ các phân tử có liên kết cộng hóa trị.","cong_thuc":null,"y":["Ở điều kiện thường có thể ở thể <b>rắn, lỏng hoặc khí</b>.","Thường dễ nóng chảy, dễ bay hơi hơn chất ion.","Phần lớn không dẫn điện ở mọi trạng thái. Ví dụ: H₂O, CO₂, đường, O₂."],"bang":null,"bien":null,"vd":{"de":"Khí carbon dioxide CO₂ ở thể khí, không dẫn điện. Đây là chất ion hay chất cộng hóa trị?","buoc":["CO₂ tồn tại dạng phân tử, dễ bay hơi (thể khí ở điều kiện thường)","Không dẫn điện, đặc trưng của chất cộng hóa trị"],"kq":"CO₂ là chất cộng hóa trị."},"nham":["Chất cộng hóa trị có thể là đơn chất (O₂, N₂) hoặc hợp chất (H₂O)."],"lq":["h7-lien-ket-cong-hoa-tri","h7-chat-ion"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-cong-thuc-hoa-hoc","mon":"KHTN","khoi":"7","chu_de":"hoa-tri","thu_tu":1,"loai":"kn","ten":"Công thức hóa học","ten_khac":["cong thuc hoa hoc","cthh","viet cong thuc","chi so","axby","formula"],"noi_dung":"Cách biểu diễn chất bằng kí hiệu hóa học của nguyên tố kèm chỉ số ở chân mỗi kí hiệu.","cong_thuc":null,"y":["<b>Chỉ số</b> ghi ở chân kí hiệu, cho biết số nguyên tử của nguyên tố; bằng 1 thì không ghi.","Đơn chất kim loại và một số phi kim rắn: CTHH là kí hiệu (Fe, Cu, C, S).","Đơn chất phi kim khí thường có 2 nguyên tử: O₂, N₂, H₂, Cl₂. Hợp chất dạng AₓBᵧ."],"bang":null,"bien":null,"vd":{"de":"Viết công thức hóa học của hợp chất gồm 1 nguyên tử Ca và 2 nguyên tử Cl liên kết với nhau.","buoc":["Ghi kí hiệu Ca trước, Cl sau","Chỉ số 1 của Ca không ghi; chỉ số 2 của Cl ghi ở chân kí hiệu"],"kq":"CaCl₂"},"nham":["Viết O2 với số 2 to ngang chữ là sai; chỉ số phải nhỏ, ở chân kí hiệu.","2O là 2 nguyên tử oxygen, O₂ là 1 phân tử oxygen."],"lq":["h7-y-nghia-cthh","h7-hoa-tri","h7-lap-cthh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-y-nghia-cthh","mon":"KHTN","khoi":"7","chu_de":"hoa-tri","thu_tu":2,"loai":"kn","ten":"Ý nghĩa công thức hóa học","ten_khac":["y nghia cthh","y nghia cong thuc hoa hoc","cthh cho biet gi","doc cong thuc"],"noi_dung":"Công thức hóa học cho biết nguyên tố tạo nên chất, số nguyên tử mỗi nguyên tố và khối lượng phân tử.","cong_thuc":null,"y":["Cho biết chất do những <b>nguyên tố</b> nào tạo nên.","Cho biết <b>số nguyên tử</b> mỗi nguyên tố trong một phân tử.","Tính được <b>khối lượng phân tử</b> và phần trăm khối lượng các nguyên tố."],"bang":null,"bien":null,"vd":{"de":"Công thức CO₂ cho biết gì?","buoc":["Tạo từ 2 nguyên tố C và O","1 phân tử có 1 nguyên tử C và 2 nguyên tử O","KLPT = 12 + 2 × 16 = 44 amu"],"kq":"Hợp chất; 1 C, 2 O; 44 amu"},"nham":null,"lq":["h7-cong-thuc-hoa-hoc","h7-khoi-luong-phan-tu","h7-phan-tram-nguyen-to"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-hoa-tri","mon":"KHTN","khoi":"7","chu_de":"hoa-tri","thu_tu":3,"loai":"kn","ten":"Hóa trị","ten_khac":["hoa tri","hoa tri la gi","so la ma","hoa tri cua nguyen to","valence","bang hoa tri"],"noi_dung":"Con số biểu thị khả năng liên kết của nguyên tử nguyên tố này với nguyên tử nguyên tố khác, ghi bằng số La Mã.","cong_thuc":null,"y":["Quy ước: <b>H hóa trị I</b>, <b>O hóa trị II</b>.","Trong hợp chất cộng hóa trị, hóa trị bằng số electron nguyên tử đã góp chung để tạo liên kết.","Một số nguyên tố có nhiều hóa trị: Fe (II, III), S (II, IV, VI)."],"bang":[["Hóa trị","Ví dụ"],["I","H, Na, K, Cl, nhóm OH, NO₃"],["II","O, Mg, Ca, Zn, nhóm SO₄, CO₃"],["III","Al, nhóm PO₄"]],"bien":null,"vd":{"de":"Biết O có hóa trị II, H có hóa trị I. Vì sao công thức của nước là H₂O chứ không phải HO?","buoc":["Quy tắc hóa trị: tích hóa trị và số nguyên tử của nguyên tố này bằng của nguyên tố kia","Với O hóa trị II cần 2 H hóa trị I để cân bằng: 2 lần I bằng 1 lần II"],"kq":"Công thức đúng là H₂O, 2 nguyên tử H ứng với 1 nguyên tử O."},"nham":["Không lấy chỉ số làm hóa trị: trong SO₃, S hóa trị VI chứ không phải 3."],"lq":["h7-quy-tac-hoa-tri","h7-lap-cthh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-quy-tac-hoa-tri","mon":"KHTN","khoi":"7","chu_de":"hoa-tri","thu_tu":4,"loai":"ct","ten":"Quy tắc hóa trị","ten_khac":["quy tac hoa tri","a.x = b.y","ax=by","tim hoa tri","tinh hoa tri"],"noi_dung":"Trong hợp chất hai nguyên tố, tích chỉ số và hóa trị của nguyên tố này bằng tích đó của nguyên tố kia.","cong_thuc":"a × x = b × y","y":["Dùng để <b>tìm hóa trị</b> chưa biết hoặc <b>kiểm tra</b> công thức đúng hay sai.","Áp dụng được cả khi B là nhóm nguyên tử (SO₄, OH…)."],"bang":null,"bien":[["a, b","hóa trị của A, B",""],["x, y","chỉ số của A, B trong AₓBᵧ",""]],"vd":{"de":"Tìm hóa trị của N trong NH₃.","buoc":["Gọi hóa trị N là a; H hóa trị I","a × 1 = I × 3"],"kq":"N hóa trị III"},"nham":null,"lq":["h7-hoa-tri","h7-lap-cthh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-lap-cthh","mon":"KHTN","khoi":"7","chu_de":"hoa-tri","thu_tu":5,"loai":"ct","ten":"Lập CTHH theo hóa trị","ten_khac":["lap cthh","lap cong thuc","quy tac cheo","cheo hoa tri","viet cong thuc theo hoa tri"],"noi_dung":"Từ hóa trị đã biết, lập tỉ lệ số nguyên tử x : y = b : a rồi viết công thức hóa học.","cong_thuc":"x : y = b : a","y":["Bước 1: viết AₓBᵧ, ghi hóa trị a, b.","Bước 2: lập x : y = b : a, rút về tỉ lệ tối giản.","Bước 3: viết công thức; nhóm nguyên tử có chỉ số lớn hơn 1 đặt trong ngoặc."],"bang":null,"bien":[["x, y","chỉ số của A, B",""],["a, b","hóa trị của A, B",""]],"vd":{"de":"Lập công thức hợp chất của Al (III) với O (II).","buoc":["x : y = II : III = 2 : 3","x = 2, y = 3"],"kq":"Al₂O₃"},"nham":["Quên rút gọn: Ca₂O₂ phải viết CaO.","Thiếu ngoặc: CaOH₂ phải viết Ca(OH)₂."],"lq":["h7-quy-tac-hoa-tri","h7-hoa-tri"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-phan-tram-nguyen-to","mon":"KHTN","khoi":"7","chu_de":"hoa-tri","thu_tu":6,"loai":"dl","ten":"Phần trăm khối lượng nguyên tố","ten_khac":["phan tram khoi luong","%m","phan tram nguyen to","thanh phan phan tram","% nguyen to"],"noi_dung":"Tỉ lệ phần trăm khối lượng của một nguyên tố so với khối lượng phân tử hợp chất.","cong_thuc":"%A = x × KLNT(A) / KLPT × 100%","y":["Tổng phần trăm các nguyên tố trong hợp chất bằng 100%.","Tính % nguyên tố cuối cùng bằng 100% trừ các % đã tính."],"bang":null,"bien":[["%A","phần trăm khối lượng nguyên tố A","%"],["x","số nguyên tử A trong phân tử",""],["KLNT(A)","khối lượng nguyên tử A","amu"],["KLPT","khối lượng phân tử hợp chất","amu"]],"vd":{"de":"Tính phần trăm khối lượng N trong NH₃ (N = 14, H = 1).","buoc":["KLPT = 14 + 3 × 1 = 17 amu","%N = 14 / 17 × 100%"],"kq":"%N ≈ 82,4%"},"nham":["Quên nhân với số nguyên tử x."],"lq":["h7-xac-dinh-cthh","h7-khoi-luong-phan-tu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h7-xac-dinh-cthh","mon":"KHTN","khoi":"7","chu_de":"hoa-tri","thu_tu":7,"loai":"ct","ten":"Xác định CTHH từ phần trăm","ten_khac":["xac dinh cthh","tim cong thuc","tim cthh","cong thuc tu phan tram","biet phan tram tim cong thuc"],"noi_dung":"Biết phần trăm khối lượng các nguyên tố và khối lượng phân tử, tính được số nguyên tử mỗi nguyên tố.","cong_thuc":"x = KLPT × %A / KLNT(A)","y":["Tính khối lượng của mỗi nguyên tố trong phân tử: KLPT × %.","Chia cho khối lượng nguyên tử để được số nguyên tử, rồi viết công thức."],"bang":null,"bien":[["x","số nguyên tử A trong phân tử",""],["KLPT","khối lượng phân tử","amu"],["%A","phần trăm khối lượng A","%"],["KLNT(A)","khối lượng nguyên tử A","amu"]],"vd":{"de":"Hợp chất gồm Fe và O, có 70% Fe, khối lượng phân tử 160 amu. Tìm công thức.","buoc":["Khối lượng Fe: 160 × 70% = 112 → 112 : 56 = 2","Khối lượng O: 160 − 112 = 48 → 48 : 16 = 3"],"kq":"Fe₂O₃"},"nham":null,"lq":["h7-phan-tram-nguyen-to","h7-cong-thuc-hoa-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-bien-doi-vat-li","mon":"KHTN","khoi":"8","chu_de":"pthh","thu_tu":1,"loai":"ht","ten":"Biến đổi vật lí","ten_khac":["bien doi vat li","bien doi vat ly","hien tuong vat li","hien tuong vat ly","khong tao chat moi","physical change"],"noi_dung":"Sự biến đổi chất mà không tạo thành chất mới, chất vẫn giữ nguyên là chất ban đầu.","cong_thuc":null,"y":["Thường chỉ thay đổi <b>thể</b> (rắn, lỏng, khí), hình dạng hoặc kích thước.","Ví dụ: nước đá tan chảy, cồn bay hơi, hòa tan đường vào nước, cắt dây đồng.","Nhiều trường hợp thu lại được chất ban đầu, ví dụ cô cạn nước muối thu lại muối ăn."],"bang":null,"bien":null,"vd":{"de":"Hòa tan muối ăn vào nước rồi đun cho nước bay hơi hết, thu lại đúng muối ăn ban đầu. Đây có phải biến đổi hóa học không?","buoc":["Muối tan rồi lại thu được đúng muối ban đầu, không sinh chất mới","Chỉ thay đổi trạng thái, không tạo chất mới"],"kq":"Không, đây là biến đổi vật lí vì không tạo ra chất mới."},"nham":["Hòa tan muối ăn vào nước là biến đổi vật lí, không phải phản ứng hóa học."],"lq":["h8-bien-doi-hoa-hoc","h8-phan-ung-hoa-hoc","h8-dung-dich"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-bien-doi-hoa-hoc","mon":"KHTN","khoi":"8","chu_de":"pthh","thu_tu":2,"loai":"ht","ten":"Biến đổi hóa học","ten_khac":["bien doi hoa hoc","hien tuong hoa hoc","tao chat moi","chemical change","bien doi hh"],"noi_dung":"Sự biến đổi chất có tạo thành chất mới, khác chất ban đầu.","cong_thuc":null,"y":["Biến đổi hóa học chính là xảy ra <b>phản ứng hóa học</b>.","Ví dụ: đốt cháy than, sắt bị gỉ, nung đá vôi thành vôi sống, thức ăn bị ôi thiu.","Nhận ra qua <b>dấu hiệu</b>: đổi màu, có chất khí, có kết tủa, tỏa nhiệt, phát sáng."],"bang":null,"bien":null,"vd":{"de":"Để một miếng gang ngoài trời ẩm một thời gian, thấy xuất hiện lớp gỉ màu nâu đỏ khác hẳn màu xám của gang. Đây là biến đổi gì?","buoc":["Lớp gỉ là chất mới, khác thành phần với gang ban đầu","Có sự tạo thành chất mới nên đây là biến đổi hóa học"],"kq":"Đây là biến đổi hóa học, gang bị gỉ và tạo chất mới."},"nham":["Đun đường: đường nóng chảy là biến đổi vật lí; đường cháy thành chất màu đen là biến đổi hóa học."],"lq":["h8-bien-doi-vat-li","h8-phan-ung-hoa-hoc","h8-dau-hieu-phan-ung"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-phan-ung-hoa-hoc","mon":"KHTN","khoi":"8","chu_de":"pthh","thu_tu":3,"loai":"kn","ten":"Phản ứng hóa học","ten_khac":["phan ung hoa hoc","pu hoa hoc","puhh","phan ung","chemical reaction","dien bien phan ung"],"noi_dung":"Quá trình biến đổi từ chất này (chất phản ứng) thành chất khác (sản phẩm).","cong_thuc":null,"y":["Ghi bằng lời: <b>chất phản ứng → sản phẩm</b>. Ví dụ: carbon + oxygen → carbon dioxide.","Trong phản ứng, <b>liên kết giữa các nguyên tử thay đổi</b>, phân tử này biến đổi thành phân tử khác.","Số nguyên tử của mỗi nguyên tố được <b>giữ nguyên</b> trước và sau phản ứng.","Trong quá trình phản ứng, lượng chất phản ứng giảm dần, lượng sản phẩm tăng dần."],"bang":null,"bien":null,"vd":{"de":"Đốt cháy carbon trong khí oxygen thu được khí carbon dioxide. Hãy chỉ ra chất phản ứng và sản phẩm.","buoc":["Chất ban đầu bị biến đổi là carbon và oxygen","Chất mới sinh ra là carbon dioxide"],"kq":"Chất phản ứng: carbon và oxygen; sản phẩm: carbon dioxide."},"nham":null,"lq":["h8-chat-phan-ung","h8-san-pham","h8-dau-hieu-phan-ung","h8-phuong-trinh-hoa-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-chat-phan-ung","mon":"KHTN","khoi":"8","chu_de":"pthh","thu_tu":4,"loai":"kn","ten":"Chất phản ứng","ten_khac":["chat phan ung","chat tham gia","chat tham gia phan ung","chat ban dau","reactant"],"noi_dung":"Chất ban đầu bị biến đổi trong phản ứng hóa học, còn gọi là chất tham gia.","cong_thuc":null,"y":["Viết ở <b>bên trái</b> mũi tên trong phương trình hóa học.","Lượng chất phản ứng <b>giảm dần</b> trong quá trình phản ứng.","Ví dụ: Zn + 2HCl → ZnCl₂ + H₂, chất phản ứng là Zn và HCl."],"bang":null,"bien":null,"vd":{"de":"Trong phản ứng Zn + 2HCl → ZnCl₂ + H₂, đâu là các chất phản ứng?","buoc":["Chất phản ứng nằm ở bên trái mũi tên","Đó là Zn và HCl"],"kq":"Chất phản ứng là Zn và HCl, lượng của chúng giảm dần."},"nham":null,"lq":["h8-san-pham","h8-phan-ung-hoa-hoc","h8-phuong-trinh-hoa-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-san-pham","mon":"KHTN","khoi":"8","chu_de":"pthh","thu_tu":5,"loai":"kn","ten":"Sản phẩm","ten_khac":["san pham","chat san pham","chat tao thanh","chat moi","san pham phan ung","product"],"noi_dung":"Chất mới được tạo thành sau phản ứng hóa học, còn gọi là chất tạo thành.","cong_thuc":null,"y":["Viết ở <b>bên phải</b> mũi tên trong phương trình hóa học.","Lượng sản phẩm <b>tăng dần</b> trong quá trình phản ứng.","Ví dụ: nung đá vôi CaCO₃ → CaO + CO₂, sản phẩm là CaO và CO₂."],"bang":null,"bien":null,"vd":{"de":"Trong phản ứng CaCO₃ → CaO + CO₂ khi nung đá vôi, đâu là sản phẩm?","buoc":["Sản phẩm nằm ở bên phải mũi tên","Đó là CaO và CO₂"],"kq":"Sản phẩm là CaO (vôi sống) và CO₂, lượng của chúng tăng dần."},"nham":null,"lq":["h8-chat-phan-ung","h8-phan-ung-hoa-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-dau-hieu-phan-ung","mon":"KHTN","khoi":"8","chu_de":"pthh","thu_tu":6,"loai":"kn","ten":"Dấu hiệu phản ứng hóa học","ten_khac":["dau hieu phan ung","dau hieu nhan biet phan ung","co phan ung xay ra","sui bot","doi mau","ket tua","toa nhiet","phat sang"],"noi_dung":"Những biến đổi quan sát được cho biết có chất mới tạo thành, tức là đã xảy ra phản ứng.","cong_thuc":null,"y":["Có <b>chất khí</b> thoát ra (sủi bọt), ví dụ nhỏ hydrochloric acid vào đá vôi.","Có <b>chất kết tủa</b> (chất rắn không tan) xuất hiện trong dung dịch.","Có sự <b>thay đổi màu sắc</b>, mùi.","Có sự <b>tỏa nhiệt</b> hoặc <b>phát sáng</b>, ví dụ đốt cháy than, nến."],"bang":null,"bien":null,"vd":{"de":"Nhỏ dung dịch hydrochloric acid vào cục đá vôi thấy có bọt khí thoát ra mạnh. Đây có phải dấu hiệu của phản ứng hóa học không?","buoc":["Xuất hiện chất khí thoát ra (sủi bọt) là dấu hiệu chất mới đã hình thành","Đây là dấu hiệu điển hình cho biết đã có phản ứng xảy ra"],"kq":"Có, sự sủi bọt khí là dấu hiệu đã xảy ra phản ứng hóa học."},"nham":["Không phải cứ sủi bọt là có phản ứng: nước sôi sủi bọt là biến đổi vật lí."],"lq":["h8-bien-doi-hoa-hoc","h8-ket-tua"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-phan-ung-toa-nhiet","mon":"KHTN","khoi":"8","chu_de":"pthh","thu_tu":7,"loai":"ht","ten":"Phản ứng tỏa nhiệt","ten_khac":["phan ung toa nhiet","toa nhiet","giai phong nhiet","exothermic","dot chay nhien lieu"],"noi_dung":"Phản ứng giải phóng năng lượng dưới dạng nhiệt ra môi trường xung quanh.","cong_thuc":null,"y":["Ví dụ: <b>đốt cháy</b> than, xăng, gas, cồn; vôi sống (CaO) tác dụng với nước.","Nhiều phản ứng đốt cháy chỉ cần đun nóng lúc đầu, sau đó tự tiếp diễn.","Ứng dụng: đốt nhiên liệu để đun nấu, sưởi ấm, chạy động cơ, sản xuất điện."],"bang":null,"bien":null,"vd":{"de":"Khi cho vôi sống CaO vào nước, thấy hỗn hợp nóng lên rõ rệt. Đây là phản ứng tỏa nhiệt hay thu nhiệt?","buoc":["Nhiệt độ hỗn hợp tăng lên nghĩa là năng lượng được giải phóng ra môi trường","Đây chính là đặc điểm của phản ứng tỏa nhiệt"],"kq":"Đây là phản ứng tỏa nhiệt."},"nham":["Hơi nước ngưng tụ cũng tỏa nhiệt nhưng là biến đổi vật lí, không phải phản ứng hóa học."],"lq":["h8-phan-ung-thu-nhiet","h8-phan-ung-hoa-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-phan-ung-thu-nhiet","mon":"KHTN","khoi":"8","chu_de":"pthh","thu_tu":8,"loai":"ht","ten":"Phản ứng thu nhiệt","ten_khac":["phan ung thu nhiet","thu nhiet","nhan nhiet","endothermic","dun nong lien tuc"],"noi_dung":"Phản ứng nhận năng lượng dưới dạng nhiệt từ môi trường xung quanh.","cong_thuc":null,"y":["Thường phải <b>cung cấp nhiệt liên tục</b>; ngừng đun thì phản ứng dừng lại.","Ví dụ: <b>nung đá vôi</b> CaCO₃ → CaO + CO₂ (phải nung liên tục ở nhiệt độ cao).","Ngược với phản ứng tỏa nhiệt (giải phóng nhiệt ra môi trường)."],"bang":null,"bien":null,"vd":{"de":"Muốn phản ứng nung đá vôi CaCO₃ → CaO + CO₂ tiếp diễn, có cần đun liên tục không, vì sao?","buoc":["Phản ứng này cần nhận nhiệt liên tục từ môi trường","Ngừng đun thì phản ứng dừng lại"],"kq":"Có, vì đây là phản ứng thu nhiệt, phải cung cấp nhiệt liên tục."},"nham":null,"lq":["h8-phan-ung-toa-nhiet","h8-phan-ung-hoa-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-phuong-trinh-hoa-hoc","mon":"KHTN","khoi":"8","chu_de":"pthh","thu_tu":9,"loai":"kn","ten":"Phương trình hóa học","ten_khac":["phuong trinh hoa hoc","pthh","pt hoa hoc","can bang phuong trinh","he so","y nghia pthh","chemical equation"],"noi_dung":"Cách biểu diễn phản ứng hóa học bằng công thức hóa học của các chất kèm hệ số thích hợp.","cong_thuc":null,"y":["Gồm công thức chất phản ứng, mũi tên (→), công thức sản phẩm; <b>hệ số</b> đặt trước công thức.","Hệ số được chọn để <b>số nguyên tử mỗi nguyên tố ở hai vế bằng nhau</b>.","Cho biết <b>tỉ lệ số nguyên tử, số phân tử</b> (cũng là tỉ lệ số mol) giữa các chất.","Lập theo 3 bước: viết sơ đồ phản ứng → cân bằng số nguyên tử → viết phương trình."],"bang":[["Phương trình","Tỉ lệ"],["2H₂ + O₂ → 2H₂O","2 : 1 : 2"],["CaCO₃ → CaO + CO₂","1 : 1 : 1"]],"bien":null,"vd":{"de":"Vì sao phương trình Zn + 2HCl → ZnCl₂ + H₂ cần hệ số 2 trước HCl mà không phải hệ số 1?","buoc":["Đếm số nguyên tử Cl bên phải, ZnCl₂ có 2 Cl","Bên trái cần 2 phân tử HCl mới đủ 2 Cl, đồng thời đủ 2 H tạo H₂"],"kq":"Hệ số 2 trước HCl để số nguyên tử Cl và H ở hai vế bằng nhau."},"nham":["Không được sửa chỉ số trong công thức (O₂ thành O) để cân bằng, chỉ được thêm hệ số.","Hệ số 1 không cần viết."],"lq":["h8-phan-ung-hoa-hoc","h8-tinh-theo-pthh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-tinh-theo-pthh","mon":"KHTN","khoi":"8","chu_de":"pthh","thu_tu":10,"loai":"ct","ten":"Tính theo phương trình hóa học","ten_khac":["tinh theo phuong trinh","tinh theo pthh","bai toan pthh","tinh luong chat","ti le mol","tinh khoi luong san pham"],"noi_dung":"Dùng tỉ lệ số mol trong phương trình hóa học để tính lượng chất phản ứng hoặc sản phẩm.","cong_thuc":"n = m/M; V = n × 24,79","y":["Bước 1: đổi lượng chất đề cho ra <b>số mol</b>.","Bước 2: viết phương trình hóa học đã cân bằng.","Bước 3: theo <b>tỉ lệ hệ số</b>, tìm số mol chất cần tính.","Bước 4: đổi số mol ra khối lượng (m = n × M) hoặc thể tích khí (V = n × 24,79)."],"bang":null,"bien":[["n","số mol","mol"],["m","khối lượng","g"],["M","khối lượng mol","g/mol"],["V","thể tích khí ở đkc","L"]],"vd":{"de":"Cho 6,5 g Zn tác dụng hết với hydrochloric acid. Tính thể tích khí H₂ thu được ở đkc (Zn = 65).","buoc":["n(Zn) = 6,5 : 65 = 0,1 mol","Zn + 2HCl → ZnCl₂ + H₂","Tỉ lệ Zn : H₂ = 1 : 1 nên n(H₂) = 0,1 mol","V(H₂) = 0,1 × 24,79"],"kq":"V(H₂) = 2,479 L"},"nham":["Dùng tỉ lệ hệ số cho khối lượng; phải đổi ra số mol rồi mới dùng tỉ lệ."],"lq":["h8-phuong-trinh-hoa-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-toc-do-phan-ung","mon":"KHTN","khoi":"8","chu_de":"pthh","thu_tu":11,"loai":"dl","ten":"Tốc độ phản ứng","ten_khac":["toc do phan ung","toc do pu","phan ung nhanh","phan ung cham","yeu to anh huong toc do","reaction rate"],"noi_dung":"Đại lượng đặc trưng cho sự nhanh hay chậm của một phản ứng hóa học.","cong_thuc":null,"y":["Phản ứng nhanh: đốt cháy cồn, pháo nổ. Phản ứng chậm: sắt bị gỉ, lên men.","<b>Tăng nồng độ</b> chất phản ứng → phản ứng xảy ra nhanh hơn.","<b>Tăng nhiệt độ</b> → phản ứng nhanh hơn; vì thế thực phẩm để tủ lạnh lâu hỏng hơn.","<b>Tăng diện tích bề mặt tiếp xúc</b> (đập nhỏ chất rắn) hoặc dùng <b>chất xúc tác</b> → phản ứng nhanh hơn."],"bang":[["Yếu tố","Cách làm phản ứng nhanh hơn"],["Nồng độ","tăng nồng độ"],["Nhiệt độ","tăng nhiệt độ"],["Diện tích bề mặt","chia nhỏ chất rắn"],["Chất xúc tác","thêm chất xúc tác"]],"bien":null,"vd":{"de":"Vì sao khi bảo quản thịt, cá người ta thường để trong tủ lạnh thay vì để ở nhiệt độ phòng?","buoc":["Nhiệt độ thấp làm giảm tốc độ các phản ứng phân hủy trong thực phẩm","Phản ứng làm hỏng thực phẩm xảy ra chậm hơn khi nhiệt độ giảm"],"kq":"Để trong tủ lạnh làm chậm tốc độ phản ứng, thực phẩm lâu hỏng hơn."},"nham":null,"lq":["h8-chat-xuc-tac","h8-phan-ung-hoa-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-chat-xuc-tac","mon":"KHTN","khoi":"8","chu_de":"pthh","thu_tu":12,"loai":"ch","ten":"Chất xúc tác","ten_khac":["chat xuc tac","xuc tac","catalyst","enzyme","men","mno2"],"noi_dung":"Chất làm tăng tốc độ phản ứng nhưng vẫn giữ nguyên về lượng và chất sau phản ứng.","cong_thuc":null,"y":["Ví dụ: manganese dioxide (MnO₂) làm hydrogen peroxide (H₂O₂) phân hủy nhanh, giải phóng oxygen.","<b>Enzyme</b> là chất xúc tác trong cơ thể sống, ví dụ enzyme trong nước bọt giúp tiêu hóa tinh bột.","Làm rượu, sữa chua, tương là nhờ <b>enzyme của vi sinh vật</b> (nấm men, vi khuẩn) xúc tác."],"bang":null,"bien":null,"vd":{"de":"Cho một ít bột manganese dioxide MnO₂ vào dung dịch hydrogen peroxide H₂O₂, thấy khí thoát ra nhanh hơn hẳn so với để yên. Vai trò của MnO₂ là gì?","buoc":["MnO₂ làm phản ứng phân hủy H₂O₂ xảy ra nhanh hơn","Sau phản ứng, lượng và bản chất MnO₂ không đổi"],"kq":"MnO₂ đóng vai trò chất xúc tác, làm tăng tốc độ phản ứng."},"nham":["Chất xúc tác không phải chất phản ứng; thường ghi trên mũi tên, không viết vào hai vế."],"lq":["h8-toc-do-phan-ung","h8-phan-ung-hoa-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-mol","mon":"KHTN","khoi":"8","chu_de":"mol","thu_tu":1,"loai":"dl","ten":"Mol","ten_khac":["mol","so mol","luong chat","mole","don vi mol","6,022","6.022"],"noi_dung":"Lượng chất có chứa N_A (6,022 × 10²³) nguyên tử hoặc phân tử của chất đó.","cong_thuc":"N = n × N_A","y":["Mol là đơn vị đo <b>lượng chất</b>; số mol kí hiệu là <b>n</b>.","1 mol nguyên tử Fe chứa 6,022 × 10²³ nguyên tử Fe; 1 mol phân tử H₂O chứa 6,022 × 10²³ phân tử H₂O.","Phải nói rõ mol <b>nguyên tử</b> hay mol <b>phân tử</b>: 1 mol H khác 1 mol H₂."],"bang":null,"bien":[["N","số nguyên tử hoặc phân tử","hạt"],["n","số mol","mol"],["N_A","số Avogadro","6,022 × 10²³"]],"vd":{"de":"0,5 mol phân tử CO₂ chứa bao nhiêu phân tử?","buoc":["N = n × N_A = 0,5 × 6,022 × 10²³"],"kq":"N = 3,011 × 10²³ phân tử"},"nham":null,"lq":["h8-khoi-luong-mol","h8-the-tich-mol-khi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-khoi-luong-mol","mon":"KHTN","khoi":"8","chu_de":"mol","thu_tu":2,"loai":"dl","ten":"Khối lượng mol","ten_khac":["khoi luong mol","g/mol","khoi luong mol phan tu","khoi luong mol nguyen tu","kl mol","molar mass","m = m/n"],"noi_dung":"Khối lượng của N_A nguyên tử hoặc phân tử chất đó, tính bằng gam, kí hiệu M.","cong_thuc":"M = m/n","y":["Khối lượng mol (g/mol) có <b>trị số bằng</b> khối lượng nguyên tử hoặc phân tử (amu) của chất đó.","Khối lượng mol phân tử = tổng khối lượng mol các nguyên tử trong phân tử.","Suy ra: <b>n = m/M</b> và <b>m = n × M</b>."],"bang":null,"bien":[["M","khối lượng mol","g/mol"],["m","khối lượng chất","g"],["n","số mol","mol"]],"vd":{"de":"Tính khối lượng mol của sulfuric acid H₂SO₄ (H = 1, S = 32, O = 16).","buoc":["M = 2 × 1 + 32 + 4 × 16"],"kq":"M = 98 g/mol"},"nham":["Nhầm đơn vị: khối lượng phân tử tính bằng amu, khối lượng mol tính bằng g/mol."],"lq":["h8-mol"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-the-tich-mol-khi","mon":"KHTN","khoi":"8","chu_de":"mol","thu_tu":3,"loai":"dl","ten":"Thể tích mol chất khí","ten_khac":["the tich mol","the tich mol khi","24,79","24.79","dkc","dieu kien chuan","v = n x 24,79","molar volume"],"noi_dung":"Thể tích chiếm bởi N_A phân tử chất khí; ở đkc (25 °C, 1 bar) bằng 24,79 L.","cong_thuc":"V = n × 24,79","y":["Ở cùng nhiệt độ và áp suất, 1 mol <b>mọi chất khí</b> đều chiếm thể tích bằng nhau.","<b>Điều kiện chuẩn (đkc)</b>: nhiệt độ 25 °C, áp suất 1 bar.","Suy ra số mol khí: <b>n = V : 24,79</b>."],"bang":null,"bien":[["V","thể tích khí ở đkc","L"],["n","số mol khí","mol"],["24,79","thể tích mol khí ở đkc","L/mol"]],"vd":{"de":"Tính số mol của 4,958 L khí O₂ ở đkc.","buoc":["n = V : 24,79 = 4,958 : 24,79"],"kq":"n = 0,2 mol"},"nham":["Dùng 22,4 L là số liệu ở điều kiện tiêu chuẩn cũ (0 °C, 1 atm); SGK KNTT 8 dùng 24,79 L ở đkc.","Chỉ dùng cho chất khí, không dùng cho chất lỏng, chất rắn."],"lq":["h8-mol"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-dung-dich","mon":"KHTN","khoi":"8","chu_de":"dung-dich","thu_tu":1,"loai":"kn","ten":"Dung dịch","ten_khac":["dung dich","dd","hon hop dong nhat","dung dich la gi","solution"],"noi_dung":"Hỗn hợp đồng nhất của chất tan và dung môi.","cong_thuc":null,"y":["Ví dụ: nước muối (muối ăn tan trong nước), nước đường, giấm ăn.","Dung dịch <b>đồng nhất</b>: mọi phần có thành phần như nhau, không nhìn thấy chất tan.","Khối lượng dung dịch = khối lượng chất tan + khối lượng dung môi."],"bang":null,"bien":null,"vd":null,"nham":["Dầu ăn trộn nước, nước lẫn cát là hỗn hợp không đồng nhất, không phải dung dịch."],"lq":["h8-chat-tan","h8-dung-moi","h8-khoi-luong-dung-dich"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-dung-moi","mon":"KHTN","khoi":"8","chu_de":"dung-dich","thu_tu":2,"loai":"kn","ten":"Dung môi","ten_khac":["dung moi","solvent","nuoc la dung moi","mdm","chat hoa tan chat khac"],"noi_dung":"Chất có khả năng hòa tan chất khác để tạo thành dung dịch.","cong_thuc":null,"y":["<b>Nước</b> là dung môi phổ biến nhất, hòa tan được nhiều chất.","Ngoài nước còn có xăng, cồn, dầu hỏa…; ví dụ xăng hòa tan được dầu ăn còn nước thì không.","Một chất có thể tan tốt trong dung môi này nhưng không tan trong dung môi khác."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h8-chat-tan","h8-dung-dich"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-chat-tan","mon":"KHTN","khoi":"8","chu_de":"dung-dich","thu_tu":3,"loai":"kn","ten":"Chất tan","ten_khac":["chat tan","solute","chat bi hoa tan","mct","khoi luong chat tan"],"noi_dung":"Chất bị hòa tan trong dung môi; có thể là chất rắn, chất lỏng hoặc chất khí.","cong_thuc":null,"y":["Ví dụ: muối ăn, đường (rắn); cồn (lỏng); khí carbon dioxide trong nước ngọt có gas (khí).","Có chất <b>tan tốt</b>, chất <b>ít tan</b> và chất <b>không tan</b> trong nước.","Lượng chất tan tối đa trong 100 g nước ở một nhiệt độ được đo bằng <b>độ tan</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h8-dung-moi","h8-dung-dich","h8-tinh-tan-muoi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-dung-dich-bao-hoa","mon":"KHTN","khoi":"8","chu_de":"dung-dich","thu_tu":4,"loai":"kn","ten":"Dung dịch bão hòa","ten_khac":["dung dich bao hoa","bao hoa","dd bao hoa","khong tan them","saturated solution"],"noi_dung":"Dung dịch không thể hòa tan thêm chất tan ở nhiệt độ và áp suất xác định.","cong_thuc":null,"y":["Cho thêm chất tan thì phần thêm vào <b>không tan nữa</b>, lắng xuống đáy.","Khối lượng chất tan trong dung dịch bão hòa ứng với 100 g nước chính là <b>độ tan</b>.","Thay đổi nhiệt độ có thể làm dung dịch bão hòa thành chưa bão hòa và ngược lại."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h8-dung-dich-chua-bao-hoa","h8-dung-dich"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-dung-dich-chua-bao-hoa","mon":"KHTN","khoi":"8","chu_de":"dung-dich","thu_tu":5,"loai":"kn","ten":"Dung dịch chưa bão hòa","ten_khac":["dung dich chua bao hoa","chua bao hoa","dd chua bao hoa","con tan them","unsaturated solution"],"noi_dung":"Dung dịch vẫn có thể hòa tan thêm chất tan ở nhiệt độ và áp suất xác định.","cong_thuc":null,"y":["Cho thêm chất tan vào và khuấy thì chất tan <b>tiếp tục tan</b>.","Hòa tan thêm đến khi không tan được nữa thì thu được dung dịch <b>bão hòa</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h8-dung-dich-bao-hoa","h8-dung-dich"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-khoi-luong-dung-dich","mon":"KHTN","khoi":"8","chu_de":"dung-dich","thu_tu":6,"loai":"dl","ten":"Khối lượng dung dịch","ten_khac":["khoi luong dung dich","mdd","m dung dich","mdd = mct + mdm","khoi luong dung moi","mdm"],"noi_dung":"Tổng khối lượng của chất tan và dung môi có trong dung dịch.","cong_thuc":"mdd = mct + mdm","y":["Dùng khi tính <b>nồng độ phần trăm</b> và khi pha chế dung dịch.","Với nước: 1 mL nước có khối lượng khoảng 1 g.","Biết thể tích V (mL) và khối lượng riêng D (g/mL) của dung dịch: mdd = D × V."],"bang":null,"bien":[["mdd","khối lượng dung dịch","g"],["mct","khối lượng chất tan","g"],["mdm","khối lượng dung môi","g"]],"vd":{"de":"Hòa tan 20 g đường vào 180 g nước. Tính khối lượng dung dịch nước đường.","buoc":["mdd = mct + mdm = 20 + 180"],"kq":"mdd = 200 g"},"nham":["Lấy khối lượng nước làm khối lượng dung dịch (quên cộng chất tan)."],"lq":["h8-dung-dich","h8-pha-che-dung-dich"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-pha-che-dung-dich","mon":"KHTN","khoi":"8","chu_de":"dung-dich","thu_tu":7,"loai":"tn","ten":"Pha chế dung dịch","ten_khac":["pha che dung dich","pha dung dich","pha che","cach pha dung dich","pha theo nong do"],"noi_dung":"Tính lượng chất tan, dung môi cần dùng rồi cân, đong, hòa tan để được dung dịch có nồng độ mong muốn.","cong_thuc":null,"y":["<b>Bước 1 – Tính toán</b>: khối lượng chất tan và khối lượng (hoặc thể tích) dung môi cần lấy.","<b>Bước 2 – Cân</b> chất tan cho vào cốc; <b>đong</b> dung môi (nước).","<b>Bước 3 – Hòa tan</b>: đổ dung môi vào cốc, khuấy đều đến khi chất tan tan hết.","Pha theo nồng độ mol: cho chất tan vào bình, thêm nước đến đúng thể tích dung dịch cần pha."],"bang":null,"bien":null,"vd":{"de":"Pha chế 50 g dung dịch NaCl 10%.","buoc":["mct = 50 × 10 : 100 = 5 g NaCl","mdm = 50 − 5 = 45 g nước (khoảng 45 mL)","Cân 5 g NaCl cho vào cốc, đổ 45 mL nước, khuấy tan"],"kq":"Được 50 g dung dịch NaCl 10%"},"nham":["Pha 100 mL dung dịch theo nồng độ mol: không đong sẵn 100 mL nước, mà thêm nước đến khi dung dịch đủ 100 mL."],"lq":["h8-khoi-luong-dung-dich"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-acid","mon":"KHTN","khoi":"8","chu_de":"acid","thu_tu":1,"loai":"kn","ten":"Acid","ten_khac":["acid","axit","acid la gi","axit la gi","ion h+","h+","goc acid"],"noi_dung":"Hợp chất trong phân tử có nguyên tử hydrogen liên kết với gốc acid; khi tan trong nước tạo ra ion H⁺.","cong_thuc":null,"y":["Ví dụ: HCl (hydrochloric acid), H₂SO₄ (sulfuric acid), HNO₃ (nitric acid), CH₃COOH (acetic acid).","Làm <b>quỳ tím hóa đỏ</b>; dung dịch acid có <b>pH nhỏ hơn 7</b>.","Tác dụng với nhiều kim loại (Mg, Zn, Fe, Al…) tạo muối và giải phóng khí <b>hydrogen</b>.","Tác dụng với base, oxide base, một số muối."],"bang":null,"bien":null,"vd":{"de":"Nhỏ một dung dịch X vào giấy quỳ tím thấy quỳ chuyển đỏ, đo được pH bằng 3. Dung dịch X có thể thuộc loại chất gì?","buoc":["Quỳ tím hóa đỏ là dấu hiệu của môi trường acid","pH bằng 3 nhỏ hơn 7, phù hợp với môi trường acid"],"kq":"Dung dịch X là một dung dịch acid."},"nham":["Không phải chất nào có H cũng là acid: H₂O, CH₄, NaOH không phải acid.","Cu, Ag không tác dụng với HCl, H₂SO₄ loãng."],"lq":["h8-hydrochloric-acid","h8-sulfuric-acid","h8-thang-ph"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-hydrochloric-acid","mon":"KHTN","khoi":"8","chu_de":"acid","thu_tu":2,"loai":"ch","ten":"Hydrochloric acid","ten_khac":["hydrochloric acid","hcl","axit clohidric","axit clohydric","acid clohydric","hydrogen chloride"],"noi_dung":"Dung dịch của khí hydrogen chloride (HCl) trong nước, là acid thường dùng trong phòng thí nghiệm.","cong_thuc":null,"y":["Có trong <b>dịch vị dạ dày</b> người và động vật, giúp tiêu hóa thức ăn.","Tác dụng với kim loại: Fe + 2HCl → FeCl₂ + H₂↑.","Dùng để tẩy gỉ bề mặt kim loại, sản xuất muối chloride và nhiều hóa chất khác."],"bang":null,"bien":null,"vd":{"de":"Cho một đinh sắt vào dung dịch hydrochloric acid dư. Viết phương trình phản ứng xảy ra.","buoc":["Sắt tác dụng với acid tạo muối iron(II) chloride và giải phóng khí hydrogen","Cân bằng số nguyên tử Cl bằng cách dùng 2HCl"],"kq":"Fe + 2HCl → FeCl₂ + H₂↑"},"nham":["Fe tác dụng với HCl tạo FeCl₂ (iron(II) chloride), không tạo FeCl₃."],"lq":["h8-acid"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-sulfuric-acid","mon":"KHTN","khoi":"8","chu_de":"acid","thu_tu":3,"loai":"ch","ten":"Sulfuric acid","ten_khac":["sulfuric acid","h2so4","axit sunfuric","axit sulfuric","acid sulfuric","pha loang h2so4","h2so4 dac"],"noi_dung":"Acid H₂SO₄, chất lỏng sánh, không màu, không bay hơi, tan nhiều trong nước và tỏa rất nhiều nhiệt.","cong_thuc":null,"y":["<b>Pha loãng</b>: rót <b>từ từ acid vào nước</b> và khuấy đều, tuyệt đối không làm ngược lại.","H₂SO₄ đặc gây <b>bỏng rất nặng</b> khi dính vào da.","Dung dịch loãng tác dụng với kim loại: Zn + H₂SO₄ → ZnSO₄ + H₂↑.","Là hóa chất quan trọng: sản xuất phân bón, chất tẩy rửa, dung dịch acid trong ắc quy…"],"bang":null,"bien":null,"vd":{"de":"Vì sao khi pha loãng sulfuric acid đặc, phải rót từ từ acid vào nước mà không được làm ngược lại?","buoc":["H₂SO₄ đặc tan trong nước tỏa rất nhiều nhiệt","Nếu đổ nước vào acid, nhiệt tỏa ra đột ngột có thể làm acid bắn ra ngoài, gây bỏng"],"kq":"Phải rót từ từ acid vào nước và khuấy đều để đảm bảo an toàn."},"nham":["Rót nước vào acid đặc làm nước sôi đột ngột, bắn acid ra ngoài, rất nguy hiểm."],"lq":["h8-acid","h8-an-toan-acid-base"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-acetic-acid","mon":"KHTN","khoi":"8","chu_de":"acid","thu_tu":4,"loai":"ch","ten":"Acetic acid","ten_khac":["acetic acid","ch3cooh","axit axetic","acid axetic","giam an","giam"],"noi_dung":"Acid CH₃COOH, có trong giấm ăn, gây vị chua.","cong_thuc":null,"y":["<b>Giấm ăn</b> là dung dịch acetic acid loãng (khoảng 2–5%).","Làm quỳ tím hóa đỏ; dùng làm gia vị, muối dưa, ngâm chua thực phẩm.","Giấm tác dụng với đá vôi, vỏ trứng (chứa calcium carbonate) tạo bọt khí carbon dioxide."],"bang":null,"bien":null,"vd":{"de":"Nhỏ giấm ăn vào vỏ trứng chứa calcium carbonate thấy có bọt khí thoát ra. Giải thích hiện tượng.","buoc":["Giấm là dung dịch acetic acid loãng, có tính acid","Acid tác dụng với calcium carbonate sinh ra khí carbon dioxide"],"kq":"Bọt khí là CO₂ sinh ra khi acetic acid phản ứng với calcium carbonate trong vỏ trứng."},"nham":null,"lq":["h8-acid","h8-thang-ph"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-an-toan-acid-base","mon":"KHTN","khoi":"8","chu_de":"acid","thu_tu":5,"loai":"ud","ten":"An toàn khi dùng acid, base","ten_khac":["an toan hoa chat","an toan acid","an toan base","bong acid","hoa chat an mon","an toan phong thi nghiem"],"noi_dung":"Acid, base đặc có tính ăn mòn, gây bỏng; phải dùng đồ bảo hộ và thao tác đúng cách.","cong_thuc":null,"y":["Đeo <b>kính bảo hộ, găng tay</b>; không nếm, không ngửi trực tiếp hóa chất.","Lấy lượng nhỏ vừa đủ bằng ống hút hoặc thìa; đậy nắp lọ ngay sau khi lấy.","Pha loãng acid đặc: rót từ từ <b>acid vào nước</b>.","Dính acid hoặc base lên da: <b>rửa ngay dưới vòi nước nhiều lần</b> và báo giáo viên."],"bang":null,"bien":null,"vd":{"de":"Không may để một giọt dung dịch sulfuric acid dính vào tay khi làm thí nghiệm. Cần xử lí thế nào ngay?","buoc":["Acid đặc có tính ăn mòn, gây bỏng da nếu để lâu","Cần loại bỏ acid khỏi da càng nhanh càng tốt"],"kq":"Rửa ngay vùng da đó dưới vòi nước sạch nhiều lần và báo giáo viên."},"nham":null,"lq":["h8-sulfuric-acid","h8-sodium-hydroxide","h8-acid","h8-base"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-base","mon":"KHTN","khoi":"8","chu_de":"base","thu_tu":1,"loai":"kn","ten":"Base","ten_khac":["base","bazo","base la gi","bazo la gi","hydroxide","nhom oh","ion oh-","oh-"],"noi_dung":"Hợp chất trong phân tử có nguyên tử kim loại liên kết với nhóm hydroxide (OH); khi tan trong nước tạo ra ion OH⁻.","cong_thuc":null,"y":["Ví dụ: NaOH, KOH, Ca(OH)₂, Ba(OH)₂ (tan); Cu(OH)₂, Fe(OH)₃, Mg(OH)₂ (không tan).","Chia thành <b>base tan (kiềm)</b> và <b>base không tan</b>.","Dung dịch kiềm làm <b>quỳ tím hóa xanh</b>, phenolphthalein hóa hồng; có <b>pH lớn hơn 7</b>.","Base tác dụng với acid tạo muối và nước (phản ứng trung hòa)."],"bang":null,"bien":null,"vd":{"de":"Nhỏ vài giọt phenolphthalein vào dung dịch Y thấy dung dịch chuyển màu hồng. Dung dịch Y có tính chất gì?","buoc":["Phenolphthalein hóa hồng trong môi trường base (kiềm)","Dung dịch trung tính và acid không làm phenolphthalein đổi màu"],"kq":"Dung dịch Y có tính base (kiềm)."},"nham":["Số nhóm OH bằng hóa trị kim loại: Fe(III) → Fe(OH)₃, không viết FeOH₃.","Base không tan không làm đổi màu quỳ tím."],"lq":["h8-kiem","h8-thang-ph"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-kiem","mon":"KHTN","khoi":"8","chu_de":"base","thu_tu":2,"loai":"kn","ten":"Kiềm","ten_khac":["kiem","base tan","bazo tan","dung dich kiem","alkali","naoh","koh"],"noi_dung":"Base tan được trong nước, như NaOH, KOH, Ca(OH)₂, Ba(OH)₂.","cong_thuc":null,"y":["Dung dịch kiềm làm <b>quỳ tím hóa xanh</b>, <b>phenolphthalein</b> không màu hóa <b>hồng</b>.","Có tính ăn mòn: làm bục vải, giấy, gây bỏng da.","Ca(OH)₂ ít tan nhưng dung dịch của nó vẫn là dung dịch kiềm."],"bang":null,"bien":null,"vd":{"de":"Hai dung dịch NaOH và Ca(OH)₂ đều làm quỳ tím hóa xanh. Nhóm chất này được gọi chung là gì?","buoc":["Cả hai đều là base tan được trong nước","Base tan trong nước gọi là kiềm"],"kq":"Cả hai đều là kiềm (base tan)."},"nham":["Kiềm nào cũng là base, nhưng không phải base nào cũng là kiềm (Cu(OH)₂ không tan)."],"lq":["h8-base","h8-sodium-hydroxide","h8-calcium-hydroxide","h8-chat-chi-thi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-sodium-hydroxide","mon":"KHTN","khoi":"8","chu_de":"base","thu_tu":3,"loai":"ch","ten":"Sodium hydroxide","ten_khac":["sodium hydroxide","naoh","natri hidroxit","natri hydroxide","xut","xut an da","caustic soda"],"noi_dung":"Base tan NaOH (xút), chất rắn màu trắng, tan nhiều trong nước và tỏa nhiệt, ăn mòn da.","cong_thuc":null,"y":["Dung dịch NaOH làm quỳ tím hóa xanh, phenolphthalein hóa hồng.","Trung hòa acid: NaOH + HCl → NaCl + H₂O.","Tác dụng với dung dịch CuSO₄ tạo kết tủa Cu(OH)₂ màu xanh lam.","Dùng sản xuất <b>xà phòng</b>, chất tẩy rửa, giấy…"],"bang":null,"bien":null,"vd":{"de":"Nhỏ từ từ dung dịch NaOH vào dung dịch HCl có vài giọt phenolphthalein đang không màu, đến khi dung dịch chuyển hồng nhạt bền màu. Đã xảy ra phản ứng gì?","buoc":["NaOH phản ứng với HCl theo phản ứng trung hòa","Khi acid hết, NaOH dư nhẹ làm phenolphthalein chuyển hồng"],"kq":"Phản ứng trung hòa: NaOH + HCl → NaCl + H₂O."},"nham":null,"lq":["h8-kiem","h8-an-toan-acid-base"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-calcium-hydroxide","mon":"KHTN","khoi":"8","chu_de":"base","thu_tu":4,"loai":"ch","ten":"Calcium hydroxide","ten_khac":["calcium hydroxide","ca(oh)2","caoh2","voi toi","nuoc voi trong","nuoc voi","canxi hidroxit"],"noi_dung":"Base Ca(OH)₂ (vôi tôi), ít tan trong nước; dung dịch trong suốt của nó gọi là nước vôi trong.","cong_thuc":null,"y":["Tạo thành khi cho vôi sống tác dụng với nước: CaO + H₂O → Ca(OH)₂.","Nhận biết khí CO₂: nước vôi trong bị <b>vẩn đục</b> do tạo CaCO₃ không tan.","Dùng khử chua đất trồng, làm vữa xây dựng, xử lí nước thải."],"bang":null,"bien":null,"vd":{"de":"Thổi hơi thở qua ống dẫn vào cốc nước vôi trong, thấy nước vôi bị vẩn đục. Giải thích và viết phương trình.","buoc":["CO₂ trong hơi thở tác dụng với Ca(OH)₂ tạo CaCO₃ không tan","Chất kết tủa trắng làm dung dịch vẩn đục"],"kq":"CO₂ + Ca(OH)₂ → CaCO₃↓ + H₂O, đây là cách nhận biết khí CO₂."},"nham":null,"lq":["h8-kiem"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-chat-chi-thi","mon":"KHTN","khoi":"8","chu_de":"base","thu_tu":5,"loai":"kn","ten":"Chất chỉ thị acid – base","ten_khac":["chat chi thi","chi thi","chi thi mau","chi thi acid base","indicator","doi mau"],"noi_dung":"Chất có màu thay đổi theo môi trường acid hay base, dùng để nhận biết môi trường của dung dịch.","cong_thuc":null,"y":["Hay dùng: <b>giấy quỳ tím</b>, dung dịch <b>phenolphthalein</b>, giấy chỉ thị pH.","Nước ép bắp cải tím, nước nghệ… cũng đổi màu theo môi trường, là chỉ thị tự nhiên.","Muốn biết giá trị pH chính xác hơn thì dùng <b>máy đo pH</b>."],"bang":[["Chỉ thị","Acid","Trung tính","Kiềm"],["Quỳ tím","đỏ","tím","xanh"],["Phenolphthalein","không màu","không màu","hồng"]],"bien":null,"vd":null,"nham":null,"lq":["h8-quy-tim","h8-phenolphthalein","h8-thang-ph"],"hinh":"H-h8-chat-chi-thi","nguon":["KHTN Pocket"]},{"ma":"h8-quy-tim","mon":"KHTN","khoi":"8","chu_de":"base","thu_tu":6,"loai":"tn","ten":"Quỳ tím","ten_khac":["quy tim","giay quy","giay quy tim","quy hoa do","quy hoa xanh","litmus"],"noi_dung":"Giấy chỉ thị màu tím: gặp acid hóa đỏ, gặp dung dịch kiềm hóa xanh.","cong_thuc":null,"y":["Môi trường trung tính (nước cất, dung dịch NaCl): quỳ <b>giữ màu tím</b>.","Cách dùng: dùng đũa thủy tinh chấm dung dịch lên mẩu quỳ, không nhúng quỳ vào lọ hóa chất.","Nhận biết nhanh 3 nhóm: acid, kiềm, dung dịch trung tính."],"bang":null,"bien":null,"vd":{"de":"Có 2 lọ mất nhãn đựng dung dịch HCl và dung dịch NaCl. Làm sao phân biệt nhanh bằng quỳ tím?","buoc":["Nhúng quỳ tím vào từng dung dịch","HCl (acid) làm quỳ hóa đỏ; NaCl (trung tính) không làm đổi màu quỳ"],"kq":"Lọ làm quỳ tím hóa đỏ là HCl, lọ không đổi màu là NaCl."},"nham":["Base không tan (Cu(OH)₂, Fe(OH)₃) không làm quỳ tím đổi màu."],"lq":["h8-chat-chi-thi","h8-phenolphthalein"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-phenolphthalein","mon":"KHTN","khoi":"8","chu_de":"base","thu_tu":7,"loai":"tn","ten":"Phenolphthalein","ten_khac":["phenolphthalein","phenolphtalein","phenolftalein","php","chi thi hong","hoa hong"],"noi_dung":"Chất chỉ thị không màu, hóa hồng trong dung dịch kiềm, không đổi màu trong acid và môi trường trung tính.","cong_thuc":null,"y":["Dùng dạng dung dịch, nhỏ 1–2 giọt vào dung dịch cần thử.","Theo dõi <b>phản ứng trung hòa</b>: dung dịch NaOH có phenolphthalein màu hồng, thêm acid đến dư thì mất màu.","Không phân biệt được acid với dung dịch trung tính (đều không màu)."],"bang":null,"bien":null,"vd":{"de":"Nhỏ phenolphthalein vào 2 dung dịch không màu là NaOH và HCl. Kết quả quan sát được là gì?","buoc":["Phenolphthalein hóa hồng trong môi trường base","Phenolphthalein không đổi màu trong môi trường acid"],"kq":"Dung dịch NaOH chuyển hồng; dung dịch HCl vẫn không màu."},"nham":null,"lq":["h8-chat-chi-thi","h8-quy-tim"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-thang-ph","mon":"KHTN","khoi":"8","chu_de":"base","thu_tu":8,"loai":"dl","ten":"Thang pH","ten_khac":["ph","thang ph","do ph","moi truong trung tinh","giay ph","may do ph","mua acid"],"noi_dung":"Thang số (thường từ 0 đến 14) dùng để biểu thị độ acid hay base của dung dịch.","cong_thuc":null,"y":["<b>pH < 7</b>: môi trường acid; <b>pH = 7</b>: trung tính; <b>pH > 7</b>: môi trường base.","pH càng nhỏ, tính acid càng mạnh; pH càng lớn, tính base càng mạnh.","Xác định pH bằng <b>giấy pH</b> (so màu với bảng màu) hoặc <b>máy đo pH</b>.","Nước mưa có pH nhỏ hơn 5,6 gọi là <b>mưa acid</b>."],"bang":[["Chất","pH (khoảng)"],["Nước chanh","2 – 3"],["Giấm ăn","2 – 3"],["Nước nguyên chất","7"],["Máu người","7,35 – 7,45"],["Nước xà phòng","9 – 10"]],"bien":null,"vd":{"de":"Đo được một dung dịch nước chanh có pH khoảng 3. Dung dịch này có tính acid hay base?","buoc":["pH bằng 3, nhỏ hơn 7","pH nhỏ hơn 7 là môi trường acid, càng nhỏ tính acid càng mạnh"],"kq":"Nước chanh có tính acid khá mạnh vì pH nhỏ."},"nham":["pH càng lớn thì tính acid càng yếu, không phải càng mạnh."],"lq":["h8-chat-chi-thi","h8-acid","h8-base"],"hinh":"H-h8-thang-ph","nguon":["KHTN Pocket"]},{"ma":"h8-oxide","mon":"KHTN","khoi":"8","chu_de":"oxide","thu_tu":1,"loai":"kn","ten":"Oxide","ten_khac":["oxide","oxit","oxide la gi","oxit la gi","ten oxide","mxoy"],"noi_dung":"Hợp chất của hai nguyên tố, trong đó có một nguyên tố là oxygen.","cong_thuc":null,"y":["Ví dụ: CO₂, SO₂, P₂O₅, CaO, CuO, Fe₂O₃. Công thức chung MxOy.","Tên: kim loại (kèm hóa trị nếu nhiều hóa trị) + oxide, ví dụ FeO: iron(II) oxide.","Oxide phi kim dùng tiền tố chỉ số nguyên tử: CO₂ carbon dioxide, SO₃ sulfur trioxide.","Phân loại theo tính chất: oxide base, oxide acid, oxide lưỡng tính, oxide trung tính."],"bang":null,"bien":null,"vd":null,"nham":["NaOH, H₂SO₄ có oxygen nhưng gồm 3 nguyên tố nên không phải oxide."],"lq":["h8-oxide-base","h8-oxide-acid"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-oxide-base","mon":"KHTN","khoi":"8","chu_de":"oxide","thu_tu":2,"loai":"kn","ten":"Oxide base","ten_khac":["oxide base","oxit bazo","oxide bazo","oxit kim loai","cao","cuo","na2o"],"noi_dung":"Oxide tác dụng với dung dịch acid tạo thành muối và nước.","cong_thuc":null,"y":["Thường là oxide của <b>kim loại</b>: CaO, Na₂O, K₂O, BaO, MgO, CuO, Fe₂O₃.","Ví dụ: CuO + 2HCl → CuCl₂ + H₂O.","Một số oxide base (Na₂O, K₂O, CaO, BaO) tác dụng với nước tạo dung dịch kiềm: CaO + H₂O → Ca(OH)₂."],"bang":null,"bien":null,"vd":{"de":"Cho copper(II) oxide CuO màu đen tác dụng với dung dịch hydrochloric acid. Nêu hiện tượng và viết phương trình.","buoc":["CuO là oxide base, tác dụng với acid tạo muối và nước","Muối CuCl₂ tan, có màu xanh lam đặc trưng"],"kq":"CuO + 2HCl → CuCl₂ + H₂O; chất rắn đen tan dần, dung dịch chuyển xanh lam."},"nham":["Không phải oxide kim loại nào cũng là oxide base: Al₂O₃, ZnO là oxide lưỡng tính.","CuO, Fe₂O₃ không tác dụng với nước."],"lq":["h8-oxide","h8-oxide-acid"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-oxide-acid","mon":"KHTN","khoi":"8","chu_de":"oxide","thu_tu":3,"loai":"kn","ten":"Oxide acid","ten_khac":["oxide acid","oxit axit","oxit phi kim","co2","so2","p2o5"],"noi_dung":"Oxide tác dụng với dung dịch base tạo thành muối và nước.","cong_thuc":null,"y":["Thường là oxide của <b>phi kim</b>: CO₂, SO₂, SO₃, P₂O₅.","Ví dụ: CO₂ + Ca(OH)₂ → CaCO₃↓ + H₂O (nước vôi trong vẩn đục).","Nhiều oxide acid tác dụng với nước tạo acid: SO₃ + H₂O → H₂SO₄."],"bang":null,"bien":null,"vd":{"de":"Sục khí CO₂ vào dung dịch nước vôi trong dư. Nêu hiện tượng.","buoc":["CO₂ là oxide acid, tác dụng với dung dịch base Ca(OH)₂","Sản phẩm CaCO₃ không tan, gây vẩn đục"],"kq":"Nước vôi trong hóa vẩn đục do tạo kết tủa trắng CaCO₃."},"nham":["CO, NO là oxide của phi kim nhưng không phải oxide acid (là oxide trung tính)."],"lq":["h8-oxide","h8-oxide-base","h8-oxide-trung-tinh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-oxide-luong-tinh","mon":"KHTN","khoi":"8","chu_de":"oxide","thu_tu":4,"loai":"kn","ten":"Oxide lưỡng tính","ten_khac":["oxide luong tinh","oxit luong tinh","luong tinh","al2o3","zno","amphoteric oxide"],"noi_dung":"Oxide tác dụng được với cả dung dịch acid và dung dịch base, tạo thành muối và nước.","cong_thuc":null,"y":["Ví dụ thường gặp: <b>Al₂O₃</b> (aluminium oxide), <b>ZnO</b> (zinc oxide).","Ví dụ: ZnO + 2HCl → ZnCl₂ + H₂O.","Là oxide của kim loại nhưng không xếp vào oxide base."],"bang":null,"bien":null,"vd":{"de":"Zinc oxide ZnO tác dụng được cả với dung dịch HCl lẫn dung dịch NaOH. Vậy ZnO được xếp vào loại oxide nào?","buoc":["Oxide base chỉ tác dụng với acid; oxide acid chỉ tác dụng với base","ZnO tác dụng được với cả hai loại dung dịch"],"kq":"ZnO là oxide lưỡng tính."},"nham":null,"lq":["h8-oxide","h8-oxide-base"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-oxide-trung-tinh","mon":"KHTN","khoi":"8","chu_de":"oxide","thu_tu":5,"loai":"kn","ten":"Oxide trung tính","ten_khac":["oxide trung tinh","oxit trung tinh","oxide khong tao muoi","oxit khong tao muoi","co","no"],"noi_dung":"Oxide không tác dụng với acid, base và nước.","cong_thuc":null,"y":["Ví dụ: <b>CO</b> (carbon monoxide), <b>NO</b> (nitrogen monoxide).","Còn gọi là oxide không tạo muối.","Carbon monoxide (CO) là khí <b>rất độc</b>, sinh ra khi đốt nhiên liệu thiếu oxygen."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h8-oxide","h8-oxide-acid"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-muoi","mon":"KHTN","khoi":"8","chu_de":"muoi","thu_tu":1,"loai":"kn","ten":"Muối","ten_khac":["muoi","muoi la gi","salt","goc acid","ten muoi","muoi ammonium"],"noi_dung":"Hợp chất tạo ra khi thay thế ion H⁺ của acid bằng ion kim loại hoặc ion ammonium (NH₄⁺).","cong_thuc":null,"y":["Ví dụ: NaCl, CaCO₃, CuSO₄, KNO₃, NH₄Cl.","Tên muối = tên kim loại (kèm hóa trị nếu nhiều hóa trị) + <b>tên gốc acid</b>: FeCl₃ là iron(III) chloride.","Muối tác dụng được với kim loại, acid, base và muối khác (khi đủ điều kiện)."],"bang":[["Acid","Gốc acid","Tên gốc"],["HCl","Cl","chloride"],["H₂SO₄","SO₄","sulfate"],["HNO₃","NO₃","nitrate"],["H₂CO₃","CO₃","carbonate"],["H₃PO₄","PO₄","phosphate"]],"bien":null,"vd":{"de":"Đặt tên cho muối FeCl₃, biết Fe có hóa trị III trong hợp chất này.","buoc":["Tên muối bằng tên kim loại (kèm hóa trị) cộng tên gốc acid","Fe hóa trị III, gốc Cl là chloride"],"kq":"FeCl₃ có tên là iron(III) chloride."},"nham":null,"lq":["h8-tinh-tan-muoi","h8-phan-ung-trao-doi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-tinh-tan-muoi","mon":"KHTN","khoi":"8","chu_de":"muoi","thu_tu":2,"loai":"kn","ten":"Tính tan của muối","ten_khac":["tinh tan","bang tinh tan","muoi tan","muoi khong tan","agcl","baso4","caco3"],"noi_dung":"Muối có thể tan, ít tan hoặc không tan trong nước; tra theo gốc acid và kim loại.","cong_thuc":null,"y":["Muối <b>nitrate</b>, muối của <b>Na, K, ammonium</b>: hầu hết đều tan.","Muối chloride đa số tan, <b>trừ AgCl</b> (kết tủa trắng).","Muối sulfate đa số tan, <b>trừ BaSO₄</b> (kết tủa trắng); CaSO₄ ít tan.","Muối carbonate, phosphate đa số <b>không tan</b>, trừ muối của Na, K, ammonium."],"bang":null,"bien":null,"vd":{"de":"Trộn dung dịch BaCl₂ với dung dịch Na₂SO₄, thấy xuất hiện kết tủa trắng. Kết tủa đó là chất nào, vì sao biết nó không tan?","buoc":["Sản phẩm gồm BaSO₄ và NaCl","Tra tính tan: hầu hết muối sulfate tan, trừ BaSO₄ không tan"],"kq":"Kết tủa trắng là BaSO₄, không tan trong nước."},"nham":null,"lq":["h8-ket-tua","h8-muoi","h8-phan-ung-trao-doi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-phan-ung-trao-doi","mon":"KHTN","khoi":"8","chu_de":"muoi","thu_tu":3,"loai":"ht","ten":"Phản ứng trao đổi","ten_khac":["phan ung trao doi","trao doi","dieu kien phan ung trao doi","muoi + muoi","muoi + base","muoi + acid"],"noi_dung":"Phản ứng trong đó hai hợp chất trao đổi thành phần cấu tạo với nhau, tạo ra hai hợp chất mới.","cong_thuc":null,"y":["Ví dụ: BaCl₂ + Na₂SO₄ → BaSO₄↓ + 2NaCl.","Xảy ra khi sản phẩm có <b>chất kết tủa</b> hoặc <b>chất khí</b> (hoặc nước).","Gặp ở phản ứng muối + acid, muối + base, muối + muối, acid + base (trung hòa)."],"bang":null,"bien":null,"vd":{"de":"Phản ứng BaCl₂ + Na₂SO₄ → BaSO₄↓ + 2NaCl thuộc loại phản ứng gì, vì sao?","buoc":["Hai muối trao đổi thành phần cấu tạo với nhau","Tạo ra chất kết tủa BaSO₄ nên phản ứng xảy ra được"],"kq":"Đây là phản ứng trao đổi."},"nham":["NaCl + KNO₃ không phản ứng vì sản phẩm đều tan, không có chất khí."],"lq":["h8-muoi","h8-ket-tua","h8-tinh-tan-muoi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-sodium-chloride","mon":"KHTN","khoi":"8","chu_de":"muoi","thu_tu":4,"loai":"ch","ten":"Sodium chloride","ten_khac":["sodium chloride","nacl","muoi an","natri clorua","muoi bien"],"noi_dung":"Muối NaCl, thành phần chính của muối ăn, tan tốt trong nước.","cong_thuc":null,"y":["Khai thác từ <b>nước biển</b> (cho nước bay hơi) và từ mỏ muối.","Dung dịch NaCl có môi trường <b>trung tính</b>, không làm đổi màu quỳ tím.","Dùng làm gia vị, bảo quản thực phẩm, nguyên liệu sản xuất NaOH, chlorine…","Nhận biết gốc chloride: nhỏ dung dịch AgNO₃ tạo kết tủa trắng AgCl."],"bang":null,"bien":null,"vd":{"de":"Làm sao nhận biết dung dịch có chứa gốc chloride như trong NaCl?","buoc":["Nhỏ dung dịch AgNO₃ vào mẫu thử","Nếu có kết tủa trắng AgCl xuất hiện thì có gốc chloride"],"kq":"Xuất hiện kết tủa trắng AgCl chứng tỏ dung dịch có gốc chloride."},"nham":null,"lq":["h8-muoi","h8-quy-tim"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-ket-tua","mon":"KHTN","khoi":"8","chu_de":"nhan-biet","thu_tu":1,"loai":"kn","ten":"Kết tủa","ten_khac":["ket tua","chat ket tua","lang xuong","van duc","chat khong tan","precipitate"],"noi_dung":"Chất rắn không tan tạo thành trong dung dịch sau phản ứng, làm dung dịch vẩn đục rồi lắng xuống.","cong_thuc":null,"y":["Trong phương trình, đánh dấu bằng mũi tên xuống <b>↓</b> sau công thức.","Ví dụ: BaSO₄ trắng, AgCl trắng, CaCO₃ trắng, Cu(OH)₂ xanh lam, Fe(OH)₃ nâu đỏ.","Xuất hiện kết tủa là một <b>dấu hiệu</b> có phản ứng hóa học xảy ra."],"bang":null,"bien":null,"vd":{"de":"Trộn dung dịch AgNO₃ với dung dịch NaCl thấy xuất hiện chất rắn màu trắng không tan, lơ lửng rồi lắng dần. Hiện tượng này gọi là gì?","buoc":["Chất rắn mới hình thành, không tan trong dung dịch","Đây gọi là sự tạo thành kết tủa"],"kq":"Đó là kết tủa AgCl, viết trong phương trình kèm dấu mũi tên xuống."},"nham":null,"lq":["h8-tinh-tan-muoi","h8-dau-hieu-phan-ung","h8-nhan-biet-chat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-nhan-biet-chat","mon":"KHTN","khoi":"8","chu_de":"nhan-biet","thu_tu":2,"loai":"tn","ten":"Nhận biết chất","ten_khac":["nhan biet","nhan biet chat","lo mat nhan","mat nhan","phan biet chat","thuoc thu","nhan biet hoa chat"],"noi_dung":"Dùng thuốc thử gây hiện tượng dễ quan sát (đổi màu, kết tủa, chất khí) để phân biệt các chất.","cong_thuc":null,"y":["<b>Trích mẫu thử</b> ra ống nghiệm và đánh số; không cho thuốc thử vào cả lọ.","Chọn thuốc thử cho <b>hiện tượng khác nhau</b> với mỗi chất; ghi hiện tượng, kết luận, viết phương trình.","Hay dùng: quỳ tím (acid, kiềm), BaCl₂ (gốc sulfate), AgNO₃ (gốc chloride), nước vôi trong (khí CO₂)."],"bang":null,"bien":null,"vd":{"de":"Có 2 lọ mất nhãn đựng dung dịch Na₂SO₄ và dung dịch NaCl. Nêu cách phân biệt.","buoc":["Trích mẫu thử, nhỏ dung dịch BaCl₂ vào từng mẫu","Mẫu xuất hiện kết tủa trắng BaSO₄ là Na₂SO₄; mẫu không hiện tượng là NaCl"],"kq":"Dùng BaCl₂: có kết tủa trắng là Na₂SO₄; không hiện tượng là NaCl."},"nham":null,"lq":["h8-quy-tim","h8-ket-tua"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-phan-bon-hoa-hoc","mon":"KHTN","khoi":"8","chu_de":"h8-phan-bon","thu_tu":1,"loai":"kn","ten":"Phân bón hóa học","ten_khac":["phan bon hoa hoc","phan bon","phan hoa hoc","nguyen to dinh duong","phan vo co","n p k"],"noi_dung":"Hóa chất chứa nguyên tố dinh dưỡng cần cho cây, được bón để cây phát triển tốt, tăng năng suất.","cong_thuc":null,"y":["Cây cần nhiều nhất 3 nguyên tố <b>N, P, K</b>; ngoài ra cần một lượng nhỏ các nguyên tố khác.","Phân chứa một nguyên tố dinh dưỡng chính: phân <b>đạm</b> (N), phân <b>lân</b> (P), phân <b>kali</b> (K).","Phân chứa nhiều nguyên tố dinh dưỡng: ví dụ phân <b>NPK</b>."],"bang":null,"bien":null,"vd":{"de":"Cây trồng có biểu hiện còi cọc, lá vàng, năng suất thấp dù đủ nước, đủ ánh sáng. Cần bổ sung gì cho đất?","buoc":["Nguyên nhân thường do đất thiếu chất dinh dưỡng như N, P, K","Cần bón phân hóa học phù hợp để bổ sung dinh dưỡng"],"kq":"Cần bón phân hóa học (đạm, lân, kali) phù hợp với biểu hiện thiếu chất của cây."},"nham":null,"lq":["h8-phan-dam","h8-phan-lan","h8-phan-kali","h8-phan-npk","h8-su-dung-phan-bon"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-phan-dam","mon":"KHTN","khoi":"8","chu_de":"h8-phan-bon","thu_tu":2,"loai":"ch","ten":"Phân đạm","ten_khac":["phan dam","dam","ure","urea","dam ure","phan n","nh4no3","(nh4)2so4"],"noi_dung":"Phân bón cung cấp nguyên tố nitrogen (N) cho cây.","cong_thuc":null,"y":["Giúp cây phát triển <b>thân, lá</b>, lá xanh tốt.","Ví dụ: urea (NH₂)₂CO, ammonium nitrate NH₄NO₃, ammonium sulfate (NH₄)₂SO₄.","Urea có hàm lượng nitrogen cao, được dùng phổ biến."],"bang":null,"bien":null,"vd":{"de":"Tính phần trăm khối lượng nitrogen trong urea (NH₂)₂CO (N = 14, H = 1, C = 12, O = 16).","buoc":["M = 2 × (14 + 2) + 12 + 16 = 60 g/mol","%N = 28 : 60 × 100%"],"kq":"%N ≈ 46,7%"},"nham":null,"lq":["h8-phan-bon-hoa-hoc","h8-phan-lan","h8-phan-kali","h8-phan-npk"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-phan-lan","mon":"KHTN","khoi":"8","chu_de":"h8-phan-bon","thu_tu":3,"loai":"ch","ten":"Phân lân","ten_khac":["phan lan","lan","phan p","phosphorus","superphosphate","supephotphat","lan nung chay","ca(h2po4)2"],"noi_dung":"Phân bón cung cấp nguyên tố phosphorus (P) cho cây.","cong_thuc":null,"y":["Giúp cây phát triển <b>bộ rễ</b>, kích thích ra hoa, kết quả.","Ví dụ: superphosphate (chứa Ca(H₂PO₄)₂), phân lân nung chảy.","Hàm lượng dinh dưỡng của phân lân được tính theo % khối lượng P₂O₅."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h8-phan-bon-hoa-hoc","h8-phan-dam","h8-phan-kali","h8-phan-npk"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-phan-kali","mon":"KHTN","khoi":"8","chu_de":"h8-phan-bon","thu_tu":4,"loai":"ch","ten":"Phân kali","ten_khac":["phan kali","kali","phan k","potassium","kcl","k2so4"],"noi_dung":"Phân bón cung cấp nguyên tố potassium (K) cho cây.","cong_thuc":null,"y":["Giúp cây tăng khả năng <b>chống chịu</b> (rét, sâu bệnh), tăng chất lượng hạt, quả.","Ví dụ: potassium chloride KCl, potassium sulfate K₂SO₄.","Hàm lượng dinh dưỡng của phân kali được tính theo % khối lượng K₂O."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h8-phan-bon-hoa-hoc","h8-phan-dam","h8-phan-lan","h8-phan-npk"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-phan-npk","mon":"KHTN","khoi":"8","chu_de":"h8-phan-bon","thu_tu":5,"loai":"ch","ten":"Phân NPK","ten_khac":["phan npk","npk","phan hon hop","phan tron","phan phuc hop","16-16-8"],"noi_dung":"Phân bón hỗn hợp chứa cả ba nguyên tố dinh dưỡng N, P và K.","cong_thuc":null,"y":["Bao bì ghi 3 số, ví dụ <b>16-16-8</b>: tỉ lệ % khối lượng N – P₂O₅ – K₂O.","Cung cấp cùng lúc nhiều chất dinh dưỡng; chọn loại phù hợp từng cây và từng giai đoạn."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h8-phan-dam","h8-phan-lan","h8-phan-kali","h8-phan-bon-hoa-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h8-su-dung-phan-bon","mon":"KHTN","khoi":"8","chu_de":"h8-phan-bon","thu_tu":6,"loai":"ud","ten":"Sử dụng phân bón hợp lí","ten_khac":["su dung phan bon","bon phan hop li","bon phan an toan","bon phan","4 dung","tac hai phan bon","o nhiem phan bon"],"noi_dung":"Bón đúng loại, đúng lúc, đúng liều lượng, đúng cách để cây tốt mà không hại môi trường và sức khỏe.","cong_thuc":null,"y":["Bón thừa phân gây <b>lãng phí</b>, làm đất chua, bạc màu và <b>ô nhiễm nguồn nước</b>.","Rau bón nhiều phân đạm sát ngày thu hoạch dễ tồn dư nitrate, có hại cho người ăn.","Bảo quản phân nơi khô ráo; đeo găng tay, khẩu trang khi bón; rửa tay sau khi dùng."],"bang":null,"bien":null,"vd":{"de":"Một người bón rất nhiều phân đạm cho rau sát ngày thu hoạch để rau tươi tốt. Cách làm này có nên không?","buoc":["Bón thừa phân đạm gần ngày thu hoạch dễ làm rau tồn dư nitrate","Nitrate dư thừa trong rau có thể gây hại cho người ăn"],"kq":"Không nên; cần bón đúng liều lượng và ngừng bón đạm trước khi thu hoạch đủ lâu."},"nham":null,"lq":["h8-phan-bon-hoa-hoc","h8-phan-dam","h8-phan-npk"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-kim-loai","mon":"KHTN","khoi":"9","chu_de":"kim-loai","thu_tu":1,"loai":"kn","ten":"Kim loại","ten_khac":["kim loai","kl","metal","nguyen to kim loai","tinh kim loai"],"noi_dung":"Nguyên tố có ánh kim, dẫn điện, dẫn nhiệt tốt, dễ dát mỏng, kéo sợi; trong phản ứng dễ tạo ion dương.","cong_thuc":null,"y":["Ở điều kiện thường hầu hết là chất rắn, riêng <b>thủy ngân (Hg)</b> là chất lỏng.","Nằm ở bên trái và khu vực giữa bảng tuần hoàn; nguyên tử thường có 1–3 electron lớp ngoài cùng.","Ví dụ: sodium (Na), magnesium (Mg), aluminium (Al), iron (Fe), copper (Cu), silver (Ag), gold (Au)."],"bang":null,"bien":null,"vd":{"de":"Một sợi dây mỏng, sáng bóng, dẫn điện tốt, dễ uốn cong mà không gãy. Đây là tính chất của kim loại hay phi kim?","buoc":["Dẫn điện tốt, có ánh kim, dễ uốn (dẻo) là đặc trưng của kim loại","Phi kim thường giòn và không dẫn điện"],"kq":"Đây là tính chất của kim loại."},"nham":["Gọi mọi chất rắn sáng bóng là kim loại: than chì (graphite) có ánh xám, dẫn điện nhưng là phi kim."],"lq":["h9-tinh-chat-vat-li-kim-loai","h9-tinh-chat-hoa-hoc-kim-loai","h9-phi-kim","h9-so-sanh-kim-loai-phi-kim"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-tinh-chat-vat-li-kim-loai","mon":"KHTN","khoi":"9","chu_de":"kim-loai","thu_tu":2,"loai":"kn","ten":"Tính chất vật lí của kim loại","ten_khac":["tinh chat vat li kim loai","dan dien","dan nhiet","tinh deo","anh kim","tcvl kim loai"],"noi_dung":"Kim loại có tính dẻo, tính dẫn điện, tính dẫn nhiệt và ánh kim.","cong_thuc":null,"y":["Dẫn điện tốt nhất là <b>bạc</b>, rồi đến đồng, vàng, nhôm, sắt.","<b>Tính dẻo:</b> dát mỏng, kéo sợi được (vàng dát được lá rất mỏng).","Khối lượng riêng, nhiệt độ nóng chảy, độ cứng của các kim loại rất khác nhau.","Mỗi ứng dụng dựa vào một tính chất phù hợp."],"bang":[["Tính chất","Ứng dụng"],["Dẫn điện","dây điện bằng đồng, nhôm"],["Dẫn nhiệt","xoong, nồi, ấm đun"],["Tính dẻo","giấy nhôm, dây thép"],["Ánh kim","đồ trang sức bằng vàng, bạc"]],"bien":null,"vd":{"de":"Vì sao dây dẫn điện trong nhà thường làm bằng đồng mà không làm bằng sắt?","buoc":["Đồng dẫn điện tốt hơn sắt, chỉ kém bạc","Sắt dẫn điện kém hơn và dễ bị gỉ"],"kq":"Vì đồng dẫn điện tốt hơn và ít bị ăn mòn hơn sắt."},"nham":["Nghĩ kim loại nào cũng rắn và nặng: thủy ngân là chất lỏng, sodium nhẹ hơn nước."],"lq":["h9-kim-loai","h9-tinh-chat-hoa-hoc-kim-loai","h9-so-sanh-kim-loai-phi-kim"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-tinh-chat-hoa-hoc-kim-loai","mon":"KHTN","khoi":"9","chu_de":"kim-loai","thu_tu":3,"loai":"kn","ten":"Tính chất hóa học của kim loại","ten_khac":["tinh chat hoa hoc kim loai","tchh kim loai","kim loai tac dung","kim loai phan ung","kim loai oxygen"],"noi_dung":"Kim loại tác dụng với phi kim, với nước, với dung dịch acid và dung dịch muối; mức độ phụ thuộc độ hoạt động.","cong_thuc":null,"y":["<b>Với oxygen</b> tạo oxide: 3Fe + 2O2 → Fe3O4 (t°); <b>với chlorine</b> tạo muối: 2Na + Cl2 → 2NaCl.","<b>Với nước:</b> K, Na, Ca… phản ứng ở nhiệt độ thường tạo base và khí H2.","<b>Với acid</b> (HCl, H2SO4 loãng): kim loại đứng trước H giải phóng H2.","<b>Với dung dịch muối:</b> kim loại mạnh hơn đẩy kim loại yếu hơn ra khỏi muối."],"bang":null,"bien":null,"vd":{"de":"Cho một mẩu sodium nhỏ vào cốc nước. Nêu hiện tượng và viết phương trình.","buoc":["Na là kim loại mạnh, phản ứng ngay với nước ở nhiệt độ thường","Sinh ra dung dịch base NaOH và khí hydrogen"],"kq":"2Na + 2H₂O → 2NaOH + H₂↑; Na chạy trên mặt nước, có khí thoát ra."},"nham":["Cho Cu tác dụng với HCl: Cu đứng sau H nên không phản ứng."],"lq":["h9-kim-loai-tac-dung-acid","h9-kim-loai-tac-dung-muoi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-kim-loai-tac-dung-acid","mon":"KHTN","khoi":"9","chu_de":"kim-loai","thu_tu":4,"loai":"ht","ten":"Kim loại tác dụng với acid","ten_khac":["kim loai tac dung acid","kim loai axit","fe hcl","zn hcl","kim loai giai phong h2","day h2"],"noi_dung":"Kim loại đứng trước H trong dãy hoạt động tác dụng với HCl, H2SO4 loãng tạo muối và khí hydrogen.","cong_thuc":null,"y":["Fe + 2HCl → FeCl2 + H2↑; Zn + H2SO4 → ZnSO4 + H2↑.","Hiện tượng: kim loại tan dần, có <b>bọt khí</b> thoát ra.","Cu, Ag, Au đứng sau H nên <b>không</b> phản ứng với HCl, H2SO4 loãng."],"bang":null,"bien":null,"vd":{"de":"Cho 5,6 g Fe tác dụng hết với dung dịch HCl. Tính thể tích H2 thu được (đkc).","buoc":["n(Fe) = 5,6 : 56 = 0,1 mol","Fe + 2HCl → FeCl2 + H2 ⇒ n(H2) = 0,1 mol","V = 0,1 × 24,79"],"kq":"V(H2) ≈ 2,48 L"},"nham":["Viết sản phẩm FeCl3: sắt tác dụng với HCl chỉ tạo FeCl2 (sắt hóa trị II)."],"lq":["h9-tinh-chat-hoa-hoc-kim-loai","h9-kim-loai-tac-dung-muoi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-kim-loai-tac-dung-muoi","mon":"KHTN","khoi":"9","chu_de":"kim-loai","thu_tu":5,"loai":"ht","ten":"Kim loại tác dụng với muối","ten_khac":["kim loai tac dung muoi","kim loai day kim loai","cu agno3","fe cuso4","day kim loai yeu"],"noi_dung":"Kim loại hoạt động mạnh hơn đẩy kim loại yếu hơn ra khỏi dung dịch muối của nó.","cong_thuc":null,"y":["Cu + 2AgNO3 → Cu(NO3)2 + 2Ag: dây đồng phủ lớp bạc, dung dịch hóa xanh.","Fe + CuSO4 → FeSO4 + Cu: đinh sắt phủ lớp đỏ, màu xanh nhạt dần.","Kim loại yếu hơn <b>không</b> đẩy được kim loại mạnh hơn: Cu + FeSO4 không phản ứng."],"bang":null,"bien":null,"vd":{"de":"Ngâm một đinh sắt sạch vào dung dịch copper(II) sulfate CuSO₄ màu xanh. Nêu hiện tượng và viết phương trình.","buoc":["Fe hoạt động mạnh hơn Cu nên đẩy được Cu ra khỏi muối","Cu sinh ra bám vào đinh sắt, màu xanh của dung dịch nhạt dần"],"kq":"Fe + CuSO₄ → FeSO₄ + Cu; đinh sắt phủ lớp đồng đỏ, dung dịch nhạt màu."},"nham":["Cho Na, K vào dung dịch muối để đẩy kim loại: chúng phản ứng với nước trước."],"lq":["h9-tinh-chat-hoa-hoc-kim-loai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-tach-kim-loai","mon":"KHTN","khoi":"9","chu_de":"kim-loai","thu_tu":6,"loai":"ht","ten":"Tách kim loại","ten_khac":["tach kim loai","dieu che kim loai","san xuat kim loai","luyen kim","khu oxide"],"noi_dung":"Quá trình lấy kim loại ra khỏi hợp chất trong quặng; phương pháp tùy độ hoạt động của kim loại.","cong_thuc":null,"y":["Kim loại càng hoạt động thì càng khó tách ra khỏi hợp chất.","Vàng, platinum có ở dạng đơn chất: tách bằng phương pháp vật lí (như đãi vàng)."],"bang":[["Kim loại","Phương pháp"],["K, Na, Ca, Mg, Al","điện phân nóng chảy"],["Zn, Fe, Pb, Cu","khử oxide bằng C, CO, H2 ở nhiệt độ cao"],["Au, Pt","có sẵn dạng đơn chất, tách bằng phương pháp vật lí"]],"bien":null,"vd":null,"nham":["Dùng CO, H2 khử Al2O3 để lấy nhôm: không được, phải điện phân nóng chảy."],"lq":["h9-nhiet-luyen","h9-dien-phan-nong-chay","h9-quang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-nhiet-luyen","mon":"KHTN","khoi":"9","chu_de":"kim-loai","thu_tu":7,"loai":"ht","ten":"Phương pháp nhiệt luyện","ten_khac":["nhiet luyen","khu oxide kim loai","co khu","h2 khu","fe2o3 co","luyen sat"],"noi_dung":"Dùng chất khử như C, CO, H2 ở nhiệt độ cao để khử oxide của kim loại hoạt động trung bình, yếu.","cong_thuc":null,"y":["Fe2O3 + 3CO → 2Fe + 3CO2 (t°): phản ứng chính khi luyện gang trong lò cao.","CuO + H2 → Cu + H2O (t°): chất rắn đen chuyển thành đỏ.","Dùng cho kim loại từ Zn trở về sau trong dãy hoạt động."],"bang":null,"bien":null,"vd":{"de":"Trong lò cao luyện gang, khí CO khử iron(III) oxide Fe₂O₃ thành sắt. Viết phương trình phản ứng.","buoc":["Chất khử là CO, chất bị khử là Fe₂O₃","Cân bằng số nguyên tử O và Fe hai vế"],"kq":"Fe₂O₃ + 3CO → 2Fe + 3CO₂ (t°)"},"nham":["Nghĩ phản ứng xảy ra ở nhiệt độ thường: luôn cần đun nóng."],"lq":["h9-tach-kim-loai","h9-gang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-dien-phan-nong-chay","mon":"KHTN","khoi":"9","chu_de":"kim-loai","thu_tu":8,"loai":"ht","ten":"Điện phân nóng chảy","ten_khac":["dien phan nong chay","dpnc","san xuat nhom","dien phan al2o3","bauxite","cryolite"],"noi_dung":"Dùng dòng điện phân hủy hợp chất nóng chảy để lấy kim loại hoạt động mạnh như Na, Mg, Al.","cong_thuc":null,"y":["Sản xuất nhôm: 2Al2O3 → 4Al + 3O2 (điện phân nóng chảy, có cryolite).","Nguyên liệu nhôm là <b>quặng bauxite</b> (thành phần chính Al2O3).","Tốn nhiều điện năng nên nhôm tái chế giúp tiết kiệm năng lượng."],"bang":null,"bien":null,"vd":{"de":"Vì sao muốn sản xuất nhôm từ quặng bauxite Al₂O₃, người ta phải điện phân nóng chảy mà không dùng CO như với sắt?","buoc":["Aluminium là kim loại hoạt động mạnh","CO không đủ mạnh để khử oxide của kim loại hoạt động mạnh như Al"],"kq":"Vì Al hoạt động mạnh, chỉ điện phân nóng chảy mới tách được Al từ Al₂O₃."},"nham":["Điện phân dung dịch muối nhôm để lấy nhôm: phải điện phân Al2O3 nóng chảy."],"lq":["h9-tach-kim-loai","h9-nhiet-luyen","h9-quang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-hop-kim","mon":"KHTN","khoi":"9","chu_de":"kim-loai","thu_tu":9,"loai":"ch","ten":"Hợp kim","ten_khac":["hop kim","alloy","duralumin","dura","dong thau","inox","hop kim nhom"],"noi_dung":"Vật liệu kim loại gồm một kim loại cơ bản và một số kim loại hoặc phi kim khác.","cong_thuc":null,"y":["Thường <b>cứng hơn, bền hơn</b>, khó bị ăn mòn hơn kim loại nguyên chất.","Thường dẫn điện, dẫn nhiệt kém hơn kim loại thành phần.","<b>Duralumin</b> (nhôm với đồng, magnesium, manganese…) nhẹ, bền: làm thân máy bay, khung xe."],"bang":[["Hợp kim","Thành phần chính"],["Gang, thép","Fe và C"],["Duralumin","Al, Cu, Mg, Mn"],["Thép không gỉ (inox)","Fe, C, Cr, Ni"]],"bien":null,"vd":{"de":"Vì sao khung máy bay thường làm bằng hợp kim duralumin (nhôm pha đồng, magnesium) mà không dùng nhôm nguyên chất?","buoc":["Hợp kim thường cứng, bền hơn kim loại nguyên chất","Duralumin nhẹ như nhôm nhưng bền chắc hơn nhiều"],"kq":"Vì hợp kim duralumin bền, cứng hơn nhôm nguyên chất mà vẫn nhẹ."},"nham":["Nghĩ hợp kim là hợp chất: hợp kim là hỗn hợp, không có công thức hóa học."],"lq":["h9-gang","h9-thep","h9-an-mon-kim-loai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-gang","mon":"KHTN","khoi":"9","chu_de":"kim-loai","thu_tu":10,"loai":"ch","ten":"Gang","ten_khac":["gang","cast iron","lo cao","luyen gang","gang trang","gang xam"],"noi_dung":"Hợp kim của sắt với carbon (khoảng 2–5%) và một số nguyên tố khác; cứng và giòn.","cong_thuc":null,"y":["Luyện gang trong <b>lò cao</b>: dùng CO khử oxide sắt trong quặng (như hematite Fe2O3).","<b>Gang xám</b> dùng đúc bệ máy, ống dẫn; <b>gang trắng</b> dùng luyện thép.","Giòn, không rèn, không dát mỏng được."],"bang":null,"bien":null,"vd":{"de":"Vì sao đồ vật bằng gang như nồi gang thường không rèn hay dát mỏng được, dễ vỡ khi rơi mạnh?","buoc":["Gang chứa nhiều carbon (khoảng 2–5%) làm gang cứng nhưng giòn","Tính giòn khiến gang dễ vỡ, không dẻo như thép ít carbon"],"kq":"Vì hàm lượng carbon cao làm gang giòn, dễ vỡ."},"nham":["Nhầm gang với thép: gang chứa nhiều carbon hơn (trên 2%)."],"lq":["h9-thep","h9-hop-kim","h9-nhiet-luyen"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-thep","mon":"KHTN","khoi":"9","chu_de":"kim-loai","thu_tu":11,"loai":"ch","ten":"Thép","ten_khac":["thep","steel","luyen thep","thep khong gi","inox"],"noi_dung":"Hợp kim của sắt với carbon (dưới 2%) và một số nguyên tố khác; cứng, đàn hồi, bền.","cong_thuc":null,"y":["Luyện thép từ gang: oxi hóa bớt C, Si, Mn… có trong gang.","Dùng làm vật liệu xây dựng, chế tạo máy, phương tiện giao thông.","<b>Thép không gỉ (inox)</b> có thêm Cr, Ni: khó bị ăn mòn, làm dụng cụ nhà bếp."],"bang":null,"bien":null,"vd":{"de":"Vì sao dao, kéo thường làm bằng thép mà không làm bằng gang?","buoc":["Thép có hàm lượng carbon thấp hơn gang nên dẻo dai, đàn hồi hơn","Gang giòn, dễ vỡ, không rèn được thành lưỡi dao mỏng"],"kq":"Vì thép dẻo dai hơn, rèn được thành lưỡi sắc mà không vỡ."},"nham":["Nghĩ thép là sắt nguyên chất: thép là hợp kim."],"lq":["h9-gang","h9-hop-kim","h9-an-mon-kim-loai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-an-mon-kim-loai","mon":"KHTN","khoi":"9","chu_de":"kim-loai","thu_tu":12,"loai":"ht","ten":"Ăn mòn kim loại (mở rộng)","ten_khac":["an mon kim loai","gi sat","sat bi gi","chong gi","bao ve kim loai","corrosion"],"noi_dung":"Sự phá hủy kim loại, hợp kim do tác dụng hóa học với các chất trong môi trường.","cong_thuc":null,"y":["Ví dụ: đồ sắt để ngoài trời bị <b>gỉ</b>.","Nước, oxygen, muối, acid trong môi trường làm ăn mòn nhanh hơn.","Bảo vệ: sơn, bôi dầu mỡ, mạ kim loại khác, dùng hợp kim khó gỉ (inox)."],"bang":null,"bien":null,"vd":{"de":"Hai đinh sắt giống nhau, một để trong không khí khô, một để ngoài trời mưa ẩm ướt. Đinh nào gỉ nhanh hơn, vì sao?","buoc":["Ăn mòn kim loại cần có nước và oxygen","Đinh ngoài trời ẩm tiếp xúc nhiều nước và oxygen hơn"],"kq":"Đinh để ngoài trời ẩm ướt gỉ nhanh hơn."},"nham":["Nghĩ ăn mòn là hiện tượng vật lí: kim loại biến thành chất khác nên là biến đổi hóa học."],"lq":["h9-hop-kim","h9-thep","h9-tinh-chat-hoa-hoc-kim-loai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-phi-kim","mon":"KHTN","khoi":"9","chu_de":"h9-phi-kim","thu_tu":1,"loai":"kn","ten":"Phi kim","ten_khac":["phi kim","nonmetal","non metal","nguyen to phi kim","tinh phi kim"],"noi_dung":"Nguyên tố không có ánh kim, thường không dẫn điện, dẫn nhiệt; trong phản ứng với kim loại tạo ion âm.","cong_thuc":null,"y":["Tồn tại ở 3 trạng thái: rắn (C, S, P, I2), lỏng (Br2), khí (O2, N2, H2, Cl2).","Thường có nhiệt độ nóng chảy, nhiệt độ sôi thấp; nhiều phi kim độc (Cl2, Br2).","Nằm ở phía trên, bên phải bảng tuần hoàn."],"bang":null,"bien":null,"vd":{"de":"Chlorine ở điều kiện thường là khí màu vàng lục, không dẫn điện. Đây là phi kim hay kim loại?","buoc":["Không dẫn điện, không có ánh kim là đặc trưng của phi kim","Chlorine tồn tại ở thể khí, không có tính chất kim loại"],"kq":"Chlorine là phi kim."},"nham":["Nghĩ phi kim không bao giờ dẫn điện: than chì (graphite) dẫn điện được."],"lq":["h9-tinh-chat-hoa-hoc-phi-kim","h9-so-sanh-kim-loai-phi-kim","h9-kim-loai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-tinh-chat-hoa-hoc-phi-kim","mon":"KHTN","khoi":"9","chu_de":"h9-phi-kim","thu_tu":2,"loai":"kn","ten":"Tính chất hóa học của phi kim","ten_khac":["tinh chat hoa hoc phi kim","tchh phi kim","phi kim tac dung","phi kim oxygen","oxide acid"],"noi_dung":"Phi kim tác dụng với oxygen tạo oxide acid, với kim loại tạo muối hoặc oxide, với hydrogen tạo hợp chất khí.","cong_thuc":null,"y":["<b>Với oxygen:</b> S + O2 → SO2 (t°); C + O2 → CO2 (t°).","<b>Với kim loại:</b> 2Na + Cl2 → 2NaCl; Fe + S → FeS (t°).","<b>Với hydrogen:</b> H2 + Cl2 → 2HCl (ánh sáng)."],"bang":null,"bien":null,"vd":{"de":"Đốt bột sulfur trong khí oxygen. Viết phương trình và cho biết sản phẩm thuộc loại oxide gì.","buoc":["Sulfur (phi kim) tác dụng với oxygen tạo oxide","Sản phẩm SO₂ là oxide acid vì sulfur là phi kim"],"kq":"S + O₂ → SO₂ (t°); SO₂ là oxide acid."},"nham":["Nghĩ oxide phi kim là oxide base: phần lớn oxide phi kim (CO2, SO2, P2O5) là oxide acid."],"lq":["h9-phi-kim","h9-so-sanh-kim-loai-phi-kim","h9-tinh-chat-hoa-hoc-kim-loai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-so-sanh-kim-loai-phi-kim","mon":"KHTN","khoi":"9","chu_de":"h9-phi-kim","thu_tu":3,"loai":"kn","ten":"So sánh kim loại và phi kim","ten_khac":["so sanh kim loai phi kim","khac nhau kim loai phi kim","kim loai va phi kim","ion duong ion am","phan biet kim loai phi kim"],"noi_dung":"Kim loại dẫn điện, có ánh kim, tạo ion dương, oxide base; phi kim thường không dẫn điện, tạo ion âm, oxide acid.","cong_thuc":null,"y":["Khác nhau về <b>tính chất vật lí</b>: dẫn điện, dẫn nhiệt, ánh kim, tính dẻo.","Khác nhau về <b>tính chất hóa học</b>: loại ion tạo thành và loại oxide."],"bang":[["Đặc điểm","Kim loại","Phi kim"],["Trạng thái (thường)","rắn (trừ Hg)","rắn, lỏng, khí"],["Dẫn điện, nhiệt","tốt","kém (trừ graphite)"],["Ánh kim, tính dẻo","có","không"],["Ion tạo thành","ion dương (Na⁺)","ion âm (Cl⁻)"],["Oxide","thường là oxide base","thường là oxide acid"]],"bien":null,"vd":null,"nham":["Phân biệt chỉ bằng màu sắc: phải xét cả tính dẫn điện và tính chất hóa học."],"lq":["h9-kim-loai","h9-phi-kim","h9-tinh-chat-hoa-hoc-phi-kim"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-hop-chat-huu-co","mon":"KHTN","khoi":"9","chu_de":"huu-co","thu_tu":1,"loai":"kn","ten":"Hợp chất hữu cơ","ten_khac":["hop chat huu co","chat huu co","hchc","organic","dan xuat hydrocarbon","dan xuat hidrocacbon"],"noi_dung":"Hợp chất của carbon, trừ một số chất như CO, CO2, H2CO3, muối carbonate.","cong_thuc":null,"y":["Chia 2 loại: <b>hydrocarbon</b> (chỉ có C, H) và <b>dẫn xuất hydrocarbon</b> (có thêm O, N, Cl…).","Thường dễ cháy, kém bền với nhiệt, ít tan trong nước, nhiệt độ sôi thấp.","Có trong cơ thể sống, thực phẩm, nhiên liệu, chất dẻo, thuốc."],"bang":[["Loại","Ví dụ"],["Hydrocarbon","CH4, C2H4"],["Dẫn xuất hydrocarbon","C2H5OH, CH3COOH"]],"bien":null,"vd":{"de":"Trong các chất CO₂, C₂H₅OH (ethylic alcohol), CH₄, đâu không phải là hợp chất hữu cơ?","buoc":["Hợp chất hữu cơ là hợp chất của carbon, trừ một số chất như CO, CO₂, muối carbonate","CO₂ nằm trong nhóm ngoại lệ nên không phải hợp chất hữu cơ"],"kq":"CO₂ không phải hợp chất hữu cơ; C₂H₅OH và CH₄ là hợp chất hữu cơ."},"nham":["Xếp CO2, CaCO3 vào hợp chất hữu cơ: chúng có carbon nhưng là hợp chất vô cơ."],"lq":["h9-hoa-hoc-huu-co","h9-hydrocarbon","h9-cong-thuc-cau-tao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-lap-cong-thuc-phan-tu","mon":"KHTN","khoi":"9","chu_de":"huu-co","thu_tu":2,"loai":"dl","ten":"Lập công thức phân tử","ten_khac":["lap cong thuc phan tu","phan tram khoi luong","%c","%h","cong thuc phan tu","cxhyoz","xac dinh cong thuc"],"noi_dung":"Biết khối lượng mol M và phần trăm khối lượng các nguyên tố, tính số nguyên tử mỗi nguyên tố trong một phân tử.","cong_thuc":"mC = %C × M ; số C = mC : 12 ; số H = mH : 1 ; số O = mO : 16","y":["Khối lượng mỗi nguyên tố trong 1 mol chất: <b>m = % × M</b>.","Số nguyên tử = khối lượng nguyên tố : nguyên tử khối (C = 12, H = 1, O = 16).","Nếu phần còn lại là oxygen: mO = M − mC − mH."],"bang":null,"bien":[["M","khối lượng mol của chất","g/mol"],["%C","phần trăm khối lượng carbon","%"],["mC","khối lượng carbon trong 1 mol chất","g"]],"vd":{"de":"Chất A có M = 30 g/mol, %C = 80%, %H = 20%. Tìm công thức phân tử của A.","buoc":["mC = 80% × 30 = 24 g → số C = 24 : 12 = 2","mH = 20% × 30 = 6 g → số H = 6 : 1 = 6"],"kq":"C2H6"},"nham":["Chia % cho nguyên tử khối mà chưa nhân với khối lượng mol M."],"lq":["h9-hop-chat-huu-co","h9-cong-thuc-cau-tao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-hoa-hoc-huu-co","mon":"KHTN","khoi":"9","chu_de":"huu-co","thu_tu":3,"loai":"kn","ten":"Hóa học hữu cơ","ten_khac":["hoa hoc huu co","hoa huu co","organic chemistry","nganh hoa huu co"],"noi_dung":"Ngành hóa học nghiên cứu về các hợp chất hữu cơ và sự chuyển hóa của chúng.","cong_thuc":null,"y":["Hợp chất hữu cơ rất nhiều và đa dạng vì nguyên tử carbon liên kết được với nhau thành mạch.","Ứng dụng trong sản xuất nhiên liệu, dược phẩm, chất dẻo, tơ sợi, thực phẩm."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h9-hop-chat-huu-co","h9-cong-thuc-cau-tao","h9-hydrocarbon"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-cong-thuc-cau-tao","mon":"KHTN","khoi":"9","chu_de":"huu-co","thu_tu":4,"loai":"kn","ten":"Công thức cấu tạo","ten_khac":["cong thuc cau tao","ctct","mach carbon","mach cacbon","hoa tri carbon","cong thuc thu gon"],"noi_dung":"Công thức cho biết thành phần phân tử và thứ tự, cách liên kết giữa các nguyên tử trong phân tử.","cong_thuc":null,"y":["Trong hợp chất hữu cơ: C hóa trị <b>IV</b>, H hóa trị I, O hóa trị II.","Carbon liên kết với nhau tạo <b>mạch carbon</b>: mạch thẳng, mạch nhánh, mạch vòng.","Cùng công thức phân tử C2H6O có 2 chất khác nhau: CH3–CH2–OH và CH3–O–CH3.","Có thể viết đầy đủ hoặc thu gọn: CH3–CH3 là ethane."],"bang":null,"bien":null,"vd":{"de":"Vì sao C₂H₆O có thể ứng với hai chất khác nhau là ethylic alcohol và dimethyl ether?","buoc":["Cùng công thức phân tử nhưng thứ tự liên kết nguyên tử khác nhau","CH₃-CH₂-OH khác CH₃-O-CH₃ về cách liên kết"],"kq":"Vì công thức cấu tạo khác nhau dù công thức phân tử giống nhau."},"nham":["Vẽ carbon có 3 hoặc 5 nét liên kết: carbon luôn có đủ 4 liên kết."],"lq":["h9-hop-chat-huu-co","h9-alkane","h9-ethylic-alcohol"],"hinh":"H-h9-cong-thuc-cau-tao","nguon":["KHTN Pocket"]},{"ma":"h9-hydrocarbon","mon":"KHTN","khoi":"9","chu_de":"huu-co","thu_tu":5,"loai":"kn","ten":"Hydrocarbon","ten_khac":["hydrocarbon","hidrocacbon","hc","chi co c va h"],"noi_dung":"Hợp chất hữu cơ mà phân tử chỉ gồm hai nguyên tố carbon và hydrogen.","cong_thuc":null,"y":["Lớp 9 học 2 loại: <b>alkane</b> (chỉ liên kết đơn) và <b>alkene</b> (có 1 liên kết đôi).","Cháy trong oxygen tạo CO2 và H2O, tỏa nhiều nhiệt nên dùng làm nhiên liệu.","Nguồn chính: dầu mỏ, khí thiên nhiên."],"bang":null,"bien":null,"vd":{"de":"Đốt cháy hoàn toàn một hydrocarbon X chỉ thu được CO₂ và H₂O. Điều này cho biết X chứa nguyên tố nào?","buoc":["Hydrocarbon chỉ gồm hai nguyên tố carbon và hydrogen","CO₂ chứa C, H₂O chứa H, phù hợp thành phần hydrocarbon"],"kq":"X chỉ chứa carbon và hydrogen."},"nham":["Xếp C2H5OH vào hydrocarbon: có thêm O nên là dẫn xuất hydrocarbon."],"lq":["h9-alkane","h9-alkene","h9-dau-mo","h9-hop-chat-huu-co"],"hinh":"H-h9-hydrocarbon","nguon":["KHTN Pocket"]},{"ma":"h9-alkane","mon":"KHTN","khoi":"9","chu_de":"huu-co","thu_tu":6,"loai":"kn","ten":"Alkane","ten_khac":["alkane","ankan","cnh2n+2","parafin","ethane","propane","butane","hydrocarbon no"],"noi_dung":"Hydrocarbon mạch hở, trong phân tử chỉ có liên kết đơn; công thức chung CnH2n+2 (n ≥ 1).","cong_thuc":null,"y":["Bốn chất đầu: <b>methane</b> CH4, <b>ethane</b> C2H6, <b>propane</b> C3H8, <b>butane</b> C4H10.","Không tan trong nước; từ C1 đến C4 là chất khí ở điều kiện thường.","Cháy tỏa nhiều nhiệt: C3H8 + 5O2 → 3CO2 + 4H2O (t°).","Dùng làm nhiên liệu: khí gas (propane, butane), xăng, dầu."],"bang":[["Tên","Công thức"],["Methane","CH4"],["Ethane","C2H6"],["Propane","C3H8"],["Butane","C4H10"]],"bien":null,"vd":{"de":"Đốt cháy hoàn toàn khí butane C₄H₁₀ trong bình gas. Viết phương trình phản ứng cháy.","buoc":["Alkane cháy tạo CO₂ và H₂O","Cân bằng số nguyên tử C, H, O ở hai vế"],"kq":"2C₄H₁₀ + 13O₂ → 8CO₂ + 10H₂O (t°)"},"nham":["Viết alkane là CnH2n: đó là alkene; alkane là CnH2n+2."],"lq":["h9-methane","h9-alkene","h9-hydrocarbon"],"hinh":"H-h9-alkane","nguon":["KHTN Pocket"]},{"ma":"h9-methane","mon":"KHTN","khoi":"9","chu_de":"huu-co","thu_tu":7,"loai":"ch","ten":"Methane","ten_khac":["methane","metan","ch4","khi bun ao","khi biogas","khi mo"],"noi_dung":"Alkane đơn giản nhất, CH4; chất khí không màu, không mùi, nhẹ hơn không khí, ít tan trong nước.","cong_thuc":null,"y":["Phân tử có 4 liên kết đơn C–H.","Có trong khí thiên nhiên, khí mỏ dầu, khí biogas, khí bùn ao, mỏ than.","Cháy tỏa nhiều nhiệt: CH4 + 2O2 → CO2 + 2H2O (t°).","Hỗn hợp methane và oxygen dễ <b>gây nổ</b> (nổ ở mỏ than)."],"bang":null,"bien":null,"vd":{"de":"Vì sao hầm biogas từ chất thải chăn nuôi có thể dùng làm nhiên liệu đun nấu?","buoc":["Khí biogas có thành phần chính là methane","Methane cháy tỏa nhiều nhiệt theo phương trình CH₄ + 2O₂ → CO₂ + 2H₂O"],"kq":"Vì biogas chứa methane, cháy tỏa nhiệt, dùng làm nhiên liệu đun nấu được."},"nham":["Nghĩ methane có mùi: gas dùng trong nhà có mùi do được pha thêm chất tạo mùi để dễ phát hiện rò rỉ."],"lq":["h9-alkane","h9-khi-thien-nhien"],"hinh":"H-h9-methane","nguon":["KHTN Pocket"]},{"ma":"h9-alkene","mon":"KHTN","khoi":"9","chu_de":"huu-co","thu_tu":8,"loai":"kn","ten":"Alkene","ten_khac":["alkene","anken","olefin","cnh2n","lien ket doi","propylene","hydrocarbon khong no"],"noi_dung":"Hydrocarbon mạch hở có một liên kết đôi C=C; công thức chung CnH2n (n ≥ 2).","cong_thuc":null,"y":["Chất đầu dãy: <b>ethylene</b> C2H4 (CH2=CH2), propylene C3H6.","Tham gia phản ứng cháy, <b>phản ứng cộng</b> (làm mất màu nước bromine) và <b>phản ứng trùng hợp</b>.","Nhận biết alkene: làm mất màu nước bromine, alkane thì không."],"bang":null,"bien":null,"vd":{"de":"Có 2 khí không màu là ethane C₂H₆ và ethylene C₂H₄. Làm sao phân biệt bằng dung dịch bromine?","buoc":["Alkene có liên kết đôi nên làm mất màu nước bromine","Alkane chỉ có liên kết đơn nên không phản ứng với nước bromine"],"kq":"Khí làm mất màu nước bromine là ethylene; khí không đổi màu là ethane."},"nham":["Cho n = 1 (CH2): không có alkene một carbon vì liên kết đôi cần 2 nguyên tử C."],"lq":["h9-ethylene","h9-phan-ung-cong","h9-phan-ung-trung-hop","h9-alkane"],"hinh":"H-h9-alkene","nguon":["KHTN Pocket"]},{"ma":"h9-ethylene","mon":"KHTN","khoi":"9","chu_de":"huu-co","thu_tu":9,"loai":"ch","ten":"Ethylene","ten_khac":["ethylene","etilen","ethene","c2h4","ch2=ch2","kich thich qua chin"],"noi_dung":"Alkene đơn giản nhất, C2H4 (CH2=CH2); chất khí không màu, không mùi, ít tan trong nước.","cong_thuc":null,"y":["Phân tử có 1 <b>liên kết đôi</b> C=C, trong đó một liên kết kém bền, dễ đứt.","Làm mất màu nước bromine: CH2=CH2 + Br2 → BrCH2–CH2Br.","Trùng hợp tạo polyethylene (PE); dùng điều chế ethylic alcohol.","Quả chín sinh ra ethylene; dùng kích thích quả mau chín."],"bang":null,"bien":null,"vd":{"de":"Người bán trái cây thường ủ chuối xanh cùng vài quả chuối chín để chuối mau chín. Vì sao?","buoc":["Quả chín tự nhiên sinh ra khí ethylene","Ethylene kích thích các quả xanh khác chín nhanh hơn"],"kq":"Ethylene sinh ra từ quả chín kích thích chuối xanh mau chín."},"nham":null,"lq":["h9-alkene","h9-phan-ung-trung-hop","h9-ethylic-alcohol"],"hinh":"H-h9-ethylene","nguon":["KHTN Pocket"]},{"ma":"h9-phan-ung-cong","mon":"KHTN","khoi":"9","chu_de":"huu-co","thu_tu":10,"loai":"ht","ten":"Phản ứng cộng","ten_khac":["phan ung cong","cong bromine","cong brom","mat mau nuoc brom","addition"],"noi_dung":"Phản ứng trong đó một liên kết của liên kết đôi bị đứt, phân tử khác gắn thêm vào.","cong_thuc":null,"y":["Đặc trưng cho hợp chất có liên kết đôi như alkene.","Ví dụ: CH2=CH2 + Br2 → BrCH2–CH2Br (nước bromine màu vàng bị mất màu).","Alkane chỉ có liên kết đơn nên <b>không</b> có phản ứng cộng."],"bang":null,"bien":null,"vd":{"de":"Dẫn khí ethylene qua dung dịch nước bromine màu vàng nâu, thấy màu dung dịch nhạt dần rồi mất màu. Viết phương trình.","buoc":["Ethylene có liên kết đôi, phản ứng cộng với bromine","Liên kết đôi bị đứt, Br gắn vào hai nguyên tử carbon"],"kq":"CH₂=CH₂ + Br₂ → BrCH₂-CH₂Br; nước bromine mất màu."},"nham":["Nhầm phản ứng cộng với phản ứng thế: cộng thì chỉ tạo một sản phẩm, không bớt nguyên tử nào."],"lq":["h9-alkene","h9-phan-ung-trung-hop"],"hinh":"H-h9-phan-ung-cong","nguon":["KHTN Pocket"]},{"ma":"h9-phan-ung-trung-hop","mon":"KHTN","khoi":"9","chu_de":"huu-co","thu_tu":11,"loai":"ht","ten":"Phản ứng trùng hợp","ten_khac":["phan ung trung hop","trung hop","polymer hoa","tao pe","polyethylene","monomer"],"noi_dung":"Quá trình nhiều phân tử nhỏ (monomer) kết hợp với nhau tạo thành phân tử rất lớn (polymer).","cong_thuc":null,"y":["Ví dụ: nCH2=CH2 → (–CH2–CH2–)n (t°, p, xúc tác) tạo <b>polyethylene (PE)</b>.","Monomer thường có liên kết đôi.","Dùng sản xuất chất dẻo, cao su tổng hợp."],"bang":null,"bien":null,"vd":{"de":"Túi nhựa PE (polyethylene) được sản xuất từ khí ethylene bằng phản ứng gì?","buoc":["Nhiều phân tử ethylene (monomer) kết hợp liên tiếp với nhau","Tạo thành mạch phân tử rất dài (polymer)"],"kq":"Bằng phản ứng trùng hợp: nCH₂=CH₂ → (-CH₂-CH₂-)n."},"nham":["Nghĩ trùng hợp làm mất bớt nguyên tử: polymer có cùng thành phần nguyên tố với monomer."],"lq":["h9-polymer","h9-ethylene","h9-chat-deo"],"hinh":"H-h9-phan-ung-trung-hop","nguon":["KHTN Pocket"]},{"ma":"h9-nhien-lieu","mon":"KHTN","khoi":"9","chu_de":"huu-co","thu_tu":12,"loai":"kn","ten":"Nhiên liệu","ten_khac":["nhien lieu","chat dot","fuel","xang","gas","su dung nhien lieu hieu qua"],"noi_dung":"Chất cháy được, khi cháy tỏa nhiều nhiệt, dùng cho đời sống và sản xuất.","cong_thuc":null,"y":["Phân loại: <b>rắn</b> (than, gỗ), <b>lỏng</b> (xăng, dầu), <b>khí</b> (gas, khí thiên nhiên, biogas).","Dùng hiệu quả: cung cấp đủ oxygen, tăng diện tích tiếp xúc, điều chỉnh lượng nhiên liệu phù hợp.","Cháy thiếu oxygen sinh khí <b>CO rất độc</b>; không đốt than trong phòng kín.","Xăng sinh học (E5) là xăng pha một lượng nhỏ ethylic alcohol."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ cứ cho thật nhiều không khí là tốt: quá nhiều không khí làm mất nhiệt."],"lq":["h9-dau-mo","h9-khi-thien-nhien","h9-nhien-lieu-hoa-thach","h9-ethylic-alcohol"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-dau-mo","mon":"KHTN","khoi":"9","chu_de":"huu-co","thu_tu":13,"loai":"ch","ten":"Dầu mỏ","ten_khac":["dau mo","dau tho","petroleum","chung cat dau mo","loc dau","xang dau"],"noi_dung":"Chất lỏng sánh, màu nâu đen, không tan và nhẹ hơn nước; là hỗn hợp nhiều hydrocarbon.","cong_thuc":null,"y":["Mỏ dầu thường có 3 lớp: khí mỏ dầu ở trên, dầu ở giữa, nước ở dưới.","<b>Chưng cất</b> dầu mỏ tách ra: khí, xăng, dầu hỏa, dầu diesel, dầu mazut, nhựa đường.","Việt Nam có dầu mỏ ở thềm lục địa phía Nam (mỏ Bạch Hổ…)."],"bang":null,"bien":null,"vd":{"de":"Vì sao khi chưng cất dầu mỏ lại thu được nhiều sản phẩm khác nhau như xăng, dầu hỏa, dầu diesel?","buoc":["Dầu mỏ là hỗn hợp nhiều hydrocarbon có nhiệt độ sôi khác nhau","Chưng cất tách các hydrocarbon theo nhiệt độ sôi thành từng phần riêng"],"kq":"Vì dầu mỏ là hỗn hợp; chưng cất tách các thành phần theo nhiệt độ sôi."},"nham":["Nghĩ dầu mỏ là một chất: dầu mỏ là hỗn hợp, không có công thức hóa học xác định."],"lq":["h9-khi-thien-nhien","h9-nhien-lieu","h9-nhien-lieu-hoa-thach","h9-hydrocarbon"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-khi-thien-nhien","mon":"KHTN","khoi":"9","chu_de":"huu-co","thu_tu":14,"loai":"ch","ten":"Khí thiên nhiên","ten_khac":["khi thien nhien","khi dot","natural gas","khi mo dau","khi dong hanh","khi metan"],"noi_dung":"Khí có trong các mỏ khí dưới lòng đất, thành phần chủ yếu là methane.","cong_thuc":null,"y":["<b>Khí mỏ dầu</b> (khí đồng hành) nằm trong mỏ dầu, cũng chứa nhiều methane.","Dùng làm nhiên liệu cho nhà máy điện, công nghiệp và nguyên liệu sản xuất phân đạm.","Cháy sạch hơn than và dầu (ít khói, bụi)."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h9-methane","h9-dau-mo","h9-nhien-lieu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-ethylic-alcohol","mon":"KHTN","khoi":"9","chu_de":"huu-co","thu_tu":15,"loai":"ch","ten":"Ethylic alcohol","ten_khac":["ethylic alcohol","ethanol","ruou etylic","ancol etylic","c2h5oh","con","c2h6o"],"noi_dung":"Chất lỏng không màu, tan vô hạn trong nước, công thức C2H5OH; phân tử có nhóm –OH.","cong_thuc":null,"y":["Sôi ở 78,3 °C, nhẹ hơn nước, hòa tan được nhiều chất (iodine…).","<b>Cháy</b> với ngọn lửa xanh: C2H5OH + 3O2 → 2CO2 + 3H2O (t°).","<b>Tác dụng với sodium:</b> 2C2H5OH + 2Na → 2C2H5ONa + H2↑.","Điều chế: lên men tinh bột, đường; hoặc cho ethylene cộng nước (xúc tác acid).","Dùng làm dung môi, nhiên liệu, sát trùng; lạm dụng rượu bia gây hại sức khỏe."],"bang":null,"bien":null,"vd":{"de":"Cho một mẩu sodium nhỏ vào ống nghiệm đựng ethylic alcohol khan. Nêu hiện tượng và viết phương trình.","buoc":["Ethylic alcohol có nhóm -OH phản ứng được với Na","Sinh ra khí hydrogen thoát ra"],"kq":"2C₂H₅OH + 2Na → 2C₂H₅ONa + H₂↑; có bọt khí thoát ra."},"nham":["Nghĩ C2H5OH là base vì có nhóm OH: ethylic alcohol không làm đổi màu quỳ tím."],"lq":["h9-do-con","h9-len-men-ruou","h9-acetic-acid"],"hinh":"H-h9-ethylic-alcohol","nguon":["KHTN Pocket"]},{"ma":"h9-do-con","mon":"KHTN","khoi":"9","chu_de":"huu-co","thu_tu":16,"loai":"dl","ten":"Độ cồn","ten_khac":["do con","do ruou","nong do con","ruou 40 do","do ruou bia","con 70 do"],"noi_dung":"Số mL ethylic alcohol nguyên chất có trong 100 mL hỗn hợp rượu với nước.","cong_thuc":"Đr = Vr/Vhh × 100","y":["Rượu 40° nghĩa là trong 100 mL rượu có 40 mL ethylic alcohol nguyên chất.","Cồn sát khuẩn thường dùng loại khoảng 70°."],"bang":null,"bien":[["Đr","độ cồn","độ (°)"],["Vr","thể tích ethylic alcohol nguyên chất","mL"],["Vhh","thể tích hỗn hợp rượu và nước","mL"]],"vd":{"de":"Tính thể tích ethylic alcohol nguyên chất có trong 500 mL rượu 40°.","buoc":["Vr = Đr × 