→ 3RCOONa + C3H5(OH)3 (t°).","Muối sodium của acid béo (RCOONa) là thành phần chính của <b>xà phòng</b>."],"bang":null,"bien":null,"vd":{"de":"Đun chất béo với dung dịch NaOH thu được xà phòng. Viết phương trình phản ứng dạng tổng quát và cho biết đó là phản ứng gì.","buoc":["Chất béo bị thủy phân trong môi trường kiềm","Sản phẩm là glycerol và muối sodium của acid béo (xà phòng)"],"kq":"(RCOO)₃C₃H₅ + 3NaOH → 3RCOONa + C₃H₅(OH)₃; đây là phản ứng xà phòng hóa."},"nham":["Nghĩ thủy phân trong acid cũng tạo xà phòng: trong acid chỉ tạo acid béo và glycerol."],"lq":["h9-chat-beo","h9-lipid"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-carbohydrate","mon":"KHTN","khoi":"9","chu_de":"h9-lipid","thu_tu":4,"loai":"kn","ten":"Carbohydrate","ten_khac":["carbohydrate","cacbohidrat","gluxit","duong bot","cn(h2o)m","chat duong"],"noi_dung":"Nhóm hợp chất hữu cơ có công thức chung Cn(H2O)m, gồm glucose, saccharose, tinh bột, cellulose.","cong_thuc":null,"y":["Chỉ gồm 3 nguyên tố C, H, O.","Được thực vật tạo ra nhờ <b>quang hợp</b>; là nguồn năng lượng chính của cơ thể."],"bang":[["Chất","Công thức"],["Glucose","C6H12O6"],["Saccharose","C12H22O11"],["Tinh bột, cellulose","(C6H10O5)n"]],"bien":null,"vd":null,"nham":["Nghĩ carbohydrate có chứa phân tử nước: Cn(H2O)m chỉ là cách viết công thức chung."],"lq":["h9-glucose","h9-saccharose","h9-tinh-bot","h9-cellulose"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-glucose","mon":"KHTN","khoi":"9","chu_de":"h9-lipid","thu_tu":5,"loai":"ch","ten":"Glucose","ten_khac":["glucose","glucozo","duong nho","c6h12o6","trang bac","trang guong"],"noi_dung":"Chất rắn kết tinh, không màu, vị ngọt, tan nhiều trong nước, công thức C6H12O6.","cong_thuc":null,"y":["Có nhiều trong quả chín (nhất là nho), mật ong; có trong máu người.","<b>Phản ứng tráng bạc:</b> với dung dịch AgNO3 trong NH3 tạo lớp bạc sáng bám thành ống nghiệm.","<b>Lên men rượu</b> tạo ethylic alcohol và CO2.","Dùng pha dịch truyền, làm thuốc, tráng gương, tráng ruột phích."],"bang":null,"bien":null,"vd":{"de":"Nhỏ dung dịch glucose vào ống nghiệm chứa dung dịch AgNO₃ trong NH₃ rồi đun nhẹ. Nêu hiện tượng.","buoc":["Glucose có phản ứng tráng bạc đặc trưng","Ion bạc bị khử thành bạc kim loại bám vào thành ống nghiệm"],"kq":"Xuất hiện lớp bạc sáng bóng bám vào thành ống nghiệm."},"nham":["Nghĩ saccharose cũng tráng bạc: saccharose không có phản ứng tráng bạc."],"lq":["h9-len-men-ruou","h9-saccharose","h9-carbohydrate"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-len-men-ruou","mon":"KHTN","khoi":"9","chu_de":"h9-lipid","thu_tu":6,"loai":"ht","ten":"Lên men rượu","ten_khac":["len men ruou","len men","men ruou","nau ruou","glucose thanh ruou"],"noi_dung":"Quá trình glucose chuyển thành ethylic alcohol và khí carbon dioxide nhờ enzyme của nấm men.","cong_thuc":null,"y":["C6H12O6 → 2C2H5OH + 2CO2 (men rượu, nhiệt độ khoảng 30 °C).","Tinh bột (gạo, sắn) được thủy phân thành glucose rồi lên men để nấu rượu.","Để lâu dung dịch rượu loãng ngoài không khí có thể bị lên men giấm."],"bang":null,"bien":null,"vd":{"de":"Ủ cơm nếp với men rượu vài ngày thấy có mùi rượu và sủi bọt khí. Giải thích và viết phương trình.","buoc":["Tinh bột trong cơm được thủy phân thành glucose","Glucose lên men nhờ enzyme của men rượu tạo alcohol và khí"],"kq":"C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂; bọt khí là CO₂, mùi rượu là ethylic alcohol."},"nham":["Nghĩ lên men cần nhiệt độ cao: nhiệt độ cao làm chết nấm men."],"lq":["h9-glucose","h9-ethylic-alcohol","h9-tinh-bot"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-saccharose","mon":"KHTN","khoi":"9","chu_de":"h9-lipid","thu_tu":7,"loai":"ch","ten":"Saccharose","ten_khac":["saccharose","saccarozo","sucrose","duong mia","duong kinh","c12h22o11"],"noi_dung":"Chất rắn kết tinh, không màu, vị ngọt, tan nhiều trong nước, công thức C12H22O11; là đường mía.","cong_thuc":null,"y":["Có trong mía, củ cải đường, thốt nốt.","<b>Thủy phân</b> (acid hoặc enzyme, t°): C12H22O11 + H2O → C6H12O6 (glucose) + C6H12O6 (fructose).","Không có phản ứng tráng bạc.","Dùng làm thực phẩm, pha chế thuốc; sản xuất từ nước mía."],"bang":null,"bien":null,"vd":{"de":"Đun nóng dung dịch saccharose (đường mía) với vài giọt acid, sau đó thử phản ứng tráng bạc thì thấy có phản ứng. Giải thích.","buoc":["Saccharose bị thủy phân trong môi trường acid thành glucose và fructose","Glucose sinh ra có khả năng tráng bạc dù saccharose ban đầu không có"],"kq":"Do saccharose bị thủy phân tạo glucose, glucose mới gây được phản ứng tráng bạc."},"nham":["Viết sản phẩm thủy phân là 2 phân tử glucose: là glucose và fructose."],"lq":["h9-glucose","h9-carbohydrate","h9-tinh-bot"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-tinh-bot","mon":"KHTN","khoi":"9","chu_de":"h9-lipid","thu_tu":8,"loai":"ch","ten":"Tinh bột","ten_khac":["tinh bot","starch","ho tinh bot","iodine tinh bot","iot tinh bot","c6h10o5"],"noi_dung":"Chất rắn màu trắng, không tan trong nước lạnh, công thức (C6H10O5)n; có nhiều trong hạt, củ, quả.","cong_thuc":null,"y":["Trong nước nóng tạo dung dịch keo gọi là <b>hồ tinh bột</b>.","Thủy phân (acid hoặc enzyme) tạo glucose.","<b>Nhận biết:</b> gặp iodine chuyển sang màu xanh tím.","Được tạo ra trong cây xanh nhờ quang hợp."],"bang":null,"bien":null,"vd":{"de":"Nhỏ vài giọt dung dịch iodine vào bát cơm chứa tinh bột. Nêu hiện tượng quan sát được.","buoc":["Tinh bột có phản ứng đặc trưng với iodine","Phản ứng tạo màu xanh tím đặc trưng"],"kq":"Cơm chuyển sang màu xanh tím, chứng tỏ có tinh bột."},"nham":["Nhầm tinh bột và cellulose là một chất: cùng dạng (C6H10O5)n nhưng cấu tạo và số mắt xích khác nhau."],"lq":["h9-cellulose","h9-glucose","h9-carbohydrate","h9-polymer"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-cellulose","mon":"KHTN","khoi":"9","chu_de":"h9-lipid","thu_tu":9,"loai":"ch","ten":"Cellulose","ten_khac":["cellulose","xenlulozo","chat xo","soi bong","go"],"noi_dung":"Chất rắn màu trắng, dạng sợi, không tan trong nước, công thức (C6H10O5)n; thành phần chính của thành tế bào thực vật.","cong_thuc":null,"y":["Có nhiều trong gỗ, tre, nứa; <b>bông</b> gần như là cellulose nguyên chất.","Thủy phân (acid, t°) tạo glucose.","Không cho màu xanh tím với iodine.","Dùng làm giấy, vải sợi, đồ gỗ, vật liệu xây dựng."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h9-tinh-bot","h9-carbohydrate","h9-to"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-protein","mon":"KHTN","khoi":"9","chu_de":"h9-lipid","thu_tu":10,"loai":"ch","ten":"Protein","ten_khac":["protein","protit","chat dam","dam","amino acid","amino axit"],"noi_dung":"Hợp chất hữu cơ có phân tử khối rất lớn, được tạo thành từ nhiều amino acid.","cong_thuc":null,"y":["Có trong thịt, cá, trứng, sữa, đậu; là thành phần chính của cơ thể động vật.","<b>Thủy phân</b> (acid, base hoặc enzyme) tạo hỗn hợp amino acid.","Bị <b>đông tụ</b> khi đun nóng hoặc gặp acid, base, muối kim loại nặng.","Đốt cháy có mùi khét (như tóc, lông cháy)."],"bang":null,"bien":null,"vd":{"de":"Luộc trứng gà, thấy lòng trắng trứng (chứa protein) từ lỏng trong suốt chuyển thành rắn, đục. Hiện tượng này gọi là gì?","buoc":["Protein bị biến đổi cấu trúc khi đun nóng","Protein bị kết tủa, không tan trở lại được"],"kq":"Đó là sự đông tụ protein do nhiệt độ cao."},"nham":["Nghĩ protein chỉ gồm C, H, O: protein luôn có thêm nitrogen."],"lq":["h9-dong-tu","h9-polymer","h9-chat-beo"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-dong-tu","mon":"KHTN","khoi":"9","chu_de":"h9-lipid","thu_tu":11,"loai":"ht","ten":"Sự đông tụ protein","ten_khac":["dong tu","su dong tu","dong tu protein","luoc trung","rieu cua","dau phu"],"noi_dung":"Hiện tượng protein bị kết tủa, không tan khi đun nóng hoặc khi gặp acid, base, muối kim loại nặng.","cong_thuc":null,"y":["Luộc trứng: lòng trắng trứng đông lại.","Nấu canh cua: protein đông tụ nổi thành mảng (riêu cua).","Vắt chanh vào sữa: sữa bị vón cục."],"bang":null,"bien":null,"vd":{"de":"Vắt vài giọt chanh chứa acid vào cốc sữa tươi, thấy sữa bị vón cục. Giải thích hiện tượng.","buoc":["Acid trong chanh làm biến đổi cấu trúc protein trong sữa","Protein bị đông tụ, không tan, vón thành cục"],"kq":"Acid trong chanh làm protein sữa bị đông tụ, gây vón cục."},"nham":["Nghĩ đông tụ là do lạnh: đông tụ protein xảy ra khi đun nóng, không phải đông đặc."],"lq":["h9-protein"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-polymer","mon":"KHTN","khoi":"9","chu_de":"h9-lipid","thu_tu":12,"loai":"kn","ten":"Polymer","ten_khac":["polymer","polime","monomer","mat xich","cao phan tu","pe","pvc"],"noi_dung":"Chất có phân tử khối rất lớn, do nhiều đơn vị nhỏ (mắt xích) liên kết với nhau tạo nên.","cong_thuc":null,"y":["<b>Monomer</b>: phân tử nhỏ ban đầu; <b>mắt xích</b>: đơn vị lặp lại, ví dụ –CH2–CH2– trong PE.","<b>Thiên nhiên</b>: tinh bột, cellulose, protein, cao su thiên nhiên; <b>tổng hợp</b>: PE, PVC, nylon.","Thường là chất rắn, không bay hơi, hầu hết không tan trong nước.","Ứng dụng: chất dẻo, tơ, cao su."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ polymer đều là nhựa nhân tạo: tinh bột, protein cũng là polymer."],"lq":["h9-phan-ung-trung-hop","h9-chat-deo","h9-to","h9-cao-su"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-chat-deo","mon":"KHTN","khoi":"9","chu_de":"h9-lipid","thu_tu":13,"loai":"ch","ten":"Chất dẻo","ten_khac":["chat deo","nhua","plastic","polyethylene","pe","pvc","tui nilon","rac thai nhua"],"noi_dung":"Vật liệu polymer có tính dẻo, dễ tạo hình khi đun nóng hoặc chịu áp lực.","cong_thuc":null,"y":["<b>PE</b> (polyethylene): túi, màng bọc thực phẩm, chai lọ.","<b>PVC</b>: ống dẫn nước, vỏ dây điện, áo mưa.","Nhẹ, bền, cách điện, rẻ; nhưng <b>rất khó phân hủy</b>, gây ô nhiễm môi trường.","Nên hạn chế dùng túi nylon, phân loại và tái chế rác nhựa."],"bang":null,"bien":null,"vd":{"de":"Vì sao nên hạn chế dùng túi nylon làm từ chất dẻo PE và ưu tiên túi vải khi đi chợ?","buoc":["Chất dẻo như PE rất khó phân hủy trong tự nhiên","Túi vải dùng được nhiều lần, dễ phân hủy hơn, giảm rác thải nhựa"],"kq":"Vì túi nylon khó phân hủy, gây ô nhiễm lâu dài, nên ưu tiên túi vải tái sử dụng."},"nham":["Đốt rác nhựa để xử lí: sinh khí độc, gây ô nhiễm không khí."],"lq":["h9-polymer","h9-phan-ung-trung-hop","h9-khai-thac-hop-li"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-to","mon":"KHTN","khoi":"9","chu_de":"h9-lipid","thu_tu":14,"loai":"ch","ten":"Tơ","ten_khac":["to","soi","to tam","to nylon","to nilon","to tong hop","to nhan tao","to visco"],"noi_dung":"Vật liệu polymer hình sợi dài, mảnh, có độ bền nhất định, dùng dệt vải.","cong_thuc":null,"y":["<b>Tơ thiên nhiên</b>: bông, tơ tằm, len.","<b>Tơ tổng hợp</b> (chế tạo từ chất đơn giản): nylon.","<b>Tơ bán tổng hợp</b> (tơ nhân tạo, chế biến từ cellulose): tơ viscose."],"bang":null,"bien":null,"vd":null,"nham":["Xếp tơ viscose vào tơ tổng hợp: tơ viscose là tơ bán tổng hợp, đi từ cellulose."],"lq":["h9-polymer","h9-cellulose","h9-cao-su"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-cao-su","mon":"KHTN","khoi":"9","chu_de":"h9-lipid","thu_tu":15,"loai":"ch","ten":"Cao su","ten_khac":["cao su","rubber","mu cao su","cao su thien nhien","cao su tong hop","dan hoi"],"noi_dung":"Vật liệu polymer có tính đàn hồi, không thấm nước, không thấm khí, cách điện.","cong_thuc":null,"y":["<b>Cao su thiên nhiên</b> lấy từ mủ cây cao su.","<b>Cao su tổng hợp</b> điều chế bằng phản ứng trùng hợp.","Dùng làm lốp xe, găng tay, ống dẫn, đệm, vật cách điện."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h9-polymer","h9-chat-deo","h9-phan-ung-trung-hop"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-vo-trai-dat","mon":"KHTN","khoi":"9","chu_de":"h9-vo-trai-dat","thu_tu":1,"loai":"kn","ten":"Vỏ Trái Đất","ten_khac":["vo trai dat","thach quyen","nguyen to vo trai dat","tai nguyen khoang san","khoang san"],"noi_dung":"Lớp đất đá rắn ngoài cùng của Trái Đất, chứa khoáng sản, đá, nhiên liệu hóa thạch.","cong_thuc":null,"y":["Nguyên tố nhiều nhất: <b>oxygen</b>, rồi đến <b>silicon</b>, aluminium, iron.","Kim loại phần lớn ở dạng hợp chất trong quặng; vàng, bạc có thể ở dạng đơn chất.","Tài nguyên: quặng kim loại, đá vôi, cát, đất sét, than, dầu mỏ, khí thiên nhiên."],"bang":[["Nguyên tố","Khối lượng (khoảng)"],["O","46%"],["Si","28%"],["Al","8%"],["Fe","5%"]],"bien":null,"vd":null,"nham":null,"lq":["h9-quang","h9-khai-thac-hop-li","h9-silicon","h9-da-voi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-quang","mon":"KHTN","khoi":"9","chu_de":"h9-vo-trai-dat","thu_tu":2,"loai":"ch","ten":"Quặng","ten_khac":["quang","quang kim loai","hematite","magnetite","bauxite","boxit","ore"],"noi_dung":"Đất đá chứa khoáng vật có kim loại hoặc chất có ích với hàm lượng đủ lớn để khai thác.","cong_thuc":null,"y":["Quặng sắt: <b>hematite</b> (Fe2O3), <b>magnetite</b> (Fe3O4).","Quặng nhôm: <b>bauxite</b> (thành phần chính Al2O3), nhiều ở Tây Nguyên.","Việt Nam còn có quặng apatite (Lào Cai), than đá (Quảng Ninh)."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h9-tach-kim-loai","h9-vo-trai-dat","h9-dien-phan-nong-chay"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-da-voi","mon":"KHTN","khoi":"9","chu_de":"h9-vo-trai-dat","thu_tu":3,"loai":"ch","ten":"Đá vôi","ten_khac":["da voi","caco3","calcium carbonate","nung voi","voi song","voi toi","cao"],"noi_dung":"Loại đá có thành phần chính là calcium carbonate (CaCO3), dùng làm vật liệu xây dựng và sản xuất vôi.","cong_thuc":null,"y":["<b>Nung vôi:</b> CaCO3 → CaO + CO2 (t°); CaO là vôi sống.","<b>Tôi vôi:</b> CaO + H2O → Ca(OH)2, tỏa nhiều nhiệt.","Là nguyên liệu sản xuất xi măng, thủy tinh.","Khai thác, nung vôi gây bụi, thải CO2, làm mất cảnh quan núi đá."],"bang":null,"bien":null,"vd":{"de":"Nung một khối đá vôi CaCO₃ ở nhiệt độ cao, sau đó cho sản phẩm rắn tác dụng với nước. Viết hai phương trình phản ứng xảy ra.","buoc":["Nung đá vôi sinh ra vôi sống và khí carbon dioxide","Vôi sống tác dụng với nước tạo vôi tôi, tỏa nhiều nhiệt"],"kq":"CaCO₃ → CaO + CO₂ (t°); CaO + H₂O → Ca(OH)₂."},"nham":["Nhầm vôi sống (CaO) với vôi tôi (Ca(OH)2)."],"lq":["h9-xi-mang","h9-thuy-tinh","h9-khai-thac-hop-li"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-silicon","mon":"KHTN","khoi":"9","chu_de":"h9-vo-trai-dat","thu_tu":4,"loai":"ch","ten":"Silicon","ten_khac":["silicon","silic","si","sio2","cat","ban dan","pin mat troi"],"noi_dung":"Phi kim phổ biến thứ hai trong vỏ Trái Đất (sau oxygen), có trong cát, đất sét dưới dạng hợp chất.","cong_thuc":null,"y":["Không có ở dạng đơn chất trong tự nhiên; cát chứa nhiều <b>silicon dioxide (SiO2)</b>.","Silicon tinh khiết là chất <b>bán dẫn</b>: làm chip, linh kiện điện tử, pin mặt trời.","Hợp chất của silicon là nguyên liệu công nghiệp silicate."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm silicon (Si, nguyên tố) với silicone (một loại polymer dùng làm keo, khuôn bánh)."],"lq":["h9-cong-nghiep-silicate","h9-vo-trai-dat","h9-thuy-tinh"],"hinh":"H-h9-silicon","nguon":["KHTN Pocket"]},{"ma":"h9-cong-nghiep-silicate","mon":"KHTN","khoi":"9","chu_de":"h9-vo-trai-dat","thu_tu":5,"loai":"ud","ten":"Công nghiệp silicate","ten_khac":["cong nghiep silicate","cong nghiep silicat","silicate","silicat","vat lieu xay dung"],"noi_dung":"Ngành sản xuất đồ gốm, thủy tinh, xi măng từ hợp chất tự nhiên của silicon (cát, đất sét…).","cong_thuc":null,"y":["Nguyên liệu: đất sét, cát thạch anh, đá vôi, soda…","Sản phẩm là vật liệu xây dựng và đồ dùng quan trọng.","Cần xử lí bụi, khí thải từ lò nung để bảo vệ môi trường."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h9-gom","h9-thuy-tinh","h9-xi-mang","h9-silicon"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-xi-mang","mon":"KHTN","khoi":"9","chu_de":"h9-vo-trai-dat","thu_tu":6,"loai":"ch","ten":"Xi măng","ten_khac":["xi mang","ximang","cement","clinker","be tong","vua"],"noi_dung":"Chất kết dính dạng bột, trộn với nước thì đông cứng; là vật liệu xây dựng quan trọng.","cong_thuc":null,"y":["Nguyên liệu: <b>đá vôi, đất sét</b> và một ít quặng sắt.","Nung trong lò quay ở nhiệt độ rất cao được clinker, nghiền với thạch cao thành xi măng.","Trộn với cát, nước được <b>vữa</b>; thêm đá sỏi được <b>bê tông</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h9-cong-nghiep-silicate","h9-da-voi","h9-gom"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-gom","mon":"KHTN","khoi":"9","chu_de":"h9-vo-trai-dat","thu_tu":7,"loai":"ch","ten":"Đồ gốm","ten_khac":["do gom","gom","gom su","su","gach ngoi","dat set","cao lanh"],"noi_dung":"Vật liệu làm từ đất sét, cao lanh nhào với nước, tạo hình, sấy khô rồi nung ở nhiệt độ cao.","cong_thuc":null,"y":["Gồm gạch, ngói, sành, sứ.","Bền, cứng, cách điện, chịu nhiệt, khó bị ăn mòn.","Làng gốm nổi tiếng: Bát Tràng (Hà Nội)."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h9-cong-nghiep-silicate","h9-thuy-tinh","h9-xi-mang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-thuy-tinh","mon":"KHTN","khoi":"9","chu_de":"h9-vo-trai-dat","thu_tu":8,"loai":"ch","ten":"Thủy tinh","ten_khac":["thuy tinh","kinh","glass","cat thach anh","soda","na2co3"],"noi_dung":"Vật liệu trong suốt làm từ cát thạch anh, đá vôi, soda nấu chảy ở nhiệt độ cao rồi làm nguội.","cong_thuc":null,"y":["Nguyên liệu chính: <b>cát (SiO2), đá vôi (CaCO3), soda (Na2CO3)</b>.","Khi mềm dẻo có thể ép, thổi thành chai, lọ, kính.","Cứng, giòn, không gỉ; có thể <b>tái chế</b> nhiều lần."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ thủy tinh là nhựa trong: thủy tinh là vật liệu silicate, nhựa là polymer."],"lq":["h9-cong-nghiep-silicate","h9-silicon","h9-da-voi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-nhien-lieu-hoa-thach","mon":"KHTN","khoi":"9","chu_de":"h9-vo-trai-dat","thu_tu":9,"loai":"ch","ten":"Nhiên liệu hóa thạch","ten_khac":["nhien lieu hoa thach","than da","than","dau mo","khi thien nhien","fossil fuel"],"noi_dung":"Than, dầu mỏ, khí thiên nhiên, hình thành từ xác sinh vật bị vùi lấp qua hàng triệu năm.","cong_thuc":null,"y":["Là tài nguyên <b>không tái tạo</b>, đang dần cạn kiệt.","Đốt cháy thải nhiều CO2 và các khí gây ô nhiễm (SO2, NO2, bụi).","Giải pháp: tiết kiệm năng lượng, dùng năng lượng tái tạo (mặt trời, gió, nước)."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h9-dau-mo","h9-khi-thien-nhien","h9-chu-trinh-carbon","h9-am-len-toan-cau"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-chu-trinh-carbon","mon":"KHTN","khoi":"9","chu_de":"h9-vo-trai-dat","thu_tu":10,"loai":"ht","ten":"Chu trình carbon","ten_khac":["chu trinh carbon","chu trinh cacbon","vong tuan hoan carbon","nguon carbon","carbon cycle"],"noi_dung":"Sự tuần hoàn của carbon giữa khí quyển, sinh vật, đại dương và vỏ Trái Đất.","cong_thuc":null,"y":["<b>Lấy CO2</b> khỏi khí quyển: quang hợp của cây xanh, hòa tan vào nước biển.","<b>Thải CO2</b>: hô hấp, phân hủy xác sinh vật, đốt nhiên liệu, núi lửa.","Nguồn carbon: đá vôi, than, dầu mỏ, khí thiên nhiên, sinh vật.","Đốt nhiều nhiên liệu hóa thạch làm lượng CO2 trong khí quyển tăng."],"bang":null,"bien":null,"vd":{"de":"Vì sao chặt phá rừng trên diện rộng có thể góp phần làm tăng lượng CO₂ trong khí quyển?","buoc":["Cây xanh hấp thụ CO₂ qua quá trình quang hợp","Mất rừng làm giảm lượng CO₂ được hấp thụ, trong khi lượng CO₂ thải ra vẫn tiếp diễn"],"kq":"Vì rừng là nơi hấp thụ CO₂ lớn; mất rừng làm CO₂ trong khí quyển tăng nhanh hơn."},"nham":null,"lq":["h9-am-len-toan-cau","h9-nhien-lieu-hoa-thach","h9-da-voi"],"hinh":"H-h9-chu-trinh-carbon","nguon":["KHTN Pocket"]},{"ma":"h9-am-len-toan-cau","mon":"KHTN","khoi":"9","chu_de":"h9-vo-trai-dat","thu_tu":11,"loai":"ht","ten":"Sự ấm lên toàn cầu","ten_khac":["am len toan cau","nong len toan cau","hieu ung nha kinh","khi nha kinh","bien doi khi hau","global warming"],"noi_dung":"Sự tăng nhiệt độ trung bình bề mặt Trái Đất, chủ yếu do khí nhà kính trong khí quyển tăng.","cong_thuc":null,"y":["Khí nhà kính chính: <b>CO2</b>, methane (CH4)…","Hậu quả: băng tan, nước biển dâng, thời tiết cực đoan, ảnh hưởng sinh vật.","Giảm thiểu: tiết kiệm năng lượng, dùng năng lượng tái tạo, trồng rừng."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ hiệu ứng nhà kính luôn có hại: nó giữ Trái Đất đủ ấm; chỉ tăng quá mức mới gây hại."],"lq":["h9-chu-trinh-carbon","h9-nhien-lieu-hoa-thach","h9-khai-thac-hop-li"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"h9-khai-thac-hop-li","mon":"KHTN","khoi":"9","chu_de":"h9-vo-trai-dat","thu_tu":12,"loai":"ud","ten":"Khai thác tài nguyên hợp lí","ten_khac":["khai thac tai nguyen hop li","khai thac hop ly","tiet kiem tai nguyen","tai che","bao ve tai nguyen"],"noi_dung":"Khai thác, sử dụng tài nguyên vỏ Trái Đất tiết kiệm, hiệu quả, hạn chế hại môi trường.","cong_thuc":null,"y":["Tài nguyên khoáng sản có hạn và phần lớn <b>không tái tạo</b>.","Tiết kiệm, <b>tái chế</b> kim loại, nhựa, thủy tinh; dùng vật liệu thay thế.","Dùng công nghệ hiện đại, xử lí chất thải, phục hồi môi trường sau khai thác.","Nghiêm cấm khai thác trái phép."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["h9-vo-trai-dat","h9-nhien-lieu-hoa-thach","h9-chat-deo","h9-am-len-toan-cau"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-te-bao","mon":"KHTN","khoi":"6","chu_de":"s6-te-bao","thu_tu":1,"loai":"kn","ten":"Tế bào","ten_khac":["te bao","tb","cell","don vi co so su song","don vi cau truc"],"noi_dung":"Đơn vị cơ sở cấu tạo nên mọi cơ thể sống và thực hiện các hoạt động sống.","cong_thuc":null,"y":["Mọi sinh vật đều được cấu tạo từ <b>một hoặc nhiều tế bào</b>.","Ba thành phần chính: <b>màng tế bào, tế bào chất, nhân</b> (hoặc vùng nhân).","Tế bào thực hiện các hoạt động sống: trao đổi chất, lớn lên, sinh sản.","Phần lớn tế bào rất nhỏ, phải quan sát bằng kính hiển vi."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ virus cũng có cấu tạo tế bào (virus chưa có cấu tạo tế bào)."],"lq":["s6-hinh-dang-kich-thuoc-te-bao","s6-mang-te-bao","s6-te-bao-chat","s6-nhan-te-bao","s6-co-the-sinh-vat"],"hinh":"H-s6-te-bao","nguon":["KHTN Pocket"]},{"ma":"s6-hinh-dang-kich-thuoc-te-bao","mon":"KHTN","khoi":"6","chu_de":"s6-te-bao","thu_tu":2,"loai":"kn","ten":"Hình dạng và kích thước tế bào","ten_khac":["hinh dang te bao","kich thuoc te bao","te bao lon nhat","te bao nho","te bao trung ca"],"noi_dung":"Tế bào có nhiều hình dạng và kích thước khác nhau, phù hợp với chức năng của chúng.","cong_thuc":null,"y":["Hình dạng đa dạng: hình cầu, hình đĩa, hình sao, hình trụ, hình sợi…","Đa số tế bào rất nhỏ, chỉ thấy dưới <b>kính hiển vi</b>.","Một số tế bào lớn thấy được bằng mắt thường, ví dụ <b>tế bào trứng cá, trứng ếch</b>."],"bang":[["Tế bào","Hình dạng"],["Hồng cầu người","Hình đĩa lõm hai mặt"],["Tế bào thần kinh","Hình sao, có sợi dài"],["Tế bào cơ","Hình sợi dài"]],"bien":null,"vd":null,"nham":null,"lq":["s6-te-bao","s6-quan-sat-te-bao","s6-te-bao-dong-vat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-hinh-dang-chuc-nang-te-bao","mon":"KHTN","khoi":"6","chu_de":"s6-te-bao","thu_tu":3,"loai":"kn","ten":"Hình dạng và chức năng tế bào","ten_khac":["hinh dang phu hop chuc nang","te bao than kinh","hong cau","te bao long hut","te bao co"],"noi_dung":"Mỗi loại tế bào có hình dạng phù hợp với chức năng mà nó đảm nhận trong cơ thể.","cong_thuc":null,"y":["<b>Tế bào thần kinh</b> có nhiều sợi nhánh dài để nhận và truyền thông tin.","<b>Hồng cầu</b> hình đĩa lõm hai mặt, dễ di chuyển trong mạch máu và vận chuyển khí.","<b>Tế bào lông hút</b> của rễ kéo dài để hút nước và muối khoáng; <b>tế bào cơ</b> dài, có khả năng co rút."],"bang":null,"bien":null,"vd":{"de":"Vì sao tế bào thần kinh có nhiều nhánh kéo dài?","buoc":["Tế bào thần kinh có chức năng nhận và truyền thông tin.","Các nhánh dài giúp nối với nhiều tế bào khác và truyền thông tin đi xa."],"kq":"Hình dạng nhiều nhánh dài phù hợp với chức năng dẫn truyền thông tin."},"nham":null,"lq":["s6-hinh-dang-kich-thuoc-te-bao","s6-te-bao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-mang-te-bao","mon":"KHTN","khoi":"6","chu_de":"s6-te-bao","thu_tu":4,"loai":"cq","ten":"Màng tế bào","ten_khac":["mang te bao","mang sinh chat","mang","cell membrane","mang bao boc"],"noi_dung":"Lớp màng bao bọc bên ngoài tế bào, bảo vệ và kiểm soát các chất đi vào, đi ra.","cong_thuc":null,"y":["Có ở <b>mọi tế bào</b> (nhân sơ và nhân thực).","Chức năng: bảo vệ tế bào, <b>kiểm soát sự vận chuyển các chất</b> giữa tế bào và môi trường.","Ở tế bào thực vật, màng nằm sát phía trong thành tế bào."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm màng tế bào với thành tế bào (thành tế bào nằm ngoài màng, chỉ có ở thực vật, vi khuẩn, nấm)."],"lq":["s6-te-bao","s6-thanh-te-bao","s6-te-bao-chat"],"hinh":"H-s6-mang-te-bao","nguon":["KHTN Pocket"]},{"ma":"s6-te-bao-chat","mon":"KHTN","khoi":"6","chu_de":"s6-te-bao","thu_tu":5,"loai":"cq","ten":"Tế bào chất","ten_khac":["te bao chat","chat te bao","cytoplasm","bao quan","noi dien ra hoat dong song"],"noi_dung":"Phần nằm giữa màng tế bào và nhân (vùng nhân), là nơi diễn ra phần lớn hoạt động sống của tế bào.","cong_thuc":null,"y":["Có ở mọi tế bào.","Chứa nhiều <b>bào quan</b>, ví dụ lục lạp ở tế bào thực vật.","Là nơi diễn ra hầu hết các hoạt động trao đổi chất của tế bào."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-mang-te-bao","s6-nhan-te-bao","s6-luc-lap","s6-khong-bao"],"hinh":"H-s6-te-bao-chat","nguon":["KHTN Pocket"]},{"ma":"s6-nhan-te-bao","mon":"KHTN","khoi":"6","chu_de":"s6-te-bao","thu_tu":6,"loai":"cq","ten":"Nhân tế bào","ten_khac":["nhan te bao","nhan","mang nhan","nucleus","vat chat di truyen","trung tam dieu khien"],"noi_dung":"Bộ phận có màng nhân bao bọc, chứa vật chất di truyền, điều khiển mọi hoạt động sống của tế bào.","cong_thuc":null,"y":["Có ở <b>tế bào nhân thực</b> (thực vật, động vật, nấm, nguyên sinh vật).","Được bao bọc bởi <b>màng nhân</b>, bên trong chứa vật chất di truyền.","Là <b>trung tâm điều khiển</b> hoạt động sống của tế bào."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ vi khuẩn có nhân (vi khuẩn chỉ có vùng nhân, không có màng nhân)."],"lq":["s6-vung-nhan","s6-te-bao-nhan-thuc","s6-te-bao-chat"],"hinh":"H-s6-nhan-te-bao","nguon":["KHTN Pocket"]},{"ma":"s6-vung-nhan","mon":"KHTN","khoi":"6","chu_de":"s6-te-bao","thu_tu":7,"loai":"cq","ten":"Vùng nhân","ten_khac":["vung nhan","nhan so","chua co mang nhan","nucleoid","vung chua vat chat di truyen"],"noi_dung":"Vùng chứa vật chất di truyền của tế bào nhân sơ, chưa có màng nhân bao bọc.","cong_thuc":null,"y":["Chỉ có ở <b>tế bào nhân sơ</b> (vi khuẩn).","Vật chất di truyền nằm trực tiếp trong tế bào chất, <b>không có màng nhân</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-te-bao-nhan-so","s6-nhan-te-bao","s6-vi-khuan"],"hinh":"H-s6-vung-nhan","nguon":["KHTN Pocket"]},{"ma":"s6-te-bao-nhan-so","mon":"KHTN","khoi":"6","chu_de":"s6-te-bao","thu_tu":8,"loai":"kn","ten":"Tế bào nhân sơ","ten_khac":["te bao nhan so","nhan so","prokaryote","te bao vi khuan","chua co nhan hoan chinh"],"noi_dung":"Tế bào chưa có nhân hoàn chỉnh: vật chất di truyền nằm ở vùng nhân, không có màng nhân.","cong_thuc":null,"y":["Kích thước rất nhỏ, cấu tạo đơn giản.","Gồm màng tế bào, tế bào chất, <b>vùng nhân</b>; thường có thêm thành tế bào, một số có roi.","Ví dụ: <b>vi khuẩn</b>."],"bang":[["Đặc điểm","Nhân sơ","Nhân thực"],["Màng nhân","Không có","Có"],["Kích thước","Nhỏ","Lớn hơn"],["Ví dụ","Vi khuẩn","Thực vật, động vật, nấm"]],"bien":null,"vd":null,"nham":null,"lq":["s6-te-bao-nhan-thuc","s6-vung-nhan","s6-vi-khuan"],"hinh":"H-s6-te-bao-nhan-so","nguon":["KHTN Pocket"]},{"ma":"s6-te-bao-nhan-thuc","mon":"KHTN","khoi":"6","chu_de":"s6-te-bao","thu_tu":9,"loai":"kn","ten":"Tế bào nhân thực","ten_khac":["te bao nhan thuc","nhan thuc","eukaryote","nhan hoan chinh","co mang nhan"],"noi_dung":"Tế bào có nhân hoàn chỉnh: vật chất di truyền được màng nhân bao bọc.","cong_thuc":null,"y":["Gồm màng tế bào, tế bào chất (nhiều bào quan có màng), <b>nhân có màng nhân</b>.","Kích thước thường lớn hơn tế bào nhân sơ, cấu tạo phức tạp hơn.","Gặp ở nguyên sinh vật, nấm, thực vật, động vật."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-te-bao-nhan-so","s6-nhan-te-bao","s6-te-bao-dong-vat","s6-te-bao-thuc-vat"],"hinh":"H-s6-te-bao-nhan-thuc","nguon":["KHTN Pocket"]},{"ma":"s6-te-bao-dong-vat","mon":"KHTN","khoi":"6","chu_de":"s6-te-bao","thu_tu":10,"loai":"kn","ten":"Tế bào động vật","ten_khac":["te bao dong vat","tb dong vat","animal cell","khong co thanh te bao","khong co luc lap"],"noi_dung":"Tế bào nhân thực gồm màng, tế bào chất, nhân; không có thành tế bào và lục lạp.","cong_thuc":null,"y":["Thành phần: <b>màng tế bào, tế bào chất, nhân</b>.","<b>Không có</b> thành tế bào, lục lạp; không bào nhỏ hoặc không có.","Hình dạng đa dạng: hồng cầu, tế bào thần kinh, tế bào cơ…"],"bang":[["Thành phần","TB động vật","TB thực vật"],["Thành tế bào","Không","Có"],["Lục lạp","Không","Có"],["Màng, tế bào chất, nhân","Có","Có"]],"bien":null,"vd":null,"nham":null,"lq":["s6-te-bao-thuc-vat","s6-te-bao-nhan-thuc","s6-luc-lap"],"hinh":"H-s6-te-bao-dong-vat","nguon":["KHTN Pocket"]},{"ma":"s6-te-bao-thuc-vat","mon":"KHTN","khoi":"6","chu_de":"s6-te-bao","thu_tu":11,"loai":"kn","ten":"Tế bào thực vật","ten_khac":["te bao thuc vat","tb thuc vat","plant cell","te bao la","te bao hanh"],"noi_dung":"Tế bào nhân thực có thành tế bào, lục lạp và thường có không bào lớn.","cong_thuc":null,"y":["Có đủ màng, tế bào chất, nhân như tế bào động vật.","Có thêm <b>thành tế bào</b> (giúp tế bào có hình dạng ổn định) và <b>lục lạp</b> (quang hợp).","Thường có <b>không bào</b> lớn chứa dịch tế bào."],"bang":null,"bien":null,"vd":null,"nham":["Cho rằng mọi tế bào thực vật đều có lục lạp (tế bào rễ, vảy hành không có)."],"lq":["s6-thanh-te-bao","s6-luc-lap","s6-khong-bao","s6-te-bao-dong-vat"],"hinh":"H-s6-te-bao-thuc-vat","nguon":["KHTN Pocket"]},{"ma":"s6-thanh-te-bao","mon":"KHTN","khoi":"6","chu_de":"s6-te-bao","thu_tu":12,"loai":"cq","ten":"Thành tế bào","ten_khac":["thanh te bao","vach te bao","cellulose","xenlulozo","cell wall"],"noi_dung":"Lớp vỏ cứng bên ngoài màng tế bào, giúp tế bào có hình dạng ổn định và được bảo vệ.","cong_thuc":null,"y":["Có ở <b>tế bào thực vật</b> (cấu tạo chủ yếu từ <b>cellulose</b>), vi khuẩn và nấm.","Tế bào động vật <b>không có</b> thành tế bào.","Nằm ngoài màng tế bào."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm thành tế bào với màng tế bào."],"lq":["s6-mang-te-bao","s6-te-bao-thuc-vat","s6-te-bao-dong-vat"],"hinh":"H-s6-thanh-te-bao","nguon":["KHTN Pocket"]},{"ma":"s6-luc-lap","mon":"KHTN","khoi":"6","chu_de":"s6-te-bao","thu_tu":13,"loai":"cq","ten":"Lục lạp","ten_khac":["luc lap","diep luc","chloroplast","bao quan quang hop","mau xanh cua la"],"noi_dung":"Bào quan chứa diệp lục, có ở tế bào thực vật, là nơi diễn ra quang hợp.","cong_thuc":null,"y":["Có ở tế bào thực vật, tảo (và trùng roi xanh); tế bào động vật không có.","Chứa <b>diệp lục</b> nên lá có màu xanh.","Hấp thụ năng lượng ánh sáng để tổng hợp chất hữu cơ."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm lục lạp với ti thể (ti thể là nơi hô hấp tế bào)."],"lq":["s6-te-bao-thuc-vat","s6-thanh-te-bao","s6-te-bao-dong-vat"],"hinh":"H-s6-luc-lap","nguon":["KHTN Pocket"]},{"ma":"s6-khong-bao","mon":"KHTN","khoi":"6","chu_de":"s6-te-bao","thu_tu":14,"loai":"cq","ten":"Không bào","ten_khac":["khong bao","dich te bao","vacuole","khong bao trung tam","tui chua dich"],"noi_dung":"Bào quan dạng túi chứa dịch tế bào, thường rất lớn ở tế bào thực vật trưởng thành.","cong_thuc":null,"y":["Nằm trong tế bào chất, chứa <b>dịch tế bào</b> (nước, muối khoáng, chất dự trữ…).","Ở tế bào thực vật thường có <b>không bào lớn</b>; tế bào động vật không bào nhỏ hoặc không có."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-te-bao-thuc-vat","s6-te-bao-chat","s6-su-lon-len-te-bao"],"hinh":"H-s6-khong-bao","nguon":["KHTN Pocket"]},{"ma":"s6-su-lon-len-te-bao","mon":"KHTN","khoi":"6","chu_de":"s6-te-bao","thu_tu":15,"loai":"ht","ten":"Sự lớn lên của tế bào","ten_khac":["su lon len cua te bao","lon len","te bao lon len","tang kich thuoc","te bao truong thanh"],"noi_dung":"Sự tăng kích thước của tế bào con đến khi thành tế bào trưởng thành, nhờ trao đổi chất.","cong_thuc":null,"y":["Tế bào non mới tạo thành có kích thước nhỏ, lớn dần lên nhờ <b>trao đổi chất</b>.","Khi đạt kích thước nhất định, một số tế bào tiếp tục <b>sinh sản</b> (phân chia).","Sự lớn lên và sinh sản của tế bào giúp cơ thể lớn lên."],"bang":null,"bien":null,"vd":{"de":"Một tế bào mới hình thành sau khi phân chia có kích thước nhỏ hơn tế bào mẹ. Vì sao sau đó nó lớn lên được?","buoc":["Tế bào con hấp thụ chất dinh dưỡng, trao đổi chất với môi trường.","Nhờ đó tế bào chất tăng dần về khối lượng và kích thước."],"kq":"Tế bào lớn dần đến khi đạt kích thước của tế bào trưởng thành."},"nham":null,"lq":["s6-su-sinh-san-te-bao","s6-te-bao","s6-co-the-da-bao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-su-sinh-san-te-bao","mon":"KHTN","khoi":"6","chu_de":"s6-te-bao","thu_tu":16,"loai":"ht","ten":"Sự sinh sản của tế bào","ten_khac":["su sinh san cua te bao","phan chia te bao","phan bao","te bao me","te bao con","2 mu n"],"noi_dung":"Quá trình một tế bào mẹ phân chia tạo thành hai tế bào con.","cong_thuc":"số tế bào con = 2ⁿ","y":["Từ 1 tế bào mẹ tạo ra <b>2 tế bào con</b>; sau n lần phân chia tạo ra <b>2ⁿ</b> tế bào.","Ý nghĩa: giúp cơ thể <b>lớn lên</b> và <b>thay thế</b> tế bào già, chết, bị tổn thương.","Sinh vật đơn bào sinh sản bằng cách phân chia tế bào."],"bang":null,"bien":[["n","số lần phân chia liên tiếp từ 1 tế bào","lần"]],"vd":{"de":"Một tế bào phân chia liên tiếp 3 lần. Tính số tế bào con tạo thành.","buoc":["1 lần: 2 tế bào; 2 lần: 4 tế bào; 3 lần: 8 tế bào.","Hay số tế bào = 2³ = 8."],"kq":"8 tế bào con"},"nham":["Tính 2 × n thay vì 2ⁿ (3 lần phân chia cho 8 chứ không phải 6 tế bào)."],"lq":["s6-su-lon-len-te-bao","s6-te-bao","s6-co-the-don-bao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-quan-sat-te-bao","mon":"KHTN","khoi":"6","chu_de":"s6-te-bao","thu_tu":17,"loai":"tn","ten":"Quan sát tế bào","ten_khac":["quan sat te bao","tieu ban","vay hanh","bieu bi hanh","kinh hien vi","trung ca","lam tieu ban"],"noi_dung":"Làm tiêu bản và dùng kính lúp, kính hiển vi để quan sát hình dạng, thành phần tế bào.","cong_thuc":null,"y":["Tế bào trứng cá quan sát được bằng <b>mắt thường hoặc kính lúp</b>.","Tế bào biểu bì vảy hành, niêm mạc miệng: làm <b>tiêu bản</b>, quan sát bằng <b>kính hiển vi</b>.","Có thể nhỏ thuốc nhuộm (xanh methylene) để thấy nhân rõ hơn.","Quan sát từ vật kính nhỏ đến vật kính lớn."],"bang":null,"bien":null,"vd":{"de":"Khi quan sát tiêu bản tế bào biểu bì vảy hành dưới kính hiển vi, nên thực hiện theo thứ tự nào?","buoc":["Đặt tiêu bản lên bàn kính, dùng vật kính nhỏ trước để tìm vùng cần quan sát.","Chỉnh ốc điều chỉnh để lấy nét, sau đó chuyển sang vật kính lớn hơn."],"kq":"Quan sát từ vật kính nhỏ đến lớn giúp dễ tìm và lấy nét tiêu bản."},"nham":["Để bọt khí lọt dưới lá kính, nhầm bọt khí là tế bào."],"lq":["s6-te-bao","s6-hinh-dang-kich-thuoc-te-bao","s6-te-bao-thuc-vat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-co-the-sinh-vat","mon":"KHTN","khoi":"6","chu_de":"s6-co-the","thu_tu":1,"loai":"kn","ten":"Cơ thể sinh vật","ten_khac":["co the","co the sinh vat","vat song","dac trung song","dau hieu su song"],"noi_dung":"Một vật sống hoàn chỉnh, có đủ các đặc trưng sống, được cấu tạo từ một hay nhiều tế bào.","cong_thuc":null,"y":["Các đặc trưng sống: <b>cảm ứng và vận động, sinh trưởng, sinh sản, hô hấp, dinh dưỡng, bài tiết</b>.","Dựa vào số lượng tế bào, chia thành cơ thể <b>đơn bào</b> và <b>đa bào</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-vat-song","s6-co-the-don-bao","s6-co-the-da-bao","s6-cap-do-to-chuc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-vat-song","mon":"KHTN","khoi":"6","chu_de":"s6-co-the","thu_tu":2,"loai":"kn","ten":"Vật sống và vật không sống","ten_khac":["vat song","vat khong song","vat vo sinh","vat huu sinh","phan biet vat song"],"noi_dung":"Vật sống có các đặc trưng sống (dinh dưỡng, sinh trưởng, sinh sản…); vật không sống thì không có.","cong_thuc":null,"y":["Vật sống: con gà, cây lúa, vi khuẩn… có trao đổi chất, lớn lên, sinh sản.","Vật không sống: hòn đá, cái bàn, xe đạp… không có các đặc trưng đó."],"bang":null,"bien":null,"vd":null,"nham":["Cho rằng vật chuyển động được là vật sống (ô tô chuyển động nhưng không sống)."],"lq":["s6-co-the-sinh-vat","s6-te-bao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-co-the-don-bao","mon":"KHTN","khoi":"6","chu_de":"s6-co-the","thu_tu":3,"loai":"kn","ten":"Cơ thể đơn bào","ten_khac":["co the don bao","don bao","sinh vat don bao","mot te bao","unicellular"],"noi_dung":"Cơ thể chỉ gồm một tế bào, tế bào đó thực hiện mọi hoạt động sống.","cong_thuc":null,"y":["Ví dụ: <b>vi khuẩn, trùng roi, trùng giày, trùng biến hình, nấm men, tảo lục đơn bào</b>.","Thường có kích thước hiển vi.","Sinh sản bằng cách <b>phân chia tế bào</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-co-the-da-bao","s6-vi-khuan","s6-trung-roi","s6-nam-men"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-co-the-da-bao","mon":"KHTN","khoi":"6","chu_de":"s6-co-the","thu_tu":4,"loai":"kn","ten":"Cơ thể đa bào","ten_khac":["co the da bao","da bao","sinh vat da bao","nhieu te bao","multicellular"],"noi_dung":"Cơ thể gồm nhiều tế bào, các tế bào phân hóa để đảm nhận các chức năng khác nhau.","cong_thuc":null,"y":["Ví dụ: cây hoa hướng dương, cây lúa, con chó, con người, nấm rơm.","Các tế bào tổ chức thành <b>mô → cơ quan → hệ cơ quan → cơ thể</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-co-the-don-bao","s6-cap-do-to-chuc","s6-mo"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-cap-do-to-chuc","mon":"KHTN","khoi":"6","chu_de":"s6-co-the","thu_tu":5,"loai":"kn","ten":"Các cấp độ tổ chức cơ thể","ten_khac":["cap do to chuc","cac cap to chuc","te bao mo co quan","to chuc co the","tu te bao den co the"],"noi_dung":"Cơ thể đa bào được tổ chức theo thứ tự: tế bào → mô → cơ quan → hệ cơ quan → cơ thể.","cong_thuc":null,"y":["Cấp dưới là đơn vị cấu tạo nên cấp trên.","Các cấp phối hợp nhịp nhàng để cơ thể tồn tại và phát triển."],"bang":[["Cấp độ","Ví dụ ở người","Ví dụ ở cây"],["Tế bào","Tế bào cơ","Tế bào biểu bì lá"],["Mô","Mô cơ","Mô biểu bì"],["Cơ quan","Tim","Lá"],["Hệ cơ quan","Hệ tuần hoàn","Hệ chồi"]],"bien":null,"vd":{"de":"Trong cơ thể người, tế bào cơ tim tạo nên mô cơ tim; mô cơ tim tạo nên tim; tim cùng mạch máu tạo hệ tuần hoàn. Sắp xếp các cấp độ này theo đúng thứ tự.","buoc":["Tế bào cơ tim là cấp nhỏ nhất.","Mô cơ tim gồm nhiều tế bào giống nhau; cơ quan (tim) gồm nhiều mô; hệ cơ quan gồm nhiều cơ quan."],"kq":"Thứ tự: tế bào → mô → cơ quan → hệ cơ quan."},"nham":null,"lq":["s6-mo","s6-co-quan","s6-he-co-quan","s6-co-the-da-bao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-mo","mon":"KHTN","khoi":"6","chu_de":"s6-co-the","thu_tu":6,"loai":"cq","ten":"Mô","ten_khac":["mo","mo te bao","tissue","nhom te bao","mo co","mo bieu bi","mo than kinh"],"noi_dung":"Tập hợp các tế bào giống nhau cùng thực hiện một chức năng nhất định.","cong_thuc":null,"y":["Mô ở động vật: <b>mô biểu bì, mô cơ, mô liên kết, mô thần kinh</b>.","Mô ở thực vật: <b>mô biểu bì, mô dẫn, mô mềm, mô phân sinh</b>…","Nhiều mô cùng tham gia tạo thành một cơ quan."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-cap-do-to-chuc","s6-co-quan","s6-te-bao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-co-quan","mon":"KHTN","khoi":"6","chu_de":"s6-co-the","thu_tu":7,"loai":"cq","ten":"Cơ quan","ten_khac":["co quan","organ","tap hop mo","tim","la","re"],"noi_dung":"Tập hợp nhiều mô cùng thực hiện một hoạt động sống nhất định.","cong_thuc":null,"y":["Ví dụ ở người: <b>tim, dạ dày, phổi, não</b>…","Ví dụ ở thực vật: <b>rễ, thân, lá, hoa, quả</b>.","Nhiều cơ quan cùng phối hợp tạo thành hệ cơ quan."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-mo","s6-he-co-quan","s6-cap-do-to-chuc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-he-co-quan","mon":"KHTN","khoi":"6","chu_de":"s6-co-the","thu_tu":8,"loai":"cq","ten":"Hệ cơ quan","ten_khac":["he co quan","he choi","he re","he tieu hoa","he tuan hoan","organ system"],"noi_dung":"Tập hợp nhiều cơ quan cùng hoạt động để thực hiện một chức năng nhất định.","cong_thuc":null,"y":["Thực vật có hai hệ cơ quan: <b>hệ chồi</b> (thân, lá, hoa, quả) và <b>hệ rễ</b>.","Người có: <b>hệ tiêu hóa, hô hấp, tuần hoàn, thần kinh, bài tiết</b>…","Các hệ cơ quan phối hợp tạo nên cơ thể thống nhất."],"bang":[["Hệ cơ quan (người)","Cơ quan chính"],["Tiêu hóa","Miệng, dạ dày, ruột"],["Hô hấp","Mũi, khí quản, phổi"],["Tuần hoàn","Tim, mạch máu"]],"bien":null,"vd":{"de":"Dạ dày, ruột non, ruột già cùng phối hợp để tiêu hóa và hấp thụ thức ăn. Chúng thuộc cấp độ tổ chức nào?","buoc":["Đây đều là các cơ quan, cùng thực hiện chung một chức năng tiêu hóa.","Tập hợp các cơ quan cùng chức năng tạo thành một hệ cơ quan."],"kq":"Đây là hệ tiêu hóa, một hệ cơ quan."},"nham":null,"lq":["s6-co-quan","s6-cap-do-to-chuc","s6-co-the-sinh-vat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-phan-loai-the-gioi-song","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":1,"loai":"kn","ten":"Phân loại thế giới sống","ten_khac":["phan loai the gioi song","phan loai sinh vat","phan loai","xep nhom sinh vat","classification"],"noi_dung":"Cách sắp xếp sinh vật vào các nhóm theo trật tự nhất định dựa vào đặc điểm của chúng.","cong_thuc":null,"y":["Giúp gọi đúng tên sinh vật, xác định vị trí của chúng trong thế giới sống.","Thấy được <b>mối quan hệ họ hàng</b> giữa các nhóm sinh vật.","Dựa vào đặc điểm cơ thể, loại tế bào, kiểu dinh dưỡng…"],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-bac-phan-loai","s6-nam-gioi-sinh-vat","s6-khoa-luong-phan","s6-ten-khoa-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-bac-phan-loai","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":2,"loai":"kn","ten":"Các bậc phân loại","ten_khac":["bac phan loai","loai chi ho bo lop nganh gioi","gioi nganh lop bo ho chi loai","loai","chi","giong"],"noi_dung":"Các mức xếp nhóm sinh vật từ thấp đến cao: loài, chi (giống), họ, bộ, lớp, ngành, giới.","cong_thuc":null,"y":["<b>Loài</b> là bậc phân loại cơ sở (thấp nhất); <b>giới</b> là bậc cao nhất.","Bậc càng thấp, các sinh vật càng giống nhau nhiều đặc điểm."],"bang":[["Bậc","Ví dụ (con người)"],["Giới","Động vật"],["Ngành","Dây sống"],["Lớp","Thú"],["Bộ","Linh trưởng"],["Họ","Người"],["Chi","Homo"],["Loài","Homo sapiens"]],"bien":null,"vd":null,"nham":["Đảo thứ tự bộ và lớp (lớp cao hơn bộ)."],"lq":["s6-phan-loai-the-gioi-song","s6-ten-khoa-hoc","s6-nam-gioi-sinh-vat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-ten-khoa-hoc","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":3,"loai":"kn","ten":"Tên khoa học","ten_khac":["ten khoa hoc","danh phap","ten latinh","ten kep","ten dia phuong","homo sapiens"],"noi_dung":"Tên gọi sinh vật dùng chung trên thế giới, gồm tên chi và tên loài, viết nghiêng.","cong_thuc":null,"y":["Cách viết: <b>Tên chi</b> (viết hoa chữ đầu) + <b>tên loài</b> (viết thường), in nghiêng.","Ví dụ: người là <i>Homo sapiens</i>.","Khác với <b>tên địa phương</b> (tên gọi thông thường, mỗi vùng một khác)."],"bang":null,"bien":null,"vd":{"de":"Tên khoa học của loài người là Homo sapiens. Phần nào là tên chi, phần nào là tên loài?","buoc":["Từ đầu viết hoa (Homo) là tên chi.","Từ sau viết thường (sapiens) là tên loài."],"kq":"Homo là tên chi, sapiens là tên loài; cả tên khoa học viết nghiêng."},"nham":["Viết hoa cả tên loài (đúng: Homo sapiens, không phải Homo Sapiens)."],"lq":["s6-bac-phan-loai","s6-phan-loai-the-gioi-song"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-khoa-luong-phan","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":4,"loai":"tn","ten":"Khóa lưỡng phân","ten_khac":["khoa luong phan","luong phan","dichotomous key","khoa phan loai","chia doi"],"noi_dung":"Cách phân loại chia sinh vật thành hai nhóm theo cặp đặc điểm đối lập, cho đến khi xác định từng sinh vật.","cong_thuc":null,"y":["Mỗi bước chọn <b>một cặp đặc điểm đối lập</b> (có/không có…).","Tiếp tục chia đôi mỗi nhóm đến khi mỗi nhóm chỉ còn <b>một sinh vật</b>."],"bang":[["Bước","Đặc điểm","Kết quả"],["1a","Có lông vũ","Chim bồ câu"],["1b","Không có lông vũ","Sang bước 2"],["2a","Có vây","Cá chép"],["2b","Không có vây","Con mèo"]],"bien":null,"vd":{"de":"Để phân loại 4 loài cá, chim, rùa, ếch bằng khóa lưỡng phân, bước đầu tiên nên dựa vào đặc điểm đối lập nào?","buoc":["Chọn một đặc điểm chia rõ hai nhóm, ví dụ có lông vũ hay không có lông vũ.","Chim tách riêng vì có lông vũ; cá, rùa, ếch còn lại không có lông vũ.","Tiếp tục chia nhỏ nhóm còn lại bằng đặc điểm khác cho đến khi nhận ra từng loài."],"kq":"Khóa lưỡng phân dùng nhiều cặp đặc điểm đối lập, chia dần thành nhóm nhỏ hơn."},"nham":["Chọn đặc điểm không đối lập (ví dụ \"có cánh\" và \"có chân\")."],"lq":["s6-phan-loai-the-gioi-song","s6-bac-phan-loai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-nam-gioi-sinh-vat","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":5,"loai":"kn","ten":"Năm giới sinh vật","ten_khac":["nam gioi sinh vat","5 gioi","gioi khoi sinh","gioi nguyen sinh","gioi nam","gioi thuc vat","gioi dong vat"],"noi_dung":"Sinh vật được chia thành 5 giới: Khởi sinh, Nguyên sinh, Nấm, Thực vật, Động vật.","cong_thuc":null,"y":["Tiêu chí: <b>loại tế bào</b> (nhân sơ/nhân thực), <b>mức độ tổ chức</b> (đơn bào/đa bào), <b>kiểu dinh dưỡng</b> (tự dưỡng/dị dưỡng).","Giới Khởi sinh gồm sinh vật nhân sơ; bốn giới còn lại là nhân thực."],"bang":[["Giới","Tế bào","Ví dụ"],["Khởi sinh","Nhân sơ, đơn bào","Vi khuẩn"],["Nguyên sinh","Nhân thực, chủ yếu đơn bào","Trùng roi, tảo"],["Nấm","Nhân thực, dị dưỡng","Nấm men, nấm rơm"],["Thực vật","Nhân thực, đa bào, tự dưỡng","Rêu, lúa"],["Động vật","Nhân thực, đa bào, dị dưỡng","Giun, cá, người"]],"bien":null,"vd":null,"nham":["Xếp virus vào giới Khởi sinh (virus chưa có cấu tạo tế bào, không thuộc 5 giới)."],"lq":["s6-phan-loai-the-gioi-song","s6-vi-khuan","s6-nguyen-sinh-vat","s6-nam","s6-thuc-vat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-virus","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":6,"loai":"ch","ten":"Virus","ten_khac":["virus","vi rut","virut","sieu vi","vo protein","ki sinh bat buoc"],"noi_dung":"Dạng sống rất nhỏ, chưa có cấu tạo tế bào, chỉ sống kí sinh bên trong tế bào sinh vật khác.","cong_thuc":null,"y":["Kích thước rất nhỏ, chỉ quan sát được bằng <b>kính hiển vi điện tử</b>.","Cấu tạo: <b>vỏ protein</b> và <b>phần lõi chứa vật chất di truyền</b>; một số có thêm vỏ ngoài.","Hình dạng: xoắn, khối, hỗn hợp.","Sống <b>kí sinh bắt buộc</b>: ra khỏi tế bào chủ thì không sinh sản được."],"bang":null,"bien":null,"vd":null,"nham":["Gọi virus là vi khuẩn (vi khuẩn có cấu tạo tế bào, virus thì không)."],"lq":["s6-benh-do-virus","s6-vaccine","s6-vi-khuan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-benh-do-virus","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":7,"loai":"ud","ten":"Bệnh do virus","ten_khac":["benh do virus","benh virus","cum","soi","thuy dau","quai bi","covid","phong benh virus"],"noi_dung":"Các bệnh do virus gây ra ở người, động vật, thực vật như cúm, sởi, thủy đậu, khảm lá.","cong_thuc":null,"y":["Ở người: <b>cúm, sởi, quai bị, thủy đậu, COVID-19, HIV/AIDS, dại</b>…","Ở cây: bệnh khảm lá (thuốc lá, cà chua…).","Phòng bệnh: <b>tiêm vaccine</b>, đeo khẩu trang, rửa tay, ăn uống đủ chất, tránh tiếp xúc nguồn bệnh."],"bang":null,"bien":null,"vd":{"de":"Một bạn học sinh sốt, phát ban, được chẩn đoán mắc bệnh thủy đậu. Bệnh do tác nhân nào gây ra và cần làm gì?","buoc":["Thủy đậu do virus gây ra, lây qua đường hô hấp và tiếp xúc dịch mụn nước.","Cần cách li, tránh tiếp xúc để không lây cho người khác."],"kq":"Nên nghỉ học, cách li cho đến khi khỏi hẳn."},"nham":["Dùng thuốc kháng sinh để chữa bệnh do virus (kháng sinh không diệt được virus)."],"lq":["s6-virus","s6-vaccine","s6-benh-do-vi-khuan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-vaccine","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":8,"loai":"ud","ten":"Vaccine","ten_khac":["vaccine","vac xin","vacxin","tiem chung","tiem phong","mien dich"],"noi_dung":"Chế phẩm sinh học giúp cơ thể tạo miễn dịch để phòng một bệnh nhất định.","cong_thuc":null,"y":["Thường được làm từ mầm bệnh <b>đã chết hoặc đã làm yếu</b> (hoặc thành phần của chúng).","Tiêm vaccine giúp cơ thể tạo <b>miễn dịch</b>, chống lại mầm bệnh khi bị nhiễm.","Tiêm đúng lịch, đủ mũi; theo dõi sức khỏe sau tiêm."],"bang":null,"bien":null,"vd":{"de":"Sau khi tiêm vaccine sởi, một thời gian sau em bé tiếp xúc với virus sởi nhưng không mắc bệnh. Vì sao?","buoc":["Vaccine chứa kháng nguyên đã làm yếu hoặc bất hoạt của virus sởi.","Cơ thể tạo kháng thể chống lại kháng nguyên đó và ghi nhớ để phản ứng nhanh."],"kq":"Cơ thể đã có miễn dịch với virus sởi nên không mắc bệnh."},"nham":["Nghĩ vaccine dùng để chữa bệnh (vaccine chủ yếu để phòng bệnh)."],"lq":["s6-virus","s6-benh-do-virus","s6-benh-do-vi-khuan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-vi-khuan","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":9,"loai":"ch","ten":"Vi khuẩn","ten_khac":["vi khuan","bacteria","khuan","nhan so","vi khuan co loi","song khuan","cau khuan"],"noi_dung":"Sinh vật đơn bào nhân sơ, rất nhỏ, sống ở khắp nơi: đất, nước, không khí, cơ thể sinh vật.","cong_thuc":null,"y":["Cấu tạo: thành tế bào, màng tế bào, tế bào chất, <b>vùng nhân</b>; nhiều loài có roi.","Hình dạng: <b>hình cầu, hình que, hình xoắn, hình dấu phẩy</b>.","Có lợi: phân giải xác sinh vật, làm sữa chua, muối dưa; một số gây bệnh."],"bang":null,"bien":null,"vd":null,"nham":["Cho rằng mọi vi khuẩn đều có hại."],"lq":["s6-te-bao-nhan-so","s6-benh-do-vi-khuan","s6-virus","s6-nam-gioi-sinh-vat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-benh-do-vi-khuan","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":10,"loai":"ud","ten":"Bệnh do vi khuẩn","ten_khac":["benh do vi khuan","benh vi khuan","lao","ta","thuong han","tieu chay","phong benh vi khuan"],"noi_dung":"Các bệnh do vi khuẩn gây ra như lao, tả, thương hàn, tiêu chảy, uốn ván.","cong_thuc":null,"y":["Ở người: <b>lao phổi, tả, thương hàn, tiêu chảy, uốn ván</b>…","Ở cây: bệnh héo xanh (cà chua, lạc), bệnh bạc lá lúa…","Phòng bệnh: <b>ăn chín uống sôi</b>, rửa tay, vệ sinh môi trường, tiêm phòng, bảo quản thực phẩm đúng cách."],"bang":null,"bien":null,"vd":{"de":"Vì sao ăn uống không hợp vệ sinh dễ khiến người ta mắc các bệnh như tả, thương hàn?","buoc":["Vi khuẩn gây bệnh có trong thức ăn, nước uống bẩn.","Vi khuẩn xâm nhập qua đường tiêu hóa, gây rối loạn tiêu hóa."],"kq":"Cần ăn chín, uống sôi để phòng các bệnh do vi khuẩn."},"nham":null,"lq":["s6-vi-khuan","s6-benh-do-virus","s6-vaccine"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-vai-tro-vi-khuan","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":11,"loai":"ud","ten":"Vai trò của vi khuẩn","ten_khac":["vai tro vi khuan","vi khuan co loi","sua chua","muoi dua","phan giai","nuoc mam"],"noi_dung":"Vi khuẩn vừa có lợi (phân giải chất hữu cơ, chế biến thực phẩm) vừa có hại (gây bệnh, làm hỏng thực phẩm).","cong_thuc":null,"y":["<b>Trong tự nhiên</b>: phân giải xác động vật, thực vật thành chất khoáng cho cây; một số vi khuẩn giúp đất thêm màu mỡ.","<b>Trong đời sống</b>: làm sữa chua, muối dưa, muối cà, sản xuất nước mắm, xử lí rác thải hữu cơ.","<b>Có hại</b>: gây bệnh cho người, động vật, thực vật; làm thức ăn ôi thiu."],"bang":null,"bien":null,"vd":{"de":"Vì sao để sữa tươi ở nhiệt độ phòng lâu ngày thì sữa bị chua và hỏng?","buoc":["Vi khuẩn trong sữa sinh sản rất nhanh ở nhiệt độ phòng.","Vi khuẩn biến đổi các chất trong sữa, làm sữa chua và hỏng."],"kq":"Do vi khuẩn phát triển mạnh; cần bảo quản sữa trong tủ lạnh."},"nham":["Cho rằng mọi vi khuẩn đều có hại."],"lq":["s6-vi-khuan","s6-benh-do-vi-khuan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-nguyen-sinh-vat","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":12,"loai":"ch","ten":"Nguyên sinh vật","ten_khac":["nguyen sinh vat","protista","gioi nguyen sinh","dong vat nguyen sinh","tao don bao"],"noi_dung":"Nhóm sinh vật nhân thực, phần lớn đơn bào, kích thước hiển vi, sống chủ yếu ở nước và nơi ẩm.","cong_thuc":null,"y":["Hình dạng đa dạng: hình cầu, hình giày, hình thoi, không cố định…","Có loài <b>tự dưỡng</b> (có lục lạp: tảo), có loài <b>dị dưỡng</b> (trùng giày, trùng biến hình).","Vai trò: tảo tạo oxygen, làm thức ăn cho động vật dưới nước; một số gây bệnh."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-trung-roi","s6-trung-giay","s6-trung-bien-hinh","s6-trung-sot-ret","s6-benh-do-nguyen-sinh-vat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-trung-roi","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":13,"loai":"ch","ten":"Trùng roi","ten_khac":["trung roi","trung roi xanh","euglena","roi boi","dim mat"],"noi_dung":"Nguyên sinh vật đơn bào có roi để di chuyển; trùng roi xanh có lục lạp.","cong_thuc":null,"y":["Di chuyển nhờ <b>roi</b>.","Trùng roi xanh có <b>lục lạp</b>: khi có ánh sáng tự tổng hợp chất hữu cơ; thiếu ánh sáng có thể dị dưỡng.","Sống ở ao, hồ, vũng nước."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-nguyen-sinh-vat","s6-trung-giay","s6-co-the-don-bao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-trung-giay","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":14,"loai":"ch","ten":"Trùng giày","ten_khac":["trung giay","paramecium","long boi","hinh chiec giay"],"noi_dung":"Nguyên sinh vật đơn bào hình chiếc giày, di chuyển bằng lông bơi, sống ở nước.","cong_thuc":null,"y":["Cơ thể hình <b>chiếc đế giày</b>, bề mặt phủ nhiều <b>lông bơi</b>.","Dị dưỡng: ăn vi khuẩn, vụn hữu cơ.","Thường gặp trong nước ao, nước ngâm rơm, cỏ khô."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-nguyen-sinh-vat","s6-trung-roi","s6-trung-bien-hinh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-trung-bien-hinh","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":15,"loai":"ch","ten":"Trùng biến hình","ten_khac":["trung bien hinh","amip","amoeba","chan gia"],"noi_dung":"Nguyên sinh vật đơn bào không có hình dạng cố định, di chuyển và bắt mồi bằng chân giả.","cong_thuc":null,"y":["Cơ thể luôn thay đổi hình dạng nhờ <b>chân giả</b>.","Dị dưỡng: dùng chân giả bao lấy thức ăn.","Sống ở ao, hồ, lớp bùn đáy."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-nguyen-sinh-vat","s6-trung-giay","s6-benh-do-nguyen-sinh-vat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-trung-sot-ret","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":16,"loai":"ch","ten":"Trùng sốt rét","ten_khac":["trung sot ret","plasmodium","sot ret","muoi anopheles","hong cau"],"noi_dung":"Nguyên sinh vật kí sinh trong máu người, gây bệnh sốt rét, truyền qua muỗi Anopheles.","cong_thuc":null,"y":["Kí sinh và phá hủy <b>hồng cầu</b> người.","Truyền bệnh qua vết đốt của <b>muỗi Anopheles</b> (muỗi sốt rét).","Phòng: <b>ngủ màn</b>, diệt muỗi, phát quang bụi rậm, khơi thông cống rãnh."],"bang":null,"bien":null,"vd":{"de":"Vì sao ở những nơi nhiều muỗi Anopheles, người dân được khuyến cáo ngủ màn để phòng sốt rét?","buoc":["Trùng sốt rét kí sinh trong máu người; muỗi Anopheles là vật trung gian truyền bệnh.","Muỗi đốt người bệnh rồi đốt sang người lành sẽ truyền trùng sốt rét."],"kq":"Ngủ màn, diệt muỗi giúp cắt đường lây truyền trùng sốt rét."},"nham":["Nghĩ muỗi gây bệnh sốt rét (muỗi chỉ là vật trung gian truyền bệnh)."],"lq":["s6-benh-do-nguyen-sinh-vat","s6-nguyen-sinh-vat","s6-trung-bien-hinh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-benh-do-nguyen-sinh-vat","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":17,"loai":"ud","ten":"Bệnh do nguyên sinh vật","ten_khac":["benh do nguyen sinh vat","sot ret","kiet li","kiet ly","trung kiet li"],"noi_dung":"Các bệnh do nguyên sinh vật gây ra ở người như sốt rét, kiết lị.","cong_thuc":null,"y":["<b>Sốt rét</b>: do trùng sốt rét, truyền qua muỗi Anopheles.","<b>Kiết lị</b>: do trùng kiết lị, lây qua thức ăn, nước uống nhiễm bẩn.","Phòng: ngủ màn, diệt muỗi; ăn chín uống sôi, rửa tay trước khi ăn."],"bang":null,"bien":null,"vd":{"de":"Ở nơi vệ sinh kém, nhiều người mắc bệnh kiết lị với triệu chứng đau bụng, đi ngoài ra máu. Nguyên nhân là gì?","buoc":["Bệnh kiết lị do một số nguyên sinh vật kí sinh ở ruột gây ra.","Chúng lây qua thức ăn, nước uống nhiễm bẩn."],"kq":"Ăn chín, uống sôi, rửa tay sạch giúp phòng bệnh kiết lị."},"nham":null,"lq":["s6-trung-sot-ret","s6-nguyen-sinh-vat","s6-benh-do-vi-khuan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-nam","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":18,"loai":"ch","ten":"Nấm","ten_khac":["nam","gioi nam","fungi","nam lon","nam moc","soi nam","bao tu nam"],"noi_dung":"Sinh vật nhân thực, đơn bào hoặc đa bào, sống dị dưỡng, không có diệp lục.","cong_thuc":null,"y":["<b>Đơn bào</b>: nấm men. <b>Đa bào</b>: nấm mốc, nấm rơm, nấm hương…","Nấm lớn gồm <b>mũ nấm, cuống nấm, sợi nấm</b>; sinh sản chủ yếu bằng <b>bào tử</b>.","Sống dị dưỡng: hoại sinh, kí sinh hoặc cộng sinh."],"bang":null,"bien":null,"vd":null,"nham":["Xếp nấm vào thực vật (nấm không có diệp lục, thuộc giới Nấm)."],"lq":["s6-nam-men","s6-nam-doc","s6-vai-tro-nam","s6-nam-gioi-sinh-vat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-nam-men","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":19,"loai":"ch","ten":"Nấm men","ten_khac":["nam men","men","men banh mi","men ruou","yeast","len men"],"noi_dung":"Nấm đơn bào, được dùng để làm bánh mì, nấu rượu, sản xuất bia.","cong_thuc":null,"y":["Cơ thể chỉ gồm <b>một tế bào</b> nhân thực.","Gây <b>lên men</b>: làm bột bánh mì nở, chuyển tinh bột, đường thành rượu."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-nam","s6-vai-tro-nam","s6-co-the-don-bao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-nam-doc","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":20,"loai":"ch","ten":"Nấm độc","ten_khac":["nam doc","ngo doc nam","nam doc do","nam la","nam moc doc"],"noi_dung":"Các loại nấm chứa chất độc, ăn phải có thể gây ngộ độc, thậm chí tử vong.","cong_thuc":null,"y":["Một số nấm độc có màu sặc sỡ, có vòng cuống, bao gốc; nhưng có nấm rất độc màu trắng, trông giống nấm ăn.","Tuyệt đối <b>không ăn nấm lạ</b>, nấm mọc hoang không rõ nguồn gốc.","Không ăn thực phẩm bị mốc (lạc, ngô mốc…) vì nấm mốc có thể sinh chất độc."],"bang":null,"bien":null,"vd":{"de":"Một gia đình hái nấm lạ trong rừng về nấu ăn và bị ngộ độc nặng. Bài học rút ra là gì?","buoc":["Nhiều nấm độc có hình dạng rất giống nấm ăn được, khó phân biệt bằng mắt.","Ăn nhầm nấm độc có thể gây ngộ độc nặng, nguy hiểm tính mạng."],"kq":"Không tự ý hái nấm mọc hoang để ăn khi chưa chắc chắn là nấm lành."},"nham":["Tin rằng nấu kĩ sẽ làm mất độc của nấm độc.","Nghĩ nấm độc luôn có màu sặc sỡ, nấm màu trắng thì ăn được."],"lq":["s6-nam","s6-vai-tro-nam"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-vai-tro-nam","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":21,"loai":"ud","ten":"Vai trò của nấm","ten_khac":["vai tro cua nam","loi ich cua nam","tac hai cua nam","benh do nam","nam an","penicillin","hac lao"],"noi_dung":"Nấm có lợi (thức ăn, dược liệu, phân giải xác) nhưng cũng gây bệnh, gây hư hỏng thực phẩm.","cong_thuc":null,"y":["Lợi ích: làm thức ăn (nấm rơm, mộc nhĩ, nấm hương), dược liệu (linh chi), làm bánh mì, rượu, sản xuất <b>kháng sinh penicillin</b>.","Phân giải xác sinh vật thành chất đơn giản trả lại cho đất.","Tác hại: gây bệnh <b>hắc lào, lang ben</b> ở người, bệnh ở cây; làm mốc hỏng thực phẩm."],"bang":null,"bien":null,"vd":{"de":"Bánh mì nở xốp nhờ nấm men, nhưng ăn nhầm nấm mọc hoang trong rừng có thể gây ngộ độc. Vì sao cùng là nấm mà vai trò khác nhau?","buoc":["Nấm men là nấm có lợi, dùng để lên men làm nở bánh.","Một số nấm hoang dại chứa độc tố, không phải nấm nào cũng ăn được."],"kq":"Chỉ dùng nấm đã biết rõ là nấm lành, không ăn nấm lạ."},"nham":null,"lq":["s6-nam","s6-nam-men","s6-nam-doc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-thuc-vat","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":22,"loai":"ch","ten":"Thực vật","ten_khac":["thuc vat","gioi thuc vat","cay xanh","plant","cac nganh thuc vat"],"noi_dung":"Sinh vật nhân thực, đa bào, có lục lạp, tự tổng hợp chất hữu cơ nhờ quang hợp.","cong_thuc":null,"y":["Tế bào có <b>thành cellulose</b> và <b>lục lạp</b>; sống <b>tự dưỡng</b>, phần lớn không di chuyển.","Bốn nhóm chính: <b>Rêu, Dương xỉ, Hạt trần, Hạt kín</b>.","Chia thành thực vật <b>không có mạch</b> (Rêu) và <b>có mạch</b> (các nhóm còn lại)."],"bang":[["Nhóm","Mạch dẫn","Sinh sản bằng","Hoa, quả"],["Rêu","Không","Bào tử","Không"],["Dương xỉ","Có","Bào tử","Không"],["Hạt trần","Có","Hạt (trên nón)","Không"],["Hạt kín","Có","Hạt (trong quả)","Có"]],"bien":null,"vd":null,"nham":null,"lq":["s6-reu","s6-duong-xi","s6-hat-tran","s6-hat-kin","s6-vai-tro-thuc-vat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-reu","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":23,"loai":"ch","ten":"Rêu","ten_khac":["reu","cay reu","nganh reu","re gia","thuc vat khong mach"],"noi_dung":"Nhóm thực vật nhỏ, sống nơi ẩm, có rễ giả, chưa có mạch dẫn, sinh sản bằng bào tử.","cong_thuc":null,"y":["Có thân, lá nhỏ và <b>rễ giả</b>; <b>chưa có mạch dẫn</b>.","Sinh sản bằng <b>bào tử</b> nằm trong túi bào tử ở ngọn cây.","Sống ở nơi <b>ẩm ướt</b>: chân tường, gốc cây, đá ẩm."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-thuc-vat","s6-duong-xi","s6-hat-tran"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-duong-xi","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":24,"loai":"ch","ten":"Dương xỉ","ten_khac":["duong xi","cay duong xi","nganh duong xi","tui bao tu","la non cuon tron","rau bo"],"noi_dung":"Nhóm thực vật có rễ thật, có mạch dẫn, chưa có hạt, sinh sản bằng bào tử.","cong_thuc":null,"y":["Có <b>rễ thật, thân, lá</b> và <b>mạch dẫn</b>.","Lá non thường <b>cuộn tròn</b> ở đầu.","Túi bào tử nằm ở <b>mặt dưới lá</b>; sinh sản bằng bào tử."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ dương xỉ sinh sản bằng hạt."],"lq":["s6-thuc-vat","s6-reu","s6-hat-tran"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-hat-tran","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":25,"loai":"ch","ten":"Hạt trần","ten_khac":["hat tran","cay hat tran","nganh hat tran","cay thong","van tue","non"],"noi_dung":"Nhóm thực vật có mạch, sinh sản bằng hạt nằm lộ trên lá noãn hở, chưa có hoa và quả.","cong_thuc":null,"y":["Cơ quan sinh sản là <b>nón</b>; <b>chưa có hoa, quả</b>.","Hạt nằm lộ trên các lá noãn hở (không được bao kín).","Ví dụ: <b>thông, vạn tuế, pơ mu, kim giao</b>."],"bang":null,"bien":null,"vd":null,"nham":["Gọi \"nón thông\" là quả thông (thực chất là nón, chưa phải quả)."],"lq":["s6-thuc-vat","s6-hat-kin","s6-duong-xi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-hat-kin","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":26,"loai":"ch","ten":"Hạt kín","ten_khac":["hat kin","cay hat kin","nganh hat kin","thuc vat co hoa","co hoa co qua"],"noi_dung":"Nhóm thực vật có hoa, quả; hạt được bảo vệ trong quả; đa dạng và tiến hóa nhất.","cong_thuc":null,"y":["Có <b>hoa, quả</b>; hạt nằm <b>trong quả</b>.","Mạch dẫn phát triển; rễ, thân, lá đa dạng.","Ví dụ: lúa, ngô, cam, bưởi, hoa hồng, cây bàng."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-thuc-vat","s6-hat-tran","s6-vai-tro-thuc-vat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-vai-tro-thuc-vat","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":27,"loai":"ud","ten":"Vai trò của thực vật","ten_khac":["vai tro cua thuc vat","loi ich cua cay xanh","dieu hoa khi hau","chong xoi mon","trong rung","bao ve rung"],"noi_dung":"Thực vật điều hòa khí hậu, bảo vệ đất và nước, cung cấp thức ăn, nơi ở cho sinh vật và con người.","cong_thuc":null,"y":["Quang hợp: hấp thụ <b>carbon dioxide</b>, thải <b>oxygen</b>, góp phần điều hòa khí hậu.","Rễ giữ đất: <b>chống xói mòn, sạt lở, lũ lụt</b>, giữ nguồn nước ngầm.","Là thức ăn, nơi ở cho động vật; cung cấp lương thực, gỗ, dược liệu cho con người."],"bang":null,"bien":null,"vd":{"de":"Ở khu vực rừng bị chặt phá nhiều, đất dễ bị xói mòn và xảy ra lũ quét khi mưa lớn. Vì sao?","buoc":["Rễ cây giữ đất, tán lá và thân cây cản bớt sức nước mưa.","Mất rừng khiến đất không được giữ, nước mưa chảy nhanh trên mặt đất."],"kq":"Mất rừng làm tăng nguy cơ xói mòn đất và lũ quét."},"nham":["Nghĩ cây xanh chỉ thải oxygen (cây vẫn hô hấp, thải carbon dioxide)."],"lq":["s6-thuc-vat","s6-hat-kin","s6-da-dang-sinh-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-dong-vat","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":28,"loai":"ch","ten":"Động vật","ten_khac":["dong vat","gioi dong vat","animal","cac nhom dong vat","phan loai dong vat"],"noi_dung":"Sinh vật nhân thực, đa bào, dị dưỡng, phần lớn có khả năng di chuyển.","cong_thuc":null,"y":["Tế bào không có thành tế bào, không có lục lạp.","Dựa vào <b>xương sống</b>, chia thành động vật <b>không xương sống</b> và <b>có xương sống</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-dong-vat-khong-xuong-song","s6-dong-vat-co-xuong-song","s6-vai-tro-dong-vat","s6-nam-gioi-sinh-vat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-dong-vat-khong-xuong-song","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":29,"loai":"ch","ten":"Động vật không xương sống","ten_khac":["dong vat khong xuong song","khong xuong song","dvkxs","invertebrate"],"noi_dung":"Nhóm động vật không có xương sống: Ruột khoang, Giun, Thân mềm, Chân khớp.","cong_thuc":null,"y":["Cơ thể không có <b>bộ xương trong</b> với cột sống.","Gồm các nhóm: <b>Ruột khoang, Giun, Thân mềm, Chân khớp</b>.","Chiếm phần lớn số loài động vật."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-ruot-khoang","s6-giun","s6-than-mem","s6-chan-khop","s6-dong-vat-co-xuong-song"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-ruot-khoang","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":30,"loai":"ch","ten":"Ruột khoang","ten_khac":["ruot khoang","thuy tuc","sua","hai quy","san ho","doi xung toa tron"],"noi_dung":"Nhóm động vật không xương sống sống ở nước, cơ thể đối xứng tỏa tròn, ruột dạng túi.","cong_thuc":null,"y":["Cơ thể <b>đối xứng tỏa tròn</b>, <b>ruột dạng túi</b>, có tua miệng.","Hầu hết sống ở biển.","Ví dụ: <b>thủy tức, sứa, hải quỳ, san hô</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-dong-vat-khong-xuong-song","s6-giun","s6-than-mem"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-giun","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":31,"loai":"ch","ten":"G