null,"nguon":["KHTN Pocket"]},{"ma":"s6-bo-sat","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":37,"loai":"ch","ten":"Bò sát","ten_khac":["bo sat","lop bo sat","than lan","ran","rua","ca sau","vay sung"],"noi_dung":"Động vật có xương sống có da khô phủ vảy sừng, đẻ trứng, thích nghi đời sống ở cạn.","cong_thuc":null,"y":["<b>Da khô, có vảy sừng</b>; thở bằng phổi.","Ví dụ: <b>thằn lằn, rắn, rùa, cá sấu</b>."],"bang":null,"bien":null,"vd":null,"nham":["Xếp cá sấu vào lớp Cá."],"lq":["s6-dong-vat-co-xuong-song","s6-luong-cu","s6-chim"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-chim","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":38,"loai":"ch","ten":"Chim","ten_khac":["chim","lop chim","long vu","canh","mo sung","chim canh cut","da dieu"],"noi_dung":"Động vật có xương sống có lông vũ, chi trước biến thành cánh, có mỏ sừng, đẻ trứng.","cong_thuc":null,"y":["Cơ thể phủ <b>lông vũ</b>, <b>chi trước biến thành cánh</b>, có <b>mỏ sừng</b>.","Đa số biết bay; một số không bay được: <b>đà điểu, chim cánh cụt</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-dong-vat-co-xuong-song","s6-bo-sat","s6-thu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-thu","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":39,"loai":"ch","ten":"Thú (Động vật có vú)","ten_khac":["thu","lop thu","dong vat co vu","co vu","long mao","nuoi con bang sua","ca voi","doi"],"noi_dung":"Động vật có xương sống có lông mao, đẻ con và nuôi con bằng sữa mẹ.","cong_thuc":null,"y":["Cơ thể phủ <b>lông mao</b>; răng phân hóa.","Hầu hết <b>đẻ con</b>, nuôi con bằng <b>sữa</b>; thú mỏ vịt đẻ trứng nhưng vẫn nuôi con bằng sữa.","Ví dụ: chó, mèo, trâu, <b>dơi</b> (biết bay), <b>cá voi</b> (sống dưới nước)."],"bang":null,"bien":null,"vd":null,"nham":["Xếp dơi vào Chim, cá voi vào Cá."],"lq":["s6-dong-vat-co-xuong-song","s6-chim","s6-ca"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-vai-tro-dong-vat","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":40,"loai":"ud","ten":"Vai trò của động vật","ten_khac":["vai tro cua dong vat","loi ich cua dong vat","tac hai cua dong vat","dong vat co hai","truyen benh"],"noi_dung":"Động vật cung cấp thực phẩm, nguyên liệu, sức kéo; một số gây hại, truyền bệnh.","cong_thuc":null,"y":["Lợi ích: thực phẩm (thịt, trứng, sữa), dược liệu, sức kéo, làm cảnh, thụ phấn cho cây (ong, bướm).","Tác hại: phá hoại mùa màng (châu chấu, chuột), <b>truyền bệnh</b> (muỗi, ruồi, chuột), kí sinh (giun, sán)."],"bang":null,"bien":null,"vd":{"de":"Ong không chỉ cho mật mà còn giúp nhiều cây ăn quả đậu quả nhiều hơn. Vì sao?","buoc":["Ong bay từ hoa này sang hoa khác lấy mật, mang theo hạt phấn.","Nhờ đó hoa được thụ phấn, tăng khả năng tạo quả và hạt."],"kq":"Ong có vai trò giúp thụ phấn cho cây, không chỉ cho mật."},"nham":null,"lq":["s6-dong-vat","s6-chan-khop","s6-da-dang-sinh-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-da-dang-sinh-hoc","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":41,"loai":"kn","ten":"Đa dạng sinh học","ten_khac":["da dang sinh hoc","dang sinh hoc","biodiversity","da dang loai","rung mua nhiet doi"],"noi_dung":"Sự phong phú về số lượng loài, số cá thể trong loài và môi trường sống của sinh vật.","cong_thuc":null,"y":["Thể hiện ở <b>số lượng loài</b> và sự đa dạng <b>môi trường sống</b>.","<b>Rừng mưa nhiệt đới</b> có đa dạng sinh học cao; hoang mạc, vùng cực thấp.","Vai trò: giữ cân bằng tự nhiên; cung cấp thức ăn, thuốc, nguyên liệu cho con người."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s6-bao-ve-da-dang-sinh-hoc","s6-vai-tro-thuc-vat","s6-vai-tro-dong-vat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-da-dang-cac-moi-truong","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":42,"loai":"kn","ten":"Đa dạng sinh học theo môi trường","ten_khac":["da dang moi truong","hoang mac","rung mua nhiet doi","rung nhiet doi","thich nghi"],"noi_dung":"Mỗi môi trường có mức độ đa dạng sinh học khác nhau; rừng mưa nhiệt đới đa dạng hơn nhiều so với hoang mạc.","cong_thuc":null,"y":["<b>Rừng mưa nhiệt đới</b>: nóng ẩm, nhiều nước, có rất nhiều loài sinh vật.","<b>Hoang mạc</b>: khô hạn, nhiệt độ ngày và đêm chênh lệch lớn, ít loài; sinh vật có đặc điểm thích nghi như lá biến thành gai, thân dự trữ nước.","Điều kiện sống càng thuận lợi thì số loài càng nhiều."],"bang":null,"bien":null,"vd":{"de":"Vì sao ở hoang mạc có ít loài sinh vật hơn ở rừng mưa nhiệt đới?","buoc":["Hoang mạc rất khô hạn, nhiệt độ ngày và đêm chênh lệch lớn.","Chỉ ít loài có đặc điểm thích nghi được với điều kiện khắc nghiệt đó."],"kq":"Điều kiện sống khắc nghiệt nên số loài ở hoang mạc ít hơn."},"nham":null,"lq":["s6-da-dang-sinh-hoc","s6-bao-ve-da-dang-sinh-hoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s6-bao-ve-da-dang-sinh-hoc","mon":"KHTN","khoi":"6","chu_de":"s6-da-dang","thu_tu":43,"loai":"ud","ten":"Bảo vệ đa dạng sinh học","ten_khac":["bao ve da dang sinh hoc","bao ton","vuon quoc gia","khu bao ton","sach do","san bat trai phep"],"noi_dung":"Các biện pháp giữ gìn sự phong phú của sinh vật: bảo vệ rừng, cấm săn bắt trái phép, lập khu bảo tồn.","cong_thuc":null,"y":["Nguyên nhân suy giảm: phá rừng, <b>săn bắt, buôn bán trái phép</b>, ô nhiễm môi trường.","Biện pháp: trồng cây gây rừng, lập <b>vườn quốc gia, khu bảo tồn</b>, đưa loài quý hiếm vào <b>Sách Đỏ</b>.","Học sinh: không săn bắt, mua bán động vật hoang dã; tuyên truyền bảo vệ môi trường."],"bang":null,"bien":null,"vd":{"de":"Vì sao khai thác gỗ và săn bắt thú rừng trái phép lại làm giảm đa dạng sinh học?","buoc":["Chặt rừng phá mất môi trường sống của nhiều loài sinh vật.","Săn bắt quá mức làm số cá thể và số loài giảm dần, có thể tuyệt chủng."],"kq":"Cần bảo vệ rừng, cấm săn bắt trái phép để giữ đa dạng sinh học."},"nham":null,"lq":["s6-da-dang-sinh-hoc","s6-vai-tro-thuc-vat","s6-vai-tro-dong-vat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-trao-doi-chat","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":1,"loai":"ht","ten":"Trao đổi chất","ten_khac":["trao doi chat","tdc","trao doi chat o sinh vat","metabolism","lay chat thai chat"],"noi_dung":"Quá trình sinh vật lấy các chất từ môi trường, biến đổi chúng trong cơ thể và thải chất không cần thiết ra môi trường.","cong_thuc":null,"y":["Gồm: <b>lấy vào</b> (thức ăn, nước, oxygen…) → <b>biến đổi</b> trong tế bào → <b>thải ra</b> (carbon dioxide, chất thải…).","Luôn đi kèm <b>chuyển hóa năng lượng</b>.","Vai trò: cung cấp nguyên liệu xây dựng cơ thể và năng lượng cho mọi hoạt động sống; ngừng trao đổi chất thì sinh vật chết."],"bang":null,"bien":null,"vd":null,"nham":["Coi trao đổi chất chỉ là ăn uống: còn gồm biến đổi chất trong tế bào và thải chất ra ngoài."],"lq":["s7-chuyen-hoa-nang-luong","s7-quang-hop","s7-ho-hap-te-bao","s7-the-thong-nhat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-chuyen-hoa-nang-luong","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":2,"loai":"ht","ten":"Chuyển hóa năng lượng","ten_khac":["chuyen hoa nang luong","chuyen hoa","bien doi nang luong","quang nang hoa nang","nang luong sinh vat"],"noi_dung":"Sự biến đổi năng lượng từ dạng này sang dạng khác trong cơ thể sinh vật.","cong_thuc":null,"y":["Ví dụ ở cây xanh: <b>quang năng → hóa năng</b> (tích lũy trong chất hữu cơ nhờ quang hợp).","Hóa năng trong chất hữu cơ được giải phóng qua hô hấp, chuyển thành năng lượng cho hoạt động sống (cơ năng, nhiệt năng…).","Trao đổi chất và chuyển hóa năng lượng luôn gắn liền với nhau."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s7-trao-doi-chat","s7-quang-hop","s7-ho-hap-te-bao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-quang-hop","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":3,"loai":"ht","ten":"Quang hợp","ten_khac":["quang hop","qh","photosynthesis","tong hop chat huu co","cay che tao tinh bot","nuoc carbon dioxide glucose oxygen"],"noi_dung":"Quá trình lá cây dùng nước, carbon dioxide và năng lượng ánh sáng (nhờ diệp lục) để tổng hợp glucose, giải phóng oxygen.","cong_thuc":null,"y":["Phương trình chữ: <b>Nước + Carbon dioxide → Glucose + Oxygen</b> (điều kiện: ánh sáng, diệp lục).","Diễn ra chủ yếu ở <b>lá</b>, trong lục lạp của tế bào.","Năng lượng: quang năng chuyển thành hóa năng tích lũy trong chất hữu cơ.","Vai trò: tạo chất hữu cơ nuôi sinh vật, cung cấp oxygen, giảm carbon dioxide trong không khí."],"bang":null,"bien":null,"vd":{"de":"Cho cành rong đuôi chó vào cốc nước, để chỗ có ánh sáng thì thấy có bọt khí thoát ra; để cốc tương tự vào chỗ tối thì không có bọt khí. Giải thích.","buoc":["Bọt khí thoát ra là oxygen sinh ra từ quang hợp.","Quang hợp cần ánh sáng; không có ánh sáng thì cây không quang hợp được."],"kq":"Ở chỗ tối rong không quang hợp nên không có bọt khí oxygen thoát ra."},"nham":["Cây lấy oxygen để quang hợp → SAI: quang hợp lấy carbon dioxide, thải oxygen.","Nhầm quang hợp với hô hấp: hô hấp mới là quá trình phân giải chất hữu cơ."],"lq":["s7-diep-luc","s7-la-cay","s7-yeu-to-quang-hop","s7-ho-hap-te-bao","s7-tn-quang-hop"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-diep-luc","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":4,"loai":"ch","ten":"Diệp lục","ten_khac":["diep luc","chat diep luc","chlorophyll","sac to xanh","mau xanh cua la"],"noi_dung":"Sắc tố màu xanh lục nằm trong lục lạp, có khả năng hấp thụ năng lượng ánh sáng để cây quang hợp.","cong_thuc":null,"y":["Có trong <b>lục lạp</b> của tế bào thịt lá (và phần xanh của thân non).","Làm lá có màu xanh.","Không có diệp lục thì không quang hợp được."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm diệp lục (chất) với lục lạp (bào quan chứa diệp lục)."],"lq":["s7-quang-hop","s7-la-cay"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-la-cay","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":5,"loai":"cq","ten":"Lá – cơ quan quang hợp","ten_khac":["la cay","la","phien la","gan la","cau tao la","co quan quang hop"],"noi_dung":"Lá là cơ quan quang hợp chủ yếu của cây, có cấu tạo phù hợp để thu nhận ánh sáng và trao đổi khí.","cong_thuc":null,"y":["Các lá trên cây thường xếp so le để nhận được nhiều ánh sáng.","Lá còn là nơi trao đổi khí và thoát hơi nước."],"bang":[["Bộ phận","Vai trò"],["Phiến lá rộng, mỏng","Thu nhận nhiều ánh sáng"],["Lục lạp (chứa diệp lục)","Hấp thụ ánh sáng, nơi quang hợp"],["Khí khổng","Cho carbon dioxide vào, oxygen và hơi nước ra"],["Gân lá","Dẫn nước tới lá, dẫn chất hữu cơ đi khắp cây"]],"bien":null,"vd":null,"nham":null,"lq":["s7-quang-hop","s7-diep-luc","s7-khi-khong","s7-thoat-hoi-nuoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-khi-khong","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":6,"loai":"cq","ten":"Khí khổng","ten_khac":["khi khong","lo khi","stomata","te bao hinh hat dau","khi khong o la"],"noi_dung":"Lỗ nhỏ trên biểu bì lá, do hai tế bào hình hạt đậu tạo nên, là nơi trao đổi khí và thoát hơi nước.","cong_thuc":null,"y":["Gồm <b>hai tế bào hình hạt đậu</b> áp sát nhau, ở giữa là lỗ khí.","Thường có nhiều ở <b>mặt dưới lá</b>.","Khí khổng mở: carbon dioxide, oxygen, hơi nước đi qua; đóng lại khi cây thiếu nước để hạn chế mất nước."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ khí khổng chỉ cho khí đi qua: hơi nước cũng thoát ra chủ yếu qua khí khổng."],"lq":["s7-trao-doi-khi","s7-thoat-hoi-nuoc","s7-la-cay"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-yeu-to-quang-hop","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":7,"loai":"kn","ten":"Yếu tố ảnh hưởng quang hợp","ten_khac":["yeu to anh huong quang hop","anh sang","nhiet do","nuoc","carbon dioxide","co2","dieu kien quang hop"],"noi_dung":"Quang hợp chịu ảnh hưởng của ánh sáng, nước, hàm lượng carbon dioxide và nhiệt độ.","cong_thuc":null,"y":["Mỗi yếu tố có một <b>khoảng thuận lợi</b>: thiếu hoặc vượt quá đều làm quang hợp giảm.","Cây ưa sáng cần nhiều ánh sáng; cây ưa bóng cần ít ánh sáng.","Thiếu nước: khí khổng đóng, ít carbon dioxide vào lá, quang hợp giảm.","Vận dụng: trồng đúng mật độ, đúng thời vụ, tưới nước hợp lí."],"bang":null,"bien":null,"vd":null,"nham":["Ánh sáng càng mạnh quang hợp càng tăng mãi → SAI: đến một mức thì không tăng nữa, quá mạnh còn gây hại."],"lq":["s7-quang-hop","s7-khi-khong","s7-yeu-to-ho-hap"],"hinh":"H-s7-yeu-to-quang-hop","nguon":["KHTN Pocket"]},{"ma":"s7-tn-quang-hop","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":8,"loai":"tn","ten":"Thí nghiệm quang hợp","ten_khac":["thi nghiem quang hop","thu tinh bot","iodine","iot","che la giay den","rong duoi cho","que dom"],"noi_dung":"Thí nghiệm chứng minh lá cây tạo tinh bột khi có ánh sáng và quang hợp giải phóng oxygen.","cong_thuc":null,"y":["<b>Tinh bột:</b> để cây trong tối 2 ngày, che một phần lá bằng giấy đen rồi để ngoài sáng.","Ngắt lá, tẩy diệp lục bằng cồn, nhỏ iodine: phần không che có màu xanh tím, phần bị che không đổi màu.","<b>Oxygen:</b> cành rong trong nước để ngoài sáng tạo bọt khí; khí thu được làm que đóm còn tàn đỏ bùng cháy.","Phải có mẫu đối chứng (phần lá bị che, cành rong để trong tối)."],"bang":null,"bien":null,"vd":{"de":"Để chứng minh lá cây tạo tinh bột khi quang hợp, người ta thử lá bằng dung dịch iodine. Nếu lá có quang hợp thì hiện tượng gì xảy ra?","buoc":["Tinh bột gặp dung dịch iodine chuyển sang màu xanh tím.","Lá đã quang hợp và tạo tinh bột sẽ bắt màu xanh tím khi nhỏ iodine."],"kq":"Phần lá có quang hợp chuyển màu xanh tím với thuốc thử iodine."},"nham":["Nhầm phần lá bị che (đối chứng) với phần lá được chiếu sáng."],"lq":["s7-quang-hop","s7-yeu-to-quang-hop"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-ho-hap-te-bao","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":9,"loai":"ht","ten":"Hô hấp tế bào","ten_khac":["ho hap te bao","ho hap","phan giai glucose","cellular respiration","atp","giai phong nang luong"],"noi_dung":"Quá trình phân giải chất hữu cơ (chủ yếu là glucose) trong tế bào để giải phóng năng lượng cho hoạt động sống.","cong_thuc":null,"y":["Phương trình chữ: <b>Glucose + Oxygen → Carbon dioxide + Nước + Năng lượng</b> (ATP, nhiệt).","Diễn ra chủ yếu ở <b>ti thể</b>, ở mọi tế bào sống, cả ngày lẫn đêm.","Thí nghiệm: hạt nảy mầm thải carbon dioxide (làm nước vôi trong vẩn đục) và tỏa nhiệt."],"bang":[["","Quang hợp","Hô hấp tế bào"],["Nguyên liệu","Nước, carbon dioxide","Glucose, oxygen"],["Sản phẩm","Glucose, oxygen","Carbon dioxide, nước"],["Năng lượng","Tích lũy","Giải phóng"],["Nơi diễn ra","Lục lạp","Ti thể"]],"bien":null,"vd":{"de":"Đổ hạt đậu đang nảy mầm vào bình kín, cắm nhiệt kế vào, sau một thời gian thấy nhiệt độ trong bình tăng lên. Giải thích.","buoc":["Hạt nảy mầm hô hấp tế bào mạnh để lấy năng lượng cho sinh trưởng.","Một phần năng lượng giải phóng dưới dạng nhiệt, làm nóng bình."],"kq":"Nhiệt độ trong bình tăng do hô hấp tế bào của hạt tỏa nhiệt."},"nham":["Nhầm hô hấp tế bào với hít thở (trao đổi khí).","Cây chỉ hô hấp ban đêm → SAI: cây hô hấp cả ngày lẫn đêm."],"lq":["s7-ti-the","s7-quang-hop","s7-yeu-to-ho-hap","s7-trao-doi-khi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-ti-the","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":10,"loai":"cq","ten":"Ti thể","ten_khac":["ti the","ty the","mitochondria","nha may nang luong","bao quan ho hap"],"noi_dung":"Bào quan là nơi diễn ra chủ yếu quá trình hô hấp tế bào, tạo năng lượng cho tế bào.","cong_thuc":null,"y":["Có ở cả tế bào thực vật và tế bào động vật.","Được ví như \"nhà máy năng lượng\" của tế bào.","Tế bào hoạt động nhiều (như tế bào cơ) thường có nhiều ti thể."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm ti thể (hô hấp) với lục lạp (quang hợp)."],"lq":["s7-ho-hap-te-bao","s7-quang-hop"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-yeu-to-ho-hap","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":11,"loai":"kn","ten":"Yếu tố ảnh hưởng hô hấp","ten_khac":["yeu to anh huong ho hap","nhiet do","do am","nuoc","oxygen","carbon dioxide","dieu kien ho hap"],"noi_dung":"Hô hấp tế bào chịu ảnh hưởng của nhiệt độ, hàm lượng nước, nồng độ oxygen và carbon dioxide.","cong_thuc":null,"y":["<b>Nhiệt độ:</b> trong khoảng thích hợp, nhiệt độ tăng thì hô hấp tăng; quá cao hoặc quá thấp thì hô hấp giảm.","<b>Nước:</b> hạt khô hô hấp rất yếu, hạt ẩm hô hấp mạnh.","<b>Khí:</b> thiếu oxygen hoặc nhiều carbon dioxide thì hô hấp giảm."],"bang":null,"bien":null,"vd":null,"nham":["Tăng oxygen để bảo quản nông sản → SAI: phải giảm oxygen, tăng carbon dioxide."],"lq":["s7-ho-hap-te-bao","s7-bao-quan-nong-san","s7-yeu-to-quang-hop"],"hinh":"H-s7-yeu-to-ho-hap","nguon":["KHTN Pocket"]},{"ma":"s7-bao-quan-nong-san","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":12,"loai":"ud","ten":"Bảo quản nông sản","ten_khac":["bao quan nong san","bao quan lanh","bao quan kho","phoi kho hat","giam ho hap","bao quan hat"],"noi_dung":"Làm giảm hô hấp của nông sản để hạn chế tiêu hao chất hữu cơ, giữ nông sản được lâu.","cong_thuc":null,"y":["<b>Bảo quản lạnh:</b> rau, quả, thịt, cá để tủ lạnh.","<b>Bảo quản khô:</b> phơi khô hạt trước khi cất.","<b>Bảo quản kín / tăng carbon dioxide:</b> giảm oxygen để hô hấp chậm lại."],"bang":null,"bien":null,"vd":{"de":"Vì sao phải phơi thật khô thóc trước khi cất vào kho?","buoc":["Hạt khô chứa ít nước nên hô hấp rất yếu.","Hô hấp yếu → ít tiêu hao chất hữu cơ, ít tỏa nhiệt, hạt không bị nóng, mốc."],"kq":"Thóc giữ được lâu, ít hao hụt."},"nham":null,"lq":["s7-yeu-to-ho-hap","s7-ho-hap-te-bao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-trao-doi-khi","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":13,"loai":"ht","ten":"Trao đổi khí","ten_khac":["trao doi khi","trao doi khi o thuc vat","khi vao khi ra","gas exchange","o2 co2"],"noi_dung":"Sự trao đổi các chất khí giữa cơ thể và môi trường: lấy khí cần thiết vào, thải khí không cần ra.","cong_thuc":null,"y":["Ở thực vật, trao đổi khí diễn ra chủ yếu qua <b>khí khổng</b> của lá.","Ban ngày: quang hợp mạnh hơn hô hấp nên lá lấy carbon dioxide, thải oxygen.","Ban đêm: chỉ hô hấp nên lá lấy oxygen, thải carbon dioxide."],"bang":[["Quá trình","Khí vào lá","Khí ra khỏi lá"],["Quang hợp","Carbon dioxide","Oxygen"],["Hô hấp","Oxygen","Carbon dioxide"]],"bien":null,"vd":null,"nham":["Ban đêm lá vẫn thải oxygen → SAI: không có ánh sáng thì không quang hợp."],"lq":["s7-khi-khong","s7-trao-doi-khi-dong-vat","s7-quang-hop","s7-ho-hap-te-bao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-trao-doi-khi-dong-vat","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":14,"loai":"ht","ten":"Trao đổi khí ở động vật","ten_khac":["trao doi khi o dong vat","ho hap qua da","mang","ong khi","phoi","phe nang","duong di cua khi"],"noi_dung":"Động vật lấy oxygen và thải carbon dioxide qua bề mặt cơ thể, mang, hệ thống ống khí hoặc phổi.","cong_thuc":null,"y":["Ở người, khí đi qua: mũi → họng → thanh quản → khí quản → phế quản → phổi (phế nang).","Tại phế nang: oxygen đi vào máu, carbon dioxide từ máu đi ra."],"bang":[["Động vật","Cơ quan trao đổi khí"],["Giun đất","Da"],["Cá","Mang"],["Côn trùng","Hệ thống ống khí"],["Chim, thú, người","Phổi"]],"bien":null,"vd":{"de":"Vì sao khi nuôi cá trong bể kín, người ta thường lắp máy sục khí?","buoc":["Cá trao đổi khí qua mang, lấy oxygen hòa tan trong nước.","Bể kín, nước ít xáo trộn nên oxygen hòa tan dễ giảm."],"kq":"Sục khí giúp bổ sung oxygen hòa tan để cá hô hấp tốt."},"nham":["Cá thở bằng phổi → SAI: cá trao đổi khí qua mang.","Nhầm khí quản (dẫn khí) với thực quản (dẫn thức ăn)."],"lq":["s7-trao-doi-khi","s7-tuan-hoan","s7-ho-hap-te-bao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-vai-tro-cua-nuoc","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":15,"loai":"kn","ten":"Vai trò của nước","ten_khac":["vai tro cua nuoc","nuoc voi sinh vat","nuoc trong co the","dung moi","dieu hoa nhiet"],"noi_dung":"Nước là thành phần chủ yếu của tế bào, là dung môi hòa tan và vận chuyển các chất, giúp điều hòa nhiệt độ.","cong_thuc":null,"y":["Là thành phần cấu tạo chủ yếu của tế bào và cơ thể.","Là <b>dung môi</b> hòa tan, vận chuyển chất dinh dưỡng và chất thải.","Tham gia các quá trình sống (ví dụ nguyên liệu của quang hợp); giúp điều hòa nhiệt độ cơ thể."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s7-trao-doi-nuoc-thuc-vat","s7-thoat-hoi-nuoc","s7-tieu-hoa"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-trao-doi-nuoc-thuc-vat","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":16,"loai":"ht","ten":"Trao đổi nước ở thực vật","ten_khac":["trao doi nuoc o thuc vat","hut nuoc","muoi khoang","van chuyen nuoc","con duong cua nuoc","dinh duong khoang"],"noi_dung":"Cây hút nước và muối khoáng ở rễ, vận chuyển lên lá, dùng một phần và thoát phần lớn ra ngoài qua lá.","cong_thuc":null,"y":["<b>Hút:</b> lông hút ở rễ hút nước và muối khoáng hòa tan.","<b>Vận chuyển:</b> nước, muối khoáng theo mạch gỗ đi lên; chất hữu cơ theo mạch rây đến các cơ quan.","<b>Thoát:</b> phần lớn nước thoát ra qua khí khổng ở lá.","Vận dụng: tưới đủ nước, bón phân đúng loại, đúng lúc, đúng liều lượng."],"bang":null,"bien":null,"vd":{"de":"Một chậu cây bị tưới quá nhiều nước liên tục nhiều ngày, đất luôn sũng nước, sau đó cây héo và chết dần dù đủ nước. Vì sao?","buoc":["Đất sũng nước làm rễ thiếu oxygen để hô hấp.","Lông hút bị hỏng, rễ không hút được nước và muối khoáng."],"kq":"Cây héo do rễ không hô hấp và hút nước được, dù đất thừa nước."},"nham":null,"lq":["s7-long-hut","s7-mach-go","s7-mach-ray","s7-thoat-hoi-nuoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-long-hut","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":17,"loai":"cq","ten":"Lông hút","ten_khac":["long hut","re cay","mien hut","hut nuoc","root hair"],"noi_dung":"Phần kéo dài của tế bào biểu bì rễ, có nhiệm vụ hút nước và muối khoáng từ đất.","cong_thuc":null,"y":["Nằm ở <b>miền hút</b> của rễ, rất nhiều, làm tăng diện tích tiếp xúc với đất.","Nước và muối khoáng từ đất qua lông hút vào rễ rồi vào mạch gỗ.","Vận dụng: xới đất tơi xốp giúp rễ và lông hút phát triển, hút nước tốt."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s7-trao-doi-nuoc-thuc-vat","s7-mach-go"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-mach-go","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":18,"loai":"cq","ten":"Mạch gỗ","ten_khac":["mach go","xylem","dan nuoc","van chuyen nuoc muoi khoang","dong di len"],"noi_dung":"Hệ mạch dẫn nước và muối khoáng từ rễ lên thân, lá.","cong_thuc":null,"y":["Dòng vận chuyển đi <b>lên</b>: rễ → thân → lá.","Thí nghiệm: cắm cành hoa trắng vào nước pha màu, một thời gian sau cánh hoa đổi màu → thân vận chuyển nước.","Lực đẩy từ rễ và lực kéo do thoát hơi nước ở lá giúp nước đi lên."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm mạch gỗ (dẫn nước, muối khoáng) với mạch rây (dẫn chất hữu cơ)."],"lq":["s7-mach-ray","s7-long-hut","s7-thoat-hoi-nuoc","s7-trao-doi-nuoc-thuc-vat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-mach-ray","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":19,"loai":"cq","ten":"Mạch rây","ten_khac":["mach ray","phloem","dan chat huu co","van chuyen chat huu co"],"noi_dung":"Hệ mạch dẫn chất hữu cơ tổng hợp ở lá đến các bộ phận khác của cây.","cong_thuc":null,"y":["Chất hữu cơ tạo ra ở lá được đưa đến nơi cần dùng hoặc nơi dự trữ (củ, quả, hạt).","Bóc một khoanh vỏ thân (có mạch rây), chất hữu cơ bị ứ lại ở mép trên chỗ bóc, làm mép trên phình to."],"bang":null,"bien":null,"vd":{"de":"Khi khoanh vỏ (bóc một vòng vỏ) quanh thân cây, sau một thời gian mép vỏ phía trên vết khoanh phình to. Giải thích.","buoc":["Bóc vỏ đã cắt đứt mạch rây dẫn chất hữu cơ từ lá xuống.","Chất hữu cơ ứ lại ở mép trên vết cắt, làm mép đó phình to."],"kq":"Mạch rây bị cắt khiến chất hữu cơ ứ đọng ở phía trên vết khoanh."},"nham":["Nghĩ mạch rây chỉ dẫn xuống: chất hữu cơ đi đến mọi nơi cần dùng, kể cả lên chồi non."],"lq":["s7-mach-go","s7-quang-hop","s7-trao-doi-nuoc-thuc-vat","s7-chiet-canh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-thoat-hoi-nuoc","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":20,"loai":"ht","ten":"Thoát hơi nước","ten_khac":["thoat hoi nuoc","thoat hoi nuoc o la","transpiration","bay hoi nuoc qua la","tui nilon"],"noi_dung":"Sự mất nước của cây dưới dạng hơi, chủ yếu qua khí khổng ở lá.","cong_thuc":null,"y":["Phần lớn nước cây hút vào được thoát ra ngoài qua lá.","Vai trò: tạo <b>lực kéo</b> nước từ rễ lên lá, làm mát lá, giúp khí khổng mở cho carbon dioxide vào.","Thí nghiệm: bọc cành lá bằng túi nilon trong suốt, thành túi đọng hơi nước.","Ánh sáng, nhiệt độ, độ ẩm không khí, gió ảnh hưởng đến thoát hơi nước."],"bang":null,"bien":null,"vd":{"de":"Một chậu cây được trùm túi nylon kín quanh lá, để ra nắng một lúc thấy mặt trong túi có các giọt nước nhỏ. Giải thích.","buoc":["Lá cây thoát hơi nước ra ngoài qua khí khổng.","Hơi nước gặp túi nylon nhiệt độ thấp hơn nên ngưng tụ thành giọt nước."],"kq":"Các giọt nước trong túi là hơi nước cây thoát ra qua lá."},"nham":["Thoát hơi nước là lãng phí → SAI: nó giúp vận chuyển nước và làm mát lá."],"lq":["s7-khi-khong","s7-mach-go","s7-trao-doi-nuoc-thuc-vat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-tieu-hoa","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":21,"loai":"ht","ten":"Tiêu hóa ở người","ten_khac":["tieu hoa","ong tieu hoa","con duong thuc an","da day","ruot non","hap thu dinh duong"],"noi_dung":"Quá trình biến đổi thức ăn thành chất dinh dưỡng đơn giản mà cơ thể hấp thụ được, thải phần bã ra ngoài.","cong_thuc":null,"y":["Đường đi của thức ăn: <b>miệng → hầu → thực quản → dạ dày → ruột non → ruột già → hậu môn</b>.","Chất dinh dưỡng được hấp thụ chủ yếu ở <b>ruột non</b> vào máu.","Nước được hấp thụ ở ruột non và ruột già; chất thải qua hậu môn, nước tiểu, mồ hôi.","Vận dụng: ăn uống đủ chất, uống đủ nước, ăn chín uống sôi."],"bang":null,"bien":null,"vd":{"de":"Vì sao khi ăn cơm nên nhai kĩ trước khi nuốt?","buoc":["Nhai kĩ giúp nghiền nhỏ thức ăn, trộn đều với nước bọt.","Thức ăn nhỏ, mềm hơn giúp các cơ quan tiêu hóa sau đó dễ biến đổi tiếp."],"kq":"Nhai kĩ giúp tiêu hóa thức ăn tốt hơn, hấp thụ được nhiều dinh dưỡng hơn."},"nham":["Thức ăn được hấp thụ chủ yếu ở dạ dày → SAI: chủ yếu ở ruột non."],"lq":["s7-tuan-hoan","s7-vai-tro-cua-nuoc","s7-trao-doi-chat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-tuan-hoan","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":22,"loai":"cq","ten":"Hệ tuần hoàn","ten_khac":["he tuan hoan","tuan hoan","tim","mach mau","mau","van chuyen chat o dong vat"],"noi_dung":"Hệ cơ quan gồm tim và mạch máu, vận chuyển chất dinh dưỡng, oxygen đến tế bào và mang chất thải đi.","cong_thuc":null,"y":["<b>Tim</b> co bóp đẩy máu đi; <b>mạch máu</b> (động mạch, tĩnh mạch, mao mạch) dẫn máu khắp cơ thể.","Máu nhận chất dinh dưỡng từ ruột non, oxygen từ phổi, đưa đến các tế bào.","Máu nhận carbon dioxide, chất thải từ tế bào đưa đến phổi, thận… để thải ra ngoài.","Máu chảy theo hai vòng: vòng tuần hoàn lớn và vòng tuần hoàn nhỏ."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s7-vong-tuan-hoan-lon","s7-vong-tuan-hoan-nho","s7-tieu-hoa","s7-trao-doi-khi-dong-vat"],"hinh":"H-s7-tuan-hoan","nguon":["KHTN Pocket"]},{"ma":"s7-vong-tuan-hoan-lon","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":23,"loai":"ht","ten":"Vòng tuần hoàn lớn","ten_khac":["vong tuan hoan lon","vong lon","tuan hoan lon","tim den cac co quan","dong mach tinh mach"],"noi_dung":"Vòng máu đi từ tim đến các cơ quan trong cơ thể rồi trở về tim.","cong_thuc":null,"y":["Đường đi: <b>tim → động mạch → mao mạch ở các cơ quan → tĩnh mạch → tim</b>.","Ở các cơ quan: máu đưa oxygen, chất dinh dưỡng cho tế bào và nhận carbon dioxide, chất thải."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm vòng lớn (tim → các cơ quan → tim) với vòng nhỏ (tim → phổi → tim)."],"lq":["s7-vong-tuan-hoan-nho","s7-tuan-hoan"],"hinh":"H-s7-vong-tuan-hoan-lon","nguon":["KHTN Pocket"]},{"ma":"s7-vong-tuan-hoan-nho","mon":"KHTN","khoi":"7","chu_de":"s7-trao-doi-chat","thu_tu":24,"loai":"ht","ten":"Vòng tuần hoàn nhỏ","ten_khac":["vong tuan hoan nho","vong nho","tuan hoan nho","tuan hoan phoi","tim phoi tim"],"noi_dung":"Vòng máu đi từ tim lên phổi để trao đổi khí rồi trở về tim.","cong_thuc":null,"y":["Đường đi: <b>tim → phổi → tim</b>.","Tại phổi: máu thải carbon dioxide và nhận oxygen, trở thành máu giàu oxygen."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ máu nhận oxygen ở vòng tuần hoàn lớn: máu nhận oxygen tại phổi, ở vòng nhỏ."],"lq":["s7-vong-tuan-hoan-lon","s7-tuan-hoan","s7-trao-doi-khi-dong-vat"],"hinh":"H-s7-vong-tuan-hoan-nho","nguon":["KHTN Pocket"]},{"ma":"s7-cam-ung","mon":"KHTN","khoi":"7","chu_de":"s7-cam-ung","thu_tu":1,"loai":"kn","ten":"Cảm ứng","ten_khac":["cam ung","cam ung o sinh vat","kich thich","phan ung voi kich thich","response"],"noi_dung":"Khả năng tiếp nhận và phản ứng với các kích thích từ môi trường, giúp sinh vật thích nghi và tồn tại.","cong_thuc":null,"y":["Kích thích có thể là ánh sáng, nước, nhiệt độ, âm thanh, sự va chạm, hóa chất…","Ví dụ: cây trinh nữ cụp lá khi bị chạm; người rụt tay khi chạm vật nóng.","Ở thực vật thường <b>chậm</b>, khó thấy; ở động vật thường <b>nhanh</b>, dễ thấy."],"bang":null,"bien":null,"vd":null,"nham":["Thực vật không có cảm ứng → SAI: có, nhưng thường diễn ra chậm."],"lq":["s7-tinh-huong","s7-cam-ung-dong-vat","s7-tap-tinh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-tinh-huong","mon":"KHTN","khoi":"7","chu_de":"s7-cam-ung","thu_tu":2,"loai":"ht","ten":"Tính hướng","ten_khac":["tinh huong","cam ung o thuc vat","huong dong","tropism","cac kieu huong"],"noi_dung":"Phản ứng của cơ quan thực vật sinh trưởng hướng về phía kích thích hoặc tránh xa kích thích.","cong_thuc":null,"y":["Các kiểu thường gặp: <b>hướng sáng, hướng nước, hướng tiếp xúc, hướng hóa</b>.","Giúp cây tìm tới ánh sáng, nước, chất dinh dưỡng, giá thể để tồn tại.","Muốn kiểm chứng phải làm thí nghiệm có mẫu đối chứng, chỉ thay đổi một yếu tố."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s7-huong-sang","s7-huong-nuoc","s7-huong-tiep-xuc","s7-huong-hoa","s7-cam-ung"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-huong-sang","mon":"KHTN","khoi":"7","chu_de":"s7-cam-ung","thu_tu":3,"loai":"ht","ten":"Hướng sáng","ten_khac":["huong sang","tinh huong sang","cay nghieng ve anh sang","phototropism","ngon cay"],"noi_dung":"Phản ứng của cây sinh trưởng hướng về phía có ánh sáng.","cong_thuc":null,"y":["Thân, ngọn cây mọc cong về phía nguồn sáng.","Thí nghiệm: đặt chậu cây con cạnh cửa sổ, vài ngày sau ngọn cây vươn về phía có ánh sáng.","Vận dụng: trồng cây đúng khoảng cách, xoay chậu cây cảnh để cây mọc thẳng."],"bang":null,"bien":null,"vd":{"de":"Một chậu cây non đặt trong phòng chỉ có ánh sáng từ một phía cửa sổ, sau vài ngày thân cây mọc cong về phía cửa sổ. Giải thích.","buoc":["Cây có tính hướng sáng, thân sinh trưởng hướng về phía có ánh sáng.","Phía cửa sổ có nhiều ánh sáng nên thân cây mọc cong về hướng đó."],"kq":"Đây là hiện tượng hướng sáng của thân cây."},"nham":null,"lq":["s7-tinh-huong","s7-huong-nuoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-huong-nuoc","mon":"KHTN","khoi":"7","chu_de":"s7-cam-ung","thu_tu":4,"loai":"ht","ten":"Hướng nước","ten_khac":["huong nuoc","tinh huong nuoc","re moc ve nguon nuoc","hydrotropism"],"noi_dung":"Phản ứng của rễ cây sinh trưởng hướng về phía nguồn nước.","cong_thuc":null,"y":["Rễ mọc dài về phía đất ẩm, nơi có nước.","Thí nghiệm: gieo hạt trong khay đất, đặt nguồn nước ở một bên, rễ mọc về phía có nước.","Vận dụng: tưới nước quanh gốc để rễ phát triển rộng."],"bang":null,"bien":null,"vd":{"de":"Khi tưới nước lệch về một bên gốc cây liên tục, rễ cây phát triển mạnh về phía nào?","buoc":["Rễ có tính hướng nước, luôn sinh trưởng hướng về phía có nguồn nước.","Phía đất được tưới nhiều nước kích thích rễ phát triển mạnh hơn."],"kq":"Rễ phát triển mạnh về phía đất được tưới nhiều nước."},"nham":null,"lq":["s7-tinh-huong","s7-huong-hoa","s7-huong-sang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-huong-tiep-xuc","mon":"KHTN","khoi":"7","chu_de":"s7-cam-ung","thu_tu":5,"loai":"ht","ten":"Hướng tiếp xúc","ten_khac":["huong tiep xuc","tua cuon","cay leo","than quan","lam gian"],"noi_dung":"Phản ứng của cây sinh trưởng khi tiếp xúc với vật khác, như tua cuốn quấn quanh giá thể.","cong_thuc":null,"y":["Ví dụ: tua cuốn của mướp, bầu, bí quấn vào giàn; thân cây leo quấn quanh cọc.","Giúp cây leo bám lên cao để nhận nhiều ánh sáng.","Vận dụng: làm giàn, cắm cọc cho cây leo."],"bang":null,"bien":null,"vd":{"de":"Cây bầu, bí có tua cuốn quấn chặt quanh giàn khi tua chạm vào giàn. Đây là hiện tượng gì?","buoc":["Tua cuốn nhạy cảm với sự tiếp xúc, uốn cong về phía vật chạm vào.","Tua cuốn dần quấn chặt quanh giàn để bám và leo lên cao."],"kq":"Đây là hiện tượng hướng tiếp xúc, giúp cây bám và leo lên cao."},"nham":null,"lq":["s7-tinh-huong","s7-huong-sang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-huong-hoa","mon":"KHTN","khoi":"7","chu_de":"s7-cam-ung","thu_tu":6,"loai":"ht","ten":"Hướng hóa","ten_khac":["huong hoa","tinh huong hoa","huong hoa chat","re moc ve phan bon","chemotropism"],"noi_dung":"Phản ứng của cây sinh trưởng hướng tới hoặc tránh xa các chất hóa học.","cong_thuc":null,"y":["Rễ mọc về phía có chất dinh dưỡng (phân bón) và tránh xa chất độc hại.","Vận dụng: bón phân đúng chỗ để rễ phát triển tốt."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s7-tinh-huong","s7-huong-nuoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-cam-ung-dong-vat","mon":"KHTN","khoi":"7","chu_de":"s7-cam-ung","thu_tu":7,"loai":"ht","ten":"Cảm ứng ở động vật","ten_khac":["cam ung o dong vat","phan ung o dong vat","giun dat","rut tay","phan xa"],"noi_dung":"Động vật tiếp nhận kích thích và phản ứng nhanh, dễ nhận thấy, nhờ có hệ thần kinh và giác quan.","cong_thuc":null,"y":["Ví dụ: giun đất chui vào đất khi gặp ánh sáng mạnh; người rụt tay khi chạm vật nóng; mèo chạy đến khi nghe tiếng gọi.","Giúp động vật tìm thức ăn, tránh kẻ thù và thích nghi với môi trường."],"bang":null,"bien":null,"vd":{"de":"Khi vô tình chạm tay vào vật rất nóng, tay ta rụt lại ngay lập tức. Đây là biểu hiện của hiện tượng gì?","buoc":["Cơ thể tiếp nhận kích thích nóng qua thụ thể ở da.","Hệ thần kinh xử lí nhanh, gây phản ứng co cơ rụt tay lại."],"kq":"Đây là cảm ứng ở động vật, giúp tránh bị bỏng."},"nham":null,"lq":["s7-cam-ung","s7-tap-tinh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-tap-tinh","mon":"KHTN","khoi":"7","chu_de":"s7-cam-ung","thu_tu":8,"loai":"kn","ten":"Tập tính","ten_khac":["tap tinh","tap tinh dong vat","behavior","chuoi phan ung","tap tinh bao ve lanh tho"],"noi_dung":"Chuỗi phản ứng của động vật trả lời kích thích từ môi trường, giúp chúng thích nghi và tồn tại.","cong_thuc":null,"y":["Một số tập tính: kiếm ăn, sinh sản, bảo vệ lãnh thổ, di cư…","Có hai loại: <b>tập tính bẩm sinh</b> và <b>tập tính học được</b>."],"bang":[["Loại","Đặc điểm","Ví dụ"],["Bẩm sinh","Sinh ra đã có, không cần học","Nhện giăng tơ, thú con bú mẹ"],["Học được","Hình thành qua học tập, rút kinh nghiệm","Chó nghe gọi tên chạy đến, khỉ làm xiếc"]],"bien":null,"vd":null,"nham":["Mọi tập tính đều phải học → SAI: có tập tính bẩm sinh."],"lq":["s7-tap-tinh-bam-sinh","s7-tap-tinh-hoc-duoc","s7-cam-ung-dong-vat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-tap-tinh-bam-sinh","mon":"KHTN","khoi":"7","chu_de":"s7-cam-ung","thu_tu":9,"loai":"kn","ten":"Tập tính bẩm sinh","ten_khac":["tap tinh bam sinh","bam sinh","sinh ra da co","ban nang"],"noi_dung":"Tập tính sinh ra đã có, không cần học, đặc trưng cho loài.","cong_thuc":null,"y":["Ví dụ: nhện giăng tơ, thú con bú mẹ, chim làm tổ.","Mọi cá thể cùng loài đều có và thường khó thay đổi."],"bang":null,"bien":null,"vd":{"de":"Nhện con mới nở đã biết chăng tơ giăng lưới giống hệt bố mẹ mà không cần học. Đây là loại tập tính nào?","buoc":["Nhện con chưa từng được dạy hay quan sát nhện khác chăng tơ.","Khả năng này có sẵn từ khi sinh ra, mang tính di truyền của loài."],"kq":"Đây là tập tính bẩm sinh, đặc trưng cho loài nhện."},"nham":null,"lq":["s7-tap-tinh","s7-tap-tinh-hoc-duoc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-tap-tinh-hoc-duoc","mon":"KHTN","khoi":"7","chu_de":"s7-cam-ung","thu_tu":10,"loai":"kn","ten":"Tập tính học được","ten_khac":["tap tinh hoc duoc","hoc duoc","hoc tap","rut kinh nghiem","huan luyen vat nuoi"],"noi_dung":"Tập tính hình thành trong đời sống của cá thể qua học tập, rút kinh nghiệm.","cong_thuc":null,"y":["Ví dụ: chó chạy đến khi nghe gọi tên, khỉ làm xiếc, gà chạy đến khi nghe tiếng gọi cho ăn.","Có thể thay đổi, mất đi nếu không được củng cố.","Vận dụng: huấn luyện vật nuôi bằng tín hiệu kèm thức ăn; người luyện tập đều đặn để hình thành thói quen tốt."],"bang":null,"bien":null,"vd":{"de":"Một con chó được huấn luyện, cứ nghe tiếng chuông là chạy đến chỗ để thức ăn. Đây là loại tập tính nào?","buoc":["Ban đầu chó chưa hề phản ứng với tiếng chuông.","Qua nhiều lần huấn luyện lặp lại, chó hình thành phản xạ nghe chuông là có ăn."],"kq":"Đây là tập tính học được, không có sẵn từ khi sinh ra."},"nham":null,"lq":["s7-tap-tinh","s7-tap-tinh-bam-sinh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-sinh-truong","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-truong","thu_tu":1,"loai":"ht","ten":"Sinh trưởng","ten_khac":["sinh truong","lon len","tang kich thuoc","tang khoi luong","growth"],"noi_dung":"Sự tăng kích thước và khối lượng của cơ thể do tăng số lượng và kích thước tế bào.","cong_thuc":null,"y":["Ví dụ: cây cao thêm, gà con nặng thêm.","Là sự biến đổi về <b>lượng</b>.","Theo dõi sinh trưởng: đo chiều cao cây sau những khoảng thời gian bằng nhau, vẽ đồ thị."],"bang":null,"bien":null,"vd":null,"nham":["Coi sinh trưởng và phát triển là một: sinh trưởng là tăng về lượng, phát triển là biến đổi về chất."],"lq":["s7-phat-trien","s7-mo-phan-sinh","s7-nhan-to-sinh-truong"],"hinh":"H-s7-sinh-truong","nguon":["KHTN Pocket"]},{"ma":"s7-phat-trien","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-truong","thu_tu":2,"loai":"ht","ten":"Phát triển","ten_khac":["phat trien","bien doi ve chat","development","cac giai doan phat trien"],"noi_dung":"Những biến đổi diễn ra trong đời sống cá thể, gồm sinh trưởng, phân hóa tế bào và phát sinh hình thái cơ quan.","cong_thuc":null,"y":["Ví dụ: cây ra hoa, tạo quả; nòng nọc biến thành ếch.","Thực vật có hoa: hạt → nảy mầm → cây con → cây trưởng thành → ra hoa, tạo quả và hạt.","Sinh trưởng và phát triển liên quan mật thiết, đan xen nhau."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s7-sinh-truong","s7-vong-doi","s7-bien-thai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-mo-phan-sinh","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-truong","thu_tu":3,"loai":"cq","ten":"Mô phân sinh","ten_khac":["mo phan sinh","meristem","te bao phan chia","mo phan chia"],"noi_dung":"Nhóm tế bào thực vật chưa phân hóa, có khả năng phân chia, giúp cây sinh trưởng.","cong_thuc":null,"y":["Có hai loại chính: <b>mô phân sinh đỉnh</b> và <b>mô phân sinh bên</b>.","Các tế bào mới sinh ra lớn lên và phân hóa thành các mô khác."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s7-mo-phan-sinh-dinh","s7-mo-phan-sinh-ben","s7-sinh-truong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-mo-phan-sinh-dinh","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-truong","thu_tu":4,"loai":"cq","ten":"Mô phân sinh đỉnh","ten_khac":["mo phan sinh dinh","dinh ngon","choi ngon","dau re","cay dai ra","bam ngon"],"noi_dung":"Mô phân sinh nằm ở chồi ngọn, chồi nách và đầu rễ, giúp thân và rễ dài ra.","cong_thuc":null,"y":["Có ở cả cây một lá mầm và cây hai lá mầm.","Làm cây <b>cao lên</b>, rễ <b>dài ra</b>.","Vận dụng: bấm ngọn để cây ra nhiều cành bên (rau muống, bông, đậu…)."],"bang":null,"bien":null,"vd":null,"nham":["Mô phân sinh đỉnh làm cây to ra → SAI: làm cây dài ra; mô phân sinh bên làm cây to ra."],"lq":["s7-mo-phan-sinh","s7-mo-phan-sinh-ben"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-mo-phan-sinh-ben","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-truong","thu_tu":5,"loai":"cq","ten":"Mô phân sinh bên","ten_khac":["mo phan sinh ben","cay to ra","than to ra","tang duong kinh than","cay hai la mam"],"noi_dung":"Mô phân sinh nằm ở thân, cành cây hai lá mầm, giúp thân và cành to ra.","cong_thuc":null,"y":["Có ở thân, cành cây <b>hai lá mầm</b>.","Làm tăng đường kính thân, cành.","Cây một lá mầm (lúa, ngô, tre) thường không có mô phân sinh bên nên thân ít to thêm."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s7-mo-phan-sinh","s7-mo-phan-sinh-dinh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-vong-doi","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-truong","thu_tu":6,"loai":"kn","ten":"Vòng đời","ten_khac":["vong doi","chu ki song","chu ky song","life cycle","cac giai doan"],"noi_dung":"Các giai đoạn sinh vật trải qua từ khi sinh ra, lớn lên, trưởng thành đến khi sinh sản tạo thế hệ mới.","cong_thuc":null,"y":["Vòng đời ếch: trứng → nòng nọc → ếch con → ếch trưởng thành.","Vòng đời cây có hoa: hạt → cây con → cây trưởng thành → hoa → quả và hạt.","Vận dụng: diệt sâu hại ở giai đoạn dễ tiêu diệt nhất; thu hoạch vật nuôi, cây trồng đúng giai đoạn."],"bang":null,"bien":null,"vd":{"de":"Ếch trải qua các giai đoạn trứng, nòng nọc, ếch con, ếch trưởng thành rồi lại đẻ trứng. Chuỗi giai đoạn này gọi là gì?","buoc":["Mỗi giai đoạn có hình thái và môi trường sống khác nhau.","Chuỗi giai đoạn nối tiếp từ khi sinh ra đến khi sinh sản tạo thế hệ mới."],"kq":"Đây là vòng đời của ếch."},"nham":null,"lq":["s7-phat-trien","s7-bien-thai"],"hinh":"H-s7-vong-doi","nguon":["KHTN Pocket"]},{"ma":"s7-bien-thai","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-truong","thu_tu":7,"loai":"ht","ten":"Biến thái","ten_khac":["bien thai","phat trien qua bien thai","khong qua bien thai","nong noc thanh ech","sau thanh buom","metamorphosis"],"noi_dung":"Kiểu phát triển mà con non có hình thái, cấu tạo khác hẳn con trưởng thành, phải qua nhiều biến đổi mới thành con trưởng thành.","cong_thuc":null,"y":["Bướm: trứng → sâu → nhộng → bướm.","Ếch: trứng → nòng nọc (sống dưới nước, thở bằng mang) → ếch trưởng thành.","Ở bướm, <b>sâu</b> (con non) thường là giai đoạn phá hại cây trồng."],"bang":[["Kiểu phát triển","Đặc điểm","Ví dụ"],["Qua biến thái","Con non khác hẳn con trưởng thành","Ếch, bướm, muỗi"],["Không qua biến thái","Con non có hình dạng, cấu tạo tương tự con trưởng thành","Gà, chó, người"]],"bien":null,"vd":{"de":"Con bướm trải qua các giai đoạn trứng, sâu, nhộng, bướm trưởng thành; hình dạng mỗi giai đoạn khác hẳn nhau. Đây là kiểu phát triển gì?","buoc":["Sâu (con non) có hình dạng, cách sống khác hẳn bướm trưởng thành.","Cơ thể phải trải qua giai đoạn nhộng mới biến đổi thành bướm."],"kq":"Đây là kiểu phát triển qua biến thái."},"nham":null,"lq":["s7-vong-doi","s7-phat-trien"],"hinh":"H-s7-bien-thai","nguon":["KHTN Pocket"]},{"ma":"s7-nhan-to-sinh-truong","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-truong","thu_tu":8,"loai":"kn","ten":"Nhân tố ảnh hưởng sinh trưởng","ten_khac":["nhan to anh huong sinh truong","yeu to anh huong sinh truong","nhiet do","anh sang","dinh duong","ung dung sinh truong"],"noi_dung":"Sinh trưởng và phát triển chịu ảnh hưởng của nhân tố bên ngoài (môi trường) và bên trong (di truyền, hormone).","cong_thuc":null,"y":["<b>Bên ngoài:</b> nhiệt độ, ánh sáng, nước, chất dinh dưỡng.","<b>Bên trong:</b> đặc điểm di truyền của loài, hormone.","Ứng dụng trồng trọt: bấm ngọn, tỉa cành, chiếu sáng, tưới nước, bón phân hợp lí.","Ứng dụng chăn nuôi: điều chỉnh thức ăn, chuồng trại phù hợp từng giai đoạn."],"bang":null,"bien":null,"vd":{"de":"Hai chậu cây con cùng giống, một chậu đủ ánh sáng lớn khỏe thân mập; chậu còn lại thiếu ánh sáng thân vươn dài, yếu, lá nhợt nhạt. Giải thích.","buoc":["Ánh sáng là nhân tố môi trường ảnh hưởng đến sinh trưởng và phát triển.","Thiếu ánh sáng, cây quang hợp kém nhưng vẫn vươn dài để tìm ánh sáng nên thân yếu."],"kq":"Thiếu ánh sáng làm cây sinh trưởng không bình thường, thân yếu, lá nhợt."},"nham":null,"lq":["s7-sinh-truong","s7-phat-trien","s7-mo-phan-sinh-dinh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-sinh-san-vo-tinh","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-san","thu_tu":1,"loai":"ht","ten":"Sinh sản vô tính","ten_khac":["sinh san vo tinh","vo tinh","ssvt","khong co giao tu","asexual reproduction"],"noi_dung":"Hình thức sinh sản không có sự kết hợp giữa giao tử đực và giao tử cái; con sinh ra giống nhau và giống cơ thể mẹ.","cong_thuc":null,"y":["Động vật: <b>phân đôi</b> (trùng roi), <b>nảy chồi</b> (thủy tức), <b>phân mảnh</b> (sao biển), <b>trinh sản</b> (ong).","Thực vật: <b>sinh sản sinh dưỡng</b> từ rễ, thân, lá.","Ưu điểm: nhanh, giữ nguyên đặc tính của mẹ; hạn chế: con kém đa dạng."],"bang":[["","Vô tính","Hữu tính"],["Giao tử","Không kết hợp giao tử","Có kết hợp giao tử đực và cái"],["Con sinh ra","Giống hệt mẹ","Mang đặc điểm của cả bố và mẹ"]],"bien":null,"vd":{"de":"Trùng biến hình khi gặp điều kiện thuận lợi tự tách thành hai cá thể con giống hệt nhau, không cần cá thể khác. Đây là hình thức sinh sản gì?","buoc":["Chỉ một cá thể mẹ tự tách thành hai cá thể con.","Không có sự kết hợp giữa giao tử đực và giao tử cái."],"kq":"Đây là sinh sản vô tính."},"nham":null,"lq":["s7-sinh-san-huu-tinh","s7-phan-doi","s7-nay-choi","s7-sinh-san-sinh-duong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-phan-doi","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-san","thu_tu":2,"loai":"ht","ten":"Phân đôi","ten_khac":["phan doi","sinh san phan doi","trung roi","vi khuan","chia doi"],"noi_dung":"Hình thức sinh sản vô tính trong đó cơ thể mẹ tách thành hai cơ thể con giống nhau.","cong_thuc":null,"y":["Gặp ở sinh vật đơn bào: trùng roi, trùng giày, vi khuẩn…","Hai cơ thể con có đặc điểm giống cơ thể mẹ."],"bang":null,"bien":null,"vd":{"de":"Một tế bào vi khuẩn trong điều kiện thuận lợi cứ 20 phút lại phân chia một lần. Sau 1 giờ, một vi khuẩn ban đầu tạo ra bao nhiêu tế bào?","buoc":["1 giờ = 60 phút, tương ứng 3 lần phân chia (mỗi 20 phút một lần).","Số tế bào = 2³ (mỗi lần phân đôi tăng gấp đôi)."],"kq":"Tạo ra 8 tế bào vi khuẩn."},"nham":null,"lq":["s7-sinh-san-vo-tinh","s7-nay-choi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-nay-choi","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-san","thu_tu":3,"loai":"ht","ten":"Nảy chồi","ten_khac":["nay choi","sinh san nay choi","thuy tuc","choi con"],"noi_dung":"Hình thức sinh sản vô tính trong đó cơ thể mẹ mọc ra chồi, chồi lớn lên thành cơ thể mới.","cong_thuc":null,"y":["Ví dụ: thủy tức, nấm men.","Chồi con có thể tách khỏi mẹ sống độc lập hoặc dính với mẹ tạo thành tập đoàn (san hô)."],"bang":null,"bien":null,"vd":{"de":"Thủy tức trong điều kiện thuận lợi mọc ra một chồi nhỏ ở thân, chồi lớn dần rồi tách ra thành cá thể mới. Đây là hình thức sinh sản gì?","buoc":["Cơ thể mẹ mọc ra một chồi nhỏ ở thân.","Chồi lớn dần, phát triển đầy đủ rồi tách khỏi cơ thể mẹ."],"kq":"Đây là hình thức nảy chồi, một kiểu sinh sản vô tính."},"nham":["Nhầm nảy chồi (động vật, nấm men) với chồi cây trong sinh sản sinh dưỡng."],"lq":["s7-sinh-san-vo-tinh","s7-phan-doi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-sinh-san-sinh-duong","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-san","thu_tu":4,"loai":"ht","ten":"Sinh sản sinh dưỡng","ten_khac":["sinh san sinh duong","sinh duong","cu","than re","la bong","khoai lang","gung"],"noi_dung":"Hình thức sinh sản vô tính ở thực vật, cây mới mọc ra từ cơ quan sinh dưỡng (rễ, thân, lá).","cong_thuc":null,"y":["Cây con giữ nguyên đặc tính của cây mẹ.","Con người ứng dụng: giâm cành, chiết cành, ghép cây, nuôi cấy mô."],"bang":[["Cơ quan","Ví dụ"],["Rễ (rễ củ)","Khoai lang"],["Thân (thân rễ, thân củ)","Gừng, nghệ, khoai tây"],["Lá","Lá bỏng"]],"bien":null,"vd":null,"nham":null,"lq":["s7-sinh-san-vo-tinh","s7-giam-canh","s7-chiet-canh","s7-ghep-cay","s7-nuoi-cay-mo"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-giam-canh","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-san","thu_tu":5,"loai":"ud","ten":"Giâm cành","ten_khac":["giam canh","giam","cam canh","san","mia","rau muong","hoa hong"],"noi_dung":"Cắt một đoạn cành (thân) có đủ mắt, chồi cắm xuống đất ẩm để đoạn cành ra rễ, phát triển thành cây mới.","cong_thuc":null,"y":["Ví dụ: sắn, mía, rau muống, hoa hồng.","Dùng cho cây có cành dễ ra rễ.","Cây con giữ đặc tính của cây mẹ, nhân giống nhanh."],"bang":null,"bien":null,"vd":{"de":"Muốn nhân giống nhanh cây rau ngót, người ta thường cắt đoạn cành có mắt cắm xuống đất ẩm thay vì gieo hạt. Vì sao?","buoc":["Đoạn cành có thể ra rễ và mọc thành cây mới.","Cách này nhanh, giữ nguyên đặc điểm của cây mẹ."],"kq":"Đây là giâm cành, giúp nhân giống nhanh và đồng đều."},"nham":["Giâm cành là sinh sản hữu tính → SAI: không có giao tử, là sinh sản vô tính."],"lq":["s7-sinh-san-sinh-duong","s7-chiet-canh","s7-ghep-cay"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-chiet-canh","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-san","thu_tu":6,"loai":"ud","ten":"Chiết cành","ten_khac":["chiet canh","chiet","khoanh vo","bo bau","buoi","cam","vai"],"noi_dung":"Làm cho cành ra rễ ngay trên cây mẹ rồi cắt đem trồng thành cây mới.","cong_thuc":null,"y":["Cách làm: khoanh bỏ một đoạn vỏ, bó đất ẩm (bầu) quanh chỗ khoanh; khi cành ra rễ thì cắt đem trồng.","Dùng cho cây ăn quả khó ra rễ: bưởi, cam, vải, nhãn…","Cây chiết nhanh cho quả, giữ đặc tính tốt của cây mẹ."],"bang":null,"bien":null,"vd":{"de":"Với cây bưởi quý khó ra rễ khi giâm, người trồng thường bó đất ẩm quanh một đoạn cành trên cây, đợi ra rễ rồi mới cắt đem trồng. Cách làm này gọi là gì?","buoc":["Đất ẩm bó quanh cành kích thích cành mọc rễ mới.","Cành ra rễ ngay khi còn ở trên cây mẹ, chưa bị cắt rời."],"kq":"Đây là chiết cành, phù hợp với cây khó ra rễ."},"nham":null,"lq":["s7-giam-canh","s7-ghep-cay","s7-sinh-san-sinh-duong","s7-mach-ray"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-ghep-cay","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-san","thu_tu":7,"loai":"ud","ten":"Ghép cây","ten_khac":["ghep cay","ghep canh","ghep mat","goc ghep","canh ghep"],"noi_dung":"Gắn một cành hoặc mắt của cây này (cành ghép) lên thân hoặc gốc của cây khác (gốc ghép) để chúng liền thành cây mới.","cong_thuc":null,"y":["Có ghép cành, ghép mắt.","Gốc ghép thường khỏe, chịu được điều kiện bất lợi; cành ghép có đặc tính mong muốn (quả ngon, sai).","Ví dụ: ghép bưởi, cam, hoa hồng, xoài."],"bang":null,"bien":null,"vd":{"de":"Người ta ghép một mắt của giống bưởi ngon lên gốc cây bưởi dại khỏe rễ để trồng. Cách làm này gọi là gì và có lợi ích gì?","buoc":["Mắt ghép mang đặc điểm giống bưởi ngon, được gắn lên gốc khác.","Gốc ghép là cây bưởi dại có bộ rễ khỏe, chống chịu tốt."],"kq":"Đây là ghép cây, kết hợp ưu điểm của cành ghép và gốc ghép."},"nham":null,"lq":["s7-giam-canh","s7-chiet-canh","s7-sinh-san-sinh-duong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-nuoi-cay-mo","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-san","thu_tu":8,"loai":"ud","ten":"Nuôi cấy mô","ten_khac":["nuoi cay mo","nuoi cay mo te bao","cay mo","vi nhan giong","nhan giong nhanh"],"noi_dung":"Tách mô (tế bào) của cây nuôi trong môi trường dinh dưỡng vô trùng để tạo ra nhiều cây con.","cong_thuc":null,"y":["Tạo số lượng lớn cây con trong thời gian ngắn.","Cây con đồng đều, sạch bệnh, giữ đặc tính của cây mẹ.","Ví dụ: nhân giống lan, chuối, khoai tây, mía."],"bang":null,"bien":null,"vd":{"de":"Để nhân giống nhanh một lượng lớn cây chuối giống đồng đều trong phòng thí nghiệm, người ta dùng phương pháp nào?","buoc":["Tách một mô nhỏ của cây chuối mẹ.","Nuôi mô trong môi trường dinh dưỡng vô trùng để phát triển thành nhiều cây con."],"kq":"Đây là nuôi cấy mô, tạo ra nhiều cây con giống hệt cây mẹ."},"nham":null,"lq":["s7-sinh-san-sinh-duong","s7-giam-canh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-sinh-san-huu-tinh","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-san","thu_tu":9,"loai":"ht","ten":"Sinh sản hữu tính","ten_khac":["sinh san huu tinh","huu tinh","ssht","giao tu","hop tu","sexual reproduction"],"noi_dung":"Hình thức sinh sản có sự kết hợp giữa giao tử đực và giao tử cái tạo thành hợp tử, hợp tử phát triển thành cơ thể mới.","cong_thuc":null,"y":["Ba giai đoạn: hình thành giao tử → <b>thụ tinh</b> tạo hợp tử → hợp tử phát triển thành cơ thể mới.","Con sinh ra mang đặc điểm của cả bố và mẹ, <b>đa dạng</b>, dễ thích nghi với môi trường thay đổi.","Động vật: giao tử đực là tinh trùng, giao tử cái là trứng."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s7-sinh-san-vo-tinh","s7-thu-tinh","s7-hoa","s7-thu-phan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-hoa","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-san","thu_tu":10,"loai":"cq","ten":"Hoa","ten_khac":["hoa","cau tao hoa","nhi","nhuy","bao phan","bau nhuy","dai hoa","canh hoa"],"noi_dung":"Cơ quan sinh sản hữu tính của thực vật có hoa.","cong_thuc":null,"y":["Nhị và nhụy là bộ phận sinh sản chủ yếu của hoa.","Dựa vào nhị và nhụy, chia thành hoa lưỡng tính và hoa đơn tính."],"bang":[["Bộ phận","Vai trò"],["Nhị (bao phấn)","Tạo hạt phấn (chứa giao tử đực)"],["Nhụy (đầu, vòi, bầu nhụy)","Bầu nhụy chứa noãn (chứa giao tử cái)"],["Cánh hoa","Bảo vệ, hấp dẫn côn trùng"],["Đài hoa","Bảo vệ hoa"]],"bien":null,"vd":null,"nham":null,"lq":["s7-hoa-luong-tinh","s7-hoa-don-tinh","s7-thu-phan","s7-thu-tinh"],"hinh":"H-s7-hoa","nguon":["KHTN Pocket"]},{"ma":"s7-hoa-luong-tinh","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-san","thu_tu":11,"loai":"kn","ten":"Hoa lưỡng tính","ten_khac":["hoa luong tinh","luong tinh","co ca nhi va nhuy","hoa buoi","hoa lua"],"noi_dung":"Hoa có cả nhị và nhụy trên cùng một hoa.","cong_thuc":null,"y":["Ví dụ: hoa bưởi, hoa cải, hoa lúa, hoa đậu.","Có thể tự thụ phấn hoặc giao phấn."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s7-hoa","s7-hoa-don-tinh","s7-thu-phan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-hoa-don-tinh","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-san","thu_tu":12,"loai":"kn","ten":"Hoa đơn tính","ten_khac":["hoa don tinh","don tinh","hoa duc","hoa cai","hoa bi","hoa muop"],"noi_dung":"Hoa chỉ có nhị (hoa đực) hoặc chỉ có nhụy (hoa cái).","cong_thuc":null,"y":["Ví dụ: hoa bí, hoa mướp, hoa ngô.","Chỉ hoa cái tạo thành quả; muốn đậu quả cần hạt phấn từ hoa đực chuyển sang.","Vận dụng: thụ phấn nhân tạo cho bí, mướp khi ít côn trùng."],"bang":null,"bien":null,"vd":{"de":"Trên cây mướp có hoa chỉ có nhị (không có nhụy) và hoa chỉ có nhụy (không có nhị) mọc riêng biệt. Đây là loại hoa gì?","buoc":["Hoa có nhị mà không có nhụy là hoa đực.","Hoa có nhụy mà không có nhị là hoa cái."],"kq":"Đây là hoa đơn tính, gồm hoa đực và hoa cái riêng."},"nham":["Nhầm \"hoa cái\" (hoa đơn tính chỉ có nhụy) với \"hoa cải\" (hoa của cây cải)."],"lq":["s7-hoa","s7-hoa-luong-tinh","s7-thu-phan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-thu-phan","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-san","thu_tu":13,"loai":"ht","ten":"Thụ phấn","ten_khac":["thu phan","tu thu phan","giao phan","thu phan nho gio","thu phan nho con trung","thu phan nhan tao"],"noi_dung":"Hiện tượng hạt phấn tiếp xúc với đầu nhụy.","cong_thuc":null,"y":["<b>Tự thụ phấn:</b> hạt phấn rơi lên đầu nhụy của chính hoa đó. <b>Giao phấn:</b> hạt phấn chuyển sang đầu nhụy của hoa khác.","Tác nhân: gió, côn trùng, nước, con người.","Vận dụng: thụ phấn nhân tạo khi thiếu côn trùng; bảo vệ ong, bướm giúp tăng năng suất."],"bang":null,"bien":null,"vd":{"de":"Hoa bí thường có màu vàng tươi, có mật ngọt, thu hút ong bướm bay đến. Điều này có lợi gì cho sinh sản của cây?","buoc":["Màu sắc và mật ngọt của hoa thu hút ong bướm đến hút mật.","Ong bướm vô tình mang hạt phấn từ hoa này sang đầu nhụy hoa khác."],"kq":"Hoa được thụ phấn nhờ côn trùng, giúp cây tạo quả và hạt."},"nham":["Thụ phấn là thụ tinh → SAI: thụ phấn xảy ra trước, thụ tinh là sự kết hợp giao tử đực và cái trong noãn."],"lq":["s7-thu-tinh","s7-hoa","s7-hoa-don-tinh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-thu-tinh","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-san","thu_tu":14,"loai":"ht","ten":"Thụ tinh","ten_khac":["thu tinh","hop tu","ong phan","noan","thu tinh trong","thu tinh ngoai"],"noi_dung":"Sự kết hợp giữa giao tử đực và giao tử cái tạo thành hợp tử.","cong_thuc":null,"y":["<b>Ở thực vật:</b> hạt phấn nảy mầm thành ống phấn, đưa giao tử đực vào noãn kết hợp với giao tử cái.","Sau thụ tinh: hợp tử → phôi, <b>noãn → hạt</b>, <b>bầu nhụy → quả</b>.","<b>Ở động vật:</b> thụ tinh ngoài (đa số cá, ếch: trong nước) hoặc thụ tinh trong (chim, thú: trong cơ thể con cái)."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm: noãn thành quả, bầu nhụy thành hạt (ngược lại mới đúng)."],"lq":["s7-thu-phan","s7-sinh-san-huu-tinh","s7-hoa"],"hinh":"H-s7-thu-tinh","nguon":["KHTN Pocket"]},{"ma":"s7-dieu-khien-sinh-san","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-san","thu_tu":15,"loai":"ud","ten":"Điều khiển sinh sản","ten_khac":["dieu khien sinh san","dieu hoa sinh san","yeu to anh huong sinh san","sinh de co ke hoach","ke hoach hoa gia dinh"],"noi_dung":"Con người tác động vào các yếu tố ảnh hưởng đến sinh sản để sinh vật sinh sản theo ý muốn.","cong_thuc":null,"y":["Yếu tố ảnh hưởng: bên trong (di truyền, hormone); bên ngoài (nhiệt độ, ánh sáng, nước, thức ăn…).","Thực vật: điều chỉnh chiếu sáng, nhiệt độ, bón phân để cây ra hoa, kết quả đúng lúc.","Động vật: thay đổi thức ăn, chiếu sáng để vật nuôi sinh sản nhiều.","Người: sinh đẻ có kế hoạch giúp chăm sóc con tốt, góp phần ổn định dân số."],"bang":null,"bien":null,"vd":{"de":"Người chăn nuôi thắp thêm đèn điện vào ban đêm trong chuồng gà. Vì sao cách này giúp gà đẻ trứng nhiều hơn?","buoc":["Thời gian chiếu sáng là một yếu tố ảnh hưởng đến sinh sản của gà.","Tăng thời gian chiếu sáng kích thích gà đẻ trứng đều và nhiều hơn."],"kq":"Đây là biện pháp điều khiển sinh sản bằng yếu tố ánh sáng."},"nham":null,"lq":["s7-sinh-san-huu-tinh","s7-sinh-san-vo-tinh","s7-the-thong-nhat"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s7-the-thong-nhat","mon":"KHTN","khoi":"7","chu_de":"s7-sinh-san","thu_tu":16,"loai":"kn","ten":"Cơ thể là thể thống nhất","ten_khac":["co the la the thong nhat","the thong nhat","moi quan he cac qua trinh song","qua trinh song"],"noi_dung":"Các quá trình sống trong cơ thể liên quan mật thiết, phối hợp với nhau, bảo đảm cơ thể tồn tại và phát triển.","cong_thuc":null,"y":["Bốn quá trình: trao đổi chất – chuyển hóa năng lượng, cảm ứng, sinh trưởng – phát triển, sinh sản.","Trao đổi chất cung cấp vật chất, năng lượng cho các quá trình khác; một quá trình thay đổi kéo theo quá trình khác thay đổi."],"bang":null,"bien":null,"vd":{"de":"Cây thiếu nước lâu ngày thì sao?","buoc":["Khí khổng đóng lại để giữ nước → ít carbon dioxide vào lá.","Quang hợp giảm → cây tạo ít chất hữu cơ."],"kq":"Cây chậm lớn, ra hoa và kết quả kém."},"nham":null,"lq":["s7-trao-doi-chat","s7-cam-ung","s7-sinh-truong","s7-sinh-san-huu-tinh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-he-co-quan","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":1,"loai":"kn","ten":"Hệ cơ quan","ten_khac":["he co quan","cac he co quan","co the nguoi","khai quat co the nguoi","co quan","he co quan nguoi"],"noi_dung":"Nhóm các cơ quan cùng phối hợp thực hiện một chức năng nhất định của cơ thể.","cong_thuc":null,"y":["Cơ thể người gồm các hệ: <b>vận động, tiêu hóa, tuần hoàn, hô hấp, bài tiết, thần kinh, nội tiết, sinh dục</b>; da và các giác quan.","Các hệ cơ quan phối hợp nhịp nhàng, cơ thể là một <b>khối thống nhất</b>.","Hệ thần kinh và hệ nội tiết điều khiển, điều hòa hoạt động của các hệ khác."],"bang":[["Hệ cơ quan","Chức năng chính"],["Vận động","Nâng đỡ, bảo vệ, giúp cơ thể di chuyển"],["Tiêu hóa","Biến đổi thức ăn, hấp thụ chất dinh dưỡng"],["Tuần hoàn","Vận chuyển các chất trong cơ thể"],["Hô hấp","Trao đổi khí với môi trường"],["Bài tiết","Lọc và thải chất thải, chất độc"],["Thần kinh","Điều khiển, điều hòa, phối hợp hoạt động"],["Nội tiết","Điều hòa bằng hormone"],["Sinh dục","Sinh sản, duy trì nòi giống"]],"bien":null,"vd":null,"nham":["Nghĩ mỗi hệ cơ quan hoạt động riêng lẻ; thực ra chúng luôn phối hợp, ví dụ khi chạy cả hệ vận động, tuần hoàn, hô hấp đều tăng hoạt động."],"lq":["s8-he-van-dong","s8-he-tieu-hoa","s8-he-tuan-hoan","s8-he-than-kinh","s8-he-noi-tiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-he-van-dong","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":2,"loai":"cq","ten":"Hệ vận động","ten_khac":["he van dong","van dong","xuong va co","co xuong","he van dong o nguoi","bo xuong va he co"],"noi_dung":"Hệ cơ quan gồm bộ xương và hệ cơ, giúp nâng đỡ, bảo vệ cơ thể và giúp cơ thể vận động.","cong_thuc":null,"y":["Gồm <b>bộ xương</b> (xương và khớp) và <b>hệ cơ</b> (cơ vân bám vào xương).","Cơ co, kéo xương chuyển động quanh khớp, tạo ra cử động.","Luyện tập thể dục thể thao, ăn đủ chất, ngồi đúng tư thế giúp hệ vận động khỏe mạnh."],"bang":null,"bien":null,"vd":null,"nham":["Cho rằng xương tự cử động; thực ra xương chỉ chuyển động khi cơ bám vào nó co lại."],"lq":["s8-bo-xuong","s8-khop-xuong","s8-he-co","s8-benh-xuong-khop"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-bo-xuong","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":3,"loai":"cq","ten":"Bộ xương người","ten_khac":["bo xuong","xuong","bo xuong nguoi","xuong dai","cau tao xuong","tuy xuong","xuong dau","xuong chi","skeleton"],"noi_dung":"Khung nâng đỡ cơ thể, gồm xương đầu, xương thân và xương chi, nối với nhau bằng các khớp.","cong_thuc":null,"y":["Ba phần: <b>xương đầu</b> (sọ, mặt), <b>xương thân</b> (cột sống, xương sườn, xương ức), <b>xương chi</b> (chi trên, chi dưới).","Chức năng: <b>nâng đỡ</b>, <b>bảo vệ</b> nội quan, làm chỗ bám cho cơ giúp <b>vận động</b>.","Xương dài gồm màng xương, mô xương cứng, mô xương xốp và <b>tủy xương</b> (tủy đỏ tạo máu).","Xương vừa cứng (nhờ chất khoáng, chủ yếu calcium) vừa đàn hồi (nhờ chất hữu cơ)."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm tủy xương với tủy sống: tủy xương nằm trong xương, tủy sống là bộ phận của hệ thần kinh."],"lq":["s8-he-van-dong","s8-khop-xuong","s8-benh-xuong-khop","s8-tuy-song"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-khop-xuong","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":4,"loai":"cq","ten":"Khớp xương","ten_khac":["khop xuong","khop","khop dong","khop ban dong","khop bat dong","sun khop","dich khop"],"noi_dung":"Nơi tiếp giáp giữa các đầu xương; có ba loại: khớp động, khớp bán động và khớp bất động.","cong_thuc":null,"y":["<b>Khớp động</b>: cử động linh hoạt, ví dụ khớp gối, khớp khuỷu tay; đầu xương có sụn, giữa có dịch khớp.","<b>Khớp bán động</b>: cử động hạn chế, ví dụ khớp giữa các đốt sống.","<b>Khớp bất động</b>: không cử động được, ví dụ khớp giữa các xương hộp sọ."],"bang":[["Loại khớp","Mức cử động","Ví dụ"],["Khớp động","Linh hoạt","Khớp gối, khớp vai"],["Khớp bán động","Hạn chế","Các đốt sống"],["Khớp bất động","Không cử động","Xương hộp sọ"]],"bien":null,"vd":null,"nham":null,"lq":["s8-bo-xuong","s8-he-van-dong","s8-benh-xuong-khop"],"hinh":"H-s8-khop-xuong","nguon":["KHTN Pocket"]},{"ma":"s8-he-co","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":5,"loai":"cq","ten":"Hệ cơ","ten_khac":["he co","co","co van","co xuong","bap co","soi co","co co","gan co"],"noi_dung":"Hệ gồm các cơ vân bám vào xương; cơ co và dãn làm xương cử động.","cong_thuc":null,"y":["Bắp cơ gồm nhiều <b>bó cơ</b>, mỗi bó gồm nhiều <b>sợi cơ</b> (tế bào cơ); hai đầu thon thành gân bám vào xương.","Tính chất của cơ là <b>co và dãn</b>; cơ co khi được hệ thần kinh kích thích.","Cơ làm việc quá sức lâu sẽ <b>mỏi cơ</b>; cần nghỉ ngơi, xoa bóp và luyện tập đều đặn."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ cơ có thể đẩy xương; thực ra cơ chỉ kéo được khi co, nên thường các cơ hoạt động thành từng cặp đối kháng."],"lq":["s8-he-van-dong","s8-bo-xuong","s8-khop-xuong"],"hinh":"H-s8-he-co","nguon":["KHTN Pocket"]},{"ma":"s8-benh-xuong-khop","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":6,"loai":"ud","ten":"Bệnh về xương khớp","ten_khac":["benh xuong khop","loang xuong","cong veo cot song","gu","veo","viem khop","gay xuong","thoai hoa khop","so cuu gay xuong"],"noi_dung":"Các bệnh và tật như loãng xương, cong vẹo cột sống, viêm khớp, gãy xương làm giảm khả năng vận động.","cong_thuc":null,"y":["<b>Loãng xương</b>: xương giòn, dễ gãy do thiếu calcium, thường gặp ở người cao tuổi.","<b>Cong vẹo cột sống</b>: hay gặp ở học sinh do ngồi sai tư thế, mang cặp lệch một bên.","Phòng bệnh: ăn đủ calcium và vitamin D, tắm nắng, vận động vừa sức, ngồi học đúng tư thế.","Khi gãy xương: giữ yên chỗ gãy, dùng nẹp cố định rồi đưa đến cơ sở y tế."],"bang":null,"bien":null,"vd":{"de":"Một học sinh ngồi học sai tư thế, cúi gằm và lệch vai trong thời gian dài. Nguy cơ nào về xương có thể xảy ra?","buoc":["Ngồi sai tư thế kéo dài tác động lệch lực lên cột sống.","Cột sống bị uốn lệch dần theo thời gian nếu không sửa tư thế."],"kq":"Có nguy cơ cong vẹo cột sống, cần ngồi học đúng tư thế."},"nham":["Tự nắn chỗ xương gãy; làm vậy có thể khiến đầu xương gãy làm tổn thương mạch máu, dây thần kinh."],"lq":["s8-bo-xuong","s8-khop-xuong","s8-he-van-dong","s8-chat-dinh-duong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-chat-dinh-duong","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":7,"loai":"kn","ten":"Chất dinh dưỡng","ten_khac":["chat dinh duong","dinh duong","carbohydrate","protein","lipid","vitamin","chat khoang","che do dinh duong","khau phan an","thap dinh duong"],"noi_dung":"Các chất trong thức ăn mà cơ thể sử dụng để tạo năng lượng, xây dựng cơ thể và duy trì sự sống.","cong_thuc":null,"y":["Gồm: <b>carbohydrate</b> (tinh bột, đường), <b>protein</b>, <b>lipid</b>, <b>vitamin</b>, <b>chất khoáng</b> và nước.","Carbohydrate và lipid chủ yếu cung cấp năng lượng; protein xây dựng, sửa chữa tế bào.","Vitamin và chất khoáng cần lượng nhỏ nhưng thiếu sẽ gây bệnh (thiếu vitamin A khô mắt, thiếu iodine bướu cổ).","<b>Chế độ dinh dưỡng</b> hợp lí: đủ chất, cân đối, phù hợp lứa tuổi, giới tính, mức hoạt động."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ ăn càng nhiều thịt càng tốt; ăn thừa chất dinh dưỡng cũng gây hại (béo phì, tim mạch)."],"lq":["s8-he-tieu-hoa","s8-an-toan-thuc-pham","s8-enzyme"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-he-tieu-hoa","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":8,"loai":"cq","ten":"Hệ tiêu hóa","ten_khac":["he tieu hoa","tieu hoa","ong tieu hoa","tuyen tieu hoa","co quan tieu hoa","tieu hoa o nguoi","hap thu"],"noi_dung":"Hệ gồm ống tiêu hóa và tuyến tiêu hóa, biến đổi thức ăn thành chất đơn giản và hấp thụ vào máu.","cong_thuc":null,"y":["Gồm <b>ống tiêu hóa</b> (miệng → hầu → thực quản → dạ dày → ruột non → ruột già → hậu môn) và <b>tuyến tiêu hóa</b>.","Biến đổi <b>cơ học</b> (nhai, nghiền, nhào trộn) và biến đổi <b>hóa học</b> nhờ enzyme.","Chất dinh dưỡng được hấp thụ chủ yếu ở <b>ruột non</b>; chất cặn bã thải qua hậu môn."],"bang":[["Cơ quan","Hoạt động chính"],["Miệng","Nghiền nhỏ, tiêu hóa một phần tinh bột"],["Dạ dày","Nhào trộn, tiêu hóa một phần protein"],["Ruột non","Tiêu hóa hoàn toàn, hấp thụ chất dinh dưỡng"],["Ruột già","Hấp thụ nước, tạo phân"]],"bien":null,"vd":null,"nham":["Nhầm gan, tụy là một đoạn của ống tiêu hóa; chúng là tuyến tiêu hóa nằm ngoài ống."],"lq":["s8-ong-tieu-hoa","s8-tuyen-tieu-hoa","s8-da-day","s8-ruot-non","s8-enzyme"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-ong-tieu-hoa","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":9,"loai":"cq","ten":"Ống tiêu hóa","ten_khac":["ong tieu hoa","mieng","thuc quan","hau","ruot gia","hau mon","duong di thuc an"],"noi_dung":"Đường đi của thức ăn: miệng, hầu, thực quản, dạ dày, ruột non, ruột già, hậu môn.","cong_thuc":null,"y":["<b>Miệng</b>: răng nghiền, lưỡi đảo trộn, nước bọt thấm ướt thức ăn.","<b>Thực quản</b>: co bóp đẩy thức ăn xuống dạ dày.","<b>Ruột già</b>: hấp thụ lại nước, chứa và thải phân qua hậu môn."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ thức ăn được hấp thụ nhiều ở dạ dày; thực ra dạ dày hấp thụ rất ít, chủ yếu ở ruột non."],"lq":["s8-he-tieu-hoa","s8-da-day","s8-ruot-non","s8-tuyen-tieu-hoa"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-tuyen-tieu-hoa","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":10,"loai":"cq","ten":"Tuyến tiêu hóa","ten_khac":["tuyen tieu hoa","tuyen nuoc bot","gan","mat","dich mat","tuy","dich tuy","tuyen vi","tuyen ruot"],"noi_dung":"Các tuyến tiết dịch tiêu hóa vào ống tiêu hóa: tuyến nước bọt, tuyến vị, gan, tụy, tuyến ruột.","cong_thuc":null,"y":["<b>Tuyến nước bọt</b>: tiết nước bọt có enzyme amylase.","<b>Tuyến vị</b> (thành dạ dày): tiết dịch vị có enzyme pepsin và hydrochloric acid.","<b>Gan</b>: tiết <b>mật</b>, giúp nhũ tương hóa lipid (chia lipid thành giọt nhỏ).","<b>Tụy</b> và <b>tuyến ruột</b>: tiết dịch có đủ enzyme tiêu hóa ở ruột non."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ dịch mật chứa enzyme tiêu hóa lipid; mật không có enzyme, chỉ giúp enzyme dễ tác động lên lipid."],"lq":["s8-he-tieu-hoa","s8-enzyme","s8-ruot-non","s8-tuyen-tuy"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-da-day","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":11,"loai":"cq","ten":"Dạ dày","ten_khac":["da day","bao tu","dich vi","pepsin","viem loet da day","dau da day"],"noi_dung":"Đoạn phình to nhất của ống tiêu hóa, co bóp nhào trộn thức ăn và tiêu hóa một phần protein.","cong_thuc":null,"y":["Thành dạ dày có lớp cơ dày, co bóp mạnh để <b>nhào trộn</b> thức ăn với dịch vị.","Dịch vị có enzyme <b>pepsin</b> biến đổi protein thành chuỗi ngắn hơn, có acid diệt bớt vi khuẩn.","Ăn uống thất thường, căng thẳng kéo dài dễ gây <b>viêm loét dạ dày</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-ong-tieu-hoa","s8-he-tieu-hoa","s8-enzyme","s8-ruot-non"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-ruot-non","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":12,"loai":"cq","ten":"Ruột non","ten_khac":["ruot non","long ruot","hap thu","hap thu chat dinh duong","ta trang","nep gap ruot"],"noi_dung":"Đoạn dài nhất của ống tiêu hóa, nơi thức ăn được tiêu hóa hoàn toàn và chất dinh dưỡng được hấp thụ.","cong_thuc":null,"y":["Nhận dịch mật, dịch tụy, dịch ruột nên có đủ enzyme biến đổi mọi loại thức ăn.","Sản phẩm cuối: <b>glucose</b>, <b>amino acid</b>, glycerol và acid béo, vitamin, chất khoáng.","Niêm mạc có nhiều nếp gấp và <b>lông ruột</b> chứa mạng mao mạch dày, làm tăng diện tích hấp thụ."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm ruột non là đoạn ngắn vì \"non\"; thực ra ruột non là đoạn dài nhất của ống tiêu hóa."],"lq":["s8-he-tieu-hoa","s8-tuyen-tieu-hoa","s8-enzyme","s8-da-day"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-enzyme","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":13,"loai":"kn","ten":"Enzyme tiêu hóa","ten_khac":["enzyme","enzim","men tieu hoa","amylase","pepsin","xuc tac sinh hoc"],"noi_dung":"Chất có bản chất protein, làm tăng tốc độ biến đổi thức ăn thành chất đơn giản trong ống tiêu hóa.","cong_thuc":null,"y":["Mỗi enzyme chỉ tác động lên một loại chất nhất định (<b>tính đặc hiệu</b>).","<b>Amylase</b> trong nước bọt biến đổi một phần tinh bột thành đường.","<b>Pepsin</b> trong dịch vị biến đổi protein thành chuỗi ngắn hơn.","Enzyme hoạt động tốt ở nhiệt độ cơ thể (khoảng 37 °C) và độ pH thích hợp."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ enzyme bị dùng hết sau phản ứng; thực ra enzyme không bị biến đổi, dùng được nhiều lần."],"lq":["s8-tuyen-tieu-hoa","s8-he-tieu-hoa","s8-da-day","s8-ruot-non"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-an-toan-thuc-pham","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":14,"loai":"ud","ten":"An toàn thực phẩm","ten_khac":["an toan thuc pham","ve sinh an toan thuc pham","vstp","ngo doc thuc pham","bao quan thuc pham","thuc pham ban"],"noi_dung":"Việc bảo đảm thực phẩm không gây hại cho sức khỏe, tính mạng người sử dụng.","cong_thuc":null,"y":["Nguyên nhân mất an toàn: <b>vi sinh vật</b> gây bệnh, <b>hóa chất</b> (thuốc trừ sâu, chất bảo quản quá mức), chất độc tự nhiên (mầm khoai tây, cá nóc, nấm độc).","Biện pháp: chọn thực phẩm rõ nguồn gốc, ăn chín uống sôi, rửa tay, bảo quản lạnh đúng cách.","Dấu hiệu <b>ngộ độc thực phẩm</b>: đau bụng, nôn, tiêu chảy, sốt; cần đến cơ sở y tế kịp thời."],"bang":null,"bien":null,"vd":{"de":"Thức ăn để ở nhiệt độ phòng quá lâu dễ bị ôi thiu. Cần làm gì để bảo đảm an toàn thực phẩm?","buoc":["Vi khuẩn sinh sôi nhanh ở nhiệt độ thường, sinh độc tố gây hại.","Bảo quản lạnh, nấu chín kĩ, che đậy thức ăn giúp hạn chế vi khuẩn."],"kq":"Bảo quản đúng cách và ăn chín giúp phòng ngộ độc thực phẩm."},"nham":null,"lq":["s8-chat-dinh-duong","s8-he-tieu-hoa"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-mau","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":15,"loai":"cq","ten":"Máu","ten_khac":["mau","thanh phan mau","te bao mau","huyet","blood","thanh phan cua mau"],"noi_dung":"Mô lỏng gồm huyết tương và các tế bào máu, lưu thông trong mạch để vận chuyển chất và bảo vệ cơ thể.","cong_thuc":null,"y":["Gồm <b>huyết tương</b> (khoảng 55% thể tích) và <b>tế bào máu</b> (khoảng 45%): hồng cầu, bạch cầu, tiểu cầu.","Chức năng: vận chuyển O₂, CO₂, chất dinh dưỡng, chất thải, hormone; bảo vệ cơ thể; góp phần điều hòa thân nhiệt.","Máu là một thành phần của <b>môi trường trong</b> cơ thể."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-huyet-tuong","s8-hong-cau","s8-bach-cau","s8-tieu-cau","s8-he-tuan-hoan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-huyet-tuong","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":16,"loai":"cq","ten":"Huyết tương","ten_khac":["huyet tuong","phan long cua mau","plasma","nuoc trong mau"],"noi_dung":"Phần lỏng, màu vàng nhạt của máu, chủ yếu là nước, chứa các chất hòa tan.","cong_thuc":null,"y":["Khoảng <b>90% là nước</b>, còn lại là chất dinh dưỡng, hormone, kháng thể, muối khoáng, chất thải.","Giúp máu lưu thông dễ dàng và vận chuyển các chất hòa tan.","Chứa các <b>kháng thể</b> tham gia bảo vệ cơ thể."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-mau","s8-khang-the","s8-nhom-mau"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-hong-cau","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":17,"loai":"cq","ten":"Hồng cầu","ten_khac":["hong cau","te bao hong cau","huyet sac to","hemoglobin","hb","thieu mau","red blood cell"],"noi_dung":"Tế bào máu màu đỏ, không nhân, hình đĩa lõm hai mặt, vận chuyển O₂ và CO₂.","cong_thuc":null,"y":["Chứa <b>hemoglobin</b> (huyết sắc tố) kết hợp được với O₂ và CO₂ nên máu có màu đỏ.","Hình đĩa lõm hai mặt giúp tăng diện tích tiếp xúc để trao đổi khí.","Thiếu sắt hoặc mất máu nhiều dễ dẫn đến <b>thiếu máu</b>."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm hồng cầu làm đông máu; đó là việc của tiểu cầu."],"lq":["s8-mau","s8-bach-cau","s8-tieu-cau","s8-trao-doi-khi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-bach-cau","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":18,"loai":"cq","ten":"Bạch cầu","ten_khac":["bach cau","te bao bach cau","thuc bao","bao ve co the","white blood cell","limpho"],"noi_dung":"Tế bào máu không màu, có nhân, bảo vệ cơ thể chống vi khuẩn, virus và tác nhân gây bệnh.","cong_thuc":null,"y":["Kích thước lớn hơn hồng cầu, có nhân, số lượng ít hơn nhiều.","Bảo vệ bằng cách: <b>thực bào</b> (nuốt và tiêu hủy mầm bệnh), <b>tiết kháng thể</b>, phá hủy tế bào bị nhiễm.","Là \"đội quân\" chủ lực của hệ <b>miễn dịch</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-mau","s8-mien-dich","s8-khang-the","s8-hong-cau"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-tieu-cau","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":19,"loai":"cq","ten":"Tiểu cầu","ten_khac":["tieu cau","dong mau","cam mau","platelet","tieu cau lam dong mau"],"noi_dung":"Các mảnh tế bào nhỏ trong máu, tham gia quá trình đông máu, giúp cầm máu khi bị thương.","cong_thuc":null,"y":["Không có nhân, kích thước rất nhỏ.","Khi mạch máu bị tổn thương, tiểu cầu bám vào chỗ vỡ và giải phóng chất giúp máu <b>đông</b>."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ tiểu cầu là tế bào hoàn chỉnh; thực ra là mảnh tế bào."],"lq":["s8-dong-mau","s8-mau","s8-hong-cau"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-dong-mau","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":20,"loai":"ht","ten":"Đông máu","ten_khac":["dong mau","cuc mau dong","cam mau","so cuu cam mau","chay mau","bang bo vet thuong","garo"],"noi_dung":"Hiện tượng máu chảy ra khỏi mạch tạo thành cục máu bịt kín vết thương, giúp cơ thể không mất nhiều máu.","cong_thuc":null,"y":["Nhờ <b>tiểu cầu</b> và các chất trong huyết tương tạo búi tơ máu giữ các tế bào máu thành <b>cục máu đông</b>.","Là cơ chế <b>bảo vệ</b> cơ thể chống mất máu.","Sơ cứu vết thương chảy máu: ấn chặt, băng ép chỗ chảy máu; chảy máu nhiều ở động mạch cần đưa ngay đến cơ sở y tế."],"bang":null,"bien":null,"vd":{"de":"Khi bị đứt tay nhẹ, sau vài phút máu tự ngừng chảy dù không băng bó. Vì sao?","buoc":["Tiểu cầu vỡ ra tại vết thương, giải phóng chất giúp hình thành tơ máu.","Tơ máu kết mạng giữ tế bào máu, tạo thành cục máu đông bịt vết thương."],"kq":"Đây là hiện tượng đông máu, giúp cơ thể tự cầm máu."},"nham":null,"lq":["s8-tieu-cau","s8-mau","s8-mach-mau"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-nhom-mau","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":21,"loai":"kn","ten":"Nhóm máu","ten_khac":["nhom mau","he nhom mau abo","abo","nhom mau a","nhom mau b","nhom mau ab","nhom mau o","khang nguyen a b"],"noi_dung":"Hệ ABO chia máu người thành 4 nhóm A, B, AB, O theo kháng nguyên trên hồng cầu và kháng thể trong huyết tương.","cong_thuc":null,"y":["Hồng cầu có thể mang kháng nguyên <b>A</b>, <b>B</b>; huyết tương có thể chứa kháng thể <b>α</b> (gây kết dính A), <b>β</b> (gây kết dính B).","Kháng nguyên A gặp kháng thể α (hoặc B gặp β) thì hồng cầu bị <b>kết dính</b>.","Nhóm máu được xác định khi xét nghiệm, không đổi suốt đời."],"bang":[["Nhóm máu","Kháng nguyên trên hồng cầu","Kháng thể trong huyết tương"],["A","A","β"],["B","B","α"],["AB","A và B","Không có"],["O","Không có","α và β"]],"bien":null,"vd":{"de":"Một người nhóm máu O bị tai nạn cần truyền máu gấp nhưng bệnh viện chỉ còn máu nhóm A. Có thể truyền được không?","buoc":["Người nhóm máu O chỉ nhận được máu từ người cùng nhóm O.","Máu nhóm A có kháng nguyên A, sẽ bị kháng thể trong máu người nhận nhóm O gây kết dính."],"kq":"Không thể truyền máu nhóm A cho người nhóm O, rất nguy hiểm."},"nham":["Nhầm nhóm O có kháng nguyên O; thực ra hồng cầu nhóm O không có kháng nguyên A, B."],"lq":["s8-truyen-mau","s8-khang-the","s8-hong-cau","s8-huyet-tuong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-truyen-mau","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":22,"loai":"ud","ten":"Truyền máu","ten_khac":["truyen mau","nguyen tac truyen mau","so do truyen mau","hien mau","cho mau","nhan mau","nguoi cho vang"],"noi_dung":"Đưa máu hoặc thành phần máu của người cho vào người nhận; phải xét nghiệm để máu không bị kết dính.","cong_thuc":null,"y":["Nguyên tắc: kháng nguyên trên hồng cầu người cho <b>không bị</b> kháng thể trong huyết tương người nhận gây kết dính.","Nhóm <b>O</b> có thể truyền cho các nhóm khác (lượng ít); nhóm <b>AB</b> có thể nhận của các nhóm khác.","Máu truyền phải được xét nghiệm, không nhiễm mầm bệnh (HIV, viêm gan B…).","<b>Hiến máu tình nguyện</b> là việc làm nhân đạo, cứu người."],"bang":[["Người cho","Truyền được cho"],["O","O, A, B, AB"],["A","A, AB"],["B","B, AB"],["AB","AB"]],"bien":null,"vd":{"de":"Trước khi truyền máu cho bệnh nhân, bác sĩ luôn xét nghiệm nhóm máu của cả người cho và người nhận. Vì sao bước này bắt buộc?","buoc":["Nếu nhóm máu không phù hợp, hồng cầu người cho có thể bị kết dính trong máu người nhận.","Kết dính máu gây tắc mạch, rất nguy hiểm đến tính mạng."],"kq":"Xét nghiệm nhóm máu trước truyền máu để bảo đảm an toàn cho người bệnh."},"nham":["Nghĩ cứ cùng nhóm là truyền bao nhiêu cũng được mà không cần xét nghiệm; vẫn phải xét nghiệm kĩ trước khi truyền."],"lq":["s8-nhom-mau","s8-mau","s8-khang-the"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-mien-dich","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":23,"loai":"ht","ten":"Miễn dịch","ten_khac":["mien dich","he mien dich","mien dich tu nhien","mien dich nhan tao","suc de khang","khang benh"],"noi_dung":"Khả năng cơ thể không bị mắc một bệnh nào đó dù sống trong môi trường có mầm bệnh.","cong_thuc":null,"y":["Một cách chia thường gặp: <b>miễn dịch tự nhiên</b> có sẵn từ khi sinh ra hoặc có được sau khi đã mắc bệnh và khỏi.","<b>Miễn dịch nhân tạo</b>: có được nhờ tiêm vaccine (hoặc huyết thanh).","Bạch cầu và kháng thể là thành phần chính của hệ miễn dịch."],"bang":null,"bien":null,"vd":{"de":"Nhiều người từng mắc thủy đậu khi còn nhỏ, về sau tiếp xúc với người bệnh thủy đậu khác nhưng không mắc lại. Giải thích.","buoc":["Sau lần mắc bệnh đầu, cơ thể đã tạo kháng thể đặc hiệu chống virus thủy đậu.","Kháng thể được lưu giữ, giúp cơ thể phản ứng nhanh khi gặp lại mầm bệnh."],"kq":"Cơ thể đã có miễn dịch với bệnh thủy đậu."},"nham":["Nghĩ đã có miễn dịch với bệnh này thì cũng miễn dịch với mọi bệnh; miễn dịch thường đặc hiệu với từng mầm bệnh."],"lq":["s8-bach-cau","s8-khang-the","s8-vaccine"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-khang-the","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":24,"loai":"kn","ten":"Kháng nguyên và kháng thể","ten_khac":["khang the","khang nguyen","antigen","antibody","khang nguyen khang the","phan ung khang nguyen"],"noi_dung":"Kháng nguyên là chất lạ kích thích cơ thể tạo kháng thể; kháng thể là protein do bạch cầu tạo ra để vô hiệu hóa kháng nguyên.","cong_thuc":null,"y":["<b>Kháng nguyên</b>: phân tử lạ, thường có trên bề mặt vi khuẩn, virus, hồng cầu khác nhóm.","<b>Kháng thể</b>: protein do một loại bạch cầu tiết ra, có trong huyết tương.","Kháng thể kết hợp đặc hiệu với kháng nguyên tương ứng (như chìa khóa với ổ khóa)."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-mien-dich","s8-bach-cau","s8-nhom-mau","s8-vaccine"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-vaccine","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":25,"loai":"ud","ten":"Vaccine","ten_khac":["vaccine","vac xin","vacxin","tiem chung","tiem phong","tiem vaccine","chung ngua"],"noi_dung":"Chế phẩm từ mầm bệnh đã chết hoặc làm yếu (hay thành phần của chúng), đưa vào cơ thể để tạo miễn dịch.","cong_thuc":null,"y":["Vaccine kích thích cơ thể tạo <b>kháng thể</b> mà không làm mắc bệnh.","Tạo <b>miễn dịch nhân tạo</b>, giúp phòng bệnh: sởi, lao, bại liệt, viêm gan B…","Cần <b>tiêm chủng</b> đủ mũi, đúng lịch."],"bang":null,"bien":null,"vd":{"de":"Vì sao vaccine cúm mùa được khuyến cáo tiêm nhắc lại hằng năm?","buoc":["Vaccine giúp cơ thể tạo miễn dịch với đúng chủng virus có trong vaccine.","Virus cúm biến đổi liên tục, chủng lưu hành năm sau thường khác năm trước."],"kq":"Cần tiêm vaccine cúm mới mỗi năm để phù hợp với chủng virus đang lưu hành."},"nham":["Nhầm vaccine là thuốc chữa bệnh; vaccine dùng để phòng bệnh."],"lq":["s8-mien-dich","s8-khang-the","s8-bach-cau"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-he-tuan-hoan","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":26,"loai":"cq","ten":"Hệ tuần hoàn","ten_khac":["he tuan hoan","tuan hoan","tuan hoan mau","tim va mach","he tim mach","benh tim mach"],"noi_dung":"Hệ gồm tim và hệ mạch máu, giúp máu lưu thông để vận chuyển các chất đi khắp cơ thể.","cong_thuc":null,"y":["Gồm <b>tim</b> (bơm máu) và <b>hệ mạch</b>: động mạch, mao mạch, tĩnh mạch.","Máu lưu thông theo <b>hai vòng tuần hoàn</b>: vòng nhỏ (qua phổi) và vòng lớn (đi khắp cơ thể).","Bảo vệ tim mạch: tập thể dục vừa sức, ăn ít muối, ít mỡ động vật, không hút thuốc lá."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-tim","s8-mach-mau","s8-vong-tuan-hoan","s8-huyet-ap","s8-mau"],"hinh":"H-s8-he-tuan-hoan","nguon":["KHTN Pocket"]},{"ma":"s8-tim","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":27,"loai":"cq","ten":"Tim","ten_khac":["tim","qua tim","tam nhi","tam that","van tim","chu ki tim","nhip tim","heart"],"noi_dung":"Cơ quan bằng cơ, có 4 ngăn, co bóp nhịp nhàng để đẩy máu đi trong hệ mạch.","cong_thuc":null,"y":["4 ngăn: <b>2 tâm nhĩ</b> (trên) nhận máu, <b>2 tâm thất</b> (dưới) đẩy máu đi; thành tâm thất trái dày nhất.","<b>Van tim</b> giúp máu chảy theo một chiều.","Mỗi <b>chu kì tim</b> khoảng 0,8 s: tâm nhĩ co 0,1 s, tâm thất co 0,3 s, dãn chung 0,4 s.","Người trưởng thành lúc nghỉ khoảng 75 nhịp/phút."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ tim làm việc liên tục không nghỉ; trong mỗi chu kì các ngăn tim đều có thời gian nghỉ."],"lq":["s8-he-tuan-hoan","s8-mach-mau","s8-vong-tuan-hoan","s8-huyet-ap"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-mach-mau","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":28,"loai":"cq","ten":"Mạch máu","ten_khac":["mach mau","dong mach","tinh mach","mao mach","he mach","ven","xo vua dong mach"],"noi_dung":"Hệ ống dẫn máu gồm động mạch, mao mạch và tĩnh mạch.","cong_thuc":null,"y":["<b>Động mạch</b>: dẫn máu từ tim đi; thành dày, đàn hồi, chịu áp lực lớn.","<b>Mao mạch</b>: rất nhỏ, thành mỏng một lớp tế bào; nơi trao đổi chất với tế bào.","<b>Tĩnh mạch</b>: dẫn máu về tim; thành mỏng hơn động mạch; nhiều tĩnh mạch (nhất là ở chân) có van giúp máu không chảy ngược."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ động mạch luôn chứa máu đỏ tươi; động mạch phổi dẫn máu đỏ thẫm (nghèo O₂) từ tim lên phổi."],"lq":["s8-tim","s8-he-tuan-hoan","s8-huyet-ap","s8-vong-tuan-hoan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-vong-tuan-hoan","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":29,"loai":"ht","ten":"Vòng tuần hoàn","ten_khac":["vong tuan hoan","vong tuan hoan lon","vong tuan hoan nho","tuan hoan phoi","duong di cua mau","dong mach chu"],"noi_dung":"Đường đi khép kín của máu từ tim qua mạch rồi trở về tim; người có vòng tuần hoàn nhỏ và vòng tuần hoàn lớn.","cong_thuc":null,"y":["<b>Vòng nhỏ</b>: tâm thất phải → động mạch phổi → mao mạch phổi (nhận O₂, thải CO₂) → tĩnh mạch phổi → tâm nhĩ trái.","<b>Vòng lớn</b>: tâm thất trái → động mạch chủ → mao mạch các cơ quan (trao đổi chất) → tĩnh mạch chủ → tâm nhĩ phải.","Máu đỏ tươi giàu O₂, máu đỏ thẫm giàu CO₂."],"bang":null,"bien":null,"vd":{"de":"Máu từ tim đi đến phổi lấy oxygen rồi trở về tim, sau đó mới được bơm đi nuôi toàn cơ thể. Hai chặng đường này gọi là gì?","buoc":["Chặng tim, phổi, tim là vòng tuần hoàn nhỏ.","Chặng tim, các cơ quan, tim là vòng tuần hoàn lớn."],"kq":"Đây là hai vòng tuần hoàn nhỏ và lớn của hệ tuần hoàn người."},"nham":["Nhầm vòng lớn bắt đầu từ tâm thất phải; vòng lớn bắt đầu từ tâm thất trái."],"lq":["s8-tim","s8-mach-mau","s8-he-tuan-hoan","s8-trao-doi-khi"],"hinh":"H-s8-vong-tuan-hoan","nguon":["KHTN Pocket"]},{"ma":"s8-huyet-ap","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":30,"loai":"dl","ten":"Huyết áp","ten_khac":["huyet ap","ap luc mau","mmhg","do huyet ap","huyet ap cao","huyet ap thap","tang huyet ap","cao huyet ap"],"noi_dung":"Áp lực của máu tác dụng lên thành mạch, đo bằng mmHg, gồm huyết áp tối đa và huyết áp tối thiểu.","cong_thuc":"Huyết áp = tối đa / tối thiểu (mmHg), ví dụ 120/80 mmHg","y":["Ghi dạng <b>tối đa/tối thiểu</b>, ví dụ 120/80 mmHg: tối đa khi tâm thất co, tối thiểu khi tâm thất dãn.","Ở người trưởng thành khỏe mạnh, huyết áp lúc nghỉ thường khoảng 120/80 mmHg hoặc thấp hơn một chút.","Huyết áp thường xuyên từ 140/90 mmHg trở lên là <b>tăng huyết áp</b>, dễ gây tai biến, bệnh tim.","Đo bằng <b>máy đo huyết áp</b> (điện tử hoặc đồng hồ), nên đo lúc nghỉ ngơi."],"bang":null,"bien":[["tối đa","huyết áp khi tâm thất co","mmHg"],["tối thiểu","huyết áp khi tâm thất dãn","mmHg"]],"vd":{"de":"Khi đo huyết áp, máy hiện kết quả 120/80 mmHg. Hai con số này cho biết điều gì?","buoc":["Số trên (120 mmHg) là huyết áp tối đa, đo khi tim co bóp đẩy máu.","Số dưới (80 mmHg) là huyết áp tối thiểu, đo khi tim giãn nghỉ."],"kq":"Đây là huyết áp bình thường: tối đa 120 mmHg, tối thiểu 80 mmHg."},"nham":["Đo huyết áp ngay sau khi chạy nhảy; kết quả sẽ cao hơn bình thường, cần nghỉ vài phút trước khi đo."],"lq":["s8-mach-mau","s8-tim","s8-he-tuan-hoan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-he-ho-hap","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":31,"loai":"cq","ten":"Hệ hô hấp","ten_khac":["he ho hap","ho hap","ho hap o nguoi","co quan ho hap","hit vao","tho ra","thong khi"],"noi_dung":"Hệ gồm đường dẫn khí và phổi, giúp lấy O₂ từ không khí và thải CO₂ ra ngoài.","cong_thuc":null,"y":["Gồm <b>đường dẫn khí</b> và <b>hai lá phổi</b>.","Hô hấp gồm: <b>thông khí</b> ở phổi (hít vào, thở ra), <b>trao đổi khí</b> ở phổi và ở tế bào.","Hít vào: cơ hoành, cơ liên sườn co, lồng ngực mở rộng; thở ra: các cơ dãn, lồng ngực thu nhỏ."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-duong-dan-khi","s8-phoi","s8-trao-doi-khi","s8-benh-ho-hap"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-duong-dan-khi","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":32,"loai":"cq","ten":"Đường dẫn khí","ten_khac":["duong dan khi","mui","hong","thanh quan","khi quan","phe quan","nap thanh quan"],"noi_dung":"Hệ ống dẫn không khí vào, ra phổi: mũi, họng, thanh quản, khí quản, phế quản.","cong_thuc":null,"y":["Dẫn khí và <b>làm ấm, làm ẩm, làm sạch</b> không khí (lông mũi, lớp niêm mạc tiết chất nhày, mạch máu dày đặc).","<b>Nắp thanh quản</b> đậy kín đường hô hấp khi nuốt, thức ăn không lọt vào khí quản.","Thanh quản còn giúp phát âm."],"bang":null,"bien":null,"vd":null,"nham":["Thở bằng miệng thay mũi; không khí vào phổi sẽ không được làm ấm, làm sạch tốt."],"lq":["s8-he-ho-hap","s8-phoi","s8-benh-ho-hap"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-phoi","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":33,"loai":"cq","ten":"Phổi","ten_khac":["phoi","phe nang","la phoi","mang phoi","tui phoi"],"noi_dung":"Cơ quan chính của hệ hô hấp, gồm rất nhiều phế nang, nơi diễn ra trao đổi khí với máu.","cong_thuc":null,"y":["Hai lá phổi nằm trong lồng ngực, bao ngoài có hai lớp <b>màng phổi</b>.","Đơn vị cấu tạo là <b>phế nang</b>: túi khí rất nhỏ, thành mỏng, bao quanh bởi mạng mao mạch dày đặc.","Số lượng phế nang rất lớn làm diện tích trao đổi khí rất rộng."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-he-ho-hap","s8-trao-doi-khi","s8-duong-dan-khi","s8-benh-ho-hap"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-trao-doi-khi","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":34,"loai":"ht","ten":"Trao đổi khí","ten_khac":["trao doi khi","trao doi khi o phoi","trao doi khi o te bao","khuech tan","o2","co2","oxygen","carbon dioxide"],"noi_dung":"Sự khuếch tán O₂ và CO₂ giữa phế nang với máu (ở phổi) và giữa máu với tế bào (ở các cơ quan).","cong_thuc":null,"y":["<b>Ở phổi</b>: O₂ từ phế nang vào máu, CO₂ từ máu vào phế nang.","<b>Ở tế bào</b>: O₂ từ máu vào tế bào, CO₂ từ tế bào vào máu.","Khí khuếch tán từ nơi <b>nồng độ cao</b> đến nơi <b>nồng độ thấp</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-phoi","s8-he-ho-hap","s8-hong-cau","s8-vong-tuan-hoan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-benh-ho-hap","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":35,"loai":"ud","ten":"Bệnh về hô hấp","ten_khac":["benh ho hap","viem phoi","lao phoi","hen","hen suyen","ung thu phoi","thuoc la","khoi thuoc","viem hong"],"noi_dung":"Các bệnh như viêm đường hô hấp, viêm phổi, lao phổi, hen, ung thư phổi, thường do mầm bệnh, khói bụi, khói thuốc lá.","cong_thuc":null,"y":["Tác nhân: vi khuẩn, virus, <b>bụi</b>, khí độc, <b>khói thuốc lá</b> (chứa nicotine, CO, nhiều chất gây ung thư).","Phòng bệnh: đeo khẩu trang, trồng cây xanh, không hút thuốc và tránh khói thuốc, tiêm vaccine, luyện thở sâu."],"bang":null,"bien":null,"vd":{"de":"Người hút thuốc lá lâu năm có nguy cơ mắc bệnh hô hấp cao hơn người không hút. Vì sao?","buoc":["Khói thuốc lá chứa nhiều chất độc hại làm tổn thương đường dẫn khí và phổi.","Phổi bị tổn thương lâu ngày dễ viêm nhiễm, giảm chức năng hô hấp."],"kq":"Hút thuốc lá làm tăng nguy cơ mắc bệnh về đường hô hấp."},"nham":["Nghĩ chỉ người hút thuốc mới bị hại; người hít khói thuốc thụ động cũng bị ảnh hưởng."],"lq":["s8-he-ho-hap","s8-phoi","s8-duong-dan-khi","s8-vaccine"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-he-bai-tiet","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":36,"loai":"cq","ten":"Hệ bài tiết","ten_khac":["he bai tiet","bai tiet","bai tiet nuoc tieu","co quan bai tiet","bong dai","bang quang","ong dan nuoc tieu","ong dai"],"noi_dung":"Hệ lọc và thải chất thải, chất độc, chất dư thừa ra ngoài để giữ ổn định môi trường trong.","cong_thuc":null,"y":["Các cơ quan bài tiết: <b>phổi</b> (thải CO₂), <b>da</b> (thải mồ hôi), <b>thận</b> (thải nước tiểu).","Hệ bài tiết nước tiểu: <b>thận</b> → ống dẫn nước tiểu → <b>bóng đái</b> → ống đái.","Giữ gìn: uống đủ nước, không nhịn tiểu lâu, ăn ít muối, hạn chế đồ ăn nhiều chất độc hại."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ bài tiết chỉ là đi tiểu; thải CO₂ qua phổi, mồ hôi qua da cũng là bài tiết."],"lq":["s8-than","s8-nuoc-tieu","s8-da","s8-can-bang-moi-truong-trong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-than","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":37,"loai":"cq","ten":"Thận","ten_khac":["than","qua than","than nguoi","soi than","suy than","benh than","kidney"],"noi_dung":"Cơ quan chính của hệ bài tiết nước tiểu, lọc máu để tạo thành nước tiểu.","cong_thuc":null,"y":["Người có <b>2 quả thận</b>, mỗi quả gồm khoảng 1 triệu <b>nephron</b>.","Cấu tạo: phần vỏ, phần tủy, bể thận.","Bệnh thường gặp: <b>sỏi thận</b>, viêm thận, suy thận; phòng bằng uống đủ nước, ăn uống hợp lí."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-nephron","s8-nuoc-tieu","s8-he-bai-tiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-nephron","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":38,"loai":"cq","ten":"Nephron","ten_khac":["nephron","don vi chuc nang cua than","cau than","nang cau than","ong than","nefron"],"noi_dung":"Đơn vị cấu tạo và chức năng của thận, nơi lọc máu và tạo nước tiểu.","cong_thuc":null,"y":["Gồm <b>cầu thận</b> (búi mao mạch), <b>nang cầu thận</b> bao quanh và <b>ống thận</b>.","Cầu thận lọc máu; ống thận hấp thụ lại chất cần thiết và bài tiết tiếp chất thải."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-than","s8-nuoc-tieu","s8-he-bai-tiet"],"hinh":"H-s8-nephron","nguon":["KHTN Pocket"]},{"ma":"s8-nuoc-tieu","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":39,"loai":"ht","ten":"Sự tạo thành nước tiểu","ten_khac":["nuoc tieu","tao thanh nuoc tieu","nuoc tieu dau","nuoc tieu chinh thuc","loc mau","tai hap thu","urea"],"noi_dung":"Quá trình thận lọc máu ở cầu thận rồi xử lí ở ống thận để tạo nước tiểu chính thức.","cong_thuc":null,"y":["<b>Lọc máu</b> ở cầu thận → <b>nước tiểu đầu</b> (gần như không có tế bào máu và protein).","<b>Hấp thụ lại</b> ở ống thận: nước, glucose, chất cần thiết trở về máu.","<b>Bài tiết tiếp</b> chất thải, chất thừa → <b>nước tiểu chính thức</b>, đổ về bể thận rồi xuống bóng đái."],"bang":null,"bien":null,"vd":{"de":"Khi uống nhiều nước, ta thấy đi tiểu nhiều hơn và nước tiểu loãng, nhạt màu hơn bình thường. Giải thích.","buoc":["Thận lọc máu, lượng nước dư thừa trong máu sẽ được lọc thải qua nước tiểu.","Nước tiểu loãng hơn vì tỉ lệ nước cao hơn so với chất hòa tan."],"kq":"Uống nhiều nước làm thận tạo nhiều nước tiểu loãng hơn để cân bằng lượng nước."},"nham":["Nhầm nước tiểu đầu với nước tiểu chính thức: nước tiểu đầu còn nhiều chất dinh dưỡng, nước tiểu chính thức đậm đặc chất thải."],"lq":["s8-nephron","s8-than","s8-he-bai-tiet"],"hinh":"H-s8-nuoc-tieu","nguon":["KHTN Pocket"]},{"ma":"s8-moi-truong-trong","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":40,"loai":"kn","ten":"Môi trường trong cơ thể","ten_khac":["moi truong trong","moi truong trong co the","dich mo","nuoc mo","bach huyet","dich co the"],"noi_dung":"Môi trường bao quanh tế bào trong cơ thể, gồm máu, nước mô và bạch huyết.","cong_thuc":null,"y":["Gồm <b>máu</b>, <b>nước mô</b> (dịch mô) và <b>bạch huyết</b>.","Giúp tế bào trao đổi chất với môi trường ngoài: nhận O₂, chất dinh dưỡng và thải chất thải."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm môi trường trong là các cơ quan bên trong cơ thể; thực ra là các dịch bao quanh tế bào."],"lq":["s8-can-bang-moi-truong-trong","s8-mau","s8-he-bai-tiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-can-bang-moi-truong-trong","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":41,"loai":"ht","ten":"Cân bằng môi trường trong","ten_khac":["can bang moi truong trong","can bang noi moi","on dinh moi truong trong","dieu hoa moi truong trong","ph mau","duong huyet"],"noi_dung":"Sự duy trì ổn định các điều kiện lí, hóa của môi trường trong, bảo đảm cơ thể hoạt động bình thường.","cong_thuc":null,"y":["Các chỉ số như nhiệt độ, pH máu (khoảng 7,35–7,45), nồng độ glucose, muối khoáng được giữ trong giới hạn nhất định.","Do hệ thần kinh, hệ nội tiết điều khiển với sự tham gia của thận, phổi, da, gan…","Mất cân bằng môi trường trong gây bệnh, ví dụ tiểu đường khi glucose máu luôn cao."],"bang":null,"bien":null,"vd":{"de":"Sau bữa ăn, lượng đường trong máu tăng lên nhưng sau đó nhanh chóng trở lại mức bình thường. Đây là biểu hiện của cơ chế nào?","buoc":["Tuyến tụy tiết hormone điều chỉnh khi glucose máu tăng cao.","Nhờ đó glucose máu được đưa trở lại mức ổn định."],"kq":"Đây là cơ chế cân bằng môi trường trong của cơ thể."},"nham":null,"lq":["s8-moi-truong-trong","s8-he-noi-tiet","s8-he-bai-tiet","s8-tuyen-tuy"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-he-than-kinh","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":42,"loai":"cq","ten":"Hệ thần kinh","ten_khac":["he than kinh","than kinh","than kinh trung uong","than kinh ngoai bien","day than kinh","hach than kinh","benh than kinh"],"noi_dung":"Hệ điều khiển, điều hòa và phối hợp hoạt động của các cơ quan, giúp cơ thể thích nghi với môi trường.","cong_thuc":null,"y":["<b>Bộ phận trung ương</b>: não và tủy sống; <b>bộ phận ngoại biên</b>: dây thần kinh và hạch thần kinh.","Theo chức năng: hệ thần kinh <b>vận động</b> (điều khiển cơ vân, có ý thức) và hệ thần kinh <b>sinh dưỡng</b> (điều khiển nội quan).","Bảo vệ: ngủ đủ, tránh căng thẳng, không dùng chất kích thích, chất gây nghiện."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-neuron","s8-nao","s8-tuy-song","s8-phan-xa","s8-chat-gay-nghien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-neuron","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":43,"loai":"cq","ten":"Neuron","ten_khac":["neuron","noron","te bao than kinh","soi truc","soi nhanh","than neuron","xinap","synapse"],"noi_dung":"Tế bào thần kinh, đơn vị cấu tạo của hệ thần kinh, có chức năng cảm ứng và dẫn truyền xung thần kinh.","cong_thuc":null,"y":["Gồm <b>thân</b> (chứa nhân), nhiều <b>sợi nhánh</b> ngắn và một <b>sợi trục</b> dài.","Xung thần kinh truyền theo một chiều: sợi nhánh → thân → sợi trục.","Nơi tiếp nối giữa các neuron hoặc giữa neuron và cơ quan gọi là <b>synapse</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-he-than-kinh","s8-phan-xa","s8-nao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-nao","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":44,"loai":"cq","ten":"Não","ten_khac":["nao","bo nao","dai nao","tieu nao","tru nao","nao trung gian","vo nao"],"noi_dung":"Bộ phận trung ương thần kinh nằm trong hộp sọ, gồm trụ não, tiểu não, não trung gian và đại não.","cong_thuc":null,"y":["<b>Đại não</b>: lớn nhất, vỏ não có nhiều nếp gấp; trung khu của cảm giác, vận động có ý thức, tư duy, ngôn ngữ.","<b>Tiểu não</b>: điều hòa, phối hợp cử động và giữ thăng bằng.","<b>Trụ não</b>: điều khiển hoạt động nội quan như hô hấp, tuần hoàn, tiêu hóa."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm tiểu não điều khiển tư duy; tư duy, ngôn ngữ do vỏ đại não."],"lq":["s8-he-than-kinh","s8-tuy-song","s8-neuron"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-tuy-song","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":45,"loai":"cq","ten":"Tủy sống","ten_khac":["tuy song","chat xam","chat trang","day than kinh tuy","cot song"],"noi_dung":"Bộ phận trung ương thần kinh nằm trong ống xương sống, là trung khu của nhiều phản xạ không điều kiện.","cong_thuc":null,"y":["<b>Chất xám</b> ở giữa (hình cánh bướm) là trung khu phản xạ; <b>chất trắng</b> bao ngoài là đường dẫn truyền nối với não.","Có <b>31 đôi dây thần kinh tủy</b>.","Chấn thương cột sống có thể làm tổn thương tủy sống, gây liệt."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm tủy sống với tủy xương."],"lq":["s8-he-than-kinh","s8-nao","s8-phan-xa","s8-bo-xuong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-phan-xa","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":46,"loai":"ht","ten":"Phản xạ","ten_khac":["phan xa","cung phan xa","phan xa khong dieu kien","phan xa co dieu kien","phan ung","reflex"],"noi_dung":"Phản ứng của cơ thể trả lời kích thích của môi trường, thực hiện qua hệ thần kinh.","cong_thuc":null,"y":["<b>Cung phản xạ</b> gồm 5 thành phần: cơ quan thụ cảm → neuron cảm giác (hướng tâm) → trung ương thần kinh → neuron vận động (li tâm) → cơ quan phản ứng.","Ví dụ: chạm tay vào vật nóng thì rụt tay lại; thấy quả chanh thì tiết nước bọt."],"bang":null,"bien":null,"vd":{"de":"Khi ánh sáng mạnh chiếu vào mắt, đồng tử tự động co nhỏ lại mà ta không cần suy nghĩ. Đây là hiện tượng gì?","buoc":["Kích thích ánh sáng mạnh được cơ quan thụ cảm ở mắt tiếp nhận.","Xung thần kinh truyền qua hệ thần kinh, gây phản ứng co đồng tử."],"kq":"Đây là một phản xạ của cơ thể."},"nham":["Gọi phản ứng của cây trinh nữ khi chạm vào là phản xạ; thực vật không có hệ thần kinh nên đó là cảm ứng."],"lq":["s8-neuron","s8-he-than-kinh","s8-tuy-song"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-chat-gay-nghien","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":47,"loai":"ud","ten":"Chất gây nghiện","ten_khac":["chat gay nghien","ma tuy","ruou bia","thuoc la","chat kich thich","nicotine","nghien"],"noi_dung":"Các chất như ma túy, rượu bia, thuốc lá gây lệ thuộc và làm tổn hại hệ thần kinh cùng nhiều cơ quan khác.","cong_thuc":null,"y":["Gây rối loạn hoạt động thần kinh, giảm trí nhớ, dễ mất kiểm soát hành vi.","Gây hại tim mạch, gan, phổi; ma túy còn dễ lây nhiễm HIV khi dùng chung kim tiêm.","Nói <b>không</b> với ma túy; học sinh không sử dụng rượu bia, thuốc lá."],"bang":null,"bien":null,"vd":{"de":"Một người dùng thử chất gây nghiện vài lần rồi dần phải dùng liều cao hơn mới thấy tác dụng như trước. Vì sao?","buoc":["Chất gây nghiện tác động và làm tổn hại hệ thần kinh.","Cơ thể quen dần, cần liều cao hơn mới có tác dụng như trước."],"kq":"Đây là biểu hiện của nghiện chất, rất nguy hiểm và khó cai."},"nham":null,"lq":["s8-he-than-kinh","s8-nao","s8-benh-ho-hap"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-mat","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":48,"loai":"cq","ten":"Mắt","ten_khac":["mat","cau tao mat","giac quan thi giac","mang luoi","the thuy tinh","dong tu","te bao non","te bao que","thi giac"],"noi_dung":"Cơ quan thị giác, thu nhận ánh sáng và tạo ảnh trên màng lưới rồi truyền về não.","cong_thuc":null,"y":["Cầu mắt có 3 lớp màng: <b>màng cứng</b> (phía trước là màng giác trong suốt), <b>màng mạch</b>, <b>màng lưới</b>.","Ánh sáng qua màng giác, thủy dịch, <b>thể thủy tinh</b>, dịch thủy tinh rồi tạo ảnh trên màng lưới.","Màng lưới có <b>tế bào nón</b> (nhìn màu, ánh sáng mạnh) và <b>tế bào que</b> (nhìn lúc ánh sáng yếu).","Bảo vệ mắt: đọc sách đủ sáng, giữ khoảng cách, hạn chế nhìn màn hình lâu."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-can-thi","s8-vien-thi","s8-tai","s8-he-than-kinh"],"hinh":"H-s8-mat","nguon":["KHTN Pocket"]},{"ma":"s8-can-thi","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":49,"loai":"kn","ten":"Cận thị","ten_khac":["can thi","mat can","tat can thi","kinh can","nhin gan"],"noi_dung":"Tật mắt chỉ nhìn rõ vật ở gần, không nhìn rõ vật ở xa; ảnh của vật ở xa hiện trước màng lưới.","cong_thuc":null,"y":["Nguyên nhân: cầu mắt dài bẩm sinh hoặc thể thủy tinh quá phồng do đọc sách quá gần, nhìn màn hình lâu.","Khắc phục: đeo <b>kính cận</b> (kính mặt lõm, phân kì).","Phòng tránh: ngồi học đúng tư thế, đủ ánh sáng, nghỉ mắt định kì."],"bang":null,"bien":null,"vd":{"de":"Một bạn học sinh ngồi cuối lớp nhìn chữ trên bảng bị mờ, nhưng đọc sách gần vẫn rõ. Đây là tật gì và cần làm gì?","buoc":["Nhìn xa mờ, nhìn gần rõ là dấu hiệu của cận thị.","Ảnh của vật ở xa hiện ra trước màng lưới thay vì đúng trên màng lưới."],"kq":"Cần đi khám và đeo kính cận phù hợp."},"nham":["Nhầm cận thị với viễn thị: cận thị nhìn rõ gần, viễn thị nhìn rõ xa."],"lq":["s8-mat","s8-vien-thi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-vien-thi","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":50,"loai":"kn","ten":"Viễn thị","ten_khac":["vien thi","mat vien","tat vien thi","kinh vien","lao thi","nhin xa"],"noi_dung":"Tật mắt chỉ nhìn rõ vật ở xa, không nhìn rõ vật ở gần; ảnh của vật ở gần hiện sau màng lưới.","cong_thuc":null,"y":["Nguyên nhân: cầu mắt ngắn bẩm sinh, hoặc ở người già thể thủy tinh bị lão hóa, kém phồng (<b>lão thị</b>).","Khắc phục: đeo <b>kính viễn</b> (kính mặt lồi, hội tụ)."],"bang":null,"bien":null,"vd":{"de":"Một bạn học sinh nhìn rõ vật ở xa nhưng đọc sách ở gần thấy mờ, nhanh mỏi mắt. Đây có thể là tật gì?","buoc":["Nhìn xa rõ, nhìn gần mờ là dấu hiệu của viễn thị.","Ảnh của vật ở gần hiện ra sau màng lưới thay vì đúng trên màng lưới."],"kq":"Có thể là viễn thị; cần đi khám mắt và đeo kính phù hợp theo chỉ định."},"nham":["Nghĩ người viễn thị nhìn mọi thứ đều rõ hơn người thường; họ khó nhìn rõ vật ở gần như khi đọc sách."],"lq":["s8-mat","s8-can-thi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-tai","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":51,"loai":"cq","ten":"Tai","ten_khac":["tai","cau tao tai","giac quan thinh giac","mang nhi","oc tai","chuoi xuong tai","tien dinh","viem tai giua","thinh giac"],"noi_dung":"Cơ quan thính giác và giữ thăng bằng, gồm tai ngoài, tai giữa và tai trong.","cong_thuc":null,"y":["<b>Tai ngoài</b>: vành tai, ống tai (hứng và dẫn âm), kết thúc ở <b>màng nhĩ</b>.","<b>Tai giữa</b>: <b>chuỗi xương tai</b> truyền rung động từ màng nhĩ vào tai trong.","<b>Tai trong</b>: <b>ốc tai</b> thu nhận âm thanh; <b>bộ phận tiền đình</b> giúp giữ thăng bằng.","Bảo vệ tai: không ngoáy tai bằng vật nhọn, tránh tiếng ồn lớn, chữa kịp thời viêm họng để phòng viêm tai giữa."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-mat","s8-he-than-kinh","s8-nao"],"hinh":"H-s8-tai","nguon":["KHTN Pocket"]},{"ma":"s8-he-noi-tiet","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":52,"loai":"cq","ten":"Hệ nội tiết","ten_khac":["he noi tiet","noi tiet","tuyen noi tiet","tuyen ngoai tiet","tuyen pha","cac tuyen noi tiet"],"noi_dung":"Hệ gồm các tuyến nội tiết, tiết hormone vào máu để điều hòa hoạt động của cơ thể.","cong_thuc":null,"y":["<b>Tuyến nội tiết</b>: chất tiết (hormone) đổ thẳng vào máu; <b>tuyến ngoại tiết</b>: chất tiết theo ống dẫn ra ngoài (tuyến mồ hôi, tuyến nước bọt).","Các tuyến nội tiết chính: tuyến yên, tuyến giáp, tuyến tụy, tuyến trên thận, tuyến sinh dục.","Tuyến tụy, tuyến sinh dục vừa nội tiết vừa ngoại tiết (<b>tuyến pha</b>)."],"bang":[["Tuyến","Hormone tiêu biểu","Vai trò"],["Tuyến yên","GH (tăng trưởng)","Kích thích sinh trưởng; điều khiển tuyến khác"],["Tuyến giáp","Thyroxine","Điều hòa trao đổi chất"],["Tuyến tụy","Insulin, glucagon","Điều hòa glucose máu"],["Tuyến trên thận","Adrenaline, cortisol","Ứng phó căng thẳng"],["Tuyến sinh dục","Testosterone, estrogen","Phát triển giới tính"]],"bien":null,"vd":null,"nham":["Xếp tuyến nước bọt vào tuyến nội tiết; nó là tuyến ngoại tiết."],"lq":["s8-hormone","s8-tuyen-yen","s8-tuyen-giap","s8-tuyen-tuy","s8-tuyen-tren-than"],"hinh":"H-s8-he-noi-tiet","nguon":["KHTN Pocket"]},{"ma":"s8-hormone","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":53,"loai":"kn","ten":"Hormone","ten_khac":["hormone","hoocmon","hormon","noi tiet to","chat tiet cua tuyen noi tiet"],"noi_dung":"Chất hóa học do tuyến nội tiết tiết vào máu, được máu đưa tới cơ quan đích để điều hòa hoạt động.","cong_thuc":null,"y":["Hoạt tính mạnh: chỉ với <b>lượng rất nhỏ</b> đã gây tác dụng rõ.","Có <b>tính đặc hiệu</b>: mỗi hormone tác động lên cơ quan hoặc tế bào xác định.","Thừa hoặc thiếu hormone đều gây bệnh."],"bang":null,"bien":null,"vd":{"de":"Sau bữa ăn, tuyến tụy tiết ra insulin vào máu. Insulin có phải là enzyme tiêu hóa không? Vì sao?","buoc":["Insulin được tuyến tụy tiết vào máu để tác động lên tế bào khắp cơ thể, không đổ vào ống tiêu hóa.","Đây là hormone điều hòa lượng đường trong máu, không phải enzyme tiêu hóa thức ăn."],"kq":"Insulin là hormone, không phải enzyme tiêu hóa."},"nham":null,"lq":["s8-he-noi-tiet","s8-tuyen-tuy","s8-tuyen-giap","s8-tuyen-yen"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-tuyen-yen","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":54,"loai":"cq","ten":"Tuyến yên","ten_khac":["tuyen yen","gh","hormone tang truong","hormone sinh truong","nguoi khong lo","lun"],"noi_dung":"Tuyến nhỏ nằm ở nền sọ, tiết hormone tăng trưởng và điều khiển hoạt động nhiều tuyến nội tiết khác.","cong_thuc":null,"y":["Tiết <b>GH</b> (hormone tăng trưởng) kích thích sự lớn lên của cơ thể.","Tiết các hormone điều khiển tuyến giáp, tuyến trên thận, tuyến sinh dục.","Thiếu GH ở trẻ em gây lùn; thừa GH gây khổng lồ."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-he-noi-tiet","s8-hormone","s8-tuyen-giap"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-tuyen-giap","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":55,"loai":"cq","ten":"Tuyến giáp","ten_khac":["tuyen giap","thyroxine","tiroxin","buou co","iodine","iot","muoi iot"],"noi_dung":"Tuyến nằm ở cổ, phía trước khí quản, tiết thyroxine điều hòa trao đổi chất của cơ thể.","cong_thuc":null,"y":["Hormone <b>thyroxine</b> có chứa <b>iodine</b>, tham gia điều hòa trao đổi chất và năng lượng.","Thiếu iodine → thiếu thyroxine → tuyến giáp to ra gây <b>bướu cổ</b>; trẻ em chậm lớn, kém phát triển trí tuệ.","Phòng bệnh: dùng muối iodine, ăn hải sản."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-he-noi-tiet","s8-hormone","s8-tuyen-yen"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-tuyen-tuy","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":56,"loai":"cq","ten":"Tuyến tụy","ten_khac":["tuyen tuy","tuy","insulin","glucagon","duong huyet","tieu duong","dai thao duong","glucose mau"],"noi_dung":"Tuyến vừa tiết dịch tụy vào ruột non, vừa tiết insulin và glucagon điều hòa lượng glucose trong máu.","cong_thuc":null,"y":["Chức năng ngoại tiết: tiết <b>dịch tụy</b> tiêu hóa thức ăn.","<b>Insulin</b>: làm <b>giảm</b> glucose máu khi glucose máu tăng (sau ăn).","<b>Glucagon</b>: làm <b>tăng</b> glucose máu khi glucose máu giảm (lúc đói).","Thiếu insulin hoặc insulin kém tác dụng → glucose máu luôn cao → bệnh <b>tiểu đường</b> (đái tháo đường)."],"bang":null,"bien":null,"vd":{"de":"Một người có lượng đường trong máu luôn cao hơn bình thường dù ăn uống điều độ, bác sĩ nghi ngờ tuyến tụy hoạt động kém. Vì sao tuyến tụy liên quan đến bệnh này?","buoc":["Tuyến tụy tiết insulin, hormone làm giảm glucose trong máu.","Tuyến tụy hoạt động kém khiến thiếu insulin, glucose máu không được điều hòa, tăng cao."],"kq":"Đây có thể là dấu hiệu của bệnh đái tháo đường liên quan đến tuyến tụy."},"nham":["Nhầm insulin làm tăng đường huyết; insulin làm giảm, glucagon làm tăng."],"lq":["s8-he-noi-tiet","s8-hormone","s8-tuyen-tieu-hoa","s8-can-bang-moi-truong-trong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-tuyen-tren-than","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":57,"loai":"cq","ten":"Tuyến trên thận","ten_khac":["tuyen tren than","thuong than","adrenaline","adrenalin","cortisol","hormone cang thang"],"noi_dung":"Đôi tuyến nằm trên hai quả thận, tiết adrenaline, cortisol giúp cơ thể thích nghi khi căng thẳng.","cong_thuc":null,"y":["<b>Adrenaline</b>: tăng nhịp tim, tăng huyết áp, tăng glucose máu khi hồi hộp, sợ hãi.","<b>Cortisol</b>: tham gia điều hòa glucose máu và ứng phó căng thẳng kéo dài."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-he-noi-tiet","s8-hormone","s8-than"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-da","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":58,"loai":"cq","ten":"Da","ten_khac":["da","cau tao da","bieu bi","lop bi","tuyen mo hoi","tuyen nhon","lop mo duoi da","mun trung ca","bong"],"noi_dung":"Lớp bao bọc cơ thể, bảo vệ, cảm giác, bài tiết mồ hôi và tham gia điều hòa thân nhiệt.","cong_thuc":null,"y":["Ba lớp: <b>lớp biểu bì</b> (ngoài cùng), <b>lớp bì</b> (có mạch máu, tuyến mồ hôi, tuyến nhờn, thụ quan, chân lông), <b>lớp mỡ dưới da</b>.","Chức năng: bảo vệ, tiếp nhận kích thích, bài tiết, điều hòa thân nhiệt.","Giữ vệ sinh da; khi bị bỏng nhẹ cần ngâm vùng bỏng vào nước sạch, mát."],"bang":null,"bien":null,"vd":null,"nham":["Nặn mụn bằng tay bẩn; dễ gây nhiễm trùng, để lại sẹo."],"lq":["s8-dieu-hoa-than-nhiet","s8-he-bai-tiet","s8-he-than-kinh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-dieu-hoa-than-nhiet","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":59,"loai":"ht","ten":"Điều hòa thân nhiệt","ten_khac":["dieu hoa than nhiet","than nhiet","nhiet do co the","soc nhiet","say nang","cam lanh","toat mo hoi","sot"],"noi_dung":"Cơ chế giữ nhiệt độ cơ thể ổn định (khoảng 37 °C) nhờ cân bằng sinh nhiệt và tỏa nhiệt.","cong_thuc":null,"y":["Trời nóng: mạch máu dưới da <b>dãn</b>, tăng <b>tiết mồ hôi</b> để tỏa nhiệt.","Trời lạnh: mạch máu dưới da <b>co</b>, cơ chân lông co (nổi da gà), run để sinh nhiệt.","Do <b>hệ thần kinh</b> điều khiển, da là cơ quan quan trọng nhất trong điều hòa thân nhiệt.","Say nắng: đưa người bệnh vào chỗ mát, nới lỏng quần áo, chườm mát, cho uống nước."],"bang":null,"bien":null,"vd":{"de":"Khi trời nóng hoặc vận động mạnh, cơ thể đổ nhiều mồ hôi. Việc này giúp ích gì cho cơ thể?","buoc":["Tuyến mồ hôi tiết nhiều mồ hôi ra bề mặt da khi cơ thể nóng lên.","Mồ hôi bay hơi lấy đi nhiệt, giúp hạ bớt nhiệt độ cơ thể."],"kq":"Đổ mồ hôi giúp cơ thể tỏa bớt nhiệt, giữ thân nhiệt ổn định."},"nham":["Nghĩ đổ mồ hôi chỉ làm mất nước; thực ra mồ hôi bay hơi giúp mang nhiệt ra khỏi cơ thể."],"lq":["s8-da","s8-can-bang-moi-truong-trong","s8-he-than-kinh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-sinh-duc-nam","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":60,"loai":"cq","ten":"Cơ quan sinh dục nam","ten_khac":["co quan sinh duc nam","sinh duc nam","tinh hoan","tinh trung","ong dan tinh","testosterone","tuyen tien liet"],"noi_dung":"Cơ quan tạo tinh trùng và hormone sinh dục nam, gồm tinh hoàn, ống dẫn tinh, túi tinh, dương vật và các tuyến.","cong_thuc":null,"y":["<b>Tinh hoàn</b>: sản sinh <b>tinh trùng</b> (từ tuổi dậy thì) và hormone <b>testosterone</b>.","Tinh trùng đi qua mào tinh, ống dẫn tinh, được túi tinh, tuyến tiền liệt tiết dịch tạo thành tinh dịch.","Testosterone gây biến đổi cơ thể tuổi dậy thì ở nam: vỡ giọng, mọc râu…"],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-sinh-duc-nu","s8-thu-tinh","s8-he-noi-tiet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-sinh-duc-nu","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":61,"loai":"cq","ten":"Cơ quan sinh dục nữ","ten_khac":["co quan sinh duc nu","sinh duc nu","buong trung","trung","tu cung","ong dan trung","estrogen","progesterone"],"noi_dung":"Cơ quan tạo trứng và hormone sinh dục nữ, gồm buồng trứng, ống dẫn trứng, tử cung, âm đạo.","cong_thuc":null,"y":["<b>Buồng trứng</b>: sản sinh <b>trứng</b> (từ tuổi dậy thì) và hormone <b>estrogen</b>, <b>progesterone</b>.","<b>Ống dẫn trứng</b>: đón trứng, là nơi thường diễn ra thụ tinh.","<b>Tử cung</b>: nơi phôi làm tổ và thai phát triển."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-sinh-duc-nam","s8-kinh-nguyet","s8-thu-tinh","s8-thai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-kinh-nguyet","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":62,"loai":"ht","ten":"Kinh nguyệt","ten_khac":["kinh nguyet","chu ki kinh nguyet","hanh kinh","rung trung","day thi o nu","ve sinh kinh nguyet"],"noi_dung":"Hiện tượng lớp niêm mạc tử cung bong ra, thoát ra ngoài cùng máu khi trứng không được thụ tinh, lặp lại theo chu kì.","cong_thuc":null,"y":["Là dấu hiệu nữ đã bước vào tuổi <b>dậy thì</b>.","Chu kì thường khoảng <b>28–32 ngày</b> (tùy người), mỗi lần hành kinh kéo dài vài ngày.","Cần giữ vệ sinh, thay băng vệ sinh thường xuyên."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-sinh-duc-nu","s8-thu-tinh","s8-tranh-thai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-thu-tinh","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":63,"loai":"ht","ten":"Thụ tinh và thụ thai","ten_khac":["thu tinh","thu thai","hop tu","lam to","mang thai","tinh trung gap trung"],"noi_dung":"Thụ tinh là tinh trùng kết hợp với trứng tạo hợp tử; thụ thai là phôi làm tổ được trong niêm mạc tử cung.","cong_thuc":null,"y":["<b>Thụ tinh</b> thường xảy ra ở ống dẫn trứng; chỉ một tinh trùng kết hợp với trứng.","Hợp tử vừa di chuyển xuống tử cung vừa phân chia thành phôi.","<b>Thụ thai</b>: phôi bám và làm tổ ở lớp niêm mạc tử cung."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm thụ tinh và thụ thai là một; thụ tinh xảy ra trước, thụ thai là khi phôi làm tổ thành công."],"lq":["s8-sinh-duc-nu","s8-sinh-duc-nam","s8-thai","s8-tranh-thai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-thai","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":64,"loai":"ht","ten":"Sự phát triển của thai","ten_khac":["thai","phat trien cua thai","nhau thai","bao thai","mang thai","day ron","sinh con"],"noi_dung":"Quá trình phôi phát triển thành thai trong tử cung, nhận chất dinh dưỡng từ mẹ qua nhau thai, khoảng 9 tháng.","cong_thuc":null,"y":["Thai nhận O₂ và chất dinh dưỡng, thải chất thải qua <b>nhau thai</b> và dây rốn.","Mẹ mang thai cần ăn đủ chất, không dùng rượu bia, thuốc lá, khám thai định kì."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-thu-tinh","s8-sinh-duc-nu","s8-tranh-thai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-tranh-thai","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":65,"loai":"ud","ten":"Biện pháp tránh thai","ten_khac":["tranh thai","bien phap tranh thai","bao cao su","thuoc tranh thai","dung cu tu cung","mang thai o tuoi vi thanh nien","vong"],"noi_dung":"Các cách ngăn không cho thụ tinh hoặc không cho phôi làm tổ, giúp chủ động việc có con.","cong_thuc":null,"y":["Nguyên tắc: ngăn trứng chín và rụng; ngăn tinh trùng gặp trứng; ngăn trứng đã thụ tinh làm tổ.","Biện pháp: <b>bao cao su</b> (còn phòng bệnh lây truyền qua đường sinh dục), thuốc tránh thai, dụng cụ tử cung.","Mang thai ở tuổi vị thành niên gây nhiều nguy cơ cho sức khỏe, học tập của người mẹ."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-thu-tinh","s8-benh-lay-qua-duong-sinh-duc","s8-kinh-nguyet"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-benh-lay-qua-duong-sinh-duc","mon":"KHTN","khoi":"8","chu_de":"s8-co-the-nguoi","thu_tu":66,"loai":"ud","ten":"Bệnh lây truyền qua đường sinh dục","ten_khac":["benh lay truyen qua duong sinh duc","benh lay qua duong sinh duc","benh lay truyen qua duong tinh duc","hiv","aids","lau","giang mai","benh xa hoi"],"noi_dung":"Các bệnh lây truyền chủ yếu qua quan hệ tình dục không an toàn, như HIV/AIDS, lậu, giang mai.","cong_thuc":null,"y":["<b>HIV/AIDS</b>: virus HIV phá hủy tế bào miễn dịch; lây qua đường máu, tình dục, mẹ sang con.","<b>Lậu</b>, <b>giang mai</b>: do vi khuẩn gây nên.","Phòng bệnh: sống lành mạnh, quan hệ tình dục an toàn, không dùng chung kim tiêm, dao cạo."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ HIV lây qua bắt tay, ăn chung, muỗi đốt; HIV không lây qua các con đường đó."],"lq":["s8-tranh-thai","s8-mien-dich","s8-sinh-duc-nam","s8-sinh-duc-nu"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-moi-truong-song","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":1,"loai":"kn","ten":"Môi trường sống","ten_khac":["moi truong song","moi truong","moi truong tren can","moi truong nuoc","moi truong trong dat","moi truong sinh vat","noi song"],"noi_dung":"Nơi sinh sống của sinh vật, gồm tất cả các nhân tố xung quanh ảnh hưởng đến sinh vật.","cong_thuc":null,"y":["Bốn loại chính: <b>môi trường trên cạn</b>, <b>môi trường nước</b>, <b>môi trường trong đất</b>, <b>môi trường sinh vật</b>.","Môi trường sinh vật: cơ thể sinh vật là nơi sống của sinh vật khác (ví dụ giun sán kí sinh trong ruột người)."],"bang":[["Môi trường","Ví dụ sinh vật"],["Trên cạn","Hổ, cây lúa, chim sẻ"],["Nước","Cá, tôm, rong"],["Trong đất","Giun đất, chuột chũi"],["Sinh vật","Giun đũa, chấy, rận"]],"bien":null,"vd":null,"nham":null,"lq":["s8-nhan-to-sinh-thai","s8-gioi-han-sinh-thai","s8-he-sinh-thai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-nhan-to-sinh-thai","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":2,"loai":"kn","ten":"Nhân tố sinh thái","ten_khac":["nhan to sinh thai","nhan to moi truong","nhan to vo sinh","nhan to huu sinh","yeu to moi truong"],"noi_dung":"Các yếu tố của môi trường tác động lên sinh vật, chia thành nhân tố vô sinh và nhân tố hữu sinh.","cong_thuc":null,"y":["<b>Nhân tố vô sinh</b>: ánh sáng, nhiệt độ, độ ẩm, nước, đất, không khí…","<b>Nhân tố hữu sinh</b>: các sinh vật khác và con người.","Con người là nhân tố hữu sinh có ảnh hưởng mạnh mẽ nhất tới nhiều sinh vật."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-nhan-to-vo-sinh","s8-nhan-to-huu-sinh","s8-gioi-han-sinh-thai","s8-moi-truong-song"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-nhan-to-vo-sinh","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":3,"loai":"kn","ten":"Nhân tố vô sinh","ten_khac":["nhan to vo sinh","anh sang","nhiet do","do am","khong song","vo sinh"],"noi_dung":"Các nhân tố không sống của môi trường như ánh sáng, nhiệt độ, độ ẩm, nước, đất, không khí.","cong_thuc":null,"y":["<b>Ánh sáng</b> ảnh hưởng quang hợp của cây, hoạt động của động vật (động vật ưa sáng, ưa tối).","<b>Nhiệt độ</b>, <b>độ ẩm</b> ảnh hưởng hình thái, sinh lí, sự phân bố sinh vật.","Ví dụ: cây ưa sáng mọc nơi quang đãng, cây ưa bóng mọc dưới tán rừng."],"bang":null,"bien":null,"vd":{"de":"Ánh sáng, nhiệt độ, độ ẩm, đất trong một khu vườn thuộc nhóm nhân tố sinh thái nào?","buoc":["Ánh sáng, nhiệt độ, độ ẩm, đất đều không phải là sinh vật sống.","Đây là các yếu tố không sống của môi trường."],"kq":"Đây là các nhân tố vô sinh."},"nham":null,"lq":["s8-nhan-to-sinh-thai","s8-nhan-to-huu-sinh","s8-gioi-han-sinh-thai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-nhan-to-huu-sinh","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":4,"loai":"kn","ten":"Nhân tố hữu sinh","ten_khac":["nhan to huu sinh","huu sinh","nhan to con nguoi","quan he giua cac sinh vat","sinh vat khac"],"noi_dung":"Các sinh vật sống xung quanh và con người, tác động lên một sinh vật.","cong_thuc":null,"y":["Gồm quan hệ giữa các sinh vật cùng loài và khác loài (hỗ trợ, cạnh tranh, ăn thịt…).","<b>Con người</b> tác động mạnh: chặt phá rừng, săn bắt, gây ô nhiễm, nhưng cũng trồng rừng, bảo tồn."],"bang":null,"bien":null,"vd":{"de":"Sâu ăn lá, chim ăn sâu, con người chăm sóc cây trong khu vườn — đây thuộc nhóm nhân tố sinh thái nào tác động lên cây?","buoc":["Sâu, chim và con người đều là sinh vật sống tác động đến cây.","Đây là các nhân tố hữu sinh của môi trường."],"kq":"Đây là các nhân tố hữu sinh."},"nham":null,"lq":["s8-nhan-to-sinh-thai","s8-nhan-to-vo-sinh","s8-quan-xa"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-gioi-han-sinh-thai","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":5,"loai":"kn","ten":"Giới hạn sinh thái","ten_khac":["gioi han sinh thai","khoang thuan loi","khoang chong chiu","diem cuc thuan","diem gay chet","gioi han chiu dung"],"noi_dung":"Khoảng giá trị của một nhân tố sinh thái mà trong đó sinh vật có thể tồn tại và phát triển.","cong_thuc":null,"y":["Có <b>giới hạn dưới</b> và <b>giới hạn trên</b> (điểm gây chết); ra ngoài khoảng này sinh vật chết.","<b>Khoảng thuận lợi</b>: sinh vật sống tốt nhất; <b>khoảng chống chịu</b>: sinh vật bị ức chế.","Sinh vật có giới hạn sinh thái rộng thì phân bố rộng."],"bang":[["Cá rô phi (Việt Nam)","Nhiệt độ"],["Giới hạn dưới","5,6 °C"],["Điểm cực thuận","30 °C"],["Giới hạn trên","42 °C"]],"bien":null,"vd":{"de":"Cá rô phi ở Việt Nam sống được trong khoảng nhiệt độ nước từ 5,6 °C đến 42 °C, ngoài khoảng này cá chết. Khoảng nhiệt độ đó gọi là gì?","buoc":["Ngoài khoảng 5,6 °C đến 42 °C, cá rô phi không chịu được và chết.","Đây là khoảng giá trị của nhân tố nhiệt độ mà cá rô phi có thể tồn tại."],"kq":"Đây là giới hạn sinh thái về nhiệt độ của cá rô phi."},"nham":["Nghĩ trong giới hạn sinh thái sinh vật luôn sống tốt; ở khoảng chống chịu sinh vật vẫn sống nhưng yếu."],"lq":["s8-nhan-to-sinh-thai","s8-nhan-to-vo-sinh","s8-moi-truong-song"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-quan-the","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":6,"loai":"kn","ten":"Quần thể sinh vật","ten_khac":["quan the","quan the sinh vat","ti le gioi tinh","nhom tuoi","thap tuoi","dac trung quan the","kich thuoc quan the"],"noi_dung":"Tập hợp các cá thể cùng loài, sống trong một khoảng không gian xác định, ở một thời điểm, có khả năng sinh sản tạo thế hệ mới.","cong_thuc":null,"y":["Đặc trưng: <b>số lượng cá thể</b>, <b>mật độ</b>, <b>tỉ lệ giới tính</b>, <b>thành phần nhóm tuổi</b>, <b>kiểu phân bố</b>.","Nhóm tuổi: trước sinh sản, sinh sản, sau sinh sản; biểu diễn bằng <b>tháp tuổi</b>.","Ví dụ: đàn voi ở một khu rừng, các cây thông trên một đồi thông."],"bang":null,"bien":null,"vd":{"de":"Trong một ao có nhiều cá chép cùng loài sinh sống và sinh sản. Đàn cá chép đó có phải là một quần thể không? Vì sao?","buoc":["Các cá thể cùng loài, sống trong cùng không gian và thời điểm.","Chúng có khả năng giao phối, sinh sản tạo thế hệ mới."],"kq":"Đúng, đàn cá chép trong ao là một quần thể sinh vật."},"nham":["Gọi một ao có nhiều loài cá là một quần thể; đó là tập hợp nhiều quần thể (khác loài)."],"lq":["s8-mat-do-quan-the","s8-quan-xa","s8-can-bang-tu-nhien"],"hinh":"H-s8-quan-the","nguon":["KHTN Pocket"]},{"ma":"s8-mat-do-quan-the","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":7,"loai":"dl","ten":"Mật độ quần thể","ten_khac":["mat do quan the","mat do","so ca the tren dien tich","ca the/ha","ca the/m3"],"noi_dung":"Số lượng cá thể của quần thể trên một đơn vị diện tích hoặc thể tích.","cong_thuc":"mật độ = n/s","y":["Là đặc trưng quan trọng nhất, ảnh hưởng đến nguồn sống, sinh sản, tử vong của quần thể.","Mật độ thay đổi theo mùa, năm và điều kiện sống (thức ăn, thời tiết)."],"bang":null,"bien":[["n","số cá thể của quần thể","cá thể"],["s","diện tích (hoặc thể tích) nơi sống","m², ha (hoặc m³, L)"]],"vd":{"de":"Khảo sát 5 ha rừng thông đếm được 4 000 cây thông. Tính mật độ quần thể thông.","buoc":["Mật độ = 4 000 : 5"],"kq":"800 cây/ha"},"nham":["Quên ghi đơn vị (cá thể/ha, con/m²…) khi nêu mật độ."],"lq":["s8-quan-the","s8-quan-xa"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-quan-xa","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":8,"loai":"kn","ten":"Quần xã sinh vật","ten_khac":["quan xa","quan xa sinh vat","do da dang","thanh phan loai","dac trung quan xa"],"noi_dung":"Tập hợp các quần thể thuộc nhiều loài khác nhau, cùng sống trong một không gian và thời gian, có quan hệ gắn bó.","cong_thuc":null,"y":["Đặc trưng: <b>độ đa dạng</b> (số lượng loài) và <b>thành phần loài</b> (loài ưu thế, loài đặc trưng).","Ví dụ: quần xã rừng mưa nhiệt đới, quần xã ao hồ.","Quần xã có độ đa dạng càng cao thì càng ổn định."],"bang":null,"bien":null,"vd":{"de":"Trong ao còn có cá chép, cá rô, ốc, rong, nhiều loài cùng sống chung và có quan hệ dinh dưỡng với nhau. Tập hợp này gọi là gì?","buoc":["Cá chép, cá rô, ốc, rong là các quần thể của nhiều loài khác nhau.","Chúng cùng sống trong một không gian, thời gian và có quan hệ với nhau."],"kq":"Đây là một quần xã sinh vật."},"nham":["Nhầm quần xã với quần thể: quần thể một loài, quần xã nhiều loài."],"lq":["s8-quan-the","s8-loai-uu-the","s8-loai-dac-trung","s8-he-sinh-thai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-loai-uu-the","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":9,"loai":"kn","ten":"Loài ưu thế","ten_khac":["loai uu the","uu the","loai chiem uu the","thanh phan loai"],"noi_dung":"Loài có số lượng nhiều hoặc hoạt động mạnh, đóng vai trò quan trọng trong quần xã.","cong_thuc":null,"y":["Ví dụ: lúa là loài ưu thế trong quần xã ruộng lúa; cây thông trong rừng thông.","Loài ưu thế quyết định nhiều đến đặc điểm và sự ổn định của quần xã."],"bang":null,"bien":null,"vd":{"de":"Trong một cánh đồng lúa, cây lúa chiếm số lượng áp đảo so với các loài cỏ dại khác. Cây lúa đóng vai trò gì trong quần xã này?","buoc":["Cây lúa có số lượng vượt trội so với các loài khác trong ruộng.","Loài có số lượng nhiều, ảnh hưởng lớn đến quần xã được gọi là loài ưu thế."],"kq":"Cây lúa là loài ưu thế trong quần xã ruộng lúa."},"nham":["Nhầm loài ưu thế với loài đặc trưng: loài đặc trưng chỉ có (hoặc có nhiều) ở một quần xã."],"lq":["s8-loai-dac-trung","s8-quan-xa"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-loai-dac-trung","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":10,"loai":"kn","ten":"Loài đặc trưng","ten_khac":["loai dac trung","dac trung","loai chi co o","thanh phan loai"],"noi_dung":"Loài chỉ có ở một quần xã hoặc có nhiều hơn hẳn so với các quần xã khác.","cong_thuc":null,"y":["Ví dụ: cây cọ đặc trưng cho quần xã vùng đồi Phú Thọ; cá cóc Tam Đảo ở rừng Tam Đảo.","Giúp phân biệt quần xã này với quần xã khác."],"bang":null,"bien":null,"vd":{"de":"Cây cọ chỉ mọc phổ biến ở vùng trung du Phú Thọ mà hiếm gặp ở các quần xã khác. Cây cọ được gọi là loài gì của quần xã đó?","buoc":["Cây cọ gần như chỉ xuất hiện ở vùng trung du này.","Loài chỉ có hoặc có nhiều hơn hẳn ở một quần xã nhất định được gọi là loài đặc trưng."],"kq":"Cây cọ là loài đặc trưng của quần xã vùng trung du đó."},"nham":null,"lq":["s8-loai-uu-the","s8-quan-xa"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-he-sinh-thai","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":11,"loai":"kn","ten":"Hệ sinh thái","ten_khac":["he sinh thai","hst","thanh phan he sinh thai","he sinh thai tu nhien","he sinh thai nhan tao","ecosystem"],"noi_dung":"Hệ thống gồm quần xã sinh vật và môi trường sống của nó (sinh cảnh), tác động qua lại tạo thành một thể thống nhất.","cong_thuc":null,"y":["Thành phần: <b>vô sinh</b> (đất, nước, ánh sáng…) và <b>hữu sinh</b> (sinh vật sản xuất, sinh vật tiêu thụ, sinh vật phân giải).","Hệ sinh thái <b>tự nhiên</b>: trên cạn (rừng, sa mạc…), dưới nước (nước ngọt, nước mặn).","Hệ sinh thái <b>nhân tạo</b>: đồng ruộng, ao nuôi, thành phố…"],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-chuoi-thuc-an","s8-luoi-thuc-an","s8-quan-xa","s8-sinh-vat-san-xuat"],"hinh":"H-s8-he-sinh-thai","nguon":["KHTN Pocket"]},{"ma":"s8-chuoi-thuc-an","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":12,"loai":"kn","ten":"Chuỗi thức ăn","ten_khac":["chuoi thuc an","mat xich","moi an","sinh vat an sinh vat","food chain"],"noi_dung":"Dãy nhiều loài sinh vật có quan hệ dinh dưỡng với nhau, mỗi loài là một mắt xích của chuỗi.","cong_thuc":null,"y":["Thường bắt đầu từ <b>sinh vật sản xuất</b>, qua các <b>sinh vật tiêu thụ</b>, và sinh vật phân giải.","Ví dụ: Cỏ → Châu chấu → Ếch → Rắn → Vi khuẩn.","Mũi tên chỉ chiều: \"bị ăn → ăn\" (chiều dòng năng lượng)."],"bang":null,"bien":null,"vd":{"de":"Cỏ bị châu chấu ăn, châu chấu bị ếch ăn, ếch bị rắn ăn. Hãy viết chuỗi thức ăn này.","buoc":["Xác định loài nào ăn loài nào trong dãy sinh vật này.","Sắp xếp theo chiều bị ăn, mỗi loài là một mắt xích."],"kq":"Cỏ → châu chấu → ếch → rắn."},"nham":["Vẽ mũi tên ngược (từ con ăn sang con bị ăn); mũi tên phải chỉ từ sinh vật bị ăn tới sinh vật ăn nó."],"lq":["s8-luoi-thuc-an","s8-sinh-vat-san-xuat","s8-sinh-vat-tieu-thu","s8-he-sinh-thai"],"hinh":"H-s8-chuoi-thuc-an","nguon":["KHTN Pocket"]},{"ma":"s8-luoi-thuc-an","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":13,"loai":"kn","ten":"Lưới thức ăn","ten_khac":["luoi thuc an","mat xich chung","food web","nhieu chuoi thuc an"],"noi_dung":"Tập hợp các chuỗi thức ăn trong hệ sinh thái có nhiều mắt xích chung.","cong_thuc":null,"y":["Một loài có thể là mắt xích của nhiều chuỗi (<b>mắt xích chung</b>).","Lưới thức ăn càng phức tạp (nhiều loài) thì hệ sinh thái càng ổn định."],"bang":null,"bien":null,"vd":{"de":"Nếu châu chấu vừa bị ếch ăn vừa bị chim sẻ ăn, các chuỗi thức ăn có chung mắt xích châu chấu này hợp lại gọi là gì?","buoc":["Châu chấu là mắt xích chung của cả chuỗi có ếch và chuỗi có chim sẻ.","Nhiều chuỗi thức ăn có mắt xích chung, đan xen tạo thành mạng lưới."],"kq":"Đây là một lưới thức ăn."},"nham":null,"lq":["s8-chuoi-thuc-an","s8-he-sinh-thai","s8-can-bang-tu-nhien"],"hinh":"H-s8-luoi-thuc-an","nguon":["KHTN Pocket"]},{"ma":"s8-sinh-vat-san-xuat","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":14,"loai":"kn","ten":"Sinh vật sản xuất","ten_khac":["sinh vat san xuat","san xuat","thuc vat","sinh vat tu duong","mat xich dau tien"],"noi_dung":"Sinh vật tự tổng hợp chất hữu cơ từ chất vô cơ, chủ yếu là thực vật (và tảo) nhờ quang hợp.","cong_thuc":null,"y":["Thường là <b>mắt xích đầu tiên</b> của chuỗi thức ăn.","Cung cấp chất hữu cơ và năng lượng cho các sinh vật khác trong hệ sinh thái."],"bang":null,"bien":null,"vd":{"de":"Trong chuỗi thức ăn cỏ → châu chấu → ếch → rắn, cỏ đóng vai trò gì?","buoc":["Cỏ tự tổng hợp chất hữu cơ từ chất vô cơ nhờ quang hợp.","Đây là mắt xích đầu tiên, cung cấp chất hữu cơ cho cả chuỗi."],"kq":"Cỏ là sinh vật sản xuất, mắt xích đầu tiên của chuỗi."},"nham":null,"lq":["s8-sinh-vat-tieu-thu","s8-sinh-vat-phan-giai","s8-chuoi-thuc-an"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-sinh-vat-tieu-thu","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":15,"loai":"kn","ten":"Sinh vật tiêu thụ","ten_khac":["sinh vat tieu thu","tieu thu","tieu thu bac 1","tieu thu bac 2","dong vat an co","dong vat an thit"],"noi_dung":"Sinh vật không tự tổng hợp được chất hữu cơ, sử dụng chất hữu cơ của sinh vật khác, chủ yếu là động vật.","cong_thuc":null,"y":["<b>Tiêu thụ bậc 1</b>: ăn sinh vật sản xuất (động vật ăn thực vật).","<b>Tiêu thụ bậc 2, 3…</b>: ăn sinh vật tiêu thụ bậc trước (động vật ăn thịt)."],"bang":null,"bien":null,"vd":{"de":"Trong chuỗi thức ăn cỏ → châu chấu → ếch → rắn, châu chấu, ếch và rắn đóng vai trò gì?","buoc":["Châu chấu ăn cỏ, ếch ăn châu chấu, rắn ăn ếch.","Chúng không tự tổng hợp chất hữu cơ mà ăn sinh vật khác để lấy chất hữu cơ."],"kq":"Châu chấu, ếch, rắn đều là sinh vật tiêu thụ."},"nham":null,"lq":["s8-sinh-vat-san-xuat","s8-sinh-vat-phan-giai","s8-chuoi-thuc-an"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-sinh-vat-phan-giai","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":16,"loai":"kn","ten":"Sinh vật phân giải","ten_khac":["sinh vat phan giai","phan giai","vi khuan","nam","xac sinh vat","phan huy"],"noi_dung":"Sinh vật phân giải xác và chất thải của sinh vật thành chất vô cơ trả lại môi trường, chủ yếu là vi khuẩn, nấm.","cong_thuc":null,"y":["Khép kín vòng tuần hoàn vật chất trong hệ sinh thái.","Tạo chất khoáng cho sinh vật sản xuất sử dụng lại."],"bang":null,"bien":null,"vd":{"de":"Xác châu chấu, ếch, rắn chết đi dần biến mất, trả lại chất vô cơ cho đất. Nhóm sinh vật nào thực hiện quá trình này?","buoc":["Vi khuẩn và nấm phân giải xác chết, chất thải thành chất vô cơ.","Chất vô cơ được trả lại cho đất, nước, không khí."],"kq":"Đây là hoạt động của sinh vật phân giải."},"nham":null,"lq":["s8-sinh-vat-san-xuat","s8-sinh-vat-tieu-thu","s8-he-sinh-thai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-can-bang-tu-nhien","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":17,"loai":"kn","ten":"Cân bằng tự nhiên","ten_khac":["can bang tu nhien","can bang sinh hoc","khong che sinh hoc","mat can bang","on dinh he sinh thai"],"noi_dung":"Trạng thái ổn định tự nhiên của quần thể, quần xã, hệ sinh thái, số lượng cá thể dao động quanh mức cân bằng.","cong_thuc":null,"y":["Nhờ <b>khống chế sinh học</b>: số lượng loài này bị số lượng loài khác kìm hãm (ví dụ mèo và chuột).","Con người phá rừng, săn bắt, gây ô nhiễm làm <b>mất cân bằng tự nhiên</b>.","Bảo vệ: bảo vệ rừng, bảo tồn loài, hạn chế ô nhiễm, không du nhập loài lạ tùy tiện."],"bang":null,"bien":null,"vd":{"de":"Trong một khu rừng, số lượng thỏ và số lượng cáo (kẻ săn thỏ) qua nhiều năm luôn dao động quanh một mức ổn định, không loài nào tăng hay giảm mãi. Hiện tượng này gọi là gì?","buoc":["Thỏ nhiều giúp cáo có nhiều thức ăn, số lượng cáo tăng theo.","Cáo tăng ăn nhiều thỏ hơn khiến thỏ giảm, rồi cáo lại giảm theo."],"kq":"Đây là hiện tượng cân bằng tự nhiên."},"nham":null,"lq":["s8-quan-the","s8-luoi-thuc-an","s8-bao-ve-moi-truong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-sinh-quyen","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":18,"loai":"kn","ten":"Sinh quyển","ten_khac":["sinh quyen","bieu sinh quyen","lop song cua trai dat","biosphere"],"noi_dung":"Toàn bộ sinh vật trên Trái Đất cùng các nhân tố vô sinh của môi trường sống của chúng.","cong_thuc":null,"y":["Gồm phần của thạch quyển (đất), thủy quyển (nước), khí quyển (không khí) có sinh vật sống.","Được chia thành các <b>khu sinh học</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-khu-sinh-hoc","s8-he-sinh-thai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-khu-sinh-hoc","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":19,"loai":"kn","ten":"Khu sinh học","ten_khac":["khu sinh hoc","rung mua nhiet doi","sa mac","hoang mac","thao nguyen","dong reu","rung la kim","bien"],"noi_dung":"Vùng lớn của sinh quyển có khí hậu, thực vật và động vật đặc trưng.","cong_thuc":null,"y":["<b>Trên cạn</b>: rừng mưa nhiệt đới, rừng lá kim, thảo nguyên, sa mạc (hoang mạc), đồng rêu…","<b>Dưới nước</b>: khu nước ngọt (sông, hồ) và khu nước mặn (biển, đại dương)."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s8-sinh-quyen","s8-he-sinh-thai"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-o-nhiem-moi-truong","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":20,"loai":"ht","ten":"Ô nhiễm môi trường","ten_khac":["o nhiem moi truong","o nhiem","o nhiem khong khi","o nhiem nuoc","o nhiem dat","rac thai","chat thai"],"noi_dung":"Sự thay đổi tính chất của môi trường (đất, nước, không khí) do chất gây ô nhiễm, gây hại cho sinh vật và con người.","cong_thuc":null,"y":["Nguyên nhân: khí thải, nước thải công nghiệp và sinh hoạt, thuốc bảo vệ thực vật, rác thải nhựa…","Hậu quả: gây bệnh cho người, suy giảm đa dạng sinh học.","Biện pháp: xử lí chất thải, phân loại rác, dùng năng lượng sạch, trồng cây xanh."],"bang":null,"bien":null,"vd":{"de":"Nước thải nhà máy chưa xử lí xả thẳng ra sông làm cá chết hàng loạt. Đây là hiện tượng gì?","buoc":["Chất thải làm thay đổi tính chất của nước, thiếu oxygen và có chất độc.","Sinh vật sống trong nước bị hại, thậm chí chết."],"kq":"Đây là hiện tượng ô nhiễm môi trường nước."},"nham":null,"lq":["s8-bien-doi-khi-hau","s8-bao-ve-moi-truong","s8-can-bang-tu-nhien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-bien-doi-khi-hau","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":21,"loai":"ht","ten":"Biến đổi khí hậu","ten_khac":["bien doi khi hau","nong len toan cau","hieu ung nha kinh","khi nha kinh","nuoc bien dang"],"noi_dung":"Sự thay đổi của khí hậu trong thời gian dài, chủ yếu do con người thải nhiều khí nhà kính.","cong_thuc":null,"y":["Biểu hiện: nhiệt độ Trái Đất tăng, nước biển dâng, thời tiết cực đoan (bão lũ, hạn hán) nhiều hơn.","Ảnh hưởng: thay đổi nơi sống, đe dọa nhiều loài sinh vật.","Ứng phó: tiết kiệm năng lượng, trồng rừng, giảm khí thải."],"bang":null,"bien":null,"vd":{"de":"Nhiều năm gần đây, nhiệt độ trung bình Trái Đất tăng dần, băng ở hai cực tan nhiều hơn trước. Nguyên nhân chính là gì?","buoc":["Con người thải nhiều khí nhà kính từ đốt nhiên liệu hóa thạch, phá rừng.","Khí nhà kính giữ nhiệt, làm Trái Đất nóng lên trong thời gian dài."],"kq":"Đây là biểu hiện của biến đổi khí hậu do con người gây ra."},"nham":null,"lq":["s8-o-nhiem-moi-truong","s8-bao-ve-moi-truong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-bao-ve-dong-vat-hoang-da","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":22,"loai":"ud","ten":"Bảo vệ động vật hoang dã","ten_khac":["bao ve dong vat hoang da","dong vat hoang da","khu bao ton","vuon quoc gia","san bat trai phep","sach do"],"noi_dung":"Các hoạt động bảo vệ loài động vật sống tự nhiên khỏi săn bắt, buôn bán trái phép và mất môi trường sống.","cong_thuc":null,"y":["Nguyên nhân suy giảm: săn bắt, buôn bán trái phép, phá rừng, ô nhiễm.","Biện pháp: xây dựng <b>vườn quốc gia</b>, <b>khu bảo tồn</b>; không mua bán, sử dụng sản phẩm từ động vật hoang dã."],"bang":null,"bien":null,"vd":{"de":"Nạn săn bắt, buôn bán tê giác, hổ trái phép khiến số lượng các loài này giảm mạnh, có nguy cơ tuyệt chủng. Cần làm gì để bảo vệ chúng?","buoc":["Cấm săn bắt, buôn bán trái phép động vật hoang dã.","Bảo vệ môi trường sống tự nhiên, lập khu bảo tồn."],"kq":"Các biện pháp này giúp bảo vệ động vật hoang dã khỏi tuyệt chủng."},"nham":null,"lq":["s8-bao-ve-moi-truong","s8-can-bang-tu-nhien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s8-bao-ve-moi-truong","mon":"KHTN","khoi":"8","chu_de":"s8-moi-truong","thu_tu":23,"loai":"ud","ten":"Bảo vệ môi trường","ten_khac":["bao ve moi truong","bvmt","phan loai rac","tai che","trong cay","tiet kiem nang luong","phat trien ben vung"],"noi_dung":"Các hoạt động giữ môi trường trong lành, sạch đẹp, hạn chế ô nhiễm và sử dụng hợp lí tài nguyên.","cong_thuc":null,"y":["Hạn chế ô nhiễm, ứng phó với biến đổi khí hậu, bảo vệ đa dạng sinh học.","Học sinh có thể: phân loại rác, tiết kiệm điện nước, hạn chế đồ nhựa dùng một lần, trồng và chăm sóc cây xanh."],"bang":null,"bien":null,"vd":{"de":"Một khu dân cư thường xuyên xả rác bừa bãi ra kênh, làm kênh ô nhiễm, bốc mùi. Cần có biện pháp gì?","buoc":["Thu gom, xử lí rác đúng nơi quy định thay vì xả bừa bãi.","Tuyên truyền nâng cao ý thức người dân về bảo vệ môi trường."],"kq":"Các biện pháp này giúp cải thiện môi trường sống của khu dân cư."},"nham":null,"lq":["s8-o-nhiem-moi-truong","s8-bien-doi-khi-hau","s8-bao-ve-dong-vat-hoang-da","s8-can-bang-tu-nhien"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-di-truyen","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":1,"loai":"kn","ten":"Di truyền","ten_khac":["di truyen","di truyen hoc","heredity","genetics","truyen dac diem","con giong bo me"],"noi_dung":"Hiện tượng truyền đạt các đặc điểm (tính trạng) của bố mẹ, tổ tiên cho các thế hệ con cháu.","cong_thuc":null,"y":["Nhờ di truyền, con cái <b>giống bố mẹ</b> và giống nhau ở nhiều đặc điểm.","<b>Di truyền học</b> nghiên cứu cơ sở vật chất, cơ chế và quy luật của di truyền và biến dị.","Di truyền và biến dị là hai hiện tượng song song, gắn liền với quá trình sinh sản.","Mendel được coi là người đặt nền móng cho di truyền học."],"bang":null,"bien":null,"vd":null,"nham":["Nhầm di truyền với \"bẩm sinh\": không phải mọi đặc điểm có từ lúc sinh ra đều do di truyền."],"lq":["s9-bien-di","s9-mendel","s9-tinh-trang","s9-gene"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-bien-di","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":2,"loai":"kn","ten":"Biến dị","ten_khac":["bien di","variation","khac bo me","sai khac","bien di di truyen"],"noi_dung":"Hiện tượng con sinh ra khác với bố mẹ và khác nhau ở nhiều chi tiết.","cong_thuc":null,"y":["Anh chị em ruột cùng bố mẹ vẫn có những điểm khác nhau là do biến dị.","Biến dị gồm <b>biến dị tổ hợp</b> (sắp xếp lại gene) và <b>đột biến</b> (thay đổi vật chất di truyền).","Biến dị là nguồn nguyên liệu cho <b>chọn giống</b> và <b>tiến hóa</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-di-truyen","s9-bien-di-to-hop","s9-dot-bien-gene","s9-tien-hoa"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-mendel","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":3,"loai":"kn","ten":"Mendel","ten_khac":["mendel","men den","gregor mendel","phuong phap phan tich con lai","dau ha lan","cha de di truyen hoc"],"noi_dung":"Gregor Mendel (1822–1884), người phát hiện các quy luật di truyền đầu tiên nhờ thí nghiệm lai trên đậu Hà Lan.","cong_thuc":null,"y":["Chọn <b>đậu Hà Lan</b>: tự thụ phấn nghiêm ngặt, vòng đời ngắn, có nhiều cặp tính trạng tương phản dễ quan sát.","<b>Phương pháp phân tích con lai:</b> tạo dòng thuần chủng, lai các cặp bố mẹ khác nhau về một hoặc vài cặp tính trạng tương phản.","Theo dõi sự di truyền từng cặp tính trạng qua nhiều thế hệ, dùng <b>thống kê</b> để phân tích số liệu.","Phát hiện: quy luật phân li và quy luật phân li độc lập."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-lai-mot-cap","s9-quy-luat-phan-li","s9-quy-luat-phan-li-doc-lap","s9-giong-thuan-chung"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-tinh-trang","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":4,"loai":"kn","ten":"Tính trạng","ten_khac":["tinh trang","tinh trang tuong phan","dac diem","trait","mau hat","hinh dang hat"],"noi_dung":"Những đặc điểm về hình thái, cấu tạo, sinh lí của cơ thể, ví dụ màu hạt, chiều cao thân.","cong_thuc":null,"y":["<b>Cặp tính trạng tương phản:</b> hai trạng thái biểu hiện trái ngược nhau của cùng một tính trạng.","Ví dụ ở đậu Hà Lan: hạt vàng – hạt xanh; hạt trơn – hạt nhăn; thân cao – thân thấp.","Tính trạng do gene quy định và chịu ảnh hưởng của môi trường."],"bang":null,"bien":null,"vd":null,"nham":["Hạt vàng và hạt trơn không phải cặp tương phản vì thuộc hai tính trạng khác nhau (màu, hình dạng)."],"lq":["s9-tinh-trang-troi-lan","s9-kieu-hinh","s9-gene-den-tinh-trang","s9-mendel"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-tinh-trang-troi-lan","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":5,"loai":"kn","ten":"Tính trạng trội, lặn","ten_khac":["tinh trang troi","tinh trang lan","troi","lan","troi hoan toan","dominant","recessive"],"noi_dung":"Tính trạng trội biểu hiện ngay ở F1 khi lai hai giống thuần chủng tương phản; tính trạng lặn đến F2 mới biểu hiện.","cong_thuc":null,"y":["Kí hiệu: <b>chữ in hoa</b> (A) cho allele trội, <b>chữ thường</b> (a) cho allele lặn.","Tính trạng lặn chỉ biểu hiện khi kiểu gene đồng hợp lặn (aa).","Trội hoàn toàn: kiểu gene Aa có kiểu hình giống AA."],"bang":[["Tính trạng (đậu Hà Lan)","Trội","Lặn"],["Màu hạt","Vàng","Xanh"],["Hình dạng hạt","Trơn","Nhăn"],["Chiều cao thân","Cao","Thấp"]],"bien":null,"vd":{"de":"Lai hai giống đậu Hà Lan thuần chủng hạt vàng và hạt xanh, F1 thu được 100% hạt vàng. Xác định tính trạng trội, tính trạng lặn.","buoc":["Tính trạng biểu hiện ở F1 (hạt vàng) là tính trạng trội.","Tính trạng không biểu hiện ở F1 (hạt xanh) là tính trạng lặn."],"kq":"Hạt vàng là trội, hạt xanh là lặn."},"nham":["Tính trạng trội không phải lúc nào cũng \"tốt hơn\" hay \"phổ biến hơn\" tính trạng lặn."],"lq":["s9-tinh-trang","s9-allele","s9-dong-hop","s9-di-hop"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-nhan-to-di-truyen","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":6,"loai":"kn","ten":"Nhân tố di truyền","ten_khac":["nhan to di truyen","nhan to","hereditary factor","mendel goi gene","ntdt"],"noi_dung":"Tên Mendel gọi yếu tố quy định tính trạng của cơ thể; ngày nay gọi là gene.","cong_thuc":null,"y":["Mendel cho rằng mỗi tính trạng do <b>một cặp nhân tố di truyền</b> quy định.","Trong tế bào, nhân tố di truyền tồn tại thành cặp; trong giao tử chỉ còn một.","Các nhân tố di truyền không hòa trộn vào nhau."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-gene","s9-allele","s9-quy-luat-phan-li","s9-mendel"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-giong-thuan-chung","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":7,"loai":"kn","ten":"Giống thuần chủng","ten_khac":["giong thuan chung","dong thuan","thuan chung","pure line","dong hop","giong thuan"],"noi_dung":"Giống có đặc tính di truyền đồng nhất, các thế hệ sau giống hoàn toàn thế hệ trước về tính trạng đang xét.","cong_thuc":null,"y":["Kiểu gene của giống thuần chủng là <b>đồng hợp</b> (AA hoặc aa).","Mendel tạo dòng thuần bằng cách cho cây <b>tự thụ phấn</b> qua nhiều thế hệ.","Lai hai giống thuần chủng khác nhau thì F1 đồng tính."],"bang":null,"bien":null,"vd":{"de":"Một giống lúa khi tự thụ phấn qua nhiều thế hệ, đời con luôn có 100% hạt gạo trắng giống bố mẹ. Giống lúa này có phải giống thuần chủng về tính trạng màu hạt không?","buoc":["Cây tự thụ phấn nhiều đời mà tính trạng màu hạt không hề đổi.","Thế hệ sau luôn giống hoàn toàn thế hệ trước về tính trạng đang xét."],"kq":"Đúng, đây là giống thuần chủng về tính trạng màu hạt."},"nham":null,"lq":["s9-dong-hop","s9-lai-mot-cap","s9-mendel","s9-kieu-gene"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-allele","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":8,"loai":"kn","ten":"Allele","ten_khac":["allele","alen","alleles","a va a","cap allele","trang thai cua gene"],"noi_dung":"Các trạng thái khác nhau của cùng một gene, ví dụ allele A (hạt vàng) và allele a (hạt xanh).","cong_thuc":null,"y":["Mỗi gene có thể có hai hay nhiều allele.","Trong tế bào lưỡng bội, allele tồn tại thành <b>cặp</b>, mỗi allele nằm trên một NST của cặp tương đồng.","Kí hiệu cùng một chữ cái: in hoa là trội, thường là lặn."],"bang":null,"bien":null,"vd":null,"nham":["A và B là hai gene khác nhau, không phải hai allele của một gene."],"lq":["s9-gene","s9-kieu-gene","s9-dong-hop","s9-di-hop"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-kieu-gene","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":9,"loai":"kn","ten":"Kiểu gene","ten_khac":["kieu gene","kieu gen","genotype","aa","aabb","to hop gene"],"noi_dung":"Tổ hợp toàn bộ các gene trong tế bào của cơ thể; khi xét vài tính trạng chỉ ghi các cặp gene liên quan.","cong_thuc":null,"y":["Ví dụ về màu hạt đậu Hà Lan: AA, Aa, aa.","Kiểu gene quy định <b>kiểu hình</b> trong điều kiện môi trường cụ thể.","Kiểu gene gồm các cặp allele <b>đồng hợp</b> hoặc <b>dị hợp</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-kieu-hinh","s9-allele","s9-dong-hop","s9-di-hop"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-kieu-hinh","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":10,"loai":"kn","ten":"Kiểu hình","ten_khac":["kieu hinh","phenotype","bieu hien","hat vang","to hop tinh trang"],"noi_dung":"Tổ hợp toàn bộ các tính trạng của cơ thể; thường chỉ xét một vài tính trạng đang nghiên cứu.","cong_thuc":null,"y":["Ví dụ: hạt vàng, hạt xanh; thân cao, thân thấp.","Kiểu hình là kết quả tương tác giữa <b>kiểu gene</b> và <b>môi trường</b>.","Cùng kiểu hình có thể khác kiểu gene: AA và Aa đều cho hạt vàng."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-kieu-gene","s9-tinh-trang","s9-lai-phan-tich"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-dong-hop","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":11,"loai":"kn","ten":"Thể đồng hợp","ten_khac":["dong hop","the dong hop","dong hop troi","dong hop lan","homozygous","aa"],"noi_dung":"Cơ thể mang cặp gene gồm hai allele giống nhau, ví dụ AA (đồng hợp trội) hoặc aa (đồng hợp lặn).","cong_thuc":null,"y":["Chỉ tạo <b>một loại giao tử</b> (AA cho A, aa cho a).","Tự thụ phấn cho đời con đồng tính, giống bố mẹ.","Giống thuần chủng có kiểu gene đồng hợp."],"bang":null,"bien":null,"vd":{"de":"Cây đậu có kiểu gene AA. Cây này có kiểu gene đồng hợp hay dị hợp? Nó tạo ra loại giao tử nào?","buoc":["Cặp gene AA gồm hai allele giống nhau nên là thể đồng hợp.","Giảm phân chỉ tạo một loại giao tử mang allele A."],"kq":"Thể đồng hợp AA, chỉ tạo giao tử A."},"nham":null,"lq":["s9-di-hop","s9-giong-thuan-chung","s9-kieu-gene","s9-allele"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-di-hop","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":12,"loai":"kn","ten":"Thể dị hợp","ten_khac":["di hop","the di hop","heterozygous","aa","aabb","khong thuan chung"],"noi_dung":"Cơ thể mang cặp gene gồm hai allele khác nhau, ví dụ Aa.","cong_thuc":null,"y":["Aa tạo <b>hai loại giao tử</b> với tỉ lệ ngang nhau: 1A : 1a.","Khi trội hoàn toàn, Aa có kiểu hình trội giống AA.","Tự thụ phấn (Aa × Aa) cho đời con phân li 3 trội : 1 lặn."],"bang":null,"bien":null,"vd":{"de":"Cây đậu có kiểu gene Aa. Cây này có kiểu gene đồng hợp hay dị hợp? Nó tạo ra loại giao tử nào?","buoc":["Cặp gene Aa gồm hai allele khác nhau nên là thể dị hợp.","Giảm phân tạo hai loại giao tử với tỉ lệ bằng nhau, A và a."],"kq":"Thể dị hợp Aa, tạo hai loại giao tử A và a tỉ lệ 1:1."},"nham":null,"lq":["s9-dong-hop","s9-quy-luat-phan-li","s9-lai-phan-tich","s9-allele"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-ki-hieu-lai","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":13,"loai":"kn","ten":"Kí hiệu trong phép lai","ten_khac":["ki hieu","p","f1","f2","g","giao tu","phep lai","so do lai"],"noi_dung":"Các kí hiệu dùng khi viết sơ đồ lai: P, G, F1, F2, ×, ♀, ♂.","cong_thuc":null,"y":["Viết sơ đồ lai theo thứ tự: P → G(P) → F1 → G(F1) → F2.","Viết kiểu gene của bố mẹ trước, rồi giao tử, rồi tổ hợp ở đời con."],"bang":[["Kí hiệu","Ý nghĩa"],["P","cặp bố mẹ xuất phát"],["×","phép lai"],["G","giao tử"],["F1","thế hệ con thứ nhất"],["F2","thế hệ con thứ hai (F1 × F1)"],["♀ / ♂","giới cái (mẹ) / giới đực (bố)"]],"bien":null,"vd":null,"nham":null,"lq":["s9-lai-mot-cap","s9-lai-hai-cap","s9-kieu-gene"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-lai-mot-cap","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":14,"loai":"tn","ten":"Lai một cặp tính trạng","ten_khac":["lai mot cap tinh trang","lai mot cap","thi nghiem mendel","3:1","aa x aa","hat vang hat xanh"],"noi_dung":"Phép lai giữa hai bố mẹ thuần chủng khác nhau về một cặp tính trạng tương phản.","cong_thuc":null,"y":["Mendel lai đậu hạt vàng thuần chủng × hạt xanh thuần chủng: F1 <b>100% hạt vàng</b>.","Cho F1 tự thụ phấn: F2 phân li xấp xỉ <b>3 hạt vàng : 1 hạt xanh</b>.","Tỉ lệ kiểu gene F2: <b>1 AA : 2 Aa : 1 aa</b>."],"bang":null,"bien":null,"vd":{"de":"Ở đậu Hà Lan, A: hạt vàng trội hoàn toàn so với a: hạt xanh. Viết sơ đồ lai P thuần chủng hạt vàng × hạt xanh đến F2.","buoc":["P: AA (vàng) × aa (xanh); G: A, a","F1: Aa (100% vàng)","F1 × F1: Aa × Aa; G: (A, a) × (A, a)","F2: 1 AA : 2 Aa : 1 aa"],"kq":"F2: 3 hạt vàng : 1 hạt xanh"},"nham":["Tỉ lệ 3 : 1 là tỉ lệ kiểu hình, còn tỉ lệ kiểu gene là 1 : 2 : 1."],"lq":["s9-quy-luat-phan-li","s9-ki-hieu-lai","s9-lai-phan-tich","s9-mendel"],"hinh":"H-s9-lai-mot-cap","nguon":["KHTN Pocket"]},{"ma":"s9-quy-luat-phan-li","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":15,"loai":"ct","ten":"Quy luật phân li","ten_khac":["quy luat phan li","phan li","dinh luat mendel 1","giao tu thuan khiet","law of segregation"],"noi_dung":"Khi hình thành giao tử, mỗi nhân tố di truyền trong cặp phân li về một giao tử và giữ nguyên bản chất.","cong_thuc":"Aa × Aa → 1 AA : 2 Aa : 1 aa (3 trội : 1 lặn)","y":["Mỗi tính trạng do <b>một cặp nhân tố di truyền</b> (cặp allele) quy định.","Giao tử chỉ chứa <b>một</b> nhân tố của cặp (giao tử thuần khiết).","Thụ tinh tổ hợp lại các nhân tố thành cặp → F2 có tỉ lệ 3 trội : 1 lặn.","Cơ sở tế bào học: sự phân li của cặp NST tương đồng trong giảm phân."],"bang":null,"bien":[["A","allele trội","–"],["a","allele lặn","–"]],"vd":{"de":"Cơ thể có kiểu gene Aa giảm phân tạo giao tử. Theo quy luật phân li, mỗi giao tử chứa allele nào?","buoc":["Khi giảm phân, cặp allele Aa phân li về hai loại giao tử khác nhau.","Mỗi giao tử chỉ nhận một allele, giữ nguyên bản chất của allele đó."],"kq":"Một nửa giao tử mang allele A, một nửa mang allele a."},"nham":null,"lq":["s9-lai-mot-cap","s9-nhan-to-di-truyen","s9-giam-phan","s9-quy-luat-phan-li-doc-lap"],"hinh":"H-s9-quy-luat-phan-li","nguon":["KHTN Pocket"]},{"ma":"s9-lai-phan-tich","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":16,"loai":"tn","ten":"Lai phân tích","ten_khac":["lai phan tich","phep lai phan tich","test cross","kiem tra kieu gene","lai voi lan"],"noi_dung":"Phép lai cá thể mang tính trạng trội cần xác định kiểu gene với cá thể mang tính trạng lặn.","cong_thuc":null,"y":["Con lai <b>đồng tính trội</b> → cá thể đem lai đồng hợp trội (AA).","Con lai phân li <b>1 trội : 1 lặn</b> → cá thể đem lai dị hợp (Aa).","Dùng để kiểm tra độ thuần chủng của giống."],"bang":null,"bien":null,"vd":{"de":"Cây đậu hạt vàng (A_) lai với cây hạt xanh (aa), đời con có 50% vàng, 50% xanh. Xác định kiểu gene cây hạt vàng.","buoc":["Cây aa chỉ cho giao tử a.","Đời con có hạt xanh (aa) → cây hạt vàng phải cho giao tử a.","Vậy cây hạt vàng là Aa: Aa × aa → 1 Aa : 1 aa."],"kq":"Cây hạt vàng có kiểu gene Aa"},"nham":["Lai phân tích phải lai với cá thể đồng hợp lặn, không lai với cá thể trội."],"lq":["s9-dong-hop","s9-di-hop","s9-lai-mot-cap","s9-kieu-hinh"],"hinh":"H-s9-lai-phan-tich","nguon":["KHTN Pocket"]},{"ma":"s9-lai-hai-cap","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":17,"loai":"tn","ten":"Lai hai cặp tính trạng","ten_khac":["lai hai cap tinh trang","lai hai cap","9:3:3:1","vang tron xanh nhan","aabb x aabb"],"noi_dung":"Phép lai giữa hai bố mẹ thuần chủng khác nhau về hai cặp tính trạng tương phản.","cong_thuc":null,"y":["Mendel lai đậu hạt vàng, trơn × hạt xanh, nhăn (thuần chủng): F1 100% vàng, trơn.","F1 tự thụ phấn: F2 có 4 kiểu hình xấp xỉ <b>9 vàng, trơn : 3 vàng, nhăn : 3 xanh, trơn : 1 xanh, nhăn</b>.","Tỉ lệ từng cặp tính trạng ở F2 đều là 3 : 1."],"bang":null,"bien":null,"vd":{"de":"A: vàng, a: xanh; B: trơn, b: nhăn. P thuần chủng vàng, trơn × xanh, nhăn. Tìm kiểu gene P, F1 và giao tử F1.","buoc":["P: AABB × aabb; G: AB, ab","F1: AaBb (100% vàng, trơn)","F1 cho 4 loại giao tử bằng nhau: AB, Ab, aB, ab"],"kq":"F2: 16 tổ hợp, 9 : 3 : 3 : 1"},"nham":null,"lq":["s9-quy-luat-phan-li-doc-lap","s9-bien-di-to-hop","s9-lai-mot-cap","s9-ki-hieu-lai"],"hinh":"H-s9-lai-hai-cap","nguon":["KHTN Pocket"]},{"ma":"s9-quy-luat-phan-li-doc-lap","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":18,"loai":"ct","ten":"Quy luật phân li độc lập","ten_khac":["quy luat phan li doc lap","phan li doc lap","dinh luat mendel 2","pldl","independent assortment"],"noi_dung":"Các cặp nhân tố di truyền quy định các cặp tính trạng khác nhau phân li độc lập trong quá trình hình thành giao tử.","cong_thuc":"AaBb × AaBb → 9 A-B- : 3 A-bb : 3 aaB- : 1 aabb","y":["Tỉ lệ kiểu hình F2 bằng <b>tích</b> tỉ lệ các cặp tính trạng: (3 : 1)(3 : 1) = 9 : 3 : 3 : 1.","Điều kiện: các cặp gene nằm trên <b>các cặp NST khác nhau</b>.","Ý nghĩa: tạo ra nhiều <b>biến dị tổ hợp</b>, giải thích sự đa dạng của sinh vật."],"bang":null,"bien":[["A, a","cặp allele thứ nhất","–"],["B, b","cặp allele thứ hai (trên cặp NST khác)","–"]],"vd":{"de":"Cơ thể có kiểu gene AaBb giảm phân bình thường, hai cặp gene nằm trên hai cặp NST khác nhau. Cơ thể này tạo ra những loại giao tử nào?","buoc":["Cặp Aa phân li độc lập với cặp Bb khi hình thành giao tử.","Tổ hợp tự do giữa A, a với B, b tạo 4 loại giao tử với tỉ lệ bằng nhau."],"kq":"4 loại giao tử: AB, Ab, aB, ab, tỉ lệ 1:1:1:1."},"nham":null,"lq":["s9-lai-hai-cap","s9-bien-di-to-hop","s9-quy-luat-phan-li","s9-di-truyen-lien-ket"],"hinh":"H-s9-quy-luat-phan-li-doc-lap","nguon":["KHTN Pocket"]},{"ma":"s9-bien-di-to-hop","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":19,"loai":"kn","ten":"Biến dị tổ hợp","ten_khac":["bien di to hop","to hop lai","kieu hinh moi","recombination","vang nhan","xanh tron"],"noi_dung":"Biến dị do sự tổ hợp lại các tính trạng (các gene) của bố mẹ, làm xuất hiện kiểu hình khác bố mẹ.","cong_thuc":null,"y":["Ví dụ: lai vàng, trơn × xanh, nhăn cho F2 xuất hiện <b>vàng, nhăn</b> và <b>xanh, trơn</b>.","Xuất hiện nhiều ở loài <b>sinh sản hữu tính</b>.","Là nguồn nguyên liệu cho chọn giống và tiến hóa."],"bang":null,"bien":null,"vd":{"de":"Bố mẹ đều có kiểu gene AaBb, đời con xuất hiện kiểu hình mới khác cả bố và mẹ. Đây là loại biến dị nào?","buoc":["Các gene A, a, B, b của bố mẹ tổ hợp lại theo cách khác nhau ở đời con.","Kiểu hình mới xuất hiện không phải do gene bị biến đổi."],"kq":"Đây là biến dị tổ hợp."},"nham":null,"lq":["s9-quy-luat-phan-li-doc-lap","s9-bien-di","s9-lai-hai-cap"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-nucleic-acid","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":20,"loai":"ch","ten":"Nucleic acid","ten_khac":["nucleic acid","axit nucleic","acid nucleic","dna va rna","dai phan tu"],"noi_dung":"Đại phân tử sinh học cấu tạo theo nguyên tắc đa phân, đơn phân là nucleotide; gồm DNA và RNA.","cong_thuc":null,"y":["Có hai loại: <b>DNA</b> (deoxyribonucleic acid) và <b>RNA</b> (ribonucleic acid).","Chức năng: lưu giữ, truyền đạt và biểu hiện thông tin di truyền."],"bang":[["Đặc điểm","DNA","RNA"],["Số mạch","2 mạch","1 mạch"],["Đường","deoxyribose","ribose"],["Loại base","A, T, G, C","A, U, G, C"]],"bien":null,"vd":null,"nham":null,"lq":["s9-dna","s9-rna","s9-nucleotide"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-dna","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":21,"loai":"ch","ten":"DNA","ten_khac":["dna","adn","deoxyribonucleic acid","chuoi xoan kep","xoan kep","watson crick"],"noi_dung":"Phân tử mang thông tin di truyền, gồm hai mạch polynucleotide xoắn song song quanh một trục.","cong_thuc":null,"y":["Mô hình <b>chuỗi xoắn kép</b> do Watson và Crick công bố năm 1953.","Mỗi chu kì xoắn gồm <b>10 cặp nucleotide</b>, dài 3,4 nm; đường kính 2 nm.","Hai mạch liên kết với nhau theo <b>nguyên tắc bổ sung</b>: A – T, G – C.","Tính đặc thù do số lượng, thành phần và trình tự sắp xếp nucleotide."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-nucleotide","s9-nguyen-tac-bo-sung","s9-gene","s9-tai-ban-dna","s9-nhiem-sac-the"],"hinh":"H-s9-dna","nguon":["KHTN Pocket"]},{"ma":"s9-tinh-toan-gene","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":22,"loai":"dl","ten":"Các công thức tính của gene","ten_khac":["chieu dai gene","khoi luong gene","lien ket hydrogen","so nucleotide","n = 2a + 2g","h = 2a + 3g","l = n/2","m = n x 300"],"noi_dung":"Từ tổng số nucleotide N và nguyên tắc bổ sung, tính được số nucleotide từng loại, chiều dài, khối lượng và số liên kết hydrogen của gene.","cong_thuc":"N = 2A + 2G ; L = (N : 2) × 0,34 nm ; M = N × 300 amu ; H = 2A + 3G","y":["Nguyên tắc bổ sung: <b>A = T, G = C</b>; A + G = N : 2 (hay %A + %G = 50%).","Mỗi cặp nucleotide dài <b>0,34 nm (3,4 Å)</b>: L = (N : 2) × 0,34 nm.","Khối lượng trung bình một nucleotide khoảng <b>300 amu</b>: M = N × 300.","A – T nối bằng <b>2</b>, G – C nối bằng <b>3</b> liên kết hydrogen: H = 2A + 3G."],"bang":null,"bien":[["N","tổng số nucleotide của gene","nucleotide"],["L","chiều dài gene","nm"],["M","khối lượng gene","amu"],["H","số liên kết hydrogen","liên kết"]],"vd":{"de":"Một gene có 3000 nucleotide, loại A chiếm 20%. Tính chiều dài, khối lượng và số liên kết hydrogen.","buoc":["A = 20% × 3000 = 600; G = 30% × 3000 = 900","L = 1500 × 0,34 = 510 nm; M = 3000 × 300 = 900 000 amu","H = 2 × 600 + 3 × 900"],"kq":"L = 510 nm; M = 900 000 amu; H = 3900"},"nham":["Quên chia đôi N khi tính chiều dài (N là số nucleotide của cả hai mạch).","Đảo hệ số: A – T có 2 liên kết, G – C có 3 liên kết hydrogen."],"lq":["s9-dna","s9-nguyen-tac-bo-sung","s9-gene"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-tinh-toan-tai-ban","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":23,"loai":"dl","ten":"Tính toán trong tái bản DNA","ten_khac":["so dna con","2 mu k","tai ban k lan","nucleotide moi truong cung cap","n x (2^k - 1)","ban bao toan"],"noi_dung":"Một DNA tái bản k lần liên tiếp tạo 2 mũ k DNA con; môi trường cung cấp số nucleotide đủ để tạo các mạch mới.","cong_thuc":"Số DNA con = 2^k ; Số nucleotide môi trường cung cấp = N × (2^k − 1)","y":["Một DNA tái bản k lần liên tiếp tạo <b>2^k</b> DNA con.","Theo nguyên tắc bán bảo toàn, luôn có <b>2</b> DNA con còn giữ một mạch cũ của DNA mẹ.","Số nucleotide môi trường cung cấp = <b>N × (2^k − 1)</b> (trừ đi DNA mẹ ban đầu)."],"bang":null,"bien":[["k","số lần tái bản liên tiếp","lần"],["N","số nucleotide của DNA mẹ","nucleotide"]],"vd":{"de":"Một gene có 3000 nucleotide tái bản liên tiếp 3 lần.","buoc":["Số DNA con = 2³ = 8","Nucleotide môi trường cung cấp = 3000 × (8 − 1)"],"kq":"8 DNA con; 21 000 nucleotide"},"nham":["Tính N × 2^k mà quên trừ số nucleotide của DNA mẹ ban đầu."],"lq":["s9-tai-ban-dna","s9-dna"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-nucleotide","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":24,"loai":"cq","ten":"Nucleotide","ten_khac":["nucleotide","nucleotit","nu","don phan","a t g c","nitrogenous base","baz nito"],"noi_dung":"Đơn phân cấu tạo nên nucleic acid, gồm gốc phosphate, đường 5 carbon và một nitrogenous base.","cong_thuc":null,"y":["DNA có 4 loại nucleotide: <b>A</b> (adenine), <b>T</b> (thymine), <b>G</b> (guanine), <b>C</b> (cytosine).","RNA có <b>U</b> (uracil) thay cho T.","Các nucleotide nối với nhau thành chuỗi polynucleotide."],"bang":null,"bien":null,"vd":null,"nham":["Viết nhầm T trong mạch RNA (RNA không có T, chỉ có U)."],"lq":["s9-dna","s9-rna","s9-nguyen-tac-bo-sung","s9-nucleic-acid"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-nguyen-tac-bo-sung","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":25,"loai":"ct","ten":"Nguyên tắc bổ sung","ten_khac":["nguyen tac bo sung","ntbs","bo sung","a lien ket t","g lien ket c","a-t g-c","complementary"],"noi_dung":"Nguyên tắc ghép cặp base: A liên kết với T (hoặc U), G liên kết với C.","cong_thuc":"A = T; G = C","y":["Trong DNA: <b>A – T, G – C</b>, nên số A = số T, số G = số C.","Khi phiên mã: A (gene) – U, T – A, G – C, C – G.","Biết trình tự một mạch suy ra được trình tự mạch kia.","Được áp dụng trong tái bản, phiên mã và dịch mã."],"bang":null,"bien":[["A, T, G, C","số nucleotide mỗi loại trong phân tử DNA","nucleotide"]],"vd":{"de":"Một đoạn mạch DNA có trình tự –A–T–G–C–T–A–G–. Viết trình tự mạch bổ sung.","buoc":["Ghép cặp: A với T, T với A, G với C, C với G."],"kq":"Mạch bổ sung: –T–A–C–G–A–T–C–"},"nham":["Ghép A với U khi viết mạch DNA bổ sung (U chỉ có trong RNA)."],"lq":["s9-dna","s9-tai-ban-dna","s9-phien-ma","s9-dich-ma"],"hinh":"H-s9-nguyen-tac-bo-sung","nguon":["KHTN Pocket"]},{"ma":"s9-gene","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":26,"loai":"kn","ten":"Gene","ten_khac":["gene","gen","doan dna","don vi di truyen","nhan to di truyen"],"noi_dung":"Một đoạn DNA mang thông tin quy định một sản phẩm nhất định (RNA hoặc chuỗi polypeptide).","cong_thuc":null,"y":["Mỗi phân tử DNA chứa <b>nhiều gene</b>.","Thông tin di truyền được mã hóa bằng <b>trình tự nucleotide</b> trong gene.","Gene nằm trên NST, chủ yếu trong nhân tế bào.","Gene chính là \"nhân tố di truyền\" mà Mendel đề cập."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-dna","s9-allele","s9-nhan-to-di-truyen","s9-phien-ma","s9-gene-den-tinh-trang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-rna","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":27,"loai":"ch","ten":"RNA","ten_khac":["rna","arn","ribonucleic acid","mot mach","uracil"],"noi_dung":"Nucleic acid một mạch, đơn phân là nucleotide A, U, G, C, được tổng hợp từ gene nhờ phiên mã.","cong_thuc":null,"y":["Kích thước nhỏ hơn DNA nhiều.","Có 3 loại chính: <b>mRNA</b>, <b>tRNA</b>, <b>rRNA</b>.","Tham gia vào quá trình tổng hợp protein."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-mrna","s9-trna","s9-rrna","s9-phien-ma","s9-nucleic-acid"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-mrna","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":28,"loai":"ch","ten":"mRNA","ten_khac":["mrna","marn","rna thong tin","messenger rna","ban sao cua gene"],"noi_dung":"RNA thông tin: bản sao của gene, mang thông tin quy định cấu trúc protein từ nhân tới ribosome.","cong_thuc":null,"y":["Được tổng hợp trong <b>phiên mã</b> theo nguyên tắc bổ sung với mạch khuôn của gene.","Trình tự nucleotide đọc theo từng <b>bộ ba (codon)</b>.","Là khuôn để ribosome tổng hợp chuỗi polypeptide."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-phien-ma","s9-dich-ma","s9-ma-di-truyen","s9-rna"],"hinh":"H-s9-mrna","nguon":["KHTN Pocket"]},{"ma":"s9-trna","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":29,"loai":"ch","ten":"tRNA","ten_khac":["trna","tarn","rna van chuyen","transfer rna","anticodon","bo ba doi ma"],"noi_dung":"RNA vận chuyển: mang amino acid tới ribosome trong quá trình dịch mã.","cong_thuc":null,"y":["Mỗi tRNA có <b>bộ ba đối mã (anticodon)</b> khớp bổ sung với codon trên mRNA.","Một đầu gắn với một amino acid tương ứng."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-dich-ma","s9-mrna","s9-rrna","s9-rna"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-rrna","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":30,"loai":"ch","ten":"rRNA","ten_khac":["rrna","rarn","rna ribosome","ribosomal rna","ribosome"],"noi_dung":"RNA ribosome: cùng với protein cấu tạo nên ribosome, nơi tổng hợp protein.","cong_thuc":null,"y":["Chiếm tỉ lệ lớn nhất trong các loại RNA của tế bào.","<b>Ribosome</b> là \"nhà máy\" lắp ráp amino acid thành chuỗi polypeptide."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-dich-ma","s9-trna","s9-mrna","s9-rna"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-ma-di-truyen","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":31,"loai":"kn","ten":"Mã di truyền","ten_khac":["ma di truyen","codon","bo ba","ma bo ba","aug","bo ba ket thuc","genetic code"],"noi_dung":"Trình tự nucleotide trên mRNA quy định trình tự amino acid; cứ 3 nucleotide liền nhau mã hóa 1 amino acid.","cong_thuc":null,"y":["Có <b>64 bộ ba</b>: 61 bộ ba mã hóa amino acid, 3 bộ ba kết thúc.","Bộ ba mở đầu: <b>AUG</b> (mã hóa methionine).","Bộ ba kết thúc: <b>UAA, UAG, UGA</b> (không mã hóa amino acid).","Được đọc liên tục theo từng bộ ba; hầu hết các loài dùng chung một bộ mã."],"bang":null,"bien":null,"vd":{"de":"Một đoạn mRNA có 300 nucleotide sẽ mã hóa cho một chuỗi polypeptide có tối đa bao nhiêu amino acid?","buoc":["Cứ 3 nucleotide trên mRNA (1 bộ ba) mã hóa 1 amino acid.","Số amino acid tối đa = 300 : 3."],"kq":"Tối đa 100 amino acid."},"nham":["Đếm cả bộ ba kết thúc khi tính số amino acid."],"lq":["s9-mrna","s9-dich-ma","s9-protein","s9-trna"],"hinh":"H-s9-ma-di-truyen","nguon":["KHTN Pocket"]},{"ma":"s9-tai-ban-dna","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":32,"loai":"ht","ten":"Tái bản DNA","ten_khac":["tai ban dna","nhan doi dna","tu nhan doi","sao chep dna","ban bao toan","replication","nhan doi adn","tai ban adn"],"noi_dung":"Quá trình tạo ra hai phân tử DNA con giống hệt phân tử DNA mẹ.","cong_thuc":"số DNA con = 2^k","y":["Hai mạch DNA tách nhau; <b>mỗi mạch làm khuôn</b> để tổng hợp mạch mới.","Theo <b>nguyên tắc bổ sung</b> (A – T, G – C) và <b>nguyên tắc bán bảo toàn</b>: mỗi DNA con có 1 mạch cũ, 1 mạch mới.","Diễn ra trước khi tế bào phân chia, nhờ đó thông tin di truyền truyền qua các thế hệ tế bào."],"bang":null,"bien":[["k","số lần tái bản","lần"]],"vd":{"de":"Một phân tử DNA tái bản liên tiếp 3 lần. Tạo ra bao nhiêu phân tử DNA con?","buoc":["Số DNA con = 2^k = 2^3"],"kq":"8 phân tử DNA"},"nham":null,"lq":["s9-dna","s9-nguyen-tac-bo-sung","s9-phien-ma","s9-nguyen-phan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-phien-ma","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":33,"loai":"ht","ten":"Phiên mã","ten_khac":["phien ma","tong hop rna","sao ma","transcription","gene thanh mrna","mach khuon"],"noi_dung":"Quá trình tổng hợp RNA dựa trên khuôn mẫu là một mạch của gene.","cong_thuc":null,"y":["Chỉ <b>một mạch</b> của gene (mạch khuôn) được dùng làm khuôn.","Nucleotide ghép theo nguyên tắc bổ sung: A – U, T – A, G – C, C – G.","Ở tế bào nhân thực diễn ra chủ yếu trong <b>nhân</b>; mRNA sau đó ra tế bào chất."],"bang":null,"bien":null,"vd":{"de":"Mạch khuôn của gene: –T–A–C–G–G–A–. Viết trình tự mRNA.","buoc":["T → A, A → U, C → G, G → C"],"kq":"mRNA: –A–U–G–C–C–U–"},"nham":["Nhầm với tái bản: phiên mã chỉ dùng một mạch và tạo RNA (có U), không tạo DNA."],"lq":["s9-mrna","s9-gene","s9-dich-ma","s9-tai-ban-dna"],"hinh":"H-s9-phien-ma","nguon":["KHTN Pocket"]},{"ma":"s9-dich-ma","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":34,"loai":"ht","ten":"Dịch mã","ten_khac":["dich ma","giai ma","tong hop protein","translation","ribosome","chuoi polypeptide"],"noi_dung":"Quá trình tổng hợp chuỗi polypeptide (protein) dựa trên trình tự codon của mRNA, diễn ra tại ribosome.","cong_thuc":null,"y":["Ribosome trượt trên mRNA, đọc từng bộ ba, bắt đầu từ bộ ba mở đầu <b>AUG</b>.","tRNA mang amino acid tới, anticodon khớp bổ sung với codon.","Các amino acid nối lại thành chuỗi; gặp bộ ba kết thúc thì dừng.","Diễn ra ở <b>tế bào chất</b>."],"bang":null,"bien":null,"vd":{"de":"Một đoạn mRNA có 90 nucleotide được dịch mã. Chuỗi polypeptide tạo thành có khoảng bao nhiêu amino acid?","buoc":["Cứ 3 nucleotide mã hóa 1 amino acid.","Số amino acid ≈ 90 : 3."],"kq":"Khoảng 30 amino acid."},"nham":null,"lq":["s9-mrna","s9-trna","s9-rrna","s9-ma-di-truyen","s9-protein"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-protein","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":35,"loai":"ch","ten":"Protein","ten_khac":["protein","protit","chat dam","amino acid","axit amin","chuoi polypeptide"],"noi_dung":"Đại phân tử gồm một hay nhiều chuỗi polypeptide, đơn phân là amino acid; biểu hiện trực tiếp thành tính trạng.","cong_thuc":null,"y":["Có khoảng <b>20 loại amino acid</b> tham gia cấu tạo protein.","Tính đặc thù do số lượng, thành phần và trình tự amino acid.","Chức năng: cấu trúc, xúc tác (enzyme), vận chuyển, bảo vệ (kháng thể), điều hòa (hormone)…"],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-dich-ma","s9-gene-den-tinh-trang","s9-ma-di-truyen"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-gene-den-tinh-trang","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":36,"loai":"kn","ten":"Từ gene đến tính trạng","ten_khac":["gene den tinh trang","gene mrna protein","moi quan he gene tinh trang","bieu hien gene","so do gene","gen den tinh trang"],"noi_dung":"Gene quy định tính trạng thông qua sơ đồ: Gene (DNA) → mRNA → Protein → Tính trạng.","cong_thuc":null,"y":["Trình tự nucleotide trong gene quy định trình tự nucleotide trong mRNA (<b>phiên mã</b>).","mRNA quy định trình tự amino acid trong protein (<b>dịch mã</b>).","Protein trực tiếp tham gia cấu trúc và hoạt động của tế bào → biểu hiện thành <b>tính trạng</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-gene","s9-phien-ma","s9-dich-ma","s9-protein","s9-tinh-trang"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-dot-bien-gene","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":37,"loai":"ht","ten":"Đột biến gene","ten_khac":["dot bien gene","dot bien gen","dbg","mat cap nucleotide","them cap","thay the cap","mutation"],"noi_dung":"Những biến đổi trong cấu trúc của gene, thường liên quan đến một cặp nucleotide.","cong_thuc":null,"y":["Các dạng: <b>mất</b>, <b>thêm</b>, <b>thay thế</b> một cặp nucleotide.","Nguyên nhân: tác nhân vật lí (tia phóng xạ, tia UV), hóa học, sai sót khi tái bản DNA.","Làm biến đổi mRNA và protein → có thể biến đổi tính trạng.","Đa số có hại, một số có lợi hoặc trung tính; là nguyên liệu cho chọn giống, tiến hóa."],"bang":null,"bien":null,"vd":{"de":"Một gene bị mất một cặp nucleotide ở giữa mạch. Vì sao đột biến này có thể làm thay đổi nhiều amino acid trong protein, dù chỉ mất một cặp nucleotide?","buoc":["Mất một cặp nucleotide làm các bộ ba từ vị trí đó trở về sau bị đọc lệch đi.","Các bộ ba mới mã hóa amino acid khác, nên nhiều amino acid phía sau bị thay đổi."],"kq":"Mất một cặp nucleotide làm thay đổi các bộ ba từ vị trí đột biến trở về sau, ảnh hưởng nhiều amino acid."},"nham":["Nghĩ mọi đột biến gene đều biểu hiện ngay: đột biến lặn ở thể dị hợp thường không biểu hiện."],"lq":["s9-gene","s9-bien-di","s9-dot-bien-cau-truc-nst","s9-benh-tat-di-truyen"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-tach-chiet-dna","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":38,"loai":"tn","ten":"Tách chiết DNA","ten_khac":["tach chiet dna","thuc hanh dna","chiet dna","con lanh","dna gan ga","dna chuoi","tach chiet adn"],"noi_dung":"Thí nghiệm thu DNA từ mẫu sinh vật (gan gà, chuối, dâu tây…) để quan sát bằng mắt thường.","cong_thuc":null,"y":["Nghiền mẫu, thêm <b>nước rửa bát</b> và <b>muối</b> để phá màng tế bào, màng nhân.","Lọc lấy dịch, rót nhẹ <b>cồn lạnh</b> theo thành ống nghiệm.","DNA kết tủa thành <b>sợi trắng đục</b> ở mặt phân cách giữa cồn và dịch chiết."],"bang":null,"bien":null,"vd":{"de":"Trong thí nghiệm tách chiết DNA từ chuối, sau khi nghiền và lọc, người ta đổ cồn lạnh vào dịch lọc thì thấy xuất hiện các sợi trắng nổi lên. Đó là gì?","buoc":["DNA hòa tan trong dịch lọc nhưng không tan trong cồn.","Khi gặp cồn lạnh, DNA kết tủa lại thành các sợi trắng nổi lên."],"kq":"Các sợi trắng đó chính là DNA được tách ra."},"nham":["Lắc mạnh ống nghiệm làm đứt vụn sợi DNA, khó quan sát."],"lq":["s9-dna","s9-nucleic-acid"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-nhiem-sac-the","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":39,"loai":"cq","ten":"Nhiễm sắc thể","ten_khac":["nhiem sac the","nst","chromosome","chromatid","cromatit","tam dong","histone"],"noi_dung":"Cấu trúc nằm trong nhân tế bào, gồm DNA và protein histone, mang gene và bắt màu khi nhuộm.","cong_thuc":null,"y":["Nhìn rõ nhất ở <b>kì giữa</b> của phân bào, khi NST co xoắn cực đại.","NST kép gồm <b>2 chromatid</b> chị em dính nhau ở <b>tâm động</b>.","Là cấu trúc mang gene, có khả năng tự nhân đôi, giúp truyền thông tin di truyền qua các thế hệ."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-dna","s9-nst-tuong-dong","s9-bo-nst-luong-boi","s9-nguyen-phan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-nst-tuong-dong","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":40,"loai":"kn","ten":"Cặp NST tương đồng","ten_khac":["nst tuong dong","cap nst tuong dong","tuong dong","homologous","cap nhiem sac the"],"noi_dung":"Cặp gồm hai NST giống nhau về hình thái, kích thước; một chiếc có nguồn gốc từ bố, một chiếc từ mẹ.","cong_thuc":null,"y":["Trong tế bào sinh dưỡng, NST tồn tại thành <b>từng cặp tương đồng</b>.","Các allele của một gene nằm ở vị trí tương ứng trên hai NST của cặp.","Cặp NST giới tính XY ở người không tương đồng hoàn toàn."],"bang":null,"bien":null,"vd":{"de":"Trong tế bào sinh dưỡng người, mỗi cặp NST gồm một chiếc từ bố, một chiếc từ mẹ, giống nhau về hình dạng, kích thước. Cặp NST này gọi là gì?","buoc":["Hai chiếc NST trong cặp giống nhau về hình thái và kích thước.","Một chiếc có nguồn gốc từ bố, một chiếc từ mẹ."],"kq":"Đây là cặp NST tương đồng."},"nham":null,"lq":["s9-nhiem-sac-the","s9-bo-nst-luong-boi","s9-allele","s9-giam-phan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-bo-nst-luong-boi","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":41,"loai":"kn","ten":"Bộ NST lưỡng bội","ten_khac":["bo nst luong boi","luong boi","2n","diploid","bo nhiem sac the","2n = 46"],"noi_dung":"Bộ NST chứa các cặp NST tương đồng, kí hiệu 2n, có trong tế bào sinh dưỡng và hợp tử.","cong_thuc":null,"y":["Mỗi loài có bộ NST <b>đặc trưng</b> về số lượng, hình dạng, cấu trúc.","Số lượng NST không phản ánh mức độ tiến hóa của loài.","Được duy trì ổn định nhờ nguyên phân, giảm phân và thụ tinh."],"bang":[["Loài","2n"],["Người","46"],["Tinh tinh","48"],["Ruồi giấm","8"],["Đậu Hà Lan","14"],["Ngô","20"],["Lúa","24"]],"bien":null,"vd":{"de":"Người có bộ NST lưỡng bội 2n = 46. Tế bào sinh dưỡng của người có bao nhiêu NST và được sắp xếp thế nào?","buoc":["Bộ NST lưỡng bội 2n = 46 gồm 23 cặp NST tương đồng.","Tế bào sinh dưỡng luôn mang đủ bộ NST lưỡng bội này."],"kq":"Tế bào sinh dưỡng có 46 NST, xếp thành 23 cặp tương đồng."},"nham":["Nghĩ loài có nhiều NST hơn thì tiến hóa hơn (tinh tinh 2n = 48 > người 2n = 46)."],"lq":["s9-bo-nst-don-boi","s9-nst-tuong-dong","s9-nhiem-sac-the","s9-thu-tinh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-bo-nst-don-boi","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":42,"loai":"kn","ten":"Bộ NST đơn bội","ten_khac":["bo nst don boi","don boi","n","haploid","nst giao tu","n = 23"],"noi_dung":"Bộ NST chỉ chứa một chiếc của mỗi cặp tương đồng, kí hiệu n, có trong giao tử.","cong_thuc":null,"y":["Số NST bằng <b>một nửa</b> bộ lưỡng bội: người n = 23.","Tạo ra nhờ <b>giảm phân</b>.","Khi thụ tinh, giao tử đực (n) + giao tử cái (n) → hợp tử (2n)."],"bang":null,"bien":null,"vd":{"de":"Ruồi giấm có bộ NST lưỡng bội 2n = 8. Giao tử của ruồi giấm có bộ NST đơn bội là bao nhiêu?","buoc":["Giao tử chỉ mang một chiếc của mỗi cặp NST tương đồng.","n = 2n : 2 = 8 : 2."],"kq":"n = 4 NST trong mỗi giao tử."},"nham":null,"lq":["s9-bo-nst-luong-boi","s9-giam-phan","s9-thu-tinh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-nst-gioi-tinh","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":43,"loai":"cq","ten":"NST giới tính","ten_khac":["nst gioi tinh","nhiem sac the gioi tinh","xx","xy","sex chromosome","nst x","nst y"],"noi_dung":"NST mang gene quy định giới tính (và một số tính trạng thường), thường có một cặp trong tế bào lưỡng bội.","cong_thuc":null,"y":["Ở người: nữ <b>XX</b>, nam <b>XY</b>.","Cặp XY khác nhau về hình dạng, kích thước (Y nhỏ hơn X).","Gene trên NST X quy định cả một số tính trạng khác, ví dụ bệnh máu khó đông, mù màu."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-nst-thuong","s9-xac-dinh-gioi-tinh","s9-benh-mau-kho-dong"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-nst-thuong","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":44,"loai":"cq","ten":"NST thường","ten_khac":["nst thuong","nhiem sac the thuong","autosome","nst khong gioi tinh","22 cap"],"noi_dung":"Các NST không phải NST giới tính, luôn tồn tại thành cặp tương đồng, giống nhau ở hai giới.","cong_thuc":null,"y":["Ở người có <b>22 cặp</b> NST thường và 1 cặp NST giới tính.","Mang gene quy định các tính trạng thường của cơ thể."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-nst-gioi-tinh","s9-nst-tuong-dong","s9-bo-nst-luong-boi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-nguyen-phan","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":45,"loai":"ht","ten":"Nguyên phân","ten_khac":["nguyen phan","phan bao nguyen nhiem","mitosis","ki dau","ki giua","ki sau","ki cuoi"],"noi_dung":"Hình thức phân bào tạo ra hai tế bào con có bộ NST giống hệt tế bào mẹ (2n → 2n).","cong_thuc":"số tế bào con = 2^k","y":["Trước phân bào (kì trung gian), mỗi NST <b>nhân đôi</b> thành NST kép.","<b>Kì đầu</b>: NST co xoắn; <b>kì giữa</b>: NST kép xếp <b>một hàng</b> ở mặt phẳng xích đạo.","<b>Kì sau</b>: hai chromatid tách nhau về hai cực; <b>kì cuối</b>: tạo hai tế bào con.","Ý nghĩa: giúp cơ thể lớn lên, thay thế tế bào già, tái sinh; là cơ sở của sinh sản vô tính."],"bang":null,"bien":[["k","số lần nguyên phân liên tiếp","lần"]],"vd":{"de":"Một tế bào nguyên phân liên tiếp 4 lần. Tính số tế bào con.","buoc":["Số tế bào con = 2^k = 2^4"],"kq":"16 tế bào con"},"nham":null,"lq":["s9-giam-phan","s9-nhiem-sac-the","s9-tai-ban-dna","s9-bo-nst-luong-boi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-giam-phan","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":46,"loai":"ht","ten":"Giảm phân","ten_khac":["giam phan","phan bao giam nhiem","meiosis","giam phan 1","giam phan 2","trao doi cheo"],"noi_dung":"Hình thức phân bào tạo giao tử: từ một tế bào 2n qua hai lần phân bào tạo bốn tế bào con n.","cong_thuc":null,"y":["Gồm <b>2 lần phân bào</b> (giảm phân I, II) nhưng NST chỉ nhân đôi <b>1 lần</b>.","Giảm phân I: NST kép tiếp hợp, có thể trao đổi chéo; kì giữa I xếp <b>hai hàng</b>; kì sau I cặp tương đồng phân li.","Ở động vật: 1 tế bào sinh tinh → 4 tinh trùng; 1 tế bào sinh trứng → 1 trứng + 3 thể cực.","Ý nghĩa: tạo giao tử đơn bội và nhiều loại giao tử khác nhau (biến dị tổ hợp)."],"bang":[["","Nguyên phân","Giảm phân"],["Tế bào","sinh dưỡng, sinh dục sơ khai","sinh dục chín"],["Số lần phân bào","1","2"],["Kết quả","2 tế bào 2n","4 tế bào n"]],"bien":null,"vd":{"de":"Một tế bào sinh dục chín (2n) giảm phân bình thường. Tính số tế bào con và số NST trong mỗi tế bào con tạo thành.","buoc":["Giảm phân qua 2 lần phân bào tạo 4 tế bào con.","Mỗi tế bào con có bộ NST đơn bội n, giảm một nửa so với tế bào mẹ."],"kq":"Tạo 4 tế bào con, mỗi tế bào có n NST."},"nham":["Nhầm kì giữa: nguyên phân xếp 1 hàng, giảm phân I xếp 2 hàng."],"lq":["s9-nguyen-phan","s9-bo-nst-don-boi","s9-thu-tinh","s9-quy-luat-phan-li"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-thu-tinh","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":47,"loai":"ht","ten":"Thụ tinh","ten_khac":["thu tinh","hop tu","ket hop giao tu","fertilization","n + n = 2n"],"noi_dung":"Sự kết hợp giữa một giao tử đực (n) và một giao tử cái (n) tạo thành hợp tử (2n).","cong_thuc":null,"y":["Khôi phục bộ NST <b>lưỡng bội</b> đặc trưng của loài.","Kết hợp ngẫu nhiên các giao tử khác nhau → tạo nhiều <b>biến dị tổ hợp</b>.","Nguyên phân + giảm phân + thụ tinh duy trì ổn định bộ NST qua các thế hệ."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-giam-phan","s9-bo-nst-luong-boi","s9-bo-nst-don-boi","s9-bien-di-to-hop"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-xac-dinh-gioi-tinh","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":48,"loai":"ht","ten":"Cơ chế xác định giới tính","ten_khac":["xac dinh gioi tinh","co che xac dinh gioi tinh","sinh con trai","sinh con gai","xx xy","ti le 1:1"],"noi_dung":"Giới tính được xác định nhờ sự phân li của cặp NST giới tính trong giảm phân và tổ hợp lại khi thụ tinh.","cong_thuc":null,"y":["Ở người: mẹ XX cho một loại trứng X; bố XY cho hai loại tinh trùng <b>X</b> và <b>Y</b> với tỉ lệ ngang nhau.","Trứng X + tinh trùng X → XX (gái); trứng X + tinh trùng Y → XY (trai).","Vì vậy tỉ lệ con trai : con gái xấp xỉ <b>1 : 1</b>.","Giới tính còn chịu ảnh hưởng của môi trường (nhiệt độ, hormone…) ở một số loài."],"bang":null,"bien":null,"vd":{"de":"Ở người, mẹ có cặp NST giới tính XX, bố có cặp NST giới tính XY. Vì sao tỉ lệ con trai và con gái sinh ra xấp xỉ 1:1?","buoc":["Mẹ chỉ tạo một loại trứng mang X; bố tạo hai loại tinh trùng mang X và mang Y với tỉ lệ ngang nhau.","Trứng thụ tinh với tinh trùng X tạo hợp tử XX là con gái; với tinh trùng Y tạo hợp tử XY là con trai."],"kq":"Tỉ lệ con trai và con gái xấp xỉ 1:1 do hai loại tinh trùng có số lượng ngang nhau."},"nham":["Cho rằng sinh con trai hay gái là do người mẹ: thực tế do loại tinh trùng của bố quyết định."],"lq":["s9-nst-gioi-tinh","s9-giam-phan","s9-thu-tinh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-di-truyen-lien-ket","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":49,"loai":"ct","ten":"Di truyền liên kết","ten_khac":["di truyen lien ket","lien ket gene","morgan","nhom gene lien ket","ruoi giam","linkage","lien ket gen"],"noi_dung":"Hiện tượng các gene nằm trên cùng một NST cùng phân li về giao tử và di truyền cùng nhau.","cong_thuc":"AB/ab → giao tử 1 AB : 1 ab (liên kết hoàn toàn)","y":["Do <b>Morgan</b> phát hiện qua thí nghiệm trên <b>ruồi giấm</b>.","Các gene trên một NST tạo thành <b>nhóm gene liên kết</b>; số nhóm liên kết bằng số NST đơn bội (n).","Hạn chế biến dị tổ hợp, đảm bảo sự di truyền bền vững từng nhóm tính trạng.","Ứng dụng trong chọn giống: chọn được những tính trạng tốt luôn đi kèm nhau."],"bang":null,"bien":[["AB/ab","A và B cùng nằm trên một NST, a và b trên NST tương đồng","–"]],"vd":{"de":"Hai gene A và B cùng nằm trên một NST (A liên kết với B, a liên kết với b), không phân li độc lập. Cơ thể AaBb giảm phân tạo giao tử nào?","buoc":["Gene liên kết cùng nằm trên một NST nên di truyền cùng nhau, không tổ hợp tự do.","A đi cùng B, a đi cùng b trong mỗi giao tử."],"kq":"2 loại giao tử AB và ab, tỉ lệ 1:1, thay vì 4 loại như phân li độc lập."},"nham":["Nhầm với phân li độc lập (gene trên các NST khác nhau)."],"lq":["s9-quy-luat-phan-li-doc-lap","s9-nhiem-sac-the","s9-bo-nst-don-boi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-dot-bien-cau-truc-nst","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":50,"loai":"ht","ten":"Đột biến cấu trúc NST","ten_khac":["dot bien cau truc nst","mat doan","lap doan","dao doan","chuyen doan","dot bien nst","dot bien cau truc nhiem sac the"],"noi_dung":"Những biến đổi trong cấu trúc của NST, làm thay đổi số lượng hoặc trật tự sắp xếp gene trên NST.","cong_thuc":null,"y":["Các dạng: <b>mất đoạn</b>, <b>lặp đoạn</b>, <b>đảo đoạn</b>, <b>chuyển đoạn</b>.","Nguyên nhân: tác nhân vật lí, hóa học hoặc rối loạn trong tế bào.","Thường có hại cho sinh vật; mất đoạn lớn có thể gây chết."],"bang":[["Dạng","Mô tả (NST ABCDEFG)"],["Mất đoạn","ABCFG (mất DE)"],["Lặp đoạn","ABCDEDEFG"],["Đảo đoạn","ABEDCFG"],["Chuyển đoạn","một đoạn chuyển sang NST khác"]],"bien":null,"vd":{"de":"Một đoạn NST bị đứt ra và gắn ngược trở lại đúng vị trí đó nhưng bị đảo chiều. Trật tự gene trên đoạn đó thay đổi thế nào? Đây là dạng đột biến gì?","buoc":["Đoạn NST bị đứt ra rồi gắn lại nhưng theo chiều ngược lại.","Trật tự các gene trên đoạn đó bị đảo ngược so với ban đầu."],"kq":"Đây là đột biến cấu trúc NST, dạng đảo đoạn."},"nham":null,"lq":["s9-dot-bien-so-luong-nst","s9-dot-bien-gene","s9-nhiem-sac-the"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-dot-bien-so-luong-nst","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":51,"loai":"ht","ten":"Đột biến số lượng NST","ten_khac":["dot bien so luong nst","lech boi","di boi","da boi","the ba","2n+1","2n-1","3n","dot bien so luong nhiem sac the"],"noi_dung":"Những biến đổi về số lượng NST, xảy ra ở một hay một số cặp (lệch bội) hoặc toàn bộ bộ NST (đa bội).","cong_thuc":null,"y":["<b>Lệch bội</b>: thêm hoặc mất NST ở một cặp, ví dụ 2n + 1, 2n − 1.","<b>Đa bội</b>: bộ NST tăng theo bội số của n (3n, 4n…).","Nguyên nhân: NST không phân li trong phân bào.","Cây đa bội thường có cơ quan sinh dưỡng to, sinh trưởng mạnh; ứng dụng tạo dưa hấu tam bội (3n) không hạt."],"bang":[["Thể","Số NST","Ví dụ ở người"],["Thể ba (2n + 1)","47","Hội chứng Down (3 NST số 21)"],["Thể một (2n − 1)","45","Hội chứng Turner (chỉ 1 NST X)"]],"bien":null,"vd":{"de":"Trong giảm phân, một cặp NST không phân li, tạo giao tử thừa một NST. Giao tử này kết hợp với giao tử bình thường sẽ tạo hợp tử có bộ NST thế nào?","buoc":["Một cặp NST không phân li tạo ra giao tử thừa 1 NST (n+1).","Giao tử (n+1) kết hợp giao tử bình thường (n) tạo hợp tử 2n+1."],"kq":"Hợp tử có bộ NST 2n+1, một dạng đột biến số lượng NST (thể ba)."},"nham":null,"lq":["s9-hoi-chung-down","s9-dot-bien-cau-truc-nst","s9-bo-nst-luong-boi","s9-benh-tat-di-truyen"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-tinh-so-nst-dot-bien","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":52,"loai":"dl","ten":"Số NST thể đột biến","ten_khac":["so nst the dot bien","the ba","the mot","tam boi","tu boi","2n+1","2n-1","3n","4n","the da boi","the lech boi"],"noi_dung":"Từ bộ NST lưỡng bội 2n của loài, tính được số NST trong tế bào sinh dưỡng của thể lệch bội và thể đa bội.","cong_thuc":"Thể ba: 2n + 1 ; Thể một: 2n − 1 ; Tam bội: 3n ; Tứ bội: 4n","y":["Lệch bội chỉ thay đổi ở <b>một cặp</b> NST: thêm 1 chiếc (thể ba) hoặc mất 1 chiếc (thể một).","Đa bội thay đổi <b>cả bộ</b>: số NST là bội số của n và lớn hơn 2n.","Muốn tính đa bội phải tìm n = 2n : 2 trước."],"bang":null,"bien":[["2n","bộ NST lưỡng bội của loài","NST"],["n","bộ NST đơn bội (n = 2n : 2)","NST"]],"vd":{"de":"Lúa có 2n = 24. Tính số NST trong tế bào sinh dưỡng của thể ba, thể một, thể tam bội và thể tứ bội.","buoc":["n = 24 : 2 = 12","Thể ba: 24 + 1 = 25; thể một: 24 − 1 = 23","Tam bội: 3 · 12 = 36; tứ bội: 4 · 12 = 48"],"kq":"25; 23; 36; 48 NST"},"nham":["Tính thể ba là 3n (nhầm lệch bội với đa bội).","Tính tam bội là 2n + 3."],"lq":["s9-dot-bien-so-luong-nst","s9-bo-nst-luong-boi","s9-bo-nst-don-boi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-benh-tat-di-truyen","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":53,"loai":"kn","ten":"Bệnh và tật di truyền","ten_khac":["benh di truyen","tat di truyen","benh tat di truyen","genetic disease","di tat bam sinh"],"noi_dung":"Bệnh, tật do đột biến gene hoặc đột biến NST gây ra, có thể truyền cho thế hệ sau.","cong_thuc":null,"y":["Bệnh do đột biến gene: <b>bạch tạng</b>, <b>máu khó đông</b>, mù màu…","Hội chứng do đột biến NST: <b>Down</b>, <b>Turner</b>…","Tật di truyền: khe hở môi – hàm, bàn tay mất ngón hoặc nhiều ngón…","Hạn chế: bảo vệ môi trường, không kết hôn gần, tư vấn di truyền và sàng lọc trước sinh."],"bang":null,"bien":null,"vd":{"de":"Một gia đình có người mắc bệnh do đột biến gene di truyền từ bố mẹ. Cần làm gì để giảm nguy cơ sinh con mắc bệnh tương tự?","buoc":["Bệnh và tật di truyền có thể truyền cho thế hệ sau qua gene hoặc NST.","Tư vấn di truyền giúp xác định nguy cơ và đưa ra lời khuyên phù hợp."],"kq":"Nên đi tư vấn di truyền trước khi sinh con tiếp theo."},"nham":null,"lq":["s9-benh-bach-tang","s9-hoi-chung-down","s9-benh-mau-kho-dong","s9-tu-van-di-truyen"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-hoi-chung-down","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":54,"loai":"kn","ten":"Hội chứng Down","ten_khac":["hoi chung down","down","dao","the ba nst 21","trisomy 21","3 nst 21"],"noi_dung":"Hội chứng do tế bào có 3 NST số 21 (tổng 47 NST), là một dạng đột biến số lượng NST.","cong_thuc":null,"y":["Biểu hiện: người thấp, cổ ngắn, mắt một mí, khe mắt xếch, lưỡi hay thè ra, thiểu năng trí tuệ.","Nguy cơ tăng khi <b>mẹ sinh con ở tuổi cao</b>, rõ rệt nhất là sau 35 tuổi.","Có thể phát hiện sớm nhờ sàng lọc, chẩn đoán trước sinh."],"bang":null,"bien":null,"vd":{"de":"Xét nghiệm tế bào của một trẻ cho thấy có 47 NST, trong đó NST số 21 có 3 chiếc thay vì 2. Đây là hội chứng gì?","buoc":["Bình thường mỗi người có 2 chiếc NST số 21.","Trẻ này thừa 1 chiếc, tổng cộng có 3 chiếc NST số 21."],"kq":"Đây là hội chứng Down, một dạng đột biến số lượng NST."},"nham":null,"lq":["s9-dot-bien-so-luong-nst","s9-benh-tat-di-truyen","s9-tu-van-di-truyen"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-benh-bach-tang","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":55,"loai":"kn","ten":"Bệnh bạch tạng","ten_khac":["bach tang","benh bach tang","albinism","da trang","gene lan nst thuong"],"noi_dung":"Bệnh do đột biến gene lặn trên NST thường, cơ thể không tạo được sắc tố melanin.","cong_thuc":null,"y":["Biểu hiện: da và tóc màu trắng, mắt nhạy cảm với ánh sáng.","Chỉ biểu hiện khi mang cặp gene <b>đồng hợp lặn (aa)</b>.","Bố mẹ bình thường nhưng đều mang gene (Aa) vẫn có thể sinh con bạch tạng (xác suất 1/4)."],"bang":null,"bien":null,"vd":{"de":"Bố và mẹ đều có màu da bình thường nhưng sinh ra con bị bạch tạng. Điều này được giải thích thế nào?","buoc":["Bệnh bạch tạng do gene lặn trên NST thường quy định.","Cả bố và mẹ đều mang gene lặn ở trạng thái dị hợp, không biểu hiện bệnh."],"kq":"Bố mẹ đều là thể dị hợp mang gene bệnh, con nhận cả hai allele lặn nên biểu hiện bạch tạng."},"nham":null,"lq":["s9-benh-tat-di-truyen","s9-dot-bien-gene","s9-di-hop","s9-tu-van-di-truyen"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-benh-mau-kho-dong","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":56,"loai":"kn","ten":"Bệnh máu khó đông","ten_khac":["mau kho dong","benh mau kho dong","hemophilia","gene lan tren x","di truyen lien ket gioi tinh"],"noi_dung":"Bệnh do gene lặn nằm trên NST X gây ra, máu chảy khó đông khi bị thương.","cong_thuc":null,"y":["Gặp chủ yếu ở <b>nam giới</b> vì nam chỉ có một NST X.","Nữ mang một gene bệnh (dị hợp) thường không biểu hiện nhưng có thể truyền cho con trai.","Bệnh mù màu cũng di truyền theo cách tương tự."],"bang":null,"bien":null,"vd":{"de":"Bệnh máu khó đông do gene lặn trên NST X quy định. Vì sao bệnh này gặp ở nam giới nhiều hơn nữ giới?","buoc":["Nam giới chỉ có 1 NST X, chỉ cần 1 allele lặn là đã biểu hiện bệnh.","Nữ giới có 2 NST X, cần cả hai allele đều lặn mới biểu hiện bệnh, khó xảy ra hơn."],"kq":"Nam dễ biểu hiện bệnh máu khó đông hơn nữ vì chỉ có một NST X."},"nham":null,"lq":["s9-nst-gioi-tinh","s9-benh-tat-di-truyen","s9-xac-dinh-gioi-tinh"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-tu-van-di-truyen","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":57,"loai":"ud","ten":"Tư vấn di truyền","ten_khac":["tu van di truyen","tu van hon nhan","ket hon can huyet","hon nhan gan","sang loc truoc sinh","pha he"],"noi_dung":"Hoạt động chẩn đoán, cung cấp thông tin và cho lời khuyên về khả năng mắc bệnh, tật di truyền ở đời con.","cong_thuc":null,"y":["Dựa vào <b>phả hệ</b> gia đình, xét nghiệm, chẩn đoán trước sinh.","Giúp các cặp vợ chồng quyết định kết hôn, sinh con phù hợp.","Luật Hôn nhân và gia đình cấm kết hôn giữa những người có quan hệ họ hàng trong phạm vi <b>ba đời</b>.","Kết hôn gần làm tăng nguy cơ con cái mắc bệnh do gene lặn."],"bang":null,"bien":null,"vd":{"de":"Một cặp vợ chồng có người thân mắc bệnh di truyền, muốn biết khả năng con của họ mắc bệnh trước khi sinh con. Họ nên làm gì?","buoc":["Đến cơ sở y tế chuyên khoa để được xét nghiệm di truyền.","Bác sĩ tư vấn cho biết nguy cơ và lời khuyên phù hợp."],"kq":"Tư vấn di truyền giúp họ biết nguy cơ và có quyết định phù hợp."},"nham":null,"lq":["s9-benh-tat-di-truyen","s9-benh-bach-tang","s9-hoi-chung-down"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-cong-nghe-di-truyen","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":58,"loai":"ud","ten":"Công nghệ di truyền","ten_khac":["cong nghe di truyen","ki thuat di truyen","ky thuat di truyen","chuyen gene","chuyen gen","dna tai to hop","cong nghe gene"],"noi_dung":"Ngành kĩ thuật thao tác trên vật chất di truyền (DNA, gene) để tạo ra sinh vật hay sản phẩm có lợi cho con người.","cong_thuc":null,"y":["<b>Kĩ thuật chuyển gene</b>: đưa gene mong muốn từ loài này sang loài khác.","<b>Y học</b>: sản xuất insulin, vaccine bằng vi khuẩn chuyển gene; chẩn đoán bệnh.","<b>Nông nghiệp</b>: tạo giống cây trồng, vật nuôi năng suất cao, kháng sâu bệnh.","<b>Pháp y</b>: phân tích DNA để xác định danh tính, quan hệ huyết thống.","Cần tuân thủ <b>đạo đức sinh học</b> và đảm bảo an toàn sinh học."],"bang":null,"bien":null,"vd":{"de":"Các nhà khoa học chuyển gene sản xuất insulin của người vào vi khuẩn để vi khuẩn sản xuất insulin dùng chữa bệnh. Đây là ứng dụng của lĩnh vực nào?","buoc":["Gene sản xuất insulin của người được chuyển sang tế bào vi khuẩn.","Đây là thao tác trực tiếp trên gene để tạo ra sản phẩm có lợi."],"kq":"Đây là một ứng dụng của công nghệ di truyền."},"nham":null,"lq":["s9-sinh-vat-bien-doi-gene","s9-gene","s9-dna"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-sinh-vat-bien-doi-gene","mon":"KHTN","khoi":"9","chu_de":"s9-di-truyen","thu_tu":59,"loai":"ch","ten":"Sinh vật biến đổi gene","ten_khac":["sinh vat bien doi gene","bien doi gen","gmo","bien doi gene","cay chuyen gene","thuc pham bien doi gen"],"noi_dung":"Sinh vật có hệ gene đã bị con người biến đổi, thường do được chuyển thêm gene từ loài khác.","cong_thuc":null,"y":["Ví dụ: vi khuẩn E. coli mang gene insulin người; cây trồng mang gene kháng sâu; lúa \"gạo vàng\" giàu tiền vitamin A.","Lợi ích: tăng năng suất, giảm dùng thuốc trừ sâu, tạo thuốc chữa bệnh.","Cần đánh giá an toàn với sức khỏe con người và môi trường trước khi sử dụng rộng rãi."],"bang":null,"bien":null,"vd":{"de":"Một giống bông được chuyển thêm gene kháng sâu từ vi khuẩn để tự sinh ra chất diệt sâu hại. Giống bông này được gọi là gì?","buoc":["Cây bông vốn không có sẵn gene kháng sâu này.","Hệ gene của nó đã bị con người biến đổi bằng cách thêm gene lạ."],"kq":"Đây là sinh vật biến đổi gene."},"nham":null,"lq":["s9-cong-nghe-di-truyen","s9-gene","s9-chon-loc-nhan-tao"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-tien-hoa","mon":"KHTN","khoi":"9","chu_de":"s9-tien-hoa","thu_tu":1,"loai":"kn","ten":"Tiến hóa","ten_khac":["tien hoa","evolution","tien hoa sinh hoc","thay doi qua the he","nguon goc cac loai"],"noi_dung":"Sự thay đổi các đặc điểm di truyền của quần thể sinh vật qua các thế hệ.","cong_thuc":null,"y":["Kết quả: sinh vật ngày càng <b>thích nghi</b> với môi trường, hình thành <b>loài mới</b>.","Giải thích sự <b>đa dạng</b> và nguồn gốc chung của sinh giới.","Đơn vị tiến hóa là <b>quần thể</b>, không phải từng cá thể."],"bang":null,"bien":null,"vd":null,"nham":["Nghĩ cá thể tiến hóa trong đời sống của nó: tiến hóa xảy ra ở quần thể qua nhiều thế hệ."],"lq":["s9-chon-loc-tu-nhien","s9-co-che-tien-hoa","s9-darwin","s9-phat-sinh-su-song"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-chon-loc-nhan-tao","mon":"KHTN","khoi":"9","chu_de":"s9-tien-hoa","thu_tu":2,"loai":"ht","ten":"Chọn lọc nhân tạo","ten_khac":["chon loc nhan tao","artificial selection","chon giong","giu bien di co loi cho nguoi","giong cai"],"noi_dung":"Quá trình con người giữ lại những biến dị có lợi cho mình và loại bỏ biến dị không mong muốn ở vật nuôi, cây trồng.","cong_thuc":null,"y":["Tạo ra nhiều <b>giống</b> vật nuôi, cây trồng khác nhau từ một dạng tổ tiên hoang dại.","Ví dụ: từ cải dại tạo ra bắp cải, súp lơ, su hào…; từ chó sói tạo nhiều giống chó.","Mỗi giống thích nghi với <b>nhu cầu của con người</b>, không nhất thiết có lợi cho chính sinh vật."],"bang":null,"bien":null,"vd":{"de":"Người chăn nuôi chỉ giữ lại và cho sinh sản những con gà mái đẻ nhiều trứng nhất qua nhiều thế hệ. Đây là quá trình gì?","buoc":["Người chăn nuôi chọn giữ lại những con gà đẻ nhiều trứng nhất.","Con người chủ động giữ lại biến dị có lợi theo nhu cầu của mình."],"kq":"Đây là chọn lọc nhân tạo, tạo ra giống gà đẻ trứng ngày càng nhiều."},"nham":null,"lq":["s9-chon-loc-tu-nhien","s9-darwin","s9-bien-di"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-chon-loc-tu-nhien","mon":"KHTN","khoi":"9","chu_de":"s9-tien-hoa","thu_tu":3,"loai":"ht","ten":"Chọn lọc tự nhiên","ten_khac":["chon loc tu nhien","cltn","natural selection","dau tranh sinh ton","thich nghi","song sot"],"noi_dung":"Quá trình giữ lại những cá thể mang biến dị có lợi, đào thải cá thể mang biến dị có hại trong điều kiện sống.","cong_thuc":null,"y":["Cá thể thích nghi hơn <b>sống sót và sinh sản</b> nhiều hơn, truyền đặc điểm cho đời sau.","Kết quả: hình thành các <b>đặc điểm thích nghi</b> và loài mới.","Ví dụ: vi khuẩn kháng thuốc kháng sinh; ở vùng công nghiệp thân cây ám bụi than, bướm màu sẫm khó bị chim phát hiện nên tăng dần."],"bang":[["","Chọn lọc nhân tạo","Chọn lọc tự nhiên"],["Tác nhân","con người","điều kiện sống"],["Kết quả","giống mới","đặc điểm thích nghi, loài mới"]],"bien":null,"vd":{"de":"Ở vùng công nghiệp ô nhiễm khói bụi, bướm đêm màu đen ngày càng chiếm số đông hơn bướm đêm màu trắng vốn phổ biến trước đó. Giải thích theo chọn lọc tự nhiên.","buoc":["Nền cây bị bồ hóng phủ đen, bướm đen ngụy trang tốt hơn, ít bị chim ăn hơn bướm trắng.","Bướm đen sống sót và sinh sản nhiều hơn qua các thế hệ."],"kq":"Chọn lọc tự nhiên làm tỉ lệ bướm đen tăng dần trong quần thể."},"nham":null,"lq":["s9-chon-loc-nhan-tao","s9-darwin","s9-co-che-tien-hoa","s9-tien-hoa"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-darwin","mon":"KHTN","khoi":"9","chu_de":"s9-tien-hoa","thu_tu":4,"loai":"kn","ten":"Darwin","ten_khac":["darwin","dac uyn","charles darwin","hoc thuyet darwin","nguon goc cac loai","beagle"],"noi_dung":"Charles Darwin (1809–1882), nhà tự nhiên học người Anh, đề xuất học thuyết tiến hóa bằng chọn lọc tự nhiên.","cong_thuc":null,"y":["Tích lũy quan sát trong chuyến đi vòng quanh thế giới trên tàu <b>Beagle</b>.","Công bố cuốn <b>\"Nguồn gốc các loài\"</b> năm 1859.","Cho rằng các loài có chung nguồn gốc; <b>biến dị cá thể</b> và <b>chọn lọc tự nhiên</b> tạo ra loài mới.","Hạn chế: chưa giải thích được nguồn gốc biến dị và cơ chế di truyền."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-chon-loc-tu-nhien","s9-chon-loc-nhan-tao","s9-co-che-tien-hoa","s9-mendel"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-co-che-tien-hoa","mon":"KHTN","khoi":"9","chu_de":"s9-tien-hoa","thu_tu":5,"loai":"ht","ten":"Cơ chế tiến hóa","ten_khac":["co che tien hoa","nhan to tien hoa","hinh thanh loai moi","thuyet tien hoa hien dai","nguyen lieu tien hoa","lamarck","lamac"],"noi_dung":"Cách thức sinh vật biến đổi qua các thế hệ để thích nghi và hình thành loài mới.","cong_thuc":null,"y":["Theo Lamarck: sinh vật biến đổi do ngoại cảnh và do sử dụng hay không sử dụng cơ quan; nay không được chấp nhận vì các biến đổi đó không di truyền.","Theo Darwin: biến dị cá thể + <b>chọn lọc tự nhiên</b> tích lũy biến dị có lợi → loài mới.","Quan niệm hiện đại: <b>đột biến</b> và <b>giao phối</b> (biến dị tổ hợp) tạo nguồn nguyên liệu.","Chọn lọc tự nhiên và các nhân tố khác làm thay đổi thành phần kiểu gene của quần thể.","Sự cách li giữa các quần thể góp phần hình thành loài mới."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-chon-loc-tu-nhien","s9-dot-bien-gene","s9-bien-di-to-hop","s9-tien-hoa"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-phat-sinh-su-song","mon":"KHTN","khoi":"9","chu_de":"s9-tien-hoa","thu_tu":6,"loai":"ht","ten":"Sự phát sinh sự sống","ten_khac":["phat sinh su song","nguon goc su song","tien hoa hoa hoc","tien hoa tien sinh hoc","te bao nguyen thuy","cay su song"],"noi_dung":"Quá trình sự sống hình thành từ chất vô cơ trên Trái Đất nguyên thủy qua các giai đoạn tiến hóa.","cong_thuc":null,"y":["<b>Tiến hóa hóa học</b>: từ chất vô cơ hình thành các chất hữu cơ đơn giản rồi phức tạp.","<b>Tiến hóa tiền sinh học</b>: hình thành tế bào nguyên thủy.","<b>Tiến hóa sinh học</b>: từ tế bào nguyên thủy tạo ra sinh giới đa dạng ngày nay.","Quan hệ họ hàng giữa các loài được biểu diễn bằng <b>cây sự sống</b>."],"bang":null,"bien":null,"vd":null,"nham":null,"lq":["s9-tien-hoa","s9-loai-nguoi","s9-nucleic-acid"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"s9-loai-nguoi","mon":"KHTN","khoi":"9","chu_de":"s9-tien-hoa","thu_tu":7,"loai":"ht","ten":"Sự phát sinh loài người","ten_khac":["loai nguoi","nguon goc loai nguoi","homo sapiens","nguoi hien dai","vuon nguoi","nguoi co"],"noi_dung":"Quá trình tiến hóa từ tổ tiên chung với vượn người đến người hiện đại Homo sapiens.","cong_thuc":null,"y":["Người và vượn người ngày nay (tinh tinh, gorilla…) có <b>chung tổ tiên</b>, không phải người tiến hóa từ tinh tinh.","Hóa thạch cho thấy nhiều dạng trung gian; các loài người thuộc chi <b>Homo</b>, ngày nay chỉ còn <b>người hiện đại</b> (Homo sapiens).","Đặc điểm nổi bật: đi thẳng bằng hai chân, bộ não phát triển, biết chế tạo công cụ, có tiếng nói."],"bang":null,"bien":null,"vd":null,"nham":["Nói \"người tiến hóa từ khỉ\": thực tế người và vượn người là hai nhánh từ một tổ tiên chung."],"lq":["s9-phat-sinh-su-song","s9-tien-hoa","s9-darwin"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-ss-khoi-luong-trong-luong","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":19,"loai":"ss","ten":"So sánh khối lượng và trọng lượng","ten_khac":["so sanh khoi luong trong luong","khoi luong va trong luong","kg va n","can nang","trong luong khac khoi luong"],"noi_dung":"Khối lượng là số đo lượng chất của vật; trọng lượng là độ lớn lực hút của Trái Đất lên vật.","cong_thuc":null,"y":["Vật có khối lượng 100 g thì có trọng lượng khoảng 1 N.","Trong đời sống, \"cân nặng\" thực ra là khối lượng."],"bang":[["","Khối lượng","Trọng lượng"],["Là gì","Số đo lượng chất của vật","Độ lớn lực hút của Trái Đất tác dụng lên vật"],["Đơn vị","kilôgam (kg)","newton (N)"],["Dụng cụ đo","Cân","Lực kế"],["Mang vật lên Mặt Trăng","Không đổi","Giảm (khoảng 6 lần)"]],"bien":null,"vd":null,"nham":null,"lq":["l6-khoi-luong","l6-trong-luong","l6-luc-hap-dan"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-ss-luc-tiep-xuc","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":20,"loai":"ss","ten":"So sánh lực tiếp xúc và lực không tiếp xúc","ten_khac":["so sanh luc tiep xuc","luc tiep xuc va khong tiep xuc","luc khong tiep xuc"],"noi_dung":"Lực tiếp xúc xuất hiện khi hai vật chạm nhau; lực không tiếp xúc xuất hiện khi hai vật không chạm nhau.","cong_thuc":null,"y":["Lực hấp dẫn và lực từ là những lực không tiếp xúc."],"bang":[["","Lực tiếp xúc","Lực không tiếp xúc"],["Khi nào xuất hiện","Vật gây ra lực tiếp xúc với vật chịu lực","Vật gây ra lực không tiếp xúc với vật chịu lực"],["Ví dụ","Tay đẩy xe, chân đá quả bóng, lực ma sát","Lực hút của Trái Đất, nam châm hút đinh sắt từ xa"]],"bien":null,"vd":null,"nham":null,"lq":["l6-luc-tiep-xuc","l6-luc-khong-tiep-xuc","l6-luc"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l6-ss-ma-sat","mon":"KHTN","khoi":"6","chu_de":"l6-luc","thu_tu":21,"loai":"ss","ten":"So sánh ma sát trượt và ma sát nghỉ","ten_khac":["so sanh ma sat","ma sat truot va ma sat nghi","luc ma sat truot","luc ma sat nghi"],"noi_dung":"Ma sát trượt xuất hiện khi vật trượt trên bề mặt vật khác; ma sát nghỉ giữ cho vật đứng yên khi bị lực tác dụng.","cong_thuc":null,"y":["Lực ma sát có thể có hại (làm mòn, cản trở) hoặc có lợi (giúp đi lại, cầm nắm, phanh xe)."],"bang":[["","Ma sát trượt","Ma sát nghỉ"],["Xuất hiện khi","Vật trượt trên bề mặt vật khác","Vật chịu lực tác dụng nhưng vẫn đứng yên trên bề mặt vật khác"],["Tác dụng","Cản trở chuyển động trượt","Giữ vật không bị trượt"],["Ví dụ","Xe phanh gấp, bánh xe trượt trên đường","Đẩy tủ nặng mà tủ chưa dịch chuyển; hàng nằm yên trên băng chuyền"]],"bien":null,"vd":null,"nham":null,"lq":["l6-luc-ma-sat","l6-ma-sat-truot","l6-ma-sat-nghi"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-ss-phan-xa-guong-khuech-tan","mon":"KHTN","khoi":"7","chu_de":"l7-anh-sang","thu_tu":18,"loai":"ss","ten":"So sánh phản xạ gương và phản xạ khuếch tán","ten_khac":["so sanh phan xa guong","phan xa khuech tan","phan xa guong va phan xa khuech tan"],"noi_dung":"Phản xạ gương xảy ra trên bề mặt nhẵn bóng; phản xạ khuếch tán xảy ra trên bề mặt gồ ghề.","cong_thuc":null,"y":["Cả hai đều tuân theo định luật phản xạ ánh sáng tại từng điểm.","Nhờ phản xạ khuếch tán, ta nhìn thấy vật từ nhiều phía."],"bang":[["","Phản xạ gương","Phản xạ khuếch tán"],["Bề mặt","Nhẵn, bóng","Gồ ghề, không nhẵn"],["Chùm tới song song","Chùm phản xạ cũng song song","Tia phản xạ hắt ra theo nhiều hướng"],["Ví dụ","Gương phẳng, mặt nước lặng","Tờ giấy, bức tường, mặt đường"]],"bien":null,"vd":null,"nham":null,"lq":["l7-phan-xa-anh-sang","l7-phan-xa-khuech-tan","l7-dinh-luat-phan-xa"],"hinh":null,"nguon":["KHTN Pocket"]},{"ma":"l7-ss-do-cao-do-to","mon":"KHTN","khoi":"7","chu_de":"l7-am-thanh","thu_tu":19,"loai":"ss","ten":"So sánh độ cao và độ to của âm","ten_khac":["so sanh do cao do to","do cao va do to","am cao am to","tan so bien do"],"noi_dung":"Độ cao của âm phụ thuộc tần số; độ to của âm phụ thuộc biên độ dao động.","cong_thuc":null,"y":["Hai hình đầu: cùng biên độ, hình thứ hai tần số lớn hơn nên âm cao hơn. Hình thứ ba: biên độ lớn hơn nên âm to hơn."],"bang":[["","Độ cao","Độ to"],["Phụ thuộc","Tần số dao động","Biên độ dao động"],["Quy luật","Tần số càng lớn, âm càng cao (bổng)","Biên độ càng lớn, âm càng to"],["Trên đồ thị dao động","Càng nhiều da